// The download archive keeps one immutable object per download plus small capped
// indexes, so any single lookup is a direct read instead of scanning everything.
const DL_ARCHIVE = {
  RECORD_PREFIX: "logs/downloads/",
  DEDUPE_PREFIX: "logs/download-dedupe/",
  USER_INDEX_PREFIX: "logs/user-downloads/",
  PRODUCT_INDEX_PREFIX: "logs/product-downloaders/",
  RECENT: "logs/download-recent.json",
  USERS: "logs/download-users.json",
  ID_PREFIX: "logs/download-id/",
  INDEX_LIMIT: 200,
  RECENT_LIMIT: 300,
};
const DL_RECORD_ID_PATTERN = /^dl_[a-z0-9]{6,32}$/;

function getSiteLogBotToken(env) {
  return env.SITE_LOG_BOT_TOKEN || env.DISCORD_BOT_TOKEN || "";
}

// Storage internals are never named in visitor-facing text: everything is "the server".
function publicErrorMessage(error) {
  return String(error?.message || error || "").replace(/\bR2\b/g, "server").slice(0, 400);
}

const siteErrorDedupe = new Map();
const siteErrorRate = new Map();
// Even the same failure repeats across isolates, so alerts are also deduped in R2.
const ERROR_ALERT_DEDUPE_KEY = "system/error_alert_dedupe.json";
const ERROR_ALERT_DEDUPE_WINDOW_MS = 5 * 60 * 1000;
// A dropped request or a cancelled image is also what a phone in a lift reports,
// so those client-side conditions are collapsed to one alert per hour.
const ERROR_ALERT_DEDUPE_WINDOWS = {
  api_network_error: 60 * 60 * 1000,
  asset_load_error: 60 * 60 * 1000,
};

function cleanErrorField(value, max = 400) {
  return String(value == null ? "" : value)
    .replace(/https?:\/\/[^\s?]+\?[^\s)]+/gi, "[url]")
    .replace(/\b(token|api[_-]?key|secret|authorization|cookie)=?[^\s&;,]*/gi, "$1=[redacted]")
    .replace(/[A-Za-z0-9_-]{48,}(?:\.[A-Za-z0-9_-]{20,})?/g, "[redacted]")
    .replace(/[\r\n\t]+/g, " ")
    .slice(0, max);
}

async function sendSiteErrorToDiscord(env, request, event) {
  const now = Date.now();
  const host = new URL(request.url).hostname.toLowerCase();
  if (host !== "zyrexediting.xyz" && host !== "dl.zyrexediting.xyz") return false;

  const details = {
    source: cleanErrorField(event.source || "site", 40),
    type: cleanErrorField(event.type || "error", 60),
    page: cleanErrorField(event.page || "", 160).split("?")[0],
    request_path: cleanErrorField(event.request_path || "", 180).split("?")[0],
    method: cleanErrorField(event.method || "", 10),
    status: Math.max(0, Math.min(599, Number(event.status) || 0)),
    code: cleanErrorField(event.code || "", 80),
    // Pinpointing the script line is what turns a stack overflow into a fix.
    line: Math.max(0, Number(event.line) || 0),
    column: Math.max(0, Number(event.column) || 0),
    title: cleanErrorField(event.title || "", 220),
    subsystem: cleanErrorField(event.subsystem || "", 80),
    message: cleanErrorField(event.message || "Unknown site error", 360),
  };
  const fingerprintText = [host, details.source, details.type, details.page, details.request_path, details.status, details.code, details.message].join("|");
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(fingerprintText));
  const fingerprint = Array.from(new Uint8Array(digest).slice(0, 12), b => b.toString(16).padStart(2, "0")).join("");
  const dedupeWindowMs = ERROR_ALERT_DEDUPE_WINDOWS[details.type] || ERROR_ALERT_DEDUPE_WINDOW_MS;
  const recent = siteErrorDedupe.get(fingerprint);
  if (recent && now - recent.at < dedupeWindowMs) {
    recent.count++;
    return true;
  }
  siteErrorDedupe.set(fingerprint, { at: now, count: 0 });
  for (const [key, value] of siteErrorDedupe) if (now - value.at > Math.max(10 * 60 * 1000, dedupeWindowMs)) siteErrorDedupe.delete(key);

  // The map above only covers one isolate, and the site is served from many, so
  // the same failure used to alert once per isolate. This durable record is what
  // actually collapses duplicates into a single alert.
  if (env?.STORAGE) {
    try {
      const stored = await r2GetJSON(env, ERROR_ALERT_DEDUPE_KEY, {});
      const seen = stored && typeof stored === "object" && !Array.isArray(stored) ? stored : {};
      const previous = Number(seen[fingerprint]) || 0;
      if (now - previous < dedupeWindowMs) return true;
      seen[fingerprint] = now;
      const kept = Object.entries(seen).sort((a, b) => Number(b[1]) - Number(a[1])).slice(0, 80);
      await r2PutJSON(env, ERROR_ALERT_DEDUPE_KEY, Object.fromEntries(kept));
    } catch (_) {}
  }

  // Use an ephemeral one-way hash for throttling; never forward the IP to logs.
  const edgeIp = String(request.headers.get("CF-Connecting-IP") || "unknown");
  const ipDigest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(edgeIp));
  const rateKey = Array.from(new Uint8Array(ipDigest).slice(0, 10), b => b.toString(16).padStart(2, "0")).join("");
  const rate = siteErrorRate.get(rateKey);
  if (rate && now - rate.at < 60 * 1000 && rate.count >= 20) return true;
  if (rate && now - rate.at < 60 * 1000) rate.count++;
  else siteErrorRate.set(rateKey, { at: now, count: 1 });
  if (siteErrorRate.size > 2000) {
    for (const [key, value] of siteErrorRate) if (now - value.at > 10 * 60 * 1000) siteErrorRate.delete(key);
  }

  let userId = /^\d{15,22}$/.test(String(event.user_id || "")) ? String(event.user_id) : "";
  try { userId = parseSession(request.headers.get("Cookie"), request)?.userId || userId; } catch (_) {}
  const reportTitle = details.title || `${details.type}: ${details.request_path || details.page || "/"}`.slice(0, 220);
  const reportMessage = [
    `Host: ${host}`,
    `Page: ${details.page || "/"}`,
    details.request_path ? `Request: ${details.method || "GET"} ${details.request_path}` : "",
    details.status ? `HTTP: ${details.status}` : "",
    details.code ? `Code: ${details.code}` : "",
    details.line ? `Line: ${details.line}${details.column ? ":" + details.column : ""}` : "",
    `Message: ${details.message}`,
    `Fingerprint: ${fingerprint}`,
  ].filter(Boolean).join("\n").slice(0, 1500);

  try {
    await recordTelemetryEvent(env, {
      subsystem: host === "dl.zyrexediting.xyz" ? "storage" : "api_gateway",
      title: reportTitle,
      message: reportMessage,
      severity: details.status >= 500 ? "outage" : "degraded",
      count: 1,
      user: userId ? `Discord user ${userId}` : "Website visitor",
      source: details.source,
      type: details.type,
      status: details.status,
    });
  } catch (_) {}

  try {
    const logBotToken = getSiteLogBotToken(env);
    if (!logBotToken) throw new Error("SITE_LOG_BOT_TOKEN is not configured");
    const response = await fetch(`${DISCORD_API}/channels/${SITE_LOG_CHANNEL_ID}/messages`, {
      method: "POST",
      headers: {
        Authorization: `Bot ${logBotToken}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        content: `<@${SITE_ERROR_ALERT_USER_ID}> Site error detected`,
        allowed_mentions: { parse: [], users: [SITE_ERROR_ALERT_USER_ID] },
        embeds: [{
          title: reportTitle,
          description: reportMessage,
          color: details.status >= 500 ? 0xef4444 : 0xf59e0b,
          timestamp: new Date(now).toISOString(),
          footer: { text: `Zyrex live site monitor • ${host}` },
          fields: [
            { name: "Severity", value: details.status >= 500 ? "Outage" : "Error", inline: true },
            ...(details.subsystem ? [{ name: "Subsystem", value: details.subsystem, inline: true }] : []),
            ...(userId ? [{ name: "Discord user", value: `<@${userId}>`, inline: true }] : []),
          ],
        }],
      }),
      signal: AbortSignal.timeout(5000),
    });
    if (!response.ok) {
      console.error("Discord site-error forwarding failed:", response.status, (await response.text()).slice(0, 300));
      return false;
    }
    return true;
  } catch (error) {
    console.error("Discord site-error forwarding failed:", error?.message || String(error));
    return false;
  }
}

async function sendVpsSiteLogToDiscord(env, event) {
  const token = getSiteLogBotToken(env);
  if (!token) throw new Error("SITE_LOG_BOT_TOKEN is not configured");
  const kind = cleanErrorField(event.kind || "info", 30);
  const isError = kind === "error" || kind === "incident";
  const userId = /^\d{15,22}$/.test(String(event.user_id || "")) ? String(event.user_id) : "";
  const title = cleanErrorField(event.title || (isError ? "VPS service error" : "VPS site event"), 240);
  const description = cleanErrorField(event.message || "No details", 3500);
  const fields = [];
  if (event.subsystem) fields.push({ name: "Subsystem", value: cleanErrorField(event.subsystem, 100), inline: true });
  if (userId) fields.push({ name: "User", value: `<@${userId}> (${cleanErrorField(event.user_name || "", 100)})`, inline: true });
  if (event.ip) fields.push({ name: "IP", value: `||\`${cleanErrorField(event.ip, 80)}\`||`, inline: true });
  if (event.country) fields.push({ name: "Country", value: cleanErrorField(event.country, 80), inline: true });
  const avatar = String(event.user_avatar || "");
  const embed = {
    title,
    description,
    color: isError ? 0xef4444 : kind === "download" ? 0x34d399 : 0x3b82f6,
    timestamp: new Date().toISOString(),
    fields,
    footer: { text: "Zyrex VPS → live site telemetry" },
  };
  if (/^https:\/\/(?:cdn\.discordapp\.com|media\.discordapp\.net|zyrexediting\.xyz)\//i.test(avatar)) {
    embed.author = { name: cleanErrorField(event.user_name || "Website member", 240), icon_url: avatar };
  }
  const notify = isError && String(event.notify_admin || "true").toLowerCase() !== "false";
  const response = await fetch(`${DISCORD_API}/channels/${SITE_LOG_CHANNEL_ID}/messages`, {
    method: "POST",
    headers: { Authorization: `Bot ${token}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      ...(notify ? { content: `<@${SITE_ERROR_ALERT_USER_ID}> VPS site error detected` } : {}),
      allowed_mentions: notify ? { parse: [], users: [SITE_ERROR_ALERT_USER_ID] } : { parse: [] },
      embeds: [embed],
    }),
    signal: AbortSignal.timeout(8000),
  });
  if (!response.ok) throw new Error(`Discord log send failed (${response.status}): ${(await response.text()).slice(0, 250)}`);
}

// ── Logger bot: verified-role and download-access audits ──────────────────────
// Every access decision (who verified, who unlocked downloads, who was refused and
// why) is written by the logger bot, so the answer to "why could this member not
// download?" lives in Discord next to the download archive. A subsystem posts into
// its own room when one is configured and otherwise falls back to the site log
// channel, so a missing channel permission can never swallow the record.
const SECURITY_LOG_COLORS = { info: 0x3b82f6, success: 0x22c55e, warn: 0xf59e0b, alert: 0xef4444 };
const SECURITY_SUBSYSTEMS = {
  verification: { label: "Verified role", channelVars: ["VERIFY_EVENT_CHANNEL_ID"] },
  access: { label: "Download access", channelVars: ["ACCESS_EVENT_CHANNEL_ID"] },
};

function securityLogChannels(env, subsystem) {
  const config = SECURITY_SUBSYSTEMS[subsystem] || SECURITY_SUBSYSTEMS.access;
  const ids = [...config.channelVars, "SECURITY_LOG_CHANNEL_ID"]
    .map(name => String((env && env[name]) || "").trim())
    .concat([SITE_LOG_CHANNEL_ID]);
  return ids.filter((id, index) => /^\d{15,25}$/.test(id) && ids.indexOf(id) === index);
}

async function sendSecurityEventToDiscord(env, subsystem, event) {
  const token = getSiteLogBotToken(env);
  if (!token) return false;
  const config = SECURITY_SUBSYSTEMS[subsystem] || SECURITY_SUBSYSTEMS.access;
  const level = Object.prototype.hasOwnProperty.call(SECURITY_LOG_COLORS, event.level) ? event.level : "info";
  const userId = /^\d{15,25}$/.test(String(event.user_id || "")) ? String(event.user_id) : "";
  const userName = cleanErrorField(event.user_name || "", 80);
  const fields = [];
  if (userId) fields.push(discordField("Member", `<@${userId}>${userName ? `\n${userName}` : ""}\nID: \`${userId}\``, true));
  if (event.action) fields.push(discordField("Action", cleanErrorField(event.action, 120), true));
  if (event.resource_id || event.resource_name) {
    const label = cleanErrorField(event.resource_name || event.resource_id, 120);
    const link = event.resource_id ? `https://zyrexediting.xyz/leak?id=${encodeURIComponent(event.resource_id)}` : "";
    fields.push(discordField("Resource", link ? `[${label}](${link})\nID: \`${cleanErrorField(event.resource_id, 80)}\`` : label, true));
  }
  if (event.ip) fields.push(discordField("IP address", `||\`${cleanErrorField(event.ip, 60)}\`||`, true));
  if (event.country) fields.push(discordField("Country", cleanErrorField(event.country, 40), true));
  if (event.access) fields.push(discordField("Access", cleanErrorField(event.access, 200), true));
  const expiresAt = discordTime(event.expires_at);
  if (expiresAt) fields.push(discordField("Access expires", `<t:${expiresAt}:F> • <t:${expiresAt}:R>`, true));
  if (event.reason) fields.push(discordField("Reason", cleanErrorField(event.reason, 400), false));

  const embed = {
    title: cleanErrorField(event.title || `${config.label} event`, 220),
    color: SECURITY_LOG_COLORS[level],
    timestamp: new Date().toISOString(),
    fields: fields.slice(0, 25),
    footer: { text: `Zyrex ${config.label} audit • logger bot` },
  };
  const description = cleanErrorField(event.description || "", 1500);
  if (description) embed.description = description;
  const avatar = String(event.user_avatar || "");
  if (userId) {
    embed.author = {
      name: userName || "Website member",
      ...(/^https:\/\/(?:cdn\.discordapp\.com|media\.discordapp\.net|thumbnail\.zyrexediting\.xyz)\//i.test(avatar) ? { icon_url: avatar } : {}),
      url: `https://discord.com/users/${userId}`,
    };
  }

  for (const channelId of securityLogChannels(env, subsystem)) {
    try {
      const response = await fetch(`${DISCORD_API}/channels/${channelId}/messages`, {
        method: "POST",
        headers: { Authorization: `Bot ${token}`, "Content-Type": "application/json" },
        body: JSON.stringify({ embeds: [embed], allowed_mentions: { parse: [] } }),
        signal: AbortSignal.timeout(6000),
      });
      if (response.ok) return true;
      console.error(`Security log to ${channelId} failed:`, response.status, (await response.text()).slice(0, 200));
    } catch (error) {
      console.error(`Security log to ${channelId} failed:`, error?.message || String(error));
    }
  }
  return false;
}

// The VPS bots relay their own events; map one payload shape onto the audit embed.
function securityEventFromRelay(event, subsystem) {
  const source = event || {};
  return {
    level: source.level || (source.kind === "error" ? "warn" : "info"),
    title: source.title || (subsystem === "verification" ? "Verified role event" : "Download access event"),
    description: source.message || source.description || "",
    action: source.action || `${subsystem}-relay`,
    user_id: source.user_id || "",
    user_name: source.user_name || source.username || "",
    user_avatar: source.user_avatar || "",
    ip: source.ip || "",
    country: source.country || "",
    access: source.access || "",
    expires_at: source.expires_at || "",
    reason: source.reason || "",
    resource_id: source.resource_id || source.product_id || "",
    resource_name: source.resource_name || source.product_name || "",
  };
}

// The decision is already made; the audit line must never delay the response.
function queueSecurityEvent(env, ctx, subsystem, event) {
  const task = sendSecurityEventToDiscord(env, subsystem, event).catch(() => false);
  if (ctx && ctx.waitUntil) ctx.waitUntil(task);
  else task.catch(() => false);
  return task;
}

function normalizeRequestMatchText(value) {
  return String(value || "").normalize("NFKD").replace(/[\u0300-\u036f]/g, "")
    .toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

function normalizeRequestMatchUrl(value) {
  try {
    let raw = String(value || "").trim();
    if (!raw) return "";
    if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(raw)) raw = `https://${raw}`;
    const parsed = new URL(raw);
    const path = parsed.pathname.replace(/\/+$/, "").toLowerCase();
    if (!path) return "";
    const host = parsed.hostname.toLowerCase().replace(/^www\./, "");
    const parts = path.split("/").filter(Boolean);
    if (/(^|\.)payhip\.com$/.test(host)) return `payhip:${parts.at(-1) || ""}`;
    if (/(^|\.)gumroad\.com$/.test(host)) return `gumroad:${parts.at(-1) || ""}`;
    if (host === "ko-fi.com") return `kofi:${parts.at(-1) || ""}`;
    return `${host}${path}`;
  } catch (_) { return ""; }
}

function getResourceSourceUrls(resource) {
  const values = [resource?.product_url, resource?.source_url, resource?.source_link, resource?.original_url];
  for (const group of [resource?.source_urls, resource?.product_urls]) {
    if (Array.isArray(group)) values.push(...group);
  }
  if (Array.isArray(resource?.links)) {
    for (const link of resource.links) {
      if (typeof link === "string") values.push(link);
      else if (link && typeof link === "object") values.push(link.url, link.href, link.link);
    }
  }
  return [...new Set(values.map(value => {
    const raw = String(value || "").trim();
    return /^(?:payhip|gumroad|kofi):/i.test(raw) ? raw.toLowerCase() : normalizeRequestMatchUrl(raw);
  }).filter(Boolean))];
}

function getRequestMatchIdentities(item, isRequest) {
  const values = isRequest
    ? [item.creator_name, item.creator_social_url]
    : [item.creator_nickname, item.creator_username, item.creator_social_url];
  const identities = new Set();
  const ignored = new Set(["http", "https", "www", "com", "tiktok", "instagram", "twitter", "x"]);
  for (const value of values) {
    const raw = String(value || "").trim();
    if (!raw) continue;
    try {
      if (/^https?:\/\//i.test(raw)) {
        const parsed = new URL(raw);
        const handle = parsed.pathname.split("/").filter(Boolean).pop() || "";
        const normalizedHandle = normalizeRequestMatchText(handle.replace(/^@/, ""));
        if (normalizedHandle && !ignored.has(normalizedHandle)) identities.add(normalizedHandle);
        continue;
      }
    } catch (_) {}
    const normalized = normalizeRequestMatchText(raw.replace(/^@/, ""));
    if (normalized && !ignored.has(normalized)) identities.add(normalized);
  }
  return identities;
}

function requestResourceTypeCompatible(req, product) {
  const wanted = normalizeRequestMatchText(req.type).replace(/ /g, "-");
  if (!wanted || wanted === "other") return true;
  const subcategories = Array.isArray(product.resource_subcategories)
    ? product.resource_subcategories
    : String(product.resource_subcategories || "").split(/[,/]/);
  const actual = new Set([product.type, product.resource_category, ...subcategories]
    .flatMap(value => String(value || "").split(/[,/]/))
    .map(value => normalizeRequestMatchText(value).replace(/ /g, "-"))
    .filter(Boolean));
  if (!actual.size) return true;
  if (wanted === "project-file") return actual.has("project-file") || actual.has("projectfile") || actual.has("preset");
  if (wanted === "preset") return actual.has("preset") || actual.has("project-file") || actual.has("projectfile");
  return actual.has(wanted);
}

function findBestRequestForResource(product, requests) {
  if (!product) return null;
  const title = normalizeRequestMatchText(product.name || product.title);
  const genericWords = new Set(["a", "an", "the", "pack", "preset", "editing", "edit", "project", "file", "cc", "coloring", "bundle", "effect", "effects", "new"]);
  const titleTokens = new Set(title.split(/\s+/).filter(Boolean));
  const informativeTokens = [...titleTokens].filter(token => !genericWords.has(token));
  const productUrls = new Set(getResourceSourceUrls(product));
  const productIdentities = getRequestMatchIdentities(product, false);
  const candidates = [];

  for (const req of requests || []) {
    if (["completed", "rejected"].includes(String(req.status || "pending").toLowerCase())) continue;
    const reqUrls = getResourceSourceUrls(req);
    const exactUrl = reqUrls.some(value => productUrls.has(value));
    // An exact source link is authoritative even if request and resource titles
    // or category labels differ.
    if (exactUrl) return req;
    if (!title || !requestResourceTypeCompatible(req, product)) continue;
    const reqTitle = normalizeRequestMatchText(req.title);
    if (!reqTitle) continue;
    const exactTitle = reqTitle === title;
    const reqIdentities = getRequestMatchIdentities(req, true);
    const identityMatch = [...reqIdentities].some(value => productIdentities.has(value));
    const identityConflict = reqIdentities.size > 0 && productIdentities.size > 0 && !identityMatch;
    const reqTokens = new Set(reqTitle.split(/\s+/).filter(Boolean));
    const overlap = [...titleTokens].filter(token => reqTokens.has(token)).length;
    const union = new Set([...titleTokens, ...reqTokens]).size;
    const similarity = union ? overlap / union : 0;
    let score = 0;
    if (exactUrl) score = 1000 + (identityMatch ? 20 : 0);
    else if (exactTitle && !identityConflict && (identityMatch || informativeTokens.length >= 2)) score = 600 + (identityMatch ? 100 : 0);
    else if (!identityConflict && identityMatch && similarity >= 0.78 && overlap > 0) score = 300 + Math.round(similarity * 100) + 100;
    else if (!identityConflict && !reqIdentities.size && !productIdentities.size && similarity >= 0.94 && informativeTokens.length >= 3) score = 300 + Math.round(similarity * 100);
    if (score) candidates.push({ req, score });
  }

  candidates.sort((a, b) => b.score - a.score);
  if (!candidates.length) return null;
  if (candidates[1] && candidates[0].score - candidates[1].score < 60) return null;
  return candidates[0].req;
}

function formatPayhipPrice(amount, currency = "") {
  const raw = String(amount ?? "").trim();
  if (!raw) return "";
  if (/^free$/i.test(raw)) return "Free";
  const numeric = raw.replace(/,/g, "");
  if (!/^\d+(?:\.\d{1,4})?$/.test(numeric)) return "";
  const symbols = { USD: "$", GBP: "£", EUR: "€", JPY: "¥", CAD: "CA$", AUD: "A$", TRY: "₺", CHF: "CHF " };
  const code = String(currency || "").toUpperCase();
  const symbol = symbols[code] || (code ? `${code} ` : "$");
  const value = Number(numeric);
  return value === 0 ? "Free" : `${symbol}${value.toFixed(2)}`;
}

function extractPayhipPrice(html) {
  const scripts = [...String(html || "").matchAll(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)];
  const offers = [];
  const visit = value => {
    if (Array.isArray(value)) return value.forEach(visit);
    if (!value || typeof value !== "object") return;
    if (value["@graph"]) visit(value["@graph"]);
    const type = Array.isArray(value["@type"]) ? value["@type"].join(" ") : String(value["@type"] || "");
    const offerValue = value.offers || (/(?:^|\s)(?:Offer|AggregateOffer)(?:\s|$)/i.test(type) ? value : null);
    if (offerValue) {
      for (const offer of (Array.isArray(offerValue) ? offerValue : [offerValue])) {
        const spec = offer?.priceSpecification || {};
        const amount = offer?.price ?? offer?.lowPrice ?? spec.price ?? spec.minPrice;
        if (amount !== undefined && amount !== null) offers.push(formatPayhipPrice(amount, offer.priceCurrency || spec.priceCurrency));
      }
    }
    for (const [key, child] of Object.entries(value)) if (key !== "offers" && key !== "@graph" && child && typeof child === "object") visit(child);
  };
  for (const script of scripts) {
    try { visit(JSON.parse(script[1])); } catch (_) {}
  }
  const structuredPrice = offers.find(Boolean);
  if (structuredPrice) return structuredPrice;

  const meta = String(html || "").match(/<meta\b(?=[^>]*(?:property|name)=["'](?:product:price:amount|og:price:amount|price)["'])(?=[^>]*content=["']([^"']+)["'])[^>]*>/i);
  if (meta?.[1]) {
    const currency = (String(html).match(/<meta\b(?=[^>]*(?:property|name)=["'](?:product:price:currency|og:price:currency)["'])(?=[^>]*content=["']([^"']+)["'])[^>]*>/i) || [])[1];
    const formatted = formatPayhipPrice(meta[1].replace(/[^\d.,]/g, "").replace(/,(?=\d{3}\b)/g, ""), currency);
    if (formatted) return formatted;
  }
  const itemprop = String(html || "").match(/<[^>]*itemprop=["']price["'][^>]*content=["']([^"']+)["'][^>]*>/i);
  if (itemprop?.[1]) {
    const currency = (String(html).match(/itemprop=["']priceCurrency["'][^>]*content=["']([^"']+)["']/i) || [])[1];
    const formatted = formatPayhipPrice(itemprop[1], currency);
    if (formatted) return formatted;
  }
  const priceElement = String(html || "").match(/<([a-z0-9]+)\b[^>]*class=["'][^"']*(?:product-)?price[^"']*["'][^>]*>([\s\S]{0,180}?)<\/\1>/i);
  if (priceElement?.[2]) {
    const text = priceElement[2].replace(/<[^>]*>/g, " ").replace(/&nbsp;|&#160;/gi, " ").trim();
    if (/\bfree\b/i.test(text)) return "Free";
    const match = text.match(/(CA\$|A\$|USD|GBP|EUR|JPY|TRY|CHF|[$£€¥₺])\s*(\d[\d,]*(?:\.\d{1,4})?)/i);
    if (match) {
      const code = /^(?:CA\$|A\$|USD|GBP|EUR|JPY|TRY|CHF)$/i.test(match[1]) ? match[1].replace("$", "") : ({ "£": "GBP", "€": "EUR", "¥": "JPY", "₺": "TRY", "$": "USD" }[match[1]] || "USD");
      return formatPayhipPrice(match[2].replace(/,/g, ""), code);
    }
  }
  return "";
}

function extractApiKey(request, url = null) {
  if (!request) return "";
  let key = request.headers.get("X-Zyrex-Key") ||
            request.headers.get("X-API-Key") ||
            request.headers.get("x-zyrex-key") ||
            request.headers.get("x-api-key") ||
            "";
  if (!key) {
    const auth = request.headers.get("Authorization") || "";
    if (auth.toLowerCase().startsWith("bearer ")) {
      key = auth.slice(7).trim();
    }
  }
  if (!key) {
    try {
      const parsedUrl = url || (request.url ? new URL(request.url) : null);
      if (parsedUrl && parsedUrl.searchParams) {
        key = parsedUrl.searchParams.get("api_key") || parsedUrl.searchParams.get("key") || parsedUrl.searchParams.get("master_key") || "";
      }
    } catch (_) {}
  }
  if (!key && request && request.headers) {
    try {
      const cookieHeader = request.headers.get("Cookie") || "";
      const match = cookieHeader.match(/(?:^|;\s*)zyrex_master_key=([^;]+)/);
      if (match) key = decodeURIComponent(match[1]).trim();
    } catch (_) {}
  }
  return key;
}

function isMasterApiKey(key, env = null) {
  if (!key) return false;
  const master = env?.ZYREX_MASTER_KEY || ZYREX_MASTER_KEY;
  const maintenanceKey = env?.ZYREX_MAINTENANCE_KEY || "";
  return key === master || (!!maintenanceKey && key === maintenanceKey);
}

function isValidAppApiKey(key, env = null) {
  if (!key) return false;
  const master = env?.ZYREX_MASTER_KEY || ZYREX_MASTER_KEY;
  const legacyAppKey = env?.ZYREX_API_KEY || "zyrex_app_sec_k982f81a7b54c29013e9a";
  return key === master || key === legacyAppKey;
}

