// No separate notification needed — the bot announces directly to Discord channel during submit
// See C:\Users\reyli\Desktop\zyrex-bot\bot.py → announce_product()

// In-memory stores
let sftpgoToken = null;
let sftpgoTokenExpiry = 0;
const downloadCounts = new Map();  // productId -> count (stateless — reset on cold start, acceptable)
const downloadCooldownMap = new Map();  // user:product -> timestamp (15s cooldown enforcement)
const usedTokens = new Set();  // single-use token enforcement (in-memory cache, backed by R2)
const TOKEN_EXPIRY = 1800;  // 30 minutes, to allow mobile ad tasks and app switching

// Self-contained token helpers (Workers are stateless — tokens carry their own data)
function base64UrlEncode(bytes) {
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function base64UrlDecode(value) {
  let base64 = String(value || "").replace(/-/g, "+").replace(/_/g, "/");
  while (base64.length % 4) base64 += "=";
  return Uint8Array.from(atob(base64), c => c.charCodeAt(0));
}

async function getDownloadTokenKey(env) {
  const secret = String(env.DOWNLOAD_TOKEN_SECRET || env.ZYREX_API_KEY || "").trim();
  if (!secret) throw new Error("DOWNLOAD_TOKEN_SECRET is not configured");
  return crypto.subtle.importKey("raw", new TextEncoder().encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign", "verify"]);
}

async function encodeToken(data, env) {
  const payload = JSON.stringify({ ...data, exp: Date.now() + TOKEN_EXPIRY * 1000 });
  const bytes = new TextEncoder().encode(payload);
  const encoded = base64UrlEncode(bytes);
  const signature = await crypto.subtle.sign("HMAC", await getDownloadTokenKey(env), new TextEncoder().encode(encoded));
  return encoded + "." + base64UrlEncode(new Uint8Array(signature));
}

async function decodeToken(token, env) {
  try {
    if (!token) return null;
    const parts = String(token).split(".");
    if (parts.length !== 2) return null;
    const valid = await crypto.subtle.verify("HMAC", await getDownloadTokenKey(env), base64UrlDecode(parts[1]), new TextEncoder().encode(parts[0]));
    if (!valid) return null;
    const json = new TextDecoder().decode(base64UrlDecode(parts[0]));
    const data = JSON.parse(json);
    if (Date.now() > data.exp) return null;  // expired
    return data;
  } catch { return null; }
}

function getClientIp(request) {
  return String(request.headers.get("CF-Connecting-IP") || "").trim();
}

// A pending unlock is a short-lived claim: it exists for 30 minutes, and is only
// marked complete when the offer provider sends the member back through the unlock
// landing route. Nothing else can complete it.
async function getAccessGrant(env, grantId) {
  if (!env.STORAGE || !grantId) return null;
  try {
    const obj = await env.STORAGE.get("unlock/grants/" + grantId);
    return obj ? await obj.json() : null;
  } catch (_) { return null; }
}

const ACCESS_USER_GRANTS_PREFIX = "unlock/user-grants/";

// One small record per member, so answering "how many times did this member try
// and did any of them complete?" never requires scanning the whole grant prefix.
async function recordUserGrant(env, discordId, entry) {
  const id = String(discordId || "").trim();
  if (!env?.STORAGE || !/^\d{17,20}$/.test(id) || !entry?.grant_id) return;
  try {
    const key = ACCESS_USER_GRANTS_PREFIX + id + ".json";
    const stored = await r2GetJSON(env, key, []);
    const list = Array.isArray(stored) ? stored : [];
    const existing = list.find(item => item && item.grant_id === entry.grant_id);
    if (existing) Object.assign(existing, entry);
    else list.unshift({ ...entry });
    await r2PutJSON(env, key, list.slice(0, 20));
  } catch (_) {}
}

async function readUserGrants(env, discordId) {
  const id = String(discordId || "").trim();
  if (!env?.STORAGE || !/^\d{17,20}$/.test(id)) return [];
  const stored = await r2GetJSON(env, ACCESS_USER_GRANTS_PREFIX + id + ".json", []);
  return Array.isArray(stored) ? stored : [];
}

// Only these observations and offer hosts are ever stored, so a report cannot
// be used to smuggle arbitrary text or URLs into the diagnostics prefix.
const DIAGNOSTIC_SYMPTOMS = new Set(["blank", "stuck_loading", "adblock_warning", "tasks_never_complete", "error_message", "works_now"]);

// The offer provider rotates the short domain it serves lockers from, so the host
// cannot be pinned to one literal. A link is accepted only when it is a plain https
// URL on a public DNS name that is not our own site, which blocks javascript:,
// data:, localhost and private-range targets without breaking a provider rotation.
// An optional comma-separated allowlist in the environment can pin it down further.
function isAcceptableOfferUrl(value, allowlist = "") {
  let parsed;
  try { parsed = new URL(String(value || "")); } catch (_) { return false; }
  if (parsed.protocol !== "https:") return false;
  const host = parsed.hostname.toLowerCase();
  if (!host.includes(".") || host.endsWith(".")) return false;
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(host)) return false;
  if (host === "localhost" || host.endsWith(".localhost") || host.endsWith(".local")) return false;
  if (host === "zyrexediting.xyz" || host.endsWith(".zyrexediting.xyz")) return false;
  if (/^(10|127)\./.test(host) || /^192\.168\./.test(host) || /^169\.254\./.test(host)) return false;
  if (/^172\.(1[6-9]|2\d|3[01])\./.test(host)) return false;
  const allowed = String(allowlist || "").split(",").map(item => item.trim().toLowerCase()).filter(Boolean);
  if (allowed.length && !allowed.some(entry => host === entry || host.endsWith("." + entry))) return false;
  return true;
}

function offerHostAllowlist(env) {
  return String(env?.ADMAVEN_LOCKER_HOSTS || "");
}

function diagnosticStringList(value, max, length) {
  if (!Array.isArray(value)) return [];
  return value.slice(0, max).map(item => String(item == null ? "" : item).slice(0, length)).filter(Boolean);
}

function sanitizeDiagnosticExtensions(input) {
  const source = input && typeof input === "object" ? input : {};
  return {
    signals: diagnosticStringList(source.signals, 20, 70),
    plugins: diagnosticStringList(source.plugins, 20, 60),
    detected: diagnosticStringList(source.detected, 30, 60),
  };
}

// Our own page's DevTools-equivalent data. The third-party locker page cannot be
// inspected from here, which is what the HAR summary below is for.
function sanitizeDiagnosticPage(input) {
  const source = input && typeof input === "object" ? input : {};
  const rawTimings = source.timings && typeof source.timings === "object" ? source.timings : {};
  const timings = {};
  for (const key of Object.keys(rawTimings).slice(0, 20)) {
    const value = Number(rawTimings[key]);
    if (Number.isFinite(value)) timings[String(key).slice(0, 30)] = Math.round(value);
  }
  return {
    console_errors: diagnosticStringList(source.console_errors, 15, 170),
    failed_resources: diagnosticStringList(source.failed_resources, 15, 170),
    resources: diagnosticStringList(source.resources, 20, 120),
    timings,
    memory_mb: Math.round(Number(source.memory_mb) || 0),
    long_tasks: Math.round(Number(source.long_tasks) || 0),
    visibility: String(source.visibility || "").slice(0, 20),
  };
}

// Accepts only the derived summary of a HAR export: never headers, cookies,
// bodies, or full query strings.
function sanitizeDiagnosticHar(input) {
  if (!input || typeof input !== "object") return null;
  const summary = input.summary && typeof input.summary === "object" ? input.summary : {};
  const rawHosts = summary.hosts && typeof summary.hosts === "object" ? summary.hosts : {};
  const hosts = {};
  for (const host of Object.keys(rawHosts).slice(0, 25)) {
    const count = Number(rawHosts[host]);
    if (Number.isFinite(count)) hosts[String(host).slice(0, 80)] = Math.round(count);
  }
  const problems = Array.isArray(input.problems) ? input.problems.slice(0, 40).map(item => ({
    host: String(item?.host || "").slice(0, 80),
    path: String(item?.path || "").slice(0, 100),
    method: String(item?.method || "").slice(0, 8),
    status: Math.round(Number(item?.status) || 0),
    failure: String(item?.failure || "").slice(0, 100),
    time_ms: Math.round(Number(item?.time_ms) || 0),
  })) : [];
  return {
    total: Math.round(Number(summary.total) || 0),
    failed: Math.round(Number(summary.failed) || 0),
    pending: Math.round(Number(summary.pending) || 0),
    error_status: Math.round(Number(summary.error_status) || 0),
    captured_at: String(input.captured_at || "").slice(0, 24),
    hosts,
    problems,
  };
}

async function getDownloadAccess(env, discordId) {
  if (!env.STORAGE || !/^\d{15,22}$/.test(String(discordId || ""))) return null;
  try {
    const obj = await env.STORAGE.get("download-access/" + discordId);
    return obj ? await obj.json() : null;
  } catch (_) { return null; }
}

async function hasActiveDownloadAccess(env, discordId, now = Date.now()) {
  const access = await getDownloadAccess(env, discordId);
  return !!(access && Number(access.expires_at) > now);
}

// A download token only ever carries a pass flag now. The pass itself is what was
// granted after an offer was completed, so no per-token grant lookup is needed and
// a revoked pass is rejected the moment the stored record expires.
async function hasValidDownloadPass(env, data) {
  if (!data || !data.discord_id) return false;
  if (data.download_access === true) {
    return (await checkAdFreeRole(data.discord_id, env)) ||
      await hasActiveDownloadAccess(env, data.discord_id);
  }
  // Legacy ad-free tokens must still belong to a user who currently has
  // the explicitly approved role.
  return !data.ad_required && await checkAdFreeRole(data.discord_id, env);
}

// Creates the content-locker link the member is sent to. AdMaven only redirects to
// the `url` we hand it after the offer is completed, so that destination is the
// completion signal: it is our own unlock landing route, and it carries nothing but
// the unguessable claim id.
async function requestAdMavenLocker(env, destinationUrl, title) {
  const apiToken = String(env.ADMAVEN_API_TOKEN || "").trim();
  if (!apiToken) throw new Error("AdMaven is not configured");

  const lockerRequest = {
    title: String(title || "Zyrex Download").slice(0, 30),
    url: destinationUrl,
  };
  // A sub_id only works once it has been created in the publisher panel; sending an
  // unknown one makes the provider reject the whole request, so it is opt-in.
  const subId = String(env.ADMAVEN_SUB_ID || "").trim();
  if (subId) lockerRequest.sub_id = subId.slice(0, 7);
  // The API key is scoped to a content-locker tag. Accounts with more than one tag
  // have to say which one to use, so it is configurable rather than hardcoded.
  const tag = String(env.ADMAVEN_TAG || "").trim();
  if (tag) lockerRequest.tag = tag.slice(0, 40);
  const background = String(env.ADMAVEN_LOCKER_BACKGROUND || "").trim();
  if (background) lockerRequest.background = background;

  const response = await fetch("https://publishers.ad-maven.com/api/public/content_locker", {
    method: "POST",
    headers: { "Content-Type": "application/json", "Accept": "application/json", "Authorization": "Bearer " + apiToken },
    body: JSON.stringify(lockerRequest),
  });
  const raw = await response.text();
  let result = {};
  try { result = JSON.parse(raw); } catch (_) {}
  const message = result && typeof result === "object" ? result.message : null;
  const linkData = Array.isArray(message) ? message[0] : message;
  // The live API answers with `full_short`; the published documentation still calls
  // the field `desturl`, so both names are read and the message text is ignored.
  const destUrl = typeof linkData === "string"
    ? ""
    : String(linkData?.full_short || linkData?.desturl || "").trim();

  if (!response.ok || result.type === "error" || !destUrl) {
    const providerMessage = typeof linkData === "string"
      ? linkData
      : linkData?.error || linkData?.message || result?.error || result?.message || response.statusText || "invalid response";
    throw new Error("AdMaven could not create an offer link: " + String(providerMessage).slice(0, 180));
  }
  if (!isAcceptableOfferUrl(destUrl, offerHostAllowlist(env))) {
    throw new Error("AdMaven returned an offer link we cannot send you to");
  }

  return {
    url: destUrl,
    destination_url: destinationUrl,
    locker_request: lockerRequest,
    locker_status: response.status,
    locker_response: String(raw).slice(0, 900),
    short_code: String(linkData?.short || "").slice(0, 40),
    offer_host: (() => { try { return new URL(destUrl).hostname; } catch (_) { return ""; } })(),
  };
}

async function createAdMavenLockerLink(env, destinationUrl, title) {
  return (await requestAdMavenLocker(env, destinationUrl, title)).url;
}

async function probeAdMaven(env) {
  const apiToken = String(env.ADMAVEN_API_TOKEN || "").trim();
  if (!apiToken) {
    return { status: "outage", latency: 0, error: "AdMaven API token is not configured" };
  }
  if (!env.STORAGE) {
    return { status: "outage", latency: 0, error: "Unlock storage is unavailable" };
  }
  if (adMavenProbeCache.value && Date.now() < adMavenProbeCache.expiresAt) {
    return { ...adMavenProbeCache.value };
  }
  const cacheResult = result => {
    adMavenProbeCache = { value: result, expiresAt: Date.now() + 10000 };
    return { ...result };
  };

  const startedAt = Date.now();
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 2200);
  let outcome;
  try {
    // A GET with no `url` is answered with the parameter error, which still proves
    // the endpoint and the token are live without creating a real locker link.
    const probeUrl = new URL("https://publishers.ad-maven.com/api/public/content_locker");
    probeUrl.searchParams.set("api_token", apiToken);
    const response = await fetch(probeUrl.toString(), {
      method: "GET",
      headers: { "Accept": "application/json" },
      signal: controller.signal,
    });
    const body = await response.text().catch(() => "");
    outcome = { status: response.status, body: String(body).slice(0, 200) };
  } catch (error) {
    outcome = { error: error?.name === "AbortError" ? "AdMaven API probe timed out" : "AdMaven API could not be reached" };
  } finally {
    clearTimeout(timeoutId);
  }
  const latency = Date.now() - startedAt;

  if (outcome.error) return cacheResult({ status: "outage", latency, error: outcome.error });
  if (/tag or sub does not exist/i.test(outcome.body)) {
    return cacheResult({
      status: "outage",
      latency,
      error: "AdMaven has no content-locker tag enabled for this account",
    });
  }
  if (outcome.status === 401 || outcome.status === 403) {
    return cacheResult({ status: "outage", latency, error: "AdMaven rejected the configured API token" });
  }
  if (outcome.status === 429) {
    return cacheResult({ status: "degraded", latency, error: "AdMaven API is rate limited" });
  }
  // A validation error proves the endpoint and the token are both fine: the API
  // answers 500 for a missing field, which must not be read as an outage.
  if (/Missing mandatory field/i.test(outcome.body)) {
    return cacheResult({ status: "operational", latency, error: null });
  }
  if (outcome.status === 404 || outcome.status >= 500) {
    return cacheResult({ status: "outage", latency, error: "AdMaven API endpoint is unavailable" });
  }
  if (latency >= 1500) {
    return cacheResult({ status: "degraded", latency, error: "AdMaven API response is slow" });
  }
  if (!(outcome.status >= 200 && outcome.status < 300) && outcome.status !== 400) {
    return cacheResult({ status: "degraded", latency, error: "AdMaven API returned an unexpected response" });
  }
  return cacheResult({ status: "operational", latency, error: null });
}

function hashToken(token) {
  return token.length > 32 ? token.slice(-32) : token;
}

// Check if token was used (in-memory cache + R2 persistent)
async function checkTokenUsed(env, tokenFingerprint) {
  if (usedTokens.has(tokenFingerprint)) return true;
  try {
    const marker = await env.STORAGE.get("tokens/used/" + tokenFingerprint);
    if (marker) {
      usedTokens.add(tokenFingerprint); // cache for this isolate
      return true;
    }
  } catch(e) {}
  return false;
}

// Single-use enforcement. The claim is written before any archive work starts and is
// verified by reading it back, so two requests racing on the same token cannot both
// proceed and a page reload can never replay a spent link.
async function claimTokenOnce(env, tokenFingerprint) {
 const fingerprint = String(tokenFingerprint || "");
 if (!fingerprint) return false;
 if (usedTokens.has(fingerprint)) return false;
 if (!env || !env.STORAGE) return false;
 const key = "tokens/used/" + fingerprint;
 const nonce = (crypto.randomUUID ? crypto.randomUUID() : String(Math.random())) + "";
 const payload = JSON.stringify({ used_at: Date.now(), nonce });
 try {
   const existing = await env.STORAGE.get(key);
   if (existing) {
     usedTokens.add(fingerprint);
     return false;
   }
   await env.STORAGE.put(key, payload, { httpMetadata: { contentType: "application/json" } });
   const verify = await env.STORAGE.get(key);
   const body = verify ? await verify.text() : "";
   if (!body.includes(nonce)) return false;
   usedTokens.add(fingerprint);
   return true;
 } catch (error) {
   // Fail closed: an unverified claim must never unlock a second download.
   console.error("claimTokenOnce storage error:", error?.message || String(error));
   return false;
 }
}

// A claim only becomes final once bytes reach the visitor. When the archive could not
// be produced at all the link stays usable, so a storage hiccup does not burn it.
async function releaseTokenClaim(env, tokenFingerprint) {
  const fingerprint = String(tokenFingerprint || "");
  if (!fingerprint) return;
  usedTokens.delete(fingerprint);
  if (!env?.STORAGE) return;
  try {
    await env.STORAGE.delete("tokens/used/" + fingerprint);
  } catch (error) {
    console.error("releaseTokenClaim storage error:", error?.message || String(error));
  }
}

// Mark token as used (in-memory + R2 persistent)
async function markTokenUsed(env, tokenFingerprint) {
  usedTokens.add(tokenFingerprint);
  try {
    // Store a small marker in R2 so token stays used across Worker recycles
    const markerData = new TextEncoder().encode(JSON.stringify({ used_at: Date.now() }));
    await env.STORAGE.put("tokens/used/" + tokenFingerprint, markerData);
  } catch(e) { console.error("markTokenUsed storage error:", e.message); }
}

// The storage service answers through a tunnel and restarts on its own, so a single
// hiccup used to fail the whole download. Ask for a fresh token and retry once before
// giving up, with a timeout so a hung storage call cannot consume the request.
const DOWNLOAD_MIME_BY_EXT = {
  zip: "application/zip", rar: "application/vnd.rar", "7z": "application/x-7z-compressed",
  pdf: "application/pdf", mp4: "video/mp4", mov: "video/quicktime", mkv: "video/x-matroska",
  mp3: "audio/mpeg", wav: "audio/wav", aep: "application/octet-stream", prproj: "application/octet-stream",
  png: "image/png", jpg: "image/jpeg", jpeg: "image/jpeg", gif: "image/gif", webp: "image/webp",
  txt: "text/plain; charset=utf-8", json: "application/json",
};

// One file needs no archive: stream it straight out of R2 when the zip service is
// unavailable, so a single-file resource never fails because of the packer.
async function streamSingleStorageObject(env, object, useProd, title) {
  if (!object || !object.key) return null;
  try {
    const stored = await r2Get(env, object.key, useProd);
    if (!stored || !stored.body) return null;
    const originalName = String(object.key).split("/").pop() || "file";
    const extension = (originalName.split(".").pop() || "").toLowerCase();
    const base = safeZipFilename(title || originalName.replace(/\.[^.]+$/, "")).slice(0, 110) || "download";
    const filename = extension ? `${base} - ${DOWNLOAD_BRAND}.${extension}` : `${base} - ${DOWNLOAD_BRAND}`;
    const asciiFilename = filename.replace(/[^\x20-\x7E]/g, "_").replace(/["\\]/g, "_");
    const headers = {
      "Content-Type": DOWNLOAD_MIME_BY_EXT[extension] || "application/octet-stream",
      "Content-Disposition": `attachment; filename="${asciiFilename}"; filename*=UTF-8''${encodeURIComponent(filename)}`,
      "Cache-Control": "no-store",
    };
    if (stored.size) headers["Content-Length"] = String(stored.size);
    return new Response(stored.body, { status: 200, headers });
  } catch (error) {
    console.error("Direct storage fallback failed:", error?.message || String(error));
    return null;
  }
}

// ── Archive cache ──────────────────────────────────────────────────────────────
// The archive is built once by the storage service and then served straight from R2. Repeat
// downloads of the same file set never touch the VPS, which removes the single point of
// failure that produced STORAGE_UNAVAILABLE 503s.
const ARCHIVE_CACHE_PREFIX = "downloads/archives/";
// The worker holds the stream in memory while copying it, so very large packs stay uncached.
const ARCHIVE_CACHE_MAX_BYTES = 96 * 1024 * 1024;

async function archiveCacheKey(productId, r2Prefix, selectedNames) {
  const names = (Array.isArray(selectedNames) ? selectedNames : []).slice().sort();
  const material = JSON.stringify({ product: String(productId || ""), prefix: String(r2Prefix || ""), names });
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(material));
  const hash = Array.from(new Uint8Array(digest).slice(0, 16), byte => byte.toString(16).padStart(2, "0")).join("");
  return `${ARCHIVE_CACHE_PREFIX}${hash}.zip`;
}

async function readCachedArchive(env, key) {
  if (!env?.STORAGE || !key) return null;
  try {
    const object = await env.STORAGE.get(key);
    if (!object || !object.body) return null;
    return object;
  } catch (_) {
    return null;
  }
}

// Copies the archive into R2 while the visitor downloads it, so the next request is cache-only.
function cacheArchiveWhileStreaming(ctx, env, key, response) {
  const length = Number(response.headers.get("Content-Length") || 0);
  if (!env?.STORAGE || !key || !response.body || !Number.isFinite(length) || length <= 0 || length > ARCHIVE_CACHE_MAX_BYTES) {
    return response.body;
  }
  const [toVisitor, toCache] = response.body.tee();
  const task = (async () => {
    try {
      const { readable, writable } = new FixedLengthStream(length);
      const copied = toCache.pipeTo(writable).catch(() => null);
      await env.STORAGE.put(key, readable, { httpMetadata: { contentType: "application/zip" } });
      await copied;
    } catch (error) {
      console.warn("Archive cache write skipped:", error?.message || String(error));
    }
  })();
  if (ctx?.waitUntil) ctx.waitUntil(task);
  return toVisitor;
}

// Builds the archive ahead of the click, so the visitor's own request is a cache hit.
async function warmArchiveCache(env, ctx, options) {
  if (!env?.STORAGE) return false;
  const productId = String((options && options.productId) || "");
  const r2Prefix = String((options && options.r2Prefix) || "");
  if (!r2Prefix) return false;
  const task = (async () => {
    try {
      let objects = [];
      try { objects = archiveObjects(await r2List(env, r2Prefix, true), r2Prefix); } catch (_) { objects = []; }
      if (!objects.length) {
        try { objects = archiveObjects(await r2List(env, r2Prefix, false), r2Prefix); } catch (_) { objects = []; }
      }
      if (!objects.length) return false;
      const names = objects.map(object => relativeR2Name(object.key, r2Prefix)).filter(Boolean);
      const key = await archiveCacheKey(productId, r2Prefix, names);
      if (await readCachedArchive(env, key)) return true;
      const built = await requestStorageZip({
        discordId: String((options && options.discordId) || "warm"),
        productId,
        r2Prefix,
        title: String((options && options.title) || productId),
        selectedNames: names,
      }, { attempts: 1, startTimeouts: [25000] });
      if (!built.response || !built.response.body) return false;
      const declared = Number(built.response.headers.get("Content-Length") || 0);
      if (declared > ARCHIVE_CACHE_MAX_BYTES) return false;
      // Streamed archives carry no Content-Length, so copy with a hard cap instead of
      // buffering whatever the storage host sends.
      const reader = built.response.body.getReader();
      const chunks = [];
      let total = 0;
      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          total += value.byteLength;
          if (total > ARCHIVE_CACHE_MAX_BYTES) {
            await reader.cancel().catch(() => {});
            return false;
          }
          chunks.push(value);
        }
      } catch (error) {
        await reader.cancel().catch(() => {});
        return false;
      }
      if (!total) return false;
      const bytes = new Uint8Array(total);
      let offset = 0;
      for (const chunk of chunks) {
        bytes.set(chunk, offset);
        offset += chunk.byteLength;
      }
      await env.STORAGE.put(key, bytes, { httpMetadata: { contentType: "application/zip" } });
      return true;
    } catch (error) {
      console.warn("Archive warm skipped:", error?.message || String(error));
      return false;
    }
  })();
  if (ctx?.waitUntil) ctx.waitUntil(task);
  return task;
}

async function requestStorageZip({ discordId, productId, r2Prefix, title, selectedNames }, options = {}) {
  const serviceAuth = "zyrex-files-api-2026";
  // The archive is built on demand, so a cold or busy storage host can take a while to
  // answer. Four staggered attempts give it room without holding the visitor forever; a
  // background warm uses a single attempt so it never piles up.
  const attempts = Math.max(1, Math.min(Number(options.attempts) || 4, 4));
  const startTimeouts = options.startTimeouts || [45000, 35000, 25000, 20000];
  const backoff = [0, 600, 1200, 1800];
  let failure = "prepare";
  let detail = { status: 0, type: "", reason: "" };

  for (let attempt = 1; attempt <= attempts; attempt++) {
    let tokenBody = null;
    try {
      const tokenResponse = await fetch(`${FILE_API}/api/files/request-token`, {
        method: "POST",
        headers: { "Content-Type": "application/json", "X-API-Token": serviceAuth },
        body: JSON.stringify({
          discord_id: discordId,
          product_id: productId,
          file_path: r2Prefix,
        }),
        signal: AbortSignal.timeout(8000),
      });
      tokenBody = await tokenResponse.json().catch(() => null);
      if (!tokenResponse.ok || !tokenBody?.success || !tokenBody?.token) {
        console.error("Storage ZIP token request failed:", attempt, tokenResponse.status, tokenBody?.error || "invalid response");
        tokenBody = null;
      }
    } catch (error) {
      console.error("Storage ZIP token request error:", attempt, error?.message || String(error));
      tokenBody = null;
    }

    if (tokenBody?.token) {
      const storageUrl = new URL(`${FILE_API}/api/files/download`);
      storageUrl.searchParams.set("token", tokenBody.token);
      storageUrl.searchParams.set("title", title || productId);
      // Pass the Worker-validated object list every time so placeholders and stored
      // watermark copies stay out of the archive.
      storageUrl.searchParams.set("files", (selectedNames || []).join(","));
      // The timeout covers waiting for the archive to start. Once headers arrive the
      // stream must stay open: aborting it mid-flight truncates large downloads.
      if (backoff[attempt - 1]) await new Promise(resolve => setTimeout(resolve, backoff[attempt - 1]));
      const startTimeoutMs = startTimeouts[attempt - 1] || 20000;
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), startTimeoutMs);
      let response = null;
      try {
        response = await fetch(storageUrl.toString(), {
          headers: { "X-API-Token": serviceAuth },
          signal: controller.signal,
        });
      } catch (error) {
        console.error("Storage ZIP request error:", attempt, error?.message || String(error));
        failure = "deliver";
        detail = { status: 0, type: "", reason: error?.name === "AbortError" ? "timeout" : String(error?.message || error).slice(0, 120) };
      } finally {
        clearTimeout(timer);
      }
      if (response) {
        const type = String(response.headers.get("Content-Type") || "").toLowerCase();
        const deliverable = response.ok && response.body &&
          (type.includes("application/zip") || type.includes("octet-stream") || type.includes("application/force-download") || type.includes("binary/octet-stream"));
        if (deliverable) return { response, failure: "", detail: { status: response.status, type, reason: "" } };
        const errorText = await response.text().catch(() => "");
        console.error("Storage ZIP request failed:", attempt, response.status, type, errorText.slice(0, 240));
        failure = "deliver";
        detail = { status: response.status, type: type.slice(0, 60), reason: errorText.slice(0, 160) };
      }
    }

    if (attempt < attempts) await new Promise(resolve => setTimeout(resolve, 400 * attempt));
  }

  return { response: null, failure, detail, attempts };
}

const SUBSYSTEM_NAMES = {
  api_gateway: "Api Gateway",
  site_gate: "Site Gate",
  storage: "Resource Downloads",
  requests_system: "Community Requests System",
  shortener_gateway: "Download Access (Offers)",
  resource_uploads: "Resource Uploads",
  comments: "Comments System",
  discord_auth: "Discord Authentication",
  token_generator: "Download Tokens"
};

async function recordTelemetryEvent(env, { subsystem, title, message, severity = "degraded", count = 1, user = "", source = "", type = "", status = 0 }) {
  try {
    if (!env.STORAGE) return;
    const key = "system/telemetry_events.json";
    let events = [];
    try {
      const obj = await env.STORAGE.get(key);
      if (obj) events = await obj.json();
    } catch (_) {}

    const now = new Date();
    const dateStr = now.toISOString().split("T")[0];

    const existing = events.find(e => 
      e.subsystem === subsystem && 
      e.title === title && 
      (now.getTime() - new Date(e.timestamp || e.created_at || now).getTime()) < 20 * 60 * 1000
    );

    if (existing) {
      existing.outages_count = (existing.outages_count || 1) + count;
      existing.last_seen = now.toISOString();
      existing.source = source || existing.source || "";
      existing.type = type || existing.type || "";
      existing.http_status = status || existing.http_status || 0;
      if (severity === "outage") existing.severity = severity;
      if (message && !existing.message.includes(message)) {
        existing.message = message;
      }
    } else {
      events.unshift({
        id: `inc-${now.getTime()}-${Math.random().toString(36).substring(2, 7)}`,
        subsystem: subsystem,
        subsystem_name: SUBSYSTEM_NAMES[subsystem] || subsystem,
        title: title,
        message: message,
        severity: severity,
        outages_count: count,
        source: source,
        type: type,
        http_status: status,
        date: dateStr,
        timestamp: now.toISOString(),
        created_at: now.toISOString(),
        status: "Investigating"
      });
      if (events.length > 100) events = events.slice(0, 100);
    }

    await env.STORAGE.put(key, JSON.stringify(events), {
      httpMetadata: { contentType: "application/json" }
    });
  } catch (err) {
    console.warn("Failed to record telemetry event:", err);
  }
}

// Role check cache (simple in-memory, 30s TTL)
const roleCheckCache = new Map();
let statusSummaryCache = { expiresAt: 0, value: null };
let adMavenProbeCache = { expiresAt: 0, value: null };

// Persistent role-check verdicts in R2 so verified members are not locked out
// during brief VPS/Discord outages (the live check falls back to this cache).
const ROLE_CHECK_R2_KEY = "database/verified_roles.json";

// The VPS bot publishes the full member list of each gated role into this single
// object on a timer. Reading one snapshot instead of asking Discord on every
// request removes the role-check latency that was blocking verified members
// (503 ROLE_CHECK_UNAVAILABLE) whenever the bot or Discord was slow.
const ROLE_SNAPSHOT_KEY = "database/role_members.json";
const ROLE_SNAPSHOT_STALE_MS = 6 * 60 * 60 * 1000;
// A miss is only conclusive while the snapshot is this recent; two sync cycles
// plus slack. Older snapshots still prove membership but never prove absence.
const ROLE_SNAPSHOT_FRESH_MS = 10 * 60 * 1000;
const ROLE_SNAPSHOT_MEMO_MS = 30 * 1000;
const ROLE_SNAPSHOT_MAX_IDS = 50000;
const VERIFIED_ROLE_ID = "1519246304163659858";
const roleSnapshotMemo = new Map();

function isValidRoleId(value) {
  return /^\d{15,25}$/.test(String(value || ""));
}

function cleanRoleIdList(input) {
  if (!Array.isArray(input)) return [];
  const out = [];
  for (const value of input) {
    const id = String(value == null ? "" : value).trim();
    if (/^\d{15,25}$/.test(id)) out.push(id);
    if (out.length >= ROLE_SNAPSHOT_MAX_IDS) break;
  }
  return out;
}

async function readRoleSnapshotRoles(env) {
  const data = await r2GetJSON(env, ROLE_SNAPSHOT_KEY, null);
  if (!data || typeof data !== "object") return {};
  const roles = data.roles;
  return roles && typeof roles === "object" ? roles : {};
}

// Returns { ids, fresh } or null when the snapshot is missing, malformed or too
// old to be trusted (in which case callers fall back to a live check).
async function loadRoleSnapshot(env, roleId) {
  if (!isValidRoleId(roleId) || !env || !env.STORAGE) return null;
  const memo = roleSnapshotMemo.get(roleId);
  if (memo && Date.now() - memo.at < ROLE_SNAPSHOT_MEMO_MS) return memo.value;
  let value = null;
  try {
    const entry = (await readRoleSnapshotRoles(env))[roleId];
    const updatedAt = Number(entry && entry.updated_at) || 0;
    const age = updatedAt ? Date.now() - updatedAt : null;
    if (entry && Array.isArray(entry.ids) && age !== null && age <= ROLE_SNAPSHOT_STALE_MS) {
      value = { ids: new Set(entry.ids.map(String)), fresh: age <= ROLE_SNAPSHOT_FRESH_MS };
    }
  } catch (e) {
    value = null;
  }
  roleSnapshotMemo.set(roleId, { at: Date.now(), value });
  return value;
}

async function updateRoleSnapshot(env, roleId, options) {
  const opts = options || {};
  const replace = Array.isArray(opts.userIds) ? cleanRoleIdList(opts.userIds) : null;
  const add = cleanRoleIdList(opts.add);
  const remove = cleanRoleIdList(opts.remove);
  const roles = await readRoleSnapshotRoles(env);
  const existingEntry = roles[roleId];
  const previous = existingEntry && Array.isArray(existingEntry.ids) ? existingEntry.ids.map(String) : null;
  let ids;
  if (replace) {
    // The snapshot answers access questions without a live lookup, so a truncated
    // list would lock real members out. An implausible shrink needs force:true.
    if (!opts.force && previous && previous.length >= 50 && replace.length < previous.length * 0.5) {
      return { refused: "shrink", existing: previous.length, incoming: replace.length };
    }
    ids = Array.from(new Set(replace));
  } else {
    // Patching a role that was never published would create a snapshot holding a
    // single id, which would then deny everybody else.
    if (!previous) return { refused: "missing" };
    const set = new Set(previous);
    for (const id of add) set.add(id);
    for (const id of remove) set.delete(id);
    ids = Array.from(set);
  }
  ids.sort();
  // A granted role is fresh evidence: if that member was only blocked because the
  // role had gone away, let them back in (bans, staff decisions and manual blocks
  // still hold — otherwise an explicit revoke would heal itself within minutes).
  if (!replace && add.length && roleId === VERIFIED_ROLE_ID) {
    const users = await readRevocationUsers(env).catch(() => ({}));
    const healing = add.filter(id => users[id] && !isStickyRevocation(users[id]));
    if (healing.length) {
      await restoreUserAccess(env, healing).catch(() => {});
      // Keep them in the list we are about to store.
      for (const id of healing) {
        if (!ids.includes(id)) ids.push(id);
      }
      ids.sort();
    }
  }
  const updatedAt = Date.now();
  // A blocked member must not be published as verified. The snapshot is the fast
  // path that answers downloads, so keeping a revoked id out of it means a failed
  // revocation read can never re-admit someone the staff explicitly blocked.
  let storedIds = ids;
  let filteredRevoked = 0;
  if (roleId === VERIFIED_ROLE_ID) {
    const blocked = await readRevocationUsers(env).catch(() => ({}));
    storedIds = ids.filter(id => !isStickyRevocation(blocked[id]));
    filteredRevoked = ids.length - storedIds.length;
    // Remembering who was verified is what lets a later rejoin be recognised as a
    // return instead of a first join.
    await recordMemberHistory(env, ids, { verified: true, source: "role-snapshot" }).catch(() => {});
  }
  roles[roleId] = {
    ids: storedIds,
    updated_at: updatedAt,
    updated_by: String(opts.source || "vps-bot").slice(0, 40),
  };
  await r2PutJSON(env, ROLE_SNAPSHOT_KEY, { version: 1, roles });
  roleSnapshotMemo.delete(roleId);

  // Only the verified role decides access, so only its list drives revocations.
  let autoRevoked = 0;
  let autoRestored = 0;
  if (replace && roleId === VERIFIED_ROLE_ID && previous && opts.autoRevoke !== false) {
    const nextSet = new Set(ids);
    const dropped = previous.filter(id => !nextSet.has(id));
    if (dropped.length) {
      // They are gone from the authoritative list: block them without waiting for
      // a gateway event, so a removed role or a ban cannot be missed.
      const revoked = await revokeUserAccess(env, dropped, {
        reason: "snapshot_drop",
        roleId,
        source: opts.source || "vps-sync",
      });
      autoRevoked = revoked.revoked.length;
    }
    // Role evidence heals weak revocations (they are verified again by the bot).
    const users = await readRevocationUsers(env);
    const healable = ids.filter(id => users[id] && !isStickyRevocation(users[id]));
    if (healable.length) {
      const restored = await restoreUserAccess(env, healable);
      autoRestored = restored.restored.length;
    }
  }

  return {
    count: storedIds.length,
    updated_at: updatedAt,
    added: add.length,
    removed: remove.length,
    filtered_revoked: filteredRevoked,
    auto_revoked: autoRevoked,
    auto_restored: autoRestored,
  };
}

// A live check proved this member has the role, so patch them into the snapshot
// for instant access without pretending the snapshot is fresher than it is.
async function addUserToRoleSnapshot(env, roleId, userId) {
  return addUsersToRoleSnapshot(env, roleId, [userId]);
}

// true  -> the snapshot lists the member
// false -> the snapshot is fresh and does not list them, so it is authoritative
// null  -> no usable snapshot, or one old enough that a miss proves nothing
async function roleSnapshotVerdict(env, roleId, userId) {
  const snapshot = await loadRoleSnapshot(env, roleId);
  if (!snapshot) return null;
  if (snapshot.ids.has(String(userId || ""))) return true;
  return snapshot.fresh ? false : null;
}

// Access revocations: the verified role was withdrawn, the member was banned, or
// they left the server. This list outranks every other signal — a snapshot hit, a
// cached verdict and a stored download pass — so access ends immediately.
const ROLE_REVOCATIONS_KEY = "database/role_revocations.json";
const REVOCATION_MEMO_MS = 30 * 1000;
const REVOCATION_MAX_USERS = 20000;
// Bans and staff decisions survive role evidence. A normal departure is cleared
// automatically after the member returns and the verified role is confirmed.
const STRONG_REVOKE_REASONS = new Set(["banned", "manual"]);
// A revocation a human asked for must outlive every automatic signal. Reasons like
// "left" or "role_removed" are healable when the bot sees the role again, so a staff
// decision is also marked sticky — otherwise the next snapshot publish silently
// undid an explicit Discord revoke for members who still hold the verified role
// (exactly what a banned-then-unbanned-and-returned member does).
const STAFF_REVOKE_SOURCE_PATTERN = /^(?:staff:|admin-console|staff-console)/;
// Ban and unban-hold sources also mark records written before the `sticky` flag
// existed. Departures and returns remain eligible for automatic recovery.
const AUTO_STICKY_SOURCE_PATTERN = /^(?:member-banned|member-unban-hold)/;
// Shown to a revoked member instead of the generic "verify your account" text.
const ACCESS_REVOKED_MESSAGE = "Your download access has been revoked. If you believe this is a mistake, contact the staff in our Discord server.";

const REVOKE_REASON_LABELS = {
  banned: "Banned from the server",
  manual: "Removed by staff",
  returned: "Rejoined after losing access",
  snapshot_drop: "No longer in the verified list",
  role_removed: "Verified role removed",
  left: "Left the server",
};
let revocationMemo = { at: 0, users: null };

// What the audit line says for each automatic reason. A staff revoke keeps the
// generic wording, because the reason is whatever the moderator picked.
const REVOCATION_NOTICES = {
  left: {
    title: "Member left — download access revoked",
    description: "They are blocked from downloading while away. Access is restored automatically when they return and regain the verified role.",
    color: 0xf59e0b,
  },
  banned: {
    title: "Member banned — download access revoked",
    description: "Banned members lose download access immediately and keep the block after an unban.",
    color: 0xef4444,
  },
  returned: {
    title: "Member returned with access still revoked",
    description: "This member returned. Access is restored automatically when the verified role is confirmed.",
    color: 0xef4444,
  },
};

// true when role evidence must not clear this revocation on its own.
function isStickyRevocation(entry) {
  if (!entry) return false;
  // Old leave/return records may have `sticky: true`; those blocks are still
  // automatically recoverable once a verified role snapshot confirms the member.
  const reason = String(entry.reason || "");
  const source = String(entry.source || "");
  if ((reason === "left" && /^member-left/.test(source))
      || (reason === "returned" && /^member-returned/.test(source))) return false;
  // An explicit flag always wins, so a caller can opt a record out.
  if (typeof entry.sticky === "boolean") return entry.sticky;
  if (STRONG_REVOKE_REASONS.has(entry.reason)) return true;
  return STAFF_REVOKE_SOURCE_PATTERN.test(source) || AUTO_STICKY_SOURCE_PATTERN.test(source);
}

function revocationSummary(entry) {
  if (!entry) return null;
  return {
    reason: String(entry.reason || "manual"),
    reason_label: REVOKE_REASON_LABELS[entry.reason] || String(entry.reason || "manual"),
    revoked_at: Number(entry.revoked_at) || 0,
    source: entry.source || null,
    sticky: isStickyRevocation(entry),
    previous_reason: entry.previous_reason || null,
  };
}

// ── Member history ────────────────────────────────────────────────────────────
// "Did we see this member before?" is what separates a first-time join from a
// returning one. Without it a rejoin cannot be told apart from a fresh signup, so
// the answer is persisted instead of guessed. The same record lets the bot revoke
// somebody whose departure it missed while the service was down.
const MEMBER_HISTORY_KEY = "database/member_history.json";
const MEMBER_HISTORY_MAX_USERS = 30000;

async function readMemberHistory(env) {
  const data = await r2GetJSON(env, MEMBER_HISTORY_KEY, null);
  if (!data || typeof data !== "object") return {};
  return data.users && typeof data.users === "object" ? data.users : {};
}

// Marks the ids as seen and reports which of them were already known. One write per
// call, because this runs on every join and on every verified publish.
async function recordMemberHistory(env, userIds, options) {
  const opts = options || {};
  const ids = cleanRoleIdList(userIds);
  const result = { known: [], new: [], recorded: 0 };
  if (!ids.length || !env || !env.STORAGE) return result;
  const users = await readMemberHistory(env);
  const now = Date.now();
  for (const id of ids) {
    const existing = users[id];
    if (existing && Number(existing.first_seen) > 0) {
      result.known.push(id);
      existing.last_seen = now;
      if (opts.verified) existing.verified = true;
      if (opts.download) existing.downloads = (Number(existing.downloads) || 0) + 1;
      continue;
    }
    users[id] = {
      first_seen: now,
      last_seen: now,
      verified: opts.verified === true,
      downloads: opts.download ? 1 : 0,
      source: String(opts.source || "worker").slice(0, 40),
    };
    result.new.push(id);
  }
  const keys = Object.keys(users);
  if (keys.length > MEMBER_HISTORY_MAX_USERS) {
    keys.sort((a, b) => (Number(users[a].last_seen) || 0) - (Number(users[b].last_seen) || 0));
    for (const key of keys.slice(0, keys.length - MEMBER_HISTORY_MAX_USERS)) delete users[key];
  }
  await r2PutJSON(env, MEMBER_HISTORY_KEY, { version: 1, updated_at: now, users });
  result.recorded = ids.length;
  return result;
}

async function readRevocationUsers(env) {
  const data = await r2GetJSON(env, ROLE_REVOCATIONS_KEY, null);
  if (!data || typeof data !== "object") return {};
  return data.users && typeof data.users === "object" ? data.users : {};
}

async function loadRevocations(env) {
  if (!env || !env.STORAGE) return null;
  if (revocationMemo.users && Date.now() - revocationMemo.at < REVOCATION_MEMO_MS) {
    return revocationMemo.users;
  }
  let users = null;
  try {
    users = await readRevocationUsers(env);
  } catch (e) {
    users = null;
  }
  revocationMemo = { at: Date.now(), users };
  return users;
}

// true -> blocked, false -> not on the list, null -> list unavailable (treated as
// not revoked, because a storage hiccup must never block the whole site).
async function isRevoked(env, discordId) {
  const id = String(discordId || "").trim();
  if (!/^\d{15,25}$/.test(id)) return false;
  const users = await loadRevocations(env);
  if (!users) return null;
  return Object.prototype.hasOwnProperty.call(users, id);
}

function purgeRoleCaches(userId) {
  const id = String(userId || "");
  roleCheckCache.delete(id);
  adFreeRoleCache.delete(id);
  uploaderRoleCache.delete(id);
}

async function deleteDownloadPass(env, discordId) {
  try {
    if (!env || !env.STORAGE) return false;
    await env.STORAGE.delete(RESOURCE_ACCESS_PATH + String(discordId || "").trim());
    return true;
  } catch (e) {
    return false;
  }
}

// The per-user verdict exists for outages; it must not outlive a revocation.
async function forgetVerifiedVerdict(env, discordId) {
  try {
    if (!env || !env.STORAGE) return false;
    const data = await r2GetJSON(env, ROLE_CHECK_R2_KEY, {});
    const id = String(discordId || "").trim();
    if (!data || !data[id]) return false;
    delete data[id];
    await r2PutJSON(env, ROLE_CHECK_R2_KEY, data);
    return true;
  } catch (e) {
    return false;
  }
}

async function revokeUserAccess(env, targets, options) {
  const opts = options || {};
  const ids = cleanRoleIdList(targets);
  const result = { revoked: [], kept: [], reason: String(opts.reason || "manual").slice(0, 32) };
  if (!ids.length || !env || !env.STORAGE) return result;
  const users = await readRevocationUsers(env);
  const now = Date.now();
  const source = String(opts.source || "vps-bot").slice(0, 40);
  // An explicit human decision (staff slash command, admin console) survives role
  // evidence even when the chosen reason would otherwise be healable. Departures and
  // bans are treated the same way, so rejoining and verifying cannot buy access back.
  const sticky = opts.sticky === true
    || STRONG_REVOKE_REASONS.has(result.reason)
    || STAFF_REVOKE_SOURCE_PATTERN.test(source)
    || (AUTO_STICKY_SOURCE_PATTERN.test(source) && opts.sticky !== false);
  for (const id of ids) {
    purgeRoleCaches(id);
    const existing = users[id];
    // Without an override an existing canonical block wins, so a background signal
    // can never rewrite (or downgrade) what is already recorded.
    if (existing && (isStickyRevocation(existing) || existing.reason === result.reason) && opts.override !== true) {
      result.kept.push(id);
      continue;
    }
    users[id] = {
      revoked_at: now,
      reason: result.reason,
      role_id: String(opts.roleId || "") || null,
      source,
      sticky: sticky || (existing ? isStickyRevocation(existing) : false),
      previous_reason: existing ? existing.reason : null,
    };
    result.revoked.push(id);
  }
  const keys = Object.keys(users);
  if (keys.length > REVOCATION_MAX_USERS) {
    keys.sort((a, b) => (Number(users[a].revoked_at) || 0) - (Number(users[b].revoked_at) || 0));
    for (const key of keys.slice(0, keys.length - REVOCATION_MAX_USERS)) {
      if (!isStickyRevocation(users[key])) delete users[key];
    }
  }
  await r2PutJSON(env, ROLE_REVOCATIONS_KEY, { version: 1, updated_at: now, users });
  revocationMemo = { at: now, users };
  if (opts.purgeAccess !== false && result.revoked.length) {
    await Promise.all(result.revoked.map(id => deleteDownloadPass(env, id)));
    await Promise.all(result.revoked.map(id => forgetVerifiedVerdict(env, id)));
  }
  return result;
}

async function restoreUserAccess(env, targets, options) {
  const opts = options || {};
  const ids = cleanRoleIdList(targets);
  const result = { restored: [], kept: [] };
  if (!ids.length || !env || !env.STORAGE) return result;
  const users = await readRevocationUsers(env);
  for (const id of ids) {
    const existing = users[id];
    purgeRoleCaches(id);
    if (!existing) continue;
    if (isStickyRevocation(existing) && !opts.force) {
      result.kept.push(id);
      continue;
    }
    delete users[id];
    result.restored.push(id);
  }
  if (result.restored.length) {
    const now = Date.now();
    await r2PutJSON(env, ROLE_REVOCATIONS_KEY, { version: 1, updated_at: now, users });
    revocationMemo = { at: now, users };
  }
  return result;
}

async function addUsersToRoleSnapshot(env, roleId, userIds) {
  try {
    if (!isValidRoleId(roleId) || !env || !env.STORAGE) return 0;
    let wanted = cleanRoleIdList(userIds);
    if (!wanted.length) return 0;
    // Adding a blocked member back would let the snapshot fast path admit them, so
    // the verified list refuses ids that carry a sticky block.
    if (roleId === VERIFIED_ROLE_ID) {
      const blocked = await readRevocationUsers(env).catch(() => ({}));
      wanted = wanted.filter(id => !isStickyRevocation(blocked[id]));
      if (!wanted.length) return 0;
    }
    const roles = await readRoleSnapshotRoles(env);
    const entry = roles[roleId];
    if (!entry || !Array.isArray(entry.ids)) return 0;
    const set = new Set(entry.ids.map(String));
    let added = 0;
    for (const id of wanted) {
      if (!set.has(id)) { set.add(id); added++; }
    }
    if (!added) return 0;
    entry.ids = Array.from(set).sort();
    await r2PutJSON(env, ROLE_SNAPSHOT_KEY, { version: 1, roles });
    roleSnapshotMemo.delete(roleId);
    return added;
  } catch (e) {
    return 0;
  }
}

async function removeUsersFromRoleSnapshot(env, roleId, userIds) {
  try {
    if (!isValidRoleId(roleId) || !env || !env.STORAGE) return 0;
    const drop = new Set(cleanRoleIdList(userIds));
    if (!drop.size) return 0;
    const roles = await readRoleSnapshotRoles(env);
    const entry = roles[roleId];
    if (!entry || !Array.isArray(entry.ids)) return 0;
    const before = entry.ids.map(String);
    const kept = before.filter(id => !drop.has(id));
    if (kept.length === before.length) return 0;
    const removedCount = before.length - kept.length;
    entry.ids = kept;
    await r2PutJSON(env, ROLE_SNAPSHOT_KEY, { version: 1, roles });
    roleSnapshotMemo.delete(roleId);
    return removedCount;
  } catch (e) {
    return 0;
  }
}

// One audit embed per revocation request. `details.title`, `details.description` and
// `details.color` let the caller name the situation (a departure, a ban lifted, a
// returning member) instead of every line reading the same.
async function postRevocationLogToDiscord(env, details) {
  try {
    const token = getSiteLogBotToken(env);
    if (!token) return false;
    const ids = cleanRoleIdList(details && details.ids).slice(0, 20);
    if (!ids.length) return false;
    const reason = String((details && details.reason) || "manual");
    const sticky = details && details.sticky === true;
    const embed = {
      title: (details && details.title) || "Download access revoked",
      description: (details && details.description)
        || (details && details.mentionText)
        || ids.map(id => `<@${id}> (\`${id}\`)`).join("\n"),
      color: (details && details.color) || 0xef4444,
      timestamp: new Date().toISOString(),
      fields: [
        { name: "Reason", value: REVOKE_REASON_LABELS[reason] || reason, inline: true },
        { name: "Members", value: String(details && details.count || ids.length), inline: true },
        { name: "Restore", value: sticky ? "Sticky • `/restore_access force:true`" : "Heals when the role returns", inline: true },
        ...(details && details.role_id ? [{ name: "Role", value: `<@&${details.role_id}>`, inline: true }] : []),
      ],
      footer: { text: "Zyrex access control • stored on the server" },
    };
    const response = await fetch(`${DISCORD_API}/channels/${SITE_LOG_CHANNEL_ID}/messages`, {
      method: "POST",
      headers: { Authorization: `Bot ${token}`, "Content-Type": "application/json" },
      body: JSON.stringify({ allowed_mentions: { parse: [] }, embeds: [embed] }),
      signal: AbortSignal.timeout(5000),
    });
    return response.ok;
  } catch (error) {
    console.error("Revocation log failed:", error?.message || String(error));
    return false;
  }
}

async function getCachedVerifiedRole(env, userId) {
  try {
    if (!env || !env.STORAGE) return undefined;
    const data = await r2GetJSON(env, ROLE_CHECK_R2_KEY, {});
    const entry = data && data[userId];
    if (entry && Date.now() < entry.expires) return entry.verified === true;
  } catch (e) {}
  return undefined;
}

async function setCachedVerifiedRole(env, userId) {
  try {
    if (!env || !env.STORAGE) return;
    const data = await r2GetJSON(env, ROLE_CHECK_R2_KEY, {});
    const prev = data[userId];
    if (prev && Date.now() < prev.expires) return; // already fresh
    const now = Date.now();
    data[userId] = { verified: true, expires: now + 6 * 60 * 60 * 1000 };
    for (const key of Object.keys(data)) {
      if (data[key] && now > data[key].expires) delete data[key];
    }
    await r2PutJSON(env, ROLE_CHECK_R2_KEY, data);
  } catch (e) {}
}

async function checkVerifiedRole(userId, env) {
  if (!userId) return false;
  
  // Revocations outrank everything else — a cached verdict, a snapshot hit and a
  // stored pass — so withdrawing the role or banning somebody takes effect on the
  // very next request.
  if (await isRevoked(env, userId) === true) {
    roleCheckCache.set(userId, { hasRole: false, expiry: Date.now() + 60000 });
    return false;
  }

  // Check cache
  const cached = roleCheckCache.get(userId);
  if (cached && Date.now() < cached.expiry) return cached.hasRole;

  const cacheVerdict = (hasRole, ttlMs) => {
    roleCheckCache.set(userId, { hasRole, expiry: Date.now() + ttlMs });
    if (hasRole) setCachedVerifiedRole(env, userId).catch(() => {});
  };

  // Fast path: the timer-refreshed snapshot is authoritative for who holds the
  // role, so a listed member is verified with no network round trip at all.
  const snapshot = await roleSnapshotVerdict(env, VERIFIED_ROLE_ID, userId);
  if (snapshot === true) {
    cacheVerdict(true, 300000);
    return true;
  }
  
  // The member record carries the role list, so this gate and the membership gate
  // share one lookup. A verified member is answered from the memo/R2 cache with no
  // network round trip, which is what keeps downloads instant.
  const known = await resolveGuildMember(env, userId).catch(() => null);
  if (known && known.in_guild === true && known.roles.includes(VERIFIED_ROLE_ID)) {
    cacheVerdict(true, 300000);
    addUserToRoleSnapshot(env, VERIFIED_ROLE_ID, userId).catch(() => {});
    return true;
  }

  // Anything short of a positive is confirmed live (one Discord call through the
  // worker's own bot) so a member who just verified is not held back by a cache.
  const live = await fetchGuildMemberLive(env, userId).catch(() => null);
  let verdict = known && known.source === "discord" ? known : null;
  if (live) {
    const record = { ...live, checked_at: Date.now() };
    await r2PutJSON(env, guildMemberKey(userId), record).catch(() => false);
    guildMemberMemo.set(String(userId), { record, expires: Date.now() + GUILD_MEMBER_MEMO_MS });
    verdict = live;
  }
  if (verdict) {
    const hasRole = verdict.in_guild === true && verdict.roles.includes(VERIFIED_ROLE_ID);
    cacheVerdict(hasRole, hasRole ? 300000 : 30000);
    if (hasRole) addUserToRoleSnapshot(env, VERIFIED_ROLE_ID, userId).catch(() => {});
    return hasRole;
  }

  // Live checks failed. A readable snapshot still knows exactly who holds the role,
  // so a miss there is a real denial rather than an outage.
  if (snapshot === false) {
    cacheVerdict(false, 60000);
    return false;
  }

  // No usable snapshot either. Serve the most recent persisted verdict so a brief
  // outage does not block verified members from downloading.
  const lastKnown = await getCachedVerifiedRole(env, userId);
  if (lastKnown === true) {
    roleCheckCache.set(userId, { hasRole: true, expiry: Date.now() + 60000 });
    return true;
  }
  return null;
}

// Persistent Discord user-profile cache (R2) so /api/discord-user never 503s
// during VPS/Discord outages. One object per user: a single shared file needed
// a read-modify-write that silently dropped entries whenever several profiles
// were cached at the same time.
const DISCORD_USER_R2_PREFIX = "database/discord_users/";
const DISCORD_USER_R2_KEY = "database/discord_users.json";
const DISCORD_USER_CACHE_MS = 7 * 24 * 60 * 60 * 1000;
// A stored profile is re-queried after this window so renames and avatar changes reach
// the site without waiting for the long cache to expire.
const DISCORD_USER_REFRESH_MS = 15 * 60 * 1000;

function discordUserKey(userId) {
  return `${DISCORD_USER_R2_PREFIX}${encodeURIComponent(String(userId || "").trim())}.json`;
}

async function getCachedDiscordUser(env, userId) {
  try {
    if (!env || !env.STORAGE || !userId) return null;
    const entry = await r2GetJSON(env, discordUserKey(userId), null);
    if (entry && entry.user && (!entry.expires || Date.now() < entry.expires)) return entry.user;
    const legacy = await r2GetJSON(env, DISCORD_USER_R2_KEY, {});
    const legacyEntry = legacy && legacy[userId];
    if (legacyEntry && Date.now() < legacyEntry.expires) return legacyEntry.user;
  } catch (e) {}
  return null;
}

// Returns the stored document (user + timestamps) so callers can tell a fresh profile
// from one that was cached days ago.
async function readDiscordUserEntry(env, userId) {
  try {
    if (!env || !env.STORAGE || !userId) return null;
    const entry = await r2GetJSON(env, discordUserKey(userId), null);
    if (entry && entry.user) return entry;
    const legacy = await r2GetJSON(env, DISCORD_USER_R2_KEY, {});
    const legacyEntry = legacy && legacy[userId];
    if (legacyEntry && legacyEntry.user) return legacyEntry;
  } catch (e) {}
  return null;
}

async function setCachedDiscordUser(env, userId, user) {
  try {
    if (!env || !env.STORAGE || !user || !userId) return;
    const now = Date.now();
    await r2PutJSON(env, discordUserKey(userId), {
      user,
      fetched_at: now,
      expires: now + DISCORD_USER_CACHE_MS,
    });
  } catch (e) {}
}

// Fetches a member's main Discord profile straight from Discord with the worker's own
// logger bot token; the bot VPS is only a fallback. Returns null when nobody answers.
async function fetchDiscordUserProfile(env, userId) {
  const id = String(userId || "").trim();
  if (!/^\d{17,20}$/.test(id)) return null;
  const token = getSiteLogBotToken(env);
  if (token) {
    try {
      const res = await fetch(`${DISCORD_API}/users/${id}`, {
        headers: { Authorization: `Bot ${token}` },
        signal: AbortSignal.timeout(1800),
      });
      if (res.ok) {
        const user = await res.json();
        if (user && typeof user === "object") {
          user.display_name = user.global_name || user.username;
          normalizeDiscordProfileAvatar(user, id);
          return user;
        }
      } else if (res.status !== 404) {
        console.warn("Discord user lookup failed:", res.status);
      } else {
        return null;
      }
    } catch (error) {
      console.warn("Discord user lookup error:", error?.message || String(error));
    }
  }
  try {
    const res = await fetch(`${BOT_API}/api/discord-user?userId=${encodeURIComponent(id)}`, {
      signal: AbortSignal.timeout(1500),
    });
    if (res.ok) {
      const data = await res.json();
      if (data && data.user) {
        normalizeDiscordProfileAvatar(data.user, id);
        return data.user;
      }
    }
  } catch (error) {
    console.warn("Bot API user lookup error:", error?.message || String(error));
  }
  return null;
}

// Every member should resolve to a real main profile: when nothing was ever stored on
// the server we fetch it now, and stored profiles older than the refresh window are
// re-queried so renames and new avatars land on the site on their own.
async function ensureDiscordUserProfile(env, userId) {
  const id = String(userId || "").trim();
  if (!/^\d{17,20}$/.test(id)) return null;
  const entry = await readDiscordUserEntry(env, id);
  const fetchedAt = Number(entry && entry.fetched_at) || 0;
  const stillFresh = Boolean(entry && entry.user) && fetchedAt > 0 && Date.now() - fetchedAt < DISCORD_USER_REFRESH_MS;
  if (stillFresh) return { user: entry.user, source: "discord-cache" };
  const live = await fetchDiscordUserProfile(env, id);
  if (live) {
    await setCachedDiscordUser(env, id, live);
    return { user: live, source: "discord-live" };
  }
  return entry && entry.user ? { user: entry.user, source: "discord-cache" } : null;
}

const GUILD_MEMBER_CACHE_PREFIX = "database/guild_members/";
// A member who leaves the guild loses their profile within this window.
const GUILD_MEMBER_TTL_MS = 30 * 60 * 1000;
const GUILD_MEMBER_MEMO_MS = 5 * 60 * 1000;
const guildMemberMemo = new Map();

function guildMemberKey(userId) {
  return `${GUILD_MEMBER_CACHE_PREFIX}${encodeURIComponent(String(userId || "").trim())}.json`;
}

// Profiles only exist while the member is in the Discord guild. One record per member
// carries the membership verdict *and* the role list, so verified/ad-free gates answer
// from the same read. Order: memo -> fresh cache -> live Discord (logger bot) -> bot VPS
// (last resort) -> stale cache. No VPS round trip sits in front of a download.
async function fetchGuildMemberLive(env, userId) {
  const id = String(userId || "").trim();
  const token = getSiteLogBotToken(env);
  const guildId = (env && env.GUILD_ID) || "1518954946110685184";
  if (!token) return null;
  try {
    const res = await fetch(`${DISCORD_API}/guilds/${encodeURIComponent(guildId)}/members/${id}`, {
      headers: { Authorization: `Bot ${token}` },
      signal: AbortSignal.timeout(2500),
    });
    if (res.ok) {
      const member = await res.json().catch(() => null);
      return {
        in_guild: true,
        roles: Array.isArray(member && member.roles) ? member.roles.map(String).slice(0, 60) : [],
        joined_at: String((member && member.joined_at) || ""),
        source: "discord",
      };
    }
    // Discord answers 404 for ids that are not members of the guild.
    if (res.status === 404) return { in_guild: false, roles: [], joined_at: "", source: "discord" };
    console.warn("Guild member lookup failed:", res.status);
    return null;
  } catch (error) {
    console.warn("Guild member lookup error:", error?.message || String(error));
    return null;
  }
}

async function readGuildMemberCache(env, userId) {
  try {
    const cached = await r2GetJSON(env, guildMemberKey(userId), null);
    if (!cached || typeof cached !== "object") return null;
    return {
      in_guild: cached.in_guild === true,
      roles: Array.isArray(cached.roles) ? cached.roles.map(String) : [],
      joined_at: String(cached.joined_at || ""),
      checked_at: Number(cached.checked_at) || 0,
      source: "cache",
    };
  } catch (_) {
    return null;
  }
}

async function resolveGuildMember(env, userId, options = {}) {
  const id = String(userId || "").trim();
  if (!/^\d{17,20}$/.test(id)) return null;
  const maxAgeMs = Number(options.maxAgeMs) > 0 ? Number(options.maxAgeMs) : GUILD_MEMBER_TTL_MS;

  const memo = guildMemberMemo.get(id);
  if (memo && Date.now() < memo.expires) return memo.record;

  const remember = record => {
    guildMemberMemo.set(id, { record, expires: Date.now() + Math.min(GUILD_MEMBER_MEMO_MS, maxAgeMs) });
    return record;
  };

  const cached = await readGuildMemberCache(env, id);
  if (cached && cached.checked_at && Date.now() - cached.checked_at < maxAgeMs) {
    return remember(cached);
  }

  const live = await fetchGuildMemberLive(env, id);
  if (live) {
    const record = { ...live, checked_at: Date.now() };
    await r2PutJSON(env, guildMemberKey(id), record).catch(() => false);
    return remember(record);
  }

  // Discord unreachable: the bot VPS is a last resort, then whatever the cache knows.
  try {
    const res = await fetch(`${BOT_API}/api/guild/check-membership?userId=${encodeURIComponent(id)}`, {
      signal: AbortSignal.timeout(2500),
    });
    if (res.ok) {
      const data = await res.json().catch(() => null);
      if (data && typeof data.in_guild === "boolean") {
        const record = {
          in_guild: data.in_guild,
          roles: Array.isArray(data.roles) ? data.roles.map(String).slice(0, 60) : [],
          joined_at: "",
          checked_at: Date.now(),
          source: "vps",
        };
        await r2PutJSON(env, guildMemberKey(id), record).catch(() => false);
        return remember(record);
      }
    }
  } catch (error) {
    console.warn("Guild membership check failed:", id, error?.message || String(error));
  }

  if (cached) return remember({ ...cached, source: "cache-stale" });
  return null;
}

// true = in the guild, false = definitively not, null = could not be checked.
async function checkGuildMembership(env, userId) {
  const id = String(userId || "").trim();
  if (!/^\d{17,20}$/.test(id)) return false;
  const record = await resolveGuildMember(env, id);
  return record ? record.in_guild === true : null;
}

// The guild-member lookup is the only place that knows a real "member since".
async function readGuildJoinedAt(env, discordId) {
  try {
    const entry = await r2GetJSON(env, guildMemberKey(discordId), null);
    return String((entry && entry.joined_at) || "");
  } catch (_) {
    return "";
  }
}

// A profile only exists for members confirmed in the Discord guild. An unknown
// verdict is not good enough, and the membership is re-confirmed at least every two
// minutes so a member who leaves loses their page quickly.
async function isGuildProfileMissing(env, userId) {
  const id = String(userId || "").trim();
  // The official Zyrex account is the site itself, so it never loses its page.
  if (await isOfficialProfileId(env, id)) return false;
  const record = await resolveGuildMember(env, id, { maxAgeMs: 2 * 60 * 1000 }).catch(() => null);
  if (!record) return true;
  return record.in_guild !== true;
}

// Cheap variant for public lists: rows whose cached record says the member left are
// dropped, while unknown records are left alone so a cold cache cannot hide a member.
async function dropKnownNonMembers(env, rows, idOf = row => row && row.id) {
  const verdicts = await Promise.all((rows || []).map(async row => {
    const record = await readGuildMemberCache(env, idOf(row)).catch(() => null);
    if (!record) return true;
    return record.in_guild !== false;
  }));
  return (rows || []).filter((row, index) => verdicts[index]);
}

// Keeps only the rows whose member is confirmed in the guild.
async function filterGuildMembers(env, rows, idOf = row => row && row.id) {
  const verdicts = await Promise.all((rows || []).map(row => checkGuildMembership(env, idOf(row))));
  return (rows || []).filter((row, index) => verdicts[index] === true);
}

// Only this Discord role grants ad-free downloads.
const AD_FREE_ROLE_IDS = ["1535219942553690154"];

// How long an offer-completed download pass stays valid. Changing this value
// also requires resetting existing passes (see /api/admin/access/reset), because
// stored passes keep the expiry they were granted with.
const RESOURCE_ACCESS_DURATION_DAYS = 7;
const RESOURCE_ACCESS_DURATION_MS = RESOURCE_ACCESS_DURATION_DAYS * 24 * 60 * 60 * 1000;
const RESOURCE_ACCESS_LABEL = `${RESOURCE_ACCESS_DURATION_DAYS}-Day`;
const RESOURCE_ACCESS_PATH = "download-access/";
const adFreeRoleCache = new Map();

async function checkAdFreeRole(userId, env) {
  if (!userId) return false;
  
  // Check cache
  const cached = adFreeRoleCache.get(userId);
  if (cached && Date.now() < cached.expiry) return cached.hasRole;

  if (await isRevoked(env, userId) === true) {
    adFreeRoleCache.set(userId, { hasRole: false, expiry: Date.now() + 600000 });
    return false;
  }

  // Snapshot first, exactly like the verified check: it keeps live lookups off
  // the access page, which is the common case because few members are ad-free.
  let answeredBySnapshot = 0;
  for (const roleId of AD_FREE_ROLE_IDS) {
    const snapshot = await roleSnapshotVerdict(env, roleId, userId);
    if (snapshot === true) {
      adFreeRoleCache.set(userId, { hasRole: true, expiry: Date.now() + 300000 });
      return true;
    }
    if (snapshot === false) answeredBySnapshot++;
  }
  if (answeredBySnapshot === AD_FREE_ROLE_IDS.length) {
    adFreeRoleCache.set(userId, { hasRole: false, expiry: Date.now() + 300000 });
    return false;
  }
  
  // Same member record as the verified gate: the role list decides the perk, so a
  // cached positive answers without any network call.
  const known = await resolveGuildMember(env, userId).catch(() => null);
  const hasAdFree = record => Boolean(record && record.in_guild === true &&
    record.roles.some(roleId => AD_FREE_ROLE_IDS.includes(roleId)));
  if (known && hasAdFree(known)) {
    adFreeRoleCache.set(userId, { hasRole: true, expiry: Date.now() + 300000 });
    AD_FREE_ROLE_IDS.forEach(roleId => addUserToRoleSnapshot(env, roleId, userId).catch(() => {}));
    return true;
  }

  const live = await fetchGuildMemberLive(env, userId).catch(() => null);
  if (live) {
    const record = { ...live, checked_at: Date.now() };
    await r2PutJSON(env, guildMemberKey(userId), record).catch(() => false);
    guildMemberMemo.set(String(userId), { record, expires: Date.now() + GUILD_MEMBER_MEMO_MS });
    const granted = hasAdFree(live);
    adFreeRoleCache.set(userId, { hasRole: granted, expiry: Date.now() + (granted ? 300000 : 60000) });
    if (granted) AD_FREE_ROLE_IDS.forEach(roleId => addUserToRoleSnapshot(env, roleId, userId).catch(() => {}));
    return granted;
  }

  // Discord unreachable: never revoke a perk that a cached record still grants.
  if (known && hasAdFree(known)) {
    adFreeRoleCache.set(userId, { hasRole: true, expiry: Date.now() + 60000 });
    return true;
  }
  adFreeRoleCache.set(userId, { hasRole: false, expiry: Date.now() + 15000 });
  return false;
}

