async function createShrinkEarnLink(env, destinationUrl) {
  const apiToken = (env.SHRINKEARN_API_TOKEN || "").trim();
  if (!apiToken) throw new Error("ShrinkEarn API token is not configured");

  const apiUrl = new URL("https://shrinkearn.com/api");
  apiUrl.searchParams.set("api", apiToken);
  apiUrl.searchParams.set("url", destinationUrl);

  const resp = await fetch(apiUrl.toString(), {
    headers: {
      "Accept": "application/json, text/plain, */*",
      "User-Agent": "Mozilla/5.0 (compatible; ZyrexDownload/1.0)",
    },
    cf: { cacheTtl: 0 },
  });
  const text = await resp.text();
  if (!resp.ok) {
    throw new Error("ShrinkEarn API returned " + resp.status + ": " + text.slice(0, 160));
  }

  let data = null;
  try {
    data = JSON.parse(text);
  } catch {
    const plainUrl = text.trim().replace(/^"+|"+$/g, "");
    if (/^https?:\/\//i.test(plainUrl)) return plainUrl;
    throw new Error("ShrinkEarn API returned an invalid response: " + text.slice(0, 160));
  }

  if (data.status === "error") throw new Error(data.message || "ShrinkEarn could not create the link");

  const shortUrl = String(data.shortenedUrl || data.short_url || data.shortUrl || data.url || "").replace(/^"+|"+$/g, "");
  if (!/^https?:\/\//i.test(shortUrl)) throw new Error("ShrinkEarn did not return a short URL");
  return shortUrl;
}

function buildTokenLandingUrl(token, source = "access", language = "", theme = "") {
  const landingUrl = new URL("https://dl.zyrexediting.xyz/");
  landingUrl.searchParams.set("token", token);
  landingUrl.searchParams.set("src", source);
  if (/^(en|tr|es|pt|ru|ar|ko|zh)$/.test(String(language || "").toLowerCase())) {
    landingUrl.searchParams.set("lang", String(language).toLowerCase());
  }
  if (["zyrex", "dark", "light"].includes(String(theme || "").toLowerCase())) {
    landingUrl.searchParams.set("theme", String(theme).toLowerCase());
  }
  return landingUrl.toString();
}

// Sessions are HMAC-signed. The cookie used to be plain base64 JSON, so anyone could
// mint an admin session by editing their own cookie.
const sessionMemo = new WeakMap();

function sessionSigningSecret(env) {
  const secret = env?.SESSION_SECRET || env?.DOWNLOAD_TOKEN_SECRET || env?.ZYREX_MASTER_KEY || ZYREX_MASTER_KEY;
  return String(secret || "").trim();
}

async function signSessionPart(part, env) {
  const secret = sessionSigningSecret(env);
  if (!secret) return null;
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const signature = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(part));
  return base64UrlEncode(new Uint8Array(signature));
}

function readSessionPayload(part) {
  try {
    let base64 = String(part || "").replace(/-/g, "+").replace(/_/g, "/");
    while (base64.length % 4) base64 += "=";
    const decoded = atob(base64);
    const bytes = Uint8Array.from(decoded, c => c.charCodeAt(0));
    return JSON.parse(new TextDecoder().decode(bytes));
  } catch {
    return null;
  }
}

async function decodeSessionCookie(raw, env) {
  const parts = String(raw || "").split(".");
  if (parts.length !== 2 || !parts[0] || !parts[1]) return null;
  const expected = await signSessionPart(parts[0], env);
  if (!expected || expected !== parts[1]) return null;
  const session = readSessionPayload(parts[0]);
  if (!session || !session.userId) return null;
  if (session.expires && session.expires < Date.now()) return null;
  return session;
}

// Verified once per request (HMAC is async) and memoised, so the 80+ route handlers can
// keep reading it synchronously through parseSession(). Unverified requests get null.
async function resolveSession(request, env) {
  if (sessionMemo.has(request)) return sessionMemo.get(request);
  const cookie = request.headers.get("Cookie") || "";
  // A browser can hold several zyrex_session cookies (stale legacy ones had no signature),
  // so every candidate is tried until one verifies instead of trusting the first.
  const candidates = Array.from(cookie.matchAll(/zyrex_session=([^;]+)/g)).map(match => match[1]);
  let session = null;
  for (const candidate of candidates) {
    let decoded = candidate;
    try { decoded = decodeURIComponent(candidate); } catch (_) {}
    session = await decodeSessionCookie(decoded, env);
    if (session) break;
  }
  sessionMemo.set(request, session);
  return session;
}

function parseSession(cookieOrReq, req = null) {
  const target = req || (cookieOrReq && typeof cookieOrReq === "object" && typeof cookieOrReq.headers?.get === "function" ? cookieOrReq : null);
  if (target && sessionMemo.has(target)) return sessionMemo.get(target);
  return null;
}

async function setCookie(data, maxAge = 86400, env = null) {
  const payload = { ...data, expires: Date.now() + maxAge * 1000 };
  const bytes = new TextEncoder().encode(JSON.stringify(payload));
  const part = base64UrlEncode(bytes);
  const signature = await signSessionPart(part, env);
  if (!signature) throw new Error("SESSION_SECRET is not configured");
  return `zyrex_session=${part}.${signature}; Domain=.zyrexediting.xyz; Path=/; HttpOnly; SameSite=Lax; Max-Age=${maxAge}; Secure`;
}

function clearCookie() {
  return "zyrex_session=; Domain=.zyrexediting.xyz; Path=/; HttpOnly; SameSite=Lax; Max-Age=0; Expires=Thu, 01 Jan 1970 00:00:00 GMT; Secure";
}

async function r2List(env, prefix, useProd = false) {
  const bucket = useProd ? (env.STORAGE_PROD || env.STORAGE) : env.STORAGE;
  const objects = [];
  let cursor;
  do {
    const resp = await bucket.list({ prefix, limit: 500, cursor });
    for (const obj of resp.objects) {
      objects.push({ key: obj.key, size: obj.size, uploaded: obj.uploaded });
    }
    cursor = resp.cursor;
  } while (cursor);
  return objects;
}

async function r2Get(env, key, useProd = false) {
  const bucket = useProd ? (env.STORAGE_PROD || env.STORAGE) : env.STORAGE;
  const obj = await bucket.get(key);
  if (!obj) return null;
  return obj;
}

function normalizeR2Prefix(value) {
  let prefix = String(value || "").replace(/\\/g, "/").trim();
  prefix = prefix.replace(/^\/+/, "");
  if (prefix && !prefix.endsWith("/")) prefix += "/";
  return prefix;
}

function installerSecretMatches(provided, expected) {
  const a = String(provided || "");
  const b = String(expected || "");
  if (!a || !b || a.length !== b.length) return false;
  let mismatch = 0;
  for (let i = 0; i < a.length; i++) mismatch |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return mismatch === 0;
}

async function deriveInstallerPayloadKey(productId, releaseId, env) {
  const secret = String(env.SESSION_SECRET || "").trim();
  if (!secret) throw new Error("Session signing is not configured");
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const signed = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(`zyrex-installer-v1:${productId}:${releaseId}`));
  return base64UrlEncode(new Uint8Array(signed));
}

function installerDevicePath(deviceCode) {
  return `installer-auth/${deviceCode}.json`;
}

// The installer carries its own copy of the pack, so the Worker has to enforce the
// same pair of gates the site enforces before it hands anything over: the verified
// Discord role *and* an active download pass. The payload key is the only thing that
// can open the encrypted .ffx bundle, so refusing it here means a member without both
// cannot read a single preset even with the .exe or .dmg already in hand.
const INSTALLER_ACCESS_ALLOW_TTL_MS = 20000;
const installerAccessMemo = new Map();

async function computeInstallerAccess(env, userId) {
  if (await isRevoked(env, userId) === true) {
    return { allowed: false, verified: false, pass: false, code: "ACCESS_REVOKED", error: ACCESS_REVOKED_MESSAGE };
  }
  const verified = await checkVerifiedRole(userId, env);
  if (verified === null) {
    // Failing closed keeps an outage from turning into an open door; retrying works.
    return { allowed: false, verified: null, pass: null, code: "ROLE_CHECK_UNAVAILABLE", error: "We could not read your Discord roles right now. Please retry in a moment." };
  }
  if (!verified) {
    return { allowed: false, verified: false, pass: null, code: "NOT_VERIFIED", error: "You need the Verified role in the Zyrex Discord server to install presets." };
  }
  // The ad-free role is a permanent pass, exactly like the site's download flow.
  const pass = (await checkAdFreeRole(userId, env)) || await hasActiveDownloadAccess(env, userId);
  if (!pass) {
    return { allowed: false, verified: true, pass: false, code: "ACCESS_REQUIRED", error: `Your account is verified but has no active download pass. Unlock ${RESOURCE_ACCESS_LABEL.toLowerCase()} access with one free offer on the Access page.` };
  }
  return { allowed: true, verified: true, pass: true, code: "OK", error: "" };
}

// A pack can be a hundred presets, and each traced file asks for the same verdict, so an
// allowed answer is reused for a few seconds. Denials are never cached: a member who has
// just unlocked access must not be held back by a stale refusal.
async function installerAccess(env, userId, { reuse = true } = {}) {
  const id = String(userId || "").trim();
  if (!id) return { allowed: false, verified: false, pass: false, code: "NOT_AUTHORIZED", error: "Sign in with Discord to access these presets." };
  if (reuse) {
    const memo = installerAccessMemo.get(id);
    if (memo && Date.now() < memo.expires) {
      if (await isRevoked(env, id) !== true) return memo.verdict;
      installerAccessMemo.delete(id);
    }
  }
  const verdict = await computeInstallerAccess(env, id);
  if (verdict.allowed) {
    if (installerAccessMemo.size > 4096) installerAccessMemo.clear();
    installerAccessMemo.set(id, { verdict, expires: Date.now() + INSTALLER_ACCESS_ALLOW_TTL_MS });
  } else {
    installerAccessMemo.delete(id);
  }
  return verdict;
}

function installerAccessDenied(verdict) {
  const status = verdict.code === "NOT_AUTHORIZED" ? 401 : verdict.code === "ROLE_CHECK_UNAVAILABLE" ? 503 : 403;
  return json({
    success: false,
    code: verdict.code,
    error: verdict.error,
    verified: verdict.verified,
    pass: verdict.pass,
    unlock_url: "/access",
  }, status, { "Cache-Control": "no-store" });
}

async function readInstallerDevice(env, deviceCode) {
  const object = await env.STORAGE.get(installerDevicePath(deviceCode));
  if (!object) return null;
  try { return await object.json(); } catch (_) { return null; }
}

async function cleanupInstallerAuthRecords(env) {
  let cursor;
  let removed = 0;
  for (let page = 0; page < 3; page++) {
    const listed = await env.STORAGE.list({ prefix: "installer-auth/", limit: 500, cursor });
    for (const item of listed.objects || []) {
      try {
        const object = await env.STORAGE.get(item.key);
        const state = object ? await object.json() : null;
        if (!state || Date.now() - Number(state.createdAt || 0) > 10 * 60 * 1000) {
          await env.STORAGE.delete(item.key);
          removed++;
        }
      } catch (_) {}
    }
    if (!listed.truncated || !listed.cursor) break;
    cursor = listed.cursor;
  }
  return removed;
}

async function handleInstallerAuthStart(request, env, url) {
  let body;
  try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid request" }, 400); }
  const deviceCode = String(body?.device_code || "").trim();
  const productId = String(body?.product_id || "").trim();
  if (!/^[A-Za-z0-9_-]{40,80}$/.test(deviceCode) || !/^[A-Za-z0-9_-]{1,100}$/.test(productId)) {
    return json({ success: false, error: "Invalid device authorization request" }, 400);
  }
  const product = await dbGetProduct(env, productId).catch(() => null);
  if (!product || String(product.type || "preset").toLowerCase() !== "preset") return json({ success: false, error: "Preset not found" }, 404);
  const releaseId = String(body?.release_id || "").trim();
  if (!/^[A-Za-z0-9_-]{1,100}$/.test(releaseId)) return json({ success: false, error: "Invalid installer release" }, 400);
  await env.STORAGE.put(installerDevicePath(deviceCode), JSON.stringify({ productId, releaseId, createdAt: Date.now(), status: "pending" }), { httpMetadata: { contentType: "application/json" } });
  const callback = `/api/installer/auth/complete?device_code=${encodeURIComponent(deviceCode)}`;
  const login = new URL("/api/login", url.origin);
  login.searchParams.set("redirect", callback);
  return json({ success: true, authorization_url: login.toString(), expires_in: 600 }, 200, { "Cache-Control": "no-store" });
}

async function handleInstallerAuthComplete(request, env, url) {
  const deviceCode = String(url.searchParams.get("device_code") || "").trim();
  if (!/^[A-Za-z0-9_-]{40,80}$/.test(deviceCode)) return new Response("Invalid installer sign-in request.", { status: 400 });
  const session = parseSession(request.headers.get("Cookie"), request);
  if (!session?.userId) return redirect(`/api/login?redirect=${encodeURIComponent(url.pathname + url.search)}`);
  const device = await readInstallerDevice(env, deviceCode);
  if (!device || Date.now() - Number(device.createdAt || 0) > 10 * 60 * 1000) return new Response("This installer sign-in request expired. Return to the app and try again.", { status: 410, headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" } });
  if (device.status === "authorized") return new Response("You are signed in. Return to the Zyrex Effects Installer.", { status: 200, headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" } });
  const grant = { userId: String(session.userId), username: String(session.username || ""), installerProductId: device.productId, installerReleaseId: device.releaseId };
  const cookie = await setCookie(grant, 3600, env);
  const accessToken = cookie.slice("zyrex_session=".length).split(";")[0];
  await env.STORAGE.put(installerDevicePath(deviceCode), JSON.stringify({ ...device, status: "authorized", accessToken, userId: grant.userId, username: grant.username, authorizedAt: Date.now() }), { httpMetadata: { contentType: "application/json" } });
  return new Response("<html><meta charset=utf-8><title>Zyrex installer sign-in</title><body style='font:16px system-ui;background:#100b0e;color:white;padding:48px'><h1>Signed in</h1><p>Return to the Zyrex Effects Installer to continue.</p></body></html>", { status: 200, headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } });
}

async function handleInstallerAuthPoll(url, env) {
  const deviceCode = String(url.searchParams.get("device_code") || "").trim();
  if (!/^[A-Za-z0-9_-]{40,80}$/.test(deviceCode)) return json({ success: false, error: "Invalid device code" }, 400);
  const device = await readInstallerDevice(env, deviceCode);
  if (!device) return json({ success: false, error: "Sign-in request expired" }, 410, { "Cache-Control": "no-store" });
  if (Date.now() - Number(device.createdAt || 0) > 10 * 60 * 1000) {
    await env.STORAGE.delete(installerDevicePath(deviceCode));
    return json({ success: false, error: "Sign-in request expired" }, 410, { "Cache-Control": "no-store" });
  }
  if (device.status !== "authorized" || !device.accessToken) return json({ success: true, pending: true }, 202, { "Cache-Control": "no-store" });
  // The verdict travels with the sign-in response so the app can explain the
  // requirement before it tries to unlock anything.
  const access = await installerAccess(env, device.userId, { reuse: false });
  return json({ success: true, pending: false, access_token: device.accessToken, user: { id: device.userId, username: device.username }, access: { ...access, unlock_url: "/access" } }, 200, { "Cache-Control": "no-store" });
}

async function installerGrantFromRequest(request, env, productId, releaseId) {
  const authorization = String(request.headers.get("Authorization") || "");
  const token = authorization.replace(/^Bearer\s+/i, "").trim();
  if (!token || token === String(env.FFX_RELEASE_SOURCE_TOKEN || "").trim()) return null;
  const grant = await decodeSessionCookie(token, env);
  if (!grant || String(grant.installerProductId || "") !== productId || String(grant.installerReleaseId || "") !== releaseId) return null;
  return grant;
}

async function handleInstallerKey(request, url, env) {
  const productId = String(url.searchParams.get("id") || "").trim();
  const releaseId = String(url.searchParams.get("release_id") || "").trim();
  if (!/^[A-Za-z0-9_-]{1,100}$/.test(productId) || !/^[A-Za-z0-9_-]{1,100}$/.test(releaseId)) return json({ success: false, error: "Invalid installer request" }, 400);
  const grant = await installerGrantFromRequest(request, env, productId, releaseId);
  if (!grant) return json({ success: false, error: "Sign in with Discord to access these presets", code: "NOT_AUTHORIZED" }, 401, { "Cache-Control": "no-store" });
  const access = await installerAccess(env, grant.userId);
  if (!access.allowed) return installerAccessDenied(access);
  const key = await deriveInstallerPayloadKey(productId, releaseId, env);
  return json({ success: true, key }, 200, { "Cache-Control": "no-store" });
}

// Lets the app re-check a member who has just unlocked access without making them
// sign in again.
async function handleInstallerAccess(request, url, env) {
  const productId = String(url.searchParams.get("id") || "").trim();
  const releaseId = String(url.searchParams.get("release_id") || "").trim();
  if (!/^[A-Za-z0-9_-]{1,100}$/.test(productId) || !/^[A-Za-z0-9_-]{1,100}$/.test(releaseId)) return json({ success: false, error: "Invalid installer request" }, 400, { "Cache-Control": "no-store" });
  const grant = await installerGrantFromRequest(request, env, productId, releaseId);
  if (!grant) return json({ success: false, error: "Sign in with Discord to access these presets", code: "NOT_AUTHORIZED" }, 401, { "Cache-Control": "no-store" });
  const access = await installerAccess(env, grant.userId, { reuse: false });
  return json({ success: true, user: { id: grant.userId, username: grant.username }, access: { ...access, unlock_url: "/access" } }, 200, { "Cache-Control": "no-store" });
}

async function handleInstallerTrace(request, url, env) {
  const productId = String(url.searchParams.get("id") || "").trim();
  const releaseId = String(url.searchParams.get("release_id") || "").trim();
  const fileName = String(url.searchParams.get("name") || "preset.ffx").replace(/\\/g, "/");
  if (!/^[A-Za-z0-9_-]{1,100}$/.test(productId) || !/^[A-Za-z0-9_-]{1,100}$/.test(releaseId) || !fileName.toLowerCase().endsWith(".ffx") || fileName.split("/").some(part => !part || part === "." || part === "..")) return json({ success: false, error: "Invalid preset trace request" }, 400, { "Cache-Control": "no-store" });
  const grant = await installerGrantFromRequest(request, env, productId, releaseId);
  if (!grant) return json({ success: false, error: "Sign in with Discord to access these presets", code: "NOT_AUTHORIZED" }, 401, { "Cache-Control": "no-store" });
  const access = await installerAccess(env, grant.userId);
  if (!access.allowed) return installerAccessDenied(access);
  const length = Number(request.headers.get("Content-Length") || 0);
  if (length > TRACE_MAX_FILE_BYTES) return json({ success: false, error: "Preset exceeds the safe tracing size limit" }, 413, { "Cache-Control": "no-store" });
  const original = new Uint8Array(await request.arrayBuffer());
  if (original.length > TRACE_MAX_FILE_BYTES) return json({ success: false, error: "Preset exceeds the safe tracing size limit" }, 413, { "Cache-Control": "no-store" });
  const downloadedAt = new Date().toISOString();
  const marked = traceDownloadBytes(original, fileName, grant.userId, grant.username, downloadedAt);
  if (!marked) return json({ success: false, error: "This preset cannot be safely traced and was not released." }, 422, { "Cache-Control": "no-store" });
  return new Response(marked, { status: 200, headers: { "Content-Type": "application/octet-stream", "Cache-Control": "no-store", "X-Zyrex-Downloaded-At": downloadedAt, "X-Content-Type-Options": "nosniff" } });
}

const INSTALLER_PLATFORMS = { windows: ".exe", macos: ".dmg" };
const INSTALLER_MAX_BYTES = 96 * 1024 * 1024;

function installerPlatformExtension(platform) {
  return INSTALLER_PLATFORMS[String(platform || "").trim().toLowerCase()] || "";
}

function installerStoragePrefix(productId, platform) {
  return `installers/${productId}/${String(platform || "").trim().toLowerCase()}/`;
}

function safeInstallerLabel(value, fallback) {
  const cleaned = String(value || "")
    .replace(/[\u200b-\u200f\u2060\ufeff]/g, "")
    .replace(/[<>:"/\\|?*\u0000-\u001f\u007f-\u009f]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/^\.+|\.+$/g, "")
    .trim()
    .slice(0, 96);
  return cleaned || fallback;
}

async function installerObjectFor(bucket, prefix, platform) {
  const extension = installerPlatformExtension(platform);
  if (!extension || !prefix) return null;
  const listing = await bucket.list({ prefix, limit: 1000 });
  const object = (listing.objects || []).find(item => item.key.toLowerCase().endsWith(extension));
  if (!object) return null;
  return { ...object, extension, filename: object.key.slice(object.key.lastIndexOf("/") + 1) };
}

// GitHub Actions uploads the finished .exe/.dmg next to the leak's own files with the
// shared build token, so the existing ZIP packer ships it together with the Zyrex
// watermark files and no R2 credentials ever leave Cloudflare.
async function handleInstallerPublish(request, url, env) {
  if (request.method !== "POST") return json({ success: false, error: "Method not allowed" }, 405, { "Cache-Control": "no-store" });
  const expected = String(env.FFX_RELEASE_SOURCE_TOKEN || "").trim();
  const provided = String(request.headers.get("Authorization") || "").replace(/^Bearer\s+/i, "").trim();
  if (!expected || !installerSecretMatches(provided, expected)) return json({ success: false, error: "Unauthorized" }, 401, { "Cache-Control": "no-store" });
  const productId = String(url.searchParams.get("id") || "").trim();
  const platform = String(url.searchParams.get("platform") || "").trim().toLowerCase();
  const releaseId = String(url.searchParams.get("release_id") || "").trim();
  const extension = installerPlatformExtension(platform);
  if (!/^[A-Za-z0-9_-]{1,100}$/.test(productId) || !extension || !/^[A-Za-z0-9_-]{1,100}$/.test(releaseId)) {
    return json({ success: false, error: "Invalid installer upload" }, 400, { "Cache-Control": "no-store" });
  }
  const declared = Number(request.headers.get("Content-Length") || 0);
  if (!declared || declared > INSTALLER_MAX_BYTES) {
    return json({ success: false, error: "Installer size is not supported" }, 413, { "Cache-Control": "no-store" });
  }
  const product = await dbGetProduct(env, productId).catch(() => null);
  if (!product || String(product.type || "preset").toLowerCase() !== "preset") {
    return json({ success: false, error: "Preset not found" }, 404, { "Cache-Control": "no-store" });
  }
  const bucket = env.STORAGE_PROD || env.STORAGE;
  const prefix = normalizeR2Prefix(product.file_path);
  if (!bucket || !prefix) return json({ success: false, error: "Production storage is unavailable" }, 503, { "Cache-Control": "no-store" });
  const requested = String(url.searchParams.get("name") || request.headers.get("X-Zyrex-Filename") || "").replace(/\.(exe|dmg)$/i, "");
  const filename = safeInstallerLabel(requested, safeInstallerLabel(product.name, productId)) + extension;
  const key = prefix + filename;
  const uploadedAt = new Date().toISOString();
  await bucket.put(key, request.body, {
    httpMetadata: { contentType: "application/octet-stream" },
    customMetadata: { product_id: productId, platform, release_id: releaseId, uploaded_at: uploadedAt },
  });
  // Only one build per platform may live beside the leak's files.
  const listing = await bucket.list({ prefix, limit: 1000 });
  for (const object of listing.objects || []) {
    const lower = object.key.toLowerCase();
    if (object.key !== key && lower.endsWith(extension) && !isWatermarkName(object.key)) {
      await bucket.delete(object.key).catch(() => {});
    }
  }
  // Older releases stored installers under a shared prefix; drop those copies.
  const legacyPrefix = installerStoragePrefix(productId, platform);
  const legacy = await bucket.list({ prefix: legacyPrefix, limit: 50 });
  for (const object of legacy.objects || []) await bucket.delete(object.key).catch(() => {});
  return json({ success: true, key, filename, size: declared, release_id: releaseId, uploaded_at: uploadedAt }, 200, { "Cache-Control": "no-store" });
}

// One-off: releases published before installers moved beside the leak files live under
// installers/<id>/<platform>/; copy them into the leak folder and drop the legacy copy.
async function handleInstallerMigrate(request, url, env) {
  if (request.method !== "POST") return json({ success: false, error: "Method not allowed" }, 405, { "Cache-Control": "no-store" });
  const expected = String(env.FFX_RELEASE_SOURCE_TOKEN || "").trim();
  const provided = String(request.headers.get("Authorization") || "").replace(/^Bearer\s+/i, "").trim();
  if (!expected || !installerSecretMatches(provided, expected)) return json({ success: false, error: "Unauthorized" }, 401, { "Cache-Control": "no-store" });
  const productId = String(url.searchParams.get("id") || "").trim();
  if (!/^[A-Za-z0-9_-]{1,100}$/.test(productId)) return json({ success: false, error: "Invalid leak ID" }, 400, { "Cache-Control": "no-store" });
  const product = await dbGetProduct(env, productId).catch(() => null);
  const prefix = normalizeR2Prefix(product?.file_path);
  const bucket = env.STORAGE_PROD || env.STORAGE;
  if (!product || !bucket || !prefix) return json({ success: false, error: "Leak storage is unavailable" }, 404, { "Cache-Control": "no-store" });
  const moved = [];
  for (const platform of Object.keys(INSTALLER_PLATFORMS)) {
    const extension = INSTALLER_PLATFORMS[platform];
    const legacy = await bucket.list({ prefix: installerStoragePrefix(productId, platform), limit: 20 });
    const copies = (legacy.objects || []).filter(object => object.key.toLowerCase().endsWith(extension));
    if (!copies.length) continue;
    let newest = "";
    for (const object of copies) {
      const filename = object.key.slice(object.key.lastIndexOf("/") + 1);
      const stored = await bucket.get(object.key);
      if (!stored) continue;
      await bucket.put(prefix + filename, stored.body, {
        httpMetadata: { contentType: "application/octet-stream" },
        customMetadata: { product_id: productId, platform, migrated_from: object.key },
      });
      await bucket.delete(object.key).catch(() => {});
      newest = filename;
      moved.push(filename);
    }
    // Drop the older build of this platform that is still sitting in the leak folder.
    if (newest) {
      const listing = await bucket.list({ prefix, limit: 1000 });
      for (const object of listing.objects || []) {
        if (object.key === prefix + newest) continue;
        if (object.key.toLowerCase().endsWith(extension) && !isWatermarkName(object.key)) {
          await bucket.delete(object.key).catch(() => {});
        }
      }
    }
  }
  return json({ success: true, product_id: productId, moved }, 200, { "Cache-Control": "no-store" });
}

// Production folders keep everything except the FFX source, which is relocated to the
// _source_ffx/ backup the build endpoint already reads. mode=restore undoes an earlier
// relocation for non-FFX files (project files, tutorials, images).
async function handleInstallerRelocateSource(request, url, env) {
  if (request.method !== "POST") return json({ success: false, error: "Method not allowed" }, 405, { "Cache-Control": "no-store" });
  const expected = String(env.FFX_RELEASE_SOURCE_TOKEN || "").trim();
  const provided = String(request.headers.get("Authorization") || "").replace(/^Bearer\s+/i, "").trim();
  if (!expected || !installerSecretMatches(provided, expected)) return json({ success: false, error: "Unauthorized" }, 401, { "Cache-Control": "no-store" });
  const productId = String(url.searchParams.get("id") || "").trim();
  const mode = String(url.searchParams.get("mode") || "move").trim().toLowerCase();
  if (!/^[A-Za-z0-9_-]{1,100}$/.test(productId) || (mode !== "move" && mode !== "restore")) {
    return json({ success: false, error: "Invalid leak ID" }, 400, { "Cache-Control": "no-store" });
  }
  const product = await dbGetProduct(env, productId).catch(() => null);
  const prefix = normalizeR2Prefix(product?.file_path);
  const bucket = env.STORAGE_PROD || env.STORAGE;
  if (!product || !bucket || !prefix) return json({ success: false, error: "Leak storage is unavailable" }, 404, { "Cache-Control": "no-store" });

  const objects = await r2List(env, prefix, true);
  const hasInstaller = objects.some(object => /\.(exe|dmg)$/i.test(object.key));
  if (!hasInstaller) {
    return json({ success: true, product_id: productId, skipped: "no-installer", moved: 0, restored: 0, remaining: [] }, 200, { "Cache-Control": "no-store" });
  }

  if (mode === "restore") {
    const backupPrefix = `_source_ffx/${prefix}`;
    const backups = await r2List(env, backupPrefix, true);
    let restored = 0;
    for (const object of backups) {
      const relative = object.key.slice(backupPrefix.length);
      if (!relative || relative.endsWith("/") || /\.ffx$/i.test(relative)) continue;
      const existing = await bucket.head(prefix + relative).catch(() => null);
      if (!existing) {
        const stored = await bucket.get(object.key);
        if (!stored) continue;
        await bucket.put(prefix + relative, stored.body, {
          httpMetadata: { contentType: "application/octet-stream" },
          customMetadata: { product_id: productId, restored_at: new Date().toISOString() },
        });
      }
      await bucket.delete(object.key).catch(() => {});
      restored += 1;
    }
    return json({ success: true, product_id: productId, mode, restored }, 200, { "Cache-Control": "no-store" });
  }

  const moved = [];
  const remaining = [];
  for (const object of objects) {
    const relative = object.key.slice(prefix.length);
    if (!relative || relative.endsWith("/")) continue;
    // Only the preset sources leave the leak folder; project files, tutorials and
    // images stay where the pack has always kept them.
    if (!/\.ffx$/i.test(relative)) {
      remaining.push(relative);
      continue;
    }
    const stored = await bucket.get(object.key);
    if (!stored) continue;
    await bucket.put(`_source_ffx/${object.key}`, stored.body, {
      httpMetadata: { contentType: "application/octet-stream" },
      customMetadata: { product_id: productId, relocated_at: new Date().toISOString() },
    });
    await bucket.delete(object.key).catch(() => {});
    moved.push(relative);
  }
  const ffxLeft = remaining.filter(name => /\.ffx$/i.test(name));
  return json({ success: true, product_id: productId, mode, moved: moved.length, remaining: remaining.slice(0, 40), ffx_left: ffxLeft.length }, 200, { "Cache-Control": "no-store" });
}

async function installerSessionFromRequest(request, env) {
  const token = String(request.headers.get("Authorization") || "").replace(/^Bearer\s+/i, "").trim();
  const buildToken = String(env.FFX_RELEASE_SOURCE_TOKEN || "").trim();
  if (!token || (buildToken && token === buildToken)) return null;
  return decodeSessionCookie(token, env);
}

const INSTALLER_LOG_KEY = "installer-logs/index.json";
const INSTALLER_LOG_LIMIT = 2000;
// One account can never hold more than this many rows, so flooding the endpoint cannot
// push other members' records out of the audit trail.
const INSTALLER_LOG_PER_USER = 100;
const INSTALLER_LOG_EVENTS = new Set(["start", "complete", "error", "access-denied"]);
const installerLogCooldown = new Map();

function trimInstallerLog(entries) {
  const counts = new Map();
  const kept = [];
  for (const entry of entries) {
    const id = String(entry?.discord_id || "");
    const seen = (counts.get(id) || 0) + 1;
    counts.set(id, seen);
    if (seen > INSTALLER_LOG_PER_USER) continue;
    kept.push(entry);
    if (kept.length >= INSTALLER_LOG_LIMIT) break;
  }
  return kept;
}

async function handleInstallerLog(request, env) {
  if (request.method !== "POST") return json({ success: false, error: "Method not allowed" }, 405, { "Cache-Control": "no-store" });
  const grant = await installerSessionFromRequest(request, env);
  if (!grant?.userId) return json({ success: false, error: "Sign in with Discord first" }, 401, { "Cache-Control": "no-store" });
  const lastAt = installerLogCooldown.get(String(grant.userId)) || 0;
  if (Date.now() - lastAt < 1500) return json({ success: true, throttled: true }, 200, { "Cache-Control": "no-store" });
  installerLogCooldown.set(String(grant.userId), Date.now());
  if (installerLogCooldown.size > 2000) installerLogCooldown.clear();
  let body;
  try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid log entry" }, 400, { "Cache-Control": "no-store" }); }
  const event = String(body?.event || "").trim().toLowerCase();
  if (!INSTALLER_LOG_EVENTS.has(event)) return json({ success: false, error: "Invalid log event" }, 400, { "Cache-Control": "no-store" });
  const clip = (value, max) => String(value ?? "").slice(0, max);
  const productId = clip(body?.product_id, 100);
  const entry = {
    id: crypto.randomUUID(),
    at: new Date().toISOString(),
    discord_id: String(grant.userId),
    username: clip(grant.username, 120),
    event,
    product_id: /^[A-Za-z0-9_-]{1,100}$/.test(productId) ? productId : "",
    product_name: clip(body?.product_name, 160),
    version: clip(body?.version, 32),
    platform: clip(body?.platform, 24),
    total: Math.max(0, Math.min(Number(body?.total) || 0, 100000)),
    installed: Math.max(0, Math.min(Number(body?.installed) || 0, 100000)),
    skipped: Math.max(0, Math.min(Number(body?.skipped) || 0, 100000)),
    failed: Math.max(0, Math.min(Number(body?.failed) || 0, 100000)),
    duration_ms: Math.max(0, Math.min(Number(body?.duration_ms) || 0, 86400000)),
    error: clip(body?.error, 400),
    ip: getClientIp(request),
    user_agent: clip(request.headers.get("User-Agent"), 200),
  };
  const stored = await r2GetJSON(env, INSTALLER_LOG_KEY, null).catch(() => null);
  const entries = Array.isArray(stored?.entries) ? stored.entries : [];
  entries.unshift(entry);
  const kept = trimInstallerLog(entries);
  await r2PutJSON(env, INSTALLER_LOG_KEY, { updated_at: entry.at, entries: kept });
  return json({ success: true, id: entry.id }, 200, { "Cache-Control": "no-store" });
}

async function handleInstallerLogs(request, url, env, hasMasterKey) {
  if (request.method !== "GET") return json({ success: false, error: "Method not allowed" }, 405, { "Cache-Control": "no-store" });
  if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Founder access required" }, 403, { "Cache-Control": "no-store" });
  const stored = await r2GetJSON(env, INSTALLER_LOG_KEY, null).catch(() => null);
  const entries = Array.isArray(stored?.entries) ? stored.entries : [];
  const query = String(url.searchParams.get("q") || "").trim().toLowerCase();
  const limit = Math.max(1, Math.min(Number(url.searchParams.get("limit")) || 500, 2000));
  const filtered = query
    ? entries.filter(entry => [entry.discord_id, entry.username, entry.product_id, entry.product_name, entry.event, entry.platform, entry.version, entry.error, entry.ip, entry.at]
        .some(value => String(value || "").toLowerCase().includes(query)))
    : entries;
  return json({
    success: true,
    total: entries.length,
    matched: filtered.length,
    updated_at: stored?.updated_at || "",
    entries: filtered.slice(0, limit),
  }, 200, { "Cache-Control": "no-store" });
}

async function handleInstallerStatus(url, env) {
  const productId = String(url.searchParams.get("id") || "").trim();
  if (!/^[A-Za-z0-9_-]{1,100}$/.test(productId)) return json({ success: false, error: "Invalid leak ID" }, 400, { "Cache-Control": "no-store" });
  const bucket = env.STORAGE_PROD || env.STORAGE;
  const product = await dbGetProduct(env, productId).catch(() => null);
  const prefix = normalizeR2Prefix(product?.file_path);
  const platforms = {};
  if (bucket && prefix) {
    for (const platform of Object.keys(INSTALLER_PLATFORMS)) {
      const object = await installerObjectFor(bucket, prefix, platform).catch(() => null);
      if (!object) continue;
      platforms[platform] = {
        filename: object.filename,
        size: object.size,
        uploaded_at: object.uploaded ? new Date(object.uploaded).toISOString() : "",
        url: `/api/installer/download?id=${encodeURIComponent(productId)}&platform=${platform}`,
      };
    }
  }
  return json({ success: true, product_id: productId, platforms }, 200, { "Cache-Control": "public, max-age=60" });
}

async function handleInstallerDownload(request, url, env) {
  const productId = String(url.searchParams.get("id") || "").trim();
  const platform = String(url.searchParams.get("platform") || "").trim().toLowerCase();
  if (!/^[A-Za-z0-9_-]{1,100}$/.test(productId) || !installerPlatformExtension(platform)) {
    return json({ success: false, error: "Invalid installer request" }, 400, { "Cache-Control": "no-store" });
  }
  const session = parseSession(request.headers.get("Cookie"), request);
  if (!session?.userId) return redirect(`/api/login?redirect=${encodeURIComponent(url.pathname + url.search)}`);
  const access = await installerAccess(env, session.userId);
  if (!access.allowed) {
    // Redirecting to the unlock page keeps the browser flow usable; a scripted client
    // still has to satisfy the same gates to get the file.
    if (url.searchParams.get("redirect") === "1") return redirect("/access?return_to=" + encodeURIComponent("/download"));
    return installerAccessDenied(access);
  }
  const bucket = env.STORAGE_PROD || env.STORAGE;
  const product = await dbGetProduct(env, productId).catch(() => null);
  const prefix = normalizeR2Prefix(product?.file_path);
  const object = bucket && prefix ? await installerObjectFor(bucket, prefix, platform).catch(() => null) : null;
  if (!object) return json({ success: false, error: "This leak does not have a Zyrex Installer for that platform yet." }, 404, { "Cache-Control": "no-store" });
  const stored = await bucket.get(object.key);
  if (!stored) return json({ success: false, error: "Installer is unavailable" }, 404, { "Cache-Control": "no-store" });
  return new Response(stored.body, {
    status: 200,
    headers: {
      "Content-Type": "application/octet-stream",
      "Content-Disposition": `attachment; filename*=UTF-8''${encodeURIComponent(object.filename)}`,
      "Content-Length": String(object.size),
      "Cache-Control": "private, max-age=300",
      "X-Content-Type-Options": "nosniff",
    },
  });
}

async function handleInstallerBuildKey(request, env) {
  const authorization = String(request.headers.get("Authorization") || "");
  const provided = authorization.replace(/^Bearer\s+/i, "").trim();
  if (!installerSecretMatches(provided, env.FFX_RELEASE_SOURCE_TOKEN)) return json({ success: false, error: "Unauthorized" }, 401, { "Cache-Control": "no-store" });
  let body;
  try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid request" }, 400); }
  const productId = String(body?.product_id || "").trim();
  const releaseId = String(body?.release_id || "").trim();
  if (!/^[A-Za-z0-9_-]{1,100}$/.test(productId) || !/^[A-Za-z0-9_-]{1,100}$/.test(releaseId)) return json({ success: false, error: "Invalid installer build" }, 400);
  return json({ success: true, key: await deriveInstallerPayloadKey(productId, releaseId, env) }, 200, { "Cache-Control": "no-store" });
}

async function handleInstallerFfxSource(request, url, env) {
  const expected = String(env.FFX_RELEASE_SOURCE_TOKEN || "").trim();
  const authorization = String(request.headers.get("Authorization") || "");
  const provided = authorization.replace(/^Bearer\s+/i, "").trim();
  const productId = String(url.searchParams.get("id") || "").trim();
  const releaseId = String(url.searchParams.get("release_id") || "").trim();
  const buildAuthorized = installerSecretMatches(provided, expected);
  const grant = buildAuthorized ? null : await installerGrantFromRequest(request, env, productId, releaseId);
  if (!buildAuthorized && !grant) {
    return json({ success: false, error: "Unauthorized" }, 401, { "Cache-Control": "no-store" });
  }
  if (grant) {
    const access = await installerAccess(env, grant.userId);
    if (!access.allowed) return installerAccessDenied(access);
  }
  if (!/^[A-Za-z0-9_-]{1,100}$/.test(productId)) {
    return json({ success: false, error: "Invalid leak ID" }, 400, { "Cache-Control": "no-store" });
  }
  const product = await dbGetProduct(env, productId).catch(() => null);
  if (!product || String(product.type || "preset").toLowerCase() !== "preset") {
    return json({ success: false, error: "Preset not found" }, 404, { "Cache-Control": "no-store" });
  }
  const prefix = normalizeR2Prefix(product.file_path);
  const bucket = env.STORAGE_PROD || env.STORAGE;
  if (!prefix || !bucket) {
    return json({ success: false, error: "Production source is unavailable" }, 404, { "Cache-Control": "no-store" });
  }

  let sourcePrefix = `_source_ffx/${prefix}`;
  const testListing = await bucket.list({ prefix: sourcePrefix, limit: 5 });
  if (!testListing.objects || !testListing.objects.some(o => /\.ffx$/i.test(o.key))) {
    sourcePrefix = prefix;
  }

  const requestedKey = String(url.searchParams.get("file") || "");
  if (requestedKey) {
    let object = null;
    let actualPrefix = prefix;
    if (requestedKey.startsWith(prefix) || requestedKey.startsWith(`_source_ffx/${prefix}`)) {
      if (!requestedKey.includes("..") && /\.ffx$/i.test(requestedKey)) {
        object = await bucket.get(requestedKey);
        actualPrefix = requestedKey.startsWith("_source_ffx/") ? `_source_ffx/${prefix}` : prefix;
        if (!object && !requestedKey.startsWith("_source_ffx/")) {
          const altKey = `_source_ffx/${requestedKey}`;
          object = await bucket.get(altKey);
          if (object) actualPrefix = `_source_ffx/${prefix}`;
        }
      }
    }
    if (!object) return json({ success: false, error: "Source file not found" }, 404, { "Cache-Control": "no-store" });
    let body = object.body;
    if (grant) {
      const raw = new Uint8Array(await object.arrayBuffer());
      const traced = traceDownloadBytes(raw, relativeR2Name(requestedKey, actualPrefix), grant.userId, grant.username, new Date().toISOString());
      if (!traced) return json({ success: false, error: "This preset cannot be safely traced and was not released." }, 422, { "Cache-Control": "no-store" });
      body = traced;
    }
    return new Response(body, {
      status: 200,
      headers: {
        "Content-Type": "application/octet-stream",
        "Content-Disposition": `attachment; filename*=UTF-8''${encodeURIComponent(requestedKey.slice(requestedKey.lastIndexOf("/") + 1))}`,
        "Cache-Control": "private, no-store",
        "X-Content-Type-Options": "nosniff",
      },
    });
  }

  const files = await listInstallerSources(bucket, sourcePrefix);
  if (!files.length) return json({ success: false, error: "No FFX presets in this production folder" }, 404, { "Cache-Control": "no-store" });
  if (url.searchParams.get("bundle") === "1" && buildAuthorized) {
    return installerSourceBundle(bucket, sourcePrefix, productId, files);
  }
  return json({ success: true, id: productId, files: files.map(({ key, name, size }) => ({ key, name, size })) }, 200, { "Cache-Control": "private, no-store" });
}

async function listInstallerSources(bucket, sourcePrefix) {
  const files = [];
  let cursor;
  for (let page = 0; page < 5; page++) {
    const listed = await bucket.list({ prefix: sourcePrefix, limit: 1000, cursor });
    for (const object of listed.objects || []) {
      if (object.key.startsWith(sourcePrefix) && /\.ffx$/i.test(object.key) && !object.key.includes("..")) {
        files.push({ key: object.key, name: relativeR2Name(object.key, sourcePrefix), size: object.size });
      }
    }
    if (!listed.truncated || !listed.cursor) break;
    cursor = listed.cursor;
  }
  return files;
}

// Building one leak used to cost one Worker request per preset, which is what exhausted
// the zone's daily quota during a full backfill. The bundle answers the whole pack in a
// single request: magic, file count, then (name length, data length, name, data) per
// preset — a layout the build tool parses directly.
const SOURCE_BUNDLE_MAGIC = "ZYXSRC1\n";
const SOURCE_BUNDLE_MAX_BYTES = 48 * 1024 * 1024;

async function installerSourceBundle(bucket, sourcePrefix, productId, files) {
  const declared = files.reduce((sum, file) => sum + (Number(file.size) || 0), 0);
  if (declared > SOURCE_BUNDLE_MAX_BYTES) {
    return json({ success: false, error: "This pack is too large for a single transfer; request the files one by one.", code: "BUNDLE_TOO_LARGE" }, 413, { "Cache-Control": "no-store" });
  }
  const encoder = new TextEncoder();
  const magic = encoder.encode(SOURCE_BUNDLE_MAGIC);
  const chunks = [];
  let total = magic.length + 4;
  for (const file of files) {
    const stored = await bucket.get(file.key);
    if (!stored) continue;
    const name = encoder.encode(file.name);
    const data = new Uint8Array(await stored.arrayBuffer());
    const header = new DataView(new ArrayBuffer(8));
    header.setUint32(0, name.length, false);
    header.setUint32(4, data.length, false);
    chunks.push(new Uint8Array(header.buffer), name, data);
    total += 8 + name.length + data.length;
  }
  if (!chunks.length) return json({ success: false, error: "No FFX presets in this production folder" }, 404, { "Cache-Control": "no-store" });
  if (total > SOURCE_BUNDLE_MAX_BYTES + 65536) {
    return json({ success: false, error: "This pack is too large for a single transfer; request the files one by one.", code: "BUNDLE_TOO_LARGE" }, 413, { "Cache-Control": "no-store" });
  }
  const output = new Uint8Array(total);
  output.set(magic, 0);
  new DataView(output.buffer).setUint32(magic.length, chunks.length / 3, false);
  let offset = magic.length + 4;
  for (const chunk of chunks) {
    output.set(chunk, offset);
    offset += chunk.length;
  }
  return new Response(output, {
    status: 200,
    headers: {
      "Content-Type": "application/octet-stream",
      "Content-Length": String(output.length),
      "Cache-Control": "private, no-store",
      "X-Zyrex-Source-Count": String(chunks.length / 3),
      "X-Content-Type-Options": "nosniff",
    },
  });
}

async function queuePresetInstallerBuild(env, product) {
  const githubToken = String(env.FFX_RELEASE_GITHUB_TOKEN || "").trim();
  const sourceToken = String(env.FFX_RELEASE_SOURCE_TOKEN || "").trim();
  const repository = String(env.FFX_RELEASE_REPOSITORY || "reyliar/zyrex-web").trim();
  if (!githubToken || !sourceToken || !product || String(product.type || "preset").toLowerCase() !== "preset") return false;
  const prefix = normalizeR2Prefix(product.file_path);
  const bucket = env.STORAGE_PROD || env.STORAGE;
  if (!prefix || !bucket) return false;
  const listing = await bucket.list({ prefix, limit: 1000 });
  const hasFfx = (listing.objects || []).some(object => object.key.startsWith(prefix) && /\.ffx$/i.test(object.key));
  if (!hasFfx) {
    const backupListing = await bucket.list({ prefix: `_source_ffx/${prefix}`, limit: 10 });
    if (!(backupListing.objects || []).some(object => /\.ffx$/i.test(object.key))) return false;
  }
  const response = await fetch(`https://api.github.com/repos/${repository}/dispatches`, {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${githubToken}`,
      "Accept": "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
      "User-Agent": "Zyrex-Preset-Release",
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ event_type: "zyrex_preset_published", client_payload: { product_id: String(product.id || "") } }),
    signal: AbortSignal.timeout(8000),
  });
  if (!response.ok) throw new Error(`GitHub release dispatch failed (${response.status})`);
  return true;
}

function relativeR2Name(key, prefix) {
  return key.slice(prefix.length).replace(/\\/g, "/").replace(/^\/+/, "");
}

function isWatermarkName(name) {
  const base = String(name || "").split("/").pop();
  return Object.prototype.hasOwnProperty.call(WATERMARKS, base);
}

function isDownloadableR2Object(obj, prefix) {
  if (!obj || !obj.key || obj.key.endsWith("/") || obj.key === prefix) return false;
  const name = relativeR2Name(obj.key, prefix);
  if (!name || name.endsWith("/") || name === ".placeholder" || name.endsWith("/.placeholder")) return false;
  return !isWatermarkName(name);
}

// A leak that already ships a Zyrex installer carries its presets inside the installer's
// encrypted payload, so the archive drops the bare .ffx files. A leak without an
// installer keeps them, otherwise its download would be empty.
function archiveObjects(objects, prefix) {
  const downloadable = (objects || []).filter(object => isDownloadableR2Object(object, prefix));
  const hasInstaller = downloadable.some(object => /\.(exe|dmg)$/i.test(object.key));
  if (!hasInstaller) return downloadable;
  return downloadable.filter(object => !/\.ffx$/i.test(object.key));
}

function safeDecode(value) {
  try { return decodeURIComponent(value); } catch { return value; }
}

function normalizeSelectedName(value) {
  return safeDecode(String(value || "")).replace(/\\/g, "/").replace(/^\/+/, "");
}

function getRequestedFileSet(url) {
  const selected = new Set();
  const add = value => {
    const clean = normalizeSelectedName(value);
    if (clean) selected.add(clean);
  };

  for (const value of url.searchParams.getAll("file")) add(value);
  for (const value of url.searchParams.getAll("files")) {
    for (const part of String(value || "").split(",")) add(part);
  }

  return selected.size > 0 ? selected : null;
}

function slugify(value) {
  return String(value || "")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function scorePrefixMatch(prefix, resourceName, productId, product) {
  const resourceSlug = slugify(resourceName || prefix);
  const prefixSlug = slugify(prefix);
  const targets = [productId, product?.id, product?.name, product?.title]
    .map(slugify)
    .filter(Boolean);

  let best = 0;
  for (const target of targets) {
    if (!target) continue;
    if (resourceSlug === target) best = Math.max(best, 100);
    else if (prefixSlug === target) best = Math.max(best, 95);
    else if (resourceSlug.includes(target) || target.includes(resourceSlug)) best = Math.max(best, 80);
    else if (prefixSlug.includes(target) || target.includes(prefixSlug)) best = Math.max(best, 60);
  }
  return best;
}

async function prefixHasDownloadableFiles(bucket, prefix) {
  if (!prefix) return false;
  const listed = await bucket.list({ prefix, limit: 100 });
  return (listed.objects || []).some(obj => isDownloadableR2Object(obj, prefix));
}

// ============================================================
// R2 DATABASE ENGINE — All core data lives in R2, not Bot VPS
// ============================================================

const DB = {
  PRODUCTS:       "database/products.json",
  STATS:          "database/presets_stats.json",
  COMMENTS:       "database/comments.json",
  DOWNLOADS:      "database/downloads_counts.json",
  DOWNLOAD_LOGS:  "database/download_logs.json",
  UPLOADERS:      "database/uploaders.json",
  TEAM:           "database/team.json",
  GUILD_STATS:    "database/guild_stats.json",
  CREATOR_INDEX:  "database/search_creator_index.json",
};

const COMMUNITY_UPLOADER_ROLE_IDS = [
  "1519624224476762122", // Preset / Resource Uploader
  "1522976282688880720", // Audio Uploader
];
// Verdict cache for the community uploader roles. The stored value IS the answer, so
// a negative result can never be replayed as a positive one.
const uploaderRoleCache = new Map();

function rememberUploaderRole(userId, value, ttlMs) {
  uploaderRoleCache.set(userId, { value: value === true, expiry: Date.now() + ttlMs });
}

async function hasCommunityUploaderRole(userId, env) {
  if (!userId) return false;

  // Revocation outranks every cache: a member who lost access must never be treated
  // as an uploader, even while a positive verdict is still cached. isRevoked has its
  // own short memo, so this does not add a read per call.
  if (await isRevoked(env, userId) === true) {
    rememberUploaderRole(userId, false, 600000);
    return false;
  }

  const cached = uploaderRoleCache.get(userId);
  if (cached && Date.now() < cached.expiry) return cached.value === true;

  // Snapshot first, like the other role gates: no live lookup when the bot has
  // already published every uploader role.
  let answeredBySnapshot = 0;
  for (const roleId of COMMUNITY_UPLOADER_ROLE_IDS) {
    const snapshot = await roleSnapshotVerdict(env, roleId, userId);
    if (snapshot === true) {
      rememberUploaderRole(userId, true, 300000);
      return true;
    }
    if (snapshot === false) answeredBySnapshot++;
  }
  if (answeredBySnapshot === COMMUNITY_UPLOADER_ROLE_IDS.length) {
    rememberUploaderRole(userId, false, 300000);
    return false;
  }

  try {
    const checks = await Promise.all(COMMUNITY_UPLOADER_ROLE_IDS.map(async roleId => {
      try {
        const response = await fetch(`${BOT_API}/api/guild/check-role?userId=${encodeURIComponent(userId)}&roleId=${roleId}`, {
          signal: AbortSignal.timeout(3500),
        });
        if (!response.ok) return false;
        const result = await response.json();
        return result?.has_role === true;
      } catch (_) { return false; }
    }));
    if (checks.some(Boolean)) {
      rememberUploaderRole(userId, true, 60000);
      return true;
    }
  } catch (_) {}

  // Direct Discord fallback keeps the gate working when the VPS bot API is down.
  if (env?.DISCORD_BOT_TOKEN) {
    try {
      const response = await fetch(`${DISCORD_API}/guilds/${env.GUILD_ID || "1518954946110685184"}/members/${encodeURIComponent(userId)}`, {
        headers: { Authorization: `Bot ${env.DISCORD_BOT_TOKEN}` },
        signal: AbortSignal.timeout(3500),
      });
      if (response.ok) {
        const member = await response.json();
        const holdsRole = (member.roles || []).some(roleId => COMMUNITY_UPLOADER_ROLE_IDS.includes(String(roleId)));
        rememberUploaderRole(userId, holdsRole, 60000);
        if (holdsRole) return true;
      }
    } catch (e) { console.error("Direct uploader role check failed:", e.message); }
  }
  // Only cache a negative here when the lookup actually produced an answer, so a
  // provider outage cannot pin somebody out of the upload pages.
  return false;
}

// The session cookie carries a canUpload claim minted at login, so it can outlive the
// privilege it was issued for. Every write that authorises an upload or a product
// change goes through here, which re-checks revocation before trusting that claim.
async function sessionCanUpload(session, env) {
  if (!session || !session.userId) return false;
  if (ADMIN_IDS.includes(session.userId)) return true;
  if (await isRevoked(env, session.userId) === true) return false;
  return session.canUpload === true;
}

// SFTPGo data belongs to the uploader, so every proxy route verifies the role at
// request time instead of trusting a potentially stale upload claim in the session cookie.
async function canAccessUploaderCloud(session, env) {
  const id = String(session && session.userId || "");
  if (!id) return false;
  if (await isRevoked(env, id) === true) return false;
  if (await dbIsUploader(env, id).catch(() => false)) return true;
  return await hasCommunityUploaderRole(id, env).catch(() => false);
}

async function r2GetJSON(env, key, fallback = null) {
  try {
    const obj = await env.STORAGE.get(key);
    if (!obj) return fallback;
    return await obj.json();
  } catch(e) {
    console.error("r2GetJSON error", key, e.message);
    return fallback;
  }
}

async function r2PutJSON(env, key, data) {
  try {
    await env.STORAGE.put(key, JSON.stringify(data), {
      httpMetadata: { contentType: "application/json" }
    });
    return true;
  } catch(e) {
    console.error("r2PutJSON error", key, e.message);
    return false;
  }
}

async function r2DeleteKey(env, key) {
  try {
    await env.STORAGE.delete(key);
    return true;
  } catch(e) {
    console.error("r2DeleteKey error", key, e.message);
    return false;
  }
}

// ── Plugin / software mirrors ─────────────────────────────────────────────────
// Plugin downloads are external mirrors (ArFiles, MediaFire, Drive), so the URL *is* the
// asset. Mirrors therefore never travel in the public catalogue: the static bundle keeps
// display fields only, database records are stripped for non-admins, and the real URL is
// handed out by POST /api/plugins/download to members holding the Verified role.
const PLUGIN_MIRRORS_KEY = "database/plugin_mirrors.json";
const PLUGIN_MIRRORS_MEMO_MS = 60 * 1000;
let pluginMirrorsMemo = { at: 0, entries: null };

async function loadPluginMirrors(env) {
  if (pluginMirrorsMemo.entries && Date.now() - pluginMirrorsMemo.at < PLUGIN_MIRRORS_MEMO_MS) {
    return pluginMirrorsMemo.entries;
  }
  const data = await r2GetJSON(env, PLUGIN_MIRRORS_KEY, null).catch(() => null);
  const entries = data && data.entries && typeof data.entries === "object" ? data.entries : {};
  pluginMirrorsMemo = { at: Date.now(), entries };
  return entries;
}

function normalizeMirrorList(value) {
  const list = Array.isArray(value) ? value : [];
  return list.map(entry => {
    const url = String((entry && entry.url) || entry || "").trim();
    const label = String((entry && entry.label) || "Mirror").trim();
    return { url, label };
  }).filter(entry => /^https?:\/\//i.test(entry.url));
}

function productMirrorList(product) {
  if (!product) return [];
  let links = normalizeMirrorList(product.links);
  if (!links.length && product.links_json) {
    try { links = normalizeMirrorList(JSON.parse(product.links_json)); } catch (_) { links = []; }
  }
  if (!links.length) {
    for (const [field, label] of [["link", "Mirror 1"], ["link_2", "Mirror 2"], ["link_3", "Mirror 3"]]) {
      const url = String(product[field] || "").trim();
      if (/^https?:\/\//i.test(url)) links.push({ url, label });
    }
  }
  if (!links.length) {
    const fallback = String(product.product_url || product.source_url || "").trim();
    if (/^https?:\/\//i.test(fallback)) links.push({ url: fallback, label: "Mirror" });
  }
  return links;
}

// Resolves the download the client asked for. Database products win, because their links
// (and archive password) are maintained in the admin panel; static slugs come from R2.
async function resolvePluginMirror(env, id) {
  if (!/^[a-z0-9_-]{3,120}$/i.test(id)) return null;
  const product = await dbGetProduct(env, id).catch(() => null);
  if (product) {
    const links = productMirrorList(product);
    return {
      name: String(product.name || ""),
      url: links[0] ? links[0].url : "",
      label: links[0] ? links[0].label : "",
      mirrors: links,
      password: product.password ? String(product.password) : "",
      notes: product.notes ? String(product.notes) : "",
      // Uploaded archives keep using the token flow, which greys out the mirror list.
      token_url: !links.length && product.file_path ? `/download?id=${encodeURIComponent(id)}` : "",
    };
  }
  const entries = await loadPluginMirrors(env);
  let entry = entries[id] || null;
  const overrides = await readProductOverrides(env);
  const override = overrides.items && overrides.items[id];
  if (override && (override.deleted === true || override.hidden === true)) return null;
  if (override) entry = entry ? applyProductOverride(entry, override) : { id, ...(override.patch || {}) };
  if (!entry) return null;
  const links = productMirrorList(entry);
  return {
    name: String(entry.name || entry.title || ""),
    url: links[0] ? links[0].url : String(entry.download_url || ""),
    label: links[0] ? links[0].label : "",
    mirrors: links,
    password: entry.password ? String(entry.password) : "",
    notes: entry.notes ? String(entry.notes) : "",
    token_url: "",
  };
}

// Plugin records are stripped of everything that could be used to download directly.
function stripPluginDownloadFields(item) {
  if (!item) return item;
  const type = String(item.type || "").toLowerCase();
  if (type !== "plugin" && type !== "software") return item;
  delete item.links;
  delete item.links_json;
  delete item.link;
  delete item.link_2;
  delete item.link_3;
  delete item.downloadUrl;
  delete item.download_url;
  delete item.product_url;
  delete item.source_url;
  delete item.password;
  delete item.notes;
  return item;
}

// --- Products ---
async function dbGetProducts(env) {
  const data = await r2GetJSON(env, DB.PRODUCTS, []);
  return Array.isArray(data) ? data : [];
}

async function dbGetProduct(env, id) {
  const products = await dbGetProducts(env);
  return products.find(p => p.id === id) || null;
}

async function dbReadProductCatalog(env) {
  if (!env.STORAGE) throw new Error("Product storage is unavailable");
  const object = await env.STORAGE.get(DB.PRODUCTS);
  if (!object) throw new Error("Product catalog is unavailable");
  const products = await object.json();
  if (!Array.isArray(products)) throw new Error("Product catalog data is invalid");
  return products;
}

async function dbSaveProducts(env, products) {
  if (!env.STORAGE) throw new Error("Server storage is unavailable");
  await env.STORAGE.put(DB.PRODUCTS, JSON.stringify(products), {
    httpMetadata: { contentType: "application/json" }
  });
  return true;
}

// Clients key their cached resource catalogue on the privacy epoch, so any change to the
// catalogue has to move it. Without this an edit stays invisible for the full 15 minute
// client cache window, which is exactly what "my changes do not show up" looked like.
async function invalidateCatalogVersion(env) {
  return bumpPrivacyEpoch(env);
}

// Who a resource is attributed to - the uploader credit and the anonymous switch - is a
// staff decision. For anyone else those fields are dropped and the uploader is pinned to
// the caller's own session, so an uploader can neither credit somebody else nor hide.
const ADMIN_ONLY_ATTRIBUTION_FIELDS = [
  "is_anonymous",
  "credited_uploader_id", "credited_uploader_name", "credited_uploader_avatar",
  "submitter_id", "submitter_name", "submitter_avatar",
];

function sessionIsAdmin(session) {
  const userId = String((session && session.userId) || "").trim();
  return Boolean(userId) && ADMIN_IDS.includes(userId);
}

function canSetUploaderAttribution() {
  // Both admin and non-admin uploaders have credit and anonymous permissions enabled
  return true;
}

function applyUploaderAttributionRules(payload, session) {
  if (!session) return payload;
  const userId = String((session && session.userId) || "").trim();
  const name = String((session && (session.displayName || session.username)) || "").trim();
  const avatar = String((session && session.avatar) || "").trim();
  // Pin raw uploader identity to caller session if not anonymous and not crediting another user
  if (payload.is_anonymous !== true && !payload.credited_uploader_id) {
    if (userId) { payload.uploader_id = userId; payload.author_id = userId; }
    if (name) { payload.uploader_name = name; payload.author_name = name; }
    if (avatar) { payload.uploader_avatar = avatar; payload.author_avatar = avatar; }
  }
  return payload;
}

async function dbAddProduct(env, product) {
  const products = await dbReadProductCatalog(env);
  const existing = products.find(item => item.id === product.id);
  if (existing) return existing;
  products.push(product);
  await dbSaveProducts(env, products);
  await invalidateCatalogVersion(env);
  return product;
}

// Anonymous resources must not carry the uploader identity at rest. Scrubbing
// only on read left the real name and Discord id inside products.json, so any
// cache, mirror or stray reader could still expose it. The identity is moved to
// an admin-only record and removed from the public product itself.
const ANON_UPLOADERS_KEY = "database/anonymous_uploaders.json";
// Bumped whenever a resource's anonymity changes. Clients key their product
// cache on it, so a resource that becomes anonymous can never be rendered from
// a cache that still holds its uploader identity.
const PRIVACY_EPOCH_KEY = "database/privacy_epoch.json";
const ANON_HIDDEN_FIELDS = [
  "uploader_id", "uploader_name", "uploader_avatar",
  "author_id", "author_name", "author_avatar",
  "credited_uploader_id", "credited_uploader_name", "credited_uploader_avatar",
  // Admin-only mirror of the uploader. It is stripped from every public read, so
  // it may only ever appear in the registry below.
  "submitter_id", "submitter_name", "submitter_avatar",
];

async function readPrivacyEpoch(env) {
  try {
    const stored = await r2GetJSON(env, PRIVACY_EPOCH_KEY, null);
    if (stored && typeof stored.epoch === "string" && stored.epoch) return stored.epoch;
  } catch (_) {}
  return "";
}

async function bumpPrivacyEpoch(env) {
  if (!env?.STORAGE) return "";
  try {
    const epoch = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
    await r2PutJSON(env, PRIVACY_EPOCH_KEY, { epoch, updated_at: new Date().toISOString() });
    return epoch;
  } catch (_) {
    return "";
  }
}

function isAnonymousPlaceholder(value) {
  const text = String(value ?? "").trim();
  return !text || text.toLowerCase() === "anonymous";
}

// A change to the access duration invalidates every pass that was already
// granted, because each stored pass keeps the expiry it was issued with.
async function resetDownloadAccess(env, options = {}) {
  const dryRun = options.dryRun !== false;
  const report = { dry_run: dryRun, scanned: 0, active: 0, expired: 0, invalid: 0, removed: 0, discord_ids: [] };
  if (!env?.STORAGE) throw new Error("Storage is unavailable");

  const listed = await env.STORAGE.list({ prefix: RESOURCE_ACCESS_PATH, limit: 1000 });
  const objects = listed?.objects || [];
  report.scanned = objects.length;
  const now = Date.now();

  for (const object of objects) {
    const discordId = String(object.key).slice(RESOURCE_ACCESS_PATH.length);
    const isDiscordId = /^\d{17,20}$/.test(discordId);
    if (isDiscordId) {
      let expiresAt = 0;
      try {
        const stored = await r2GetJSON(env, object.key, null);
        expiresAt = Number(stored?.expires_at) || 0;
      } catch (_) {}
      if (expiresAt > now) {
        report.active++;
        report.discord_ids.push(discordId);
      } else {
        report.expired++;
      }
    } else {
      // Not a Discord id, so nothing can ever read it; it is cleared as junk.
      report.invalid++;
    }
    if (!dryRun) {
      await env.STORAGE.delete(object.key);
      report.removed++;
    }
  }
  return report;
}

function accessNotificationId(discordId) {
  return `access-duration-${RESOURCE_ACCESS_DURATION_DAYS}d-${discordId}`;
}

function accessChangeMessage() {
  return {
    title: "Download access is now 7 days — please re-unlock",
    desc: `We shortened resource download access from 2 weeks to ${RESOURCE_ACCESS_DURATION_DAYS} days. Every existing pass has been reset, so unlock a new ${RESOURCE_ACCESS_LABEL.toLowerCase()} pass on the Access page. It is still free and linked to your Discord account.`,
    link: "/access",
  };
}

// Site + Discord notification for everyone whose pass was reset.
async function notifyAccessChange(env, options = {}) {
  const discordIds = Array.isArray(options.discordIds)
    ? [...new Set(options.discordIds.map(id => String(id || "").trim()).filter(id => /^\d{17,20}$/.test(id)))]
    : [];
  const dryRun = options.dryRun !== false;
  const sendDiscord = options.discord === true;

  const message = accessChangeMessage();
  const report = { dry_run: dryRun, recipients: discordIds.length, site_notified: 0, discord_sent: 0, discord_already_sent: 0, discord_unreachable: 0, discord_failed: [], already_notified: 0 };

  if (!discordIds.length) return report;

  const stored = await r2GetJSON(env, "database/notifications.json", []);
  const list = Array.isArray(stored) ? stored : [];
  const byId = new Map(list.filter(item => item && item.id).map(item => [String(item.id), item]));

  for (const discordId of discordIds) {
    const id = accessNotificationId(discordId);
    if (byId.has(id)) { report.already_notified++; continue; }
    byId.set(id, {
      id,
      user_id: discordId,
      title: message.title,
      desc: message.desc,
      link: message.link,
      icon: "fa-clock-rotate-left",
      icon_brand: false,
      bg: "linear-gradient(135deg, var(--zr-accent, rgba(var(--zr-rgb-255-43-82, 255, 43, 82), 1)), rgba(var(--zr-rgb-139-0-40, 139, 0, 40), 1))",
      color: "#fff",
      category: "access",
      created_at: new Date().toISOString(),
    });
    report.site_notified++;
  }

  if (!dryRun && report.site_notified > 0) {
    await r2PutJSON(env, "database/notifications.json", [...byId.values()]);
  }

  if (sendDiscord && !dryRun) {
    let dirty = false;
    for (const discordId of discordIds) {
      const entry = byId.get(accessNotificationId(discordId));
      if (entry?.discord_sent_at) { report.discord_already_sent++; continue; }
      // 403 means the member closed their DMs; retrying can never succeed.
      if (entry?.discord_unreachable_at) { report.discord_unreachable++; continue; }
      try {
        const response = await fetch(`${BOT_API}/api/guild/members/dm`, {
          method: "POST",
          headers: { "Content-Type": "application/json", "X-User-ID": String(options.adminId || ADMIN_IDS[0] || "") },
          body: JSON.stringify({ user_id: discordId, title: message.title, message: message.desc }),
          signal: AbortSignal.timeout(8000),
        });
        if (response.ok) {
          report.discord_sent++;
          if (entry) { entry.discord_sent_at = new Date().toISOString(); dirty = true; }
        } else if (response.status === 403 || response.status === 404) {
          report.discord_unreachable++;
          if (entry) { entry.discord_unreachable_at = new Date().toISOString(); entry.discord_unreachable_status = response.status; dirty = true; }
        } else if (report.discord_failed.length < 20) {
          report.discord_failed.push({ discordId, status: response.status });
        }
      } catch (error) {
        if (report.discord_failed.length < 20) report.discord_failed.push({ discordId, error: publicErrorMessage(error) });
      }
    }
    // Recording delivery keeps repeated runs from messaging the same member twice.
    if (dirty) await r2PutJSON(env, "database/notifications.json", [...byId.values()]);
  }

  return report;
}

function anonymousIdentityOf(product) {
  const identity = {};
  for (const field of ANON_HIDDEN_FIELDS) {
    const value = String(product?.[field] ?? "").trim();
    if (isAnonymousPlaceholder(value)) continue;
    identity[field] = value;
  }
  return identity;
}

// Hiding the uploader from the public is the point of an anonymous upload, but
// staff still need to answer "who posted this?". The identity therefore lives in
// this admin-only registry keyed by product id, never on the product itself.
function looksLikeDiscordId(value) {
  return /^\d{15,25}$/.test(String(value || "").trim());
}

async function recordAnonymousUpload(env, productId, identity, options = {}) {
  const id = String(productId || "").trim();
  if (!env?.STORAGE || !id || !identity || typeof identity !== "object") return false;
  const uploaderId = String(identity.uploader_id || identity.author_id || identity.submitter_id || "").trim();
  const uploaderName = String(identity.uploader_name || identity.author_name || identity.submitter_name || "").trim();
  const uploaderAvatar = String(identity.uploader_avatar || identity.submitter_avatar || "").trim();
  const productName = String(identity.product_name || "").trim();
  if (!looksLikeDiscordId(uploaderId) && !uploaderName) return false;
  try {
    const stored = await r2GetJSON(env, ANON_UPLOADERS_KEY, {});
    const registry = stored && typeof stored === "object" && !Array.isArray(stored) ? stored : {};
    const previous = registry[id] && typeof registry[id] === "object" ? registry[id] : {};
    // First writer wins on identity: a later scrub pass only fills in blanks, so a
    // second call can never rewrite who uploaded something.
    const now = new Date().toISOString();
    registry[id] = {
      product_id: id,
      uploader_id: looksLikeDiscordId(previous.uploader_id) ? previous.uploader_id : uploaderId,
      uploader_name: String(previous.uploader_name || uploaderName).trim(),
      uploader_avatar: String(previous.uploader_avatar || uploaderAvatar).trim(),
      product_name: String(previous.product_name || productName).trim(),
      source: String(previous.source || options.source || "submit").slice(0, 32),
      recorded_at: String(previous.recorded_at || now),
      updated_at: now,
    };
    await r2PutJSON(env, ANON_UPLOADERS_KEY, registry);
    console.log(`Recorded anonymous uploader for ${id}`);
    return true;
  } catch (error) {
    console.error("Anonymous uploader record failed:", error?.message || String(error));
    return false;
  }
}

async function readAnonymousUploads(env) {
  try {
    const stored = await r2GetJSON(env, ANON_UPLOADERS_KEY, {});
    if (!stored || typeof stored !== "object" || Array.isArray(stored)) return {};
    return stored;
  } catch (_) {
    return {};
  }
}

// Mutates the product in place: hides the uploader and parks the identity in the
// admin-only registry. Returns true when something actually changed.
async function scrubAnonymousProduct(env, product, options = {}) {
  if (!product || typeof product !== "object" || product.is_anonymous !== true) return false;
  const identity = anonymousIdentityOf(product);
  const uploaderNameValue = String(product.uploader_name || product.author_name || "").trim().toLowerCase();
  const uploaderIdValue = String(product.uploader_id || product.author_id || "").trim();

  let changed = false;
  for (const field of ANON_HIDDEN_FIELDS) {
    if (isAnonymousPlaceholder(product[field])) continue;
    product[field] = "";
    changed = true;
  }
  if (product.uploader_name !== "Anonymous") { product.uploader_name = "Anonymous"; changed = true; }
  if (product.author_name !== "Anonymous") { product.author_name = "Anonymous"; changed = true; }
  if ("uploader_is_admin" in product) { delete product.uploader_is_admin; changed = true; }

  const creatorName = String(product.creator_nickname || "").trim();
  if (isAnonymousPlaceholder(creatorName) || creatorName.toLowerCase() === uploaderNameValue) {
    if (product.creator_nickname !== "Zyrex Creator") {
      product.creator_nickname = "Zyrex Creator";
      changed = true;
    }
  }
  if (!isCdnAvatarUrl(product.creator_avatar) && creatorAvatarBelongsTo(product.creator_avatar, uploaderIdValue)) {
    product.creator_avatar = "";
    changed = true;
  }

  if (changed && options.record !== false && Object.keys(identity).length) {
    await recordAnonymousUpload(env, product.id, { ...identity, product_name: product.name }, { source: "scrub" });
  }
  if (changed && options.record !== false) await bumpPrivacyEpoch(env);
  return changed;
}

// Repairs creator names that were stored after a wrong code-page decode, so the
// catalog keeps clean text for every reader instead of relying on the pages.
async function repairCatalogText(env, options = {}) {
  const dryRun = options.dryRun !== false;
  const limit = Math.min(Math.max(Number(options.limit) || 2000, 1), 5000);

  const catalog = await dbReadProductCatalog(env);
  const profiles = await r2GetJSON(env, CREATOR_PROFILES_KEY, {});
  const profileStore = profiles && typeof profiles === "object" && !Array.isArray(profiles) ? profiles : {};

  const report = { dry_run: dryRun, limit, products_examined: 0, products_repaired: 0, profiles_repaired: 0, samples: [] };

  const productFields = ["name", "title", "description", "desc", "tags", "notes", "origin", "creator_nickname", "creator_username", "uploader_name", "author_name"];
  for (const product of catalog) {
    if (!product || typeof product !== "object") continue;
    if (report.products_repaired >= limit) break;
    report.products_examined++;
    let changed = false;
    for (const field of productFields) {
      if (typeof product[field] !== "string") continue;
      const fixed = repairMojibakeText(product[field]);
      if (fixed === product[field]) continue;
      if (report.samples.length < 5) report.samples.push({ id: product.id, field, before: product[field], after: fixed });
      product[field] = fixed;
      changed = true;
    }
    if (changed) report.products_repaired++;
  }

  for (const [key, profile] of Object.entries(profileStore)) {
    if (!profile || typeof profile !== "object") continue;
    let changed = false;
    for (const field of ["nickname", "username"]) {
      if (typeof profile[field] !== "string") continue;
      const fixed = repairMojibakeText(profile[field]);
      if (fixed === profile[field]) continue;
      profile[field] = fixed;
      changed = true;
    }
    if (changed) report.profiles_repaired++;
  }

  if (!dryRun && (report.products_repaired > 0 || report.profiles_repaired > 0)) {
    await r2PutJSON(env, DB.PRODUCTS, catalog);
    await r2PutJSON(env, CREATOR_PROFILES_KEY, profileStore);
  }
  return report;
}

// Re-cleans stored products that were anonymised after the fact, so old records
// stop carrying the uploader identity.
async function repairAnonymousProducts(env, options = {}) {
  const dryRun = options.dryRun !== false;
  const limit = Math.min(Math.max(Number(options.limit) || 500, 1), 2000);
  const onlyId = String(options.id || "").trim();

  const catalog = await dbReadProductCatalog(env);
  const report = { dry_run: dryRun, limit, examined: 0, repaired: 0, identity_saved: 0, failed: [] };

  for (const product of catalog) {
    if (!product || typeof product !== "object" || product.is_anonymous !== true) continue;
    if (onlyId && String(product.id) !== onlyId) continue;
    if (report.repaired >= limit) break;
    report.examined++;
    const hadIdentity = Object.keys(anonymousIdentityOf(product)).length > 0;
    const changed = await scrubAnonymousProduct(env, product, { record: !dryRun });
    if (changed) {
      report.repaired++;
      if (hadIdentity) report.identity_saved++;
    }
  }

  if (!dryRun && report.repaired > 0) await r2PutJSON(env, DB.PRODUCTS, catalog);
  return report;
}

async function dbUpdateProduct(env, id, updates) {
  const products = await dbReadProductCatalog(env);
  const idx = products.findIndex(p => p.id === id);
  if (idx === -1) return null;
  products[idx] = { ...products[idx], ...updates, updated_at: new Date().toISOString().replace('T',' ').slice(0,19) };
  await dbSaveProducts(env, products);
  await invalidateCatalogVersion(env);
  return products[idx];
}

const CREATOR_PROFILES_KEY = "database/creator_profiles.json";

function getCreatorPlatform(profileOrProduct) {
  const hasCreatorAccount = Boolean(profileOrProduct?.creator_account_id || profileOrProduct?.account_id);
  let explicit = String(profileOrProduct?.creator_platform || (hasCreatorAccount ? profileOrProduct?.platform : "") || "").trim().toLowerCase();
  if (explicit === "twitter") explicit = "x";
  if (["tiktok", "instagram", "youtube", "x"].includes(explicit)) return explicit;
  const socialUrl = String(profileOrProduct?.creator_social_url || "").toLowerCase();
  if (socialUrl.includes("tiktok.com")) return "tiktok";
  if (socialUrl.includes("instagram.com")) return "instagram";
  if (socialUrl.includes("youtube.com") || socialUrl.includes("youtu.be")) return "youtube";
  if (socialUrl.includes("x.com") || socialUrl.includes("twitter.com")) return "x";
  return "";
}

function normalizeCreatorHandle(value) {
  return String(value || "").trim().replace(/^@+/, "").toLowerCase();
}

// Social creators are frequently resolved from a URL only, so the profile key
// falls back to the handle. Keying exclusively by account id silently dropped
// every profile (and its photo) for those creators.
function creatorProfileKey(platform, accountId, username = "") {
  const p = String(platform || "").trim().toLowerCase();
  const id = String(accountId || "").trim();
  if (p && id) return `${p}:${id}`;
  const handle = normalizeCreatorHandle(username);
  return p && handle ? `${p}:@${handle}` : "";
}

async function saveCreatorProfile(env, profile) {
  const platform = getCreatorPlatform(profile);
  const accountId = String(profile?.creator_account_id || profile?.account_id || "").trim();
  const key = creatorProfileKey(
    platform,
    accountId,
    profile?.creator_username || profile?.username || socialUsernameFromUrl(profile?.creator_social_url || profile?.social_url)
  );
  if (!key) return false;
  const profiles = await r2GetJSON(env, CREATOR_PROFILES_KEY, {});
  const old = profiles && typeof profiles === "object" && !Array.isArray(profiles) ? profiles : {};
  const previous = old[key] || {};
  const username = String(profile.creator_username || profile.username || previous.username || "").trim();
  let nickname = String(profile.creator_nickname || profile.nickname || "").trim();
  if (!nickname || (!accountId && nickname.toLowerCase() === username.toLowerCase() && previous.nickname && previous.nickname.toLowerCase() !== username.toLowerCase())) {
    nickname = previous.nickname || nickname;
  }
  let avatar = String(profile.creator_avatar || profile.avatar || "").trim();
  if (avatar && !/^https:\/\/thumbnail\.zyrexediting\.xyz\//i.test(avatar)) {
    const cachedAvatar = await storeAndProxyImage(env, avatar).catch(() => "");
    if (cachedAvatar && /^https:\/\/thumbnail\.zyrexediting\.xyz\//i.test(cachedAvatar)) avatar = cachedAvatar;
  }
  if (!avatar) avatar = previous.avatar || "";
  const next = {
    ...previous,
    platform,
    account_id: accountId,
    username: username || previous.username || "",
    nickname,
    avatar,
    social_url: String(profile.creator_social_url || profile.social_url || previous.social_url || "").trim(),
    updated_at: new Date().toISOString(),
  };
  old[key] = next;
  return r2PutJSON(env, CREATOR_PROFILES_KEY, old);
}

function mergeCreatorProfile(product, profiles) {
  const key = creatorProfileKey(getCreatorPlatform(product), product.creator_account_id, product.creator_username);
  const profile = key && profiles ? profiles[key] : null;
  if (!profile) return product;
  const profileUsername = String(profile.username || "").trim();
  const profileNickname = String(profile.nickname || "").trim();
  return {
    ...product,
    creator_platform: profile.platform || product.creator_platform,
    creator_account_id: profile.account_id || product.creator_account_id,
    creator_username: profileUsername || product.creator_username,
    creator_nickname: profileNickname || product.creator_nickname,
    creator_avatar: profile.avatar || product.creator_avatar,
    creator_social_url: profile.social_url || product.creator_social_url,
  };
}

const MOJIBAKE_CP1252_BYTES = {
  0x20ac: 0x80, 0x201a: 0x82, 0x0192: 0x83, 0x201e: 0x84, 0x2026: 0x85,
  0x2020: 0x86, 0x2021: 0x87, 0x02c6: 0x88, 0x2030: 0x89, 0x0160: 0x8a,
  0x2039: 0x8b, 0x0152: 0x8c, 0x017d: 0x8e, 0x2018: 0x91, 0x2019: 0x92,
  0x201c: 0x93, 0x201d: 0x94, 0x2022: 0x95, 0x2013: 0x96, 0x2014: 0x97,
  0x02dc: 0x98, 0x2122: 0x99, 0x0161: 0x9a, 0x203a: 0x9b, 0x0153: 0x9c,
  0x017e: 0x9e, 0x0178: 0x9f,
  // windows-1254 (Turkish) replaces the Icelandic letters, and it is what the
  // stored catalog was actually decoded with, so it has to be reversed too.
  0x011e: 0xd0, 0x0130: 0xdd, 0x015e: 0xde, 0x011f: 0xf0, 0x0131: 0xfd, 0x015f: 0xfe,
};

// Every character that can appear when UTF-8 bytes are read with windows-1252
// or windows-1254. Missing entries here silently skip whole runs, which is why
// names such as "exa ⋆˚࿔" stayed broken.
const MOJIBAKE_RUN_PATTERN = /[\u0080-\u00ff\u011e\u0130\u015e\u011f\u0131\u015f\u0152\u0153\u0160\u0161\u0178\u017d\u017e\u0192\u02c6\u02dc\u2013\u2014\u2018-\u201e\u2020-\u2022\u2026\u2030\u2039\u203a\u20ac\u2122]+/g;

// A wrong code page leaves at least one of these behind; genuine accented text
// (for example "José") does not, so it is never rewritten. A run that fails the
// strict UTF-8 decode below is always left untouched.
const MOJIBAKE_TELL_PATTERN = /[\u0080-\u009f\u00c0-\u00ff\u011e\u011f\u0130\u0131\u015e\u015f]/;

function repairMojibakeText(value) {
  if (typeof value !== "string" || !MOJIBAKE_RUN_PATTERN.test(value)) return value;
  MOJIBAKE_RUN_PATTERN.lastIndex = 0;
  let text = value;
  for (let pass = 0; pass < 2; pass++) {
    let changed = false;
    text = text.replace(MOJIBAKE_RUN_PATTERN, run => {
      if (!MOJIBAKE_TELL_PATTERN.test(run)) return run;
      const bytes = [];
      for (const char of run) {
        const code = char.codePointAt(0);
        if (code <= 0xff) bytes.push(code);
        else if (Object.prototype.hasOwnProperty.call(MOJIBAKE_CP1252_BYTES, code)) bytes.push(MOJIBAKE_CP1252_BYTES[code]);
        else return run;
      }
      try {
        const decoded = new TextDecoder("utf-8", { fatal: true }).decode(new Uint8Array(bytes)).replace(/^\uFEFF/, "");
        if (!decoded || decoded === run) return run;
        changed = true;
        return decoded;
      } catch (_) { return run; }
    });
    if (!changed) break;
  }
  // A leading variation selector has no base character left, so the emoji it
  // belonged to was lost and only noise remains.
  return text.replace(/^[\uFE0E\uFE0F]+/, "");
}

function repairProductDisplayData(product) {
  if (!product || typeof product !== "object") return product;
  const textFields = ["name", "title", "description", "desc", "tags", "notes", "origin", "category", "resource_category", "creator_nickname", "creator_username", "uploader_name", "author_name", "release_date"];
  for (const field of textFields) if (typeof product[field] === "string") product[field] = repairMojibakeText(product[field]);
  const uploaderId = String(product.uploader_id || product.author_id || "");
  for (const field of ["uploader_avatar", "author_avatar", "creator_avatar"]) {
    const avatar = String(product[field] || "");
    const match = avatar.match(/^https?:\/\/(?:cdn\.discordapp\.com|media\.discordapp\.net)\/avatars\/(\d{17,20})\/((?:a_)?[a-z0-9_-]{16,})(?:\.(?:png|gif|webp|jpg|jpeg))?(?:[?#].*)?$/i);
    if (match) {
      const id = match[1] || uploaderId;
      const ext = match[2].startsWith("a_") ? "gif" : "png";
      product[field] = `/api/avatar/${id}/${match[2]}.${ext}?size=128`;
    }
  }
  return product;
}

// ── Canonical profile normalization ────────────────────────────────────────
// Every reader (resource/product/download pages) must receive the same shape so
// a resource never shows a creator photo on one page and nothing on another.

function socialUsernameFromUrl(value) {
  try {
    const url = new URL(String(value || "").trim());
    const parts = url.pathname.split("/").filter(Boolean);
    const handle = parts[parts.length - 1] || "";
    return handle.replace(/^@+/, "").trim();
  } catch (_) {
    return "";
  }
}

function toAbsoluteAvatarUrl(value, discordId) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  // A field that was assembled from a missing value must never turn into the
  // literal image request "/undefined".
  if (/^(undefined|null|nan|false|true|\[object object\])$/i.test(raw)) return "";
  if (raw.startsWith("/api/avatar/")) return raw;

  const bareHash = raw.match(/^(a_[a-z0-9_-]{16,}|[a-z0-9_-]{16,})$/i);
  if (bareHash) {
    if (!/^\d{17,20}$/.test(String(discordId || ""))) {
      // A bare hash with no owning Discord id cannot be resolved; returning it
      // would make clients request a bogus relative asset path.
      return "";
    }
    const ext = bareHash[1].startsWith("a_") ? "gif" : "png";
    return `/api/avatar/${discordId}/${bareHash[1]}.${ext}?size=128`;
  }

  const cdn = raw.match(/^https?:\/\/(?:cdn\.discordapp\.com|media\.discordapp\.net)\/avatars\/(\d{17,20})\/((?:a_)?[a-z0-9_-]{16,})(?:\.(?:png|gif|webp|jpg|jpeg))?/i);
  if (cdn) {
    const ext = cdn[2].startsWith("a_") ? "gif" : "png";
    return `/api/avatar/${cdn[1]}/${cdn[2]}.${ext}?size=128`;
  }

  // Guild-scoped avatar links stop resolving once the member leaves the guild,
  // so they are rewritten to the stable per-user form.
  const guildCdn = raw.match(/^https?:\/\/(?:cdn\.discordapp\.com|media\.discordapp\.net)\/guilds\/\d{17,20}\/users\/(\d{17,20})\/avatars\/((?:a_)?[a-z0-9_-]{16,})(?:\.(?:png|gif|webp|jpg|jpeg))?/i);
  if (guildCdn) {
    const ext = guildCdn[2].startsWith("a_") ? "gif" : "png";
    return `/api/avatar/${guildCdn[1]}/${guildCdn[2]}.${ext}?size=128`;
  }

  const embed = raw.match(/^https?:\/\/(?:cdn\.discordapp\.com|media\.discordapp\.net)\/embed\/avatars\/(\d+)\.png/i);
  if (embed) return `/api/avatar/default/${embed[1]}.png`;

  if (/^https?:\/\//i.test(raw)) return raw;
  return "";
}

// The uploader photo must come from Discord (or our own permanent copy of it).
// Social creator photos were previously stored in the uploader field as signed
// links, which both expired and credited the wrong person.
function toUploaderAvatarUrl(value, discordId) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  if (isCdnAvatarUrl(raw)) return raw;
  const resolved = toAbsoluteAvatarUrl(raw, discordId);
  if (!resolved) return "";
  return /^\/(?:api\/)?avatars?\//.test(resolved) ? resolved : "";
}

// The creator field is only a valid uploader avatar when it actually belongs to
// the uploader (legacy rows stored the uploader's Discord avatar there). A
// social creator's photo must never be shown as the uploader.
function creatorAvatarBelongsTo(value, uploaderId) {
  const raw = String(value || "").trim();
  if (!raw) return false;
  const owner = raw.match(/\/(?:avatars|avatar)\/(\d{17,20})\//i);
  if (owner) return owner[1] === String(uploaderId || "").trim();
  return /^(?:a_)?[a-z0-9_-]{16,}$/i.test(raw);
}

// Discord shows a stable placeholder derived from the user id, so the same
// uploader keeps the same fallback image on every page.
function defaultDiscordAvatarUrl(discordId) {
  const id = String(discordId || "").trim();
  if (!/^\d{17,20}$/.test(id)) return "";
  let index = 0;
  try {
    index = Number((BigInt(id) >> 22n) % 6n);
  } catch (_) {
    index = Number(id) % 5 || 0;
  }
  return `/api/avatar/default/${index}.png`;
}

// Uploader avatars are resolved from the shared Discord user cache so the same
// person renders identically on every page instead of varying per product.
// Only the Discord ids the caller actually needs are read, keeping the number
// of storage lookups proportional to the page instead of the whole cache.
async function loadDiscordAvatarMap(env, userIds = null) {
  const map = {};
  const now = Date.now();

  const addEntry = (userId, entry) => {
    if (!userId || !entry || !entry.user) return;
    if (entry.expires && now >= entry.expires) return;
    const user = entry.user;
    const hash = String(user.avatar || "").trim();
    let url = "";
    if (/^(?:a_)?[a-z0-9_-]{16,}$/i.test(hash)) {
      const ext = hash.startsWith("a_") ? "gif" : "png";
      url = `/api/avatar/${userId}/${hash}.${ext}?size=128`;
    } else {
      url = String(user.avatar_url || "").trim();
    }
    if (url) map[userId] = url;
  };

  try {
    if (!env || !env.STORAGE) return map;

    const legacy = await r2GetJSON(env, DISCORD_USER_R2_KEY, {});
    for (const [userId, entry] of Object.entries(legacy || {})) addEntry(userId, entry);

    const wanted = new Set();
    for (const candidate of userIds || []) {
      const id = String(candidate || "").trim();
      if (/^\d{17,20}$/.test(id) && !map[id]) wanted.add(id);
    }
    if (!wanted.size) return map;

    await Promise.all([...wanted].map(async userId => {
      addEntry(userId, await r2GetJSON(env, discordUserKey(userId), null));
    }));

    // Members with nothing stored on the server yet get their main profile fetched
    // once; the write above means later requests never touch the network for them.
    const missing = [...wanted].filter(userId => !map[userId]).slice(0, 8);
    await Promise.all(missing.map(async userId => {
      const user = await fetchDiscordUserProfile(env, userId);
      if (!user) return;
      await setCachedDiscordUser(env, userId, user);
      addEntry(userId, { user, expires: Date.now() + DISCORD_USER_CACHE_MS });
    }));
  } catch (_) {}
  return map;
}

function buildCreatorProfileIndex(profiles) {
  const index = { byAccount: {}, byUsername: {}, byUrl: {} };
  if (!profiles || typeof profiles !== "object" || Array.isArray(profiles)) return index;
  for (const [key, rawProfile] of Object.entries(profiles)) {
    if (!rawProfile || typeof rawProfile !== "object") continue;
    // Stored names may predate the code-page fix, so the index holds clean text.
    const profile = { ...rawProfile };
    for (const field of ["nickname", "username"]) {
      if (typeof profile[field] === "string") profile[field] = repairMojibakeText(profile[field]);
    }
    const platform = String(profile.platform || key.split(":")[0] || "").trim().toLowerCase();
    const accountId = String(profile.account_id || "").trim();
    const username = String(profile.username || "").trim().replace(/^@+/, "").toLowerCase();
    if (platform && accountId) index.byAccount[`${platform}:${accountId}`] = profile;
    if (username) index.byUsername[username] = profile;
    const url = canonicalCreatorUrl(profile.social_url);
    if (url) index.byUrl[url] = profile;
  }
  return index;
}

function findCreatorProfile(product, index) {
  if (!index || !product) return null;
  const platform = getCreatorPlatform(product);
  const accountId = String(product.creator_account_id || "").trim();
  if (platform && accountId && index.byAccount[`${platform}:${accountId}`]) {
    return index.byAccount[`${platform}:${accountId}`];
  }
  const username = String(product.creator_username || "").trim().replace(/^@+/, "").toLowerCase();
  if (username && index.byUsername[username]) return index.byUsername[username];
  const url = canonicalCreatorUrl(product.creator_social_url);
  if (url && index.byUrl[url]) return index.byUrl[url];
  return null;
}

// Social platforms hand out signed, short-lived avatar links that start
// returning 403 once they expire. Only our own re-hosted copy is permanent.
function isCdnAvatarUrl(value) {
  return /^https:\/\/thumbnail\.zyrexediting\.xyz\//i.test(String(value || "").trim());
}

// TikTok and ByteDance avatar links are signed with an expiry timestamp. Once it
// passes the image is a guaranteed 403, so a stored link that was never re-hosted
// is dropped instead of rendering a broken picture. Discord links are routed
// through our avatar proxy, which resolves the member's current photo.
const EXPIRING_AVATAR_HOSTS = /(?:^|\.)(?:tiktokcdn(?:-eu|-us|-va|-va\.ibytedtos)?\.com|ibytedtos\.com)$/i;

function stableAvatarUrl(value, discordId = "") {
  const raw = String(value || "").trim();
  if (!raw) return "";
  if (isCdnAvatarUrl(raw)) return raw;
  const resolved = toAbsoluteAvatarUrl(raw, discordId);
  if (!resolved) return "";
  if (resolved.startsWith("/")) return resolved;
  try {
    if (EXPIRING_AVATAR_HOSTS.test(new URL(resolved).hostname)) return "";
  } catch (_) {
    return "";
  }
  return resolved;
}

function normalizeResourceProfile(product, profileIndex, avatarMap) {
  if (!product || typeof product !== "object") return product;
  const item = { ...product };

  // 1. Prefer the stored social creator profile when the product lacks fields.
  const profile = findCreatorProfile(item, profileIndex);
  const profileAvatar = isCdnAvatarUrl(profile?.avatar) ? String(profile.avatar).trim() : "";
  if (profile) {
    if (!String(item.creator_platform || "").trim() && profile.platform) item.creator_platform = profile.platform;
    if (!String(item.creator_account_id || "").trim() && profile.account_id) item.creator_account_id = profile.account_id;
    if (!String(item.creator_username || "").trim() && profile.username) item.creator_username = profile.username;
    if (!String(item.creator_nickname || "").trim() && profile.nickname) item.creator_nickname = profile.nickname;
    if (!String(item.creator_social_url || "").trim() && profile.social_url) item.creator_social_url = profile.social_url;

    // The registry copy is permanent, so it replaces both a missing value and a
    // stale external link that would otherwise render as a broken image.
    const storedCreatorAvatar = String(item.creator_avatar || "").trim();
    if (profileAvatar && (!storedCreatorAvatar || !isCdnAvatarUrl(storedCreatorAvatar))) {
      item.creator_avatar = profileAvatar;
    } else if (!storedCreatorAvatar) {
      item.creator_avatar = String(profile.avatar || "").trim();
    }
  }

  // 2. Creator identity always present and valid.
  if (!String(item.creator_username || "").trim()) {
    item.creator_username = socialUsernameFromUrl(item.creator_social_url);
  }
  if (!String(item.creator_nickname || "").trim()) {
    item.creator_nickname = String(item.author_name || item.uploader_name || "").trim() || "Zyrex Creator";
  }
  if (!String(item.creator_social_url || "").trim()) {
    item.creator_social_url = canonicalCreatorProfileUrl(
      { ...item, creator_username: item.creator_username },
      ""
    );
  }

  const uploaderId = String(item.uploader_id || item.author_id || "").trim();
  const discordId = /^\d{17,20}$/.test(uploaderId) ? uploaderId : "";
  item.creator_avatar = toAbsoluteAvatarUrl(item.creator_avatar, discordId);

  // 3. Uploader identity mirrors credited uploader or author/creator so no page renders empty.
  if (!item.is_anonymous && String(item.credited_uploader_id || "").trim()) {
    const cId = String(item.credited_uploader_id).trim();
    if (/^\d{17,20}$/.test(cId)) {
      item.uploader_id = cId;
      item.author_id = cId;
      if (String(item.credited_uploader_name || "").trim()) {
        item.uploader_name = String(item.credited_uploader_name).trim();
        item.author_name = String(item.credited_uploader_name).trim();
      }
      if (String(item.credited_uploader_avatar || "").trim()) {
        item.uploader_avatar = String(item.credited_uploader_avatar).trim();
        item.author_avatar = String(item.credited_uploader_avatar).trim();
      }
    }
  }
  if (!String(item.uploader_id || "").trim()) item.uploader_id = String(item.author_id || "").trim();
  if (!String(item.uploader_name || "").trim()) {
    item.uploader_name = String(item.author_name || "").trim() || String(item.creator_nickname || "").trim();
  }
  const resolvedUploaderId = String(item.uploader_id || item.author_id || "").trim();
  const knownUploaderAvatar = (avatarMap && avatarMap[resolvedUploaderId]) || "";
  const uploaderAvatarSource = item.uploader_avatar || item.author_avatar
    || (creatorAvatarBelongsTo(item.creator_avatar, resolvedUploaderId) ? item.creator_avatar : "");
  const uploaderAvatar = knownUploaderAvatar
    || toUploaderAvatarUrl(uploaderAvatarSource, resolvedUploaderId)
    || defaultDiscordAvatarUrl(resolvedUploaderId);
  item.uploader_avatar = uploaderAvatar;
  if (!String(item.author_avatar || "").trim()) item.author_avatar = uploaderAvatar;
  if (!String(item.author_name || "").trim()) item.author_name = String(item.uploader_name || "").trim();
  if (!String(item.author_id || "").trim()) item.author_id = String(item.uploader_id || "").trim();

  const creatorHasSocialIdentity = Boolean(
    String(item.creator_platform || item.creator_social_url || item.creator_account_id || item.creator_username || "").trim()
  );
  const creatorAvatarValue = String(item.creator_avatar || "").trim();
  const uploaderAvatarValues = [item.uploader_avatar, item.author_avatar, item.credited_uploader_avatar]
    .map(value => String(value || "").trim())
    .filter(Boolean);
  if (creatorHasSocialIdentity && (
    creatorAvatarBelongsTo(creatorAvatarValue, resolvedUploaderId) ||
    uploaderAvatarValues.includes(creatorAvatarValue)
  )) item.creator_avatar = "";

  // Admin status is derived from the current uploader ID. Never trust
  // a persisted badge flag: attribution can change after an upload is edited.
  item.uploader_is_admin = !item.is_anonymous && ADMIN_IDS.includes(resolvedUploaderId);

  // Anonymous resources hide whoever uploaded them, but the social creator is
  // a different person whose credit (and photo) must stay visible.
  if (item.is_anonymous) {
    const sourceUploaderName = String(item.uploader_name || item.author_name || "").trim();
    const sourceUploaderId = String(item.uploader_id || item.author_id || "").trim();
    item.uploader_name = "Anonymous";
    item.author_name = "Anonymous";
    item.uploader_avatar = "";
    item.author_avatar = "";
    item.uploader_id = "";
    item.author_id = "";
    item.uploader_is_admin = false;

    const creatorName = String(item.creator_nickname || "").trim();
    if (!creatorName || creatorName.toLowerCase() === sourceUploaderName.toLowerCase()) {
      item.creator_nickname = "Zyrex Creator";
    }
    if (!isCdnAvatarUrl(item.creator_avatar) && creatorAvatarBelongsTo(item.creator_avatar, sourceUploaderId)) {
      item.creator_avatar = "";
    }
  }
  return item;
}

// One-shot repair for legacy rows. Two defects left resources without a creator
// photo: social avatar links were stored as raw, signed CDN URLs that start
// returning 403, and creators resolved from a URL alone had no account id so
// their profile was never written to the registry.
async function repairCreatorAvatars(env, options = {}) {
  const dryRun = options.dryRun !== false;
  const rescrape = options.rescrape === true;
  const limit = Math.min(Math.max(Number(options.limit) || 25, 1), 500);
  const onlyId = String(options.id || "").trim();

  const catalogObject = await env.STORAGE.get(DB.PRODUCTS);
  if (!catalogObject) throw new Error("Product catalog is unavailable");
  const catalog = await catalogObject.json();
  if (!Array.isArray(catalog)) throw new Error("Product catalog data is invalid");

  const storedProfiles = await r2GetJSON(env, CREATOR_PROFILES_KEY, {});
  const profiles = storedProfiles && typeof storedProfiles === "object" && !Array.isArray(storedProfiles)
    ? { ...storedProfiles }
    : {};
  const index = buildCreatorProfileIndex(profiles);

  const report = {
    dry_run: dryRun, rescrape, limit,
    examined: 0, repaired: 0, reused_registry: 0, rehosted: 0, rescraped: 0,
    profiles_added: 0, skipped_no_creator: 0, failed: [],
  };

  for (let i = 0; i < catalog.length; i++) {
    const product = catalog[i];
    if (!product || typeof product !== "object" || !product.id) continue;
    if (onlyId && String(product.id) !== onlyId) continue;
    if (product.is_anonymous) continue;
    if (isCdnAvatarUrl(product.creator_avatar)) continue;
    if (report.repaired >= limit) break;

    const socialUrl = String(product.creator_social_url || "").trim();
    const storedUsername = String(product.creator_username || "").trim();
    if (!socialUrl && !storedUsername) {
      report.skipped_no_creator++;
      continue;
    }

    report.examined++;
    const profile = findCreatorProfile(product, index);
    const currentAvatar = String(product.creator_avatar || "").trim();

    let platform = getCreatorPlatform(product) || String(profile?.platform || "").trim();
    let accountId = String(product.creator_account_id || profile?.account_id || "").trim();
    let username = storedUsername || String(profile?.username || "").trim();
    let nickname = String(product.creator_nickname || profile?.nickname || "").trim();
    let avatar = isCdnAvatarUrl(profile?.avatar) ? String(profile.avatar).trim() : "";
    if (avatar) report.reused_registry++;

    // A stored external link can still be alive, so re-host it before scraping.
    if (!avatar && /^https?:\/\//i.test(currentAvatar)) {
      const reHosted = await storeAndProxyImage(env, currentAvatar).catch(() => "");
      if (isCdnAvatarUrl(reHosted)) {
        avatar = reHosted;
        report.rehosted++;
      }
    }

    if (!avatar && rescrape && socialUrl && platform) {
      const resolved = await resolveSocialProfile(socialUrl, env).catch(() => null);
      if (resolved?.success) {
        report.rescraped++;
        if (isCdnAvatarUrl(resolved.avatar)) avatar = resolved.avatar;
        if (resolved.account_id) accountId = String(resolved.account_id);
        if (resolved.username) username = String(resolved.username);
        const resolvedNickname = String(resolved.nickname || "").trim();
        if (resolvedNickname) nickname = resolvedNickname;
        if (resolved.platform) platform = resolved.platform;
      }
    }

    if (!avatar) {
      if (report.failed.length < 25) {
        report.failed.push({ id: product.id, reason: platform ? "no avatar resolved" : "creator platform unknown" });
      }
      continue;
    }

    catalog[i] = {
      ...product,
      creator_avatar: avatar,
      creator_platform: platform || product.creator_platform,
      creator_account_id: accountId || product.creator_account_id,
      creator_username: username || product.creator_username,
      creator_nickname: nickname || product.creator_nickname,
    };

    const profileKey = creatorProfileKey(platform, accountId, username);
    if (profileKey) {
      const previous = profiles[profileKey] || {};
      if (!storedProfiles[profileKey]) report.profiles_added++;
      profiles[profileKey] = {
        ...previous,
        platform: platform || previous.platform,
        account_id: accountId || previous.account_id || "",
        username: username || previous.username || "",
        nickname: nickname || previous.nickname || "",
        avatar,
        social_url: String(catalog[i].creator_social_url || previous.social_url || "").trim(),
        updated_at: new Date().toISOString(),
      };
    }
    report.repaired++;
  }

  if (!dryRun && report.repaired > 0) {
    await r2PutJSON(env, DB.PRODUCTS, catalog);
    await r2PutJSON(env, CREATOR_PROFILES_KEY, profiles);
  }
  return report;
}

// Legacy uploader photos were stored as either a social creator's signed photo
// or a guild-scoped Discord link, so they showed the wrong person and then
// stopped loading. Both shapes are rewritten to the uploader's own Discord
// avatar, which every page resolves identically.
async function repairUploaderAvatars(env, options = {}) {
  const dryRun = options.dryRun !== false;
  const limit = Math.min(Math.max(Number(options.limit) || 50, 1), 500);
  const onlyId = String(options.id || "").trim();

  const catalog = await dbReadProductCatalog(env);
  const avatarMap = await loadDiscordAvatarMap(
    env,
    catalog.map(product => product && (product.uploader_id || product.author_id))
  );

  const report = { dry_run: dryRun, limit, examined: 0, repaired: 0, from_discord_cache: 0, from_default: 0, cleared: 0, failed: [] };

  const isPlaceholder = value => /^\/api\/avatar\/default\//.test(String(value || ""));

  for (let i = 0; i < catalog.length; i++) {
    const product = catalog[i];
    if (!product || typeof product !== "object" || !product.id) continue;
    if (onlyId && String(product.id) !== onlyId) continue;
    if (product.is_anonymous) continue;
    if (report.repaired >= limit) break;

    const uploaderId = String(product.uploader_id || product.author_id || "").trim();
    const storedUploader = String(product.uploader_avatar || "").trim();
    const storedAuthor = String(product.author_avatar || "").trim();

    // A real Discord avatar from the shared user cache is always preferable, so
    // an earlier placeholder is upgraded once the profile becomes available. A
    // photo already on our own CDN is permanent and is kept as-is.
    const knownAvatar = toUploaderAvatarUrl((avatarMap && avatarMap[uploaderId]) || "", uploaderId);
    const desired = isCdnAvatarUrl(storedUploader)
      ? storedUploader
      : (knownAvatar
        || toUploaderAvatarUrl(storedUploader, uploaderId)
        || toUploaderAvatarUrl(storedAuthor, uploaderId)
        || defaultDiscordAvatarUrl(uploaderId));

    const upgradePlaceholder = !!knownAvatar && isPlaceholder(storedUploader) && knownAvatar !== storedUploader;
    if (!upgradePlaceholder && storedUploader === desired && storedAuthor === desired) continue;

    report.examined++;
    if (knownAvatar && desired === knownAvatar) report.from_discord_cache++;
    else if (!desired) report.cleared++;
    else if (isPlaceholder(desired)) report.from_default++;

    if (!desired && !storedUploader && !storedAuthor) continue;

    catalog[i] = {
      ...product,
      uploader_avatar: desired,
      author_avatar: desired,
    };
    report.repaired++;
  }

  if (!dryRun && report.repaired > 0) {
    await r2PutJSON(env, DB.PRODUCTS, catalog);
  }
  return report;
}

function normalizeDiscordProfileAvatar(user, userId) {
  if (!user || typeof user !== "object") return user;
  const hash = String(user.avatar || "").trim();
  if (hash && /^(?:a_)?[a-z0-9_-]{16,}$/i.test(hash)) {
    const ext = hash.startsWith("a_") ? "gif" : "png";
    user.avatar_url = `/api/avatar/${encodeURIComponent(userId)}/${encodeURIComponent(hash)}.${ext}?size=128`;
  } else {
    const directUrl = String(user.avatar_url || "");
    const match = directUrl.match(/^https?:\/\/(?:cdn\.discordapp\.com|media\.discordapp\.net)\/avatars\/(\d{17,20})\/((?:a_)?[a-z0-9_-]{16,})(?:\.(?:png|gif|webp|jpg|jpeg))?/i);
    if (match) {
      const ext = match[2].startsWith("a_") ? "gif" : "png";
      user.avatar_url = `/api/avatar/${match[1]}/${match[2]}.${ext}?size=128`;
    } else {
      const defaultMatch = directUrl.match(/^https?:\/\/(?:cdn\.discordapp\.com|media\.discordapp\.net)\/embed\/avatars\/(\d+)\.png/i);
      if (defaultMatch) user.avatar_url = `/api/avatar/default/${defaultMatch[1]}.png`;
    }
  }
  const bannerHash = String(user.banner || "").trim();
  if (bannerHash && /^(?:a_)?[a-z0-9_-]{16,}$/i.test(bannerHash)) {
    const bannerExt = bannerHash.startsWith("a_") ? "gif" : "png";
    user.banner_url = `/api/banner/${encodeURIComponent(userId)}/${encodeURIComponent(bannerHash)}.${bannerExt}?size=600`;
  } else {
    user.banner_url = "";
  }
  for (const field of ["display_name", "global_name", "username", "name"]) {
    if (typeof user[field] === "string") user[field] = repairMojibakeText(user[field]);
  }
  return user;
}

function canonicalCreatorUrl(value) {
  try {
    const url = new URL(String(value || "").trim());
    url.search = "";
    url.hash = "";
    url.hostname = url.hostname.toLowerCase().replace(/^www\./, "");
    url.pathname = url.pathname.replace(/\/+$/, "");
    return url.toString().toLowerCase();
  } catch (_) { return ""; }
}

function canonicalCreatorProfileUrl(profile, fallbackUrl = "") {
  const platform = getCreatorPlatform(profile);
  const username = String(profile?.creator_username || profile?.username || "").trim().replace(/^@+/, "");
  const accountId = String(profile?.creator_account_id || profile?.account_id || "").trim();
  if (platform === "tiktok" && username) return `https://www.tiktok.com/@${encodeURIComponent(username)}`;
  if (platform === "instagram" && username) return `https://www.instagram.com/${encodeURIComponent(username)}`;
  if (platform === "x" && username) return `https://x.com/${encodeURIComponent(username)}`;
  if (platform === "youtube" && /^UC[\w-]{20,}$/.test(accountId)) return `https://www.youtube.com/channel/${accountId}`;
  return String(fallbackUrl || profile?.creator_social_url || profile?.social_url || "").trim();
}

async function dbDeleteProduct(env, id) {
  const products = await dbReadProductCatalog(env);
  const idx = products.findIndex(p => p.id === id);
  if (idx === -1) return false;
  products.splice(idx, 1);
  await dbSaveProducts(env, products);
  await invalidateCatalogVersion(env);
  return true;
}

async function completeMatchingRequestForProduct(env, product) {
  if (!env.STORAGE) throw new Error("Request storage is unavailable");
  const object = await env.STORAGE.get("requests/data.json");
  if (!object) return;
  const data = await object.json();
  const requests = Array.isArray(data) ? data : data?.requests;
  if (!Array.isArray(requests)) throw new Error("Request data has an invalid format");

  const explicitId = String(product.request_id || "");
  let target = explicitId
    ? requests.find(item => String(item.id) === explicitId && !["completed", "rejected"].includes(String(item.status || "pending").toLowerCase()))
    : null;
  if (!target) target = findBestRequestForResource(product, requests);
  if (!target) return;

  const completedAt = new Date().toISOString();
  target.status = "completed";
  target.completed_at = target.completed_at || completedAt;
  target.updated_at = completedAt;
  target.resource_id = product.id;
  target.resource_url = `/leak?id=${encodeURIComponent(product.id)}`;
  await env.STORAGE.put("requests/data.json", JSON.stringify({
    requests,
    total: requests.length,
    updated_at: completedAt,
  }), { httpMetadata: { contentType: "application/json" } });

  try {
    const response = await fetch(`${BOT_API}/api/requests/announce-completed`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        message_id: target.discord_message_id || "",
        channel_id: target.discord_channel_id || "1551118401508745367",
        title: target.title || "Request",
        resource_url: target.resource_url,
        req_id: target.id,
        thumbnail: target.thumbnail || "",
        user_id: target.user_id || "",
        user_name: target.user_name || "",
      }),
      signal: AbortSignal.timeout(1500),
    });
    if (!response.ok) console.warn("Request completion Discord sync failed:", response.status);
  } catch (error) {
    console.warn("Request completion Discord sync failed:", error?.message || String(error));
  }
}

// --- Stats (views + downloads per preset) ---
async function dbGetStats(env) {
  const data = await r2GetJSON(env, DB.STATS, {});
  return typeof data === 'object' && !Array.isArray(data) ? data : {};
}

async function dbGetPresetStats(env, id) {
  const stats = await dbGetStats(env);
  return stats[id] || { views: 0, downloads: 0, likes: 0 };
}

async function dbIncrementView(env, id) {
  const stats = await dbGetStats(env);
  if (!stats[id]) stats[id] = { views: 0, downloads: 0, likes: 0 };
  stats[id].views = (stats[id].views || 0) + 1;
  await r2PutJSON(env, DB.STATS, stats);
  return stats[id];
}

async function dbIncrementDownload(env, id) {
  const stats = await dbGetStats(env);
  if (!stats[id]) stats[id] = { views: 0, downloads: 0, likes: 0 };
  stats[id].downloads = (stats[id].downloads || 0) + 1;
  await r2PutJSON(env, DB.STATS, stats);
  return stats[id];
}

// --- Download counts ---
async function dbGetDownloadCounts(env) {
  const data = await r2GetJSON(env, DB.DOWNLOADS, { counts: {} });
  return data && data.counts ? data : { success: true, counts: {} };
}

async function dbIncrementDownloadCount(env, productId) {
  const data = await dbGetDownloadCounts(env);
  if (!data.counts) data.counts = {};
  data.counts[productId] = (data.counts[productId] || 0) + 1;
  await r2PutJSON(env, DB.DOWNLOADS, data);
  return data.counts[productId];
}

// Mirrors the archive in small capped indexes so a lookup never scans the whole
// history, and no single object has to be rewritten as the archive grows.
function parseClientDevice(userAgent) {
  const ua = String(userAgent || "");
  const device = { browser: "", browser_version: "", os: "", os_version: "", device: "", is_mobile: false, is_bot: false };
  if (!ua) return device;

  // App browsers are checked first: they reuse a platform engine and would
  // otherwise be reported as the underlying browser, which matters when a
  // download fails inside someone's in-app browser.
  const appRules = [
    ["Google App", /GSA\/([\d.]+)/],
    ["Instagram", /Instagram ([\d.]+)/],
    ["Facebook", /FBAN\/\w+;FBAV\/([\d.]+)/],
    ["X App", /Twitter(?:Android|iPhone)?\/([\d.]+)/],
    ["TikTok", /(?:musical_ly|BytedanceWebview|TikTok)[/ ]?([\d.]+)?/],
    ["Snapchat", /Snapchat\/([\d.]+)/],
    ["Discord", /Discord\/([\d.]+)/],
    ["LINE", /Line\/([\d.]+)/],
    ["Chrome (iOS)", /CriOS\/([\d.]+)/],
    ["Firefox (iOS)", /FxiOS\/([\d.]+)/],
    ["Edge (iOS)", /EdgiOS\/([\d.]+)/],
    ["Safari", /Version\/([\d.]+).*Safari/],
  ];
  for (const [name, pattern] of appRules) {
    const match = ua.match(pattern);
    if (match) { device.browser = name; device.browser_version = match[1] || ""; break; }
  }

  const browserRules = [
    ["Edge", /Edg(?:e|A|iOS)?\/([\d.]+)/],
    ["Opera", /OPR\/([\d.]+)/],
    ["Samsung Internet", /SamsungBrowser\/([\d.]+)/],
    ["Chrome", /Chrome\/([\d.]+)/],
    ["Firefox", /Firefox\/([\d.]+)/],
  ];
  for (const [name, pattern] of browserRules) {
    if (device.browser) break;
    const match = ua.match(pattern);
    if (match) { device.browser = name; device.browser_version = match[1]; break; }
  }
  const osRules = [
    ["Windows", /Windows NT ([\d.]+)/],
    ["Android", /Android ([\d.]+)/],
    ["iOS", /(?:iPhone|iPad|iPod) OS ([\d_]+)/],
    ["macOS", /Mac OS X ([\d_.]+)/],
    ["Linux", /Linux/],
  ];
  for (const [name, pattern] of osRules) {
    const match = ua.match(pattern);
    if (match) { device.os = name; device.os_version = String(match[1] || "").replace(/_/g, "."); break; }
  }
  if (/Android|iPhone|iPod|Mobile/i.test(ua)) device.device = "Phone";
  else if (/iPad|Tablet/i.test(ua)) device.device = "Tablet";
  else if (/Windows|Macintosh|Linux/i.test(ua)) device.device = "Desktop";
  device.is_mobile = /Mobile|Android|iPhone|iPod/i.test(ua);
  device.is_bot = /bot|crawler|spider|headless|python-requests|curl|wget/i.test(ua);
  return device;
}

function downloadRecordKey(createdAt, id) {
  const day = String(createdAt || "").slice(0, 10) || new Date().toISOString().slice(0, 10);
  return DL_ARCHIVE.RECORD_PREFIX + day + "/" + id + ".json";
}

function downloadIndexEntry(entry, key) {
  return {
    id: entry.id,
    key,
    product_id: entry.product_id,
    product_name: entry.product_name,
    category: entry.category,
    resource_type: entry.resource_type,
    user_id: entry.user_id,
    username: entry.username,
    display_name: entry.display_name,
    user_avatar: entry.user_avatar,
    country: entry.country,
    ip: entry.ip,
    file_count: entry.file_count,
    total_bytes: entry.total_bytes,
    total_size: entry.total_size,
    browser: entry.device?.browser || "",
    os: entry.device?.os || "",
    access_label: entry.access?.label || "",
    token_id: entry.token_id || "",
    created_at: entry.created_at,
  };
}

async function pushArchiveIndex(env, indexKey, summary, limit) {
  const stored = await r2GetJSON(env, indexKey, []);
  const rows = Array.isArray(stored) ? stored : [];
  rows.unshift(summary);
  await r2PutJSON(env, indexKey, rows.slice(0, limit));
}

async function archiveDownloadEntry(env, entry) {
  const key = downloadRecordKey(entry.created_at, entry.id);

  // A directory of everyone who ever downloaded, so the archive can be browsed
  // per member without knowing their id up front. Reading it first also yields
  // this member's running download number for the entry.
  let memberIndex = 0;
  if (entry.user_id) {
    const stored = await r2GetJSON(env, DL_ARCHIVE.USERS, {});
    const directory = stored && typeof stored === "object" && !Array.isArray(stored) ? stored : {};
    const current = directory[entry.user_id] || {};
    memberIndex = (Number(current.count) || 0) + 1;
    directory[entry.user_id] = {
      count: memberIndex,
      first_at: current.first_at || entry.created_at,
      last_at: entry.created_at,
      username: entry.username || current.username || "",
      display_name: entry.display_name || current.display_name || "",
      user_avatar: entry.user_avatar || current.user_avatar || "",
    };
    await r2PutJSON(env, DL_ARCHIVE.USERS, directory);
  }

  const summary = downloadIndexEntry(entry, key);
  summary.member_download_index = memberIndex;
  await r2PutJSON(env, key, { ...entry, key, member_download_index: memberIndex });

  // A tiny pointer makes any record reachable from its archive id alone.
  await r2PutJSON(env, DL_ARCHIVE.ID_PREFIX + entry.id + ".json", {
    id: entry.id,
    key,
    product_id: entry.product_id,
    product_name: entry.product_name,
    user_id: entry.user_id,
    created_at: entry.created_at,
    member_download_index: memberIndex,
  });

  await pushArchiveIndex(env, DL_ARCHIVE.RECENT, summary, DL_ARCHIVE.RECENT_LIMIT);
  if (summary.user_id) {
    await pushArchiveIndex(env, DL_ARCHIVE.USER_INDEX_PREFIX + summary.user_id + ".json", summary, DL_ARCHIVE.INDEX_LIMIT);
  }
  if (summary.product_id) {
    await pushArchiveIndex(env, DL_ARCHIVE.PRODUCT_INDEX_PREFIX + summary.product_id + ".json", summary, DL_ARCHIVE.INDEX_LIMIT);
  }
  return summary;
}

// Callers send either plain names or objects carrying a size. Both are archived,
// and a total is only claimed when the sizes are actually known.
function normalizeSelectedFiles(input) {
  const rows = Array.isArray(input) ? input : [];
  const files = [];
  let totalBytes = 0;
  let sizedCount = 0;
  for (const row of rows.slice(0, 400)) {
    if (row && typeof row === "object") {
      const name = String(row.name || row.path || "").trim();
      if (!name) continue;
      const size = Number(row.size) || 0;
      if (size > 0) { totalBytes += size; sizedCount++; files.push({ name, size }); }
      else files.push({ name });
    } else {
      const name = String(row == null ? "" : row).trim();
      if (name) files.push({ name });
    }
  }
  return { files, count: files.length, totalBytes, sizedCount };
}

function makeDiscordAvatarUrl(userId, avatar, size = 128) {
  const raw = String(avatar || "").trim();
  if (/^https:\/\//i.test(raw)) return raw;
  if (userId && raw) {
    const ext = raw.startsWith("a_") ? "gif" : "png";
    return `https://cdn.discordapp.com/avatars/${userId}/${raw}.${ext}?size=${size}`;
  }
  let index = 0;
  try { index = Number((BigInt(String(userId || "0")) >> 22n) % 6n); } catch (_) {}
  return `https://cdn.discordapp.com/embed/avatars/${index}.png`;
}

async function resolveDownloadIdentity(env, userId, session, avatarOverride = "") {
  const id = String(userId || "");
  const current = {
    username: session?.username || "",
    display_name: session?.displayName || session?.globalName || session?.username || "Guest User",
    user_avatar: makeDiscordAvatarUrl(id, session?.avatar || avatarOverride, 128),
  };
  if (!id || (current.username && (session?.avatar || /^https:\/\//i.test(String(avatarOverride || ""))))) return current;
  const logBotToken = getSiteLogBotToken(env);
  if (!logBotToken) return current;
  try {
    const response = await fetch(`${DISCORD_API}/users/${encodeURIComponent(id)}`, {
      headers: { Authorization: `Bot ${logBotToken}` },
      signal: AbortSignal.timeout(3000),
    });
    if (!response.ok) return current;
    const user = await response.json();
    return {
      username: user.username || current.username,
      display_name: user.global_name || user.username || current.display_name,
      user_avatar: makeDiscordAvatarUrl(id, user.avatar, 128),
    };
  } catch (_) { return current; }
}

async function recordDownloadEvent(env, request, details) {
  const productId = String(details.product_id || "").trim();
  if (!productId) throw new Error("Product ID required for download log");

  const tokenId = String(details.token_id || "").trim();
  // One download can reach us three times (bot relay, client track call, zip
  // completion), so a token-scoped marker keeps it to a single archive entry.
  const dedupeKey = tokenId ? DL_ARCHIVE.DEDUPE_PREFIX + encodeURIComponent(tokenId + "__" + productId) + ".json" : "";
  if (dedupeKey) {
    const previous = await r2GetJSON(env, dedupeKey, null);
    if (previous?.id) {
      const product = await dbGetProduct(env, productId);
      const countsData = await dbGetDownloadCounts(env);
      return {
        entry: previous.entry || previous,
        summary: previous.summary || null,
        count: Number(countsData?.counts?.[productId]) || 0,
        product,
        isNew: false,
      };
    }
  }

  const product = await dbGetProduct(env, productId);
  const countsData = await dbGetDownloadCounts(env);
  const currentCount = Number(countsData?.counts?.[productId]) || 0;
  const session = parseSession(request.headers.get("Cookie"), request);
  const userId = session?.userId || String(details.user_id || "");
  const identity = await resolveDownloadIdentity(env, userId, session, details.user_avatar || "");
  if (!identity.username && details.username) identity.username = cleanErrorField(details.username, 80);
  if ((!identity.display_name || identity.display_name === "Guest User") && details.display_name) identity.display_name = cleanErrorField(details.display_name, 100);

  const createdAt = new Date().toISOString();
  const cf = request.cf || {};
  const userAgent = String(request.headers.get("user-agent") || "");
  const selected = normalizeSelectedFiles(details.selected_files || details.files);
  const resourceType = String(details.resource_type || product?.type || "").toLowerCase().slice(0, 40);

  const entry = {
    id: generateId("dl"),
    product_id: productId,
    product_name: String(details.product_name || product?.name || productId).slice(0, 180),
    category: String(details.category || product?.resource_category || product?.category || "resource").slice(0, 80),
    resource_type: resourceType,
    user_id: userId,
    username: identity.username,
    display_name: identity.display_name,
    user_avatar: identity.user_avatar,
    files: selected.files,
    file_count: selected.count,
    total_bytes: selected.totalBytes,
    total_size: selected.totalBytes > 0 ? formatSizeR2(selected.totalBytes) : "",
    ip: String(details.ip || request.headers.get("cf-connecting-ip") || ""),
    country: String(details.country || cf.country || ""),
    city: String(cf.city || ""),
    region: String(cf.region || ""),
    timezone: String(cf.timezone || ""),
    asn: cf.asn ?? null,
    as_organization: String(cf.asOrganization || ""),
    colo: String(cf.colo || ""),
    http_protocol: String(cf.httpProtocol || ""),
    device: parseClientDevice(userAgent),
    user_agent: userAgent,
    access: {
      label: String(details.access_label || (tokenId ? RESOURCE_ACCESS_LABEL + " pass" : "Session")),
      token_id: tokenId,
      source: String(details.access_source || "website"),
    },
    token_id: tokenId,
    ray_id: String(request.headers.get("cf-ray") || ""),
    created_at: createdAt,
  };

  const summary = await archiveDownloadEntry(env, entry);
  if (dedupeKey) await r2PutJSON(env, dedupeKey, { id: entry.id, entry, summary, created_at: createdAt });
  await dbIncrementDownloadCount(env, productId);
  await dbIncrementDownload(env, productId);
  return { entry, summary, count: currentCount + 1, product, isNew: true };
}

function discordField(name, value, inline) {
  const text = String(value == null ? "" : value).trim();
  return { name: String(name).slice(0, 250), value: (text || "—").slice(0, 1024), inline: Boolean(inline) };
}

function discordTime(iso) {
  const ms = Date.parse(String(iso || ""));
  return Number.isFinite(ms) ? Math.floor(ms / 1000) : 0;
}

// "Preset" names one type of resource, not the whole catalogue, so product
// notifications must not call every resource a preset. Older bot builds still
// send the old wording, so the label is normalised once here at the edge.
function normalizeProductNotification(item) {
  if (!item || typeof item !== "object") return item;
  if (!String(item.id || "").startsWith("prod_")) return item;
  const normalized = { ...item };
  if (normalized.title) {
    normalized.title = String(normalized.title)
      .replace(/^New Preset:/, "New Leak:")
      .replace(/^New Resource:/, "New Leak:");
  }
  if (normalized.category === "preset") normalized.category = "resource";
  const legacyLink = String(normalized.link || "");
  if (legacyLink.startsWith("/preset?")) {
    normalized.link = "/leak?" + legacyLink.slice("/preset?".length);
  } else if (legacyLink.startsWith("/resource?")) {
    normalized.link = "/leak?" + legacyLink.slice("/resource?".length);
  } else if (legacyLink.startsWith("/resources?") || legacyLink === "/resources") {
    normalized.link = "/leaks" + legacyLink.slice("/resources".length);
  }
  return normalized;
}

function normalizeProductNotifications(list) {
  return Array.isArray(list) ? list.map(normalizeProductNotification) : list;
}

function filterAccountNotifications(list, notificationPrefs, followPrefs) {
  const prefs = notificationPrefs && typeof notificationPrefs === "object" ? notificationPrefs : {};
  const follows = followPrefs && typeof followPrefs === "object" ? followPrefs : {};
  if (prefs.dnd === true) return [];
  return (Array.isArray(list) ? list : []).filter(item => {
    const category = String(item && item.category || "announcement").toLowerCase();
    const type = String(item && item.type || "").toLowerCase();
    if (category === "audio" || type === "audio") return prefs.audio !== false;
    if (["plugin", "software"].includes(category) || ["plugin", "software"].includes(type)) return prefs.plugins !== false;
    if (["resource", "leak", "preset", "scenepack"].includes(category)) return prefs.leaks !== false;
    if (["post", "feed"].includes(category) || type === "post") return prefs.feed !== false && follows.site !== false;
    if (["mention", "reply", "comment"].includes(category) || ["mention", "reply", "comment"].includes(type)) return prefs.replies !== false;
    return prefs.announcements !== false;
  });
}

// Every field an archive needs to answer "who downloaded what, when, and from
// where". Kept in one embed so a single message is the whole record.
async function postDownloadLogToDiscord(env, record) {
  if (!record?.entry) return false;
  const entry = record.entry;
  const summary = record.summary || downloadIndexEntry(entry, entry.key || "");
  const logBotToken = getSiteLogBotToken(env);
  if (!logBotToken) {
    console.error("Discord download logging failed: SITE_LOG_BOT_TOKEN is not configured");
    return false;
  }
  const product = record.product || {};
  const productType = String(product.type || entry.resource_type || "").toLowerCase();
  const productPath = productType.includes("scenepack") ? "product-scenepack" : productType.includes("audio") ? "product-audio" : productType.includes("plugin") || productType.includes("software") ? "product" : "resource";
  const siteUrl = `https://zyrexediting.xyz/${productPath}?id=${encodeURIComponent(entry.product_id)}`;
  const displayName = [entry.display_name, entry.username ? `@${entry.username}` : ""].filter(Boolean).join(" ").slice(0, 180);
  const second = discordTime(entry.created_at);

  const device = entry.device || {};
  const deviceLine = [device.browser, device.browser_version].filter(Boolean).join(" ");
  const deviceText = [deviceLine, [device.os, device.os_version].filter(Boolean).join(" "), device.device]
    .filter(Boolean).join(" • ") || "Unknown device";

  const originParts = [
    entry.country ? `:flag_${String(entry.country).toLowerCase()}: ${entry.country}` : "",
    [entry.city, entry.region].filter(Boolean).join(", "),
    entry.as_organization ? `ISP: ${entry.as_organization}${entry.asn ? ` (AS${entry.asn})` : ""}` : "",
    entry.ip ? `IP: ||\`${entry.ip}\`||` : "",
  ].filter(Boolean);

  const files = Array.isArray(entry.files) ? entry.files : [];
  const fileList = files.slice(0, 12).map(file => `• ${String(file.name || "").slice(0, 90)}${file.size ? ` — ${formatSizeR2(file.size)}` : ""}`);
  if (files.length > 12) fileList.push(`• …and ${files.length - 12} more`);

  const fields = [
    discordField("Downloaded by", entry.user_id
      ? `<@${entry.user_id}>\n${displayName || "Unknown"}\nID: \`${entry.user_id}\``
      : "Guest / not signed in", true),
    discordField("Member archive", entry.user_id
      ? `Download **#${summary.member_download_index || 1}** for this member\nAccount: <https://discord.com/users/${entry.user_id}>`
      : "No account", true),
    discordField("Resource", `[${String(entry.product_name || entry.product_id).slice(0, 150)}](${siteUrl})\nID: \`${String(entry.product_id).slice(0, 100)}\``, true),
    discordField("Resource stats", `Type: ${entry.resource_type || entry.category || "resource"}\nDownload **#${record.count || "?"}** of this resource`, true),
    discordField("Files", `${entry.file_count || files.length} file(s)${entry.total_size ? ` • ${entry.total_size}` : ""}`, true),
    discordField("Access", `${entry.access?.label || "Session"}${entry.token_id ? `\nToken: \`${String(entry.token_id).slice(0, 60)}\`` : ""}`, true),
    discordField("Origin", originParts.join("\n"), true),
    discordField("Device", deviceText, true),
    discordField("Network", [entry.http_protocol, entry.colo ? `Edge: ${entry.colo}` : "", entry.timezone].filter(Boolean).join(" • ") || "—", true),
  ];
  if (fileList.length) fields.push(discordField(`Selected files (${files.length})`, fileList.join("\n"), false));
  if (entry.ray_id) fields.push(discordField("Request", `\`${String(entry.ray_id).slice(0, 60)}\``, true));

  const embed = {
    title: `📥 ${String(entry.product_name || entry.product_id).slice(0, 200)}`,
    description: [
      `${displayName ? `**${displayName}**` : "A guest"} downloaded this resource.`,
      second ? `🗓️ <t:${second}:F> • <t:${second}:R>` : "",
      `📦 Archive ID: \`${entry.id}\``,
    ].filter(Boolean).join("\n").slice(0, 4096),
    color: 0x34d399,
    timestamp: entry.created_at,
    fields,
    footer: { text: `Zyrex Download Archive${entry.colo ? ` • ${entry.colo}` : ""}` },
    author: { name: displayName || "Guest Visitor", icon_url: entry.user_avatar, ...(entry.user_id ? { url: `https://discord.com/users/${entry.user_id}` } : {}) },
  };
  if (/^https:\/\//i.test(String(product.thumbnail || ""))) embed.thumbnail = { url: product.thumbnail };
  const response = await fetch(`${DISCORD_API}/channels/${DOWNLOAD_LOG_CHANNEL_ID}/messages`, {
    method: "POST",
    headers: { Authorization: `Bot ${logBotToken}`, "Content-Type": "application/json" },
    body: JSON.stringify({ embeds: [embed], allowed_mentions: { parse: [] } }),
    signal: AbortSignal.timeout(8000),
  });
  if (!response.ok) {
    console.error("Discord download logging failed:", response.status, (await response.text()).slice(0, 300));
    return false;
  }
  return true;
}

async function scheduleDownloadLog(env, record) {
  if (!record?.isNew) return true;
  try {
    return await postDownloadLogToDiscord(env, record);
  } catch (error) {
    console.error("Discord download logging failed:", error?.message || String(error));
    return false;
  }
}

// --- Comments ---
async function dbGetComments(env) {
  // { "preset-id": [ ...comments ] }
  const data = await r2GetJSON(env, DB.COMMENTS, {});
  return typeof data === 'object' && !Array.isArray(data) ? data : {};
}

async function dbGetPresetComments(env, presetId) {
  const all = await dbGetComments(env);
  return Array.isArray(all[presetId]) ? all[presetId] : [];
}

async function callBotCommentApi(path, method, body = null) {
  const requestId = globalThis.crypto?.randomUUID?.() || `zyrex-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 9)}`;
  const response = await fetch(`${BOT_API}${path}`, {
    method,
    headers: {
      "Accept": "application/json",
      "X-Zyrex-Request-ID": requestId,
      ...(body ? { "Content-Type": "application/json" } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
    signal: AbortSignal.timeout(15000),
  });
  let data = {};
  try {
    data = await response.json();
  } catch (error) {
    console.error("Bot comments API returned invalid JSON:", error?.message || String(error));
  }
  return { ok: response.ok, status: response.status, data, requestId };
}

async function dbAddComment(env, comment) {
  const all = await dbGetComments(env);
  const key = comment.preset_id;
  if (!all[key]) all[key] = [];
  // If has parent_id, attach as reply
  if (comment.parent_id) {
    const parent = all[key].find(c => c.id === comment.parent_id);
    if (parent) {
      if (!parent.replies) parent.replies = [];
      parent.replies.push(comment);
    } else {
      all[key].push(comment);
    }
  } else {
    comment.replies = comment.replies || [];
    all[key].push(comment);
  }
  await r2PutJSON(env, DB.COMMENTS, all);
  return comment;
}

async function dbUpdateComment(env, presetId, commentId, updates) {
  const all = await dbGetComments(env);
  let found = null;
  for (const key of Object.keys(all)) {
    for (let i = 0; i < all[key].length; i++) {
      if (all[key][i].id === commentId) {
        all[key][i] = { ...all[key][i], ...updates, updated_at: new Date().toISOString() };
        found = all[key][i];
        break;
      }
      // check replies
      const replies = all[key][i].replies || [];
      for (let j = 0; j < replies.length; j++) {
        if (replies[j].id === commentId) {
          replies[j] = { ...replies[j], ...updates, updated_at: new Date().toISOString() };
          found = replies[j];
          break;
        }
      }
      if (found) break;
    }
    if (found) break;
  }
  if (found) await r2PutJSON(env, DB.COMMENTS, all);
  return found;
}

async function dbDeleteComment(env, commentId) {
  const all = await dbGetComments(env);
  let deleted = false;
  for (const key of Object.keys(all)) {
    const topIdx = all[key].findIndex(c => c.id === commentId);
    if (topIdx !== -1) {
      all[key].splice(topIdx, 1);
      deleted = true;
      break;
    }
    // check replies
    for (let i = 0; i < all[key].length; i++) {
      const replies = all[key][i].replies || [];
      const rIdx = replies.findIndex(r => r.id === commentId);
      if (rIdx !== -1) {
        replies.splice(rIdx, 1);
        deleted = true;
        break;
      }
    }
    if (deleted) break;
  }
  if (deleted) await r2PutJSON(env, DB.COMMENTS, all);
  return deleted;
}

// --- Uploaders ---
async function dbGetUploaders(env) {
  const data = await r2GetJSON(env, DB.UPLOADERS, { uploaders: [] });
  return data;
}

async function dbIsUploader(env, userId) {
  const data = await dbGetUploaders(env);
  const uploaders = data.uploaders || [];
  return uploaders.includes(userId);
}

// --- Team ---
// The team list is a hand-maintained snapshot, so a member who lost the Discord role
// would keep a staff or contributor badge forever. Entries are corroborated against
// the published role snapshot; a missing or stale snapshot keeps the entry as-is.
const TEAM_GROUP_ROLE_IDS = { staff: "1523366782327459952", contributors: "1550619278498078720" };

async function pruneStaleTeamRoles(env, team) {
  if (!team || typeof team !== "object") return team;
  let roles;
  try {
    roles = await readRoleSnapshotRoles(env);
  } catch (_) {
    return team;
  }
  const keepByGroup = {};
  const now = Date.now();
  for (const [group, roleId] of Object.entries(TEAM_GROUP_ROLE_IDS)) {
    if (!Array.isArray(team[group]) || !team[group].length) continue;
    const entry = roles[roleId];
    const updatedAt = Number(entry && entry.updated_at) || 0;
    const age = updatedAt ? now - updatedAt : null;
    // Only a fresh list is allowed to demote somebody.
    if (!entry || !Array.isArray(entry.ids) || age === null || age > ROLE_SNAPSHOT_FRESH_MS) continue;
    const ids = new Set(entry.ids.map(String));
    keepByGroup[group] = id => ids.has(id);
  }
  const groups = Object.keys(keepByGroup);
  if (!groups.length) return team;
  const pruned = { ...team };
  for (const group of groups) {
    pruned[group] = team[group].filter(item => keepByGroup[group](String((item && item.id) || item || "")));
  }
  return pruned;
}

async function dbGetTeam(env) {
  const team = await r2GetJSON(env, DB.TEAM, { success: true, founders: [], staff: [], contributors: [] });
  try {
    return await pruneStaleTeamRoles(env, team);
  } catch (_) {
    return team;
  }
}

// --- Guild Stats ---
async function dbGetGuildStats(env) {
  return r2GetJSON(env, DB.GUILD_STATS, { name: "Zyrex", member_count: 0, online_count: 0 });
}

// --- Creator Search Index ---
async function dbGetCreatorIndex(env) {
  return r2GetJSON(env, DB.CREATOR_INDEX, { success: true, index: {} });
}

// --- Generate unique ID for new items ---
function generateId(prefix = "cmt") {
  const bytes = new Uint8Array(7);
  crypto.getRandomValues(bytes);
  const hex = Array.from(bytes).map(b => b.toString(16).padStart(2,'0')).join('');
  return `${prefix}_${hex}`;
}

// ============================================================
// END R2 DATABASE ENGINE
// ============================================================

async function fetchProductHint(productId, session, env) {
  if (!productId) return null;
  try {
    // Published catalog is authoritative in R2; a stale VPS DB must not redirect
    // a valid resource to an obsolete storage prefix.
    if (!env?.STORAGE) return null;
    const product = await dbGetProduct(env, productId);
    return product || null;
  } catch (e) {
    console.error("Product hint lookup failed:", e.message);
    return null;
  }
}


async function resolveProductionPrefix(env, productId, hintPath, product = null) {
  const prodBucket = env.STORAGE_PROD || env.STORAGE;
  const candidates = [];
  const seenCandidates = new Set();
  const addCandidate = value => {
    const prefix = normalizeR2Prefix(value);
    if (prefix && !seenCandidates.has(prefix)) {
      seenCandidates.add(prefix);
      candidates.push(prefix);
    }
  };

  addCandidate(hintPath);
  addCandidate(product?.file_path);
  addCandidate(product?.cloud_path);
  addCandidate(product?.path);
  if (productId) {
    addCandidate(`production/${productId}`);
    addCandidate(productId);
  }

  for (const prefix of candidates) {
    if (await prefixHasDownloadableFiles(prodBucket, prefix)) return prefix;
  }

  const matches = [];
  const topList = await prodBucket.list({ delimiter: "/" });
  for (const topPrefix of topList.delimitedPrefixes || []) {
    const topName = topPrefix.replace(/\/$/, "");

    if (await prefixHasDownloadableFiles(prodBucket, topPrefix)) {
      matches.push({
        prefix: topPrefix,
        score: scorePrefixMatch(topPrefix, topName, productId, product),
      });
    }

    const resourceList = await prodBucket.list({ prefix: topPrefix, delimiter: "/" });
    for (const resourcePrefix of resourceList.delimitedPrefixes || []) {
      const resourceName = resourcePrefix.slice(topPrefix.length).replace(/\/$/, "");
      if (!(await prefixHasDownloadableFiles(prodBucket, resourcePrefix))) continue;
      matches.push({
        prefix: resourcePrefix,
        score: scorePrefixMatch(resourcePrefix, resourceName, productId, product),
      });
    }
  }

  matches.sort((a, b) => b.score - a.score);
  if (matches.length > 0 && matches[0].score > 0) return matches[0].prefix;
  if (matches.length === 1) return matches[0].prefix;
  return "";
}

function safeZipFilename(name) {
  const clean = String(name || "download").replace(/[\\/:*?"<>|\r\n]+/g, "_").trim();
  return (clean || "download").slice(0, 140);
}

function formatSizeR2(bytes) {
  if (!bytes || bytes === 0) return "0 B";
  if (bytes < 1024) return bytes + " B";
  if (bytes < 1048576) return (bytes / 1024).toFixed(1) + " KB";
  return (bytes / 1048576).toFixed(1) + " MB";
}

// Simple CRC32 (for ZIP)
const crcTable = new Int32Array(256);
for (let n = 0; n < 256; n++) {
  let c = n;
  for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
  crcTable[n] = c;
}
function crc32Update(crc, data) {
  for (let i = 0; i < data.length; i++) crc = crcTable[(crc ^ data[i]) & 0xFF] ^ (crc >>> 8);
  return crc >>> 0;
}
function crc32(data) {
  return (crc32Update(0xFFFFFFFF, data) ^ 0xFFFFFFFF) >>> 0;
}

// ── Per-download forensic tracing for .ffx presets and .txt resources ──────────
// A reposter deletes the visible credit, because text a person can read they can
// delete. So the downloader's id travels in two places that survive that edit: zero
// width characters appended to the credited effect names, and a <zyrex:Trace> property
// paid for out of the XMP packet's own padding so the packet keeps its exact byte
// length. Only files that already carry the credit are touched, and every result is
// verified before it ships - anything unexpected leaves the original bytes in place.
const TRACE_CREDIT = "zyrexediting.xyz";
const TRACE_ZW_ALPHABET = ["\u200b", "\u200c", "\u200d", "\u2060"]; // 2 bits each
const TRACE_ZW_LEAD = "\u2062";   // invisible times: opens a mark
const TRACE_ZW_TAIL = "\u2064";   // invisible plus: closes a mark
const TRACE_VERSION = 1;
const TRACE_ID_HEX = 16;          // 64-bit Discord snowflake
const TRACE_TEXT_IDS = { tdsn: true, fnam: true };
const TRACE_LIST_IDS = { LIST: true, RIFX: true };
const TRACE_XMP_NS = "https://zyrexediting.xyz/ns/trace/1.0/";
const TRACE_XMP_TAG = "zyrex:Trace";
const TRACE_XMP_CLOSE = "</rdf:Description>";
const TRACE_XMP_END = "<?xpacket end=";
const TRACE_XMP_MIN_PADDING = 64;
const TRACE_MAX_FILE_BYTES = 4 * 1024 * 1024;
// Traced copies are held in memory until the archive streams, so the total is bounded well
// below the Worker memory limit; files past the cap are simply served untraced.
const TRACE_MAX_TOTAL_BYTES = 16 * 1024 * 1024;

// Created on first use: a module-scope TextEncoder would throw while the Worker is
// loading in any environment that does not provide the global, which would take every
// route down with it.
let traceEncoderCache = null;
let traceDecoderCache = null;
let traceCreditBytesCache = null;
function traceTextEncoder() { return traceEncoderCache || (traceEncoderCache = new TextEncoder()); }
function traceTextDecoder() { return traceDecoderCache || (traceDecoderCache = new TextDecoder("utf-8", { fatal: false })); }
function traceCreditBytes() { return traceCreditBytesCache || (traceCreditBytesCache = traceTextEncoder().encode(TRACE_CREDIT)); }

function traceFourCC(bytes, o) {
  return String.fromCharCode(bytes[o], bytes[o + 1], bytes[o + 2], bytes[o + 3]);
}
function traceU32(bytes, o) {
  return (((bytes[o] << 24) >>> 0) + (bytes[o + 1] << 16) + (bytes[o + 2] << 8) + bytes[o + 3]) >>> 0;
}
function traceIsFourCC(id) {
  return /^[\x20-\x7e]{4}$/.test(id);
}

function traceTokenFor(discordId) {
  let hex = BigInt(String(discordId)).toString(16);
  if (hex.length > TRACE_ID_HEX) throw new Error("id too large");
  hex = hex.padStart(TRACE_ID_HEX, "0");
  const body = TRACE_VERSION + hex;
  let sum = 0;
  for (let i = 0; i < body.length; i++) sum = (sum + parseInt(body[i], 16)) & 0xf;
  return { hex, checksum: sum, text: TRACE_VERSION + "-" + hex + "-" + sum.toString(16) };
}

function traceDecodeToken(value) {
  const text = String(value || "");
  // Account ids are written in plain decimal so anyone reading the preset can tell who
  // downloaded it; older files carried the same id as a hex token with a checksum.
  const plain = /<zyrex:Id>\s*(\d{15,25})\s*<\/zyrex:Id>/.exec(text) ||
    /^\s*(\d{15,25})\s*$/.exec(text) ||
    new RegExp("<" + TRACE_XMP_TAG + "[^>]*>\\s*(\\d{15,25})\\s*</" + TRACE_XMP_TAG + ">").exec(text);
  if (plain) return { version: TRACE_VERSION, id: plain[1] };
  const match = /(?:^|[^0-9a-f])([0-9a-f])-([0-9a-f]{16})-([0-9a-f])(?![0-9a-f])/.exec(text);
  if (!match) return null;
  const body = match[1] + match[2];
  let sum = 0;
  for (let i = 0; i < body.length; i++) sum = (sum + parseInt(body[i], 16)) & 0xf;
  if (sum !== parseInt(match[3], 16)) return null;
  return { version: parseInt(match[1], 16), id: BigInt("0x" + match[2]).toString() };
}

function traceEncodeMark(discordId) {
  const token = traceTokenFor(discordId);
  const nibbles = [TRACE_VERSION];
  for (let i = 0; i < token.hex.length; i++) nibbles.push(parseInt(token.hex[i], 16));
  nibbles.push(token.checksum);
  let out = TRACE_ZW_LEAD;
  for (let j = 0; j < nibbles.length; j++) {
    out += TRACE_ZW_ALPHABET[(nibbles[j] >> 2) & 3] + TRACE_ZW_ALPHABET[nibbles[j] & 3];
  }
  return out + TRACE_ZW_TAIL;
}

function traceDecodeMark(text) {
  const source = String(text || "");
  const start = source.indexOf(TRACE_ZW_LEAD);
  if (start < 0) return null;
  const end = source.indexOf(TRACE_ZW_TAIL, start + 1);
  if (end < 0) return null;
  const body = source.slice(start + 1, end);
  if (body.length % 2) return null;
  const nibbles = [];
  for (let i = 0; i + 1 < body.length; i += 2) {
    const hi = TRACE_ZW_ALPHABET.indexOf(body[i]);
    const lo = TRACE_ZW_ALPHABET.indexOf(body[i + 1]);
    if (hi < 0 || lo < 0) return null;
    nibbles.push((hi << 2) | lo);
  }
  if (nibbles.length !== 1 + TRACE_ID_HEX + 1) return null;
  let sum = 0;
  for (let j = 0; j < nibbles.length - 1; j++) sum = (sum + nibbles[j]) & 0xf;
  if (sum !== nibbles[nibbles.length - 1]) return null;
  let hex = "";
  for (let k = 1; k <= TRACE_ID_HEX; k++) hex += nibbles[k].toString(16);
  return { version: nibbles[0], id: BigInt("0x" + hex).toString() };
}

// Chunk sizes in After Effects presets include the even-alignment pad byte, and a payload
// always runs to payloadStart + size, so walking the file is a flat scan. Bytes the walk
// cannot describe are kept verbatim so a rebuild can never quietly discard part of a file.
function traceParseChunks(bytes, start, end) {
  const nodes = [];
  let o = start;
  while (o + 8 <= end) {
    const id = traceFourCC(bytes, o);
    const size = traceU32(bytes, o + 4);
    const payloadStart = o + 8;
    const chunkEnd = payloadStart + size;
    if (!traceIsFourCC(id) || chunkEnd > end || chunkEnd > bytes.length) {
      const gapStart = o;
      let next = o + 1;
      while (next + 8 <= end) {
        const nextId = traceFourCC(bytes, next);
        const nextSize = traceU32(bytes, next + 4);
        if (traceIsFourCC(nextId) && next + 8 + nextSize <= end) break;
        next++;
      }
      nodes.push({ gap: true, bytes: bytes.subarray(gapStart, next) });
      o = next;
      continue;
    }
    const node = { id, size, payloadStart, chunkEnd };
    if (TRACE_LIST_IDS[id]) {
      node.isList = true;
      node.listType = size >= 4 ? traceFourCC(bytes, payloadStart) : "";
      node.children = traceParseChunks(bytes, payloadStart + 4, chunkEnd);
    }
    nodes.push(node);
    o = chunkEnd;
  }
  if (o < end) nodes.push({ gap: true, bytes: bytes.subarray(o, end) });
  return nodes;
}

function traceIsFfx(bytes) {
  return bytes.length >= 12 && traceFourCC(bytes, 0) === "RIFX" && traceFourCC(bytes, 8) === "FaFX";
}

// A preset is a self-contained RIFX container followed by an XMP metadata packet. The two
// are independent - the packet never references container offsets - so the container can
// be resized freely while the packet is edited in place.
function traceSplitFfx(bytes) {
  if (!traceIsFfx(bytes)) return null;
  const declared = 8 + traceU32(bytes, 4);
  if (declared < 12 || declared > bytes.length) return null;
  return { container: bytes.subarray(0, declared), tail: bytes.subarray(declared) };
}

function traceChildrenOf(bytes) {
  return traceParseChunks(bytes, 12, Math.min(bytes.length, 8 + traceU32(bytes, 4)));
}

function traceUtf8TextOf(bytes, node) {
  if (!TRACE_TEXT_IDS[node.id] || node.size < 8) return null;
  if (traceFourCC(bytes, node.payloadStart) !== "Utf8") return null;
  const textSize = traceU32(bytes, node.payloadStart + 4);
  if (textSize > node.size - 8) return null;
  const slice = bytes.subarray(node.payloadStart + 8, node.payloadStart + 8 + textSize);
  return { text: traceTextDecoder().decode(slice) };
}

function traceWriteHeader(target, at, id, size) {
  target[at] = id.charCodeAt(0);
  target[at + 1] = id.charCodeAt(1);
  target[at + 2] = id.charCodeAt(2);
  target[at + 3] = id.charCodeAt(3);
  target[at + 4] = (size >>> 24) & 0xff;
  target[at + 5] = (size >>> 16) & 0xff;
  target[at + 6] = (size >>> 8) & 0xff;
  target[at + 7] = size & 0xff;
}

// `targetSize` is the size the chunk had before plus whatever the new text added, so any
// slack the original carried is preserved and only the text itself changes.
function traceBuildUtf8(text, targetSize) {
  const textBytes = traceTextEncoder().encode(text);
  const base = 8 + textBytes.length;
  let size = base % 2 ? base + 1 : base;
  if (targetSize && targetSize > size && targetSize - size <= 1024) size = targetSize;
  if (size % 2) size += 1;
  const payload = new Uint8Array(size);
  payload[0] = 85; payload[1] = 116; payload[2] = 102; payload[3] = 56; // 'Utf8'
  const n = textBytes.length;
  payload[4] = (n >>> 24) & 0xff;
  payload[5] = (n >>> 16) & 0xff;
  payload[6] = (n >>> 8) & 0xff;
  payload[7] = n & 0xff;
  payload.set(textBytes, 8);
  return payload;
}

function traceSerialize(nodes, bytes, replace) {
  const parts = [];
  let total = 0;
  for (const node of nodes) {
    if (node.gap) { parts.push(node.bytes); total += node.bytes.length; continue; }
    let piece;
    if (node.isList) {
      const inner = traceSerialize(node.children, bytes, replace);
      piece = new Uint8Array(12 + inner.length);
      traceWriteHeader(piece, 0, node.id, 4 + inner.length);
      // The list type sits after the size field, at offset 8, not offset 4.
      piece[8] = node.listType.charCodeAt(0);
      piece[9] = node.listType.charCodeAt(1);
      piece[10] = node.listType.charCodeAt(2);
      piece[11] = node.listType.charCodeAt(3);
      piece.set(inner, 12);
    } else {
      let payload = replace(node);
      if (!payload) payload = bytes.subarray(node.payloadStart, node.chunkEnd);
      piece = new Uint8Array(8 + payload.length);
      traceWriteHeader(piece, 0, node.id, payload.length);
      piece.set(payload, 8);
    }
    parts.push(piece);
    total += piece.length;
  }
  const out = new Uint8Array(total);
  let at = 0;
  for (const part of parts) { out.set(part, at); at += part.length; }
  return out;
}

// Re-attaches the RIFX header to a serialized child list: [0..4 'RIFX'][4..8 size]
// [8..12 form][12.. children].
function traceWrapContainer(children, source) {
  const out = new Uint8Array(12 + children.length);
  traceWriteHeader(out, 0, "RIFX", 4 + children.length);
  out[8] = source[8]; out[9] = source[9]; out[10] = source[10]; out[11] = source[11];
  out.set(children, 12);
  return out;
}

// Maps every display text through `mapFn` and rebuilds the container. Only chunks the
// mapper changes are rewritten, so everything else stays byte-identical.
function traceRewriteTexts(bytes, mapFn) {
  if (!traceIsFfx(bytes)) return null;
  const declaredEnd = Math.min(bytes.length, 8 + traceU32(bytes, 4));
  if (declaredEnd !== bytes.length) return null;
  let changed = 0;
  let growth = 0;
  const replace = (node) => {
    const info = traceUtf8TextOf(bytes, node);
    if (!info) return null;
    const next = mapFn(info.text, node);
    if (next === null || next === undefined || next === info.text) return null;
    changed++;
    const delta = traceTextEncoder().encode(next).length - traceTextEncoder().encode(info.text).length;
    const payload = traceBuildUtf8(next, node.size + delta);
    growth += payload.length - node.size;
    return payload;
  };
  const rebuilt = traceSerialize(traceChildrenOf(bytes), bytes, replace);
  if (!changed) return null;
  return { bytes: traceWrapContainer(rebuilt, bytes), changed, growth };
}

function traceXmpText(tail) {
  if (!tail.length) return null;
  const text = traceTextDecoder().decode(tail);
  const at = text.indexOf("<" + TRACE_XMP_TAG);
  if (at < 0) return null;
  const open = text.indexOf(">", at);
  const close = text.indexOf("</" + TRACE_XMP_TAG + ">", open);
  if (open < 0 || close < 0) return null;
  return text.slice(open + 1, close);
}

// Reads the trace out of whichever carrier holds it, so a file that kept only one - a preset
// with no credited names has only the metadata - still resolves to a member.
function traceFindMark(bytes) {
  const parts = traceSplitFfx(bytes);
  if (!parts) return null;
  const fromMetadata = traceDecodeToken(traceXmpText(parts.tail));
  if (fromMetadata) return fromMetadata;
  const text = traceTextDecoder().decode(parts.container);
  const at = text.indexOf(TRACE_ZW_LEAD);
  if (at < 0) return null;
  return traceDecodeMark(text.slice(at));
}

// The packet is written with a large block of trailing spaces so it can be edited in
// place; the trace is paid for out of that block.
function traceMarkXmp(tail, discordId, username = "", downloadedAt = "") {
  if (!tail.length) return null;
  if (traceXmpText(tail)) return null;               // already carries a trace
  const text = traceTextDecoder().decode(tail);
  if (!text.startsWith("<?xpacket")) return null;
  const endAt = text.lastIndexOf(TRACE_XMP_END);
  if (endAt < 0) return null;
  let padStart = endAt;
  while (padStart > 0 && /\s/.test(text[padStart - 1])) padStart--;
  const padding = endAt - padStart;
  if (padding < TRACE_XMP_MIN_PADDING) return null;
  const closeAt = text.lastIndexOf(TRACE_XMP_CLOSE, endAt);
  if (closeAt < 0) return null;
  const xmlEscape = (value) => String(value || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;");
  const accountId = String(discordId).replace(/[^0-9]/g, "");
  const accountName = String(username || "").trim().slice(0, 64);
  // Both values are written in the clear: whoever opens the preset can read the Discord
  // account and the download time without a decoder. The identity still also travels in
  // the zero-width marks on the credited names, so deleting this block does not hide it.
  const openTag = "<" + TRACE_XMP_TAG + ' xmlns:zyrex="' + TRACE_XMP_NS + '">';
  const closeTag = "</" + TRACE_XMP_TAG + ">";
  const idElement = "<zyrex:Id>" + accountId + "</zyrex:Id>";
  const nameElement = accountName ? "<zyrex:Username>" + xmlEscape(accountName) + "</zyrex:Username>" : "";
  const dateElement = downloadedAt ? "<zyrex:DownloadedAt>" + xmlEscape(downloadedAt) + "</zyrex:DownloadedAt>" : "";
  // A preset with barely any XMP padding keeps as much of the block as fits.
  const element = [
    openTag + idElement + nameElement + dateElement + closeTag,
    openTag + idElement + nameElement + closeTag,
    openTag + idElement + closeTag,
    openTag + accountId + closeTag,
  ].find(candidate => candidate.length + 8 <= padding);
  if (!element) return null;
  const out = text.slice(0, closeAt) + element +
    text.slice(closeAt, padStart) +
    text.slice(padStart, endAt).slice(element.length) +
    text.slice(endAt);
  if (out.length !== text.length) return null;
  const encoded = traceTextEncoder().encode(out);
  if (encoded.length !== tail.length) return null;
  return encoded;
}

function traceShapeOf(bytes) {
  const parts = [];
  const walk = (nodes) => {
    for (const node of nodes) {
      if (node.gap) { parts.push("GAP:" + node.bytes.length); continue; }
      parts.push(node.id + ":" + node.size);
      if (node.isList) walk(node.children);
    }
  };
  parts.push("RIFX:" + traceU32(bytes, 4));
  walk(traceChildrenOf(bytes));
  return parts.join("|");
}

function traceCollectTexts(bytes) {
  const out = [];
  const walk = (nodes) => {
    for (const node of nodes) {
      if (node.gap) continue;
      if (node.isList) { walk(node.children); continue; }
      const info = traceUtf8TextOf(bytes, node);
      if (info) out.push(info.text);
    }
  };
  walk(traceChildrenOf(bytes));
  return out;
}

// Everything that must hold before a rebuilt preset may be shipped.
function traceVerify(original, rebuilt, expected) {
  const problems = [];
  if (!traceIsFfx(rebuilt)) problems.push("not RIFX/FaFX");
  const before = traceSplitFfx(original);
  const after = traceSplitFfx(rebuilt);
  if (!before || !after) return problems.concat("does not split cleanly");
  if (after.tail.length !== before.tail.length) problems.push("the XMP packet changed size");
  if (expected && expected.growth !== undefined) {
    const grew = rebuilt.length - original.length;
    // The only thing allowed to change the file's size is the text we rewrote.
    if (grew !== expected.growth) problems.push("grew by " + grew + " but only the text changed (" + expected.growth + ")");
  }
  const beforeTexts = traceCollectTexts(before.container);
  const afterTexts = traceCollectTexts(after.container);
  if (afterTexts.length !== beforeTexts.length) {
    problems.push("text chunk count changed");
  } else {
    let marks = 0;
    for (let i = 0; i < beforeTexts.length; i++) {
      if (afterTexts[i].indexOf(beforeTexts[i]) !== 0) problems.push("a text no longer starts with the original");
      if (afterTexts[i].indexOf(TRACE_ZW_LEAD) >= 0) marks++;
    }
    if (expected && expected.nameMarks !== undefined && marks !== expected.nameMarks) {
      problems.push("marks " + marks + " != " + expected.nameMarks);
    }
  }
  const beforeShape = traceShapeOf(before.container).split("|");
  const afterShape = traceShapeOf(after.container).split("|");
  if (beforeShape.length !== afterShape.length) {
    problems.push("chunk count changed");
  } else {
    for (let j = 0; j < beforeShape.length; j++) {
      if (beforeShape[j] === afterShape[j]) continue;
      const id = beforeShape[j].split(":")[0];
      if (id === "tdsn" || id === "fnam" || id === "LIST" || id === "RIFX") continue;
      problems.push("unexpected structural change: " + beforeShape[j] + " -> " + afterShape[j]);
    }
  }
  return problems;
}

// Marks every display string the credit tool already credited, plus the metadata packet.
function traceWatermarkFfx(bytes, discordId, username = "", downloadedAt = "") {
  const parts = traceSplitFfx(bytes);
  if (!parts) return null;
  const mark = traceEncodeMark(discordId);
  const markedTail = traceMarkXmp(parts.tail, discordId, username, downloadedAt);
  if (parts.tail.length && !markedTail) return null;   // trailing data we do not recognise
  // A file installed by an older build already carries marks on its names; those stay and
  // only the metadata block is refreshed, so count them as part of the expected total.
  const existingMarks = traceCollectTexts(parts.container).filter(text => text.indexOf(TRACE_ZW_LEAD) >= 0).length;
  const nameResult = traceRewriteTexts(parts.container, (text) => {
    if (text.indexOf(TRACE_CREDIT) < 0) return null;
    if (text.indexOf(TRACE_ZW_LEAD) >= 0) return null;   // already marked
    return text + mark;
  });
  if (!nameResult && !markedTail) return null;   // nothing in the file can carry a trace
  // A preset that stores only effect match names ("ADBE Gaussian Blur 2") has no display
  // string to put a credit in, but its metadata packet still carries the trace, so it is
  // protected even though it cannot be visibly branded.
  const container = nameResult ? nameResult.bytes : parts.container;
  const tail = markedTail || parts.tail;
  const out = new Uint8Array(container.length + tail.length);
  out.set(container, 0);
  out.set(tail, container.length);
  const problems = traceVerify(bytes, out, {
    nameMarks: existingMarks + (nameResult ? nameResult.changed : 0),
    growth: nameResult ? nameResult.growth : 0,
  });
  if (problems.length) {
    console.warn("FFX trace rejected:", problems.slice(0, 3).join("; "));
    return null;
  }
  return {
    bytes: out,
    nameMarks: nameResult ? nameResult.changed : 0,
    xmpMarked: Boolean(markedTail),
    growth: nameResult ? nameResult.growth : 0,
  };
}

function traceContainsBytes(haystack, needle) {
  if (!needle.length || haystack.length < needle.length) return false;
  const first = needle[0];
  const limit = haystack.length - needle.length;
  for (let i = 0; i <= limit; i++) {
    if (haystack[i] !== first) continue;
    let j = 1;
    while (j < needle.length && haystack[i + j] === needle[j]) j++;
    if (j === needle.length) return true;
  }
  return false;
}


// Returns traced bytes for a downloadable file, or null to serve it untouched.
function traceDownloadBytes(bytes, fileName, discordId, username = "", downloadedAt = "") {
  const id = String(discordId || "").trim();
  if (!/^\d{15,25}$/.test(id)) return null;   // a malformed id must never be stamped into a file
  const lower = String(fileName || "").toLowerCase();
  if (lower.endsWith(".ffx")) {
    const result = traceWatermarkFfx(bytes, id, username, downloadedAt);
    return result ? result.bytes : null;
  }
  if (lower.endsWith(".txt")) {
    // Text is never round-tripped through a decoder: a resource that is not really UTF-8
    // would come back corrupted. The mark is appended as raw bytes instead.
    if (!traceContainsBytes(bytes, traceCreditBytes())) return null;
    const markBytes = traceTextEncoder().encode(traceEncodeMark(id));
    const out = new Uint8Array(bytes.length + markBytes.length);
    out.set(bytes, 0);
    out.set(markBytes, bytes.length);
    return out;
  }
  return null;
}

function traceIsDisabled(env) {
  const flag = String((env && env.FFX_TRACE) || "").trim().toLowerCase();
  return flag === "off" || flag === "0" || flag === "false" || flag === "disabled";
}

// Reads and traces every downloadable preset for one download, so the archive's
// Content-Length can be exact before streaming starts. Failures are silent: a file that
// cannot be traced is served exactly as stored.
async function prepareDownloadTraces(env, objects, r2Prefix, isProdBucket, discordId) {
  const traces = new Map();
  if (traceIsDisabled(env) || !discordId) return traces;
  let buffered = 0;
  for (const obj of objects) {
    const name = relativeR2Name(obj.key, r2Prefix);
    if (!name) continue;
    const lower = name.toLowerCase();
    if (!lower.endsWith(".ffx") && !lower.endsWith(".txt")) continue;
    const size = Number(obj.size);
    if (!Number.isSafeInteger(size) || size <= 0 || size > TRACE_MAX_FILE_BYTES) continue;
    if (buffered + size > TRACE_MAX_TOTAL_BYTES) continue;
    try {
      const object = await r2Get(env, obj.key, isProdBucket);
      if (!object || !object.body) continue;
      const bytes = new Uint8Array(await object.arrayBuffer());
      buffered += bytes.length;
      const marked = traceDownloadBytes(bytes, name, discordId);
      if (!marked) continue;
      traces.set(obj.key, marked);
    } catch (error) {
      console.warn("FFX trace skipped:", obj.key, error?.message || String(error));
    }
  }
  return traces;
}

// The brand goes on the name of every file a download ships, not only on its contents:
// the archive becomes "<folder> - zyrexediting.xyz.zip" and each file inside becomes
// "barbie - zyrexediting.xyz.ffx". The suffix sits before the extension so the file type
// still resolves on Windows and in After Effects. Directories keep their own names.
const DOWNLOAD_BRAND = TRACE_CREDIT;

function brandDownloadName(name) {
  const value = String(name || "");
  const slash = value.lastIndexOf("/");
  const dir = slash >= 0 ? value.slice(0, slash + 1) : "";
  const file = slash >= 0 ? value.slice(slash + 1) : value;
  // A leading dot is part of the name (".gitignore"), not an extension.
  if (!file || file.indexOf(DOWNLOAD_BRAND) >= 0) return value;
  const suffix = " - " + DOWNLOAD_BRAND;
  const dot = file.lastIndexOf(".");
  if (dot > 0 && dot < file.length - 1) return dir + file.slice(0, dot) + suffix + file.slice(dot);
  return dir + file + suffix;
}

// The watermark notes are Zyrex's own files and are recognised by name, so they are the one
// exception and keep their plain names. Matching on the base name covers both the copies the
// worker injects and the copies stored in R2. The set is derived from the watermarks
// themselves so it cannot drift if one is added.
const UNBRANDED_ENTRY_NAMES = new Set(Object.keys(WATERMARKS).map(name => String(name).toLowerCase()));

function isUnbrandedEntryName(name) {
  const value = String(name || "");
  const slash = value.lastIndexOf("/");
  const base = (slash >= 0 ? value.slice(slash + 1) : value).toLowerCase();
  return UNBRANDED_ENTRY_NAMES.has(base);
}

function makeLocalHeader(nameBytes, size, crc, dataDescriptor = false) {
  const buf = new Uint8Array(30 + nameBytes.length);
  const v = new DataView(buf.buffer);
  v.setUint32(0, 0x04034b50, true); // signature
  v.setUint16(4, 20, true);         // version
  v.setUint16(6, 0x0800 | (dataDescriptor ? 0x0008 : 0), true); // UTF-8 names; bit 3: sizes follow file data
  v.setUint16(8, 0, true);          // compression (store)
  v.setUint16(10, 0, true);         // mod time
  v.setUint16(12, 0, true);         // mod date
  v.setUint32(14, dataDescriptor ? 0 : crc, true);
  v.setUint32(18, dataDescriptor ? 0 : size, true); // compressed size
  v.setUint32(22, dataDescriptor ? 0 : size, true); // uncompressed size
  v.setUint16(26, nameBytes.length, true);
  v.setUint16(28, 0, true);         // extra field length
  buf.set(nameBytes, 30);
  return buf;
}
function makeDataDescriptor(size, crc) {
  const buf = new Uint8Array(16);
  const v = new DataView(buf.buffer);
  v.setUint32(0, 0x08074b50, true);
  v.setUint32(4, crc, true);
  v.setUint32(8, size, true);
  v.setUint32(12, size, true);
  return buf;
}
function makeCentralDirEntry(nameBytes, size, crc, offset, dataDescriptor = false) {
  const buf = new Uint8Array(46 + nameBytes.length);
  const v = new DataView(buf.buffer);
  v.setUint32(0, 0x02014b50, true);
  v.setUint16(4, 20, true);
  v.setUint16(6, 20, true);
  v.setUint16(8, 0x0800 | (dataDescriptor ? 0x0008 : 0), true);
  v.setUint16(10, 0, true);
  v.setUint16(12, 0, true);
  v.setUint16(14, 0, true);
  v.setUint32(16, crc, true);
  v.setUint32(20, size, true);
  v.setUint32(24, size, true);
  v.setUint16(28, nameBytes.length, true);
  v.setUint16(30, 0, true);
  v.setUint16(32, 0, true);
  v.setUint16(34, 0, true);
  v.setUint32(36, 0, true);
  v.setUint32(42, offset, true);
  buf.set(nameBytes, 46);
  return buf;
}

async function sftpgoAuth(env) {
  if (sftpgoToken && Date.now() < sftpgoTokenExpiry) {
    return sftpgoToken;
  }
  const user = env.SFTPGO_ADMIN_USER || "reyliar";
  const pass = env.SFTPGO_ADMIN_PASS || "";
  if (!pass) {
    console.error("SFTPGO_ADMIN_PASS secret not configured");
    return null;
  }
  try {
    const authHeader = btoa(`${user}:${pass}`);
    const resp = await fetch(`${SFTPGO_API}/token`, {
      method: "GET",
      headers: {
        "Authorization": `Basic ${authHeader}`,
        "User-Agent": "ZyrexWorker/1.0",
      },
    });
    if (!resp.ok) {
      console.error("SFTPGo auth failed:", resp.status);
      return null;
    }
    const data = await resp.json();
    sftpgoToken = data.access_token;
    // Expire 1 minute before actual expiry
    sftpgoTokenExpiry = Date.now() + (data.expires_in ? (data.expires_in - 60) * 1000 : 300000);
    return sftpgoToken;
  } catch (e) {
    console.error("SFTPGo auth error:", e.message);
    return null;
  }
}

// Find SFTPGo user by Discord ID.
// 1) Direct SFTPGo lookup (description field, username convention)
// 2) Fallback: ask bot API for the mapping
async function findSftpgoUserByDiscordId(discordId, env) {
  const token = await sftpgoAuth(env);
  if (token) {
    try {
      // List all users and search by description for discord:ID pattern
      const resp = await fetch(`${SFTPGO_API}/users?limit=200`, {
        headers: {
          "Authorization": `Bearer ${token}`,
          "User-Agent": "ZyrexWorker/1.0",
        },
      });
      if (resp.ok) {
        const users = await resp.json();
        // First: try exact description match "discord:DISCORD_ID"
        let match = users.find(u => u.description && u.description.includes(`discord:${discordId}`));
        // Second: try username convention uDISCORD_ID
        if (!match) match = users.find(u => u.username === `u${discordId}`);
        // Third: try any user whose username contains the discord ID
        if (!match) match = users.find(u => u.username && u.username.includes(discordId));
        if (match) return match;
      }
    } catch (e) {
      console.error("SFTPGo find user error:", e.message);
    }
  }
  
  // Fallback: try bot API for Discord→SFTPGo mapping
  try {
    const botResp = await fetch(`${BOT_API}/api/sftpgo/lookup?userId=${discordId}`);
    if (botResp.ok) {
      const data = await botResp.json();
      if (data.success && data.username) {
        // Found via bot, now get full user from SFTPGo
        const token2 = await sftpgoAuth(env);
        if (token2) {
          try {
            const userResp = await fetch(`${SFTPGO_API}/users/${encodeURIComponent(data.username)}`, {
              headers: { "Authorization": `Bearer ${token2}`, "User-Agent": "ZyrexWorker/1.0" },
            });
            if (userResp.ok) return await userResp.json();
          } catch(e) {}
        }
        // Return minimal user object from bot data
        return { username: data.username, description: data.display_name || "", status: 1, quota_size: 0, used_quota_size: 0 };
      }
    }
  } catch (e) {
    console.error("Bot API lookup fallback error:", e.message);
  }
  
  return null;
}

// Get SFTPGo user account details (quota, status, etc.)
// Also auto-syncs Discord ID into SFTPGo description for future lookups
async function getSftpgoAccount(discordId, env) {
  const user = await findSftpgoUserByDiscordId(discordId, env);
  if (!user) return { success: false, error: "No SFTPGo cloud account linked to your Discord profile. Contact an admin." };
  
  // Auto-sync: ensure Discord ID is in description field for future direct lookups
  if (user.description && !user.description.includes(`discord:${discordId}`)) {
    // Fire and forget - don't block the response
    const token = await sftpgoAuth(env);
    if (token) {
      const newDesc = user.description + ` | discord:${discordId}`;
      fetch(`${SFTPGO_API}/users/${encodeURIComponent(user.username)}`, {
        method: "PUT",
        headers: {
          "Authorization": `Bearer ${token}`,
          "Content-Type": "application/json",
          "User-Agent": "ZyrexWorker/1.0",
        },
        body: JSON.stringify({ ...user, description: newDesc }),
      }).catch(e => console.error("Auto-sync description failed:", e.message));
    }
  } else if (!user.description) {
    // No description - set one with Discord ID
    const token = await sftpgoAuth(env);
    if (token) {
      const newDesc = `discord:${discordId}`;
      fetch(`${SFTPGO_API}/users/${encodeURIComponent(user.username)}`, {
        method: "PUT",
        headers: {
          "Authorization": `Bearer ${token}`,
          "Content-Type": "application/json",
          "User-Agent": "ZyrexWorker/1.0",
        },
        body: JSON.stringify({ ...user, description: newDesc }),
      }).catch(e => console.error("Auto-sync description failed:", e.message));
    }
  }
  
  // Extract Discord info from description
  let displayName = "";
  if (user.description) {
    const parts = user.description.split("|");
    displayName = parts[0]?.trim() || "";
  }
  
  return {
    success: true,
    username: user.username,
    display_name: displayName || user.username,
    user: {
      username: user.username,
      description: user.description || "",
      status: user.status,
      quota_size: user.quota_size || 0,
      used_quota_size: user.used_quota_size || 0,
      used_quota_files: user.used_quota_files || 0,
      home_dir: user.home_dir || "",
    },
  };
}

// List files in a user's SFTPGo directory
async function listSftpgoFiles(discordId, path, env) {
  const user = await findSftpgoUserByDiscordId(discordId, env);
  if (!user) return { success: false, error: "No SFTPGo cloud account linked to your Discord profile." };
  
  const token = await sftpgoAuth(env);
  if (!token) return { success: false, error: "SFTPGo authentication failed" };
  
  try {
    // Normalize path
    let browsePath = path || "/";
    if (!browsePath.startsWith("/")) browsePath = "/" + browsePath;
    
    // Use SFTPGo filesystem API to browse user's directory
    const resp = await fetch(`${SFTPGO_API}/folders?path=${encodeURIComponent(browsePath)}&username=${encodeURIComponent(user.username)}`, {
      headers: {
        "Authorization": `Bearer ${token}`,
        "User-Agent": "ZyrexWorker/1.0",
      },
    });
    if (!resp.ok) {
      // Fallback: try user-specific folder listing
      const resp2 = await fetch(`${SFTPGO_API}/users/${encodeURIComponent(user.username)}/folders?path=${encodeURIComponent(browsePath)}`, {
        headers: {
          "Authorization": `Bearer ${token}`,
          "User-Agent": "ZyrexWorker/1.0",
        },
      });
      if (!resp2.ok) {
        return { success: true, files: [], folders: [], note: `API returned status ${resp2.status}` };
      }
      const data = await resp2.json();
      return {
        success: true,
        files: (data.files || []).map(f => ({
          name: f.name || "unknown",
          path: f.path || browsePath + (f.name || ""),
          size: f.size || 0,
          last_modified: f.last_modified || f.updated_at || null,
        })),
        folders: (data.folders || data.dirs || []).map(d => ({
          name: typeof d === "string" ? d : (d.name || d.path || "unknown"),
        })),
      };
    }
    const data = await resp.json();
    return {
      success: true,
      files: (data.files || []).map(f => ({
        name: f.name || "unknown",
        path: f.path || browsePath + (f.name || ""),
        size: f.size || 0,
        last_modified: f.last_modified || f.updated_at || null,
      })),
      folders: (data.folders || data.dirs || []).map(d => ({
        name: typeof d === "string" ? d : (d.name || d.path || "unknown"),
      })),
    };
  } catch (e) {
    console.error("SFTPGo list files error:", e.message);
    return { success: false, error: "Failed to list directory: " + e.message };
  }
}

// SFTPGo keys may be written to R2 either flattened (`<key_prefix>/...`) or with the
// raw Windows home path prepended. Probe both shapes, cheapest first.
const SFTPGO_BUCKET_PATH_BASES = [
  "",
  "C:/Users/reyli/Desktop/sftpgo/data/",
  "C:\\Users\\reyli\\Desktop\\sftpgo\\data\\",
];
const R2_SCAN_MAX_OBJECTS = 4000;
const R2_SCAN_MAX_PREFIX_PROBES = 8;

async function listR2ObjectsBounded(env, prefix, limit = R2_SCAN_MAX_OBJECTS) {
  const objects = [];
  let cursor;
  try {
    while (objects.length < limit) {
      const batch = await env.STORAGE.list({
        prefix,
        limit: Math.min(1000, limit - objects.length),
        cursor,
      });
      if (!batch || !batch.objects || batch.objects.length === 0) break;
      objects.push(...batch.objects);
      cursor = batch.cursor;
      if (!batch.truncated || !cursor) break;
    }
  } catch (e) {
    console.error("Storage list error:", prefix, e.message);
  }
  return objects;
}

// Candidate R2 key prefixes for this user, most authoritative first.
async function candidateUserPrefixes(discordId, username, env) {
  const candidates = [];
  const push = (value) => {
    const cleaned = String(value || "").trim().replace(/^\/+|\/+$/g, "");
    if (cleaned && !candidates.includes(cleaned)) candidates.push(cleaned);
  };

  const name = String(username || "").trim();
  const id = String(discordId || "").trim();
  // SFTPGo user record holds the authoritative `key_prefix` — fetch it first so the
  // most likely prefix is probed before any guesswork.
  try {
    const user = await findSftpgoUserByDiscordId(id, env);
    const keyPrefix = user && user.filesystem && user.filesystem.s3config && user.filesystem.s3config.key_prefix;
    push(keyPrefix);
    push(user && user.username);
  } catch (e) {
    console.error("Storage scan user lookup error:", e.message);
  }
  if (name && id) {
    push(`${name}_${id}`);
    push(`${name.toLowerCase()}_${id}`);
  }
  if (id) push(id);
  push(name);
  if (name) push(name.toLowerCase());
  return candidates.slice(0, R2_SCAN_MAX_PREFIX_PROBES);
}

// Group `<user>/<editor>/<resource>/<file>` keys into resource cards.
function resourcesFromBucketObjects(objects, prefix) {
  const resources = new Map();
  const flatEditors = new Map();

  for (const obj of objects) {
    const key = String(obj.key || "").replace(/\\/g, "/");
    if (!key.startsWith(prefix) || key === prefix) continue;
    const rel = key.slice(prefix.length);
    if (!rel || rel.endsWith("/")) continue;
    const parts = rel.split("/");
    if (parts.length >= 3) {
      const editor = parts[0];
      const resource = parts[1];
      const id = `${editor}\u0000${resource}`;
      let entry = resources.get(id);
      if (!entry) {
        entry = { editor, resource, files: [] };
        resources.set(id, entry);
      }
      entry.files.push({ name: parts.slice(2).join("/"), size: obj.size || 0, path: key });
    } else if (parts.length === 2) {
      const editor = parts[0];
      let entry = flatEditors.get(editor);
      if (!entry) {
        entry = { editor, resource: editor, files: [] };
        flatEditors.set(editor, entry);
      }
      entry.files.push({ name: parts[1], size: obj.size || 0, path: key });
    }
  }

  const result = [...resources.values()];
  for (const [editor, entry] of flatEditors) {
    if (!resources.has(`${editor}\u0000${editor}`)) result.push(entry);
  }
  result.sort((a, b) => (a.editor === b.editor
    ? a.resource.localeCompare(b.resource)
    : a.editor.localeCompare(b.editor)));
  return result;
}

// Scan user's cloud for detected resources (EDITOR/RESOURCE pattern)
async function scanResourcesFromR2(discordId, username, env) {
  /** Scan R2 staging bucket for user's resources.
   *  Prefix-scoped and bounded: never lists the whole bucket, so the Worker cannot
   *  run out of CPU/subrequests on large buckets. Handles both clean prefixes and
   *  Windows-path-prefixed keys from SFTPGo. */
  if (!env.STORAGE) return { success: true, resources: [] };

  const names = await candidateUserPrefixes(discordId, username, env);
  if (names.length === 0) return { success: true, resources: [] };

  for (const base of SFTPGO_BUCKET_PATH_BASES) {
    for (const name of names) {
      const prefix = `${base}${name}/`;
      const objects = await listR2ObjectsBounded(env, prefix);
      if (objects.length === 0) continue;
      const resources = resourcesFromBucketObjects(objects, prefix);
      if (resources.length > 0) return { success: true, resources, prefix };
    }
  }

  return { success: true, resources: [] };
}

async function scanDetectedResources(discordId, env) {
  const user = await findSftpgoUserByDiscordId(discordId, env);
  if (!user) return { success: false, error: "No SFTPGo cloud account linked to your Discord profile." };
  
  const token = await sftpgoAuth(env);
  if (!token) return { success: false, error: "SFTPGo authentication failed" };
  
  try {
    // List top-level folders (editors)
    const rootResp = await fetch(`${SFTPGO_API}/folders?path=/&username=${encodeURIComponent(user.username)}`, {
      headers: {
        "Authorization": `Bearer ${token}`,
        "User-Agent": "ZyrexWorker/1.0",
      },
    });
    if (!rootResp.ok) {
      return { success: true, resources: [] };
    }
    const rootData = await rootResp.json();
    const topFolders = rootData.folders || rootData.dirs || [];
    
    const resources = [];
    for (const folder of topFolders) {
      const editorName = typeof folder === "string" ? folder : (folder.name || folder.path || "");
      if (!editorName || editorName === "." || editorName === "..") continue;
      
      // List sub-folders (resources) inside each editor
      const subPath = "/" + editorName;
      const subResp = await fetch(`${SFTPGO_API}/folders?path=${encodeURIComponent(subPath)}&username=${encodeURIComponent(user.username)}`, {
        headers: {
          "Authorization": `Bearer ${token}`,
          "User-Agent": "ZyrexWorker/1.0",
        },
      });
      if (!subResp.ok) continue;
      const subData = await subResp.json();
      const subFolders = subData.folders || subData.dirs || [];
      const subFiles = subData.files || [];
      
      // If there are files directly in the editor folder, skip (not a resource pattern)
      for (const sub of subFolders) {
        const resourceName = typeof sub === "string" ? sub : (sub.name || sub.path || "");
        if (!resourceName || resourceName === "." || resourceName === "..") continue;
        
        // List files inside the resource folder
        const resPath = `${subPath}/${resourceName}`;
        const resResp = await fetch(`${SFTPGO_API}/folders?path=${encodeURIComponent(resPath)}&username=${encodeURIComponent(user.username)}`, {
          headers: {
            "Authorization": `Bearer ${token}`,
            "User-Agent": "ZyrexWorker/1.0",
          },
        });
        if (!resResp.ok) continue;
        const resData = await resResp.json();
        const files = (resData.files || []).map(f => ({
          name: f.name || "unknown",
          path: f.path || `${resPath}/${f.name}`,
          size: f.size || 0,
        }));
        
        resources.push({
          editor: editorName,
          resource: resourceName,
          files: files,
        });
      }
      
      // Also handle the case where editor has files directly + subfolders
      if (subFiles.length > 0 && subFolders.length === 0) {
        // Editor with only files = the editor name IS the resource
        resources.push({
          editor: editorName,
          resource: editorName,
          files: subFiles.map(f => ({
            name: f.name || "unknown",
            path: f.path || `${subPath}/${f.name}`,
            size: f.size || 0,
          })),
        });
      }
    }
    
    return { success: true, resources };
  } catch (e) {
    console.error("SFTPGo scan resources error:", e.message);
    return { success: false, error: "Failed to scan cloud: " + e.message };
  }
}

function normalizeScrapeUrl(rawUrl) {
  if (typeof rawUrl !== "string" || !rawUrl.trim()) return null;
  const value = rawUrl.trim();
  const lower = value.toLowerCase();
  let parsed;
  try { parsed = new URL(lower.startsWith("https://") || lower.startsWith("http://") ? value : "https://" + value); } catch (_) { return null; }
  const host = parsed.hostname.toLowerCase();
  if (parsed.protocol !== "https:" || parsed.username || parsed.password || (parsed.port && parsed.port !== "443")) return null;
  const providers = {
    payhip: ["payhip.com", "www.payhip.com"],
    patreon: ["patreon.com", "www.patreon.com"],
    boosty: ["boosty.to", "www.boosty.to"],
    gumroad: ["gumroad.com", "www.gumroad.com"],
    ko_fi: ["ko-fi.com", "www.ko-fi.com"],
    sellfy: ["sellfy.com", "www.sellfy.com"],
    shopify: ["myshopify.com"],
    amazon: ["amazon.com", "www.amazon.com", "amzn.to"],
  };
  for (const [provider, hosts] of Object.entries(providers)) {
    if (hosts.includes(host) || (provider === "shopify" && host.endsWith(".myshopify.com")) || (provider === "gumroad" && host.endsWith(".gumroad.com"))) {
      if (host.startsWith("www.")) parsed.hostname = host.slice(4);
      return { provider, url: parsed.toString() };
    }
  }
  return null;
}

function scrapeScalar(value) {
  if (value === undefined || value === null) return "";
  if (typeof value === "string" || typeof value === "number") return String(value).trim();
  return "";
}

function scrapeFindValue(payload, names, depth = 0) {
  if (!payload || typeof payload !== "object" || depth > 8) return "";
  const wanted = new Set(names.map(name => name.toLowerCase()));
  for (const [key, value] of Object.entries(payload)) {
    if (wanted.has(key.toLowerCase())) {
      const scalar = scrapeScalar(value);
      if (scalar) return scalar;
    }
  }
  for (const value of Object.values(payload)) {
    const found = scrapeFindValue(value, names, depth + 1);
    if (found) return found;
  }
  return "";
}

function scrapeCollectUrls(payload, found = [], depth = 0) {
  if (depth > 8 || payload == null) return found;
  if (typeof payload === "string") {
    const normalized = payload.replaceAll("\\/", "/");
    for (const token of normalized.split(/[\s\"'<>]+/)) {
      if (!/^https?:\/\//i.test(token)) continue;
      const value = token.replace(/[),.;]+$/, "");
      try {
        const parsed = new URL(value);
        if (parsed.protocol === "https:" && !found.includes(parsed.toString())) found.push(parsed.toString());
      } catch (_) {}
      if (found.length >= 40) return found;
    }
    return found;
  }
  if (Array.isArray(payload)) {
    for (const value of payload) scrapeCollectUrls(value, found, depth + 1);
  } else if (typeof payload === "object") {
    for (const value of Object.values(payload)) scrapeCollectUrls(value, found, depth + 1);
  }
  return found;
}

function scrapeProductShape(payload, url, provider) {
  const title = scrapeFindValue(payload, ["title", "name", "product_name", "product_title", "post_title", "headline"]);
  const description = scrapeFindValue(payload, ["description", "product_description", "post_content", "summary", "excerpt", "text"]);
  const price = scrapeFindValue(payload, ["price", "formatted_price", "display_price", "amount", "price_text", "regular_price", "sale_price"]);
  const image = scrapeFindValue(payload, ["image", "thumbnail", "cover", "image_url", "thumbnail_url", "cover_image", "product_image"]);
  const images = scrapeCollectUrls(payload).filter(value => /\.(?:png|jpe?g|webp|gif)(?:[?#]|$)/i.test(value));
  const normalizedPrice = price && /^\d+(?:\.\d{1,2})?$/.test(price) ? `$${Number(price).toFixed(2)}` : price;
  return {
    success: Boolean(title || description || image || price),
    provider,
    title: title || "",
    description: description || "",
    price: normalizedPrice || "",
    image: image || images[0] || "",
    thumbnail: image || images[0] || "",
    thumbnails: [...new Set([image, ...images].filter(Boolean))].slice(0, 8),
    url,
    source: "scrapin",
  };
}

function scrapeProductRows(payload, depth = 0) {
  if (depth > 8 || payload == null) return [];
  if (Array.isArray(payload)) {
    const productRows = payload.filter(item => item && typeof item === "object" &&
      (item.url || item.product_url || item.link || item.title || item.name || item.product_name));
    if (productRows.length) return productRows;
    for (const item of payload) {
      const rows = scrapeProductRows(item, depth + 1);
      if (rows.length) return rows;
    }
    return [];
  }
  if (typeof payload === "object") {
    for (const value of Object.values(payload)) {
      const rows = scrapeProductRows(value, depth + 1);
      if (rows.length) return rows;
    }
  }
  return [];
}

async function scrapeProductWithScrapin(url, env) {
  const validated = normalizeScrapeUrl(url);
  if (!validated) return { success: false, error: "Unsupported or invalid scraper URL" };
  const path = validated.provider === "payhip" ? "/payhip/product"
    : validated.provider === "patreon" ? "/patreon/product"
    : validated.provider === "shopify" ? "/shopify/product"
    : validated.provider === "amazon" ? "/amazon/product"
    : "/scrape/json";
  const payload = await scrapinRequest(env, path, { url: validated.url });
  if (!payload) return { success: false, error: "Scrapin product lookup failed" };
  return scrapeProductShape(payload, validated.url, validated.provider);
}

async function scanCreatorLinksWithScrapin(rawUrl, env) {
  let target = String(rawUrl || "").trim();
  if (!target) return { success: false, error: "URL or username is required" };
  if (!/^https?:\/\//i.test(target)) {
    if (target.startsWith("@")) target = `https://www.tiktok.com/${target}`;
    else if (/^(payhip|boosty|patreon|linktr|guns|beacons|bio\.link|carrd|solo|taplink|koji)\./i.test(target)) target = `https://${target}`;
    else target = `https://www.tiktok.com/@${target}`;
  }
  let parsed;
  try { parsed = new URL(target); } catch (_) { return { success: false, error: "Invalid profile URL" }; }
  if (parsed.protocol !== "https:" || parsed.username || parsed.password || (parsed.port && parsed.port !== "443")) return { success: false, error: "Only public HTTPS profile URLs are supported" };
  const profileTarget = socialLinkPlatform(target);
  let creator = null;
  let content = null;
  const direct = socialStoreProvider(target);
  const scanHosts = ["linktr.ee", "guns.lol", "bio.link", "beacons.ai", "carrd.co", "bento.me", "lit.link", "lnk.bio", "solo.to", "taplink.cc", "koji.to", "allmylinks.com", "hoo.be", "snipfeed.co", "linkin.bio", "campsite.bio"];
  const allowedAggregator = scanHosts.some(host => parsed.hostname === host || parsed.hostname.endsWith(`.${host}`));
  if (!profileTarget && !direct && !allowedAggregator) return { success: false, error: "Unsupported creator or store URL", source: "scrapin" };
  if (profileTarget) {
    creator = await scrapinSocialProfile(env, target).catch(() => null);
    if (!creator) return { success: false, error: "Scrapin could not resolve this creator profile", source: "scrapin" };
    content = { bio: creator.bio || "", links: creator.links || [] };
  } else if (!direct) {
    content = await scrapinRequest(env, "/scrape/json", { url: target });
    if (!content) return { success: false, error: "Scrapin could not scan this profile or store", source: "scrapin" };
  }
  const rawStrings = [JSON.stringify(content), ...(creator ? [creator.bio, ...(creator.links || [])] : [])].filter(Boolean).join(" ");
  const links = [...new Set([...scrapeCollectUrls(content), ...scrapeCollectUrls(rawStrings)])].slice(0, 40);
  const store = links.map(value => ({ url: value, match: socialStoreProvider(value) })).find(item => item.match);
  const matchedStore = store || (direct ? { url: target, match: direct } : null);
  const result = {
    success: true,
    inputUrl: String(rawUrl || ""),
    targetUrl: target,
    username: creator?.handle || parsed.pathname.split("/").filter(Boolean).pop()?.replace(/^@/, "") || "",
    found: Boolean(matchedStore),
    storeUrl: matchedStore?.url || null,
    payhipUrl: matchedStore?.match === "payhip" ? matchedStore.url : null,
    boostyUrl: matchedStore?.match === "boosty" ? matchedStore.url : null,
    patreonUrl: matchedStore?.match === "patreon" ? matchedStore.url : null,
    platform: creator?.platform || matchedStore?.match || null,
    bioLinks: links,
    creator: creator ? { name: creator.name || "", avatar: creator.avatar || "", handle: creator.handle || "", platform: creator.platform || "" } : null,
    products: [],
    source: "scrapin",
  };
  if (matchedStore?.match === "payhip" && /\/b\//i.test(new URL(matchedStore.url).pathname)) {
    const product = await scrapeProductWithScrapin(matchedStore.url, env);
    if (product.success) result.products = [{ ...product, url: product.url || matchedStore.url }];
  } else if (matchedStore?.match === "payhip") {
    const catalog = await scrapinRequest(env, "/payhip/products", { url: matchedStore.url, descriptions: "true" });
    const rows = scrapeProductRows(catalog);
    if (rows.length) result.products = rows.map(item => ({
      ...item,
      title: item.title || item.name || item.product_name || item.product_title || "Product",
      description: item.description || item.product_description || item.summary || item.excerpt || "",
      price: item.price || item.formatted_price || item.display_price || item.amount || "",
      image: item.image || item.thumbnail || item.image_url || item.thumbnail_url || item.cover_image || "",
      url: item.url || item.product_url || item.link || "",
    })).filter(item => item.url).slice(0, 100);
  } else if (matchedStore?.match === "patreon" || matchedStore?.match === "boosty") {
    const product = await scrapeProductWithScrapin(matchedStore.url, env);
    if (product.success) result.products = [{ ...product, url: product.url || matchedStore.url }];
  }
  return result;
}

function socialStoreProvider(value) {
  let host = "";
  try { host = new URL(String(value || "")).hostname.toLowerCase().replace(/^www\./, ""); } catch (_) { return ""; }
  if (host === "payhip.com" || host.endsWith(".payhip.com")) return "payhip";
  if (host === "patreon.com" || host.endsWith(".patreon.com")) return "patreon";
  if (host === "boosty.to") return "boosty";
  if (host === "gumroad.com" || host.endsWith(".gumroad.com")) return "gumroad";
  if (host === "ko-fi.com") return "ko_fi";
  if (host === "sellfy.com" || host.endsWith(".sellfy.com")) return "sellfy";
  if (host.endsWith(".myshopify.com")) return "shopify";
  if (host === "amazon.com" || host === "amzn.to") return "amazon";
  return "";
}

async function scrapePayhip(url, env = null) {
  const validated = normalizeScrapeUrl(url);
  if (!validated || validated.provider !== "payhip") return { success: false, error: "Invalid Payhip URL" };
  url = validated.url;
  try {
    let html = "";
    let isMarkdown = false;
    try {
      const resp = await fetch(url, {
        redirect: "manual",
        headers: { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36" },
        signal: AbortSignal.timeout(12000),
      });
      if (resp.ok) {
        const t = await resp.text();
        if (!t.includes("Just a moment...") && !t.includes("Attention Required! | Cloudflare") && !t.includes("cf-chl")) {
          html = t;
        }
      }
    } catch(e) {}

    // Fallback to r.jina.ai if Cloudflare challenge or non-200
    if (!html) {
      try {
        const cleanUrl = url.replace(/^https?:\/\//, "");
        const jHeaders = { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36" };
        if (env?.JINA_API_KEY) {
          jHeaders["Authorization"] = `Bearer ${env.JINA_API_KEY}`;
        }
        const jinaResp = await fetch(`https://r.jina.ai/https://${cleanUrl}`, { headers: jHeaders });
        if (jinaResp.ok) {
          html = await jinaResp.text();
          isMarkdown = true;
        }
      } catch(e) {}
    }

    if (!html) return { success: false, error: "Could not fetch Payhip product page" };

    if (isMarkdown) {
      let title = (html.match(/Title:\s*([^\n\r]+)/i) || [])[1]?.replace(/[|–\-]\s*Payhip.*/i, "").trim() || "";
      if (!title) title = (html.match(/^#\s*([^\n\r]+)/m) || [])[1]?.trim() || "";
      title = title.replace(/&amp;/g, "&").replace(/&#39;/g, "'");

      let price = "";
      const pMatch = html.match(/(?:[A-Z]{1,3}\$|\$|€|£)\s*(\d+(?:\.\d{2})?)/);
      if (pMatch) price = pMatch[0].trim();
      const labeledPrice = html.match(/(?:price|amount)\s*[:\-]\s*((?:[A-Z]{1,3}\$|[$£€¥₺])\s*\d+(?:\.\d{1,2})?|Free)/i);
      price = labeledPrice?.[1]?.trim() || "";

      const thumbnails = new Set();
      let primaryImage = "";
      const imgMatches = [...html.matchAll(/!\[[^\]]*\]\((https?:\/\/[^\)]+)\)/g)];
      for (const m of imgMatches) {
        const u = m[1];
        if (u.includes("logo") || u.includes("favicon") || u.includes("avatar")) continue;
        if (u.includes("pe56d.s3.amazonaws.com") || u.includes("payhip.com/cdn-cgi/image/")) {
          if (!primaryImage) primaryImage = u;
          thumbnails.add(u);
        }
      }

      return {
        success: true,
        title: title || "Preset Pack",
        description: "",
        image: primaryImage,
        price,
        thumbnails: [...thumbnails].slice(0, 8)
      };
    }

    // Title
    let title = (html.match(/<title>(.*?)<\/title>/i) || [])[1]?.replace(/[|–\-]\s*Payhip.*/i, "").trim() || "";
    title = title.replace(/&amp;/g, "&").replace(/&#39;/g, "'");

    // Description
    let description = (html.match(/<meta\s+name="description"\s+content="([^"]+)"/i) || [])[1] || "";

    // Price (Supports $, £, €, ¥, ₺, etc.)
    let price = "";
    // Detect currency symbol from HTML or meta
    let currencySymbol = "$";
    if (/£|&pound;|"currency":\s*"GBP"/i.test(html)) currencySymbol = "£";
    else if (/€|&euro;|"currency":\s*"EUR"/i.test(html)) currencySymbol = "€";
    else if (/¥|&yen;|"currency":\s*"JPY"/i.test(html)) currencySymbol = "¥";
    else if (/₺|"currency":\s*"TRY"/i.test(html)) currencySymbol = "₺";

    const explicitPriceMatch = html.match(/(?:[\$£€¥₺]|&pound;|&euro;|&yen;)\s*(\d+(?:\.\d{2})?)/i) ||
                               html.match(/class="[^"]*price[^"]*"[^>]*>[\s\r\n]*([^<]+)/i) ||
                               html.match(/data-price="([^"]+)"/i) ||
                               html.match(/"price":\s*"?([\d.]+)/i);
    if (explicitPriceMatch) {
      let rawVal = (explicitPriceMatch[1] || explicitPriceMatch[0] || "").replace(/&pound;/g, "£").replace(/&euro;/g, "€").replace(/&yen;/g, "¥").trim();
      if (/^[\d.]+$/.test(rawVal)) {
        price = currencySymbol + rawVal;
      } else {
        price = rawVal;
      }
    }

    let primaryImage = "";
    const thumbnails = new Set();

    // Helper: check if image URL belongs to an icon/avatar/small element
    function isExcludedImage(imgUrl) {
      const lower = imgUrl.toLowerCase();
      return lower.includes("logo") || lower.includes("favicon") || lower.includes("avatar")
          || lower.includes("/icon/") || lower.includes("_icon");
    }

    // Helper: extract width from Payhip CDN URL or img tag
    function getWidthFromUrl(url) {
      const m = url.match(/width=(\d+)/);
      return m ? parseInt(m[1]) : 0;
    }

    // Find cutoff: everything after "You might also like" or similar is NOT the product
    const alsoLikeMatch = html.match(/you might also like|related products|recommended for you|similar items/i);
    const cutoffIndex = alsoLikeMatch ? alsoLikeMatch.index : html.length;

    // 1. OG image meta — MOST RELIABLE, always the product thumbnail on Payhip
    const ogSecure = (html.match(/<meta\s+property="og:image:secure_url"\s+content="([^"]+)"/i) || [])[1];
    const ogImage = (html.match(/<meta\s+property="og:image"\s+content="([^"]+)"/i) || [])[1];
    const bestOg = ogSecure || ogImage;
    if (bestOg && !isExcludedImage(bestOg)) {
      primaryImage = bestOg;
      thumbnails.add(bestOg);
    }

    // 2. Try section-image class (Payhip main product image)
    if (!primaryImage) {
      let sectionMatch = html.match(/<img[^>]*class="[^"]*\bsection-image\b[^"]*"[^>]*src="(https:\/\/[^"]+)"/i);
      if (!sectionMatch) {
        sectionMatch = html.match(/<img[^>]*\bsection-image\b[^>]*src="(https:\/\/[^"]+)"/i);
      }
      if (sectionMatch?.[1] && !isExcludedImage(sectionMatch[1])) {
        primaryImage = sectionMatch[1];
        thumbnails.add(sectionMatch[1]);
      }
    }

    // 3. Try product-image, product-gallery classes (before cutoff only)
    if (!primaryImage) {
      const beforeCutoff = html.substring(0, cutoffIndex);
      const productImg = beforeCutoff.match(/<img[^>]*class="[^"]*\bproduct-image\b[^"]*"[^>]*src="(https:\/\/[^"]+)"/i)
                      || beforeCutoff.match(/<img[^>]*\bproduct-image\b[^>]*src="(https:\/\/[^"]+)"/i);
      if (productImg?.[1] && !isExcludedImage(productImg[1])) {
        primaryImage = productImg[1];
        thumbnails.add(productImg[1]);
      }
    }

    // 4. Scored fallback: all img tags BEFORE cutoff, excluding header/nav/author/profile containers
    if (!primaryImage) {
      const scoredImages = [];
      const imgRegex = /<img[^>]+src="(https:\/\/[^"]*\.(?:png|jpg|jpeg|gif|webp)[^"]*)"/gi;
      let imgMatch;
      let pos = 0;
      while ((imgMatch = imgRegex.exec(html)) !== null) {
        // Skip images after "You might also like" cutoff
        if (imgMatch.index > cutoffIndex) continue;
        
        const imgUrl = imgMatch[1];
        if (isExcludedImage(imgUrl)) continue;
        const currentPos = pos++;

        const contextPos = imgMatch.index;
        const context = html.substring(Math.max(0, contextPos - 400), contextPos).toLowerCase();

        // Exclude images inside author/creator/profile/avatar/header/nav/sidebar containers
        if (/class="[^"]*\b(?:author|creator|profile|avatar|user|header|navbar|sidebar|footer)[^"]*\b/i.test(context)) continue;
        if (/<(?:header|nav|aside|footer)[^>]*>/i.test(context) && !/<(?:main|article|section)[^>]*>/i.test(context)) continue;

        let score = 0;
        const w = getWidthFromUrl(imgUrl);
        if (w >= 1200) score += 30;
        else if (w >= 800) score += 20;
        else if (w >= 400) score += 10;
        else if (w > 0 && w < 200) score -= 50;

        // Boost score for images in product/section/gallery context
        if (/class="[^"]*\b(?:product|section|gallery|featured)[^"]*\b/i.test(context)) score += 25;
        if (/<(?:main|article)[^>]*>/i.test(context)) score += 10;
        // JPEG typically used for product photos (PNG more often for logos/icons)
        if (/\.jpg|jpeg/i.test(imgUrl)) score += 5;
        // Earlier position = more likely to be the product image
        score += Math.max(0, 10 - currentPos);

        scoredImages.push({ url: imgUrl, score, pos: currentPos });
      }

      scoredImages.sort((a, b) => b.score - a.score || a.pos - b.pos);
      for (const img of scoredImages) {
        if (img.score > 5) {
          if (!primaryImage) primaryImage = img.url;
          thumbnails.add(img.url);
        }
      }
    }

    if (!primaryImage && thumbnails.size > 0) {
      primaryImage = [...thumbnails][0];
    }

    price = extractPayhipPrice(html);
    return {
      success: true,
      title,
      description,
      image: primaryImage,
      price,
      thumbnails: [...thumbnails].slice(0, 8),
    };
  } catch (e) {
    return { success: false, error: publicErrorMessage(e) };
  }
}

async function scrapeProviderMetadata(url, env = null) {
  const validated = normalizeScrapeUrl(url);
  if (!validated) return { success: false, error: "Invalid scraper URL" };
  const headers = { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36" };
  let html = "";
  try {
    const response = await fetch(validated.url, { headers, redirect: "follow", signal: AbortSignal.timeout(10000) });
    if (response.ok) html = await response.text();
  } catch (_) {}
  if (!html) {
    try {
      const jinaHeaders = { ...headers };
      if (env?.JINA_API_KEY) jinaHeaders.Authorization = `Bearer ${env.JINA_API_KEY}`;
      const response = await fetch(`https://r.jina.ai/${validated.url}`, { headers: jinaHeaders, signal: AbortSignal.timeout(12000) });
      if (response.ok) html = await response.text();
    } catch (_) {}
  }
  if (!html) return { success: false, error: "Could not fetch product page" };
  const extract = (patterns) => {
    for (const pattern of patterns) {
      const match = html.match(pattern);
      if (match?.[1]) return match[1].replace(/&amp;/g, "&").replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/<[^>]*>/g, " ").trim();
    }
    return "";
  };
  const title = extract([/<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)/i, /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:title["']/i, /<title[^>]*>([^<]+)/i, /^Title:\s*([^\r\n]+)/im, /^#\s+([^\r\n]+)/m]);
  const description = extract([/<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']+)/i, /<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)/i]);
  const image = extract([/<meta[^>]+property=["']og:image(?::secure_url)?["'][^>]+content=["']([^"']+)/i, /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image(?::secure_url)?["']/i]);
  if (!title && !image) return { success: false, error: "Product metadata unavailable" };
  return { success: true, title: title || "Product", description, image, thumbnails: image ? [image] : [], price: "" };
}

async function fetchPayhipRaw(targetUrl, env = null) {
  const headers = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
    "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    "Accept-Language": "en-US,en;q=0.9"
  };
  try {
    const resp = await fetch(targetUrl, { headers, redirect: "follow" });
    if (resp.ok) {
      const text = await resp.text();
      if (!text.includes("Just a moment...") && !text.includes("Attention Required! | Cloudflare") && !text.includes("cf-chl")) {
        return { type: "html", text };
      }
    }
  } catch (e) {}

  // Fallback to r.jina.ai when Cloudflare challenge / 403 occurs
  try {
    const cleanUrl = targetUrl.replace(/^https?:\/\//, "");
    const jHeaders = { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36" };
    if (env?.JINA_API_KEY) {
      jHeaders["Authorization"] = `Bearer ${env.JINA_API_KEY}`;
    }
    const jinaResp = await fetch(`https://r.jina.ai/https://${cleanUrl}`, { headers: jHeaders });
    if (jinaResp.ok) {
      const text = await jinaResp.text();
      return { type: "markdown", text };
    }
  } catch (e) {}

  return null;
}

function parsePayhipProductsAndCollections(payload) {
  const products = [];
  const collections = new Set();
  if (!payload || !payload.text) return { products, collections };

  const { type, text } = payload;

  if (type === "markdown") {
    // 1. Markdown link format: [Title](https://payhip.com/b/SLUG)
    const matches = [...text.matchAll(/\[([^\]]+)\]\(https?:\/\/(?:www\.)?payhip\.com\/b\/([a-zA-Z0-9]+)\)/g)];
    const seen = new Set();
    for (const m of matches) {
      const title = m[1].trim();
      const slug = m[2];
      const prodUrl = `https://payhip.com/b/${slug}`;
      if (seen.has(prodUrl)) continue;
      if (['shop', 'view all results', 'buy now', 'read more', 'cart'].includes(title.toLowerCase())) continue;
      seen.add(prodUrl);

      // Extract image preceding product link (up to 500 chars before)
      const idx = m.index;
      const pre = text.substring(Math.max(0, idx - 500), idx);
      const imgMatches = [...pre.matchAll(/!\[[^\]]*\]\((https?:\/\/[^\)]+)\)/g)];
      let image = imgMatches.length > 0 ? imgMatches[imgMatches.length - 1][1] : "";
      if (image.includes("logo") || image.includes("favicon") || image.includes("avatar")) image = "";

      // Extract price following product link (up to 200 chars after)
      const post = text.substring(idx + m[0].length, Math.min(text.length, idx + m[0].length + 200));
      const pMatch = post.match(/(?:[A-Z]{1,3}\$|\$|€|£)\s*(\d+(?:\.\d{2})?)|Free/i);
      const price = pMatch ? pMatch[0].trim() : "";

      products.push({ title, url: prodUrl, image, price, slug });
    }

    // Bare /b/SLUG fallback
    const bareSlugs = [...text.matchAll(/payhip\.com\/b\/([a-zA-Z0-9]+)/g)];
    for (const bs of bareSlugs) {
      const s = bs[1];
      const u = `https://payhip.com/b/${s}`;
      if (!seen.has(u)) {
        seen.add(u);
        products.push({ title: `Product #${s}`, url: u, image: "", price: "", slug: s });
      }
    }

    // Extract collection slugs
    const colMatches = [...text.matchAll(/\/collection\/([a-zA-Z0-9_\-]+)/g)];
    for (const c of colMatches) {
      const cSlug = c[1].toLowerCase().trim();
      if (!['all', 'users', 'cart', 'login', 'signup'].includes(cSlug)) {
        collections.add(cSlug);
      }
    }
  } else {
    // HTML format
    const cards = text.split(/<div[^>]+class=["'][^"']*product-card-wrapper/i);
    const seen = new Set();
    if (cards.length > 1) {
      for (let i = 1; i < cards.length; i++) {
        const card = cards[i];
        const slugMatch = card.match(/\/b\/([a-zA-Z0-9]+)/);
        if (!slugMatch) continue;
        const slug = slugMatch[1];
        const prodUrl = `https://payhip.com/b/${slug}`;
        if (seen.has(prodUrl)) continue;
        seen.add(prodUrl);

        const titleMatch = card.match(/<h[2-4][^>]*class=["'][^"']*card__heading[^"']*["'][^>]*>[\s\r\n]*<a[^>]+>([\s\S]*?)<\/a>/i) ||
                           card.match(/<h[2-4][^>]*>[\s\r\n]*<a[^>]+>([\s\S]*?)<\/a>/i);
        let title = "";
        if (titleMatch) {
          title = titleMatch[1].replace(/<[^>]+>/g, "").replace(/&amp;/g, "&").replace(/&#39;/g, "'").replace(/&quot;/g, '"').trim();
        }

        const imgMatch = card.match(/<img[^>]+src=["'](https?:\/\/[^"']+)["']/i);
        const image = imgMatch ? imgMatch[1] : "";

        const priceMatch = card.match(/<span[^>]*class=["'][^"']*price[^"']*["'][^>]*>([\s\S]*?)<\/span>/i);
        let price = "";
        if (priceMatch) {
          price = priceMatch[1].replace(/<[^>]+>/g, "").trim();
        }

        products.push({ title: title || `Product #${slug}`, url: prodUrl, image, price, slug });
      }
    } else {
      const matches = [...text.matchAll(/\/b\/([a-zA-Z0-9]+)/g)];
      for (const m of matches) {
        const slug = m[1];
        const prodUrl = `https://payhip.com/b/${slug}`;
        if (!seen.has(prodUrl)) {
          seen.add(prodUrl);
          products.push({ title: `Product #${slug}`, url: prodUrl, image: "", price: "", slug });
        }
      }
    }

    const colMatches = [...text.matchAll(/\/collection\/([a-zA-Z0-9_\-]+)/gi)];
    for (const c of colMatches) {
      const cSlug = c[1].toLowerCase().trim();
      if (!['all', 'users', 'cart', 'login', 'signup'].includes(cSlug)) {
        collections.add(cSlug);
      }
    }
  }

  return { products, collections };
}

async function scrapePayhipStoreProducts(storeUrl, maxPages = 25, env = null) { const result = await scanCreatorLinksWithScrapin(storeUrl, env); return result.success ? result.products || [] : []; }

async function scanCreatorLinks(rawUrl, env = null) { return scanCreatorLinksWithScrapin(rawUrl, env); }

function cleanSocialNickname(name, username) {
  if (!name) return username;
  let clean = String(name).trim();
  clean = clean.replace(/\s*\(?@[\w\.-]+\)?/g, "");
  clean = clean.replace(/\s*[•\|\-\–]\s*(Instagram|TikTok|YouTube|X|Twitter).*/i, "");
  clean = clean.replace(/^\s*(Instagram|TikTok|YouTube|X|Twitter)\s*:\s*/i, "");
  clean = clean.replace(/photos and videos/i, "");
  clean = clean.replace(/on Instagram/i, "");
  clean = clean.trim();

  const lower = clean.toLowerCase();
  if (!clean || lower === "instagram" || lower.includes("instagram") || lower === "tiktok" || lower === "youtube" || lower === "x" || lower.includes("înainte de a accesa")) {
    return username;
  }
  return clean;
}

const SOCIAL_PROFILE_FETCH_HEADERS = {
  "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
  "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
};

async function resolveTikTokPageProfile(username, env = {}) {
  const handle = String(username || "").trim().replace(/^@+/, "");
  if (!handle) return null;
  try {
    const response = await fetch(`https://www.tiktok.com/@${encodeURIComponent(handle)}`, {
      headers: { ...SOCIAL_PROFILE_FETCH_HEADERS },
      signal: AbortSignal.timeout(7000),
    });
    if (!response.ok) return null;
    const html = await response.text();
    const marker = '"webapp.user-detail":';
    const markerIndex = html.indexOf(marker);
    const objectStart = markerIndex >= 0 ? html.indexOf("{", markerIndex + marker.length) : -1;
    const objectEnd = objectStart >= 0 ? html.indexOf(',"webapp.a-b"', objectStart) : -1;
    if (objectStart < 0 || objectEnd <= objectStart) return null;
    const detail = JSON.parse(html.slice(objectStart, objectEnd));
    const user = detail?.userInfo?.user;
    if (!user) return null;
    const avatarSource = String(user.avatarLarger || user.avatarMedium || user.avatarThumb || "").trim();
    let avatar = avatarSource;
    if (avatarSource && env?.STORAGE) {
      const cached = await storeAndProxyImage(env, avatarSource).catch(() => "");
      if (cached && cached.includes("thumbnail.zyrexediting.xyz")) avatar = cached;
    }
    return {
      success: true,
      platform: "tiktok",
      username: String(user.uniqueId || handle),
      nickname: String(user.nickname || user.uniqueId || handle),
      account_id: String(user.id || user.userId || user.secUid || ""),
      avatar,
      bioLink: user.bioLink?.link || null,
    };
  } catch (_) { return null; }
}

async function resolveSocialProfile(targetUrl, env = {}) { const input = String(targetUrl || "").trim(); const normalizedUrl = input.slice(0,4).toLowerCase() === "http" ? input : "https://www.tiktok.com/@" + input.replace(/^@+/, ""); const creator = await scrapinSocialProfile(env, normalizedUrl).catch(() => null); if (!creator) return { success: false, error: "Scrapin creator lookup failed", source: "scrapin" }; return { success: true, platform: creator.platform || "", nickname: creator.name || creator.handle || "", username: creator.handle || "", account_id: creator.account_id || "", avatar: creator.avatar || "", bioLink: (creator.links || [])[0] || null, bio: creator.bio || "", links: creator.links || [], source: "scrapin" }; }


async function uploadThumbnailToCDN(env, imageUrl, productId) {
  if (!imageUrl || !productId) return imageUrl;
  try {
    const resp = await fetch(imageUrl, {
      headers: { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36" },
    });
    if (!resp.ok) {
      console.error("Thumbnail download failed:", resp.status, imageUrl.substring(0, 80));
      return imageUrl;
    }
    const buffer = await resp.arrayBuffer();
    const bytes = new Uint8Array(buffer);
    const ext = (imageUrl.split('.').pop()?.split('?')[0] || 'jpg').toLowerCase();
    const filename = `${productId}.${ext}`;
    
    await env.STORAGE.put(`thumbnails/${filename}`, bytes);
    return `https://thumbnail.zyrexediting.xyz/${filename}`;
  } catch(e) {
    console.error("Thumbnail upload error:", e.message);
    return imageUrl;
  }
}

// Simple hash for image URL → short filename
async function hashImageUrl(url) {
  const data = new TextEncoder().encode(url);
  const hashBuffer = await crypto.subtle.digest("SHA-256", data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, "0")).join("").slice(0, 16);
}

// Download + cache thumbnail to R2 (fire-and-forget)
async function cacheThumbnail(env, imageUrl, filename) {
  try {
    // Check if already cached
    const existing = await env.STORAGE.get(`thumbnails/${filename}`);
    if (existing) return;
    
    const resp = await fetch(imageUrl);
    if (!resp.ok) return;
    const buffer = await resp.arrayBuffer();
    await env.STORAGE.put(`thumbnails/${filename}`, new Uint8Array(buffer));
  } catch(e) {
    console.error("Cache thumbnail error:", e.message);
  }
}

const presenceCache = new Map();

// Known fallback profiles for founders
const FOUNDER_PROFILES = {
  "1421177012814614548": {
    id: "1421177012814614548",
    username: "reyliar",
    global_name: "reyli",
    avatar: "https://cdn.discordapp.com/avatars/1421177012814614548/66077819163365312e485b95e30001d8.png?size=256"
  }
};

async function handlePresenceAPI(request, env) {
  const url = new URL(request.url);

  // POST /api/presence/update: receive Gateway presence update and save to R2 + cache
  if (request.method === "POST" && (url.pathname === "/api/presence/update" || url.pathname === "/api/presence/update/")) {
    try {
      const body = await request.json();
      const { id, user, status, activities, client_status } = body;
      if (!id) return json({ error: "id required" }, 400);

      const knownFallback = FOUNDER_PROFILES[id] || { id, username: "User", global_name: "User" };
      const existing = presenceCache.get(id)?.data || knownFallback;

      let avatarUrl = existing.avatar || knownFallback.avatar;
      if (user && user.avatar) {
        const ext = String(user.avatar).startsWith("a_") ? "gif" : "png";
        avatarUrl = `https://cdn.discordapp.com/avatars/${id}/${user.avatar}.${ext}?size=256`;
      }

      const updated = {
        ...existing,
        id,
        username: user?.username || existing.username || knownFallback.username,
        global_name: user?.global_name || user?.username || existing.global_name || knownFallback.global_name,
        avatar: avatarUrl,
        status: status || existing.status || "offline",
        online: (status || existing.status) !== "offline",
        activities: activities || existing.activities || [],
        client_status: client_status || {},
        updated_at: Date.now()
      };

      presenceCache.set(id, { data: updated, expiry: Date.now() + 60000 });
      if (env.STORAGE) {
        await env.STORAGE.put("presence/" + id, JSON.stringify(updated)).catch(() => {});
      }

      return json({ success: true, id, status: updated.status });
    } catch(e) {
      return json({ error: publicErrorMessage(e) }, 500);
    }
  }
  
  let idsParam = url.searchParams.get("ids") || url.searchParams.get("id");
  if (!idsParam) {
    const parts = url.pathname.split("/").filter(Boolean);
    if (parts.length >= 3 && parts[1] === "presence") {
      idsParam = parts[2];
    }
  }
  
  if (!idsParam) {
    idsParam = "1421177012814614548";
  }

  const ids = idsParam.split(",").map(i => i.trim()).filter(Boolean);
  if (ids.length === 0) {
    return json({ success: false, error: "No user ID specified" }, 400);
  }

  const results = {};

  await Promise.all(ids.map(async (id) => {
    // Check 2-second TTL cache for fast response
    const cached = presenceCache.get(id);
    if (cached && Date.now() < cached.expiry) {
      results[id] = cached.data;
      return;
    }

    // 1. Primary: Fetch live presence directly from VPS Bot HTTP API (storage.zyrexediting.xyz/api/presence/:id)
    let vpsPresence = null;
    try {
      const vpsRes = await fetch(`https://storage.zyrexediting.xyz/api/presence/${id}`, {
        headers: { "Accept": "application/json", "User-Agent": "ZyrexWorker/1.0" },
        cf: { cacheTtl: 2 }
      });
      if (vpsRes.ok) {
        const vpsJson = await vpsRes.json();
        if (vpsJson && vpsJson.success && vpsJson.data) {
          vpsPresence = vpsJson.data;
        }
      }
    } catch (e) {
      console.error(`VPS Presence fetch error for ${id}:`, e.message);
    }

    if (vpsPresence && vpsPresence.status) {
      presenceCache.set(id, { data: vpsPresence, expiry: Date.now() + 2000 });
      results[id] = vpsPresence;
      return;
    }

    // 2. Fallback: Check Gateway R2 storage
    let r2Presence = null;
    if (env.STORAGE) {
      try {
        const obj = await env.STORAGE.get("presence/" + id);
        if (obj) {
          r2Presence = await obj.json();
        }
      } catch(e) {}
    }

    // 2. Fetch Official Discord REST API user data (/users/{id}) if bot token exists
    let discordUserObj = null;
    if (env.DISCORD_BOT_TOKEN) {
      try {
        const dRes = await fetch(`https://discord.com/api/v10/users/${id}`, {
          headers: { "Authorization": `Bot ${env.DISCORD_BOT_TOKEN}` }
        });
        if (dRes.ok) {
          discordUserObj = await dRes.json();
        }
      } catch (e) {}
    }

    // 3. Multi-instance Lanyard mirrors (api.lanyard.rest, lanyard.cnrad.dev, api.phx.li)
    let lanyardData = null;
    const mirrors = [
      `https://api.lanyard.rest/v1/users/${id}`,
      `https://lanyard.cnrad.dev/v1/users/${id}`,
      `https://api.phx.li/v1/users/${id}`
    ];
    for (const mirror of mirrors) {
      try {
        const lRes = await fetch(mirror, {
          headers: { "Accept": "application/json", "User-Agent": "ZyrexPresenceAPI/1.0" }
        });
        if (lRes.ok) {
          const lJson = await lRes.json();
          if (lJson && lJson.success && lJson.data) {
            lanyardData = lJson.data;
            break;
          }
        }
      } catch (e) {}
    }

    // 4. Baseline Founder Fallback
    const knownFallback = FOUNDER_PROFILES[id] || {
      id,
      username: "User",
      global_name: "User",
      avatar: "https://cdn.discordapp.com/embed/avatars/0.png"
    };

    const u = discordUserObj || r2Presence || lanyardData?.discord_user || knownFallback;
    const status = r2Presence?.status || lanyardData?.discord_status || (discordUserObj ? "online" : "dnd");

    // Construct full CDN avatar URL
    let avatarUrl = knownFallback.avatar;
    if (u.avatar) {
      if (String(u.avatar).startsWith("http")) {
        avatarUrl = u.avatar;
      } else {
        const ext = String(u.avatar).startsWith("a_") ? "gif" : "png";
        avatarUrl = `https://cdn.discordapp.com/avatars/${u.id || id}/${u.avatar}.${ext}?size=256`;
      }
    }

    let bannerUrl = null;
    if (u.banner) {
      const ext = String(u.banner).startsWith("a_") ? "gif" : "png";
      bannerUrl = `https://cdn.discordapp.com/banners/${u.id || id}/${u.banner}.${ext}?size=600`;
    }

    const activities = (r2Presence?.activities && r2Presence.activities.length > 0)
      ? r2Presence.activities
      : (lanyardData?.activities || []).map(act => {
          const appId = act.application_id || null;
          function lanyardKeyToUrl(key) {
            if (!key) return null;
            const k = String(key);
            if (k.startsWith("spotify:")) return `https://i.scdn.co/image/${k.replace("spotify:", "")}`;
            if (k.startsWith("mp:external/")) {
              const raw = k.replace("mp:external/", "");
              if (raw.startsWith("https/")) return "https://" + raw.slice(6);
              if (raw.startsWith("http/")) return "http://" + raw.slice(5);
              return `https://media.discordapp.net/external/${raw}`;
            }
            if (appId) return `https://cdn.discordapp.com/app-assets/${appId}/${k}.png`;
            return null;
          }
          const largeKey = act.assets?.large_image || null;
          const smallKey = act.assets?.small_image || null;
          let largeUrl = lanyardKeyToUrl(largeKey);
          const smallUrl = lanyardKeyToUrl(smallKey);
          if (!largeUrl && appId) largeUrl = `https://cdn.discordapp.com/app-icons/${appId}/icon.png`;
          let startTs = act.timestamps?.start || null;
          if (startTs && typeof startTs === "number" && startTs < 10000000000) startTs = startTs * 1000;
          let endTs = act.timestamps?.end || null;
          if (endTs && typeof endTs === "number" && endTs < 10000000000) endTs = endTs * 1000;
          return {
            name: act.name,
            type: act.type,
            state: act.state || null,
            details: act.details || null,
            emoji: act.emoji || null,
            large_image_url: largeUrl,
            image_url: largeUrl,
            small_image_url: smallUrl,
            large_text: act.assets?.large_text || null,
            small_text: act.assets?.small_text || null,
            start_timestamp: startTs,
            end_timestamp: endTs,
            application_id: appId ? String(appId) : null
          };
        });

    const spotify = r2Presence?.spotify || (lanyardData?.spotify ? {
      song: lanyardData.spotify.song,
      artist: lanyardData.spotify.artist,
      album: lanyardData.spotify.album,
      album_art_url: lanyardData.spotify.album_art_url,
      track_id: lanyardData.spotify.track_id
    } : null);

    const presenceData = {
      id: u.id || id,
      username: u.username || knownFallback.username,
      global_name: u.global_name || u.username || knownFallback.global_name,
      avatar: avatarUrl,
      banner: bannerUrl,
      status: status, // "online", "idle", "dnd", "offline"
      online: status !== "offline",
      active_on_discord_web: !!lanyardData?.active_on_discord_web,
      active_on_discord_desktop: !!lanyardData?.active_on_discord_desktop,
      active_on_discord_mobile: !!lanyardData?.active_on_discord_mobile,
      listening_to_spotify: !!spotify,
      spotify: spotify,
      activities: activities,
      updated_at: Date.now()
    };

    presenceCache.set(id, { data: presenceData, expiry: Date.now() + 2000 });
    results[id] = presenceData;
  }));

  if (ids.length === 1) {
    return json({ success: true, data: results[ids[0]] });
  }

  return json({ success: true, count: ids.length, data: results });
}

// Download & store an image in R2 so it is served from our own permanent
// thumbnail CDN. Social platforms hand out signed links that expire, so any
// external image that is not copied here will eventually stop loading.
async function storeAndProxyImage(env, imageUrl) {
  if (!imageUrl || typeof imageUrl !== 'string') return '';
  // Admin forms may paste a URL copied from rendered HTML, where query
  // separators arrive as entities (for example Boosty's change_time image URL).
  imageUrl = imageUrl.trim()
    .replace(/&amp;/gi, "&")
    .replace(/&#0*38;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#0*39;|&apos;/gi, "'");
  if (imageUrl.includes("thumbnail.zyrexediting.xyz")) return imageUrl;
  if (!env || !env.STORAGE) return imageUrl;

  try {
    const hash = await hashImageUrl(imageUrl);
    const imagePath = new URL(imageUrl).pathname;
    const ext = (imagePath.split('.').pop() || 'jpg').toLowerCase().slice(0, 4);
    const cleanExt = ['jpg', 'jpeg', 'png', 'webp', 'gif'].includes(ext) ? ext : 'jpg';
    const filename = `${hash}.${cleanExt}`;
    const cdnUrl = `https://thumbnail.zyrexediting.xyz/${filename}`;

    const existing = await env.STORAGE.get(`thumbnails/${filename}`);
    if (existing) return cdnUrl;

    const headers = {
      "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
      "Accept": "image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8"
    };

    const resp = await fetch(imageUrl, { headers, signal: AbortSignal.timeout(15000) });
    const contentType = String(resp.headers.get("Content-Type") || "").toLowerCase();
    if (resp.ok && contentType.startsWith("image/")) {
      const buffer = await resp.arrayBuffer();
      await env.STORAGE.put(`thumbnails/${filename}`, new Uint8Array(buffer), {
        httpMetadata: { contentType: contentType || "image/jpeg" }
      });
      return cdnUrl;
    }
  } catch(e) {
    console.error("storeAndProxyImage failed:", e.message);
  }
  return imageUrl;
}

// ── Public profiles ────────────────────────────────────────────────────────────
// One page per member at /@handle. Identity, resources and every statistic are
// derived from data the site already stores, so the only new state is: the handle
// index, per-member settings, profile views, achievement unlock dates and follows.
const PROFILE_HANDLES_KEY = "profiles/handles.json";
const PROFILE_SETTINGS_PREFIX = "profiles/settings/";
const PROFILE_VIEWS_KEY = "profiles/views.json";
const PROFILE_ACHIEVEMENTS_PREFIX = "profiles/achievements/";
const PROFILE_FOLLOWS_PREFIX = "profiles/follows/";
const PROFILE_AGGREGATES_KEY = "profiles/aggregates.json";
// Rebuilt lazily: the whole catalogue is scanned once and every profile request
// reads the cached result instead of re-deriving it per visitor.
const PROFILE_AGGREGATES_TTL_MS = 10 * 60 * 1000;
const PROFILE_MAX_HANDLE_LENGTH = 24;
const PROFILE_MAX_FOLLOWS = 5000;
const PROFILE_VIEW_DAYS_KEPT = 31;
const PROFILE_HANDLE_COOLDOWN_MS = 7 * 24 * 60 * 60 * 1000;
// Handles that would look official or impersonate staff. This is not about route
// collisions: /@handle can never shadow /handle.
const PROFILE_RESERVED_HANDLES = new Set([
  "about", "access", "admin", "admin-publish", "admin-upload", "admin-vt-scan", "api",
  "assets", "audio", "bookmarks", "contact", "css", "dmca", "download", "feed", "hlx",
  "js", "leaderboards", "login", "logout", "me", "moderator", "new", "official", "owner",
  "plugins", "press", "preset", "presets", "privacy", "profile", "request", "requests",
  "resource", "resources", "scenepack", "scenepacks", "search", "settings", "staff",
  "status", "support", "team", "terms", "upload", "upload-audio", "upload-scenepack",
  "user", "users", "verify", "zyrex",
]);
const PROFILE_TIERS = {
  official: { label: "Official", icon: "fa-certificate", accent: "#3b82f6" },
  founder: { label: "Founder", icon: "fa-crown", accent: "#ffd166" },
  staff: { label: "Staff", icon: "fa-shield-halved", accent: "rgba(var(--zr-rgb-255-92-122, 255, 92, 122), 1)" },
  contributor: { label: "Contributor", icon: "fa-hand-holding-heart", accent: "#c084fc" },
  uploader: { label: "Uploader", icon: "fa-cloud-arrow-up", accent: "var(--zr-accent, rgba(var(--zr-rgb-255-43-82, 255, 43, 82), 1))" },
  creator: { label: "Creator", icon: "fa-star", accent: "#38bdf8" },
  member: { label: "Member", icon: "fa-user", accent: "#94a3b8" },
};

function normalizeHandle(raw) {
  return String(raw == null ? "" : raw).trim().replace(/^@+/, "").toLowerCase();
}

function isValidHandle(handle) {
  if (!handle || handle.length > PROFILE_MAX_HANDLE_LENGTH) return false;
  if (!/^[a-z0-9][a-z0-9._-]*$/.test(handle)) return false;
  if (/[._-]$/.test(handle) || handle.includes("..")) return false;
  return !PROFILE_RESERVED_HANDLES.has(handle);
}

function profileSettingsKey(discordId) {
  return PROFILE_SETTINGS_PREFIX + String(discordId || "").trim() + ".json";
}

function profileAchievementsKey(discordId) {
  return PROFILE_ACHIEVEMENTS_PREFIX + String(discordId || "").trim() + ".json";
}

function profileFollowsKey(discordId) {
  return PROFILE_FOLLOWS_PREFIX + String(discordId || "").trim() + ".json";
}

function profilePostsKey(discordId) {
  return "profiles/posts/" + String(discordId || "").trim() + ".json";
}

// Posts get a short, human link (/feed/post/12) instead of a uuid. The index is a
// single small document: seq -> { author_id, post_id }.
const FEED_POST_INDEX_KEY = "feed/post_index.json";
const FEED_POST_INDEX_TTL_MS = 30 * 1000;
const FEED_SEQ_MEMO_MS = 60 * 1000;
let feedPostIndexMemo = null;
let feedSeqBackfillAt = 0;

async function readFeedPostIndex(env) {
  const now = Date.now();
  if (feedPostIndexMemo && now - feedPostIndexMemo.at < FEED_POST_INDEX_TTL_MS) return feedPostIndexMemo.value;
  let stored = null;
  try { stored = await r2GetJSON(env, FEED_POST_INDEX_KEY, null); } catch (_) { stored = null; }
  const value = stored && typeof stored === "object" && stored.entries && typeof stored.entries === "object"
    ? { next: Math.max(Number(stored.next) || 1, 1), entries: stored.entries }
    : { next: 1, entries: {} };
  feedPostIndexMemo = { at: now, value };
  return value;
}

async function writeFeedPostIndex(env, index) {
  feedPostIndexMemo = { at: Date.now(), value: index };
  return Boolean(await r2PutJSON(env, FEED_POST_INDEX_KEY, {
    version: 1,
    next: Math.max(Number(index.next) || 1, 1),
    entries: index.entries,
    updated_at: new Date().toISOString(),
  }).catch(() => false));
}

function feedSeqOf(index, authorId, postId) {
  for (const [seq, entry] of Object.entries(index.entries || {})) {
    if (entry && String(entry.post_id) === String(postId) && String(entry.author_id) === String(authorId)) return Number(seq);
  }
  return 0;
}

// R2 has no atomic counter, so a collision after a racing write just retries.
async function allocateFeedSequence(env, authorId, postId) {
  const author = String(authorId || "").trim();
  const id = String(postId || "").trim();
  if (!/^\d{15,25}$/.test(author) || !/^[a-f0-9-]{16,40}$/i.test(id)) return 0;
  for (let attempt = 0; attempt < 3; attempt += 1) {
    const index = await readFeedPostIndex(env);
    const existing = feedSeqOf(index, author, id);
    if (existing) return existing;
    let seq = Math.max(Number(index.next) || 1, 1);
    while (index.entries[String(seq)]) seq += 1;
    const next = { next: seq + 1, entries: { ...index.entries, [String(seq)]: { author_id: author, post_id: id, created_at: new Date().toISOString() } } };
    const saved = await writeFeedPostIndex(env, next);
    if (!saved) continue;
    const verify = await readFeedPostIndex(env);
    const stored = verify.entries[String(seq)];
    if (stored && stored.post_id === id && stored.author_id === author) return seq;
  }
  return 0;
}

// Existing posts get their numbers in creation order, once, so old links keep working.
async function backfillFeedSequences(env, options = {}) {
  const now = Date.now();
  if (!options.force && now - feedSeqBackfillAt < FEED_SEQ_MEMO_MS) return readFeedPostIndex(env);
  feedSeqBackfillAt = now;
  const files = await r2List(env, "profiles/feed/").catch(() => []);
  const rows = [];
  for (const file of (files || []).slice(0, 400)) {
    const entry = await r2GetJSON(env, file.key, null).catch(() => null);
    if (!entry || !entry.post || !entry.author_id) continue;
    rows.push({ author_id: String(entry.author_id), post_id: String(entry.post.id || ""), created: Number(entry.post.created_at ? Date.parse(entry.post.created_at) : 0) || 0 });
  }
  rows.sort((a, b) => a.created - b.created);
  const index = await readFeedPostIndex(env);
  const known = new Map();
  for (const [seq, entry] of Object.entries(index.entries || {})) {
    if (entry && entry.post_id) known.set(String(entry.post_id), Number(seq));
  }
  let seq = Math.max(Number(index.next) || 1, 1);
  const entries = { ...index.entries };
  for (const row of rows) {
    if (!row.post_id || known.has(row.post_id)) continue;
    while (entries[String(seq)]) seq += 1;
    entries[String(seq)] = { author_id: row.author_id, post_id: row.post_id, created_at: new Date(row.created || Date.now()).toISOString() };
    known.set(row.post_id, seq);
    seq += 1;
  }
  const next = { next: Math.max(seq, Number(index.next) || 1), entries };
  await writeFeedPostIndex(env, next);
  return next;
}

function profileFeedPostKey(discordId, post) {
  const created = Date.parse(post && post.created_at || "") || Date.now();
  const id = String(post && post.id || "").replace(/[^a-f0-9-]/gi, "");
  return `profiles/feed/${String(created).padStart(13, "0")}-${String(discordId || "")}-${id}.json`;
}

function sanitizeProfileMentions(input, text) {
  if (!Array.isArray(input)) return [];
  const body = String(text || "");
  const seen = new Set();
  return input.slice(0, 30).map(mention => ({
    id: String(mention && mention.id || "").trim(),
    username: String(mention && mention.username || "").trim().replace(/^@+/, ""),
  })).filter(mention => {
    if (!/^\d{17,20}$/.test(mention.id) || !/^[a-zA-Z0-9_.-]{1,32}$/.test(mention.username)) return false;
    const key = mention.id + ":" + mention.username.toLowerCase();
    if (seen.has(key) || !body.toLowerCase().includes("@" + mention.username.toLowerCase())) return false;
    seen.add(key);
    return true;
  });
}

// Hashtags are stored with the post so the feed can filter without scanning text.
const PROFILE_POST_TAG_LIMIT = 6;

function profilePostTags(text) {
  const tags = [];
  const pattern = /(?:^|[^a-zA-Z0-9_])#([a-zA-Z0-9_]{2,24})/g;
  let match;
  while ((match = pattern.exec(String(text || ""))) !== null) {
    const tag = match[1].toLowerCase();
    if (!tags.includes(tag)) tags.push(tag);
    if (tags.length >= PROFILE_POST_TAG_LIMIT) break;
  }
  return tags;
}

function sanitizeProfilePost(post, authorId) {
  if (!post || typeof post !== "object") return null;
  const text = String(post.text || "").trim().slice(0, 1200);
  const media = Array.isArray(post.media)
    ? post.media.map(value => sanitizeProfileMediaUrl(value, authorId || post.author_id)).filter(Boolean).slice(0, 4)
    : [];
  const links = sanitizePostLinks(post.links);
  const video = sanitizePostVideo(post.video, authorId || post.author_id);
  const repost = post.repost_of && typeof post.repost_of === "object" ? {
    author_id: String(post.repost_of.author_id || "").trim(),
    post_id: String(post.repost_of.post_id || "").trim(),
  } : null;
  if (repost && (!/^\d{15,25}$/.test(repost.author_id) || !/^[a-f0-9-]{16,40}$/i.test(repost.post_id))) return null;
  const id = String(post.id || "");
  if (!/^[a-f0-9-]{16,40}$/i.test(id)) return null;
  if (!text && !media.length && !links.length && !video && !repost) return null;
  return {
    id,
    author_id: String(authorId || post.author_id || "").trim(),
    author: post.author && typeof post.author === "object" ? {
      name: String(post.author.name || "").slice(0, 80),
      handle: normalizeHandle(post.author.handle),
      avatar: String(post.author.avatar || "").slice(0, 500),
      url: String(post.author.url || "").slice(0, 300),
    } : null,
    text,
    media,
    links,
    video,
    mentions: sanitizeProfileMentions(post.mentions, text),
    tags: profilePostTags(text),
    seq: Number.isFinite(Number(post.seq)) && Number(post.seq) > 0 ? Number(post.seq) : 0,
    edited_at: Number.isFinite(Date.parse(post.edited_at)) ? new Date(post.edited_at).toISOString() : "",
    repost_of: repost,
    created_at: String(post.created_at || ""),
  };
}

async function readProfilePosts(env, discordId) {
  const id = String(discordId || "").trim();
  if (!/^\d{15,25}$/.test(id)) return [];
  const stored = await r2GetJSON(env, profilePostsKey(id), null);
  return (Array.isArray(stored && stored.posts) ? stored.posts : [])
    .map(post => sanitizeProfilePost(post, id)).filter(Boolean)
    .sort((a, b) => String(b.created_at).localeCompare(String(a.created_at)));
}

async function readProfilePost(env, authorId, postId) {
  return (await readProfilePosts(env, authorId)).find(post => post.id === String(postId || "")) || null;
}

function defaultProfileSettings(discordId) {
  return {
    discord_id: String(discordId || "").trim(),
    handle: "",
    // Public by default: the whole point is a shareable page. Members can turn it
    // off, and the anonymous counter stays private either way.
    public: true,
    show_downloads: true,
    show_activity: true,
    show_connections: true,
    bio: "",
    links: [],
    accent: "",
    updated_at: null,
  };
}

const PROFILE_LINK_LIMIT = 8;
// Only photo hosts a social platform actually serves from are accepted, so a saved
// link can never point the profile at an arbitrary URL.
const SOCIAL_AVATAR_HOSTS = [
  /(^|\.)cdninstagram\.com$/i,
  /(^|\.)fbcdn\.net$/i,
  /(^|\.)tiktokcdn[-a-z0-9]*\.com$/i,
  /(^|\.)tiktok\.com$/i,
  /(^|\.)yt3\.ggpht\.com$/i,
  /(^|\.)yt3\.googleusercontent\.com$/i,
  /(^|\.)pbs\.twimg\.com$/i,
  /(^|\.)licdn\.com$/i,
  /(^|\.)cdn\.discordapp\.com$/i,
  /(^|\.)steamstatic\.com$/i,
  /(^|\.)steamcommunity\.com$/i,
  /(^|\.)rbxcdn\.com$/i,
  /(^|\.)roblox\.com$/i,
  /^thumbnail\.zyrexediting\.xyz$/i,
  /(^|\.)giphy\.com$/i,
  /(^|\.)tenor\.com$/i,
];

function sanitizeSocialAvatar(value) {
  const raw = String(value || "").trim();
  if (!raw || raw.length > 500) return "";
  let parsed;
  try { parsed = new URL(raw); } catch (_) { return ""; }
  if (parsed.protocol !== "https:") return "";
  return SOCIAL_AVATAR_HOSTS.some(pattern => pattern.test(parsed.hostname)) ? raw : "";
}

// Link fields arrive from a text input, so a bare "site.com/user" is completed instead
// of being thrown away by the URL parser.
function normalizeProfileLinkUrl(value) {
  const raw = String(value == null ? "" : value).trim().slice(0, 300);
  if (!raw) return "";
  return /^[a-z][a-z0-9+.-]*:\/\//i.test(raw) ? raw : `https://${raw}`;
}

function sanitizeProfileLinks(input) {
  if (!Array.isArray(input)) return [];
  const out = [];
  for (const item of input.slice(0, PROFILE_LINK_LIMIT)) {
    const label = String((item && item.label) || "").trim().slice(0, 24);
    const rawUrl = String((item && item.url) || "").trim().slice(0, 300);
    const url = /^https?:\/\//i.test(rawUrl) ? rawUrl : "";
    const platformKey = String((item && item.platform) || "").trim().toLowerCase().slice(0, 24);
    const game = gamePlatform(platformKey);
    if (game) {
      const handle = sanitizeGameHandle(item && (item.handle || item.name), game.key);
      if (!handle) continue;
      const name = String((item && item.name) || "").trim().slice(0, 60);
      const detail = String((item && item.detail) || "").trim().slice(0, 40);
      const avatar = sanitizeSocialAvatar(item && item.avatar);
      // Roblox has a real profile page; Riot games only exist inside their client.
      const gameUrl = game.key === "roblox" && /^https:\/\/www\.roblox\.com\/users\/\d{1,20}\/profile$/i.test(rawUrl) ? rawUrl : "";
      out.push({
        label: label || game.label,
        url: gameUrl,
        platform: game.key,
        icon: game.icon,
        handle,
        ...(name ? { name } : {}),
        ...(detail ? { detail } : {}),
        ...(avatar ? { avatar } : {}),
      });
      continue;
    }
    if (!url) continue;
    const claimedPlatform = SOCIAL_LINK_PLATFORMS.find(entry => entry.key === platformKey) || null;
    const claimedHandle = normalizeHandle(item && item.handle).slice(0, 60);
    // The URL is what visitors click and what gets scraped, so a profile-shaped URL wins
    // over a platform or handle left over from an older edit.
    const detected = socialLinkPlatform(url);
    const platform = detected && detected.handle ? detected.platform : claimedPlatform;
    const handle = detected && detected.handle ? detected.handle : claimedHandle;
    const identityChanged = (claimedPlatform ? claimedPlatform.key : platformKey) !== (platform ? platform.key : platformKey)
      || claimedHandle !== handle;
    // A photo and a name belong to the account they were scraped from, so they are dropped
    // as soon as the link points somewhere else.
    const name = identityChanged ? "" : String((item && item.name) || "").trim().slice(0, 60);
    const avatar = identityChanged ? "" : sanitizeSocialAvatar(item && item.avatar);
    out.push({
      label: label || (platform ? platform.label : "Link"),
      url,
      ...(platform ? { platform: platform.key, icon: platform.icon } : {}),
      ...(handle && /^[a-z0-9._-]{2,60}$/.test(handle) ? { handle } : {}),
      ...(name ? { name } : {}),
      ...(avatar ? { avatar } : {}),
    });
  }
  return out;
}

function sanitizeProfileBio(input) {
  // Plain text only: the page escapes it, and a bio has no business carrying markup.
  return String(input == null ? "" : input).replace(/\s+/g, " ").trim().slice(0, 400);
}

// ── The Zyrex official profile ───────────────────────────────────────────────
// The site's own Discord account (the logger bot) is a real guild member, so the
// official profile borrows that identity instead of inventing a fake one.
const ZYREX_PROFILE_KEY = "database/zyrex_profile.json";
const ZYREX_HANDLE = "zyrex";
const ZYREX_BIO = "Zyrex's official profile.";
const ZYREX_IDENTITY_TTL_MS = 6 * 60 * 60 * 1000;
const ZYREX_FOLLOWER_LIMIT = 20000;
let zyrexIdentityMemo = null;

async function fetchZyrexIdentity(env) {
  const token = getSiteLogBotToken(env);
  if (!token) return null;
  try {
    const response = await fetch(`${DISCORD_API}/users/@me`, {
      headers: { Authorization: `Bot ${token}` },
      signal: AbortSignal.timeout(4000),
    });
    if (!response.ok) return null;
    const user = await response.json().catch(() => null);
    const id = String((user && user.id) || "");
    if (!/^\d{15,25}$/.test(id)) return null;
    return {
      id,
      name: String(user.global_name || user.username || "Zyrex").slice(0, 60),
      username: String(user.username || "zyrex").slice(0, 40),
      avatar_hash: String(user.avatar || ""),
    };
  } catch (_) {
    return null;
  }
}

async function resolveZyrexProfile(env) {
  const now = Date.now();
  if (zyrexIdentityMemo && now - zyrexIdentityMemo.at < ZYREX_IDENTITY_TTL_MS) return zyrexIdentityMemo.value;
  let stored = null;
  try { stored = await r2GetJSON(env, ZYREX_PROFILE_KEY, null); } catch (_) { stored = null; }
  const cachedValid = stored && /^\d{15,25}$/.test(String(stored.id || ""));
  let identity = cachedValid && now - Number(stored.checked_at || 0) < ZYREX_IDENTITY_TTL_MS ? stored : null;
  if (!identity) {
    const live = await fetchZyrexIdentity(env);
    if (live) {
      identity = { ...live, checked_at: now };
      await r2PutJSON(env, ZYREX_PROFILE_KEY, { version: 1, ...identity }).catch(() => false);
    } else if (cachedValid) {
      identity = stored;
    }
  }
  const value = identity ? {
    id: String(identity.id),
    name: String(identity.name || "Zyrex"),
    username: String(identity.username || "zyrex"),
    avatar_hash: String(identity.avatar_hash || ""),
    avatar: identity.avatar_hash
      ? profileAvatarUrl(String(identity.id), identity.avatar_hash)
      : "/assets/content.png",
    handle: ZYREX_HANDLE,
    bio: ZYREX_BIO,
  } : null;
  zyrexIdentityMemo = { at: now, value };
  return value;
}

async function zyrexProfileId(env) {
  const identity = await resolveZyrexProfile(env).catch(() => null);
  return identity ? identity.id : "";
}

async function isOfficialProfileId(env, userId) {
  const id = String(userId || "").trim();
  if (!/^\d{15,25}$/.test(id)) return false;
  return (await zyrexProfileId(env)) === id;
}

// The @zyrex handle belongs to the official account and can never be claimed.
async function ensureZyrexHandle(env, officialId) {
  const id = String(officialId || "").trim();
  if (!/^\d{15,25}$/.test(id)) return false;
  const index = await readHandleIndex(env);
  const existing = index.handles[ZYREX_HANDLE];
  if (existing && String(existing.id || "") === id) return true;
  index.handles[ZYREX_HANDLE] = { id, handle: ZYREX_HANDLE, updated_at: new Date().toISOString() };
  const saved = await r2PutJSON(env, PROFILE_HANDLES_KEY, index).catch(() => false);
  if (saved) invalidateHandleIndex();
  return Boolean(saved);
}

// The roster is the one place that knows every member's display name and photo
// without a per-member lookup, so it is cached whole and reused by follow lists,
// mention suggestions and the official follower sync.
const GUILD_ROSTER_KEY = "database/guild_roster.json";
const GUILD_ROSTER_TTL_MS = 5 * 60 * 1000;
let guildRosterMemo = null;

function rosterRow(row) {
  const user = (row && row.user) || {};
  const id = String(user.id || "");
  if (!/^\d{15,25}$/.test(id)) return null;
  const username = String(user.username || "").slice(0, 40);
  const display = String(user.global_name || user.nick || username || "").slice(0, 60);
  return {
    id,
    username,
    display_name: display || username,
    avatar_hash: String(user.avatar || ""),
    bot: user.bot === true,
    joined_at: String((row && row.joined_at) || ""),
  };
}

async function fetchGuildRosterLive(env) {
  const token = getSiteLogBotToken(env);
  const guildId = (env && env.GUILD_ID) || "1518954946110685184";
  if (!token) return [];
  const seen = new Map();
  let after = "";
  for (let page = 0; page < 10; page += 1) {
    const target = new URL(`${DISCORD_API}/guilds/${guildId}/members`);
    target.searchParams.set("limit", "1000");
    if (after) target.searchParams.set("after", after);
    const response = await fetch(target.toString(), {
      headers: { Authorization: `Bot ${token}` },
      signal: AbortSignal.timeout(6000),
    }).catch(() => null);
    if (!response || !response.ok) break;
    const rows = await response.json().catch(() => []);
    if (!Array.isArray(rows) || !rows.length) break;
    for (const row of rows) {
      const entry = rosterRow(row);
      if (entry && !entry.bot) seen.set(entry.id, entry);
    }
    after = String(((rows[rows.length - 1] || {}).user || {}).id || "");
    if (rows.length < 1000 || !after) break;
  }
  return [...seen.values()];
}

async function readGuildRoster(env, options = {}) {
  const now = Date.now();
  const maxAge = Number(options.maxAgeMs) > 0 ? Number(options.maxAgeMs) : GUILD_ROSTER_TTL_MS;
  if (guildRosterMemo && now - guildRosterMemo.at < maxAge) return guildRosterMemo.members;
  let stored = null;
  try { stored = await r2GetJSON(env, GUILD_ROSTER_KEY, null); } catch (_) { stored = null; }
  const cached = stored && Array.isArray(stored.members) ? stored : null;
  if (cached && now - Number(cached.at || 0) < maxAge) {
    guildRosterMemo = { at: Number(cached.at) || now, members: cached.members };
    return cached.members;
  }
  const live = await fetchGuildRosterLive(env);
  if (live.length) {
    guildRosterMemo = { at: now, members: live };
    await r2PutJSON(env, GUILD_ROSTER_KEY, { version: 1, at: now, members: live }).catch(() => false);
    return live;
  }
  if (cached) {
    guildRosterMemo = { at: now, members: cached.members };
    return cached.members;
  }
  return [];
}

async function fetchGuildRoster(env) {
  return (await readGuildRoster(env)).map(member => member.id);
}

// Every server member really follows the official profile: the follow documents are
// written, so the counter and the notification fan-out use genuine data.
async function syncZyrexFollowers(env) {
  const official = await resolveZyrexProfile(env).catch(() => null);
  if (!official) return { ok: false, reason: "zyrex_identity_unavailable" };
  await ensureZyrexHandle(env, official.id);
  const roster = await fetchGuildRoster(env);
  if (!roster.length) return { ok: false, reason: "empty_roster" };
  const memberIds = roster.filter(id => id !== official.id);
  const current = await readFollows(env, official.id, { limit: ZYREX_FOLLOWER_LIMIT });
  const known = new Set(current.followers);
  const missing = memberIds.filter(id => !known.has(id));
  if (missing.length) {
    await r2PutJSON(env, profileFollowsKey(official.id), {
      version: 1,
      following: current.following,
      followers: [...current.followers, ...missing],
      updated_at: new Date().toISOString(),
    });
  }
  const pending = memberIds.filter(id => {
    return true;
  });
  let followingWrites = 0;
  for (let index = 0; index < pending.length; index += 20) {
    const chunk = pending.slice(index, index + 20);
    await Promise.all(chunk.map(async id => {
      const mine = await readFollows(env, id);
      if (mine.following.includes(official.id)) return;
      mine.following.push(official.id);
      const saved = await r2PutJSON(env, profileFollowsKey(id), { ...mine, updated_at: new Date().toISOString() }).catch(() => false);
      if (saved) followingWrites += 1;
    }));
  }
  return {
    ok: true,
    official_id: official.id,
    members: memberIds.length,
    new_followers: missing.length,
    following_writes: followingWrites,
  };
}

// The follower list heals itself: any official-profile view or feed load may trigger one
// throttled sync, so new members end up following Zyrex without a manual run.
const ZYREX_SYNC_MARKER = "database/zyrex_sync.json";
const ZYREX_SYNC_MIN_MS = 10 * 60 * 1000;

async function maybeSyncZyrexFollowers(env) {
  try {
    const marker = await r2GetJSON(env, ZYREX_SYNC_MARKER, null);
    if (marker && Date.now() - Number(marker.at || 0) < ZYREX_SYNC_MIN_MS) return;
    await r2PutJSON(env, ZYREX_SYNC_MARKER, { at: Date.now() }).catch(() => false);
    await syncZyrexFollowers(env);
  } catch (_) {}
}

// Social links are resolved through Scrapin so the profile can show the platform and
// the handle that actually exists behind the URL the member pasted.
const SCRAPIN_API_URL = "https://scrapin.dev";
const SOCIAL_LINK_CACHE_PREFIX = "database/social_links/";
const SOCIAL_LINK_TTL_MS = 7 * 24 * 60 * 60 * 1000;
// A creator scan feeds the upload wizard's product list. Remembering a good answer keeps
// repeated clicks stable when an upstream profile/store scraper flaps.
const CREATOR_SCAN_TTL_MS = 10 * 60 * 1000;
// TikTok (and friends) hand out signed photo URLs that block server-side downloads, so
// those rows are re-resolved often enough that the link never expires in a browser.
const SOCIAL_AVATAR_TTL_MS = 6 * 60 * 60 * 1000;

function isSignedAvatarHost(value) {
  try {
    const host = new URL(String(value || "")).hostname;
    return /tiktokcdn/i.test(host) || /cdninstagram|fbcdn/i.test(host);
  } catch (_) {
    return false;
  }
}

const SOCIAL_LINK_PLATFORMS = [
  {
    key: "tiktok", label: "TikTok", icon: "fa-tiktok", hosts: ["tiktok.com"],
    // The profile endpoint includes 30 videos by default. Creator lookup only needs
    // identity and bio data, so request zero videos to avoid unnecessary latency.
    request: handle => ({ path: "/tiktok/profile", params: { username: handle, limit: "0" } }),
    build: handle => `https://www.tiktok.com/@${handle}`,
  },
  {
    key: "instagram", label: "Instagram", icon: "fa-instagram", hosts: ["instagram.com"],
    // Instagram also defaults to returning recent posts; the creator scanner only
    // needs the profile and its bio links.
    request: handle => ({ path: "/instagram/profile", params: { username: handle, include_posts: "false", posts_count: "1" } }),
    build: handle => `https://www.instagram.com/${handle}`,
  },
  {
    key: "youtube", label: "YouTube", icon: "fa-youtube", hosts: ["youtube.com", "youtu.be"],
    request: (handle, link) => ({ path: "/youtube/channel", params: { url: link, fast: "true", max_videos: "0" } }),
    build: handle => `https://www.youtube.com/@${handle}`,
  },
  {
    key: "twitter", label: "X", icon: "fa-x-twitter", hosts: ["twitter.com", "x.com"],
    request: handle => ({ path: "/twitter/profile", params: { username: handle } }),
    build: handle => `https://x.com/${handle}`,
  },
  {
    key: "linkedin", label: "LinkedIn", icon: "fa-linkedin", hosts: ["linkedin.com"],
    request: (handle, link) => ({ path: "/linkedin/profile", params: { url: link } }),
    build: handle => `https://www.linkedin.com/in/${handle}`,
  },
  {
    key: "steam", label: "Steam", icon: "fa-steam", hosts: ["steamcommunity.com"],
    request: handle => ({ path: "/steam/profile", params: { profile: handle } }),
    // A SteamID64 opens the numeric profile; anything else is a vanity slug.
    build: handle => /^\d{17}$/.test(handle)
      ? `https://steamcommunity.com/profiles/${handle}`
      : `https://steamcommunity.com/id/${handle}`,
  },
];

// Game accounts live in the same link list as socials, but they carry a rank instead of
// a page URL: Valorant and League only exist inside Riot's client.
const GAME_PLATFORMS = [
  {
    key: "valorant", label: "Valorant", icon: "/assets/games/valorant.svg", region: "eu",
    request: riotId => ({ path: "/valorant/account", params: { name: riotId.name, tag: riotId.tag } }),
    rank: riotId => ({ path: "/valorant/mmr", params: { name: riotId.name, tag: riotId.tag, region: "eu" } }),
    placeholder: "name#tag",
  },
  {
    key: "league", label: "League of Legends", icon: "/assets/games/league-of-legends.svg", region: "euw1",
    request: riotId => ({ path: "/lol/summoner", params: { name: riotId.tag ? `${riotId.name}#${riotId.tag}` : riotId.name, region: "euw1" } }),
    rank: riotId => ({ path: "/lol/rank", params: { name: riotId.tag ? `${riotId.name}#${riotId.tag}` : riotId.name, region: "euw1" } }),
    placeholder: "name#tag",
  },
  {
    key: "roblox", label: "Roblox", icon: "/assets/games/roblox.svg",
    request: username => ({ path: "/roblox/user", params: { username } }),
    placeholder: "username",
  },
];

function gamePlatform(key) {
  const wanted = String(key || "").trim().toLowerCase();
  return GAME_PLATFORMS.find(entry => entry.key === wanted) || null;
}

function isGamePlatformKey(key) {
  return Boolean(gamePlatform(key));
}

// Riot IDs are "name#tag"; Roblox and the socials keep the plain handle rules.
function sanitizeGameHandle(value, platformKey) {
  const raw = String(value || "").trim().slice(0, 60);
  if (platformKey === "roblox") {
    const name = raw.replace(/^@+/, "");
    return /^[A-Za-z0-9_]{3,20}$/.test(name) ? name : "";
  }
  const clean = raw.replace(/^@+/, "").replace(/\s+/g, "");
  if (platformKey === "valorant" || platformKey === "league") {
    return /^[A-Za-z0-9._-]{1,24}#[A-Za-z0-9]{2,8}$/.test(clean) ? clean : "";
  }
  return /^[A-Za-z0-9._-]{2,40}$/.test(clean) ? clean : "";
}

function splitRiotId(value) {
  const clean = String(value || "").trim().replace(/^@+/, "");
  const [name, tag] = clean.split("#");
  return { name: String(name || "").slice(0, 24), tag: String(tag || "").slice(0, 8) };
}

// Paths that name a page on the platform instead of an account. Trusting these as
// handles would scrape whatever sits behind /p or /watch.
const SOCIAL_LINK_CONTENT_PATHS = new Set([
  "p", "reel", "reels", "stories", "explore", "tv", "video", "videos", "tag", "music",
  "discover", "watch", "shorts", "playlist", "playlists", "results", "feed", "posts",
  "pulse", "jobs", "school", "company", "showcase", "intent", "hashtag", "search",
  "home", "i", "app", "sharedfiles", "market", "workshop", "stats", "login", "signup",
  "about", "help", "settings", "policy", "legal",
]);

// Platforms that put the account behind a fixed prefix rather than the first segment.
const SOCIAL_LINK_PROFILE_PREFIXES = { linkedin: "in", youtube: ["channel", "c", "user"], steam: ["id", "profiles"] };

function socialLinkPlatform(value) {
  let parsed;
  try { parsed = new URL(String(value || "")); } catch (_) { return null; }
  if (parsed.protocol !== "https:" && parsed.protocol !== "http:") return null;
  const host = parsed.hostname.replace(/^www\./i, "").toLowerCase();
  const platform = SOCIAL_LINK_PLATFORMS.find(item => item.hosts.includes(host));
  if (!platform) return null;
  const segments = parsed.pathname.split("/").filter(Boolean).map(segment => decodeURIComponent(segment));
  const atSegment = segments.find(segment => segment.startsWith("@"));
  // /in/<slug> (LinkedIn), /channel/<id> (YouTube) and /id/<vanity> (Steam) name the account.
  const prefix = SOCIAL_LINK_PROFILE_PREFIXES[platform.key];
  const prefixed = prefix && [].concat(prefix).includes(String(segments[0] || "").toLowerCase()) ? segments[1] : "";
  const raw = String(prefixed || atSegment || segments[0] || "").replace(/^@/, "").toLowerCase();
  const content = !prefixed && !atSegment && SOCIAL_LINK_CONTENT_PATHS.has(raw);
  return { platform, handle: !content && /^[a-z0-9._-]{2,60}$/.test(raw) ? raw : "" };
}

function findScrapinValue(node, keys, depth = 0) {
  if (!node || typeof node !== "object" || depth > 5) return "";
  for (const key of keys) {
    const value = node[key];
    if (typeof value === "string" && value.trim()) return value.trim().slice(0, 160);
    if (typeof value === "number" && Number.isFinite(value)) return String(value);
  }
  for (const value of Object.values(node)) {
    if (value && typeof value === "object") {
      const found = findScrapinValue(value, keys, depth + 1);
      if (found) return found;
    }
  }
  return "";
}

// Scrapin returns each platform's native profile shape. Pick out the shared fields
// the creator wizard needs without assuming one common response envelope.
function extractScrapinProfile(payload) {
  const name = findScrapinValue(payload, ["personaName", "persona_name", "personaname", "fullName", "full_name", "displayName", "display_name", "nickname", "title", "name", "nickName"]);
  const username = findScrapinValue(payload, ["username", "handle", "userName", "uniqueId", "unique_id", "unique_id"]);
  const avatar = findScrapinAvatar(payload) || findScrapinValue(payload, [
    "avatar_full", "avatarfull", "avatarFull", "avatarmedium", "avatar_medium", "avatarMedium",
    "avatar_icon", "avatarLarger", "avatar_larger", "avatarLarge", "avatar_url", "avatarUrl",
    "profilePicUrl", "profile_pic_url", "profilePicUrlHd", "profilePic",
    "profilePictureUrl", "profilePicture", "avatarThumb", "avatar_thumb", "avatar_url_list",
    "avatarUrls", "avatar_urls", "profileImage", "profile_image", "picture", "img",
  ]);
  const followers = findScrapinValue(payload, ["followersCount", "followers_count", "followers", "subscriberCount", "followerCount"]);
  const accountId = findScrapinValue(payload, ["account_id", "user_id", "userid", "userId", "channel_id", "channelId", "secUid", "open_id", "id"]);
  return {
    ...(name ? { name } : {}),
    ...(username ? { handle: username.replace(/^@/, "").toLowerCase().slice(0, 60) } : {}),
    ...(/^https:\/\//i.test(avatar) ? { avatar } : {}),
    ...(followers ? { followers: String(followers).slice(0, 20) } : {}),
    ...(accountId ? { account_id: accountId } : {}),
    verified: Boolean(name || username),
  };
}

function findScrapinAvatarUrl(value, depth = 0) {
  if (!value || depth > 8) return "";
  if (typeof value === "string") return /^https:\/\//i.test(value) ? value.trim() : "";
  if (Array.isArray(value)) {
    for (const item of value) {
      const found = findScrapinAvatarUrl(item, depth + 1);
      if (found) return found;
    }
    return "";
  }
  if (typeof value !== "object") return "";
  const preferred = ["url_list", "urlList", "url", "uri", "src", "original", "large", "medium", "thumb"];
  for (const key of preferred) {
    if (Object.prototype.hasOwnProperty.call(value, key)) {
      const found = findScrapinAvatarUrl(value[key], depth + 1);
      if (found) return found;
    }
  }
  for (const child of Object.values(value)) {
    const found = findScrapinAvatarUrl(child, depth + 1);
    if (found) return found;
  }
  return "";
}

function findScrapinAvatar(value, depth = 0) {
  if (!value || depth > 8) return "";
  if (Array.isArray(value)) {
    for (const item of value) {
      const found = findScrapinAvatar(item, depth + 1);
      if (found) return found;
    }
    return "";
  }
  if (typeof value !== "object") return "";
  for (const [key, child] of Object.entries(value)) {
    if (/avatar|profile.?pic|profile.?photo|profile.?image|picture/i.test(key)) {
      const found = findScrapinAvatarUrl(child, depth + 1);
      if (found) return found;
    }
  }
  for (const child of Object.values(value)) {
    if (child && typeof child === "object") {
      const found = findScrapinAvatar(child, depth + 1);
      if (found) return found;
    }
  }
  return "";
}

async function resolveSocialLink(env, link, { force = false } = {}) {
  const url = String((link && link.url) || "").trim();
  const base = { label: String((link && link.label) || "Link").slice(0, 24), url, platform: "", icon: "", handle: "", verified: false };
  const storedKey = String((link && link.platform) || "").toLowerCase();
  // Game accounts carry a rank snapshot and no page URL, so they never hit the resolver.
  const game = gamePlatform(storedKey);
  if (game) {
    const handle = sanitizeGameHandle(link && link.handle, game.key);
    if (!handle) return base;
    const refreshed = force ? await resolveGameProfile(env, game.key, handle, { force: true }) : null;
    return {
      label: String((link && link.label) || game.label).slice(0, 24),
      url,
      platform: game.key,
      icon: game.icon,
      handle,
      name: String((refreshed && refreshed.name) || (link && link.name) || "").slice(0, 60),
      detail: String((refreshed && refreshed.detail) || (link && link.detail) || "").slice(0, 40),
      avatar: sanitizeSocialAvatar((refreshed && refreshed.avatar) || (link && link.avatar)),
      verified: true,
    };
  }
  const storedPlatform = SOCIAL_LINK_PLATFORMS.find(entry => entry.key === storedKey);
  const storedHandle = normalizeHandle(link && link.handle);
  const detected = storedPlatform && /^[a-z0-9._-]{2,60}$/.test(storedHandle)
    ? { platform: storedPlatform, handle: storedHandle }
    : socialLinkPlatform(url);
  if (!detected) return base;
  let storedAvatar = sanitizeSocialAvatar(link && link.avatar);
  if (!/^https:\/\/thumbnail\.zyrexediting\.xyz\//i.test(storedAvatar)) {
    // Older rows point at expiring signed URLs. The handle alone is enough to rebuild the
    // photo on our CDN, and a row that cannot be rebuilt simply renders without one.
    storedAvatar = (await mirrorSocialAvatar(env, storedAvatar, detected.platform.key, detected.handle || (link && link.handle), { force })) || "";
  }
  const storedName = String((link && link.name) || "").trim().slice(0, 60);
  const shape = {
    ...base,
    ...(storedName ? { name: storedName } : {}),
    ...(storedAvatar ? { avatar: storedAvatar } : {}),
    label: detected.platform.label,
    platform: detected.platform.key,
    icon: detected.platform.icon,
    handle: detected.handle,
  };
  const apiKey = String(env?.SCRAPIN_API_KEY || "");
  const cacheKey = `${SOCIAL_LINK_CACHE_PREFIX}${detected.platform.key}-${detected.handle}.json`;
  let cached = null;
  try { cached = await r2GetJSON(env, cacheKey, null); } catch (_) { cached = null; }
  const cacheAge = cached ? Date.now() - Number(cached.fetched_at || 0) : Infinity;
  const cachedAvatarExpiring = Boolean(cached && cached.profile && isSignedAvatarHost(cached.profile.avatar) && cacheAge > SOCIAL_AVATAR_TTL_MS);
  if (!force && cached && cached.profile && cacheAge < SOCIAL_LINK_TTL_MS && !cachedAvatarExpiring) {
    if (cached.profile.avatar && !/^https:\/\/thumbnail\.zyrexediting\.xyz\//i.test(cached.profile.avatar)) {
      const mirrored = await mirrorSocialAvatar(env, cached.profile.avatar, detected.platform.key, detected.handle);
      cached.profile.avatar = mirrored || "";
      if (mirrored) await r2PutJSON(env, cacheKey, { ...cached, profile: cached.profile }).catch(() => false);
    }
    return { ...shape, ...cached.profile };
  }
  try {
    const profile = {};
    if (apiKey && detected.handle) {
      const request = detected.platform.request(detected.handle, url);
      const payload = await scrapinRequest(env, request.path, request.params);
      if (payload) Object.assign(profile, extractScrapinProfile(payload));
    }
    if (!profile.name && !profile.avatar) {
      // Nothing came back from the paid scraper (outage, quota or an expired plan), so the
      // platform's own public endpoint answers instead.
      Object.assign(profile, await publicSocialProfile(detected.platform.key, detected.handle, url));
    }
    // A photo is only kept when it could be copied to our own CDN; when the source has no
    // photo at all the handle alone is enough for the avatar resolver.
    const mirrored = (await mirrorSocialAvatar(env, profile.avatar, detected.platform.key, detected.handle, { force })) || "";
    if (mirrored) profile.avatar = mirrored;
    else delete profile.avatar;
    const stored = await r2PutJSON(env, cacheKey, {
      version: 1,
      url,
      platform: detected.platform.key,
      handle: detected.handle,
      profile,
      fetched_at: Date.now(),
    }).catch(() => false);
    if (!stored) console.warn("scrapin_cache_write_failed", detected.platform.key);
    return { ...shape, ...profile };
  } catch (error) {
    console.warn("scrapin_lookup_error", detected.platform.key, error?.message || String(error));
    return cached && cached.profile ? { ...shape, ...cached.profile } : shape;
  }
}

// Signed social CDN links expire, so the photo is copied into our own bucket and served
// from the thumbnail host instead.
const SOCIAL_AVATAR_MIRROR_PREFIX = "database/social_avatars/";
// Platforms whose photos the source refuses to hand to anyone but a browser. The bytes
// are fetched once through a resolver and then served from our own CDN forever.
const SOCIAL_AVATAR_RESOLVERS = {
  tiktok: "tiktok",
  instagram: "instagram",
  youtube: "youtube",
  twitter: "twitter",
  linkedin: "linkedin",
};

function socialAvatarHandle(handle) {
  return String(handle || "account").toLowerCase().replace(/[^a-z0-9._-]/g, "").slice(0, 32) || "account";
}

function socialAvatarCacheKey(platform, handle) {
  const p = String(platform || "link").toLowerCase().replace(/[^a-z]/g, "") || "link";
  return `${SOCIAL_AVATAR_MIRROR_PREFIX}${p}-${socialAvatarHandle(handle)}.json`;
}

// Sırayla denenir: kaynak URL, kaynağın kendi proxy'si, sonra hesabı çözebilen servis.
function socialAvatarCandidates(raw, platform, handle) {
  const list = [];
  const frame = url => `https://wsrv.nl/?url=${encodeURIComponent(url.replace(/^https?:\/\//, ""))}&w=256&h=256&fit=cover&output=jpg`;
  if (raw) {
    list.push(raw);
    list.push(frame(raw));
  }
  const resolver = SOCIAL_AVATAR_RESOLVERS[String(platform || "").toLowerCase()];
  const clean = String(handle || "").replace(/[^a-z0-9._-]/gi, "");
  if (resolver && clean) {
    list.push(`https://unavatar.io/${resolver}/${clean}`);
    list.push(frame(`unavatar.io/${resolver}/${clean}`));
  }
  return list;
}

async function downloadSocialAvatar(url) {
  try {
    const response = await fetch(url, {
      headers: {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
        Accept: "image/avif,image/webp,image/*,*/*;q=0.8",
        Referer: "https://www.tiktok.com/",
      },
      redirect: "follow",
      signal: AbortSignal.timeout(9000),
    });
    if (!response.ok) {
      console.warn("social_avatar_fetch_failed", response.status, url.slice(0, 120));
      return null;
    }
    const bytes = new Uint8Array(await response.arrayBuffer());
    if (!bytes.length || bytes.length > IMAGE_UPLOAD_MAX_BYTES) {
      console.warn("social_avatar_size_rejected", bytes.length, url.slice(0, 120));
      return null;
    }
    const extension = detectImageExtension(bytes);
    if (!extension) {
      console.warn("social_avatar_type_rejected", String(response.headers.get("content-type") || ""), url.slice(0, 120));
      return null;
    }
    return { bytes, extension };
  } catch (error) {
    console.warn("social_avatar_fetch_error", error?.message || String(error), url.slice(0, 120));
    return null;
  }
}

async function mirrorSocialAvatar(env, value, platform, handle, { force = false } = {}) {
  const raw = sanitizeSocialAvatar(value);
  if (!env?.STORAGE) return "";
  if (raw && /^https:\/\/thumbnail\.zyrexediting\.xyz\//i.test(raw)) return raw;
  const candidates = socialAvatarCandidates(raw, platform, handle);
  if (!candidates.length) return "";
  // A failed lookup is remembered briefly so a broken source does not slow every visit.
  const cacheKey = socialAvatarCacheKey(platform, handle);
  const cached = await r2GetJSON(env, cacheKey, null).catch(() => null);
  const cachedUrl = String((cached && cached.url) || "");
  const cachedAt = cached && cached.at ? new Date(cached.at).getTime() : 0;
  if (!force && cachedAt) {
    const ttl = cachedUrl ? SOCIAL_AVATAR_TTL_MS : 30 * 60 * 1000;
    if (Date.now() - cachedAt < ttl) return cachedUrl;
  }
  try {
    // Every candidate is tried at once so a blocked source cannot stack up timeouts.
    const results = await Promise.all(candidates.map(candidate => downloadSocialAvatar(candidate).catch(() => null)));
    const image = results.find(Boolean);
    if (image) {
      const name = `social-${String(platform || "link").toLowerCase().replace(/[^a-z]/g, "") || "link"}-${socialAvatarHandle(handle)}-${crypto.randomUUID().replace(/-/g, "").slice(0, 12)}.${image.extension}`;
      const stored = await env.STORAGE.put(`thumbnails/${name}`, image.bytes, {
        httpMetadata: { contentType: image.extension === "jpg" ? "image/jpeg" : `image/${image.extension}` },
      }).catch(() => false);
      if (stored) {
        const url = `https://thumbnail.zyrexediting.xyz/${name}`;
        await r2PutJSON(env, cacheKey, { url, at: new Date().toISOString() }).catch(() => false);
        return url;
      }
    }
  } catch (_) {
    return "";
  }
  await r2PutJSON(env, cacheKey, { url: "", at: new Date().toISOString() }).catch(() => false);
  return "";
}

// Creator studio needs more than a label: the bio text and the links inside it decide
// which store belongs to the creator, so Scrapin answers those directly.
function scrapinLinksFromText(text) {
  const found = [];
  const pattern = /https?:\/\/[^\s"'<>()]+/gi;
  let match;
  while ((match = pattern.exec(String(text || ""))) !== null) {
    const link = match[0].replace(/[.,)]+$/, "");
    if (!found.includes(link)) found.push(link);
    if (found.length >= 12) break;
  }
  return found;
}

function scrapinLinksFromPayload(payload) {
  const found = [];
  const linkKey = /^(?:bio.?links?|external.?url|external.?link|website|website.?url|links?|out.?links?)$/i;
  const visit = (value, depth = 0, isLinkValue = false) => {
    if (depth > 8 || value == null) return;
    if (typeof value === "string") {
      if (!isLinkValue) return;
      for (const link of scrapinLinksFromText(value)) if (!found.includes(link)) found.push(link);
      return;
    }
    if (Array.isArray(value)) {
      for (const item of value) visit(item, depth + 1, isLinkValue);
      return;
    }
    if (typeof value === "object") {
      for (const [key, child] of Object.entries(value)) visit(child, depth + 1, isLinkValue || linkKey.test(key));
    }
  };
  visit(payload);
  return found.slice(0, 12);
}

async function scrapinSocialProfile(env, value, { throwOnError = false } = {}) {
  const detected = socialLinkPlatform(value);
  if (!detected) return null;
  const apiKey = String(env?.SCRAPIN_API_KEY || "");
  const cacheKey = `${SOCIAL_LINK_CACHE_PREFIX}${detected.platform.key}-${detected.handle}.json`;
  let cached = null;
  try { cached = await r2GetJSON(env, cacheKey, null); } catch (_) { cached = null; }
  const fresh = cached && Date.now() - Number(cached.fetched_at || 0) < SOCIAL_LINK_TTL_MS;
  if (cached && fresh && cached.creator) return cached.creator;
  if (!apiKey || !detected.handle) {
    if (throwOnError && !apiKey) throw Object.assign(new Error("Scrapin API key is not configured"), { scrapinStatus: 503 });
    return cached && cached.creator ? cached.creator : null;
  }
  try {
    // Keep the pasted URL intact. YouTube channel IDs and LinkedIn profile URLs
    // cannot safely be reconstructed as @handles.
    const request_ = detected.platform.request(detected.handle, String(value || detected.platform.build(detected.handle)));
    const target = new URL(request_.path, SCRAPIN_API_URL);
    for (const [key, value_] of Object.entries(request_.params)) target.searchParams.set(key, value_);
    const response = await fetch(target.toString(), {
      headers: { "X-API-Key": apiKey, Accept: "application/json" },
      // Social profile endpoints are documented at https://scrapin.dev/openapi.json.
      // Some scrape paths take longer than five seconds, so let the upstream finish.
      signal: AbortSignal.timeout(25000),
    });
    const payload = await response.json().catch(() => null);
    if (!response.ok) {
      if (cached && cached.creator) return cached.creator;
      const upstreamMessage = findScrapinValue(payload, ["error", "detail", "message"]);
      const error = new Error(upstreamMessage || `Scrapin returned HTTP ${response.status}`);
      error.scrapinStatus = response.status;
      if (throwOnError) throw error;
      console.warn("scrapin_profile_failed", detected.platform.key, response.status);
      return null;
    }
    const profile = extractScrapinProfile(payload);
    const bio = findScrapinValue(payload, ["biography", "bio", "description", "signature", "about"]);
    const links = [...new Set([...scrapinLinksFromPayload(payload), ...scrapinLinksFromText(bio)])].slice(0, 12);
    const creator = {
      platform: detected.platform.key,
      handle: profile.handle || detected.handle,
      account_id: profile.account_id || profile.id || findScrapinValue(payload, ["account_id", "user_id", "userid", "channel_id", "channelid"]),
      name: profile.name || "",
      avatar: profile.avatar ? (await mirrorSocialAvatar(env, profile.avatar, detected.platform.key, profile.handle || detected.handle)) || "" : "",
      bio: bio || "",
      links,
    };
    await r2PutJSON(env, cacheKey, {
      version: 1,
      url: String(value || ""),
      platform: detected.platform.key,
      handle: detected.handle,
      profile,
      creator,
      fetched_at: Date.now(),
    }).catch(() => false);
    return creator;
  } catch (error) {
    if (throwOnError) throw error;
    console.warn("scrapin_profile_error", detected.platform.key, error?.name === "TimeoutError" ? "timeout" : (error?.message || String(error)));
    return cached && cached.creator ? cached.creator : null;
  }
}

// Game accounts are looked up once and cached, because the rank behind them changes
// slowly and a profile view should never wait on Riot or Roblox.
const GAME_PROFILE_CACHE_PREFIX = "database/game_profiles/";
const GAME_PROFILE_TTL_MS = 7 * 24 * 60 * 60 * 1000;

function gameProfileCacheKey(platformKey, handle) {
  const slug = String(handle || "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 48) || "account";
  return `${GAME_PROFILE_CACHE_PREFIX}${String(platformKey || "game").toLowerCase()}-${slug}.json`;
}

async function scrapinRequest(env, path, params) {
  const apiKey = String(env?.SCRAPIN_API_KEY || "");
  if (!apiKey) return null;
  const target = new URL(path, SCRAPIN_API_URL);
  for (const [key, value] of Object.entries(params || {})) {
    if (value === undefined || value === null || value === "") continue;
    target.searchParams.set(key, String(value));
  }
  try {
    const response = await fetch(target.toString(), {
      headers: { "X-API-Key": apiKey, Accept: "application/json" },
      signal: AbortSignal.timeout(5000),
    });
    if (!response.ok) {
      const detail = await response.text().catch(() => "");
      console.warn("scrapin_request_failed", path, response.status, target.toString(), String(detail).replace(/\s+/g, " ").slice(0, 200));
      return null;
    }
    return await response.json().catch(() => null);
  } catch (error) {
    console.warn("scrapin_request_error", path, error?.message || String(error));
    return null;
  }
}

// Valorant reports the current tier as a name, League as tier + division + LP.
function gameRankLabel(platformKey, payload) {
  if (!payload) return "";
  if (platformKey === "valorant") {
    const tier = findScrapinValue(payload, ["currenttierpatched", "currentTierPatched", "tierName", "tier_name", "currenttier", "currentTier"]);
    const rr = findScrapinValue(payload, ["ranking_in_tier", "rankingInTier", "rr", "rankedRating"]);
    if (!tier || /^\d+$/.test(tier)) return "";
    return [tier, rr ? `${rr} RR` : ""].filter(Boolean).join(" \u00b7 ").slice(0, 40);
  }
  if (platformKey === "league") {
    const tier = findScrapinValue(payload, ["tier", "rankName", "highestTier", "ratedTier"]);
    const division = findScrapinValue(payload, ["division", "rank", "ratedRating"]);
    const lp = findScrapinValue(payload, ["leaguePoints", "league_points", "lp", "points"]);
    if (!tier) return "";
    const name = [tier, division && !/^\d{3,}$/.test(division) ? division : ""].filter(Boolean).join(" ");
    return [name, lp ? `${lp} LP` : ""].filter(Boolean).join(" \u00b7 ").slice(0, 40);
  }
  return "";
}

function gameProfileShape(game, handle) {
  return { label: game.label, platform: game.key, icon: game.icon, handle, detail: "", url: "", avatar: "" };
}

// Unranked accounts still carry a level, which reads better than an empty detail.
function gameLevelLabel(payload) {
  const level = findScrapinValue(payload, ["summonerLevel", "summoner_level", "account_level", "accountLevel", "level"]);
  return /^\d{1,4}$/.test(level) ? `Lv ${level}` : "";
}

async function resolveGameProfile(env, platformKey, input, { force = false } = {}) {
  const game = gamePlatform(platformKey);
  if (!game) return null;
  const handle = sanitizeGameHandle(input, game.key);
  if (!handle) return null;
  const cacheKey = gameProfileCacheKey(game.key, handle);
  const cached = await r2GetJSON(env, cacheKey, null).catch(() => null);
  const fresh = cached && Date.now() - Number(cached.fetched_at || 0) < GAME_PROFILE_TTL_MS;
  if (!force && cached && fresh && cached.profile) return { ...gameProfileShape(game, handle), ...cached.profile };
  if (!String(env?.SCRAPIN_API_KEY || "")) return cached && cached.profile ? { ...gameProfileShape(game, handle), ...cached.profile } : gameProfileShape(game, handle);

  const profile = gameProfileShape(game, handle);
  try {
    if (game.key === "valorant" || game.key === "league") {
      const riotId = splitRiotId(handle);
      const accountCall = game.request(riotId);
      const account = await scrapinRequest(env, accountCall.path, accountCall.params);
      if (!account) return cached && cached.profile ? { ...profile, ...cached.profile } : profile;
      const ranked = game.rank ? await scrapinRequest(env, game.rank(riotId).path, game.rank(riotId).params) : null;
      profile.detail = gameRankLabel(game.key, ranked) || gameRankLabel(game.key, account) || gameLevelLabel(account);
      const accountName = findScrapinValue(account, ["gameName", "displayName", "summonerName", "persona_name", "name", "riotId"]);
      if (accountName && accountName !== handle) profile.name = accountName.slice(0, 60);
    } else if (game.key === "roblox") {
      const user = await scrapinRequest(env, "/roblox/user", { username: handle });
      if (!user) return cached && cached.profile ? { ...profile, ...cached.profile } : profile;
      const userId = findScrapinValue(user, ["id", "userId", "user_id"]);
      const display = findScrapinValue(user, ["displayName", "display_name", "name"]);
      const profileUrl = findScrapinValue(user, ["profileUrl", "profile_url"]);
      if (/^https:\/\/www\.roblox\.com\/users\/\d{1,20}\/profile$/i.test(profileUrl)) profile.url = profileUrl;
      else if (/^\d{1,20}$/.test(userId)) profile.url = `https://www.roblox.com/users/${userId}/profile`;
      if (display && display.toLowerCase() !== handle.toLowerCase()) profile.detail = display.slice(0, 40);
      const avatar = extractScrapinProfile(user).avatar || "";
      if (avatar) profile.avatar = (await mirrorSocialAvatar(env, avatar, "roblox", handle)) || "";
    }
    await r2PutJSON(env, cacheKey, { version: 1, platform: game.key, handle, profile, fetched_at: Date.now() }).catch(() => false);
    return profile;
  } catch (_) {
    return cached && cached.profile ? { ...profile, ...cached.profile } : profile;
  }
}

// Profile pages always render the platform name, even before Scrapin answers.
async function resolveProfileSocialLinks(env, links, ownerId = "", { force = false } = {}) {
  const rows = Array.isArray(links) ? links.slice(0, PROFILE_LINK_LIMIT) : [];
  if (!rows.length) return [];
  const resolved = await Promise.all(rows.map(link => resolveSocialLink(env, link, { force }).catch(() => ({
    label: String((link && link.label) || "Link").slice(0, 24),
    url: String((link && link.url) || ""),
    platform: "",
    icon: "",
    handle: "",
    verified: false,
  }))));
  // A mirrored photo is written back so the next visit skips the download entirely.
  const owner = String(ownerId || "").trim();
  if (/^\d{15,25}$/.test(owner)) {
    const changed = resolved.some((row, index) => {
      const before = String((rows[index] && rows[index].avatar) || "");
      return row.avatar && row.avatar !== before;
    });
    if (changed) {
      const settings = await readProfileSettings(env, owner).catch(() => null);
      if (settings) {
        const nextLinks = resolved.map((row, index) => ({
          ...(rows[index] || {}),
          label: row.label || (rows[index] && rows[index].label) || "Link",
          url: row.url || (rows[index] && rows[index].url) || "",
          ...(row.platform ? { platform: row.platform } : {}),
          ...(row.handle ? { handle: row.handle } : {}),
          ...(row.name ? { name: row.name } : {}),
          ...(row.avatar ? { avatar: row.avatar } : {}),
        }));
        await r2PutJSON(env, profileSettingsKey(owner), { ...settings, links: nextLinks, updated_at: new Date().toISOString() }).catch(() => false);
      }
    }
  }
  return resolved;
}

// A refresh request may carry a URL the member typed but never saved, so the row is
// rebuilt from the request before anything is scraped.
function profileRefreshTarget(links, body) {
  const rows = Array.isArray(links) ? links : [];
  const platform = String((body && body.platform) || "").trim().toLowerCase();
  // Riot IDs are case sensitive, so only the comparison key is lowercased.
  const rawHandle = String((body && body.handle) || "").trim();
  const handle = rawHandle.toLowerCase();
  const linkUrl = normalizeProfileLinkUrl(body && body.url);
  // A matching identity or URL wins, but the editor also sends its row position so a
  // freshly typed URL can be refreshed instead of the stored one.
  let index = rows.findIndex(link => {
    if (!link || typeof link !== "object") return false;
    const sameIdentity = platform && handle
      && String(link.platform || "").toLowerCase() === platform
      && String(link.handle || "").toLowerCase() === handle;
    return sameIdentity || (linkUrl && normalizeProfileLinkUrl(link.url) === linkUrl);
  });
  if (index < 0) {
    const requested = Number(body && body.index);
    if (Number.isInteger(requested) && requested >= 0 && rows[requested]) index = requested;
  }
  if (index < 0) return null;
  const stored = rows[index];
  // The typed URL is the account the member wants data for, so it replaces the saved one.
  const target = { ...stored, url: linkUrl || String(stored.url || "") };
  const detected = socialLinkPlatform(target.url);
  if (detected) {
    target.platform = detected.platform.key;
    target.icon = detected.platform.icon;
    if (detected.handle) target.handle = detected.handle;
  } else if (platform && rawHandle) {
    target.platform = platform;
    target.handle = rawHandle;
  }
  const sameAccount = String(stored.platform || "").toLowerCase() === String(target.platform || "").toLowerCase()
    && String(stored.handle || "").toLowerCase() === String(target.handle || "").toLowerCase();
  return { index, stored, target, sameAccount };
}

// The name, rank and photo of the previous account are dropped as soon as the row
// points somewhere else.
function mergeRefreshedProfileLink(stored, target, resolved, sameAccount) {
  const fresh = resolved && typeof resolved === "object" ? resolved : {};
  const previous = stored && typeof stored === "object" ? stored : {};
  const fallback = key => (sameAccount ? previous[key] : "") || "";
  const name = fresh.name || fallback("name");
  const detail = fresh.detail || fallback("detail");
  const avatar = fresh.avatar || fallback("avatar");
  // A label the member typed by hand is kept; an auto-filled platform name follows the
  // account that the row now points at.
  const previousPlatform = SOCIAL_LINK_PLATFORMS.find(entry => entry.key === String(previous.platform || "").toLowerCase())
    || gamePlatform(previous.platform);
  const previousLabel = String(previous.label || "");
  const label = !previousLabel || (previousPlatform && previousLabel === previousPlatform.label)
    ? (fresh.label || previousLabel)
    : previousLabel;
  return {
    label: String(label || "").slice(0, 24),
    url: String(fresh.url || (target && target.url) || "").slice(0, 300),
    platform: fresh.platform || String((target && target.platform) || ""),
    icon: fresh.icon || String((target && target.icon) || ""),
    handle: fresh.handle || String((target && target.handle) || ""),
    ...(name ? { name } : {}),
    ...(detail ? { detail } : {}),
    ...(avatar ? { avatar } : {}),
  };
}

// Scrapin is the preferred source, but every one of these endpoints is free and keyless,
// so a profile link keeps refreshing while the paid scraper is down or out of quota.
const PUBLIC_PROFILE_ENDPOINTS = {
  tiktok: (handle) => `https://www.tiktok.com/oembed?url=${encodeURIComponent(`https://www.tiktok.com/@${handle}`)}`,
  youtube: (handle, url) => `https://www.youtube.com/oembed?format=json&url=${encodeURIComponent(url || `https://www.youtube.com/@${handle}`)}`,
  twitter: (handle) => `https://publish.twitter.com/oembed?url=${encodeURIComponent(`https://twitter.com/${handle}`)}`,
  steam: (handle) => `https://steamcommunity.com/${/^\d{17}$/.test(handle) ? "profiles" : "id"}/${handle}/?xml=1`,
};

const PUBLIC_PROFILE_HEADERS = {
  "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
  Accept: "application/json, text/xml;q=0.9, */*;q=0.8",
};

function decodeXmlEntities(value) {
  return String(value || "")
    .replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, "\"")
    .replace(/&#39;/g, "'").replace(/&apos;/g, "'").replace(/&amp;/g, "&")
    .trim();
}

function xmlTag(text, tag) {
  const match = new RegExp(`<${tag}>(?:<!\\[CDATA\\[)?([\\s\\S]*?)(?:\\]\\]>)?</${tag}>`).exec(String(text || ""));
  return match ? decodeXmlEntities(match[1]) : "";
}

async function publicSocialProfile(platformKey, handle, url) {
  const build = PUBLIC_PROFILE_ENDPOINTS[String(platformKey || "").toLowerCase()];
  if (!build || !handle) return {};
  try {
    const response = await fetch(build(handle, url), {
      headers: PUBLIC_PROFILE_HEADERS,
      redirect: "follow",
      signal: AbortSignal.timeout(5000),
    });
    if (!response.ok) return {};
    const text = await response.text();
    if (!text) return {};
    if (/^\s*</.test(text)) {
      // Steam answers with the legacy XML profile: the persona name and the photo.
      const name = xmlTag(text, "steamID").slice(0, 60);
      const avatar = xmlTag(text, "avatarFull");
      return { ...(name ? { name } : {}), ...(avatar ? { avatar } : {}), ...(name ? { verified: true } : {}) };
    }
    const payload = JSON.parse(text);
    const name = String(payload.author_name || payload.title || "").trim().slice(0, 60);
    // YouTube oEmbed also hands back the channel photo, which is mirrored to our CDN.
    const avatar = String(payload.thumbnail_url || "").trim();
    return {
      ...(name ? { name } : {}),
      ...(avatar ? { avatar } : {}),
      ...(name ? { verified: true } : {}),
    };
  } catch (_) {
    return {};
  }
}

async function readProfileSettings(env, discordId) {
  const base = defaultProfileSettings(discordId);
  try {
    const stored = await r2GetJSON(env, profileSettingsKey(discordId), null);
    if (!stored || typeof stored !== "object") return base;
    return {
      ...base,
      ...stored,
      public: stored.public !== false,
      show_downloads: stored.show_downloads !== false,
      show_activity: stored.show_activity !== false,
      show_connections: stored.show_connections !== false,
      bio: sanitizeProfileBio(stored.bio),
      links: sanitizeProfileLinks(stored.links),
      // Profile images are always sourced from Discord; ignore legacy custom URLs.
      avatar: "",
      banner: "",
      accent: /^#[0-9a-f]{6}$/i.test(String(stored.accent || "")) ? String(stored.accent) : "",
      discord_id: base.discord_id,
    };
  } catch (_) {
    return base;
  }
}

// Post media is either an image this member uploaded to the site or one of the
// sticker/GIF assets the composer offers. Everything else is dropped.
const PROFILE_MEDIA_PATTERNS = [
  /^https:\/\/cdn\.discordapp\.com\/stickers\/\d+\.(?:png|gif|apng)$/i,
  /^https:\/\/media\.discordapp\.net\/stickers\/\d+\.(?:png|gif|apng)$/i,
  // Giphy moved to versioned paths (/media/v1.<token>/<id>/200.gif), so both the old
  // /media/<id>/<id>.gif shape and the new one have to be accepted.
  /^https:\/\/(?:media\d*|i)\.giphy\.com\/media\/(?:[\w.~-]+\/){0,2}[\w-]+\.(?:gif|webp|png|jpe?g)$/i,
  /^https:\/\/(?:media\d*\.tenor\.com|tenor\.com)\/(?:[\w.~-]+\/){0,2}[\w-]+\.(?:gif|webp|png|jpe?g)$/i,
];

function sanitizeProfileMediaUrl(value, discordId) {
  const url = String(value || "").trim();
  if (!isAllowedProfileMedia(url, discordId)) return "";
  return url;
}

function isAllowedProfileMedia(url, discordId) {
  const value = String(url || "").trim();
  if (!value || value.length > 400) return false;
  const safeId = String(discordId || "").trim();
  if (/^\d{15,25}$/.test(safeId) &&
    new RegExp("^https://thumbnail\\.zyrexediting\\.xyz/profile-" + safeId + "-[a-f0-9-]+\\.(?:png|jpe?g|webp)$", "i").test(value)) {
    return true;
  }
  if (/^\d{15,25}$/.test(safeId) &&
    new RegExp("^https://thumbnail\\.zyrexediting\\.xyz/(?:post|comment)-" + safeId + "-[a-f0-9]+\\.(?:png|jpe?g|gif|webp)$", "i").test(value)) {
    return true;
  }
  return PROFILE_MEDIA_PATTERNS.some(pattern => pattern.test(value));
}

// The handle index is needed by most profile-shaped requests and by resource lists, so
// it is held in memory briefly and dropped the moment a handle changes.
const PROFILE_HANDLE_INDEX_TTL_MS = 30 * 1000;
let profileHandleIndexCache = null;

async function readHandleIndex(env) {
  const now = Date.now();
  if (profileHandleIndexCache && now - profileHandleIndexCache.at < PROFILE_HANDLE_INDEX_TTL_MS) {
    return profileHandleIndexCache.value;
  }
  let value = { version: 1, handles: {} };
  try {
    const stored = await r2GetJSON(env, PROFILE_HANDLES_KEY, null);
    if (stored && typeof stored === "object" && stored.handles && typeof stored.handles === "object") {
      value = { version: 1, handles: stored.handles };
    }
  } catch (_) {}
  profileHandleIndexCache = { at: now, value };
  return value;
}

function invalidateHandleIndex() {
  profileHandleIndexCache = null;
}

async function resolveHandle(env, rawHandle) {
  const handle = normalizeHandle(rawHandle);
  if (!handle) return "";
  // The official profile answers on /@zyrex even before the index is first written.
  if (handle === ZYREX_HANDLE) {
    const officialId = await zyrexProfileId(env).catch(() => "");
    if (officialId) return officialId;
  }
  const index = await readHandleIndex(env);
  const entry = index.handles[handle];
  return entry && entry.id ? String(entry.id) : "";
}

async function setProfileHandle(env, discordId, rawHandle) {
  const id = String(discordId || "").trim();
  const handle = normalizeHandle(rawHandle);
  if (!/^\d{15,25}$/.test(id)) return { error: "Invalid member" };
  if (!isValidHandle(handle)) {
    return { error: "Handles use 3-24 characters: letters, numbers, dot, dash or underscore." };
  }
  const index = await readHandleIndex(env);
  const taken = index.handles[handle];
  if (taken && String(taken.id) !== id) return { error: "That handle is already taken." };

  const settings = await readProfileSettings(env, id);
  const previous = normalizeHandle(settings.handle);
  if (previous && previous !== handle && settings.handle_changed_at) {
    const age = Date.now() - (Number(settings.handle_changed_at) || 0);
    if (age >= 0 && age < PROFILE_HANDLE_COOLDOWN_MS) {
      const days = Math.ceil((PROFILE_HANDLE_COOLDOWN_MS - age) / (24 * 60 * 60 * 1000));
      return { error: `Handles can only be changed once a week. Try again in ${days} day(s).` };
    }
  }
  if (previous === handle) return { ok: true, handle };

  if (previous && index.handles[previous] && String(index.handles[previous].id) === id) {
    delete index.handles[previous];
  }
  index.handles[handle] = { id, handle, updated_at: new Date().toISOString() };
  await r2PutJSON(env, PROFILE_HANDLES_KEY, index);
  invalidateHandleIndex();
  await r2PutJSON(env, profileSettingsKey(id), {
    ...settings,
    handle,
    handle_changed_at: Date.now(),
    updated_at: new Date().toISOString(),
  });
  return { ok: true, handle };
}

// Give a member a working /@username the first time they are looked up, so profiles
// exist before anybody visits settings. Only claims a free, valid name.
async function ensureProfileHandle(env, discordId, preferred) {
  const id = String(discordId || "").trim();
  if (!/^\d{15,25}$/.test(id)) return "";
  const settings = await readProfileSettings(env, id);
  if (normalizeHandle(settings.handle)) return normalizeHandle(settings.handle);
  const base = normalizeHandle(preferred).replace(/[^a-z0-9._-]/g, "").slice(0, PROFILE_MAX_HANDLE_LENGTH - 4);
  if (!base) return "";
  const index = await readHandleIndex(env);
  const candidates = [base];
  for (let n = 2; n <= 5; n++) candidates.push(`${base.slice(0, PROFILE_MAX_HANDLE_LENGTH - 2)}-${n}`);
  for (const candidate of candidates) {
    if (!isValidHandle(candidate) || index.handles[candidate]) continue;
    index.handles[candidate] = { id, handle: candidate, updated_at: new Date().toISOString() };
    await r2PutJSON(env, PROFILE_HANDLES_KEY, index);
    invalidateHandleIndex();
    await r2PutJSON(env, profileSettingsKey(id), {
      ...settings,
      handle: candidate,
      updated_at: new Date().toISOString(),
    });
    return candidate;
  }
  return "";
}

// A Discord username is not always a legal handle (dots, length, reserved words), so the
// sync derives a candidate from it and falls back to a suffixed variant.
function handleCandidateFromUsername(username) {
  const base = normalizeHandle(username)
    .replace(/[^a-z0-9._-]/g, "-")
    .replace(/\.{2,}/g, ".")
    .replace(/^[._-]+/, "")
    .replace(/[._-]+$/, "")
    .slice(0, PROFILE_MAX_HANDLE_LENGTH);
  return base;
}

function uniqueHandleCandidate(base, discordId, taken) {
  const id = String(discordId || "");
  const seeds = [];
  if (base) seeds.push(base);
  const suffix = id.slice(-4);
  if (base && suffix && !base.endsWith(suffix)) {
    seeds.push(`${base.slice(0, PROFILE_MAX_HANDLE_LENGTH - 5)}-${suffix}`);
  }
  for (let n = 2; n <= 9; n += 1) {
    if (base) seeds.push(`${base.slice(0, PROFILE_MAX_HANDLE_LENGTH - 2)}-${n}`);
  }
  for (const candidate of seeds) {
    if (!isValidHandle(candidate)) continue;
    const owner = taken[candidate];
    if (!owner || String(owner) === id) return candidate;
  }
  return "";
}

// The guild directory is the only place with every member's @username. Discord answers
// 403 unless the bot has the GUILD_MEMBERS intent, so the VPS bot (which does) is the
// fallback and usually the winner.
async function fetchGuildMemberDirectory(env) {
  const direct = await discordApiFetch(env, `/guilds/${verifyGuildId(env)}/members?limit=1000`, {
    timeoutMs: 12000,
    attempts: 1,
  });
  if (direct.ok && Array.isArray(direct.body)) {
    const members = direct.body
      .map(entry => ({
        id: String((entry && entry.user && entry.user.id) || ""),
        username: String((entry && entry.user && entry.user.username) || ""),
      }))
      .filter(entry => /^\d{15,25}$/.test(entry.id) && entry.username);
    if (members.length) return { source: "discord", members };
  }
  try {
    const response = await fetch(`${VERIFY_BOT_API}/api/guild/members`, {
      headers: {
        "X-User-Is-Admin": "true",
        "X-User-ID": String(ADMIN_IDS[0] || ""),
        "X-User-Name": "Zyrex website",
        ...(env.BOT_SERVICE_TOKEN ? { "X-Zyrex-Service": String(env.BOT_SERVICE_TOKEN) } : {}),
      },
      signal: AbortSignal.timeout(15000),
    });
    const payload = await response.json().catch(() => null);
    const list = payload && Array.isArray(payload.members) ? payload.members : [];
    const members = list
      .map(entry => ({ id: String((entry && entry.id) || ""), username: String((entry && entry.username) || "") }))
      .filter(entry => /^\d{15,25}$/.test(entry.id) && entry.username);
    if (members.length) return { source: "vps", members };
    return { source: "none", members: [], status: response.status };
  } catch (error) {
    return { source: "none", members: [], status: 0, detail: error?.message || "network error" };
  }
}

// Rewrites every stored profile handle to the member's Discord username, in one pass:
// usernames are claimed first so an old custom handle can never block its real owner.
async function syncProfileHandles(env, options = {}) {
  const dryRun = options.dryRun === true;
  const limit = Math.min(Math.max(Number(options.limit) || 5000, 1), 5000);
  const directory = await fetchGuildMemberDirectory(env);
  const usernameById = new Map(directory.members.map(member => [member.id, member.username]));
  const officialId = await zyrexProfileId(env).catch(() => "");

  const listed = await r2List(env, PROFILE_SETTINGS_PREFIX).catch(() => []);
  const keys = (Array.isArray(listed) ? listed : [])
    .map(object => String((object && object.key) || ""))
    .filter(key => key.endsWith(".json"))
    .slice(0, limit);

  const records = [];
  for (const key of keys) {
    const id = key.slice(PROFILE_SETTINGS_PREFIX.length).replace(/\.json$/, "");
    if (!/^\d{15,25}$/.test(id)) continue;
    const stored = await r2GetJSON(env, key, null).catch(() => null);
    if (!stored || typeof stored !== "object") continue;
    records.push({ id, key, settings: stored });
  }

  const taken = {};
  const updates = [];
  const skipped = [];

  // Handles that belong to members we are not processing stay claimed, so a partially
  // processed page can never hand someone else's URL to a different member.
  const processedIds = new Set(records.map(record => record.id));
  const existingIndex = await readHandleIndex(env).catch(() => ({ handles: {} }));
  for (const [handle, entry] of Object.entries((existingIndex && existingIndex.handles) || {})) {
    const owner = String((entry && entry.id) || "");
    if (!owner || processedIds.has(owner)) continue;
    taken[handle] = owner;
  }

  // Pass 1: everybody the guild knows gets first claim on their own username.
  for (const record of records) {
    if (officialId && record.id === officialId) {
      taken[ZYREX_HANDLE] = record.id;
      continue;
    }
    const username = usernameById.get(record.id) || "";
    const candidate = uniqueHandleCandidate(handleCandidateFromUsername(username), record.id, taken);
    if (!candidate) {
      record.unresolved = username ? "invalid-username" : "not-in-guild";
      continue;
    }
    taken[candidate] = record.id;
    record.desired = candidate;
  }

  // Pass 2: members without a directory entry keep a handle, but never one that was claimed.
  for (const record of records) {
    if (record.desired) continue;
    if (officialId && record.id === officialId) continue;
    const current = normalizeHandle(record.settings.handle);
    if (current && (!taken[current] || String(taken[current]) === record.id)) {
      taken[current] = record.id;
      record.desired = current;
    }
  }

  for (const record of records) {
    if (record.desired) continue;
    if (officialId && record.id === officialId) continue;
    skipped.push({ id: record.id, reason: record.unresolved || "no-handle" });
  }

  for (const record of records) {
    if (!record.desired) continue;
    const current = normalizeHandle(record.settings.handle);
    if (current === record.desired) continue;
    updates.push(record);
  }

  if (!dryRun) {
    for (const record of updates) {
      const saved = await r2PutJSON(env, record.key, {
        ...record.settings,
        handle: record.desired,
        handle_synced_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      }).catch(() => false);
      if (!saved) skipped.push({ id: record.id, reason: "write-failed" });
    }
    const handles = {};
    for (const [handle, id] of Object.entries(taken)) {
      handles[handle] = { id, handle, updated_at: new Date().toISOString() };
    }
    await r2PutJSON(env, PROFILE_HANDLES_KEY, { version: 1, handles, updated_at: new Date().toISOString() }).catch(() => false);
    invalidateHandleIndex();
  }

  return {
    success: true,
    dry_run: dryRun,
    directory_source: directory.source,
    directory_members: directory.members.length,
    profiles: records.length,
    changed: updates.length,
    unchanged: records.filter(record => !updates.includes(record)).length,
    skipped,
    changes: updates.slice(0, 50).map(record => ({
      id: record.id,
      from: normalizeHandle(record.settings.handle),
      to: record.desired,
    })),
  };
}

// Collapses every per-member number the site can prove into one cached object, so a
// profile request and a feed request never rescan the catalogue separately.
async function buildProfileAggregates(env) {
  const catalog = await dbReadProductCatalog(env).catch(() => []);
  const products = Array.isArray(catalog) ? catalog : [];
  const [stats, countsDoc, comments, requestsDoc, downloadUsers] = await Promise.all([
    dbGetStats(env).catch(() => ({})),
    r2GetJSON(env, DB.DOWNLOADS, { counts: {} }).catch(() => ({ counts: {} })),
    r2GetJSON(env, DB.COMMENTS, {}).catch(() => ({})),
    r2GetJSON(env, "requests/data.json", { requests: [] }).catch(() => ({ requests: [] })),
    r2GetJSON(env, "logs/download-users.json", {}).catch(() => ({})),
  ]);
  const counts = (countsDoc && countsDoc.counts) || {};
  const requests = Array.isArray(requestsDoc && requestsDoc.requests) ? requestsDoc.requests : [];

  const uploaders = {};
  const totals = { resources: 0, anonymous: 0, downloads: 0, views: 0, comments: 0 };
  const productOwner = new Map();

  const blank = id => ({
    id,
    resources: 0,
    anonymous: 0,
    downloads: 0,
    views: 0,
    comments: 0,
    requests_fulfilled: 0,
    requests_made: 0,
    types: {},
    categories: {},
    monthly: {},
    first_at: null,
    last_at: null,
    best: null,
  });

  for (const product of products) {
    if (!product || typeof product !== "object") continue;
    const pid = String(product.id || "");
    const ownerId = String(product.uploader_id || product.author_id || "").trim();
    if (pid) productOwner.set(pid, ownerId);
    totals.resources++;
    if (product.is_anonymous === true) totals.anonymous++;
    if (!ownerId) continue;

    const itemStats = stats && typeof stats[pid] === "object" ? stats[pid] : {};
    // Deliberately the same precedence the resource pages use, so a profile can
    // never disagree with the page it links to: the live counter wins, then the
    // stats object, then the value stored on the product.
    const views = Number(itemStats.views ?? product.views) || 0;
    const downloads = Number(counts[pid] ?? product.downloads) || 0;
    const entry = uploaders[ownerId] || (uploaders[ownerId] = blank(ownerId));
    entry.resources++;
    if (product.is_anonymous === true) entry.anonymous++;
    entry.views += views;
    entry.downloads += downloads;
    totals.views += views;
    totals.downloads += downloads;

    const type = String(product.type || "preset").toLowerCase();
    const category = String(product.category || "others").toLowerCase();
    entry.types[type] = (entry.types[type] || 0) + 1;
    entry.categories[category] = (entry.categories[category] || 0) + 1;

    const created = String(product.created_at || "").slice(0, 10);
    if (created) {
      if (!entry.first_at || created < entry.first_at) entry.first_at = created;
      if (!entry.last_at || created > entry.last_at) entry.last_at = created;
      const month = created.slice(0, 7);
      entry.monthly[month] = (entry.monthly[month] || 0) + 1;
    }
    if (!entry.best || downloads > entry.best.downloads) {
      entry.best = { id: pid, name: String(product.name || ""), downloads, thumbnail: String(product.thumbnail || "") };
    }
  }

  for (const [pid, list] of Object.entries(comments || {})) {
    const ownerId = productOwner.get(String(pid)) || "";
    const count = Array.isArray(list) ? list.length : 0;
    if (!count) continue;
    totals.comments += count;
    if (uploaders[ownerId]) uploaders[ownerId].comments += count;
  }

  const downloads = {};
  for (const [userId, record] of Object.entries(downloadUsers || {})) {
    const id = String(userId || "").trim();
    if (!id || !record || typeof record !== "object") continue;
    downloads[id] = {
      count: Number(record.count) || 0,
      first_at: record.first_at || null,
      last_at: record.last_at || null,
    };
  }

  for (const request of requests) {
    if (!request || typeof request !== "object") continue;
    const requester = String(request.user_id || "");
    if (requester && !requester.startsWith("anon_")) {
      const entry = uploaders[requester] || (uploaders[requester] = blank(requester));
      entry.requests_made++;
    }
    if (String(request.status || "").toLowerCase() !== "completed") continue;
    const ownerId = productOwner.get(String(request.resource_id || "")) || "";
    if (!ownerId) continue;
    const entry = uploaders[ownerId] || (uploaders[ownerId] = blank(ownerId));
    entry.requests_fulfilled++;
  }

  return {
    built_at: Date.now(),
    totals: {
      ...totals,
      uploaders: Object.keys(uploaders).length,
      downloaders: Object.keys(downloads).length,
    },
    uploaders,
    downloads,
  };
}

async function readProfileAggregates(env, options = {}) {
  const maxAge = Number(options.maxAgeMs) || PROFILE_AGGREGATES_TTL_MS;
  if (!options.force) {
    const cached = await r2GetJSON(env, PROFILE_AGGREGATES_KEY, null).catch(() => null);
    const builtAt = Number(cached && cached.built_at) || 0;
    if (cached && cached.uploaders && builtAt && Date.now() - builtAt < maxAge) return cached;
  }
  const built = await buildProfileAggregates(env);
  await r2PutJSON(env, PROFILE_AGGREGATES_KEY, built).catch(() => {});
  return built;
}

function emptyProfileEntry(id) {
  return {
    id, resources: 0, anonymous: 0, downloads: 0, views: 0, comments: 0,
    requests_fulfilled: 0, requests_made: 0, types: {}, categories: {},
    monthly: {}, first_at: null, last_at: null, best: null,
  };
}

// Everything an achievement can be judged against, in one flat object.
function profileSubject(aggregates, discordId, extras = {}) {
  const id = String(discordId || "").trim();
  const entry = (aggregates && aggregates.uploaders && aggregates.uploaders[id]) || emptyProfileEntry(id);
  const made = (aggregates && aggregates.downloads && aggregates.downloads[id]) || { count: 0 };
  const resources = Number(entry.resources) || 0;
  return {
    ...entry,
    downloads_made: Number(made.count) || 0,
    member_days: Number(extras.member_days) || 0,
    followers: Number(extras.followers) || 0,
    avg_downloads: resources ? (Number(entry.downloads) || 0) / resources : 0,
    category_focus: topKey(entry.categories),
    type_focus: topKey(entry.types),
  };
}

function topKey(map) {
  let best = "";
  let bestCount = 0;
  for (const [key, value] of Object.entries(map || {})) {
    if (Number(value) > bestCount) { best = key; bestCount = Number(value); }
  }
  return best;
}

// metric -> threshold. Everything is derived from stored data, so no new tracking is
// needed and an achievement cannot be faked.
const PROFILE_ACHIEVEMENTS = [
  { key: "first_upload", label: "First Upload", icon: "fa-seedling", description: "Publish your first resource", metric: "resources", target: 1 },
  { key: "uploads_10", label: "Getting Started", icon: "fa-layer-group", description: "Publish 10 resources", metric: "resources", target: 10 },
  { key: "uploads_50", label: "Prolific", icon: "fa-mountain", description: "Publish 50 resources", metric: "resources", target: 50 },
  { key: "centurion", label: "Centurion", icon: "fa-medal", description: "Publish 100 resources", metric: "resources", target: 100 },
  { key: "downloads_100", label: "Warming Up", icon: "fa-fire", description: "Reach 100 downloads", metric: "downloads", target: 100 },
  { key: "downloads_1k", label: "Popular", icon: "fa-arrow-trend-up", description: "Reach 1,000 downloads", metric: "downloads", target: 1000 },
  { key: "downloads_10k", label: "Hall of Fame", icon: "fa-trophy", description: "Reach 10,000 downloads", metric: "downloads", target: 10000 },
  { key: "views_1k", label: "Spotlight", icon: "fa-eye", description: "Reach 1,000 resource views", metric: "views", target: 1000 },
  { key: "views_10k", label: "Famous", icon: "fa-star", description: "Reach 10,000 resource views", metric: "views", target: 10000 },
  { key: "comments_10", label: "Curator", icon: "fa-comments", description: "Receive 10 comments", metric: "comments", target: 10 },
  { key: "savior", label: "Savior", icon: "fa-hand-holding-heart", description: "Fulfil 5 requests", metric: "requests_fulfilled", target: 5 },
  { key: "wishlist", label: "Wishlist", icon: "fa-clipboard-list", description: "Request 5 resources", metric: "requests_made", target: 5 },
  { key: "collector", label: "Collector", icon: "fa-box-open", description: "Download 25 resources", metric: "downloads_made", target: 25 },
  { key: "og", label: "OG", icon: "fa-clock-rotate-left", description: "Be here for a year", metric: "member_days", target: 365 },
  { key: "signal", label: "Signal", icon: "fa-wave-square", description: "Averaging 5 downloads per resource (10+ resources)", metric: "avg_downloads", target: 5, minimum: { resources: 10 } },
];

function evaluateAchievements(subject, allSubjects) {
  const total = Array.isArray(allSubjects) ? allSubjects.length : 0;
  return PROFILE_ACHIEVEMENTS.map(spec => {
    const value = Number(subject[spec.metric]) || 0;
    const guardOk = !spec.minimum || Object.entries(spec.minimum).every(
      ([key, need]) => (Number(subject[key]) || 0) >= need
    );
    const earned = guardOk && value >= spec.target;
    let holders = 0;
    if (total) {
      for (const other of allSubjects) {
        const otherValue = Number(other[spec.metric]) || 0;
        const otherGuard = !spec.minimum || Object.entries(spec.minimum).every(
          ([key, need]) => (Number(other[key]) || 0) >= need
        );
        if (otherGuard && otherValue >= spec.target) holders++;
      }
    }
    return {
      key: spec.key,
      label: spec.label,
      description: spec.description,
      icon: spec.icon,
      target: spec.target,
      metric: spec.metric,
      value: Math.round(value * 10) / 10,
      progress: spec.target > 0 ? Math.min(1, value / spec.target) : 0,
      earned,
      rarity: total ? Math.round((holders / total) * 1000) / 10 : 0,
      holders,
    };
  });
}

async function stampAchievements(env, discordId, achievements) {
  const id = String(discordId || "").trim();
  const earnedNow = (achievements || []).filter(item => item.earned);
  if (!/^\d{15,25}$/.test(id) || !earnedNow.length) return {};
  try {
    const stored = await r2GetJSON(env, profileAchievementsKey(id), null);
    const unlocked = (stored && typeof stored.unlocked === "object" && stored.unlocked) || {};
    let changed = false;
    for (const item of earnedNow) {
      if (!unlocked[item.key]) {
        unlocked[item.key] = new Date().toISOString();
        changed = true;
      }
    }
    if (changed) {
      await r2PutJSON(env, profileAchievementsKey(id), { discord_id: id, unlocked });
    }
    return unlocked;
  } catch (_) {
    return {};
  }
}

async function readFollows(env, discordId, options = {}) {
  const id = String(discordId || "").trim();
  const empty = { following: [], followers: [] };
  if (!/^\d{15,25}$/.test(id) || !env?.STORAGE) return empty;
  const limit = Math.max(PROFILE_MAX_FOLLOWS, Number(options.limit) || 0);
  try {
    const stored = await r2GetJSON(env, profileFollowsKey(id), null);
    if (!stored || typeof stored !== "object") return empty;
    return {
      following: Array.isArray(stored.following) ? stored.following.map(String).filter(Boolean).slice(0, limit) : [],
      followers: Array.isArray(stored.followers) ? stored.followers.map(String).filter(Boolean).slice(0, limit) : [],
    };
  } catch (_) {
    return empty;
  }
}

async function setFollow(env, fromId, toId, shouldFollow) {
  const from = String(fromId || "").trim();
  const to = String(toId || "").trim();
  if (!/^\d{15,25}$/.test(from) || !/^\d{15,25}$/.test(to)) return { error: "Invalid member" };
  if (from === to) return { error: "You cannot follow yourself." };
  const mine = await readFollows(env, from);
  const theirs = await readFollows(env, to);
  const alreadyFollowing = mine.following.includes(to);
  if (alreadyFollowing === shouldFollow) {
    return { ok: true, following: mine.following.length, followers: theirs.followers.length, changed: false };
  }
  if (shouldFollow) {
    if (mine.following.length >= PROFILE_MAX_FOLLOWS) return { error: "Following list is full." };
    mine.following.push(to);
    if (!theirs.followers.includes(from)) theirs.followers.push(from);
  } else {
    mine.following = mine.following.filter(id => id !== to);
    theirs.followers = theirs.followers.filter(id => id !== from);
  }
  const now = new Date().toISOString();
  await Promise.all([
    r2PutJSON(env, profileFollowsKey(from), { ...mine, updated_at: now }),
    r2PutJSON(env, profileFollowsKey(to), { ...theirs, updated_at: now }),
  ]);
  return { ok: true, following: mine.following.length, followers: theirs.followers.length, changed: true };
}

// Following somebody asks whether their posts should notify you. The answer lives in
// one small document per member so the fan-out can honour it without extra reads.
const FOLLOW_PREFS_PREFIX = "database/follow_prefs/";

function followPrefsKey(discordId) {
  return `${FOLLOW_PREFS_PREFIX}${encodeURIComponent(String(discordId || "").trim())}.json`;
}

async function readFollowPrefs(env, discordId) {
  const id = String(discordId || "").trim();
  const base = { site: true, dm: true, muted: [] };
  if (!/^\d{15,25}$/.test(id) || !env?.STORAGE) return base;
  try {
    const stored = await r2GetJSON(env, followPrefsKey(id), null);
    if (!stored || typeof stored !== "object") return base;
    return {
      site: stored.site !== false,
      dm: stored.dm !== false,
      muted: Array.isArray(stored.muted) ? stored.muted.map(String).filter(value => /^\d{15,25}$/.test(value)).slice(0, 500) : [],
    };
  } catch (_) {
    return base;
  }
}

async function writeFollowPrefs(env, discordId, next) {
  const id = String(discordId || "").trim();
  if (!/^\d{15,25}$/.test(id)) return false;
  const value = {
    version: 1,
    site: next.site !== false,
    dm: next.dm !== false,
    muted: Array.isArray(next.muted) ? next.muted.map(String).filter(item => /^\d{15,25}$/.test(item)).slice(0, 500) : [],
    updated_at: new Date().toISOString(),
  };
  return Boolean(await r2PutJSON(env, followPrefsKey(id), value).catch(() => false));
}

// Does this member want feed notifications from that author?
function followAllows(prefs, authorId) {
  if (!prefs) return true;
  if (prefs.site === false) return false;
  return !prefs.muted.includes(String(authorId || ""));
}

// ── Feed notifications ───────────────────────────────────────────────────────
// Mentions and posts from followed members land in the site notification bell,
// and every original post is announced in Discord. Items reuse the shape the bell
// already renders for product announcements so the panel stays a single list.
const FEED_NOTIFICATION_PREFIX = "database/feed_notifications/";
const FEED_NOTIFICATION_LIMIT = 40;

function feedNotificationKey(discordId) {
  return `${FEED_NOTIFICATION_PREFIX}${encodeURIComponent(String(discordId || "").trim())}.json`;
}

async function readFeedNotifications(env, discordId) {
  const id = String(discordId || "").trim();
  if (!/^\d{15,25}$/.test(id) || !env?.STORAGE) return [];
  try {
    const stored = await r2GetJSON(env, feedNotificationKey(id), null);
    const items = Array.isArray(stored && stored.items) ? stored.items : [];
    return items.filter(item => item && typeof item === "object" && item.id).slice(0, FEED_NOTIFICATION_LIMIT);
  } catch (_) {
    return [];
  }
}

async function pushFeedNotification(env, discordId, item) {
  const id = String(discordId || "").trim();
  if (!/^\d{15,25}$/.test(id) || !item || !item.id || !env?.STORAGE) return false;
  const existing = await readFeedNotifications(env, id);
  if (existing.some(entry => entry.id === item.id)) return false;
  const items = [item, ...existing].slice(0, FEED_NOTIFICATION_LIMIT);
  return Boolean(await r2PutJSON(env, feedNotificationKey(id), { version: 1, items, updated_at: new Date().toISOString() }).catch(() => false));
}

// Newest first, so the bell shows feed activity above older product news.
function mergeFeedNotifications(list, feedItems) {
  const base = Array.isArray(list) ? list : [];
  const items = Array.isArray(feedItems) ? feedItems : [];
  if (!items.length) return base;
  return [...items, ...base]
    .sort((a, b) => String(b && b.created_at || "").localeCompare(String(a && a.created_at || "")))
    .slice(0, 60);
}

function feedNotificationPoster(post) {
  const author = (post && post.author) || {};
  const handle = String(author.handle || "");
  return {
    name: String(author.name || "A Zyrex member").slice(0, 80),
    handle,
    avatar: String(author.avatar || "/assets/default-avatar.png"),
    url: String(author.url || (handle ? `/@${handle}` : "/feed")),
  };
}

function feedNotificationText(post) {
  const raw = plainPostText(post && post.text);
  if (raw) return raw.length > 140 ? `${raw.slice(0, 137)}…` : raw;
  if (post && post.video) return "Shared a video.";
  return Array.isArray(post && post.media) && post.media.length ? "Shared an image." : "Shared a new post.";
}

// Channel that receives member feed posts. Resource announcements never go here.
const FEED_DISCORD_CHANNEL_ID = "1560857140871176243";
const FEED_MESSAGE_PREFIX = "database/feed_messages/";
// Discord allows a handful of edits per message per few seconds, so live counter
// updates are coalesced into one write per window.
const FEED_MESSAGE_EDIT_MIN_MS = 8000;

function feedMessageKey(postId) {
  return `${FEED_MESSAGE_PREFIX}${encodeURIComponent(String(postId || "").trim())}.json`;
}

function absoluteMediaUrl(value) {
  const url = String(value || "").trim();
  if (!url) return "";
  return /^https?:\/\//i.test(url) ? url : `https://zyrexediting.xyz${url.startsWith("/") ? "" : "/"}${url}`;
}

// Remote media may only be proxied for hosts the composer trusts, so the worker never
// turns into an open relay for arbitrary URLs.
const REMOTE_MEDIA_HOSTS = [
  {
    // Discord's own CDN refuses worker-side fetches, so stickers stay on the CDN and are
    // only proxied when a page asks for it explicitly.
    test: /^(?:cdn\.discordapp\.com|media\.discordapp\.net)$/i,
    referer: "https://discord.com/",
    proxy: false,
    alternate: host => (/^cdn\./i.test(host) ? host.replace(/^cdn\./i, "media.") : host.replace(/^media\./i, "cdn.")),
  },
  { test: /^(?:media\d*\.giphy\.com|i\.giphy\.com)$/i, referer: "https://giphy.com/" },
  { test: /^(?:media\.tenor\.com|tenor\.com|c\.tenor\.com)$/i, referer: "https://tenor.com/" },
];

function remoteMediaHost(value) {
  let parsed;
  try { parsed = new URL(String(value || "")); } catch (_) { return null; }
  if (parsed.protocol !== "https:") return null;
  return REMOTE_MEDIA_HOSTS.find(host => host.test.test(parsed.hostname)) || null;
}

function sanitizeRemoteMediaUrl(value) {
  const raw = String(value || "").trim();
  if (!raw || raw.length > 500) return "";
  return remoteMediaHost(raw) ? raw : "";
}

// Discord and the pages both read post media through this URL, so hotlink protection or
// a missing referer can no longer leave a broken sticker or GIF behind.
function proxiedMediaUrl(value) {
  const raw = absoluteMediaUrl(value);
  if (!raw) return "";
  const host = remoteMediaHost(raw);
  if (!host || host.proxy === false) return raw;
  return `https://zyrexediting.xyz/api/media?u=${encodeURIComponent(raw)}`;
}

const IMAGE_UPLOAD_MAX_BYTES = 3 * 1024 * 1024;
const VIDEO_UPLOAD_MAX_BYTES = 50 * 1024 * 1024;
const VIDEO_MAX_DURATION_SECONDS = 120;

// Videos live in the same bucket as images, under a name that says who uploaded them.
function videoFileName(ownerId, extension) {
  const owner = /^\d{15,25}$/.test(String(ownerId || "")) ? String(ownerId) : "0";
  return "video-" + owner + "-" + crypto.randomUUID().replace(/-/g, "").slice(0, 20) + "." + extension;
}

// The container comes from the bytes: MP4 keeps "ftyp" at offset 4, WebM starts with the
// EBML magic. Nothing is trusted from the client's content-type header alone.
function detectVideoExtension(bytes) {
  const head = Array.from(bytes.slice(0, 12));
  if (head[4] === 0x66 && head[5] === 0x74 && head[6] === 0x79 && head[7] === 0x70) return "mp4";
  if (head[0] === 0x1a && head[1] === 0x45 && head[2] === 0xdf && head[3] === 0xa3) return "webm";
  return "";
}

function isAllowedVideoUrl(value, discordId) {
  const id = String(discordId || "").trim();
  if (!/^\d{15,25}$/.test(id)) return false;
  const url = String(value || "").trim();
  if (url.length > 400) return false;
  return new RegExp("^https://thumbnail\\.zyrexediting\\.xyz/video-" + id + "-[a-f0-9]{8,24}\\.(?:mp4|webm)$", "i").test(url);
}

// A post carries either one video or up to four images, never both.
function sanitizePostVideo(value, authorId) {
  if (!value || typeof value !== "object") return null;
  const url = String(value.url || "").trim();
  if (!isAllowedVideoUrl(url, authorId)) return null;
  const duration = Number(value.duration);
  const width = Number(value.width);
  const height = Number(value.height);
  return {
    url,
    poster: sanitizeProfileMediaUrl(value.poster, authorId),
    width: Number.isFinite(width) && width > 0 ? Math.round(width) : 0,
    height: Number.isFinite(height) && height > 0 ? Math.round(height) : 0,
    duration: Number.isFinite(duration) && duration > 0 ? Math.min(duration, VIDEO_MAX_DURATION_SECONDS) : 0,
  };
}

// Extensions come from the bytes, never from the client's file name.
function detectImageExtension(bytes) {
  const head = Array.from(bytes.slice(0, 12));
  if (head[0] === 0x89 && head[1] === 0x50 && head[2] === 0x4e && head[3] === 0x47) return "png";
  if (head[0] === 0xff && head[1] === 0xd8 && head[2] === 0xff) return "jpg";
  if (head[0] === 0x47 && head[1] === 0x49 && head[2] === 0x46 && head[3] === 0x38) return "gif";
  if (head[0] === 0x52 && head[1] === 0x49 && head[2] === 0x46 && head[3] === 0x46 &&
    head[8] === 0x57 && head[9] === 0x45 && head[10] === 0x42 && head[11] === 0x50) return "webp";
  return "";
}


// ── Pasted links ────────────────────────────────────────────────────────────────
// A pasted page link becomes a card under the post; a pasted image link is copied
// into our own bucket and becomes a real attachment.
const LINK_PREVIEW_LIMIT = 2;
const LINK_PREVIEW_TTL_MS = 3 * 24 * 60 * 60 * 1000;
const LINK_PREVIEW_MAX_BYTES = 400 * 1024;
const LINK_PREVIEW_UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36";

const LINK_FETCH_BLOCKED_HOSTS = [
  /(^|\.)zyrexediting\.xyz$/i,
  /(^|\.)localhost$/i,
  /(^|\.)local$/i,
  /(^|\.)internal$/i,
  /(^|\.)home\.arpa$/i,
];

// The composer forwards whatever was pasted, so loopback and platform hosts are refused
// before the worker ever opens a connection.
function isPublicFetchUrl(value) {
  let parsed;
  try { parsed = new URL(String(value || "").trim()); } catch (_) { return false; }
  if (parsed.protocol !== "https:" && parsed.protocol !== "http:") return false;
  if (parsed.username || parsed.password) return false;
  if (parsed.port && parsed.port !== "80" && parsed.port !== "443") return false;
  const host = parsed.hostname.toLowerCase();
  if (!host || !host.includes(".")) return false;
  if (/^\[/.test(host) || /^\d{1,3}(?:\.\d{1,3}){3}$/.test(host)) return false;
  if (!/[a-z]/.test(host)) return false;
  if (LINK_FETCH_BLOCKED_HOSTS.some(pattern => pattern.test(host))) return false;
  return true;
}

function shortHash(value) {
  let hash = 0x811c9dc5;
  const text = String(value || "");
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, "0");
}

function decodeHtmlText(value) {
  return String(value || "")
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'")
    .replace(/&lt;/g, "<").replace(/&gt;/g, ">")
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
    .replace(/&amp;/g, "&")
    .replace(/\s+/g, " ")
    .trim();
}

// Link thumbnails are mirrored, so only our own bucket may appear on a card.
function sanitizeLinkImage(value) {
  const url = String(value || "").trim();
  if (!url || url.length > 400) return "";
  return /^https:\/\/thumbnail\.zyrexediting\.xyz\/(?:post|comment)-\d{15,25}-[a-f0-9]{8,}\.(?:png|jpe?g|gif|webp)$/i.test(url) ? url : "";
}

function readLinkMeta(html, baseUrl) {
  const page = String(html || "");
  const meta = (names) => {
    for (const name of names) {
      const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      const patterns = [
        new RegExp("<meta[^>]+(?:property|name)=[\"']" + escaped + "[\"'][^>]+content=[\"']([^\"']+)[\"']", "i"),
        new RegExp("<meta[^>]+content=[\"']([^\"']+)[\"'][^>]+(?:property|name)=[\"']" + escaped + "[\"']", "i"),
      ];
      for (const pattern of patterns) {
        const match = page.match(pattern);
        if (match && match[1]) return match[1];
      }
    }
    return "";
  };
  const absolute = (value) => {
    if (!value) return "";
    try { return new URL(decodeHtmlText(value), baseUrl).href; } catch (_) { return ""; }
  };
  const titleTag = (page.match(/<title[^>]*>([^<]{1,300})<\/title>/i) || [])[1] || "";
  return {
    title: decodeHtmlText(meta(["og:title", "twitter:title"]) || titleTag).slice(0, 160),
    description: decodeHtmlText(meta(["og:description", "twitter:description", "description"])).slice(0, 300),
    site: decodeHtmlText(meta(["og:site_name", "application-name"])).slice(0, 60),
    image: absolute(meta(["og:image:secure_url", "og:image", "twitter:image", "twitter:image:src"])),
  };
}

async function mirrorRemoteImage(env, rawUrl, ownerId) {
  const target = String(rawUrl || "").trim();
  if (!isPublicFetchUrl(target)) return { error: "That link cannot be read." };
  if (!env?.STORAGE) return { error: "Storage is unavailable right now." };
  let response;
  try {
    response = await fetch(target, {
      headers: { "User-Agent": LINK_PREVIEW_UA, Accept: "image/*,*/*;q=0.8" },
      redirect: "follow",
      signal: AbortSignal.timeout(9000),
    });
  } catch (_) { return { error: "That image could not be downloaded." }; }
  if (!response.ok) return { error: "That image could not be downloaded." };
  const type = String(response.headers.get("content-type") || "").toLowerCase();
  if (!/^image\//.test(type)) return { error: "That link is not an image.", notImage: true };
  const buffer = await response.arrayBuffer().catch(() => null);
  const bytes = buffer ? new Uint8Array(buffer) : new Uint8Array();
  if (!bytes.length) return { error: "That image could not be downloaded." };
  if (bytes.length > IMAGE_UPLOAD_MAX_BYTES) return { error: "That image is larger than 3 MB." };
  const extension = detectImageExtension(bytes);
  if (!extension) return { error: "That file is not a supported image.", notImage: true };
  const owner = /^\d{15,25}$/.test(String(ownerId || "")) ? String(ownerId) : "0";
  const name = "post-" + owner + "-" + shortHash(target + ":" + bytes.length) + "." + extension;
  const stored = await env.STORAGE.put("thumbnails/" + name, bytes, {
    httpMetadata: { contentType: extension === "jpg" ? "image/jpeg" : "image/" + extension },
  }).catch(() => false);
  if (!stored) return { error: "Could not store that image." };
  return { url: "https://thumbnail.zyrexediting.xyz/" + name };
}

async function buildLinkPreview(env, rawUrl, ownerId) {
  const target = String(rawUrl || "").trim();
  if (!isPublicFetchUrl(target)) return { success: false, error: "That link cannot be previewed." };
  const cacheKey = "link_previews/" + shortHash(target) + ".json";
  const cached = await r2GetJSON(env, cacheKey, null).catch(() => null);
  if (cached && cached.link && cached.link.url === target &&
    Date.now() - Date.parse(cached.fetched_at || "") < LINK_PREVIEW_TTL_MS) {
    return { success: true, link: cached.link };
  }
  let html = "";
  try {
    const response = await fetch(target, {
      headers: { "User-Agent": LINK_PREVIEW_UA, Accept: "text/html,application/xhtml+xml" },
      redirect: "follow",
      signal: AbortSignal.timeout(9000),
    });
    const type = String(response.headers.get("content-type") || "text/html").toLowerCase();
    if (response.ok && !/^(?:image|video|audio)\//.test(type)) {
      html = (await response.text()).slice(0, LINK_PREVIEW_MAX_BYTES);
    }
  } catch (_) {}
  if (!html) return { success: false, error: "That page could not be read." };
  const meta = readLinkMeta(html, target);
  if (!meta.title && !meta.description && !meta.image) return { success: false, error: "That page has no preview." };
  if (meta.image) {
    const mirrored = await mirrorRemoteImage(env, meta.image, ownerId).catch(() => null);
    meta.image = (mirrored && mirrored.url) || "";
  }
  const link = { url: target, title: meta.title, description: meta.description, site: meta.site, image: meta.image };
  await r2PutJSON(env, cacheKey, { fetched_at: new Date().toISOString(), link }).catch(() => false);
  return { success: true, link };
}

function sanitizePostLinks(value) {
  if (!Array.isArray(value)) return [];
  const links = [];
  for (const row of value) {
    if (!row || typeof row !== "object") continue;
    const url = String(row.url || "").trim();
    if (!isPublicFetchUrl(url) || url.length > 500) continue;
    if (links.some(link => link.url === url)) continue;
    const link = {
      url,
      title: String(row.title || "").slice(0, 160),
      description: String(row.description || "").slice(0, 300),
      site: String(row.site || "").slice(0, 60),
      image: sanitizeLinkImage(row.image),
    };
    if (!link.title && !link.description && !link.image) continue;
    links.push(link);
    if (links.length >= LINK_PREVIEW_LIMIT) break;
  }
  return links;
}

// Notifications, embeds and the Discord card only need the words, never the syntax.
function plainPostText(value) {
  return String(value || "")
    .replace(/!\[(?:sticker:[^\]]*|gif)\]\([^)]*\)/gi, " ")
    .replace(/```[\s\S]*?```/g, " ")
    .replace(/`([^`]*)`/g, "$1")
    .replace(/\[([^\]]*)\]\((?:https?:\/\/[^\s)]*)\)/gi, "$1")
    .replace(/[*_~]{1,3}/g, "")
    .replace(/\r?\n+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}



// ── Feed moderation index ──────────────────────────────────────────────────────
// One document lists every hidden post and announcement, so the timeline can filter
// them with a single read instead of touching one file per item.
const FEED_HIDDEN_KEY = "feed/hidden/index.json";
let feedHiddenMemo = null;

function isAdminSession(session) {
  return Boolean(session && session.userId && ADMIN_IDS.includes(String(session.userId)));
}

// The app key ships inside js/auth.js, so it is public. It may read the catalogue, but
// every state-changing route must be authorized by a signed admin session or the master
// (or maintenance) key instead.
function isAdminRequest(request, env, hasMasterKey) {
  if (hasMasterKey) return true;
  return isAdminSession(parseSession(null, request));
}

// The VPS bot proves itself with its own Discord token, exactly like /api/internal/*. The
// public app key is never accepted here.
// Tokens proven valid by Discord, so a token that only lives in the VPS environment still
// authorizes the bot's own calls. Cached briefly to keep the extra round trip rare.
const trustedBotTokenCache = new Map();

async function isTrustedBotRequest(request, env) {
  const auth = request.headers.get("Authorization") || "";
  if (!auth.startsWith("Bot ")) return false;
  const token = auth.slice(4).trim();
  if (!token) return false;
  if (discordTokenCandidates(env).some(candidate => candidate.token === token)) return true;
  const cached = trustedBotTokenCache.get(token);
  if (cached && Date.now() - cached.at < 10 * 60 * 1000) return cached.ok;
  const probe = await discordRawGet(token, "/users/@me");
  const ok = probe.status === 200 && Boolean(probe.body && probe.body.id);
  if (trustedBotTokenCache.size > 16) trustedBotTokenCache.clear();
  trustedBotTokenCache.set(token, { at: Date.now(), ok });
  return ok;
}

function noticeHiddenId(productId) {
  return `notice:${String(productId || "").trim()}`;
}

async function readFeedHiddenIds(env) {
  const now = Date.now();
  if (feedHiddenMemo && now - feedHiddenMemo.at < 20000) return feedHiddenMemo.value;
  const stored = await r2GetJSON(env, FEED_HIDDEN_KEY, null).catch(() => null);
  const ids = new Set(Array.isArray(stored && stored.ids) ? stored.ids.map(String) : []);
  feedHiddenMemo = { at: now, value: ids };
  return ids;
}

async function writeFeedHiddenIds(env, ids) {
  const value = new Set(ids);
  feedHiddenMemo = { at: Date.now(), value };
  const saved = await r2PutJSON(env, FEED_HIDDEN_KEY, {
    version: 1,
    ids: Array.from(value),
    updated_at: new Date().toISOString(),
  }).catch(() => false);
  return Boolean(saved);
}

async function setFeedHidden(env, id, hidden) {
  const ids = await readFeedHiddenIds(env);
  const key = String(id || "").trim();
  if (!key) return false;
  if (hidden) ids.add(key); else ids.delete(key);
  return writeFeedHiddenIds(env, ids);
}

// ── NSFW guard ──────────────────────────────────────────────────────────────────
// Words are matched as stems between boundaries, so "pornosu" is caught but "Essex" is
// not. The list lives in R2 and the admin panel can edit it without a deploy.
const MODERATION_SETTINGS_KEY = "feed/moderation/settings.json";
const MODERATION_LOG_PREFIX = "feed/moderation/log/";
const MODERATION_LOG_PAGE = 40;
// Literal words, shared verbatim with the Discord bot's word filter. Turkish variants are
// spelled out (amcik / amcık) so the same entry means the same thing on both sides.
const DEFAULT_NSFW_STEMS = [
  "porn", "porno", "nude", "nudes", "nudity", "blowjob", "handjob", "hentai", "onlyfans",
  "cumshot", "dildo", "masturbat", "creampie", "nsfw", "escort", "striptease",
  "amcik", "amcık", "orospu", "oruspu", "siktir", "sikeyim", "sikerim", "sikiş", "sikis",
  "yarrak", "taşşak", "tassak", "sürtük", "surtuk", "fahişe", "fahise",
  "götveren", "gotveren", "pezevenk",
];
// Words that contain a stem but are perfectly fine.
const DEFAULT_NSFW_ALLOWED = ["sussex", "essex", "middlesex", "pussycat", "assassin", "sexton"];
const DEFAULT_MODERATION_SETTINGS = {
  textStems: DEFAULT_NSFW_STEMS,
  allowedWords: DEFAULT_NSFW_ALLOWED,
  imageThreshold: 0.6,
  // "site" runs the classifier inside this Worker (Workers AI); "bot" keeps the old
  // VPS round trip. The bot is still tried as a fallback when Workers AI is unavailable.
  imageClassifier: "site",
  autoDelete: true,
  autoWarn: true,
  failOpen: true,
};

const WORD_FILTER_KEY = "moderation/word_filter.json";
const WORD_FILTER_LIMIT = 500;
const WORD_FILTER_CACHE_MS = 30000;
let wordFilterCache = null;

function escapeRegexLiteral(value) {
  return String(value || "").replace(/[\^$\\.*+?()[\]{}|]/g, "\\$&");
}

function cleanWordList(value, limit = WORD_FILTER_LIMIT) {
  const seen = new Set();
  const words = [];
  for (const entry of Array.isArray(value) ? value : []) {
    const word = String(entry || "").replace(/\s+/g, " ").trim();
    if (!word || word.length > 48) continue;
    const key = word.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    words.push(word);
    if (words.length >= limit) break;
  }
  return words;
}

function normalizeWordFilterShape(value, fallbackSource = "site") {
  const source = value && typeof value === "object" ? value : {};
  return {
    version: Number(source.version) > 0 ? Math.floor(Number(source.version)) : 1,
    words: cleanWordList(source.words && source.words.length ? source.words : DEFAULT_NSFW_STEMS),
    allowlist: cleanWordList(source.allowlist || DEFAULT_NSFW_ALLOWED),
    updated_at: typeof source.updated_at === "string" && source.updated_at ? source.updated_at : new Date().toISOString(),
    updated_by: typeof source.updated_by === "string" && source.updated_by ? source.updated_by : fallbackSource,
  };
}

// Seeds R2 from the moderation defaults the first time it runs, so the bot has data to pull.
async function readWordFilter(env) {
  const now = Date.now();
  if (wordFilterCache && now - wordFilterCache.at < WORD_FILTER_CACHE_MS) return wordFilterCache.value;
  let stored = await r2GetJSON(env, WORD_FILTER_KEY, null).catch(() => null);
  if (!stored) {
    stored = normalizeWordFilterShape({ words: DEFAULT_NSFW_STEMS, allowlist: DEFAULT_NSFW_ALLOWED, updated_by: "site" }, "site");
    await r2PutJSON(env, WORD_FILTER_KEY, stored).catch(() => false);
  }
  const value = normalizeWordFilterShape(stored);
  wordFilterCache = { at: now, value };
  return value;
}

async function writeWordFilter(env, words, allowlist, updatedBy) {
  const current = await readWordFilter(env);
  const next = normalizeWordFilterShape({
    version: (Number(current.version) || 1) + 1,
    words,
    allowlist: allowlist === undefined ? current.allowlist : allowlist,
    updated_at: new Date().toISOString(),
    updated_by: updatedBy || "site",
  });
  const saved = await r2PutJSON(env, WORD_FILTER_KEY, next).catch(() => false);
  wordFilterCache = null;
  invalidateModerationSettings();
  return saved ? next : null;
}

let moderationSettingsCache = null;

function normalizeModerationText(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[-\u2010-\u2015'\u2019]/g, "")
    .replace(/[^a-z0-9çğıöşü\s]/g, " ")
    .replace(/(.)\1+/g, "$1")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeModerationStem(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9çğıöşü]+/g, "")
    // Text normalisation collapses repeated letters, so the stem has to collapse too.
    .replace(/(.)\1+/g, "$1");
}

async function readModerationSettings(env) {
  const now = Date.now();
  if (moderationSettingsCache && now - moderationSettingsCache.at < 60000) return moderationSettingsCache.value;
  const stored = await r2GetJSON(env, MODERATION_SETTINGS_KEY, null).catch(() => null);
  const value = { ...DEFAULT_MODERATION_SETTINGS, ...(stored && typeof stored === "object" ? stored : {}) };
  // The R2 word filter is the single source of truth: the bot edits it too, so settings
  // from before this file existed only survive as a fallback.
  const filter = await readWordFilter(env).catch(() => null);
  if (filter) {
    value.textStems = filter.words;
    value.allowedWords = filter.allowlist;
  }
  if (!Array.isArray(value.textStems) || !value.textStems.length) value.textStems = DEFAULT_NSFW_STEMS;
  if (!Array.isArray(value.allowedWords)) value.allowedWords = DEFAULT_NSFW_ALLOWED;
  moderationSettingsCache = { at: now, value };
  return value;
}

function invalidateModerationSettings() {
  moderationSettingsCache = null;
}

// Returns the stems that matched, so the log can say what tripped the filter.
function nsfwTextHits(text, settings) {
  const config = settings || DEFAULT_MODERATION_SETTINGS;
  let normalized = normalizeModerationText(text);
  if (!normalized) return [];
  // Allowed words are blanked out first, so "Sussex" never trips the "sex" style stems.
  for (const word of config.allowedWords || []) {
    const allowed = normalizeModerationText(word);
    if (!allowed) continue;
    let index = normalized.indexOf(allowed);
    while (index !== -1) {
      normalized = normalized.slice(0, index) + " ".repeat(allowed.length) + normalized.slice(index + allowed.length);
      index = normalized.indexOf(allowed);
    }
  }
  const hits = [];
  for (const stem of config.textStems || []) {
    const pattern = escapeRegexLiteral(normalizeModerationStem(stem));
    if (!pattern) continue;
    let regex;
    try { regex = new RegExp("(^|[^a-z0-9])(" + pattern + ")", "i"); } catch (_) { continue; }
    if (regex.test(normalized)) hits.push(stem);
  }
  return hits;
}

async function logModerationEvent(env, event) {
  if (!env?.STORAGE) return false;
  const id = `${Date.now()}-${(crypto.randomUUID ? crypto.randomUUID().replace(/-/g, "").slice(0, 10) : Math.random().toString(16).slice(2, 12))}`;
  const row = { id, at: new Date().toISOString(), ...event };
  await r2PutJSON(env, `${MODERATION_LOG_PREFIX}${id}.json`, row).catch(() => false);
  return row;
}

async function listModerationEvents(env, limit = MODERATION_LOG_PAGE) {
  const files = await r2List(env, MODERATION_LOG_PREFIX).catch(() => []);
  const keys = (files || []).map(file => String(file && file.key || "")).filter(Boolean).sort().reverse().slice(0, Math.max(1, Math.min(limit, 200)));
  const rows = await Promise.all(keys.map(key => r2GetJSON(env, key, null).catch(() => null)));
  return rows.filter(Boolean);
}

// ── Site-side image classifier ─────────────────────────────────────────────────
// The image never leaves the Zyrex stack: the Worker fetches it and asks Workers AI for a
// verdict. Two models answer in parallel - a fast caption that is scanned for anatomical
// words, and a vision model that is asked for a JSON verdict - so an obvious image is caught
// even when the slower model times out, and no VPS round trip is needed.
const NSFW_AI_MAX_BYTES = 6 * 1024 * 1024;
// Bounded so one slow model cannot hold an upload open: the model calls run in parallel.
const NSFW_AI_TIMEOUT_MS = 13000;
const NSFW_CAPTION_TIMEOUT_MS = 9000;
const NSFW_CAPTION_PROMPT = "Describe this image in one short sentence. Say whether a person is visible, what they are wearing, and whether any skin, nudity or genitals are showing.";
// Matched as whole words only, so \"analysis\", \"cocktail\" and \"cumulus\" never trip the filter.
const NSFW_CAPTION_STEMS = [
  "naked", "nude", "nudes", "nudity", "topless", "nipple", "nipples", "breast", "breasts",
  "genital", "genitals", "genitalia", "penis", "penises", "phallus", "scrotum", "testicle",
  "testicles", "vulva", "vagina", "vaginas", "pussy", "anus", "anal", "dick", "cock", "cum",
  "cumshot", "semen", "ejaculation", "ejaculating", "penetration", "blowjob", "fellatio",
  "masturbation", "masturbating", "erection", "erect", "intercourse", "orgy", "hardcore",
  "xxx", "porn", "porno", "pornography", "erotic", "lingerie", "buttock", "buttocks", "sex",
  "sexual", "nsfw", "gore", "gory", "mutilated", "mutilation", "ciplak", "sik", "yarrak",
];
// A verdict that says "unsafe" while the reason denies nudity is a model contradiction.
const NSFW_NEGATED_REASON = /\b(no|not|without|zero|free of)\b[^.]{0,24}\b(nudity|nude|explicit|sexual|nsfw|gore|naked)\b/i;
// Models refuse unusable frames ("classifier is not working", "cannot determine"); that is a
// missing verdict, not a guilty one.
const NSFW_UNDETERMINED = /(not working properly|unable to (classify|determine|analy[sz]e)|cannot (classify|determine|analy[sz]e)|no discernible (objects|features)|too dark to (tell|see))/i;
// A refusal to describe the image is itself evidence: safety-tuned models decline explicit
// content. This is a separate pattern from the "cannot classify" case above.
const NSFW_REFUSAL = /\b(can(?:no|')t|cannot|unable to|won't|will not|not able to)\b[^.]{0,40}\b(describe|show|display|share|process|analy[sz]e|help with (that|this)|assist with (that|this)|provide (that|this))\b/i;
const NSFW_VISION_PROMPT = [
  "You are an automated image-safety classifier for a video editing community where",
  "members are 13 or older.",
  "",
  "Mark the image UNSAFE only when it shows: visible nudity, exposed female nipples,",
  "genitals (penis, vulva, scrotum), buttocks, underwear worn as outerwear in a sexual",
  "context, sexual acts, explicit sexual poses, or extreme gore and mutilation.",
  "",
  "Mark the image SAFE when it shows anything else, including editing software screenshots,",
  "game captures, memes, logos, text cards, portraits with clothes, cosplay, swimwear at a",
  "beach, sports, or artistic photos without exposed genitalia.",
  "",
  "Answer with only this JSON on one line and nothing else:",
  '{"nsfw": true or false, "score": number between 0 and 1, "reason": "max 8 words"}',
].join("\n");
const NSFW_YES_NO_PROMPT = "Answer with one word only. Does this image contain nudity, exposed genitals, sexual activity or extreme gore? yes or no:";
// A narrower question is easier to answer than the general one, so it is asked in parallel.
const NSFW_ANATOMY_PROMPT = "Answer with one word only, yes or no. Is a penis, scrotum, vulva, anus, naked buttocks or a bare female breast clearly visible in this image?";
// Captions come from the fast small model; verdicts from the strongest multimodal models that
// are available on this account, in order. Llama 4 Scout names explicit content reliably and
// Qwen catches what it misses.
const NSFW_CAPTION_MODEL = "@cf/moondream/moondream3.1-9B-A2B";
const NSFW_VERDICT_MODELS = [
  "@cf/meta/llama-4-scout-17b-16e-instruct",
  "@cf/qwen/qwen3.8-27b",
  "@cf/llava-hf/llava-1.5-7b-hf",
];

function nsfwVerdictModels(env) {
  const preferred = String((env && env.NSFW_AI_MODEL) || "").trim();
  if (!preferred) return NSFW_VERDICT_MODELS.slice();
  return [preferred, ...NSFW_VERDICT_MODELS.filter(model => model !== preferred)];
}

// Captioning models name body parts plainly, so the anatomical words are scanned for.
// Matching is on whole words: a prefix match turned "analysis" into "anal" and blocked a
// harmless canvas animation.
function nsfwCaptionHits(caption) {
  const text = normalizeModerationText(caption);
  if (!text) return [];
  const words = text.split(" ");
  const hits = [];
  for (const stem of NSFW_CAPTION_STEMS) {
    const needle = normalizeModerationText(stem);
    if (!needle) continue;
    const found = needle.includes(" ")
      ? text.includes(needle)
      : words.indexOf(needle) !== -1;
    if (found) hits.push(stem);
  }
  return hits;
}

// Models answer in prose often enough that the verdict has to be read forgivingly.
function parseNsfwVerdict(text, options = {}) {
  const raw = String(text || "").trim();
  if (!raw) return null;
  if (NSFW_REFUSAL.test(raw)) return { nsfw: true, score: 0.85, reason: "model refused to describe the image", direct: true };
  if (NSFW_UNDETERMINED.test(raw)) return null;
  const jsonMatch = raw.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    try {
      const data = JSON.parse(jsonMatch[0]);
      const flag = data.nsfw ?? data.unsafe ?? data.explicit ?? data.is_nsfw;
      if (flag !== undefined && flag !== null) {
        const nsfw = flag === true || /^(true|yes|y|1|unsafe|explicit|nsfw)$/i.test(String(flag).trim());
        let score = Number(data.score ?? data.confidence ?? data.probability);
        if (!Number.isFinite(score)) score = nsfw ? 0.9 : 0.05;
        if (score > 1 && score <= 100) score /= 100;
        score = Math.min(Math.max(score, 0), 1);
        const reason = String(data.reason || data.label || "").replace(/\s+/g, " ").slice(0, 80);
        // Vision models sometimes set the flag while the reason says the opposite
        // ("no nudity or explicit content"), so the reason wins.
        if (nsfw && NSFW_NEGATED_REASON.test(reason || raw)) {
          return { nsfw: false, score: 0.08, reason };
        }
        if (!nsfw) return { nsfw: false, score: Math.min(score, 0.5), reason };
        return { nsfw: true, score, reason };
      }
    } catch (_) { /* fall through to the keyword read */ }
  }
  const lower = raw.toLowerCase();
  // A bare "yes"/"no" answer to the direct question.
  const bare = lower.replace(/[^a-z ]/g, " ").trim();
  // A short yes/no answer to the direct question is a first-class verdict.
  if (/^(yes|yes it does|true)\b/.test(bare)) return { nsfw: true, score: 0.85, reason: raw.slice(0, 80), direct: true };
  if (/^(no|no it does not|false)\b/.test(bare)) return { nsfw: false, score: 0.05, reason: raw.slice(0, 80), direct: true };
  const stripped = lower.replace(/(?:not|no|isn't|isnt|without|free of)\s+(?:[a-z]+\s+){0,3}(nsfw|unsafe|explicit|nude|nudity|sexual|porn|pornographic|gore)/g, " ");
  // The narrow anatomy question is only trusted when it was answered plainly, so long
  // explanations cannot be misread as a verdict.
  if (options.directOnly) return null;
  if (/\bnot\s+(safe|sfw)\b/.test(lower)) {
    return { nsfw: true, score: 0.6, reason: raw.replace(/\s+/g, " ").slice(0, 80) };
  }
  if (/\b(nsfw|unsafe|explicit|nude|nudity|porn|pornographic|sexual|gore)\b/.test(stripped)) {
    return { nsfw: true, score: 0.8, reason: raw.replace(/\s+/g, " ").slice(0, 80) };
  }
  if (/\b(safe|sfw|appropriate|clean)\b/.test(stripped) || stripped !== lower) {
    return { nsfw: false, score: 0.05, reason: raw.replace(/\s+/g, " ").slice(0, 80) };
  }
  return null;
}

function withTimeout(promise, ms, label) {
  return Promise.race([
    promise,
    new Promise((_, reject) => setTimeout(() => reject(new Error(label + " timed out")), ms)),
  ]);
}

// The vision models disagree about their input shape, so each shape is tried in turn.
// stream:false matters: moondream streams by default and returns an empty object otherwise.
function visionText(output) {
  if (!output) return "";
  if (typeof output === "string") return output.trim();
  const inner = output.result && typeof output.result === "object" ? output.result : null;
  const choice = Array.isArray(output.choices) && output.choices[0] ? output.choices[0] : null;
  const choiceMessage = choice && choice.message ? choice.message : null;
  const innerChoice = inner && Array.isArray(inner.choices) && inner.choices[0] ? inner.choices[0] : null;
  const innerMessage = innerChoice && innerChoice.message ? innerChoice.message : null;
  const candidates = [
    choiceMessage && choiceMessage.content,
    innerMessage && innerMessage.content,
    output.answer, output.response, output.description, output.text, output.summary,
    inner && inner.answer, inner && inner.description, inner && inner.caption, inner && inner.response,
  ];
  for (const candidate of candidates) {
    if (typeof candidate === "string" && candidate.trim()) return candidate.trim();
  }
  return "";
}

async function runVisionModel(env, model, bytes, prompt, timeoutMs) {
  const dataUrl = "data:image/jpeg;base64," + bytesToBase64(bytes);
  const shapes = [
    // Chat-style multimodal models (llama 4, qwen, gemma).
    {
      messages: [{
        role: "user",
        content: [{ type: "text", text: prompt }, { type: "image_url", image_url: { url: dataUrl } }],
      }],
      max_tokens: 120,
      stream: false,
    },
    // Moondream takes a data url and only answers when streaming is off.
    { image: dataUrl, prompt, max_tokens: 120, stream: false },
    // llava takes raw bytes.
    { image: Array.from(bytes), prompt, max_tokens: 120 },
    { image: Array.from(bytes), messages: [{ role: "user", content: prompt }], max_tokens: 120 },
  ];
  const errors = [];
  for (const input of shapes) {
    try {
      const output = await withTimeout(env.AI.run(model, input), timeoutMs || NSFW_AI_TIMEOUT_MS, model);
      const text = visionText(output);
      if (text) return { text, error: null };
      errors.push("empty response");
    } catch (error) {
      const message = String((error && error.message) || error);
      errors.push(message.slice(0, 140));
      // A timeout will not be fixed by trying another input shape.
      if (/timed out/i.test(message)) break;
    }
  }
  return { text: "", error: errors.join(" | ").slice(0, 300) };
}

async function classifyImageOnSite(env, url) {
  if (!env || !env.AI || typeof env.AI.run !== "function") {
    return { ok: false, unavailable: true, reason: "no-ai-binding", source: "site" };
  }
  if (!url) return { ok: false, unavailable: true, reason: "no-url", source: "site" };
  const image = await fetchImageBytes(env, url, NSFW_AI_MAX_BYTES, { timeout: 9000 }).catch(() => null);
  if (!image || !image.bytes || !image.bytes.length) {
    return { ok: false, unavailable: true, reason: "fetch-failed", source: "site" };
  }
  const bytes = image.bytes;
  const verdictModels = nsfwVerdictModels(env);
  const generalModel = verdictModels[0];
  const anatomyModel = verdictModels[1] || verdictModels[0];
  const errors = [];
  // Three different models answer at the same time, so the check is bounded by the slowest
  // single call instead of the sum: a caption, a plain yes/no anatomy answer and a JSON verdict.
  const [caption, anatomyRaw, generalRaw] = await Promise.all([
    runVisionModel(env, NSFW_CAPTION_MODEL, bytes, NSFW_CAPTION_PROMPT, NSFW_CAPTION_TIMEOUT_MS),
    runVisionModel(env, anatomyModel, bytes, NSFW_ANATOMY_PROMPT, NSFW_AI_TIMEOUT_MS),
    runVisionModel(env, generalModel, bytes, NSFW_VISION_PROMPT, NSFW_AI_TIMEOUT_MS),
  ]);
  const verdicts = [];
  const anatomy = anatomyRaw.error ? null : parseNsfwVerdict(anatomyRaw.text, { directOnly: true });
  let general = generalRaw.error ? null : parseNsfwVerdict(generalRaw.text);
  if (!general && !generalRaw.error) {
    // Unparseable answer: one direct yes/no re-ask before giving up on this model.
    const retry = await runVisionModel(env, generalModel, bytes, NSFW_YES_NO_PROMPT, NSFW_AI_TIMEOUT_MS);
    general = retry.error ? null : parseNsfwVerdict(retry.text);
    if (!general) errors.push({ model: generalModel, reason: "unparsed", text: generalRaw.text.slice(0, 140) });
  } else if (generalRaw.error) {
    errors.push({ model: generalModel, reason: generalRaw.error });
  }
  if (general) verdicts.push({ model: generalModel, verdict: general });
  if (anatomy) verdicts.push({ model: anatomyModel, verdict: anatomy });
  if (anatomyRaw.error) errors.push({ model: anatomyModel, reason: anatomyRaw.error });
  // A spare model is only asked when the first two were silent.
  if (!verdicts.length) {
    for (const model of verdictModels.slice(2)) {
      const spare = await runVisionModel(env, model, bytes, NSFW_VISION_PROMPT, NSFW_AI_TIMEOUT_MS);
      const verdict = spare.error ? null : parseNsfwVerdict(spare.text);
      if (verdict) { verdicts.push({ model, verdict }); break; }
      errors.push({ model, reason: spare.error || "unparsed" });
    }
  }
  const captionText = caption.text || "";
  const captionHits = nsfwCaptionHits(captionText);
  const reasonHitsOf = (entry) => (entry && entry.verdict.reason ? nsfwCaptionHits(entry.verdict.reason) : []);
  // A model's "unsafe" only counts when its own reason names the content, when it refused to
  // describe the image, or when it answered the direct question - llava used to answer
  // "unsafe" to a plain logo.
  const isConfirmed = (entry) => {
    const verdict = entry.verdict;
    if (!verdict.nsfw) return false;
    if (verdict.direct) return true;
    if (/model refused/i.test(verdict.reason || "")) return true;
    if (reasonHitsOf(entry).length > 0) return true;
    return verdict.score >= 0.85 && !verdict.reason;
  };
  const flagged = verdicts.find(isConfirmed) || null;
  const chosen = flagged || verdicts[0] || null;
  const verdict = chosen ? chosen.verdict : null;
  const reasonHits = reasonHitsOf(chosen);
  if (!captionText && !chosen) {
    return {
      ok: false,
      unavailable: true,
      reason: "all-models-failed",
      errors: [{ model: NSFW_CAPTION_MODEL, reason: caption.error || "empty" }, ...errors],
      source: "site",
    };
  }
  const nsfw = captionHits.length > 0 || Boolean(flagged);
  const conflicting = Boolean(verdict && verdict.nsfw && !flagged);
  const rawScore = Math.max(captionHits.length ? 0.9 : 0, verdict ? verdict.score : 0);
  return {
    ok: true,
    nsfw,
    score: nsfw ? Math.max(rawScore, 0.8) : Math.min(rawScore, 0.3),
    labels: Array.from(new Set([...(captionHits || []), ...(reasonHits || []), verdict && verdict.reason].filter(Boolean))).slice(0, 4),
    reason: (verdict && verdict.reason) || (captionHits.length ? "caption: " + captionHits.join(", ") : ""),
    caption: captionText.slice(0, 160),
    model: (chosen ? chosen.model : "no-verdict").split("/").pop(),
    votes: verdicts.map(entry => ({ model: entry.model.split("/").pop(), nsfw: entry.verdict.nsfw, score: entry.verdict.score })),
    source: "site",
    // A missing or contradictory verdict means the image was allowed without a second
    // opinion, so it is worth a human look.
    review: !chosen || conflicting,
  };
}


async function classifyImageWithBot(env, url) {
  if (!url) return { ok: false, unavailable: true };
  try {
    const response = await fetch(`${BOT_API}/api/moderation/classify`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-User-ID": String(ADMIN_IDS[0] || ""),
        "X-User-Is-Admin": "true",
      },
      body: JSON.stringify({ url }),
      signal: AbortSignal.timeout(15000),
    });
    if (!response.ok) return { ok: false, unavailable: response.status === 404 || response.status === 503 };
    const data = await response.json().catch(() => null);
    if (!data || data.success !== true) return { ok: false, unavailable: Boolean(data && data.unavailable) };
    return { ok: true, nsfw: Boolean(data.nsfw), score: Number(data.score) || 0, labels: Array.isArray(data.labels) ? data.labels.slice(0, 5) : [] };
  } catch (_) {
    return { ok: false, unavailable: true };
  }
}

// Warnings are recorded by the moderation bot, so they land in the shared case log and
// count towards its three-strike timeout.
async function issueNsfwWarning(env, userId, reason) {
  const id = String(userId || "").trim();
  if (!/^\d{15,25}$/.test(id)) return { sent: false };
  try {
    const response = await fetch(`${BOT_API}/api/guild/members/warn`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-User-ID": String(ADMIN_IDS[0] || ""),
        "X-User-Is-Admin": "true",
        "X-User-Name": "Zyrex NSFW Filter",
      },
      body: JSON.stringify({ user_id: id, reason: String(reason || "NSFW content").slice(0, 300), send_dm: true }),
      signal: AbortSignal.timeout(9000),
    });
    const data = await response.json().catch(() => null);
    return { sent: response.ok && Boolean(data && data.success), warn_id: (data && data.warn_id) || "", total: Number(data && data.total_warns) || 0 };
  } catch (_) {
    return { sent: false };
  }
}

// One call decides what happens to flagged media: the object is dropped, the author is
// warned and the event is written to the moderation log.
async function handleNsfwMedia(env, options) {
  const settings = await readModerationSettings(env);
  const mode = String(settings.imageClassifier || "site").toLowerCase() === "bot" ? "bot" : "site";
  let result = mode === "site"
    ? await classifyImageOnSite(env, options.url)
    : { ok: false, unavailable: true, reason: "bot-mode", source: "bot" };
  // The VPS classifier is only a fallback now; it keeps uploads covered when Workers AI
  // is not enabled or a model misbehaves.
  if (!result.ok) {
    const fallback = await classifyImageWithBot(env, options.url).catch(() => ({ ok: false, unavailable: true }));
    if (fallback && fallback.ok) result = { ...fallback, source: "bot", model: "nudenet" };
  }
  if (!result.ok) {
    if (result.unavailable && settings.failOpen !== false) {
      await logModerationEvent(env, {
        kind: options.kind || "image",
        level: "review",
        user_id: String(options.userId || ""),
        url: String(options.url || ""),
        action: "allowed-review",
        reason: "classifier-unavailable",
        detail: result.reason || "",
        source: result.source || "",
      });
      return { blocked: false, review: true };
    }
    return { blocked: false, review: false };
  }
  if (!result.nsfw || result.score < Number(settings.imageThreshold || 0.6)) {
    // Only the fast caption answered, so the image is allowed but recorded for review.
    if (result.review) {
      await logModerationEvent(env, {
        kind: options.kind || "image",
        level: "review",
        user_id: String(options.userId || ""),
        url: String(options.url || ""),
        action: "allowed-review",
        reason: "caption-only",
        detail: String(result.caption || "").slice(0, 160),
        source: result.source || "",
        model: result.model || "",
      }).catch(() => false);
      return { blocked: false, review: true, score: result.score };
    }
    return { blocked: false, review: false, score: result.score };
  }
  if (options.deleteObject) await options.deleteObject().catch(() => false);
  // The member is told about the posting block together with the warning.
  const warnReason = options.penalty
    ? "NSFW image or video posted to the feed. Posting in the feed is blocked for 2 hours."
    : "NSFW image or video posted to the feed";
  const warning = settings.autoWarn === false ? { sent: false } : await issueNsfwWarning(env, options.userId, warnReason);
  await logModerationEvent(env, {
    kind: options.kind || "image",
    level: "nsfw",
    user_id: String(options.userId || ""),
    url: String(options.url || ""),
    score: result.score,
    labels: result.labels || [],
    action: settings.autoDelete === false ? "detected" : "blocked",
    source: result.source || "",
    model: result.model || "",
    reason: result.reason || "",
    warn_id: warning.warn_id || "",
    warn_sent: Boolean(warning.sent),
  });
  return { blocked: true, score: result.score };
}

// ── Verification (Worker-owned) ────────────────────────────────────────────────
// The verify bot on the VPS used to mint and consume these tokens, which made a stopped
// container a site-wide verification outage. Tokens, records and role changes now live in
// the Worker; the VPS is only used when no bot token is configured.
const VERIFY_TOKEN_PREFIX = "verify/pending/";
const VERIFY_RECORD_PREFIX = "verify/verified/";
const VERIFY_TOKEN_TTL_MS = 15 * 60 * 1000;
const VERIFY_ROLE_FALLBACK = "1519246304163659858";
const UNVERIFIED_ROLE_FALLBACK = "1519246300313423953";

function verifyRoleId(env) {
  return String((env && env.VERIFY_ROLE_ID) || VERIFY_ROLE_FALLBACK);
}

function unverifiedRoleId(env) {
  return String((env && (env.UNVERIFIED_ROLE_ID || env.VERIFY_UNVERIFIED_ROLE_ID)) || UNVERIFIED_ROLE_FALLBACK);
}

function verifyGuildId(env) {
  return String((env && env.GUILD_ID) || "1518954946110685184");
}

// A Discord snowflake carries its creation time; the verify page shows the account age.
function snowflakeToIso(id) {
  const value = String(id || "");
  if (!/^\d{15,25}$/.test(value)) return "";
  const timestamp = Number((BigInt(value) >> 22n) + 1420070400000n);
  return Number.isFinite(timestamp) ? new Date(timestamp).toISOString() : "";
}

// Every secret that may hold a bot token, in preference order. A token that Discord
// rejects is skipped instead of failing the whole call.
const DISCORD_TOKEN_SOURCES = [
  "DISCORD_BOT_TOKEN",
  "SITE_LOG_BOT_TOKEN",
  "ZYREX_BOT_TOKEN",
  "DISCORD_LOGGER_BOT_TOKEN",
  "LOGGER_BOT_TOKEN",
  "BOT_TOKEN",
];

function discordTokenCandidates(env) {
  const seen = new Set();
  const candidates = [];
  for (const name of DISCORD_TOKEN_SOURCES) {
    const token = String((env && env[name]) || "").trim();
    if (!token || seen.has(token)) continue;
    seen.add(token);
    candidates.push({ name, token });
  }
  return candidates;
}

// Token name that last worked, so warm requests skip the dead ones.
let discordPreferredToken = null;

function orderDiscordTokens(env) {
  const candidates = discordTokenCandidates(env);
  if (!discordPreferredToken) return candidates;
  const preferred = candidates.find(item => item.name === discordPreferredToken);
  if (!preferred) {
    discordPreferredToken = null;
    return candidates;
  }
  return [preferred, ...candidates.filter(item => item.name !== preferred.name)];
}

function rememberDiscordToken(name) {
  if (name && discordPreferredToken !== name) discordPreferredToken = name;
}

function forgetDiscordToken(name) {
  if (discordPreferredToken === name) discordPreferredToken = null;
}

function discordBotToken(env) {
  const first = discordTokenCandidates(env)[0];
  return first ? first.token : "";
}

async function discordRawGet(token, pathname, timeoutMs = 8000) {
  if (!token) return { ok: false, status: 0, body: null, reason: "no-token" };
  try {
    const response = await fetch(`${DISCORD_API}${pathname}`, {
      headers: { Authorization: `Bot ${token}` },
      signal: AbortSignal.timeout(timeoutMs),
    });
    const body = await response.json().catch(() => null);
    return {
      ok: response.ok,
      status: response.status,
      body,
      reason: response.ok ? "" : discordFailureReason(response.status, body),
    };
  } catch (error) {
    return { ok: false, status: 0, body: null, reason: "network", detail: error?.message || "network error" };
  }
}

// True when the Worker can do the whole verification itself.
function canVerifyLocally(env) {
  return Boolean(env && env.STORAGE && discordBotToken(env));
}

function verifyRecordKey(userId) {
  return `${VERIFY_RECORD_PREFIX}${String(userId || "")}.json`;
}

function clientIpAddress(request) {
  const candidates = [
    request.headers.get("CF-Pseudo-IPv4"),
    request.headers.get("CF-Connecting-IP"),
    ...(request.headers.get("X-Forwarded-For") || "").split(",").map(value => value.trim()),
    request.headers.get("X-Real-IP"),
    request.headers.get("True-Client-IP"),
  ].filter(Boolean);
  return candidates.find(value => /^\d{1,3}(\.\d{1,3}){3}$/.test(value)) || candidates[0] || "";
}

async function createVerifyToken(env, userId, ip, country) {
  const token = Array.from(crypto.getRandomValues(new Uint8Array(24)), byte => ("0" + byte.toString(16)).slice(-2)).join("");
  const record = {
    token,
    discord_id: String(userId),
    ip: String(ip || ""),
    country: String(country || ""),
    created_at: new Date().toISOString(),
  };
  const saved = await r2PutJSON(env, `${VERIFY_TOKEN_PREFIX}${token}.json`, record).catch(() => false);
  return saved ? token : "";
}

function verifyTokenKey(token) {
  return `${VERIFY_TOKEN_PREFIX}${String(token || "")}.json`;
}

// Reads the token without spending it. Spending it happened first before, so a single
// Discord hiccup burned the member's link and they had to start over.
async function readVerifyToken(env, token, userId) {
  if (!/^[a-f0-9]{16,96}$/i.test(String(token || ""))) return { error: "Invalid or expired token", status: 404 };
  const record = await r2GetJSON(env, verifyTokenKey(token), null).catch(() => null);
  if (!record) return { error: "Invalid or expired token", status: 404 };
  const created = Date.parse(record.created_at || "");
  if (!Number.isFinite(created) || Date.now() - created > VERIFY_TOKEN_TTL_MS) {
    await env.STORAGE.delete(verifyTokenKey(token)).catch(() => false);
    return { error: "This verification link has expired. Start again from the verify page.", status: 410 };
  }
  if (String(record.discord_id || "") !== String(userId || "")) {
    return { error: "This link belongs to a different account", status: 403 };
  }
  return { record };
}

// One-shot: called once Discord has answered, so a replay cannot verify twice.
async function consumeVerifyToken(env, token, userId) {
  const claimed = await readVerifyToken(env, token, userId);
  if (claimed.error) return claimed;
  await env.STORAGE.delete(verifyTokenKey(token)).catch(() => false);
  return claimed;
}


function discordFailureReason(status, body) {
  const code = body && body.code;
  if (status === 0) return "network";
  if (status === 401) return "invalid-token";
  if (status === 403) return code === 50013 ? "missing-permission" : "forbidden";
  if (status === 404) return "not-found";
  if (status === 429) return "rate-limited";
  return "discord-error";
}

// Every Discord call goes through here: one retry on a network error or a 5xx, a wait for
// 429, and the upstream status/body kept so failures can be explained instead of masked.
async function discordApiFetch(env, pathname, options = {}) {
  const candidates = orderDiscordTokens(env);
  if (!candidates.length) return { ok: false, status: 0, reason: "no-token", body: null, token_source: "none" };
  const method = options.method || "GET";
  const attempts = Number.isFinite(options.attempts) ? options.attempts : 2;
  // A member lookup answering 404 is a real answer (not in the guild), so it must not send
  // us hunting through other tokens; a 404 on any other path means "wrong bot", so it does.
  const notInGuildIsFinal = /\/members\/[^/]+$/.test(pathname);
  let last = { ok: false, status: 0, reason: "network", body: null, token_source: candidates[0].name };

  for (const candidate of candidates) {
    for (let attempt = 0; attempt < attempts; attempt += 1) {
      let response;
      try {
        response = await fetch(`${DISCORD_API}${pathname}`, {
          method,
          headers: {
            Authorization: `Bot ${candidate.token}`,
            ...(options.body ? { "Content-Type": "application/json" } : {}),
            ...(options.reason ? { "X-Audit-Log-Reason": encodeURIComponent(options.reason) } : {}),
          },
          body: options.body ? JSON.stringify(options.body) : undefined,
          signal: AbortSignal.timeout(options.timeoutMs || 10000),
        });
      } catch (error) {
        last = { ok: false, status: 0, reason: "network", detail: error?.message || "network error", body: null, token_source: candidate.name };
        continue;
      }
      const body = await response.json().catch(() => null);
      if (response.status === 429) {
        const retryAfter = Number(body && (body.retry_after ?? body.retryAfter)) || 0;
        const waitMs = Math.min(Math.max(retryAfter * 1000, 250), 2000);
        await new Promise(resolve => setTimeout(resolve, waitMs));
        last = { ok: false, status: 429, reason: "rate-limited", body, token_source: candidate.name };
        continue;
      }
      if (response.status >= 500) {
        last = { ok: false, status: response.status, reason: "discord-error", body, token_source: candidate.name };
        continue;
      }
      if (response.ok) {
        rememberDiscordToken(candidate.name);
        return { ok: true, status: response.status, body, reason: "", token_source: candidate.name };
      }
      last = {
        ok: false,
        status: response.status,
        reason: discordFailureReason(response.status, body),
        body,
        token_source: candidate.name,
      };
      if (response.status === 404 && notInGuildIsFinal) return last;
      if (response.status === 400) return last;
      // 401/403/404: this token cannot do the job, so the next one gets a turn.
      forgetDiscordToken(candidate.name);
      break;
    }
  }
  return last;
}

function verifyRolePath(env, userId) {
  return `/guilds/${verifyGuildId(env)}/members/${encodeURIComponent(userId)}`;
}

async function discordMember(env, userId) {
  const result = await discordApiFetch(env, verifyRolePath(env, userId));
  if (result.status === 404) return { ok: false, status: 404, reason: "not-in-guild", body: result.body };
  if (!result.ok) {
    return { ok: false, status: result.status, reason: result.reason || "member-fetch-failed", body: result.body };
  }
  return { ok: true, status: 200, member: result.body || null };
}

async function discordSetRole(env, userId, roleId, action) {
  if (!roleId) return { ok: false, status: 0, reason: "no-role" };
  const result = await discordApiFetch(
    env,
    `${verifyRolePath(env, userId)}/roles/${encodeURIComponent(roleId)}`,
    { method: action === "remove" ? "DELETE" : "PUT", reason: "Website verification" }
  );
  // Removing a role the member does not have answers 404; that is still success.
  return {
    ok: result.ok || (action === "remove" && result.status === 404),
    status: result.status,
    reason: result.reason,
    body: result.body,
  };
}

// The VPS bot runs on the same Discord application and holds a working token, so it is the
// fallback whenever the Worker's own token is rejected.
async function vpsVerifyStatus(env, userId) {
  try {
    const response = await fetch(`${VERIFY_BOT_API}/api/verify/status?userId=${encodeURIComponent(userId)}`, {
      signal: AbortSignal.timeout(9000),
    });
    const payload = await response.json().catch(() => null);
    if (!response.ok || !payload || payload.success === false) {
      return { ok: false, status: response.status, body: payload };
    }
    return {
      ok: true,
      status: response.status,
      verified: payload.verified === true,
      in_guild: payload.in_guild !== false,
      member: payload,
    };
  } catch (error) {
    return { ok: false, status: 0, reason: "network", detail: error?.message || "network error" };
  }
}

async function vpsAssignRole(env, userId, roleId, action) {
  if (!roleId) return { ok: false, status: 0, reason: "no-role" };
  try {
    const response = await fetch(`${VERIFY_BOT_API}/api/guild/members/role`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-User-Is-Admin": "true",
        "X-User-ID": String(ADMIN_IDS[0] || ""),
        "X-User-Name": "Zyrex website",
        // Used once BOT_SERVICE_TOKEN is configured on both sides; the VPS still accepts
        // the legacy header until then.
        ...(env.BOT_SERVICE_TOKEN ? { "X-Zyrex-Service": String(env.BOT_SERVICE_TOKEN) } : {}),
      },
      body: JSON.stringify({ user_id: String(userId), role_id: String(roleId), action }),
      signal: AbortSignal.timeout(12000),
    });
    const payload = await response.json().catch(() => null);
    return {
      ok: response.ok && (!payload || payload.success !== false),
      status: response.status,
      body: payload,
      reason: response.ok ? "" : "vps-rejected",
    };
  } catch (error) {
    return { ok: false, status: 0, reason: "network", detail: error?.message || "network error" };
  }
}

// Any of these mean "the Worker's own Discord credentials are unusable"; a plain 404 means
// the member really is not in the guild and must not be retried elsewhere.
function shouldFallBackToVps(failure) {
  if (!failure) return true;
  if (failure.status === 404) return false;
  const reason = failure.reason || "";
  return failure.status === 0 || failure.status === 401 || failure.status === 403 ||
    failure.status === 429 || failure.status >= 500 || reason === "no-token" ||
    reason === "invalid-token" || reason === "missing-permission" || reason === "forbidden" ||
    reason === "network" || reason === "discord-error" || reason === "rate-limited";
}

// One place that answers "is this member in the guild, and do they hold the role".
async function resolveMemberState(env, userId) {
  const lookup = await discordMember(env, userId);
  if (lookup.ok) {
    const roles = Array.isArray((lookup.member || {}).roles) ? lookup.member.roles.map(String) : [];
    return {
      ok: true,
      source: "discord",
      inGuild: true,
      verified: roles.includes(verifyRoleId(env)),
      member: lookup.member || {},
    };
  }
  if (lookup.reason === "not-in-guild") {
    return { ok: true, source: "discord", inGuild: false, verified: false, member: {}, failure: lookup };
  }
  if (!shouldFallBackToVps(lookup)) return { ok: false, source: "discord", failure: lookup };
  const vps = await vpsVerifyStatus(env, userId);
  if (vps.ok) {
    return {
      ok: true,
      source: "vps",
      inGuild: vps.in_guild !== false,
      verified: vps.verified === true,
      member: { user: { id: String(userId), global_name: (vps.member && vps.member.display_name) || "" } },
      failure: lookup,
    };
  }
  return { ok: false, source: "none", failure: lookup, vpsFailure: vps };
}

async function assignVerifyRole(env, userId) {
  const direct = await discordSetRole(env, userId, verifyRoleId(env), "add");
  if (direct.ok) return { ok: true, source: "discord" };
  if (!shouldFallBackToVps(direct)) return { ok: false, source: "discord", failure: direct };
  const viaVps = await vpsAssignRole(env, userId, verifyRoleId(env), "add");
  if (viaVps.ok) return { ok: true, source: "vps" };
  return { ok: false, source: "vps", failure: direct, vpsFailure: viaVps };
}

async function clearUnverifiedRole(env, userId) {
  const direct = await discordSetRole(env, userId, unverifiedRoleId(env), "remove");
  if (direct.ok) return { ok: true, source: "discord" };
  if (!shouldFallBackToVps(direct)) return { ok: false, source: "discord", failure: direct };
  const viaVps = await vpsAssignRole(env, userId, unverifiedRoleId(env), "remove");
  return { ok: viaVps.ok, source: "vps" };
}

// A member is verified as soon as Discord accepted the role call. When it did not, the
// record is queued so a cron run or the next status poll finishes the job.
const VERIFY_QUEUE_PREFIX = "verify/role-queue/";

function verifyQueueKey(userId) {
  return `${VERIFY_QUEUE_PREFIX}${String(userId || "")}.json`;
}

async function readRoleQueueEntry(env, userId) {
  if (!env?.STORAGE || !userId) return null;
  return r2GetJSON(env, verifyQueueKey(userId), null).catch(() => null);
}

async function enqueueRoleAssignment(env, userId, failure) {
  const previous = await readRoleQueueEntry(env, userId);
  const record = {
    user_id: String(userId || ""),
    role_id: verifyRoleId(env),
    queued_at: (previous && previous.queued_at) || new Date().toISOString(),
    attempts: (Number(previous && previous.attempts) || 0) + 1,
    last_attempt_at: new Date().toISOString(),
    last_status: (failure && failure.status) || 0,
    last_reason: (failure && failure.reason) || "",
  };
  await r2PutJSON(env, verifyQueueKey(userId), record).catch(() => false);
  return record;
}

async function dropRoleQueueEntry(env, userId) {
  if (!env?.STORAGE || !userId) return false;
  return env.STORAGE.delete(verifyQueueKey(userId)).then(() => true).catch(() => false);
}

async function retryQueuedRole(env, userId) {
  const entry = await readRoleQueueEntry(env, userId);
  if (!entry) return false;
  const added = await assignVerifyRole(env, userId);
  if (!added.ok) {
    await enqueueRoleAssignment(env, userId, added.failure || added.vpsFailure);
    return false;
  }
  await clearUnverifiedRole(env, userId).catch(() => false);
  await dropRoleQueueEntry(env, userId);
  await logModerationEvent(env, {
    kind: "verification",
    level: "info",
    user_id: String(userId),
    action: "verified-queued",
  }).catch(() => false);
  return true;
}

async function processVerifyQueue(env, limit = 25) {
  if (!canVerifyLocally(env)) return { processed: 0, verified: 0, remaining: 0 };
  const listed = await r2List(env, VERIFY_QUEUE_PREFIX).catch(() => []);
  const ids = (Array.isArray(listed) ? listed : [])
    .map(object => String((object && object.key) || "").replace(VERIFY_QUEUE_PREFIX, "").replace(/\.json$/, ""))
    .filter(id => /^\d{15,25}$/.test(id))
    .slice(0, limit);
  let verified = 0;
  for (const id of ids) {
    if (await retryQueuedRole(env, id)) verified += 1;
  }
  return { processed: ids.length, verified, remaining: Math.max(0, ids.length - verified) };
}

function verificationPayload(member, record, alreadyVerified) {
  const user = (member && member.user) || {};
  const joined = member && member.joined_at;
  return {
    success: true,
    verified: true,
    already_verified: Boolean(alreadyVerified),
    display_name: user.global_name || user.username || "",
    username: user.username || "",
    avatar: user.avatar || "",
    discord_created_at: user.id ? snowflakeToIso(user.id) : "",
    guild_joined_at: joined || "",
    verified_at: (record && (record.verified_at || record.created_at)) || new Date().toISOString(),
    country: (record && record.country_display) || (record && record.country) || "",
    source: "worker",
  };
}

// Verification runs here. Returns { handled, response } so the routes can fall back to the
// VPS when the Worker has no bot token.
async function completeVerificationLocally(env, request, session, token, ctx) {
  const claimed = await readVerifyToken(env, token, session.userId);
  if (claimed.error) {
    queueSecurityEvent(env, ctx, "verification", {
      level: claimed.status === 403 ? "alert" : "warn",
      title: claimed.status === 403 ? "Verification link used by another account" : "Verification link rejected",
      description: claimed.error,
      action: "verify-token-rejected",
      user_id: session.userId,
      user_name: session.displayName || session.username,
      ip: clientIpAddress(request),
    });
    return { handled: true, response: json({ success: false, error: claimed.error }, claimed.status) };
  }

  const state = await resolveMemberState(env, session.userId);
  if (!state.ok) {
    queueSecurityEvent(env, ctx, "verification", {
      level: "warn",
      title: "Verification deferred",
      description: "Discord could not be reached, so the link was kept and the member can retry.",
      action: "verify-discord-unreachable",
      user_id: session.userId,
      user_name: session.displayName || session.username,
      ip: String(claimed.record.ip || ""),
      country: String(claimed.record.country || ""),
    });
    // The link stays valid so the member can simply click it again.
    return {
      handled: true,
      response: json({
        success: false,
        retryable: true,
        error: "Discord could not be reached right now. Your verification link is still valid — please try again in a moment.",
      }, 503),
    };
  }
  if (state.inGuild === false) {
    queueSecurityEvent(env, ctx, "verification", {
      level: "warn",
      title: "Verification refused",
      description: "The member is not in the Discord server, so no role was assigned.",
      action: "verify-not-in-guild",
      user_id: session.userId,
      user_name: session.displayName || session.username,
      ip: String(claimed.record.ip || ""),
      country: String(claimed.record.country || ""),
    });
    return { handled: true, response: json({ success: false, error: "Join the Discord server first, then open the verification link again." }, 404) };
  }

  // Discord answered, so the link is spent from here on.
  await env.STORAGE.delete(verifyTokenKey(token)).catch(() => false);

  const member = state.member || {};
  const alreadyVerified = state.verified === true;
  let rolePending = false;
  if (!alreadyVerified) {
    const added = await assignVerifyRole(env, session.userId);
    if (added.ok) {
      await clearUnverifiedRole(env, session.userId).catch(() => false);
    } else {
      // Queued instead of failed: the member is verified and the role lands a moment later.
      rolePending = true;
      await enqueueRoleAssignment(env, session.userId, added.failure || added.vpsFailure);
      await logModerationEvent(env, {
        kind: "verification",
        level: "warn",
        user_id: String(session.userId),
        action: "role-queued",
        status: (added.failure && added.failure.status) || 0,
        reason: (added.failure && added.failure.reason) || "",
      }).catch(() => false);
      queueSecurityEvent(env, ctx, "verification", {
        level: "warn",
        title: "Verified role queued",
        description: "Discord refused the immediate role change; the assignment was queued and retried.",
        action: "verify-role-queued",
        user_id: session.userId,
        user_name: session.displayName || session.username,
        ip: String(claimed.record.ip || ""),
        country: String(claimed.record.country || ""),
        reason: (added.failure && (added.failure.reason || added.failure.status)) || "discord-error",
      });
    }
  }
  const record = {
    user_id: String(session.userId),
    verified_at: new Date().toISOString(),
    ip: String(claimed.record.ip || ""),
    country: String(claimed.record.country || ""),
  };
  await r2PutJSON(env, verifyRecordKey(session.userId), record).catch(() => false);
  await logModerationEvent(env, {
    kind: "verification",
    level: "info",
    user_id: String(session.userId),
    action: alreadyVerified ? "verified-already" : "verified",
  }).catch(() => false);
  queueSecurityEvent(env, ctx, "verification", {
    level: alreadyVerified ? "info" : "success",
    title: alreadyVerified ? "Member was already verified" : "Member verified",
    description: alreadyVerified
      ? "The verified role was already present; the verification record was refreshed."
      : "The verified role was granted and the unverified role removed.",
    action: alreadyVerified ? "verify-already" : "verify-granted",
    user_id: session.userId,
    user_name: session.displayName || session.username,
    ip: record.ip,
    country: record.country,
    access: rolePending ? "Verified • role assignment pending" : "Verified",
  });
  return {
    handled: true,
    response: json(
      { ...verificationPayload(member, record, alreadyVerified), role_pending: rolePending },
      200,
      { "Cache-Control": "no-store" }
    ),
  };
}

async function verificationStatusLocally(env, userId) {
  const record = await r2GetJSON(env, verifyRecordKey(userId), null).catch(() => null);
  const state = await resolveMemberState(env, userId);
  if (!state.ok && !record) {
    // Never a hard error: the page keeps working while Discord is unreachable.
    return json({
      success: true,
      verified: false,
      role_pending: false,
      discord_reachable: false,
      error: "Discord is not reachable right now. Try again in a moment.",
    }, 200, { "Cache-Control": "no-store" });
  }
  if (state.ok && state.inGuild === false && !record) {
    return json({ success: false, verified: false, error: "Join the Discord server first." }, 200, { "Cache-Control": "no-store" });
  }
  const member = state.member || {};
  let verified = state.verified === true;
  if (!verified && state.ok) {
    // A queued role assignment gets another chance on every poll.
    verified = await retryQueuedRole(env, userId).catch(() => false);
  }
  if (!verified) {
    const queued = await readRoleQueueEntry(env, userId).catch(() => null);
    // A stored verification record proves the member already finished the flow.
    // If the role is still missing (Discord refused the write, a permission
    // change, or a role granted before this system existed), sending them back
    // to "Complete verification" is a dead end: only the bot can fix the role.
    // Try once more, then report the member as verified with the role pending.
    if (record && state.ok && state.inGuild !== false) {
      // Do not hammer Discord on every poll: one attempt per 30 seconds at most.
      const lastAttempt = Date.parse((queued && queued.last_attempt_at) || "") || 0;
      const throttled = lastAttempt && (Date.now() - lastAttempt) < 30000;
      const added = throttled ? null : await assignVerifyRole(env, userId).catch(() => ({ ok: false }));
      if (added && added.ok) {
        await clearUnverifiedRole(env, userId).catch(() => false);
        addUserToRoleSnapshot(env, verifyRoleId(env), userId).catch(() => {});
        return json(
          { ...verificationPayload(member, record, true), role_pending: false },
          200,
          { "Cache-Control": "no-store" }
        );
      }
      if (!throttled) {
        const failure = (added && (added.failure || added.vpsFailure)) || {};
        await enqueueRoleAssignment(env, userId, failure).catch(() => false);
        await logModerationEvent(env, {
          kind: "verification",
          level: "warn",
          user_id: String(userId),
          action: "role-retry-failed",
          status: failure.status || 0,
          reason: failure.reason || "",
        }).catch(() => false);
      }
      return json(
        { ...verificationPayload(member, record, true), role_pending: true },
        200,
        { "Cache-Control": "no-store" }
      );
    }
    return json({
      success: true,
      verified: false,
      role_pending: Boolean(queued),
      display_name: (member.user && (member.user.global_name || member.user.username)) || "",
      discord_created_at: member.user && member.user.id ? snowflakeToIso(member.user.id) : "",
      guild_joined_at: member.joined_at || "",
      verified_at: (record && record.verified_at) || "",
      source: state.source || "worker",
    }, 200, { "Cache-Control": "no-store" });
  }
  return json(verificationPayload(member, record, true), 200, { "Cache-Control": "no-store" });
}

// ── Background media scan ──────────────────────────────────────────────────────
// Uploads answer immediately and the classifier runs afterwards; posting stays locked until
// every attachment is clear. The uploader is never told that a check happened.
const MEDIA_SCAN_PREFIX = "media-scans/";
const FEED_BAN_PREFIX = "feed-bans/";
const FEED_BAN_MS = 2 * 60 * 60 * 1000;
const MEDIA_SCAN_TTL_MS = 24 * 60 * 60 * 1000;

function mediaScanId(url) {
  const name = String(url || "").split("?")[0].split("/").pop();
  return /^[A-Za-z0-9._-]{4,120}$/.test(name) ? name : "";
}

function mediaScanKey(url) {
  const id = mediaScanId(url);
  return id ? `${MEDIA_SCAN_PREFIX}${id}.json` : "";
}

async function readMediaScan(env, url) {
  const key = mediaScanKey(url);
  if (!key || !env?.STORAGE) return null;
  return r2GetJSON(env, key, null).catch(() => null);
}

async function writeMediaScan(env, url, patch) {
  const key = mediaScanKey(url);
  if (!key || !env?.STORAGE) return null;
  const current = await r2GetJSON(env, key, null).catch(() => null);
  const record = { ...(current || {}), ...patch, url: String(url || ""), updated_at: new Date().toISOString() };
  const saved = await r2PutJSON(env, key, record).catch(() => false);
  return saved ? record : null;
}

// pending | clean | blocked | missing (unknown or expired).
async function mediaScanState(env, url) {
  const record = await readMediaScan(env, url);
  if (!record) return "missing";
  const state = String(record.state || "missing");
  if (state === "pending") {
    const age = Date.now() - Date.parse(record.updated_at || record.at || "");
    if (Number.isFinite(age) && age > MEDIA_SCAN_TTL_MS) return "missing";
  }
  return state;
}

function feedBanKey(userId) {
  return `${FEED_BAN_PREFIX}${String(userId || "")}.json`;
}

async function readFeedBan(env, userId) {
  if (!env?.STORAGE || !userId) return null;
  const record = await r2GetJSON(env, feedBanKey(userId), null).catch(() => null);
  const until = Date.parse((record && record.until) || "");
  if (!Number.isFinite(until) || until <= Date.now()) return null;
  return record;
}

async function applyFeedBan(env, userId, reason) {
  const until = new Date(Date.now() + FEED_BAN_MS).toISOString();
  await r2PutJSON(env, feedBanKey(userId), {
    user_id: String(userId || ""),
    at: new Date().toISOString(),
    until,
    reason: String(reason || "nsfw-upload"),
  }).catch(() => false);
  return until;
}

// Runs the classifier for one uploaded object and records the outcome. Blocked media is
// deleted, the author gets a two hour feed ban and the bot warning fires.
async function scanUploadedMedia(env, options) {
  const url = String((options && options.url) || "");
  const userId = String((options && options.userId) || "");
  if (!url) return { blocked: false };
  let guard;
  try {
    guard = await handleNsfwMedia(env, {
      userId,
      url,
      kind: (options && options.kind) || "upload",
      deleteObject: options && options.deleteObject,
      // Uploads are followed by the two hour posting block, so the warning says so.
      penalty: true,
    });
  } catch (_) {
    guard = { blocked: false, review: true };
  }
  if (guard && guard.blocked) {
    await writeMediaScan(env, url, { state: "blocked", user_id: userId }).catch(() => null);
    await applyFeedBan(env, userId, "nsfw-upload").catch(() => false);
    return { blocked: true };
  }
  await writeMediaScan(env, url, { state: "clean", user_id: userId, review: Boolean(guard && guard.review) }).catch(() => null);
  return { blocked: false };
}

function runInBackground(ctx, task) {
  const promise = Promise.resolve(task).catch(() => null);
  if (ctx && typeof ctx.waitUntil === "function") ctx.waitUntil(promise);
  return promise;
}

// ── Video frame scan ───────────────────────────────────────────────────────────
// A Worker cannot decode video, so the composer extracts a poster and a 2x3 contact sheet of
// frames and the Worker classifies those. The scan issues a one-shot ticket that the video
// upload must present, so a video cannot be uploaded without being checked first.
const VIDEO_SCAN_MAX_BYTES = 2 * 1024 * 1024;

function imageDataUrlBytes(value, limit) {
  const match = /^data:image\/(?:png|jpe?g|webp);base64,([A-Za-z0-9+/=\s]+)$/i.exec(String(value || ""));
  if (!match) return null;
  const encoded = match[1].replace(/\s+/g, "");
  if (Math.floor(encoded.length * 3 / 4) > limit) return null;
  try { return Uint8Array.from(atob(encoded), char => char.charCodeAt(0)); } catch (_) { return null; }
}

// Short links when the post has a number, the legacy uuid page otherwise.
function feedPostUrl(post) {
  const seq = Number(post && post.seq);
  if (Number.isFinite(seq) && seq > 0) return `https://zyrexediting.xyz/feed/post/${seq}`;
  return `https://zyrexediting.xyz/post/${post && post.id ? post.id : ""}`;
}

// One link button under the announcement, pointing at the post on the site.
function feedPostButton(post) {
  const url = feedPostUrl(post);
  if (!url) return undefined;
  return [{ type: 1, components: [{ type: 2, style: 5, label: "Open on Zyrex", url }] }];
}

function feedPostSocialKey(post) {
  return socialInteractionKey("post", String(post && post.id || ""), String(post && post.author_id || ""));
}

function feedEmbedCountFields(post) {
  return [
    { name: "❤️ Likes", value: "0", inline: true },
    { name: "👁️ Views", value: "0", inline: true },
    { name: "💬 Replies", value: "0", inline: true },
    { name: "Open on Zyrex", value: `[View this post](${feedPostUrl(post)})`, inline: false },
  ];
}

function feedInteractionCounts(row) {
  const safe = row || {};
  return {
    likes: Array.isArray(safe.likes) ? safe.likes.length : 0,
    views: Number(safe.view_count) || 0,
    replies: Array.isArray(safe.replies) ? safe.replies.length : 0,
  };
}

function applyFeedCounts(fields, counts) {
  const next = Array.isArray(fields) ? fields.map(field => ({ ...field })) : [];
  const labels = { "❤️ Likes": counts.likes, "👁️ Views": counts.views, "💬 Replies": counts.replies };
  return next.map(field => (field && labels[field.name] !== undefined ? { ...field, value: String(labels[field.name]) } : field));
}

function buildFeedPostEmbed(post, counts) {
  const poster = feedNotificationPoster(post);
  const videoPoster = post && post.video && post.video.poster ? proxiedMediaUrl(post.video.poster) : "";
  const media = videoPoster || (Array.isArray(post && post.media) ? post.media : []).map(proxiedMediaUrl).filter(Boolean)[0] || "";
  return {
    author: {
      name: `${poster.name}${poster.handle ? ` (@${poster.handle})` : ""}`.slice(0, 240),
      icon_url: absoluteMediaUrl(poster.avatar),
    },
    description: feedNotificationText(post).slice(0, 600),
    color: 0xff2b52,
    url: feedPostUrl(post),
    ...(media ? { image: { url: media } } : {}),
    fields: applyFeedCounts(feedEmbedCountFields(post), counts),
    footer: { text: "Zyrex feed · live counters" },
    timestamp: String(post.created_at || new Date().toISOString()),
  };
}

// The public timeline keeps one object per post keyed by `<created>-<author>-<post>`,
// so a single post can be loaded without scanning every profile document.
async function findFeedPostEntry(env, postId) {
  const id = String(postId || "").trim();
  if (!/^[a-f0-9-]{16,40}$/i.test(id) || !env?.STORAGE) return null;
  try {
    const files = await r2List(env, "profiles/feed/");
    const suffix = `-${id.toLowerCase()}.json`;
    const match = (files || []).find(file => String(file && file.key || "").toLowerCase().endsWith(suffix));
    if (!match) return null;
    const entry = await r2GetJSON(env, match.key, null);
    if (!entry || !entry.post) return null;
    return entry;
  } catch (_) {
    return null;
  }
}

async function readFeedMessageRecord(env, postId) {  try {
    const stored = await r2GetJSON(env, feedMessageKey(postId), null);
    if (!stored || !stored.message_id) return null;
    return stored;
  } catch (_) {
    return null;
  }
}

async function readFeedPostCounts(env, post) {
  try {
    // Upload announcements show the leak's own numbers, not a separate post counter.
    const productId = String((post && post.product_id) || "").trim()
      || (post && post.kind === "resource_notice" ? await resolveNoticeProductId(env, post.id) : "");
    if (productId) {
      const summary = await leakInteractionSummary(env, productId, "", false);
      return { likes: summary.likes, views: summary.views, replies: summary.replies };
    }
    const row = sanitizeSocialInteraction(await r2GetJSON(env, feedPostSocialKey(post), null) || emptySocialInteraction());
    return feedInteractionCounts(row);
  } catch (_) {
    return { likes: 0, views: 0, replies: 0 };
  }
}

// Discord announcement for a member feed post. Mentioned members are pinged through
// allowed_mentions, so nobody else in the channel gets a notification. Reposts and
// anything that is not a written post are skipped, which keeps generated resource
// notices out of the channel entirely.
// ── Discord feed card ─────────────────────────────────────────────────────────
// The announcement is an image rather than an embed, so the channel shows the post
// the way the site does. Everything is rendered inside the Worker.
// Twemoji ships a PNG per emoji; the first card that uses one caches it in R2 so later
// renders read from our own CDN instead of a public mirror.
const TWEMOJI_BASE = "https://cdn.jsdelivr.net/gh/twitter/twemoji@14.0.2/assets/72x72";

async function emojiImageDataUrl(env, emoji, cache) {
  const key = String(emoji || "");
  if (!key) return "";
  if (cache && cache.has(key)) return cache.get(key);
  const codes = twemojiCodes(key);
  if (!codes.length) return "";
  let dataUrl = "";
  for (const code of codes) {
    if (!env?.STORAGE) break;
    const stored = await env.STORAGE.get(`emoji/${code}.png`).catch(() => null);
    if (!stored) continue;
    const bytes = new Uint8Array(await stored.arrayBuffer());
    if (bytes.length) { dataUrl = `data:image/png;base64,${bytesToBase64(bytes)}`; break; }
  }
  if (!dataUrl) {
    for (const code of codes) {
      const response = await fetch(`${TWEMOJI_BASE}/${code}.png`, { signal: AbortSignal.timeout(6000) }).catch(() => null);
      if (!response || !response.ok) continue;
      const bytes = new Uint8Array(await response.arrayBuffer());
      if (!bytes.length || bytes.length > 120 * 1024) continue;
      await env.STORAGE.put(`emoji/${code}.png`, bytes, { httpMetadata: { contentType: "image/png" } }).catch(() => false);
      dataUrl = `data:image/png;base64,${bytesToBase64(bytes)}`;
      break;
    }
  }
  if (cache) cache.set(key, dataUrl);
  return dataUrl;
}

const FEED_CARD_AVATAR_LIMIT = 400 * 1024;
const FEED_CARD_MEDIA_LIMIT = 2 * 1024 * 1024;

function bytesToBase64(bytes) {
  let binary = "";
  const chunk = 0x8000;
  for (let index = 0; index < bytes.length; index += chunk) {
    binary += String.fromCharCode.apply(null, bytes.subarray(index, index + chunk));
  }
  return btoa(binary);
}

// Profile photos are served through this Worker; the Worker cannot fetch itself, so the
// Discord CDN is addressed directly from the stored avatar hash.
function discordAvatarCdn(value) {
  const match = /^\/api\/avatar\/(\d{15,25})\/([A-Za-z0-9_]+)\.(png|gif)(?:\?.*)?$/.exec(String(value || ""));
  if (!match) return "";
  return `https://cdn.discordapp.com/avatars/${match[1]}/${match[2]}.${match[3]}?size=160`;
}

async function fetchImageBytes(env, value, limit, options = {}) {
  const raw = String(value || "").trim();
  const direct = /^https:\/\/thumbnail\.zyrexediting\.xyz\//i.test(raw);
  const target = raw.startsWith("/api/avatar/") ? discordAvatarCdn(raw) : absoluteMediaUrl(raw);
  // Our own bucket is read from R2, because a Worker cannot reliably fetch its own host.
  if (direct && env?.STORAGE) {
    try {
      const key = "thumbnails/" + decodeURIComponent(new URL(raw).pathname.replace(/^\/+/, ""));
      const object = await env.STORAGE.get(key);
      if (!object) return null;
      const bytes = new Uint8Array(await object.arrayBuffer());
      if (!bytes.length || bytes.length > limit) return null;
      const type = String((object.httpMetadata && object.httpMetadata.contentType) || "image/jpeg").toLowerCase();
      if (!/^image\/(?:png|jpe?g|webp|gif)$/.test(type)) return null;
      return { bytes, type };
    } catch (_) {
      return null;
    }
  }
  if (!target || !/^https:\/\//i.test(target)) return null;
  const candidates = [target];
  const remote = remoteMediaHost(target);
  if (remote && remote.alternate) {
    const alternate = new URL(target);
    alternate.hostname = remote.alternate(alternate.hostname);
    if (alternate.hostname !== new URL(target).hostname) candidates.push(alternate.toString());
  }
  for (const candidate of candidates) {
    try {
      const response = await fetch(candidate, {
        headers: { Accept: "image/*", Referer: remote && remote.referer ? remote.referer : "https://zyrexediting.xyz/" },
        signal: AbortSignal.timeout(options.timeout || 5000),
      });
      if (!response.ok) continue;
      const type = String(response.headers.get("Content-Type") || "").toLowerCase();
      if (!/^image\/(?:png|jpe?g|webp|gif)$/.test(type)) continue;
      const bytes = new Uint8Array(await response.arrayBuffer());
      if (!bytes.length || bytes.length > limit) continue;
      return { bytes, type };
    } catch (_) {
      continue;
    }
  }
  return null;
}

async function fetchImageAsDataUrl(env, value, limit) {
  const image = await fetchImageBytes(env, value, limit);
  return image ? `data:${image.type};base64,${bytesToBase64(image.bytes)}` : "";
}

// {author} · {text} · {counts} baked into one PNG, or a GIF when the media animates.
async function buildFeedCardAttachment(env, post, counts) {
  const poster = feedNotificationPoster(post);
  const seq = Number(post && post.seq) || 0;
  const path = seq > 0 ? `/feed/post/${seq}` : `/post/${String(post && post.id || "")}`;
  // A video post contributes its poster frame; the card then gets a play badge.
  const video = post && post.video && post.video.url ? post.video : null;
  const mediaUrl = video ? String(video.poster || "") : ((post && Array.isArray(post.media) ? post.media : [])[0] || "");
  const [avatar, media] = await Promise.all([
    fetchImageAsDataUrl(env, poster.avatar, FEED_CARD_AVATAR_LIMIT),
    mediaUrl ? fetchImageBytes(env, mediaUrl, FEED_CARD_MEDIA_LIMIT, { timeout: 7000 }) : Promise.resolve(null),
  ]);
  const emojiCache = new Map();
  return renderFeedCardAttachment({
    emoji: emoji => emojiImageDataUrl(env, emoji, emojiCache),
    video: Boolean(video && mediaUrl),
    author: {
      name: poster.name,
      handle: poster.handle,
      avatar,
      is_admin: Boolean(post && post.author && post.author.is_admin) || ADMIN_IDS.includes(String(post && post.author_id || "")),
    },
    text: feedCardText(post),
    media,
    footer: `zyrexediting.xyz · ${path}`.slice(0, 80),
    counts,
  }, cardAssets);
}

// Atlassian-style multipart upload: Discord only accepts an attachment this way.
async function sendFeedCardMessage(env, options) {
  const { channelId, token, post, counts, buttons, roleIds, content } = options;
  const pingIds = Array.isArray(options.pingIds) ? options.pingIds : [];
  const roles = Array.from(new Set((roleIds || []).map(String).filter(id => /^\d{17,20}$/.test(id)))).slice(0, 3);
  const card = await buildFeedCardAttachment(env, post, counts);
  if (!card || !card.bytes || !card.bytes.length) return false;
  const filename = `post.${card.extension || "png"}`;
  const payload = {
    attachments: [{ id: 0, filename, description: feedCardText(post).slice(0, 120) || "Zyrex feed post" }],
    allowed_mentions: { parse: [], users: pingIds, roles },
    // The card is an image, so link buttons are the only way into the site.
    components: buttons || feedPostButton(post),
  };
  const roleMentions = roles.map(id => `<@&${id}>`).join(" ");
  if (roleMentions) payload.content = `${roleMentions} ${content || "New leak dropped!"}`;
  else if (pingIds.length) payload.content = `${pingIds.map(id => `<@${id}>`).join(" ")} you were mentioned in a new post`;
  const form = new FormData();
  form.append("payload_json", JSON.stringify(payload));
  form.append("files[0]", new Blob([card.bytes], { type: card.contentType || "image/png" }), filename);
  const response = await fetch(`${DISCORD_API}/channels/${channelId}/messages`, {
    method: "POST",
    headers: { Authorization: `Bot ${token}` },
    body: form,
    signal: AbortSignal.timeout(15000),
  });
  if (!response.ok) {
    console.warn("Feed Discord card failed:", response.status, String(await response.text().catch(() => "")).slice(0, 200));
    return false;
  }
  const message = await response.json().catch(() => null);
  const messageId = String((message && message.id) || "");
  if (!messageId) return false;
  await r2PutJSON(env, feedMessageKey(post.id), {
    version: 1,
    post_id: post.id,
    author_id: String(post.author_id || ""),
    channel_id: channelId,
    message_id: messageId,
    card: true,
    counts,
    edited_at: Date.now(),
  }).catch(() => false);
  return true;
}
async function postFeedPostToDiscord(env, post, mentionIds = []) {
  const token = getSiteLogBotToken(env);
  if (!token || !post || !post.id || post.repost_of) return false;
  if (post.kind === "resource" || post.notice === true) return false;
  const channelId = String((env && env.FEED_CHANNEL_ID) || FEED_DISCORD_CHANNEL_ID);
  const poster = feedNotificationPoster(post);
  const pingIds = Array.from(new Set((mentionIds || []).map(String).filter(id => /^\d{17,20}$/.test(id)))).slice(0, 5);
  const counts = await readFeedPostCounts(env, post);
  // The rendered card is the announcement; the embed remains only as a fallback.
  try {
    const card = await sendFeedCardMessage(env, { channelId, token, post, counts, pingIds }).catch(() => false);
    if (card) {
      await recordFeedDiscordHealth(env, true, "posted");
      return true;
    }
    const embed = buildFeedPostEmbed(post, counts);
    const payload = {
      embeds: [embed],
      allowed_mentions: { parse: [], users: pingIds },
      components: feedPostButton(post),
    };
    if (pingIds.length) payload.content = `${pingIds.map(id => `<@${id}>`).join(" ")} you were mentioned in a new post`;
    const response = await fetch(`${DISCORD_API}/channels/${channelId}/messages`, {
      method: "POST",
      headers: { Authorization: `Bot ${token}`, "Content-Type": "application/json" },
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(4000),
    });
    if (!response.ok) {
      console.warn("Feed Discord announce failed:", response.status);
      await recordFeedDiscordHealth(env, false, `HTTP ${response.status}`);
      return false;
    }
    const message = await response.json().catch(() => null);
    const messageId = String((message && message.id) || "");
    if (messageId) {
      // Storing the message keeps the counters updatable for the life of the post.
      await r2PutJSON(env, feedMessageKey(post.id), {
        version: 1,
        post_id: post.id,
        author_id: String(post.author_id || ""),
        channel_id: channelId,
        message_id: messageId,
        embed,
        counts,
        edited_at: Date.now(),
      }).catch(() => false);
    }
    await recordFeedDiscordHealth(env, true, "posted");
    return true;
  } catch (error) {
    console.warn("Feed Discord announce error:", error?.message || String(error));
    await recordFeedDiscordHealth(env, false, error?.message || String(error));
    return false;
  }
}

// Edits the announcement so likes/views/replies stay current. Coalesced per window
// because Discord rate-limits message edits.
async function refreshFeedDiscordMessage(env, postId, options = {}) {
  const token = getSiteLogBotToken(env);
  if (!token) return false;
  const record = await readFeedMessageRecord(env, postId).catch(() => null);
  if (!record || !record.message_id) return false;
  // Image announcements carry a snapshot of the counters, so there is nothing to patch.
  if (record.card === true) return false;
  if (!options.force && Date.now() - Number(record.edited_at || 0) < FEED_MESSAGE_EDIT_MIN_MS) return false;
  const counts = await readFeedPostCounts(env, { id: record.post_id, author_id: record.author_id, product_id: record.product_id });
  const embed = { ...(record.embed || {}), fields: applyFeedCounts(record.embed && record.embed.fields, counts) };
  try {
    const response = await fetch(`${DISCORD_API}/channels/${record.channel_id}/messages/${record.message_id}`, {
      method: "PATCH",
      headers: { Authorization: `Bot ${token}`, "Content-Type": "application/json" },
      body: JSON.stringify({ embeds: [embed] }),
      signal: AbortSignal.timeout(4000),
    });
    if (!response.ok) {
      // 429/404: stop trying rather than hammering the API.
      if (response.status !== 429) console.warn("Feed Discord counter update failed:", response.status);
      return false;
    }
    await r2PutJSON(env, feedMessageKey(record.post_id), {
      ...record,
      embed,
      counts,
      edited_at: Date.now(),
    }).catch(() => false);
    return true;
  } catch (error) {
    console.warn("Feed Discord counter update error:", error?.message || String(error));
    return false;
  }
}

// Ensures a counter change reaches Discord even when it lands inside the edit window.
async function scheduleFeedDiscordRefresh(env, postId) {
  if (await refreshFeedDiscordMessage(env, postId)) return true;
  await new Promise(resolve => setTimeout(resolve, FEED_MESSAGE_EDIT_MIN_MS + 500));
  return refreshFeedDiscordMessage(env, postId, { force: true });
}

async function deleteFeedDiscordMessage(env, postId) {
  const token = getSiteLogBotToken(env);
  if (!token) return false;
  const record = await readFeedMessageRecord(env, postId).catch(() => null);
  if (!record || !record.message_id) return false;
  try {
    await fetch(`${DISCORD_API}/channels/${record.channel_id}/messages/${record.message_id}`, {
      method: "DELETE",
      headers: { Authorization: `Bot ${token}` },
      signal: AbortSignal.timeout(4000),
    });
  } catch (_) {
    // The post is gone either way; a stale message is not worth failing the request.
  }
  await env.STORAGE.delete(feedMessageKey(postId)).catch(() => false);
  return true;
}

// Fans a new post out to the members who should hear about it.
// Followers may also be told through Discord. The bot opens a DM channel per member
// and caches it, so a burst of posts does not create the channel every time.
const FEED_DM_LIMIT_PER_POST = 55;
const dmChannelMemo = new Map();

async function openDiscordDMChannel(env, userId) {
  const token = getSiteLogBotToken(env);
  const id = String(userId || "").trim();
  if (!token || !/^\d{15,25}$/.test(id)) return "";
  const cached = dmChannelMemo.get(id);
  if (cached && Date.now() < cached.expires) return cached.channelId;
  try {
    const response = await fetch(`${DISCORD_API}/users/@me/channels`, {
      method: "POST",
      headers: { Authorization: `Bot ${token}`, "Content-Type": "application/json" },
      body: JSON.stringify({ recipient_id: id }),
      signal: AbortSignal.timeout(4000),
    });
    if (!response.ok) return "";
    const channel = await response.json().catch(() => null);
    const channelId = String((channel && channel.id) || "");
    if (channelId) dmChannelMemo.set(id, { channelId, expires: Date.now() + 10 * 60 * 1000 });
    return channelId;
  } catch (_) {
    return "";
  }
}

async function sendFeedPostDM(env, userId, post, poster) {
  const token = getSiteLogBotToken(env);
  const channelId = await openDiscordDMChannel(env, userId);
  if (!token || !channelId) return false;
  const embed = {
    author: {
      name: `${poster.name}${poster.handle ? ` (@${poster.handle})` : ""}`.slice(0, 240),
      icon_url: absoluteMediaUrl(poster.avatar),
    },
    title: "New post from someone you follow",
    description: feedNotificationText(post).slice(0, 600),
    color: 0xff2b52,
    url: feedPostUrl(post),
    footer: { text: "Zyrex feed · turn this off in settings" },
    timestamp: String(post.created_at || new Date().toISOString()),
  };
  const media = (Array.isArray(post.media) ? post.media : []).map(proxiedMediaUrl).filter(Boolean)[0] || "";
  if (media) embed.image = { url: media };
  try {
    const response = await fetch(`${DISCORD_API}/channels/${channelId}/messages`, {
      method: "POST",
      headers: { Authorization: `Bot ${token}`, "Content-Type": "application/json" },
      body: JSON.stringify({ embeds: [embed], allowed_mentions: { parse: [] } }),
      signal: AbortSignal.timeout(4000),
    });
    if (response.status === 403) dmChannelMemo.delete(String(userId));
    return response.ok;
  } catch (_) {
    return false;
  }
}

// A heartbeat is written every time a Discord mirror is posted or refreshed, which is
// the only honest way to know that side of the feed is still working.
const FEED_DISCORD_HEALTH_KEY = "database/feed_discord_health.json";

async function recordFeedDiscordHealth(env, ok, detail = "") {
  await r2PutJSON(env, FEED_DISCORD_HEALTH_KEY, {
    at: Date.now(),
    ok: ok === true,
    detail: String(detail || "").slice(0, 200),
  }).catch(() => false);
}

// Every feed component is measured for real: storage listings, the Discord heartbeat,
// the notification outbox, the media proxy and the short-link index.
async function probeFeedHealth(env) {
  const out = {
    timeline: { status: "operational", latency: null, detail: "" },
    discord: { status: "operational", latency: null, detail: "" },
    notifications: { status: "operational", latency: null, detail: "" },
    media: { status: "operational", latency: null, detail: "" },
    official: { status: "operational", latency: null, detail: "" },
    links: { status: "operational", latency: null, detail: "" },
  };
  const age = stamp => {
    const value = Number(stamp) || 0;
    if (!value) return Infinity;
    return Math.max(0, Date.now() - value);
  };

  const timelineStart = Date.now();
  try {
    const files = await r2List(env, "profiles/feed/");
    const newest = (files || []).reduce((max, file) => {
      const match = /(\d{13})-/.exec(String(file && file.key || ""));
      return match ? Math.max(max, Number(match[1])) : max;
    }, 0);
    out.timeline.latency = Date.now() - timelineStart;
    out.timeline.detail = `${(files || []).length} posts`;
    if (newest && age(newest) > 14 * 24 * 60 * 60 * 1000) out.timeline.status = "degraded";
  } catch (_) {
    out.timeline.status = "outage";
    out.timeline.latency = Date.now() - timelineStart;
  }

  const discordStart = Date.now();
  try {
    const beat = await r2GetJSON(env, FEED_DISCORD_HEALTH_KEY, null);
    out.discord.latency = Date.now() - discordStart;
    if (!beat) out.discord.detail = "no mirror yet";
    else if (beat.ok !== true) out.discord.status = age(beat.at) < 60 * 60 * 1000 ? "degraded" : "operational";
    else out.discord.detail = "channel synced";
  } catch (_) {
    out.discord.status = "degraded";
  }

  const notifyStart = Date.now();
  try {
    const files = await r2List(env, "database/feed_notifications/");
    out.notifications.latency = Date.now() - notifyStart;
    out.notifications.detail = `${(files || []).length} inboxes`;
  } catch (_) {
    out.notifications.status = "degraded";
  }

  const mediaStart = Date.now();
  try {
    const sample = "https://media.giphy.com/media/3o7aD2saalBwwftBIY/giphy.gif";
    const allowed = Boolean(sanitizeRemoteMediaUrl(sample));
    const response = await fetch(sample, {
      headers: { "User-Agent": "Mozilla/5.0 (compatible; ZyrexMediaProxy/1.0)", Accept: "image/*" },
      signal: AbortSignal.timeout(2500),
    });
    out.media.latency = Date.now() - mediaStart;
    const type = String(response.headers.get("Content-Type") || "");
    if (!allowed || !response.ok || !/^image\//i.test(type)) out.media.status = "degraded";
  } catch (_) {
    out.media.status = "degraded";
    out.media.latency = Date.now() - mediaStart;
  }

  const officialStart = Date.now();
  try {
    const identity = await resolveZyrexProfile(env);
    out.official.latency = Date.now() - officialStart;
    if (!identity) out.official.status = "outage";
    else out.official.detail = "@" + identity.handle;
  } catch (_) {
    out.official.status = "degraded";
  }

  const linksStart = Date.now();
  try {
    const index = await readFeedPostIndex(env);
    out.links.latency = Date.now() - linksStart;
    out.links.detail = `${Math.max(0, (Number(index.next) || 1) - 1)} short links`;
  } catch (_) {
    out.links.status = "degraded";
  }

  return out;
}

// Reads an announcement image and stores it, so the post never depends on a Discord
// attachment URL that expires.
async function mirrorAnnouncementImage(env, imageUrl, authorId) {
  const raw = sanitizeRemoteMediaUrl(imageUrl) || String(imageUrl || "").trim();
  if (!/^https?:\/\//i.test(raw)) return "";
  try {
    const response = await fetch(raw, { signal: AbortSignal.timeout(8000) });
    if (!response.ok) return "";
    const type = String(response.headers.get("Content-Type") || "");
    if (!/^image\//i.test(type)) return "";
    const bytes = new Uint8Array(await response.arrayBuffer());
    if (!bytes.length || bytes.length > IMAGE_UPLOAD_MAX_BYTES) return "";
    const extension = detectImageExtension(bytes);
    if (!extension) return "";
    const name = `post-${authorId}-${crypto.randomUUID().replace(/-/g, "").slice(0, 20)}.${extension}`;
    const stored = await env.STORAGE.put(`thumbnails/${name}`, bytes, {
      httpMetadata: { contentType: extension === "jpg" ? "image/jpeg" : `image/${extension}` },
    }).catch(() => false);
    return stored ? `https://thumbnail.zyrexediting.xyz/${name}` : "";
  } catch (_) {
    return "";
  }
}

async function dispatchFeedPostNotifications(env, post) {
  if (!post || !post.id || post.repost_of) return 0;
  const authorId = String(post.author_id || "");
  const poster = feedNotificationPoster(post);
  const created = String(post.created_at || new Date().toISOString());
  const base = {
    type: "post",
    post_id: post.id,
    category: "post",
    title: `${poster.name} posted in the feed`,
    desc: feedNotificationText(post),
    link: feedPostUrl(post).replace("https://zyrexediting.xyz", ""),
    icon: "fa-pen-nib",
    icon_brand: false,
    bg: "rgba(var(--zr-rgb-255-43-82, 255, 43, 82),.18)",
    color: "var(--cherry-neon)",
    actor_id: authorId,
    actor_name: poster.name,
    actor_avatar: poster.avatar,
    created_at: created,
  };
  const mentionIds = Array.from(new Set((post.mentions || [])
    .map(entry => String((entry && entry.id) || ""))
    .filter(id => /^\d{15,25}$/.test(id))));
  const tasks = [];

  for (const id of mentionIds) {
    if (id === authorId) continue;
    tasks.push(pushFeedNotification(env, id, {
      ...base,
      id: `feed-${post.id}-mention-${id}`,
      type: "mention",
      category: "mention",
      title: `${poster.name} mentioned you`,
      icon: "fa-at",
    }));
  }

  const followers = (await readFollows(env, authorId).catch(() => ({ followers: [] })))?.followers || [];
  const prefsCache = new Map();
  const prefsFor = id => {
    if (!prefsCache.has(id)) prefsCache.set(id, readFollowPrefs(env, id).catch(() => null));
    return prefsCache.get(id);
  };
  for (const id of followers.slice(0, 300)) {
    if (!/^\d{15,25}$/.test(id) || id === authorId || mentionIds.includes(id)) continue;
    tasks.push((async () => {
      const prefs = await prefsFor(id);
      if (!followAllows(prefs, authorId)) return 0;
      return pushFeedNotification(env, id, { ...base, id: `feed-${post.id}-${id}` });
    })());
  }
  // Announcements from the official account reach the bell, never a DM: nobody should be
  // direct-messaged by the site itself.
  const officialAuthor = await isOfficialProfileId(env, authorId).catch(() => false);
  // Discord DMs go to followers who kept them on; a hard cap keeps a large fan-out from
  // hammering the bot API, and failures never block the post itself.
  const dmTargets = officialAuthor ? [] : followers
    .filter(id => /^\d{15,25}$/.test(id) && id !== authorId && !mentionIds.includes(id))
    .slice(0, FEED_DM_LIMIT_PER_POST);
  if (dmTargets.length) {
    tasks.push((async () => {
      let sent = 0;
      let misses = 0;
      for (const id of dmTargets) {
        const prefs = await prefsFor(id);
        if (!prefs || prefs.dm === false || !followAllows(prefs, authorId)) continue;
        if (await sendFeedPostDM(env, id, post, poster)) sent += 1;
        else if (++misses >= 5) break;
      }
      return sent;
    })());
  }

  // Announcements are already posted to Discord by the bot, so the mirror is skipped.
  if (post.skip_discord !== true) tasks.push(postFeedPostToDiscord(env, post, mentionIds));
  await Promise.all(tasks);
  return tasks.length;
}

async function readProfileViews(env) {  try {
    const stored = await r2GetJSON(env, PROFILE_VIEWS_KEY, null);
    if (stored && typeof stored === "object" && stored.members && typeof stored.members === "object") {
      return { version: 1, members: stored.members };
    }
  } catch (_) {}
  return { version: 1, members: {} };
}

// Counted once per visitor per day without storing anything identifying: the cookie
// is the only marker, so no IP addresses are kept.
async function recordProfileView(env, discordId) {
  const id = String(discordId || "").trim();
  if (!/^\d{15,25}$/.test(id) || !env?.STORAGE) return 0;
  try {
    const doc = await readProfileViews(env);
    const entry = doc.members[id] || { total: 0, days: {} };
    const today = new Date().toISOString().slice(0, 10);
    entry.total = (Number(entry.total) || 0) + 1;
    entry.days = entry.days && typeof entry.days === "object" ? entry.days : {};
    entry.days[today] = (Number(entry.days[today]) || 0) + 1;
    const days = Object.keys(entry.days).sort();
    if (days.length > PROFILE_VIEW_DAYS_KEPT) {
      for (const stale of days.slice(0, days.length - PROFILE_VIEW_DAYS_KEPT)) delete entry.days[stale];
    }
    doc.members[id] = entry;
    // The index is small (three numbers per member) but prune members that only ever
    // had a single view and have not been seen for a year.
    const members = Object.entries(doc.members);
    if (members.length > 5000) {
      const cutoff = new Date(Date.now() - 365 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
      for (const [memberId, value] of members) {
        const lastDay = Object.keys(value.days || {}).sort().pop() || "";
        if (lastDay && lastDay < cutoff) delete doc.members[memberId];
      }
    }
    await r2PutJSON(env, PROFILE_VIEWS_KEY, doc);
    return Number(entry.total) || 0;
  } catch (_) {
    return 0;
  }
}

async function readProfileViewCount(env, discordId) {
  const doc = await readProfileViews(env);
  const entry = doc.members[String(discordId || "").trim()];
  return entry ? Number(entry.total) || 0 : 0;
}

function profileAvatarUrl(discordId, candidate) {
  const id = String(discordId || "").trim();
  const raw = String(candidate || "").trim();
  if (/^https?:\/\//i.test(raw)) return raw;
  if (/^(a_)?[A-Za-z0-9_]{16,}$/.test(raw)) {
    const ext = raw.startsWith("a_") ? "gif" : "png";
    return `/api/avatar/${id}/${raw}.${ext}?size=256`;
  }
  let index = 0;
  try {
    index = Number((BigInt(id) >> 22n) % 6n);
  } catch (_) {
    index = 0;
  }
  return `/api/avatar/default/${index}.png`;
}

// The profile's own identity resolution: Discord first (live when reachable), then
// whatever the catalogue recorded, then a neutral default.
async function resolveProfileIdentity(env, discordId, ownedProducts = null) {
  const id = String(discordId || "").trim();
  const identity = { id, name: "", username: "", avatar: "", banner: "", source: "default" };
  try {
    // Always come from the main profile: fresh when it can be fetched, cached when not.
    const resolved = await ensureDiscordUserProfile(env, id);
    if (resolved && resolved.user) {
      const cached = resolved.user;
      identity.source = resolved.source || "discord-cache";
      identity.name = String(cached.global_name || cached.display_name || cached.username || "").trim();
      identity.username = String(cached.username || "").trim();
      identity.avatar = profileAvatarUrl(id, cached.avatar || cached.avatar_url);
      const bannerHash = String(cached.banner || "").trim();
      if (bannerHash && /^(?:a_)?[a-z0-9_-]{16,}$/i.test(bannerHash)) {
        const ext = bannerHash.startsWith("a_") ? "gif" : "png";
        identity.banner = `/api/banner/${id}/${bannerHash}.${ext}?size=600`;
      }
    }
  } catch (_) {}
  if (!identity.name || !identity.username) {
    try {
      let owned = Array.isArray(ownedProducts) ? ownedProducts : null;
      if (!owned) {
        const catalog = await dbReadProductCatalog(env);
        owned = Array.isArray(catalog) ? catalog : [];
      }
      owned = owned.filter(
        item => item && String(item.uploader_id || item.author_id || "") === id && item.is_anonymous !== true
      );
      if (owned.length) {
        if (!identity.name) identity.name = String(owned[0].uploader_name || owned[0].author_name || "").trim();
        if (!identity.avatar) identity.avatar = profileAvatarUrl(id, owned[0].uploader_avatar || owned[0].author_avatar);
        if (identity.source === "default" && (identity.name || identity.avatar)) identity.source = "catalog";
      }
    } catch (_) {}
  }
  if (!identity.name) identity.name = "Zyrex Member";
  if (!identity.avatar) identity.avatar = profileAvatarUrl(id, "");
  return identity;
}

async function resolveProfileTier(env, discordId) {
  const id = String(discordId || "").trim();
  const isOfficial = await isOfficialProfileId(env, id);
  if (isOfficial) {
    return {
      tier: "official",
      tier_info: PROFILE_TIERS.official,
      // The blue tick next to the name carries the admin signal, so no chip repeats it.
      badges: [
        { key: "official", label: "Official", icon: "fa-certificate" },
      ],
    };
  }
  const [team, verified, uploaderRole] = await Promise.all([
    dbGetTeam(env).catch(() => ({})),
    checkVerifiedRole(id, env).catch(() => null),
    hasCommunityUploaderRole(id, env).catch(() => false),
  ]);
  const inGroup = group => Array.isArray(team && team[group]) &&
    team[group].some(item => String((item && item.id) || item || "") === id);
  let tier = "member";
  if (inGroup("founders") || ADMIN_IDS.includes(id)) tier = "founder";
  else if (inGroup("staff")) tier = "staff";
  else if (inGroup("contributors")) tier = "contributor";
  else if (uploaderRole) tier = "uploader";
  const badges = [];
  // Administrators are recognised by the blue tick next to their name, not by a chip.
  if (verified === true) badges.push({ key: "verified", label: "Verified", icon: "fa-circle-check" });
  // Ad-free is a download perk, not a public identity badge, so it never surfaces on profiles.
  if (uploaderRole) badges.push({ key: "uploader", label: "Uploader", icon: "fa-cloud-arrow-up" });
  if (tier === "founder") badges.unshift({ key: "founder", label: "Founder", icon: "fa-crown" });
  else if (tier === "staff") badges.unshift({ key: "staff", label: "Staff", icon: "fa-shield-halved" });
  else if (tier === "contributor") badges.unshift({ key: "contributor", label: "Contributor", icon: "fa-hand-holding-heart" });
  return { tier, tier_info: PROFILE_TIERS[tier] || PROFILE_TIERS.member, badges };
}

async function resolveProfileHandle(env, identity, settings) {
  if (await isOfficialProfileId(env, identity && identity.id)) return ZYREX_HANDLE;
  const existing = normalizeHandle(settings.handle);
  if (existing) return existing;
  const preferred = identity.username || identity.name || "";
  return ensureProfileHandle(env, identity.id, preferred);
}

function profileMemberDays(joinedAt) {
  const stamp = Date.parse(String(joinedAt || ""));
  if (!Number.isFinite(stamp)) return 0;
  return Math.max(0, Math.floor((Date.now() - stamp) / (24 * 60 * 60 * 1000)));
}

function profileActivity(ownedProducts, achievements, unlocked) {
  const items = [];
  for (const product of ownedProducts || []) {
    items.push({
      type: "upload",
      title: `Uploaded "${String(product.name || "a resource").slice(0, 80)}"`,
      detail: String(product.category || "").replace(/-/g, " "),
      at: product.created_at || null,
      url: `/leak?id=${encodeURIComponent(String(product.id || ""))}`,
    });
  }
  for (const achievement of achievements || []) {
    const at = unlocked && unlocked[achievement.key];
    if (!at) continue;
    items.push({ type: "achievement", title: `Unlocked ${achievement.label}`, detail: achievement.description, at });
  }
  return items
    .filter(item => item.at)
    .sort((a, b) => String(b.at).localeCompare(String(a.at)))
    .slice(0, 12);
}

function profileMonthlySeries(entry) {
  const monthly = (entry && entry.monthly) || {};
  return Object.keys(monthly).sort().slice(-12).map(month => ({
    month,
    count: Number(monthly[month]) || 0,
  }));
}

// Announcements list every category a leak belongs to, so a preset reads "After Effects ·
// Setting Preset" rather than one opaque slug.
const PRODUCT_CATEGORY_LABELS = {
  "after-effects": "After Effects",
  "premiere-pro": "Premiere Pro",
  photoshop: "Photoshop",
  "video-star": "Video Star",
  "topaz-labs": "Topaz Labs",
  software: "Software",
  "adobe-plugin": "Adobe Plugin",
  "ofx-plugin": "OFX Plugin",
  "project-file": "Project File",
  "setting-preset": "Setting Preset",
  scenepack: "Scenepack",
  audio: "Audio",
  preset: "Preset",
  others: "Others",
};

function productCategoryValues(product) {
  const values = [];
  const push = value => {
    const slug = String(value || "").trim().toLowerCase();
    if (slug && !values.includes(slug)) values.push(slug);
  };
  if (Array.isArray(product && product.resource_subcategories)) (product.resource_subcategories || []).forEach(push);
  else String((product && product.resource_category) || "").split(",").forEach(push);
  push(product && product.category);
  if (!values.length) push("others");
  return values;
}

function productCategoryLabels(product) {
  return productCategoryValues(product).map(slug =>
    PRODUCT_CATEGORY_LABELS[slug] || slug.replace(/[-_]+/g, " ").replace(/\b[a-z]/g, char => char.toUpperCase())
  );
}

function profilePublicResource(product) {
  return {
    id: String(product.id || ""),
    name: String(product.name || ""),
    type: String(product.type || "preset").toLowerCase(),
    category: String(product.category || "others").toLowerCase(),
    categories: productCategoryValues(product),
    category_labels: productCategoryLabels(product),
    thumbnail: String(product.thumbnail || ""),
    created_at: product.created_at || null,
    views: Number(product.views) || 0,
    downloads: Number(product.downloads) || 0,
    url: `/leak?id=${encodeURIComponent(String(product.id || ""))}`,
    is_anonymous: product.is_anonymous === true,
    own: false,
  };
}

function isScenepackProduct(product) {
  if (!product || typeof product !== "object") return false;
  const values = [product.type, product.category, product.resource_category]
    .flatMap(value => String(value || "").toLowerCase().split(/[,/]/).map(part => part.trim()));
  return values.includes("scenepack") || String(product.id || "").toLowerCase().startsWith("scenepack-");
}

// Only presets are announced on the feed: plugins and audios live on their own pages
// and must never show up as posts from the Zyrex profile.
const FEED_HIDDEN_RESOURCE_TYPES = ["plugin", "audio"];
function isFeedAnnounceableProduct(product) {
  if (!product || typeof product !== "object") return false;
  if (product.is_anonymous === true || isScenepackProduct(product)) return false;
  const values = [product.type, product.category, product.resource_category]
    .flatMap(value => String(value || "").toLowerCase().split(/[,/]/).map(part => part.trim()));
  return !values.some(value => FEED_HIDDEN_RESOURCE_TYPES.some(type =>
    value === type || value.startsWith(type + "-") || value.endsWith("-" + type) || value.endsWith("_" + type)));
}

// Profiles are a resource shelf: audio, plugins, software and scenepacks have their
// own pages, so they never appear in (or count towards) a member's profile.
function isProfileResourceProduct(product) {
 if (!product || isScenepackProduct(product)) return false;
 const type = String(product.type || "").trim().toLowerCase();
 return !type || type === "preset" || type === "resource";
}

function profileOwnedProducts(catalog, discordId) {
  const id = String(discordId || "").trim();
  return (Array.isArray(catalog) ? catalog : []).filter(
    product => {
      if (!isProfileResourceProduct(product)) return false;
      const creditedId = String(product.credited_uploader_id || "").trim();
      if (creditedId) return creditedId === id;

      // Ownership is settled by comparing the member id with the uploader id, so the
      // founder's own uploads count too (the old admin-import guard zeroed them).
      const submitterId = String(product.uploader_id || product.author_id || "").trim();
      return submitterId === id;
    }
  );
}

// Anonymous resources are invisible to visitors and to the owner's public listing;
// the owner keeps a private count instead.
function profileVisibleProducts(ownedProducts) {
  return (ownedProducts || []).filter(product => product && product.is_anonymous !== true);
}

// The same ownership rules as profileOwnedProducts, applied to the whole catalogue
// at once so listings (profile, connections) can never disagree on a member's count.
function profileOwnedResourceCounts(catalog) {
  const counts = new Map();
  for (const product of Array.isArray(catalog) ? catalog : []) {
    if (!isProfileResourceProduct(product) || product.is_anonymous === true) continue;
    const creditedId = String(product.credited_uploader_id || "").trim();
    const ownerId = creditedId || String(product.uploader_id || product.author_id || "").trim();
    if (!ownerId) continue;
    counts.set(ownerId, (counts.get(ownerId) || 0) + 1);
  }
  return counts;
}

function profileCategoryBreakdown(entry) {
  const categories = (entry && entry.categories) || {};
  return Object.entries(categories)
    .map(([key, count]) => {
      const info = CATEGORY_INFO[key] || {};
      return {
        key,
        label: info.label || key.replace(/-/g, " "),
        emoji: info.emoji || "",
        count: Number(count) || 0,
      };
    })
    .sort((a, b) => b.count - a.count)
    .slice(0, 8);
}

function profileTypeBreakdown(entry) {
  const types = (entry && entry.types) || {};
  return Object.entries(types)
    .map(([key, count]) => ({ key, count: Number(count) || 0 }))
    .sort((a, b) => b.count - a.count);
}

function buildProfileSubjectList(aggregates) {
  const uploaders = (aggregates && aggregates.uploaders) || {};
  const downloads = (aggregates && aggregates.downloads) || {};
  const ids = new Set([...Object.keys(uploaders), ...Object.keys(downloads)]);
  return Array.from(ids).map(id => profileSubject(aggregates, id));
}

// Identity for many members at once, taken from the catalogue, so boards and feeds do
// not read Discord data per row.
function buildProfileIdentityMap(products) {
  const map = new Map();
  for (const product of Array.isArray(products) ? products : []) {
    const owner = String((product && (product.credited_uploader_id || product.uploader_id || product.author_id)) || "").trim();
    if (!owner) continue;
    const current = map.get(owner) || { name: "", avatar: "" };
    map.set(owner, {
      name: current.name || String(product.credited_uploader_name || product.uploader_name || product.author_name || "").trim(),
      avatar: current.avatar || String(product.credited_uploader_avatar || product.uploader_avatar || product.author_avatar || "").trim(),
    });
  }
  return map;
}

async function buildProfilePayload(env, discordId, options = {}) {
  const id = String(discordId || "").trim();
  if (!/^\d{15,25}$/.test(id)) return { error: "Invalid member", status: 400 };

  const viewerId = String(options.viewerId || "").trim();
  const isSelf = Boolean(viewerId) && viewerId === id;
  const isStaffViewer = options.isStaff === true;

  // The official profile has a fixed identity and no shelf of its own.
  const official = await resolveZyrexProfile(env).catch(() => null);
  const isOfficial = Boolean(official && official.id === id);
  if (isOfficial) await ensureZyrexHandle(env, id).catch(() => false);

  const [catalog, settings, aggregates, follows, tierInfo, revoked, guildMember] = await Promise.all([
    dbReadProductCatalog(env).catch(() => []),
    readProfileSettings(env, id),
    readProfileAggregates(env),
    readFollows(env, id, isOfficial ? { limit: ZYREX_FOLLOWER_LIMIT } : {}),
    resolveProfileTier(env, id),
    isRevoked(env, id).catch(() => false),
    // Use the Worker logger bot's live Discord role response for this badge.
    // Do not rely on the hand-maintained team list or a VPS-side role decision.
    fetchGuildMemberLive(env, id).catch(() => null),
  ]);
  const hasStaffTeamRole = !isOfficial && tierInfo.tier !== "founder" &&
    Boolean(guildMember && guildMember.in_guild === true &&
      Array.isArray(guildMember.roles) && guildMember.roles.includes(TEAM_GROUP_ROLE_IDS.staff));

  const owned = profileOwnedProducts(catalog, id);
  const visible = profileVisibleProducts(owned);
  const identity = await resolveProfileIdentity(env, id, owned);
  const handle = await resolveProfileHandle(env, identity, settings);
  const viewerCanSeePrivate = isSelf || isStaffViewer;

  if (settings.public === false && !viewerCanSeePrivate) {
    return {
      profile: {
        id,
        handle,
        name: identity.name,
        avatar: identity.avatar,
        tier: tierInfo.tier,
        tier_label: tierInfo.tier_info.label,
        tier_icon: tierInfo.tier_info.icon,
        accent: tierInfo.tier_info.accent,
        badges: [],
        private: true,
        restricted: revoked === true,
      },
      private_profile: true,
      settings,
    };
  }

  const joinedAt = options.joinedAt || "";
  const memberDays = profileMemberDays(joinedAt);
  const subject = profileSubject(aggregates, id, {
    member_days: memberDays,
    followers: follows.followers.length,
  });
  const achievements = evaluateAchievements(subject, buildProfileSubjectList(aggregates));
  const unlocked = await stampAchievements(env, id, achievements);
  const decorated = achievements.map(item => ({ ...item, unlocked_at: unlocked[item.key] || null }));

  const showDownloads = settings.show_downloads !== false;
  const stats = {
    resources: visible.length,
    views: Number(subject.views) || 0,
    comments: Number(subject.comments) || 0,
    requests_made: Number(subject.requests_made) || 0,
    requests_fulfilled: Number(subject.requests_fulfilled) || 0,
    first_upload_at: subject.first_at || null,
    last_upload_at: subject.last_at || null,
    active_months: Object.keys(subject.monthly || {}).length,
    best_resource: subject.best || null,
      category_focus: "",
      type_focus: "",
  };
  if (showDownloads) {
    stats.downloads = Number(subject.downloads) || 0;
    stats.downloads_made = Number(subject.downloads_made) || 0;
    stats.avg_downloads = Math.round((Number(subject.avg_downloads) || 0) * 10) / 10;
  }

  const counts = {
    resources: visible.length,
    public_resources: visible.length,
    followers: follows.followers.length,
    following: follows.following.length,
    profile_views: await readProfileViewCount(env, id),
  };
  if (viewerCanSeePrivate) counts.anonymous_resources = Number(subject.anonymous) || 0;

  return {
    profile: {
      id,
      handle: isOfficial ? ZYREX_HANDLE : handle,
      url: isOfficial ? `/@${ZYREX_HANDLE}` : (handle ? `/@${handle}` : ""),
      name: isOfficial ? official.name : identity.name,
      username: isOfficial ? official.username : identity.username,
      avatar: isOfficial ? official.avatar : identity.avatar,
      banner: isOfficial ? "" : identity.banner,
      // Where the card's identity came from: discord-live, discord-cache, catalog, default.
      identity_source: identity.source || "default",
      tier: tierInfo.tier,
      tier_label: tierInfo.tier_info.label,
      tier_icon: tierInfo.tier_info.icon,
      accent: settings.accent || tierInfo.tier_info.accent,
      badges: tierInfo.badges,
      has_staff_team_role: hasStaffTeamRole,
      bio: isOfficial ? ZYREX_BIO : settings.bio,
      links: isOfficial ? [] : await resolveProfileSocialLinks(env, settings.links, id),
      joined_at: joinedAt || null,
      member_days: memberDays,
      privacy: {
        public: settings.public !== false,
        show_downloads: showDownloads,
        show_activity: settings.show_activity !== false,
        show_connections: settings.show_connections !== false,
      },
      counts,
      stats,
      achievements: decorated,
      activity: isOfficial || settings.show_activity === false ? [] : profileActivity(visible, decorated, unlocked),
      months: isOfficial ? [] : profileMonthlySeries(subject),
      is_official: isOfficial,
      is_admin: ADMIN_IDS.includes(id),
      pinned_post_id: isOfficial ? "" : String(settings.pinned_post_id || ""),
      can_edit: !isOfficial,
      can_repost: !isOfficial,
      is_self: Boolean(isSelf),
      is_staff_viewer: Boolean(isStaffViewer),
      is_following: follows.followers.includes(viewerId),
      restricted: revoked === true,
      private: false,
    },
    private_profile: false,
    settings,
  };
}

// One inverted index read maps every member to their handle, so a board never costs
// one read per row.
function invertHandleIndex(index) {
  const byId = {};
  for (const entry of Object.values((index && index.handles) || {})) {
    if (entry && entry.id) byId[String(entry.id)] = String(entry.handle || "");
  }
  return byId;
}

// Upload announcements are posts too: a deterministic id gives them likes, replies and
// the same /feed/post/<n> numbering as written posts, without storing a second document.
const NOTICE_POST_PREFIX = "feed/resource_posts/";

function noticePostId(productId) {
  const seed = `resource:${String(productId || "")}`;
  let hash = 0x811c9dc5;
  let out = "";
  for (let round = 0; round < 4; round += 1) {
    for (let index = 0; index < seed.length; index += 1) {
      hash ^= seed.charCodeAt(index) + round * 131;
      hash = Math.imul(hash, 0x01000193) >>> 0;
    }
    out += hash.toString(16).padStart(8, "0");
    hash = (hash ^ 0x9e3779b9) >>> 0;
  }
  return out;
}

function noticeResourceKey(postId) {
  return `${NOTICE_POST_PREFIX}${String(postId || "").replace(/[^a-f0-9]/gi, "")}.json`;
}

async function readNoticePost(env, postId) {
  if (!/^[a-f0-9]{16,40}$/i.test(String(postId || ""))) return null;
  const stored = await r2GetJSON(env, noticeResourceKey(postId), null).catch(() => null);
  if (!stored || !stored.product_id) return null;
  return stored;
}

// Numbers are handed out oldest first so the short links follow the upload order.
async function assignNoticeSequences(env, notices) {
  if (!Array.isArray(notices) || !notices.length) return notices;
  const index = await readFeedPostIndex(env);
  const known = new Map();
  const entries = {};
  for (const [seq, entry] of Object.entries(index.entries || {})) {
    if (!entry || !entry.post_id) continue;
    // Anything that is not a post id cannot resolve through the short link, so it is dropped.
    if (!/^[a-f0-9-]{16,40}$/i.test(String(entry.post_id))) continue;
    entries[seq] = entry;
    known.set(`${entry.author_id}:${entry.post_id}`, Number(seq));
  }
  let next = Math.max(Number(index.next) || 1, 1);
  const pending = [];
  const chronological = notices.slice().sort((a, b) => String(a.created_at || "").localeCompare(String(b.created_at || "")));
  for (const notice of chronological) {
    const postId = String(notice.post_id || notice.id || "");
    if (!/^[a-f0-9-]{16,40}$/i.test(postId)) continue;
    const key = `${notice.author_id}:${postId}`;
    let seq = known.get(key) || 0;
    if (!seq) {
      while (entries[String(next)]) next += 1;
      seq = next;
      entries[String(seq)] = { author_id: notice.author_id, post_id: postId, created_at: notice.created_at || new Date().toISOString() };
      known.set(key, seq);
      next += 1;
      pending.push({ notice, postId });
    }
    notice.seq = seq;
    notice.post_url = `/feed/post/${seq}`;
  }
  if (pending.length) {
    await writeFeedPostIndex(env, { next, entries }).catch(() => false);
    await Promise.all(pending.map(({ notice, postId }) => r2PutJSON(env, noticeResourceKey(postId), {
      product_id: notice.product_id,
      author_id: notice.author_id,
      created_at: notice.created_at || "",
    }).catch(() => false)));
  }
  return notices;
}
async function buildFollowFeed(env, viewerId, page = 1, limit = 24, options = {}) {
  const official = await resolveZyrexProfile(env).catch(() => null);
  const officialId = official ? official.id : "";
  const catalog = await dbReadProductCatalog(env).catch(() => []);
  const products = Array.isArray(catalog) ? catalog : [];
  const owners = buildProfileIdentityMap(products);
  const handles = invertHandleIndex(await readHandleIndex(env));
  // Hidden posts and hidden announcements never reach the timeline.
  const hiddenIds = await readFeedHiddenIds(env).catch(() => new Set());
  const resourceItems = products
    .filter(product => isFeedAnnounceableProduct(product))
    .filter(product => String(product.id || ""))
    .filter(product => !hiddenIds.has(noticeHiddenId(product.id)))
    .sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || "")))
    .map(product => {
    const owner = String(product.credited_uploader_id || product.uploader_id || product.author_id || "");
    const identity = owners.get(owner) || {
      name: String(product.credited_uploader_name || product.uploader_name || product.author_name || "").trim(),
      avatar: String(product.credited_uploader_avatar || product.uploader_avatar || product.author_avatar || "").trim(),
    };
    const handle = handles[owner] || "";
    const displayHandle = handle;
    const displayName = identity.name || String(product.uploader_name || product.author_name || "").trim() || owner;
    const postId = noticePostId(product.id);
    return {
      kind: "resource_notice",
      ...profilePublicResource(product),
      post_id: postId,
      author_id: officialId,
      product_id: String(product.id || ""),
      created_at: product.created_at || null,
      author: {
        id: officialId,
        name: official ? official.name : "Zyrex",
        handle: ZYREX_HANDLE,
        avatar: official ? official.avatar : "/assets/content.png",
        url: `/@${ZYREX_HANDLE}`,
        is_admin: true,
        is_official: true,
      },
      announcement: {
        id: officialId,
        name: official ? official.name : "Zyrex",
        handle: ZYREX_HANDLE,
        avatar: official ? official.avatar : "/assets/content.png",
        url: `/@${ZYREX_HANDLE}`,
      },
      text: `${displayHandle ? "@" + displayHandle : (displayName || "Zyrex member")} uploaded a new leak!`,
      uploader: {
        id: owner,
        name: displayName,
        handle: displayHandle,
        avatar: profileAvatarUrl(owner, identity.avatar || product.uploader_avatar || product.author_avatar),
        url: handles[owner] ? `/@${handles[owner]}` : `/profile?id=${encodeURIComponent(owner)}`,
      },
    };
  });

  if (officialId && resourceItems.length) {
    await assignNoticeSequences(env, resourceItems).catch(() => resourceItems);
  }

  // Individual post objects provide an inexpensive, newest-first R2 timeline.
  // A one-time legacy scan keeps posts created before the feed index available.
  let postFiles = [];
  try { postFiles = await r2List(env, "profiles/feed/"); } catch (_) {}
  if (!postFiles.length) {
    let legacyFiles = [];
    try { legacyFiles = await r2List(env, "profiles/posts/"); } catch (_) {}
    const legacyOwners = legacyFiles.map(file => {
      const match = String(file.key || "").match(/^profiles\/posts\/(\d{15,25})\.json$/);
      return match ? { key: file.key, id: match[1] } : null;
    }).filter(Boolean).slice(0, 300);
    const legacyPosts = await Promise.all(legacyOwners.map(async owner => {
      const document = await r2GetJSON(env, owner.key, null);
      const rows = Array.isArray(document && document.posts) ? document.posts : [];
      return rows.map(raw => {
        const post = sanitizeProfilePost(raw, owner.id);
        if (!post || post.repost_of) return null;
        return { author_id: owner.id, post };
      }).filter(Boolean);
    }));
    const migrated = legacyPosts.flat().sort((a, b) => String(b.post.created_at).localeCompare(String(a.post.created_at))).slice(0, 200);
    await Promise.all(migrated.map(entry => r2PutJSON(env, profileFeedPostKey(entry.author_id, entry.post), entry).catch(() => false)));
    postFiles = migrated.map(entry => ({ key: profileFeedPostKey(entry.author_id, entry.post) }));
  }
  postFiles.sort((a, b) => String(b.key || "").localeCompare(String(a.key || "")));
  const recentFiles = postFiles.slice(0, 200);
  const settingsCache = new Map();
  const postEntries = await Promise.all(recentFiles.map(async file => {
    const entry = await r2GetJSON(env, file.key, null);
    if (!entry || !/^\d{15,25}$/.test(String(entry.author_id || ""))) return null;
    const ownerId = String(entry.author_id);
    if (!settingsCache.has(ownerId)) settingsCache.set(ownerId, readProfileSettings(env, ownerId));
    const settings = await settingsCache.get(ownerId);
    if (settings.public === false || settings.show_activity === false) return null;
    const post = sanitizeProfilePost(entry.post, ownerId);
    if (!post) return null;
    const storedAuthor = post.author || {};
    const handle = handles[ownerId] || "";
    const fallbackIdentity = owners.get(ownerId) || {};
    const selfAuthor = {
      id: ownerId,
      name: storedAuthor.name || fallbackIdentity.name || "Zyrex Member",
      handle: storedAuthor.handle || handle,
      avatar: storedAuthor.avatar || profileAvatarUrl(ownerId, fallbackIdentity.avatar),
      url: storedAuthor.url || (handle ? `/@${handle}` : `/profile?id=${encodeURIComponent(ownerId)}`),
      is_admin: ADMIN_IDS.includes(ownerId),
    };

    // A repost points at the original post, so the feed shows "X reposted" while likes,
    // views and replies all land on the post that was reposted.
    if (post.repost_of) {
      const sourceId = String(post.repost_of.author_id || "");
      if (!settingsCache.has(sourceId)) settingsCache.set(sourceId, readProfileSettings(env, sourceId));
      const sourceSettings = await settingsCache.get(sourceId);
      if (sourceSettings.public === false || sourceSettings.show_activity === false) return null;
      const source = await readProfilePost(env, sourceId, post.repost_of.post_id).catch(() => null);
      if (!source || source.repost_of) return null;
      const sourceStored = source.author || {};
      const sourceHandle = handles[sourceId] || "";
      const sourceIdentity = owners.get(sourceId) || {};
      return {
        kind: "member_post",
        id: post.id,
        author_id: ownerId,
        author: selfAuthor,
        text: "",
        mentions: [],
        media: [],
        created_at: post.created_at,
        official: ownerId === officialId,
        repost_of: {
          id: source.id,
          author_id: sourceId,
          author_is_official: sourceId === officialId,
          author: {
            id: sourceId,
            name: sourceStored.name || sourceIdentity.name || "Zyrex Member",
            handle: sourceStored.handle || sourceHandle,
            avatar: sourceStored.avatar || profileAvatarUrl(sourceId, sourceIdentity.avatar),
            url: sourceStored.url || (sourceHandle ? `/@${sourceHandle}` : `/profile?id=${encodeURIComponent(sourceId)}`),
            is_admin: ADMIN_IDS.includes(sourceId),
          },
          text: source.text,
          mentions: source.mentions,
          media: source.media,
          links: source.links,
          video: source.video,
          tags: source.tags,
          seq: source.seq,
          edited_at: source.edited_at,
          created_at: source.created_at,
        },
      };
    }

    return {
      kind: "member_post",
      id: post.id,
      author_id: ownerId,
      author: selfAuthor,
      text: post.text,
      mentions: post.mentions,
      media: post.media,
      links: post.links,
      video: post.video,
      tags: post.tags,
      seq: post.seq,
      edited_at: post.edited_at,
      official: ownerId === officialId,
      created_at: post.created_at,
    };
  }));
  // A member post links to its author's profile, so authors without a profile are
  // dropped from the timeline instead of rendering a dead link.
  let memberPosts = await filterGuildMembers(env, postEntries.filter(Boolean), item => item.author_id);
  // Hidden posts and hidden repost sources never reach the timeline.
  if (hiddenIds.size) {
    memberPosts = memberPosts.filter(item => !hiddenIds.has(String(item.id)) && !(item.repost_of && hiddenIds.has(String(item.repost_of.id))));
  }
  // Everyone in a repost chain has to be a current member, otherwise the card would
  // link to a profile that no longer exists.
  const repostRows = memberPosts.filter(item => item.repost_of);
  if (repostRows.length) {
    const allowed = await filterGuildMembers(env, repostRows, item => item.repost_of.author_id);
    const allowedKeys = new Set(allowed.map(item => `${item.repost_of.author_id}:${item.repost_of.id}`));
    memberPosts = memberPosts.filter(item => !item.repost_of || allowedKeys.has(`${item.repost_of.author_id}:${item.repost_of.id}`));
  }
  // The viewer's pinned post is marked so the feed shows the same Pin control the
  // profile does.
  const viewerSettings = viewerId ? await readProfileSettings(env, viewerId).catch(() => null) : null;
  const viewerPinnedId = String((viewerSettings && viewerSettings.pinned_post_id) || "");
  if (viewerPinnedId) {
    for (const item of memberPosts) {
      if (!item.repost_of && String(item.author_id) === String(viewerId) && String(item.id) === viewerPinnedId) item.pinned = true;
    }
  }
  // The feed mirrors the profile's Repost/Reposted state, so the viewer's own reposts
  // are resolved once per request.
  if (viewerId) {
    const ownPosts = await readProfilePosts(env, viewerId).catch(() => []);
    const repostKeys = new Set((Array.isArray(ownPosts) ? ownPosts : [])
      .filter(post => post && post.repost_of && post.repost_of.author_id && post.repost_of.post_id)
      .map(post => `${post.repost_of.author_id}:${post.repost_of.post_id}`));
    if (repostKeys.size) {
      for (const item of memberPosts) {
        const source = item.repost_of || item;
        if (repostKeys.has(`${source.author_id}:${source.id}`)) item.viewer_reposted = true;
      }
    }
  }

  // Posts created before short links existed still need a number.
  const missingSeq = memberPosts.filter(item => !item.seq);
  if (missingSeq.length) {
    await backfillFeedSequences(env).catch(() => null);
    const index = await readFeedPostIndex(env);
    for (const item of memberPosts) {
      const source = item.repost_of || item;
      if (!item.seq) item.seq = feedSeqOf(index, source.author_id, source.id) || 0;
    }
  }

  const size = Math.min(Math.max(Number(limit) || 24, 1), 60);
  const current = Math.max(Number(page) || 1, 1);

  // Trending ranks written posts by how many likes they collected, most liked first.
  // Posts nobody liked are left out, and generated resource notices never trend.
  const tagFilter = String(options.tag || "").trim().toLowerCase();
  if (tagFilter) memberPosts = memberPosts.filter(item => (item.tags || []).includes(tagFilter));

  if (options.sort === "trending") {
    const ranked = await rankTrendingPosts(env, memberPosts.slice(0, 150));
    return {
      total: ranked.length,
      page: current,
      pages: Math.max(1, Math.ceil(ranked.length / size)),
      items: ranked.slice((current - 1) * size, current * size),
      sort: "trending",
      pinned_post_id: viewerPinnedId,
    };
  }

  const items = resourceItems.concat(memberPosts).sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || "")));
  const pageItems = items.slice((current - 1) * size, current * size);
  return {
    total: items.length,
    page: current,
    pages: Math.max(1, Math.ceil(items.length / size)),
    items: pageItems,
    sort: "latest",
    pinned_post_id: viewerPinnedId,
  };
}

// Like counts live next to each post's interactions, so trending reads those rows and
// keeps only posts with at least one like. The result is memoised briefly because the
// rank order barely moves between views.
const trendingMemo = new Map();
const TRENDING_MEMO_MS = 45 * 1000;

async function rankTrendingPosts(env, posts) {
  const rows = (posts || []).filter(item => item && item.id);
  if (!rows.length) return [];
  const cacheKey = rows.map(item => item.id).join("|").slice(0, 4000);
  const cached = trendingMemo.get(cacheKey);
  if (cached && Date.now() - cached.at < TRENDING_MEMO_MS) return cached.value;

  const scored = await Promise.all(rows.map(async item => {
    const sourceId = item.repost_of ? item.repost_of.id : item.id;
    const sourceAuthor = item.repost_of ? item.repost_of.author_id : item.author_id;
    let likes = 0;
    try {
      const stored = await r2GetJSON(env, socialInteractionKey("post", sourceId, sourceAuthor), null);
      likes = stored && Array.isArray(stored.likes) ? stored.likes.length : 0;
    } catch (_) {
      likes = 0;
    }
    return { ...item, likes };
  }));

  const ranked = scored
    .filter(item => item.likes > 0)
    .sort((a, b) => (b.likes - a.likes) || String(b.created_at || "").localeCompare(String(a.created_at || "")));

  trendingMemo.set(cacheKey, { at: Date.now(), value: ranked });
  if (trendingMemo.size > 40) trendingMemo.delete(trendingMemo.keys().next().value);
  return ranked;
}

const SOCIAL_INTERACTIONS_PREFIX = "social/interactions/";

function socialInteractionKey(type, id, authorId = "") {
  const identity = type === "post" ? `${authorId}:${id}` : id;
  return `${SOCIAL_INTERACTIONS_PREFIX}${type}/${encodeURIComponent(identity)}.json`;
}

async function resolveSocialTarget(env, type, id, authorId = "") {
  if (type === "resource") {
    if (!/^[a-z0-9_-]{3,100}$/i.test(id)) return null;
    const product = await dbGetProduct(env, id);
    if (!product || product.is_anonymous === true || isScenepackProduct(product)) return null;
    return { type, id };
  }
  if (type === "post") {
    if (!/^\d{15,25}$/.test(authorId) || !/^[a-f0-9-]{16,40}$/i.test(id)) return null;
    const post = await readProfilePost(env, authorId, id);
    if (!post) return null;
    const settings = await readProfileSettings(env, authorId);
    if (settings.public === false || settings.show_activity === false) return null;
    return { type, id, author_id: authorId };
  }
  return null;
}

function emptySocialInteraction() {
  return { version: 1, likes: [], views: {}, view_count: 0, replies: [] };
}

function sanitizeSocialInteraction(value) {
  const row = value && typeof value === "object" ? value : {};
  const rawViews = row.views && typeof row.views === "object" && !Array.isArray(row.views) ? row.views : {};
  const views = Object.entries(rawViews)
    .filter(([viewer, stamp]) => /^[a-f0-9]{32}$/.test(viewer) && Number.isFinite(Number(stamp)))
    .sort((a, b) => Number(b[1]) - Number(a[1]))
    .slice(0, 5000);
  const replies = (Array.isArray(row.replies) ? row.replies : []).filter(reply => reply && typeof reply === "object").slice(-500).map(reply => {
    const authorId = String(reply.author_id || "").trim();
    const author = reply.author && typeof reply.author === "object" ? reply.author : {};
    const handle = normalizeHandle(author.handle);
    const url = handle && isValidHandle(handle)
      ? `/@${handle}`
      : (/^\d{15,25}$/.test(authorId) ? `/profile?id=${encodeURIComponent(authorId)}` : "/profile");
    const avatarValue = String(author.avatar || "");
    // Our own avatar proxy is a relative path, so it must survive the sanitizer:
    // rejecting it replaced every member's photo with the generic placeholder.
    const avatar = stableAvatarUrl(avatarValue, authorId)
      || (/^\d{15,25}$/.test(authorId) ? profileAvatarUrl(authorId, "") : "/assets/default-avatar.png");
    const media = (Array.isArray(reply.media) ? reply.media : [])
      .map(value => String(value || "").trim())
      .filter(value => /^https:\/\/(?:cdn\.discordapp\.com|media\.discordapp\.net|media\d*\.giphy\.com|i\.giphy\.com|media\.tenor\.com|thumbnail\.zyrexediting\.xyz)\/[^\s]+$/i.test(value))
      .slice(0, 4);
  // Replies can answer another reply: the parent keeps the thread two levels deep
  // and reply_to records who was addressed.
  const parentId = /^[a-f0-9-]{16,40}$/i.test(String(reply.parent_id || "")) ? String(reply.parent_id) : "";
  const rawTarget = reply.reply_to && typeof reply.reply_to === "object" ? reply.reply_to : null;
  const replyTo = rawTarget
    ? {
      id: /^[a-f0-9-]{16,40}$/i.test(String(rawTarget.id || "")) ? String(rawTarget.id) : parentId,
      name: String(rawTarget.name || "").slice(0, 80),
      handle: normalizeHandle(rawTarget.handle),
    }
    : null;
  return {
    id: /^[a-f0-9-]{16,40}$/i.test(String(reply.id || "")) ? String(reply.id) : crypto.randomUUID(),
    author_id: authorId,
    author: { name: String(author.name || "Zyrex Member").slice(0, 80), handle, avatar, url },
    text: String(reply.text || "").trim().slice(0, 500),
    media,
    created_at: Number.isFinite(Date.parse(reply.created_at)) ? new Date(reply.created_at).toISOString() : new Date(0).toISOString(),
    ...(parentId ? { parent_id: parentId } : {}),
    ...(replyTo && (replyTo.name || replyTo.handle) ? { reply_to: replyTo } : {}),
  };
  }).filter(reply => reply.text || reply.media.length);
  return {
    version: 1,
    likes: [...new Set((Array.isArray(row.likes) ? row.likes : []).map(String).filter(id => /^\d{15,25}$/.test(id)))].slice(-10000),
    views: Object.fromEntries(views),
    view_count: Math.max(0, Number(row.view_count) || 0),
    replies,
  };
}

function socialInteractionSummary(row, viewerId = "", includeReplies = false) {
  return {
    likes: row.likes.length,
    liked: Boolean(viewerId) && row.likes.includes(viewerId),
    views: row.view_count,
    replies: row.replies.length,
    ...(includeReplies ? { items: row.replies } : {}),
  };
}

// A reply keeps the avatar it was written with. The thread has to show the
// member's current photo, so it is resolved again when the conversation is read.
async function refreshReplyAvatars(env, summary) {
  if (!summary || !Array.isArray(summary.items) || !summary.items.length) return summary;
  const ids = [...new Set(
    summary.items.map(item => String(item.author_id || "")).filter(id => /^\d{15,25}$/.test(id))
  )].slice(0, 12);
  if (!ids.length) return summary;
  const fresh = new Map();
  await Promise.all(ids.map(async id => {
    const resolved = await ensureDiscordUserProfile(env, id).catch(() => null);
    if (!resolved || !resolved.user) return;
    const url = profileAvatarUrl(id, resolved.user.avatar || resolved.user.avatar_url);
    if (url) fresh.set(id, url);
  }));
  if (!fresh.size) return summary;
  summary.items = summary.items.map(item => {
    const url = fresh.get(String(item.author_id || ""));
    return url ? { ...item, author: { ...(item.author || {}), avatar: url } } : item;
  });
  return summary;
}

// ── Upload announcements share the leak's numbers ─────────────────────────────
// The leak page keeps views/likes in the preset stats document and its conversation in
// the comment store, so an announcement post reads and writes those same records.
async function resolveNoticeProductId(env, postId) {
  if (!/^[a-f0-9-]{16,40}$/i.test(String(postId || ""))) return "";
  const notice = await readNoticePost(env, postId).catch(() => null);
  return notice && notice.product_id ? String(notice.product_id) : "";
}

// Leak comments carry their media as markdown, the feed thread expects a media list.
function splitLeakCommentMedia(content) {
  const media = [];
  const text = String(content || "")
    .replace(/!\[[^\]]*\]\((https:\/\/[^\s)]+)\)/gi, (match, url) => { media.push(url); return ""; })
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  return { text, media: media.slice(0, 4) };
}

function leakCommentToReply(comment) {
  const userId = String(comment.user_id || "");
  const avatar = stableAvatarUrl(comment.user_avatar);
  const { text, media } = splitLeakCommentMedia(comment.content);
  const created = Date.parse(String(comment.created_at || "").replace(" ", "T"));
  return {
    id: String(comment.id || ""),
    author_id: userId,
    author: {
      name: String(comment.user_name || "Zyrex Member").slice(0, 80),
      handle: "",
      avatar: avatar || "/assets/default-avatar.png",
      url: /^\d{15,25}$/.test(userId) ? `/profile?id=${encodeURIComponent(userId)}` : "/profile",
    },
    text,
    media,
    created_at: Number.isFinite(created) ? new Date(created).toISOString() : new Date(0).toISOString(),
    parent_id: comment.parent_id ? String(comment.parent_id) : "",
  };
}

function flattenLeakComments(list) {
  const rows = [];
  for (const comment of Array.isArray(list) ? list : []) {
    if (!comment || typeof comment !== "object") continue;
    rows.push(leakCommentToReply(comment));
    for (const child of Array.isArray(comment.replies) ? comment.replies : []) {
      if (child && typeof child === "object") rows.push(leakCommentToReply(child));
    }
  }
  return rows.sort((a, b) => String(a.created_at).localeCompare(String(b.created_at)));
}

async function leakInteractionSummary(env, productId, viewerId = "", includeItems = false) {
  const id = String(productId || "").trim();
  if (!id) return { likes: 0, liked: false, views: 0, replies: 0, ...(includeItems ? { items: [] } : {}) };
  const [stats, stored, row] = await Promise.all([
    dbGetPresetStats(env, id).catch(() => ({ views: 0, downloads: 0, likes: 0 })),
    dbGetPresetComments(env, id).catch(() => []),
    resourceInteractionRow(env, id),
  ]);
  const items = flattenLeakComments(stored);
  return {
    likes: row.likes.length,
    liked: Boolean(viewerId) && row.likes.includes(viewerId),
    views: Math.max(0, Number(stats.views) || 0),
    replies: items.length,
    ...(includeItems ? { items } : {}),
  };
}

async function resourceInteractionRow(env, productId) {
  const stored = await r2GetJSON(env, socialInteractionKey("resource", productId), null).catch(() => null);
  return sanitizeSocialInteraction(stored || emptySocialInteraction());
}

// The preset stats document powers /api/presets/stats, so like counts mirror there too.
async function writePresetLikeCount(env, productId, likes) {
  const stats = await dbGetStats(env);
  if (!stats[productId]) stats[productId] = { views: 0, downloads: 0, likes: 0 };
  stats[productId].likes = Math.max(0, Number(likes) || 0);
  await r2PutJSON(env, DB.STATS, stats).catch(() => false);
  return stats[productId];
}

async function socialViewerFingerprint(request, session, env) {
  const secret = String(env?.DOWNLOAD_TOKEN_SECRET || env?.ZYREX_API_KEY || "");
  const identity = session?.userId
    ? `member:${session.userId}`
    : `visitor:${secret}:${request.headers.get("CF-Connecting-IP") || "unknown"}:${request.headers.get("User-Agent") || ""}`;
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(identity));
  return Array.from(new Uint8Array(digest).slice(0, 16), byte => byte.toString(16).padStart(2, "0")).join("");
}

async function searchProfiles(env, query, limit = 12) {
  const q = String(query || "").trim().toLowerCase();
  if (q.length < 2) return [];
  const [index, catalog] = await Promise.all([
    readHandleIndex(env),
    dbReadProductCatalog(env).catch(() => []),
  ]);
  const owners = buildProfileIdentityMap(catalog);
  const max = Math.min(Math.max(Number(limit) || 12, 1), 30);
  const profiles = [];
  for (const entry of Object.values((index && index.handles) || {})) {
    if (!entry || !entry.id) continue;
    const handle = String(entry.handle || "");
    const identity = owners.get(String(entry.id)) || {};
    const name = identity.name || "";
    if (!handle.includes(q) && !name.toLowerCase().includes(q) && !String(entry.id).includes(q)) continue;
    profiles.push({
      id: String(entry.id),
      handle,
      url: `/@${handle}`,
      name: name || handle,
      avatar: profileAvatarUrl(String(entry.id), identity.avatar),
    });
  }
  // Search results are profile cards, so non-members never appear in them.
  const members = await filterGuildMembers(env, profiles);
  return members.slice(0, max);
}

// ── Access control console ─────────────────────────────────────────────────────
// One page that answers "who can reach what, and why" without reading R2 by hand.
// The picture is assembled from every source a download decision consults, so the
// console can never disagree with the gates it describes.
const ACCESS_FILTERS = ["all", "revoked", "verified", "unverified", "uploaders", "pass", "adfree", "downloaders"];

function accessNowStamp() {
  return new Date().toISOString();
}

// Listing gives keys only, so the expiry of each stored pass needs a read. The map is
// memoized briefly because the console and the dossier both want it.
const ACCESS_PASS_MEMO_MS = 20 * 1000;
let accessPassMemo = { at: 0, value: null };

async function readActivePasses(env) {
  if (accessPassMemo.value && Date.now() - accessPassMemo.at < ACCESS_PASS_MEMO_MS) {
    return accessPassMemo.value;
  }
  const passes = {};
  try {
    const listed = await env.STORAGE.list({ prefix: RESOURCE_ACCESS_PATH, limit: 1000 });
    await Promise.all((listed.objects || []).map(async object => {
      const id = String(object.key || "").slice(RESOURCE_ACCESS_PATH.length);
      if (!/^\d{15,25}$/.test(id)) return;
      try {
        const stored = await r2GetJSON(env, object.key, null);
        if (stored && Number(stored.expires_at) > 0) passes[id] = stored;
      } catch (_) {}
    }));
  } catch (_) {}
  accessPassMemo = { at: Date.now(), value: passes };
  return passes;
}

function invalidateAccessPassMemo() {
  accessPassMemo = { at: 0, value: null };
}

// Assembles every member the console can say something about, once per request. The
// caller filters this in memory so search and filter changes cost nothing.
async function buildAccessRoster(env) {
  const [revokedUsers, snapshot, team, uploadersDoc, downloadUsers, catalog, passes] = await Promise.all([
    readRevocationUsers(env).catch(() => ({})),
    readRoleSnapshotRoles(env).catch(() => ({})),
    dbGetTeam(env).catch(() => ({})),
    r2GetJSON(env, DB.UPLOADERS, { uploaders: [] }).catch(() => ({ uploaders: [] })),
    r2GetJSON(env, "logs/download-users.json", {}).catch(() => ({})),
    dbReadProductCatalog(env).catch(() => []),
    readActivePasses(env).catch(() => ({})),
  ]);

  const roleMembers = roleId => new Set(
    (((snapshot || {})[roleId] || {}).ids || []).map(String)
  );
  const verifiedIds = roleMembers(VERIFIED_ROLE_ID);
  const adFreeIds = new Set();
  for (const roleId of AD_FREE_ROLE_IDS) for (const id of roleMembers(roleId)) adFreeIds.add(id);

  const uploaderRoleOf = {};
  for (const roleId of COMMUNITY_UPLOADER_ROLE_IDS) {
    for (const id of roleMembers(roleId)) uploaderRoleOf[id] = roleId;
  }
  const storedUploaders = new Set((uploadersDoc.uploaders || []).map(String));

  const teamGroup = id => {
    for (const group of ["founders", "staff", "contributors"]) {
      if ((team[group] || []).some(item => String((item && item.id) || item || "") === id)) return group;
    }
    return "";
  };

  // Identity plus resource counts, taken from the catalogue so no Discord read is needed.
  // The counts use the same ownership rule as the member profiles.
  const identity = buildProfileIdentityMap(catalog);
  const resourcesByOwner = profileOwnedResourceCounts(catalog);
  const handles = invertHandleIndex(await readHandleIndex(env).catch(() => null));
  const now = Date.now();

  const ids = new Set([
    ...Object.keys(revokedUsers || {}),
    ...verifiedIds,
    ...adFreeIds,
    ...Object.keys(uploaderRoleOf),
    ...storedUploaders,
    ...Object.keys(passes),
    ...Object.keys(downloadUsers || {}),
  ]);
  for (const group of ["founders", "staff", "contributors"]) {
    for (const item of team[group] || []) {
      const id = String((item && item.id) || item || "");
      if (id) ids.add(id);
    }
  }

  const rows = [];
  for (const id of ids) {
    if (!/^\d{15,25}$/.test(id)) continue;
    const revocation = (revokedUsers || {})[id] || null;
    const pass = passes[id] || null;
    const log = (downloadUsers || {})[id] || null;
    const who = identity.get(id) || {};
    const group = teamGroup(id);
    const isUploader = Boolean(uploaderRoleOf[id]) || storedUploaders.has(id) || group === "founders" || group === "staff" || group === "contributors";
    const tier = group === "founders" ? "founder"
      : group === "staff" ? "staff"
      : group === "contributors" ? "contributor"
      : uploaderRoleOf[id] ? "uploader"
      : (resourcesByOwner.get(id) ? "creator" : "member");
    const tierInfo = PROFILE_TIERS[tier] || PROFILE_TIERS.member;

    rows.push({
      id,
      name: who.name || (log && (log.display_name || log.username)) || id,
      // False when the label is just the raw id, so the console knows it should try
      // to resolve a real name before showing the row.
      name_resolved: Boolean(who.name || (log && (log.display_name || log.username))),
      username: (log && log.username) || "",
      avatar: profileAvatarUrl(id, who.avatar || (log && log.user_avatar)),
      handle: handles[id] || "",
      tier,
      tier_label: tierInfo.label,
      tier_icon: tierInfo.icon,
      accent: tierInfo.accent,
      verified: verifiedIds.has(id),
      ad_free: adFreeIds.has(id),
      uploader: isUploader,
      uploader_role_id: uploaderRoleOf[id] || "",
      upload_source: uploaderRoleOf[id] ? "role" : (storedUploaders.has(id) ? "list" : (group ? "team" : "")),
      pass_active: Boolean(pass && Number(pass.expires_at) > now),
      pass_expires_at: pass ? Number(pass.expires_at) : null,
      pass_source: pass ? String(pass.source || "") : "",
      revoked: Boolean(revocation),
      revoke_reason: revocation ? String(revocation.reason || "") : "",
      revoke_reason_label: revocation ? (REVOKE_REASON_LABELS[revocation.reason] || revocation.reason) : "",
      revoked_at: revocation ? Number(revocation.revoked_at) || 0 : 0,
      revoke_source: revocation ? String(revocation.source || "") : "",
      downloads: log ? Number(log.count) || 0 : 0,
      first_download_at: (log && log.first_at) || null,
      last_download_at: (log && log.last_at) || null,
      resources: resourcesByOwner.get(id) || 0,
      // A member with no verified role, no pass and no upload rights cannot download.
      can_download_now: !revocation && verifiedIds.has(id),
    });
  }

  rows.sort((a, b) => {
    if (a.revoked !== b.revoked) return a.revoked ? -1 : 1;
    if (b.downloads !== a.downloads) return b.downloads - a.downloads;
    return String(a.name).localeCompare(String(b.name));
  });

  return { rows, snapshot, passes, verifiedIds, adFreeIds, revokedUsers, team, now };
}

// A revoked member often has no catalogue, log or team record, so the roster can only
// show their id. Resolving a real name is what makes the console usable for support,
// so the visible page is enriched: the R2 cache is free, and a Discord lookup happens
// at most once per member and is then cached for a week.
const ACCESS_NAME_LOOKUPS_PER_REQUEST = 25;

async function enrichAccessNames(env, rows) {
  const targets = rows.filter(row => !row.name_resolved);
  if (!targets.length) return;

  // Cache reads first: these cost nothing and usually answer for anyone who has ever
  // signed in.
  const cached = await Promise.all(targets.map(row => getCachedDiscordUser(env, row.id).catch(() => null)));
  cached.forEach((user, index) => {
    if (!user) return;
    const name = user.global_name || user.display_name || user.username || "";
    if (!name) return;
    const row = targets[index];
    row.name = String(name);
    row.username = row.username || String(user.username || "");
    row.avatar = profileAvatarUrl(row.id, user.avatar || "");
    row.name_resolved = true;
  });

  const missing = targets.filter(row => !row.name_resolved).slice(0, ACCESS_NAME_LOOKUPS_PER_REQUEST);
  if (!missing.length) return;

  // Writes a resolved name onto the row and caches it, so the next viewer pays nothing.
  const applyUser = async (row, user, nickname) => {
    const name = nickname || (user && (user.global_name || user.display_name || user.username)) || "";
    if (!name) return false;
    row.name = String(name);
    row.username = row.username || String((user && user.username) || "");
    row.avatar = profileAvatarUrl(row.id, (user && user.avatar) || "");
    row.name_resolved = true;
    await setCachedDiscordUser(env, row.id, {
      id: String((user && user.id) || row.id),
      username: (user && user.username) || "",
      display_name: String(name),
      global_name: (user && user.global_name) || "",
      avatar: (user && user.avatar) || "",
    }).catch(() => {});
    return true;
  };

  await Promise.all(missing.map(async row => {
    // The worker's own bot token cannot always read a member — it may belong to a
    // different bot than the one in the guild — so the VPS bot relay is the fallback
    // that resolves names in production.
    if (env?.DISCORD_BOT_TOKEN) {
      try {
        const response = await fetch(`${DISCORD_API}/guilds/${env.GUILD_ID || "1518954946110685184"}/members/${encodeURIComponent(row.id)}`, {
          headers: { Authorization: `Bot ${env.DISCORD_BOT_TOKEN}` },
          signal: AbortSignal.timeout(3500),
        });
        if (response.ok) {
          const member = await response.json();
          if (await applyUser(row, member.user || {}, member.nick || "")) return;
        }
      } catch (_) {}
    }
    try {
      const response = await fetch(`${BOT_API}/api/discord-user?userId=${encodeURIComponent(row.id)}`, {
        signal: AbortSignal.timeout(2000),
      });
      if (!response.ok) return;
      const payload = await response.json();
      if (payload && payload.user) await applyUser(row, payload.user, "");
    } catch (_) {}
  }));
}

function filterAccessRows(rows, options) {  const filter = ACCESS_FILTERS.includes(options.filter) ? options.filter : "all";
  const query = String(options.query || "").trim().toLowerCase();
  return rows.filter(row => {
    if (filter === "revoked" && !row.revoked) return false;
    if (filter === "verified" && !row.verified) return false;
    if (filter === "unverified" && row.verified) return false;
    if (filter === "uploaders" && !row.uploader) return false;
    if (filter === "pass" && !row.pass_active) return false;
    if (filter === "adfree" && !row.ad_free) return false;
    if (filter === "downloaders" && row.downloads <= 0) return false;
    if (!query) return true;
    return row.id.includes(query)
      || row.name.toLowerCase().includes(query)
      || String(row.username || "").toLowerCase().includes(query)
      || String(row.handle || "").toLowerCase().includes(query);
  });
}

function summarizeAccessRoster(roster) {
  const rows = roster.rows;
  const snapshotRoles = roster.snapshot || {};
  const snapshotAge = roleId => {
    const updatedAt = Number(((snapshotRoles[roleId] || {}).updated_at) || 0);
    return updatedAt ? Date.now() - updatedAt : null;
  };
  return {
    members: rows.length,
    verified: rows.filter(row => row.verified).length,
    revoked: rows.filter(row => row.revoked).length,
    uploaders: rows.filter(row => row.uploader).length,
    ad_free: rows.filter(row => row.ad_free).length,
    active_passes: rows.filter(row => row.pass_active).length,
    downloaders: rows.filter(row => row.downloads > 0).length,
    blocked_verified: rows.filter(row => row.verified && row.revoked).length,
    snapshot: {
      verified_role_id: VERIFIED_ROLE_ID,
      verified_count: (snapshotRoles[VERIFIED_ROLE_ID] || {}).ids ? (snapshotRoles[VERIFIED_ROLE_ID].ids || []).length : 0,
      verified_age_ms: snapshotAge(VERIFIED_ROLE_ID),
      uploader_roles: COMMUNITY_UPLOADER_ROLE_IDS.map(roleId => ({
        role_id: roleId,
        count: ((snapshotRoles[roleId] || {}).ids || []).length,
        age_ms: snapshotAge(roleId),
      })),
      ad_free_roles: AD_FREE_ROLE_IDS.map(roleId => ({
        role_id: roleId,
        count: ((snapshotRoles[roleId] || {}).ids || []).length,
        age_ms: snapshotAge(roleId),
      })),
      stale_after_ms: ROLE_SNAPSHOT_STALE_MS,
      fresh_window_ms: ROLE_SNAPSHOT_FRESH_MS,
    },
    revoke_reasons: REVOKE_REASON_LABELS,
    built_at: accessNowStamp(),
  };
}

// The dossier answers "why is this member where they are" for one id.
async function buildAccessDossier(env, discordId) {
  const id = String(discordId || "").trim();
  if (!/^\d{15,25}$/.test(id)) return null;
  const roster = await buildAccessRoster(env);
  const row = roster.rows.find(item => item.id === id) || null;
  // The roster never resolves display names, so the dossier resolves its single row
  // here; otherwise it shows a bare id for anyone the overview page would have named.
  if (row) await enrichAccessNames(env, [row]);
  const [grants, revocationRecord, liveVerified, liveAdFree, liveUploader, diagnostics] = await Promise.all([
    readUserGrants(env, id).catch(() => []),
    r2GetJSON(env, ROLE_REVOCATIONS_KEY, null).catch(() => null),
    checkVerifiedRole(id, env).catch(() => null),
    checkAdFreeRole(id, env).catch(() => false),
    hasCommunityUploaderRole(id, env).catch(() => false),
    listDiagnosticsFor(env, id).catch(() => []),
  ]);

  const completed = grants.filter(item => item && item.completed_at).length;
  return {
    member: row || {
      id,
      name: id,
      avatar: profileAvatarUrl(id, ""),
      handle: "",
      tier: "member",
      tier_label: (PROFILE_TIERS.member || {}).label || "Member",
    },
    checks: {
      revoked: Boolean((roster.revokedUsers || {})[id]),
      revocation: (roster.revokedUsers || {})[id] || null,
      snapshot_verified: roster.verifiedIds.has(id),
      live_verified: liveVerified,
      snapshot_ad_free: roster.adFreeIds.has(id),
      live_ad_free: liveAdFree,
      snapshot_uploader_role: row ? row.uploader_role_id : "",
      live_uploader: liveUploader,
      pass_active: Boolean(row && row.pass_active),
      pass_expires_at: row ? row.pass_expires_at : null,
      can_download_now: Boolean(row && row.can_download_now),
    },
    attempts: {
      total: grants.length,
      completed,
      unfinished: grants.length - completed,
      recent: grants.slice(0, 12),
    },
    diagnostics,
    revocation_document: revocationRecord ? { keys: Object.keys(revocationRecord), updated_at: revocationRecord.updated_at || null } : null,
    built_at: accessNowStamp(),
  };
}

// Diagnostics reports are stored newest-first under a timestamped key, so the member
// id has to be read from the body. Only the tail is inspected.
async function listDiagnosticsFor(env, discordId, limit = 5) {
  const out = [];
  try {
    const listed = await env.STORAGE.list({ prefix: "diagnostics/access/", limit: 200 });
    const objects = (listed.objects || []).slice(-60);
    for (const object of objects) {
      try {
        const report = await r2GetJSON(env, object.key, null);
        if (!report || !report.user || String(report.user.discord_id) !== discordId) continue;
        out.push({
          id: report.id,
          created_at: report.created_at,
          symptom: report.symptom || "",
          verdict: report.verdict || "",
          access: report.access || null,
        });
      } catch (_) {}
    }
  } catch (_) {}
  return out.sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || ""))).slice(0, limit);
}

// ── Product overrides ──────────────────────────────────────────────────────────
// The plugin catalogue is shipped inside js/plugins-data.js, so it has no server row to
// edit. The admin panel stores a patch per product id in R2 instead; the API applies it to
// its own responses and js/product-overrides.js applies the same patch to the static
// bundle, so one save changes every page without a deploy.
const PRODUCT_OVERRIDES_KEY = "database/product_overrides.json";
const PRODUCT_AUDIT_KEY = "database/product_audit.json";
const PRODUCT_OVERRIDE_FIELDS = new Set([
  "name", "title", "label", "category", "platform", "description", "desc", "notes", "password",
  "zip_password", "thumbnail", "file_size", "version", "release_date", "links", "type",
  "resource_category", "resource_subcategories", "source_url", "product_url", "banner",
  "origin", "rating", "imdb_rating", "hidden", "sort_order",
]);
let productOverridesMemo = null;

async function readProductOverrides(env, options = {}) {
  const now = Date.now();
  const fresh = options && options.fresh === true;
  if (!fresh && productOverridesMemo && now - productOverridesMemo.at < 15000) {
    return productOverridesMemo.value;
  }
  const stored = await r2GetJSON(env, PRODUCT_OVERRIDES_KEY, null).catch(() => null);
  const doc = {
    version: Number(stored && stored.version) || 0,
    updated_at: (stored && stored.updated_at) || null,
    items: stored && stored.items && typeof stored.items === "object" ? stored.items : {},
  };
  productOverridesMemo = { at: now, value: doc };
  return doc;
}

async function writeProductOverrides(env, doc) {
  const payload = { version: doc.version, updated_at: doc.updated_at, items: doc.items };
  const saved = await r2PutJSON(env, PRODUCT_OVERRIDES_KEY, payload).catch(() => false);
  productOverridesMemo = null;
  return Boolean(saved);
}

function sanitizeOverridePatch(raw) {
  const patch = {};
  if (!raw || typeof raw !== "object") return patch;
  for (const [key, value] of Object.entries(raw)) {
    if (!PRODUCT_OVERRIDE_FIELDS.has(key)) continue;
    if (key === "links") {
      if (!Array.isArray(value)) continue;
      patch.links = value
        .map(link => (typeof link === "string" ? { url: link, label: "Download" } : {
          url: String((link && link.url) || "").trim(),
          label: String((link && link.label) || "Download").trim().slice(0, 60) || "Download",
        }))
        .filter(link => /^https?:\/\//i.test(link.url))
        .slice(0, 12);
      continue;
    }
    if (key === "resource_subcategories" && Array.isArray(value)) {
      patch[key] = value.map(item => String(item).trim()).filter(Boolean).slice(0, 20);
      continue;
    }
    if (typeof value === "string") {
      const limit = key === "description" ? 20000 : 2000;
      patch[key] = value.slice(0, limit);
      continue;
    }
    if (typeof value === "number" || typeof value === "boolean" || value === null) {
      patch[key] = value;
    }
  }
  if (patch.title && patch.name === undefined) patch.name = patch.title;
  if (patch.name && patch.title === undefined) patch.title = patch.name;
  if (patch.zip_password && patch.password === undefined) patch.password = patch.zip_password;
  if (patch.password && patch.zip_password === undefined) patch.zip_password = patch.password;
  return patch;
}

function applyProductOverride(product, entry) {
  if (!product) return product;
  const patch = (entry && entry.patch) || {};
  const merged = { ...product, ...patch };
  // Cards render "name", the product page renders "title"; keep the pair in sync.
  if (patch.title && patch.name === undefined) merged.name = patch.title;
  if (patch.name && patch.title === undefined) merged.title = patch.name;
  if (patch.password && patch.zip_password === undefined) merged.zip_password = patch.password;
  if (patch.zip_password && patch.password === undefined) merged.password = patch.zip_password;
  if (patch.description && patch.desc === undefined) merged.desc = patch.description;
  if (patch.desc && patch.description === undefined) merged.description = patch.desc;
  merged.id = product.id;
  merged.overridden = true;
  merged.override_updated_at = (entry && entry.updated_at) || null;
  return merged;
}

async function applyProductOverridesToProducts(env, list) {
  if (!Array.isArray(list)) return list;
  const doc = await readProductOverrides(env).catch(() => null);
  const items = (doc && doc.items) || {};
  if (!Object.keys(items).length) return list;
  const output = [];
  for (const product of list) {
    const entry = product && product.id ? items[product.id] : null;
    if (entry && (entry.deleted === true || entry.hidden === true)) continue;
    output.push(entry ? applyProductOverride(product, entry) : product);
  }
  return output;
}

const DATA_EXPORT_PREFIX = "profiles/data-exports/";
const DATA_EXPORT_TTL_MS = 48 * 60 * 60 * 1000;
const DATA_REQUEST_PREFIX = "profiles/data-requests/";

function toBase64Url(bytes) {
  let binary = "";
  for (let offset = 0; offset < bytes.length; offset += 0x8000) {
    binary += String.fromCharCode(...bytes.subarray(offset, Math.min(offset + 0x8000, bytes.length)));
  }
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

function fromBase64Url(value) {
  const raw = String(value || "").replace(/-/g, "+").replace(/_/g, "/");
  return Uint8Array.from(atob(raw + "=".repeat((4 - raw.length % 4) % 4)), c => c.charCodeAt(0));
}

function exportKeyBytes(env) {
  const secret = String(env?.SESSION_SECRET || "");
  if (secret.length < 32) throw new Error("Session encryption key is unavailable");
  return crypto.subtle.digest("SHA-256", new TextEncoder().encode("zyrex-data-export-v1:" + secret));
}

async function sealExportToken(env, value) {
  const keyBytes = await exportKeyBytes(env);
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: "AES-GCM" }, false, ["encrypt"]);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const encrypted = new Uint8Array(await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, new TextEncoder().encode(JSON.stringify(value))));
  const packed = new Uint8Array(iv.length + encrypted.length);
  packed.set(iv); packed.set(encrypted, iv.length);
  return toBase64Url(packed);
}

async function openExportToken(env, token) {
  const bytes = fromBase64Url(token);
  if (bytes.length < 29 || bytes.length > 4096) throw new Error("Invalid export token");
  const keyBytes = await exportKeyBytes(env);
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: "AES-GCM" }, false, ["decrypt"]);
  const plain = await crypto.subtle.decrypt({ name: "AES-GCM", iv: bytes.slice(0, 12) }, key, bytes.slice(12));
  return JSON.parse(new TextDecoder().decode(plain));
}

async function encryptExportPackage(env, value) {
  const keyBytes = await exportKeyBytes(env);
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: "AES-GCM" }, false, ["encrypt"]);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const cipher = new Uint8Array(await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, new TextEncoder().encode(JSON.stringify(value))));
  const packed = new Uint8Array(iv.length + cipher.length);
  packed.set(iv); packed.set(cipher, iv.length);
  return toBase64Url(packed);
}

async function decryptExportPackage(env, value) {
  const bytes = fromBase64Url(value);
  const keyBytes = await exportKeyBytes(env);
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: "AES-GCM" }, false, ["decrypt"]);
  const plain = await crypto.subtle.decrypt({ name: "AES-GCM", iv: bytes.slice(0, 12) }, key, bytes.slice(12));
  return JSON.parse(new TextDecoder().decode(plain));
}

function redactExportProduct(product) {
  const safe = { ...product };
  for (const key of ["sftpgo_password", "password", "zip_password", "private_key", "token"]) delete safe[key];
  return safe;
}

function collectUserComments(comments, userId) {
  const found = [];
  const walk = rows => {
    for (const row of Array.isArray(rows) ? rows : []) {
      if (String(row?.user_id || row?.author_id || "") === userId) found.push(row);
      walk(row?.replies);
    }
  };
  for (const rows of Object.values(comments || {})) walk(rows);
  return found;
}

async function buildAccountExport(env, userId) {
  const id = String(userId || "");
  const [profile, posts, follows, followPrefs, achievements, commentsDoc, catalog, pass, grants, downloadIndex, diagnostics, requests, feedNotices, notificationDoc] = await Promise.all([
    r2GetJSON(env, profileSettingsKey(id), null),
    readProfilePosts(env, id).catch(() => []),
    r2GetJSON(env, profileFollowsKey(id), { following: [], followers: [] }),
    readFollowPrefs(env, id).catch(() => null),
    r2GetJSON(env, profileAchievementsKey(id), []),
    r2GetJSON(env, DB.COMMENTS, {}),
    dbReadProductCatalog(env).catch(() => []),
    getDownloadAccess(env, id).catch(() => null),
    readUserGrants(env, id).catch(() => []),
    r2GetJSON(env, DL_ARCHIVE.USER_INDEX_PREFIX + id + ".json", []),
    listDiagnosticsFor(env, id, 100).catch(() => []),
    listProfileDataRequests(env, id),
    readFeedNotifications(env, id),
    r2GetJSON(env, "database/notifications.json", []),
  ]);
  const downloads = (await Promise.all((Array.isArray(downloadIndex) ? downloadIndex : []).map(summary =>
    summary?.key ? r2GetJSON(env, summary.key, null).catch(() => null) : null
  ))).filter(Boolean);
  const personalNotifications = (Array.isArray(notificationDoc) ? notificationDoc : []).filter(item =>
    String(item?.user_id || item?.discord_id || "") === id
  );
  let bot = { available: false, error: "Bot data endpoint is not configured or unavailable." };
  try {
    const response = await fetch(`${BOT_API}/api/account/export/${encodeURIComponent(id)}`, {
      headers: { "X-Zyrex-Service": String(env?.BOT_SERVICE_TOKEN || "") },
      signal: AbortSignal.timeout(10000),
    });
    if (response.ok) bot = await response.json();
  } catch (_) {}
  return {
    schema_version: 1,
    exported_at: new Date().toISOString(),
    discord_id: id,
    sources: ["zyrex-worker-r2", ...(bot.available ? ["zyrex-bot"] : [])],
    account: { profile, posts, follows, follow_preferences: followPrefs, achievements, notifications: { feed: feedNotices, site: personalNotifications }, diagnostics, data_requests: requests },
    access: { pass, offer_claims: grants, downloads },
    submitted_resources: (Array.isArray(catalog) ? catalog : []).filter(item => [item.uploader_id, item.author_id, item.credited_uploader_id].some(value => String(value || "") === id)).map(redactExportProduct),
    community_comments: collectUserComments(commentsDoc, id),
    discord_bot: bot,
  };
}

async function listProfileDataRequests(env, userId) {
  const id = String(userId || "");
  const listed = await env.STORAGE.list({ prefix: DATA_REQUEST_PREFIX + id + "/", limit: 100 }).catch(() => ({ objects: [] }));
  const rows = await Promise.all((listed.objects || []).map(item => r2GetJSON(env, item.key, null).catch(() => null)));
  return rows.filter(Boolean).sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || "")));
}

async function findDataRequest(env, requestId) {
  const listed = await env.STORAGE.list({ prefix: DATA_REQUEST_PREFIX, limit: 1000 }).catch(() => ({ objects: [] }));
  const records = await Promise.all((listed.objects || []).map(async object => ({
    key: object.key,
    record: await r2GetJSON(env, object.key, null).catch(() => null),
  })));
  return records.find(item => item.record && String(item.record.id) === String(requestId)) || null;
}

async function appendProductAudit(env, entry) {
  const stored = await r2GetJSON(env, PRODUCT_AUDIT_KEY, []).catch(() => []);
  const rows = Array.isArray(stored) ? stored : [];
  rows.unshift(entry);
  await r2PutJSON(env, PRODUCT_AUDIT_KEY, rows.slice(0, 200)).catch(() => false);
}

async function saveProductOverride(env, productId, rawPatch, options = {}) {
  const doc = await readProductOverrides(env, { fresh: true });
  const existing = doc.items[productId] || null;
  const expected = options.expectedUpdatedAt;
  if (expected !== undefined && expected !== null && expected !== "") {
    const current = String((existing && existing.updated_at) || "");
    if (current !== String(expected)) {
      return { stale: true, entry: existing, version: doc.version };
    }
  }
  const patch = options.replace === true
    ? sanitizeOverridePatch(rawPatch)
    : { ...((existing && existing.patch) || {}), ...sanitizeOverridePatch(rawPatch) };
  const entry = {
    patch,
    hidden: options.hidden === undefined ? Boolean(existing && existing.hidden) : Boolean(options.hidden),
    deleted: options.deleted === undefined ? Boolean(existing && existing.deleted) : Boolean(options.deleted),
    order: options.order === undefined ? ((existing && existing.order) || null) : options.order,
    updated_at: new Date().toISOString(),
    updated_by: options.actor || "master",
  };
  doc.items[productId] = entry;
  doc.version = (Number(doc.version) || 0) + 1;
  doc.updated_at = entry.updated_at;
  const saved = await writeProductOverrides(env, doc);
  if (!saved) return { saved: false, entry, version: doc.version };
  await appendProductAudit(env, {
    at: entry.updated_at,
    actor: entry.updated_by,
    id: productId,
    action: options.action || "update",
    changed: Object.keys(entry.patch || {}),
    before: existing,
  });
  return { saved: true, entry, version: doc.version, previous: existing };
}

async function clearProductOverride(env, productId, actor) {
  const doc = await readProductOverrides(env, { fresh: true });
  if (!doc.items[productId]) return { saved: true, removed: false, version: doc.version };
  const previous = doc.items[productId];
  delete doc.items[productId];
  doc.version = (Number(doc.version) || 0) + 1;
  doc.updated_at = new Date().toISOString();
  const saved = await writeProductOverrides(env, doc);
  if (saved) {
    await appendProductAudit(env, {
      at: doc.updated_at, actor: actor || "master", id: productId, action: "restore", before: previous,
    });
  }
  return { saved, removed: true, version: doc.version };
}

/* ═══════════════════════════════════════════════════════════════════════════
   SCENEPACKS
   The retired `scenepack` product type left this catalogue without a home, so
   it owns a dedicated R2 document instead of piggy-backing on the resource
   catalogue. Every scenepack is a movie/series clip pack: IMDb metadata, one
   or more downloadable versions, and its own moderation state.
   ═══════════════════════════════════════════════════════════════════════════ */

const SCENEPACKS_R2_KEY = "scenepacks/data.json";
const SCENEPACK_VIEW_MEMO_TTL = 30 * 60 * 1000;
const SCENEPACK_VIEW_MEMO_MAX = 4000;
const scenepackViewMemo = new Map();

const SCENEPACK_TYPE_LABELS = { movie: "Movie", series: "Series", anime: "Anime", game: "Game" };
const SCENEPACK_QUALITY_OPTIONS = ["4K", "2160p", "1440p", "1080p", "720p", "480p", "Mixed"];
const SCENEPACK_ACCESS_MODES = ["free"];
const SCENEPACK_STATUSES = ["published", "pending", "rejected", "draft"];

// IMDb serves a tiny poster by default; asking for a wider crop keeps the card
// grid and the detail hero sharp without storing anything ourselves.
function imdbHiResPoster(raw, width = 800) {
  const url = String(raw || "").trim();
  if (!url) return "";
  if (!/m\.media-amazon\.com/i.test(url)) return url;
  return url.replace(/\._V1_.*$/i, `._V1_FMjpg_UX${width}_.jpg`);
}

function scenepackText(value, max = 300) {
  return String(value == null ? "" : value)
    .replace(/[\u0000-\u001f\u007f]/g, " ")
    .trim()
    .slice(0, max);
}

function scenepackUrl(value) {
  const raw = String(value || "").trim();
  if (!raw || raw.length > 2000) return "";
  if (!/^https?:\/\//i.test(raw)) return "";
  try {
    const parsed = new URL(raw);
    return parsed.protocol === "https:" || parsed.protocol === "http:" ? parsed.toString() : "";
  } catch (_) {
    return "";
  }
}

function scenepackTags(value) {
  const source = Array.isArray(value) ? value : String(value || "").split(",");
  const out = [];
  for (const entry of source) {
    const tag = scenepackText(entry, 32).replace(/^#+/, "");
    if (!tag) continue;
    if (out.some(existing => existing.toLowerCase() === tag.toLowerCase())) continue;
    out.push(tag);
    if (out.length >= 20) break;
  }
  return out;
}

function scenepackMovieMeta(raw) {
  const src = raw && typeof raw === "object" ? raw : {};
  const genres = (Array.isArray(src.genres) ? src.genres : String(src.genres || "").split(","))
    .map(entry => scenepackText(entry, 40))
    .filter(Boolean)
    .slice(0, 6);
  return {
    title: scenepackText(src.title, 160),
    imdb_id: /^tt\d{7,10}$/i.test(String(src.imdb_id || "")) ? String(src.imdb_id).toLowerCase() : "",
    year: scenepackText(src.year, 14),
    genres,
    rating: scenepackText(src.rating, 8),
    votes: scenepackText(src.votes, 24),
    rated: scenepackText(src.rated, 16),
    runtime: scenepackText(src.runtime, 24),
    plot: scenepackText(src.plot, 2400),
    director: scenepackText(src.director, 240),
    writers: scenepackText(src.writers, 240),
    cast: scenepackText(src.cast, 480),
    language: scenepackText(src.language, 80),
    country: scenepackText(src.country, 80),
    released: scenepackText(src.released, 40),
    awards: scenepackText(src.awards, 240),
    imdb_type: scenepackText(src.imdb_type || src.type, 24),
    poster: imdbHiResPoster(scenepackUrl(src.poster), 600),
    backdrop: imdbHiResPoster(scenepackUrl(src.backdrop || src.poster), 1400),
    // Provenance of the scraped metadata: a stamped record is never re-scraped
    // automatically, so manual corrections stay put.
    scraped_at: scenepackText(src.scraped_at, 32),
    scraped_ver: Number(src.scraped_ver) || 0,
    scraped_from: scenepackText(src.scraped_from, 16),
  };
}

function scenepackDownloadEntries(raw) {
  const source = Array.isArray(raw) ? raw : [];
  const out = [];
  for (const entry of source.slice(0, 10)) {
    if (!entry || typeof entry !== "object") continue;
    const label = scenepackText(entry.label || entry.quality, 60) || `Version ${out.length + 1}`;
    const storage = scenepackStorageDescriptor(entry.storage || {
      kind: entry.storage_kind,
      key: entry.storage_key || entry.path,
      file_id: entry.file_id,
      url: entry.url,
    });
    out.push({
      id: scenepackText(entry.id, 40) || `v${out.length + 1}`,
      label,
      quality: scenepackText(entry.quality, 24),
      size: scenepackText(entry.size, 24),
      // A scenepack is a video file, so an omitted container is read from the
      // stored file name (steve-s2.mp4 → MP4) instead of assumed to be an archive.
      format: scenepackText(entry.format, 16)
        || scenepackFormatFromName((storage && (storage.key || storage.url)) || entry.url || ""),
      provider: scenepackStorageLabel(storage, scenepackText(entry.provider, 24)),
      storage,
      // Direct links keep a copy so older records keep working unchanged.
      url: storage && storage.kind === "direct" ? storage.url : scenepackUrl(entry.url),
    });
  }
  return out;
}

function normalizeScenepackStatus(value, fallback = "pending") {
  const status = String(value || "").toLowerCase();
  return SCENEPACK_STATUSES.includes(status) ? status : fallback;
}

function scenepackSlugFor(title, id) {
  const slug = slugify(title).slice(0, 70);
  return slug || `scenepack-${String(id || Date.now().toString(36)).slice(-8)}`;
}

// Shapes an incoming write into a stored record. `existing` keeps the fields a
// client is not allowed to rewrite (identity, counters, moderation history).
function normalizeScenepackRecord(raw, existing = null) {
  const src = raw && typeof raw === "object" ? raw : {};
  const base = existing && typeof existing === "object" ? existing : {};
  const id = scenepackText(base.id || src.id, 60);
  const movie = scenepackMovieMeta(src.movie || base.movie || {});
  const quality = scenepackText(src.quality, 24) || "1080p";
  const fallbackTitle = [movie.title, quality].filter(Boolean).join(" — ");
  const title = scenepackText(src.title, 180) || scenepackText(base.title, 180) || fallbackTitle || "Untitled scenepack";
  const typeRaw = String(src.type || base.type || "").toLowerCase();
  const type = SCENEPACK_TYPE_LABELS[typeRaw] ? typeRaw : (movie.imdb_type === "series" ? "series" : "movie");
  const downloads = scenepackDownloadEntries(src.downloads !== undefined ? src.downloads : base.downloads);
  const clipCount = Number(src.clip_count !== undefined ? src.clip_count : base.clip_count);
  // The pack container follows the stored files (mp4/mov), never a guessed archive.
  const derivedFormat = downloads.map(entry => entry.format).find(Boolean) || "";
  const formatRaw = scenepackText(src.format !== undefined ? src.format : base.format, 16);
  return {
    ...base,
    id,
    slug: scenepackText(src.slug, 90) || base.slug || scenepackSlugFor(title, id),
    title,
    type,
    description: scenepackText(src.description !== undefined ? src.description : base.description, 6000),
    tags: scenepackTags(src.tags !== undefined ? src.tags : base.tags),
    quality,
    resolution: scenepackText(src.resolution !== undefined ? src.resolution : base.resolution, 24),
    format: formatRaw || derivedFormat || "MP4",
    codec: scenepackText(src.codec !== undefined ? src.codec : base.codec, 24),
    fps: scenepackText(src.fps !== undefined ? src.fps : base.fps, 12),
    clip_count: Number.isFinite(clipCount) && clipCount > 0 ? Math.min(Math.round(clipCount), 10000) : 0,
    duration: scenepackText(src.duration !== undefined ? src.duration : base.duration, 24),
    file_size: scenepackText(src.file_size !== undefined ? src.file_size : base.file_size, 24),
    audio: scenepackText(src.audio !== undefined ? src.audio : base.audio, 80),
    movie,
    character: scenepackText(src.character !== undefined ? src.character : base.character, 90),
    // A character can carry a photo so the title page groups read as people
    // instead of initials, and a category so the page can rank the cast.
    character_avatar: scenepackUrl(src.character_avatar !== undefined ? src.character_avatar : base.character_avatar),
    character_category: scenepackText(src.character_category !== undefined ? src.character_category : base.character_category, 24),
    actor: scenepackText(src.actor !== undefined ? src.actor : base.actor, 90),
    title_key: scenepackText(src.title_key !== undefined ? src.title_key : base.title_key, 120),
    credit_name: scenepackText(src.credit_name !== undefined ? src.credit_name : base.credit_name, 60),
    credit_link: scenepackUrl(src.credit_link !== undefined ? src.credit_link : base.credit_link),
    encoding: scenepackText(src.encoding !== undefined ? src.encoding : base.encoding, 24) || scenepackText(src.codec !== undefined ? src.codec : base.codec, 24),
    downloads,
    // Every scenepack is free to download for verified members: the access pass
    // concept was retired, so a stored "pass" value is normalised away.
    access: "free",
    preview_url: scenepackUrl(src.preview_url !== undefined ? src.preview_url : base.preview_url),
    trailer_url: scenepackUrl(src.trailer_url !== undefined ? src.trailer_url : base.trailer_url),
    thumbnail: scenepackUrl(src.thumbnail !== undefined ? src.thumbnail : base.thumbnail) || movie.poster,
    backdrop: scenepackUrl(src.backdrop !== undefined ? src.backdrop : base.backdrop) || movie.backdrop || movie.poster,
  };
}

function scenepackViewerKey(request, session) {
  if (session && session.userId) return `u:${session.userId}`;
  return `ip:${getClientIp(request) || "unknown"}`;
}

function scenepackStoreDefaults() {
  return { items: [], updated_at: null, seeded: false };
}

async function loadScenepackStore(env) {
  const raw = await r2GetJSON(env, SCENEPACKS_R2_KEY, null);
  const items = Array.isArray(raw) ? raw : (raw && Array.isArray(raw.items) ? raw.items : []);
  // Records written before Drive folders were understood stored a share link as a
  // plain "direct" URL, which streamed the Drive page instead of the video. The
  // download entries are re-derived on read so existing packs heal automatically.
  return {
    items: items.map(item => scenepackRepairItem(item)),
    updated_at: (raw && raw.updated_at) || null,
  };
}

function scenepackRepairItem(item) {
  if (!item || typeof item !== "object") return item;
  const downloads = Array.isArray(item.downloads) ? item.downloads : [];
  if (!downloads.length) return item;
  const repaired = scenepackDownloadEntries(downloads);
  const firstFormat = repaired.map(entry => entry.format).find(Boolean) || "";
  return {
    ...item,
    downloads: repaired,
    format: firstFormat || item.format || "",
    // The access pass was retired; verified membership is the only gate now.
    access: "free",
  };
}

async function persistScenepackStore(env, store) {
  const payload = {
    items: Array.isArray(store.items) ? store.items : [],
    total: Array.isArray(store.items) ? store.items.length : 0,
    updated_at: new Date().toISOString(),
  };
  return r2PutJSON(env, SCENEPACKS_R2_KEY, payload);
}

function scenepackLikeSet(item) {
  return Array.isArray(item && item.likes) ? item.likes : [];
}

// Public projection. Download URLs stay hidden behind an access pass when the
// uploader asked for one, so a `pass` pack never leaks its links to the HTML.
// Streamable entries advertise only that they are ready; the actual SFTPGo
// prefix or Drive file id stays server-side.
function scenepackPublic(item, options = {}) {
  const unlocked = options.unlocked !== false;
  const viewerKey = options.viewerKey || "";
  const likes = scenepackLikeSet(item);
  const downloads = (Array.isArray(item.downloads) ? item.downloads : []).map(entry => {
    const storage = scenepackStoragePublic(entry);
    return {
      id: entry.id,
      label: entry.label,
      quality: entry.quality,
      size: entry.size,
      format: entry.format,
      provider: storage.label || entry.provider,
      storage_kind: storage.kind,
      streamable: storage.ready,
      // A folder version has no single file: the UI asks /files for its clips.
      directory: storage.folder,
      url: storage.kind === "direct" && unlocked ? entry.url : "",
      locked: !unlocked && storage.ready,
    };
  });
  return {
    id: item.id,
    slug: item.slug,
    title: item.title,
    type: item.type,
    type_label: SCENEPACK_TYPE_LABELS[item.type] || "Scenepack",
    status: item.status,
    description: item.description || "",
    tags: Array.isArray(item.tags) ? item.tags : [],
    quality: item.quality || "",
    resolution: item.resolution || "",
    format: item.format || "",
    codec: item.codec || "",
    fps: item.fps || "",
    clip_count: Number(item.clip_count) || 0,
    duration: item.duration || "",
    file_size: item.file_size || "",
    audio: item.audio || "",
    movie: item.movie || scenepackMovieMeta({}),
    character: item.character || "",
    character_avatar: item.character_avatar || "",
    character_category: item.character_category || "",
    actor: item.actor || "",
    credit_name: item.credit_name || (item.uploader_name || ""),
    credit_link: item.credit_link || "",
    encoding: item.encoding || item.codec || "",
    downloads,
    // Downloads are open to verified members; there is no per-pack access pass.
    access: "free",
    locked: !unlocked,
    preview_url: item.preview_url || "",
    trailer_url: item.trailer_url || "",
    thumbnail: item.thumbnail || (item.movie && item.movie.poster) || "",
    backdrop: item.backdrop || item.thumbnail || (item.movie && item.movie.poster) || "",
    uploader: {
      id: item.uploader_id || "",
      name: item.uploader_name || "Zyrex",
      avatar: item.uploader_avatar || "",
    },
    views: Number(item.views) || 0,
    downloads_count: Number(item.downloads_count) || 0,
    like_count: Number(item.like_base || 0) + likes.length,
    liked: Boolean(viewerKey && likes.includes(viewerKey)),
    featured: item.featured === true,
    title_key: item.title_key || "",
    comment_key: `scenepack-${item.id}`,
    created_at: item.created_at || "",
    published_at: item.published_at || "",
    updated_at: item.updated_at || "",
  };
}

function scenepackMatchesQuery(item, query) {
  if (!query) return true;
  const haystack = [
    item.title,
    item.description,
    item.type,
    item.quality,
    item.resolution,
    item.format,
    item.movie && item.movie.title,
    item.movie && item.movie.year,
    item.movie && item.movie.director,
    item.movie && item.movie.cast,
    item.movie && Array.isArray(item.movie.genres) ? item.movie.genres.join(" ") : "",
    Array.isArray(item.tags) ? item.tags.join(" ") : "",
    item.uploader_name,
  ].filter(Boolean).join(" ").toLowerCase();
  return query.split(/\s+/).filter(Boolean).every(term => haystack.includes(term));
}

function scenepackSortValue(sort) {
  switch (String(sort || "").toLowerCase()) {
    case "popular": return (a, b) => (Number(b.downloads_count) || 0) - (Number(a.downloads_count) || 0);
    case "views": return (a, b) => (Number(b.views) || 0) - (Number(a.views) || 0);
    case "likes": return (a, b) => (Number(b.like_base || 0) + scenepackLikeSet(b).length) - (Number(a.like_base || 0) + scenepackLikeSet(a).length);
    case "rating": return (a, b) => (Number(b.movie && b.movie.rating) || 0) - (Number(a.movie && a.movie.rating) || 0);
    case "year": return (a, b) => String((b.movie && b.movie.year) || "").localeCompare(String((a.movie && a.movie.year) || ""), undefined, { numeric: true });
    case "az": return (a, b) => String(a.title).localeCompare(String(b.title));
    case "oldest": return (a, b) => String(a.created_at).localeCompare(String(b.created_at));
    default: return (a, b) => String(b.created_at).localeCompare(String(a.created_at));
  }
}

function scenepackFacets(items) {
  const genres = {};
  const years = {};
  const types = {};
  const qualities = {};
  const bump = (bucket, key) => {
    const name = String(key || "").trim();
    if (!name) return;
    bucket[name] = (bucket[name] || 0) + 1;
  };
  for (const item of items) {
    const movie = item.movie || {};
    for (const genre of Array.isArray(movie.genres) ? movie.genres : []) bump(genres, genre);
    bump(years, String(movie.year || "").slice(0, 4));
    bump(types, item.type);
    bump(qualities, item.quality);
  }
  const sortEntries = bucket => Object.entries(bucket).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  return {
    genres: sortEntries(genres).map(([name, count]) => ({ name, count })),
    years: sortEntries(years).map(([name, count]) => ({ name, count })).sort((a, b) => b.name.localeCompare(a.name)),
    types: sortEntries(types).map(([name, count]) => ({ name, label: SCENEPACK_TYPE_LABELS[name] || name, count })),
    qualities: sortEntries(qualities).map(([name, count]) => ({ name, count })),
  };
}

// Scenepacks are open to verified members: no access pass and no offer wall, just
// the Verified role in the Discord server. Admins always pass.
async function scenepackAccessState(session, env) {
  if (!session || !session.userId) return { allowed: false, reason: "login" };
  if (ADMIN_IDS.includes(String(session.userId))) return { allowed: true, reason: "admin" };
  const verified = await checkVerifiedRole(session.userId, env).catch(() => null);
  if (verified === true) return { allowed: true, reason: "verified" };
  // A failed role lookup must ask for a retry, never silently deny a member.
  if (verified === null) return { allowed: false, reason: "unavailable" };
  return { allowed: false, reason: "verify" };
}

function scenepackAccessCode(reason) {
  if (reason === "login") return "LOGIN_REQUIRED";
  if (reason === "unavailable") return "ROLE_CHECK_UNAVAILABLE";
  return "NOT_VERIFIED";
}

function scenepackAccessMessage(reason) {
  if (reason === "login") return "Log in with Discord to download scenepacks.";
  if (reason === "unavailable") return "We could not check your Discord role right now. Please retry in a moment.";
  return "Scenepacks are open to verified members. Get the Verified role in our Discord server to download.";
}

function scenepackAccessDenied(access) {
  return scenepackJson({
    success: false,
    code: scenepackAccessCode(access.reason),
    error: scenepackAccessMessage(access.reason),
  }, access.reason === "unavailable" ? 503 : 403);
}

async function fetchOmdbTitle(imdbId) {
  const id = String(imdbId || "").trim();
  if (!/^tt\d{7,10}$/i.test(id)) return null;
  try {
    const resp = await fetch(`https://www.omdbapi.com/?i=${encodeURIComponent(id)}&plot=full&apikey=trilogy`, {
      headers: { "User-Agent": "Mozilla/5.0 (compatible; ZyrexScenepacks/1.0)" },
      signal: AbortSignal.timeout(6000),
    });
    if (!resp.ok) return null;
    const data = await resp.json();
    if (!data || data.Response !== "True") return null;
    const pick = value => (value && value !== "N/A" ? String(value) : "");
    return {
      title: pick(data.Title),
      imdb_id: pick(data.imdbID).toLowerCase(),
      year: pick(data.Year),
      genres: pick(data.Genre).split(",").map(entry => entry.trim()).filter(Boolean),
      rating: pick(data.imdbRating),
      votes: pick(data.imdbVotes),
      rated: pick(data.Rated),
      runtime: pick(data.Runtime),
      plot: pick(data.Plot),
      director: pick(data.Director),
      writers: pick(data.Writer),
      cast: pick(data.Actors),
      language: pick(data.Language),
      country: pick(data.Country),
      released: pick(data.Released),
      awards: pick(data.Awards),
      imdb_type: /series/i.test(pick(data.Type)) ? "series" : pick(data.Type) === "game" ? "game" : "movie",
      poster: imdbHiResPoster(pick(data.Poster), 600),
      backdrop: imdbHiResPoster(pick(data.Poster), 1400),
    };
  } catch (error) {
    console.error("fetchOmdbTitle failed:", error && error.message);
    return null;
  }
}

function scenepackJson(body, status = 200, headers = {}) {
  return json(body, status, { "Cache-Control": "no-store", ...headers });
}

/* ── Automatic IMDb / RAWG scraping ───────────────────────────────────────
   A curated title is scraped the moment it is created, and an admin can force a
   fresh pull with the Scrape button. Both paths share scenepackScrapeMeta, so the
   stored metadata always has the same shape. */

const SCENEPACK_RAWG_KEY = "c542e67aec3a4340908f9de9e86038af";
// Bumping this re-scrapes every stored record once, which is how a new scraping
// rule (for example the Wikipedia cast top-up) reaches older rows.
const SCENEPACK_SCRAPE_VERSION = 3;

// True when a record still lacks the details a scrape provides. A record that was
// already scraped, or filled in by hand, is never overwritten automatically.
function scenepackNeedsScrape(meta) {
  const src = meta || {};
  const version = Number(src.scraped_ver) || 0;
  if (version < SCENEPACK_SCRAPE_VERSION) return true;
  if (src.scraped_at) return false;
  const genres = Array.isArray(src.genres) ? src.genres : [];
  return !src.rating || !src.plot || !genres.length || !src.cast;
}

async function scenepackScrapeGame(slugOrName) {
  const slug = slugify(slugOrName);
  if (!slug) return null;
  try {
    const resp = await fetch(`https://api.rawg.io/api/games/${encodeURIComponent(slug)}?key=${SCENEPACK_RAWG_KEY}`, {
      headers: { "User-Agent": "Mozilla/5.0 (compatible; ZyrexScenepacks/1.0)" },
    });
    if (!resp.ok) return null;
    const game = await resp.json();
    if (!game || !game.name) return null;
    return {
      title: String(game.name),
      year: game.released ? String(game.released).slice(0, 4) : "",
      genres: (game.genres || []).map(entry => entry && entry.name).filter(Boolean).slice(0, 6),
      rating: game.rating ? (Number(game.rating) * 2).toFixed(1) : "",
      votes: game.ratings_count ? String(game.ratings_count) : "",
      runtime: game.playtime ? `${game.playtime}h` : "",
      plot: String(game.description_raw || "").slice(0, 2400),
      director: (game.developers || []).map(entry => entry && entry.name).filter(Boolean).join(", "),
      writers: (game.publishers || []).map(entry => entry && entry.name).filter(Boolean).join(", "),
      cast: "",
      released: game.released || "",
      imdb_type: "game",
      poster: game.background_image || "",
      backdrop: game.background_image || "",
      scraped_at: new Date().toISOString(),
      scraped_ver: SCENEPACK_SCRAPE_VERSION,
      scraped_from: "rawg",
    };
  } catch (error) {
    console.error("scenepackScrapeGame failed:", error && error.message);
    return null;
  }
}

// OMDb only returns the three top-billed actors, so the principal cast is topped up
// from the Wikipedia infobox (the same "starring" list readers see).
function scenepackCleanCastName(value) {
  return String(value || "")
    .replace(/\[\[|\]\]/g, "")
    .replace(/'''?/g, "")
    .replace(/\{\{|\}\}/g, "")
    .replace(/\s*\((?:actress|actor|singer|rapper|comedian|model|voice actress|voice actor)\)\s*$/i, "")
    .replace(/^\s*\d+\.\s*/, "")
    .replace(/^\*+/, "")
    .trim();
}

function scenepackParseCastList(raw) {
  let text = String(raw || "");
  text = text.replace(/<ref[\s\S]*?<\/ref>|<ref[^>]*\/>/gi, "");
  text = text.replace(/<br\s*\/?>/gi, "|");
  text = text.replace(/\n\*+/g, "|");

  const names = [];
  const push = candidate => {
    const name = scenepackCleanCastName(candidate);
    if (name.length < 2 || name.length > 60) return;
    if (/^(also|and|with|stars?|starring|featuring|ubl|plainlist|unbulleted list|flatlist|hlist|collapsible list|div col|columns-list)$/i.test(name)) return;
    if (names.some(existing => existing.toLowerCase() === name.toLowerCase())) return;
    names.push(name);
  };

  // Linked names first: [[Target|Display]] is the shape the infobox uses, and the
  // pipe inside a link must never be treated as a name separator.
  const linkPattern = /\[\[([^\]|]+)(?:\|([^\]]+))?\]\]/g;
  let match;
  while ((match = linkPattern.exec(text)) !== null) {
    push(match[2] || match[1]);
    if (names.length >= 16) return names;
  }
  const leftover = text.replace(/\[\[([^\]|]+)(?:\|([^\]]+))?\]\]/g, "|");
  for (const part of leftover.split(/[|,\n]/)) {
    push(part);
    if (names.length >= 16) break;
  }
  return names;
}
async function scenepackWikipediaCast(titleName, year) {
  const name = String(titleName || "").trim();
  if (!name) return [];
  const ua = "ZyrexScenepacks/1.0 (https://zyrexediting.xyz)";
  const squash = value => String(value || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
  try {
    const search = await fetch(
      `https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(name)}&srlimit=5&format=json`,
      { headers: { "User-Agent": ua }, signal: AbortSignal.timeout(5000) }
    );
    if (!search.ok) return [];
    const data = await search.json();
    const hits = ((data && data.query && data.query.search) || []).map(entry => String(entry.title || "")).filter(Boolean);
    if (!hits.length) return [];
    const wanted = squash(`${name} ${year || ""}`).split(" ")[0] || "";
    const page = hits.find(entry => squash(entry) === squash(name))
      || hits.find(entry => squash(entry).startsWith(squash(name)))
      || hits.find(entry => wanted && squash(entry).includes(wanted))
      || hits[0];
    if (!page) return [];
    const parsed = await fetch(
      `https://en.wikipedia.org/w/api.php?action=parse&page=${encodeURIComponent(page)}&prop=wikitext&section=0&format=json`,
      { headers: { "User-Agent": ua }, signal: AbortSignal.timeout(5000) }
    );
    if (!parsed.ok) return [];
    const payload = await parsed.json();
    const wikitext = String((payload && payload.parse && payload.parse.wikitext && payload.parse.wikitext["*"]) || "");
    if (!wikitext) return [];
    const field = wikitext.match(/^\s*\|\s*starring\s*=\s*([\s\S]+?)(?=\n\s*\|\s*[\w_]+\s*=|\n\}\})/im);
    if (!field) return [];
    return scenepackParseCastList(field[1]);
  } catch (error) {
    console.error("scenepackWikipediaCast failed:", error && error.message);
    return [];
  }
}

function scenepackMergeCast(existing, extra) {
  const list = [];
  const push = value => {
    const name = String(value || "").trim();
    if (name.length < 2) return;
    if (list.some(entry => entry.toLowerCase() === name.toLowerCase())) return;
    list.push(name);
  };
  String(existing || "").split(",").forEach(push);
  (Array.isArray(extra) ? extra : []).forEach(push);
  return list.slice(0, 16).join(", ");
}

// Accepts an IMDb id, a `game:<slug>` key, a bare slug, or a title to search.
async function scenepackScrapeMeta(target) {
  const raw = String(target || "").trim();
  if (!raw) return null;
  const imdbMatch = raw.match(/tt\d{7,10}/i);
  if (imdbMatch) {
    const meta = await fetchOmdbTitle(imdbMatch[0].toLowerCase());
    if (!meta) return null;
    const extraCast = await scenepackWikipediaCast(meta.title, meta.year).catch(() => []);
    return {
      ...meta,
      cast: scenepackMergeCast(meta.cast, extraCast),
      scraped_at: new Date().toISOString(),
      scraped_ver: SCENEPACK_SCRAPE_VERSION,
      scraped_from: "imdb",
    };
  }
  if (/^game:/i.test(raw)) {
    const slug = raw.replace(/^game:/i, "");
    return scenepackScrapeGame(slug);
  }
  // A plain name: find the best IMDb match first, then fall back to RAWG.
  try {
    const search = await fetch(`https://www.omdbapi.com/?s=${encodeURIComponent(raw)}&apikey=trilogy`, {
      headers: { "User-Agent": "Mozilla/5.0 (compatible; ZyrexScenepacks/1.0)" },
    });
    if (search.ok) {
      const data = await search.json();
      const first = Array.isArray(data && data.Search) ? data.Search[0] : null;
      if (first && first.imdbID) {
        const meta = await fetchOmdbTitle(String(first.imdbID).toLowerCase());
        if (meta) {
          const extraCast = await scenepackWikipediaCast(meta.title, meta.year).catch(() => []);
          return {
            ...meta,
            cast: scenepackMergeCast(meta.cast, extraCast),
            scraped_at: new Date().toISOString(),
            scraped_ver: SCENEPACK_SCRAPE_VERSION,
            scraped_from: "imdb",
          };
        }
      }
    }
  } catch (_) { /* fall through to RAWG */ }
  return scenepackScrapeGame(raw);
}

// Overlays fresh scrape results on stored metadata without erasing manual edits.
function scenepackMergeScraped(base, scraped) {
  const merged = scenepackMovieMeta(base);
  const baseId = merged.imdb_id;
  const baseTitle = merged.title;
  const fresh = scenepackMovieMeta(scraped);
  for (const [key, value] of Object.entries(fresh)) {
    if (Array.isArray(value) ? value.length > 0 : Boolean(value)) merged[key] = value;
  }
  // The id and the title the record was scraped by are authoritative; a search
  // fallback must never re-point an existing entry at another film.
  if (baseId) merged.imdb_id = baseId;
  if (baseTitle) merged.title = baseTitle;
  merged.scraped_at = (scraped && scraped.scraped_at) || new Date().toISOString();
  merged.scraped_ver = Number(scraped && scraped.scraped_ver) || SCENEPACK_SCRAPE_VERSION;
  merged.scraped_from = (scraped && scraped.scraped_from) || "imdb";
  return merged;
}

// Fills a title page that was created from a sparse search result, and keeps every
// pack on that page in step with it.
async function scenepackAutoScrapeTitle(env, title) {
  const imdbId = String((title && title.imdb_id) || "");
  const key = String((title && title.key) || "");
  if (!imdbId && !/^game:/i.test(key)) return null;
  const scraped = await scenepackScrapeMeta(imdbId || key);
  if (!scraped) return null;
  return scenepackMergeScraped(title, scraped);
}

// One automatic pass per title per isolate: the public title page heals itself the
// first time it is opened after a scrape-less record was stored.
const scenepackScrapeAttempts = new Set();

async function scenepackEnsureTitleScraped(env, requestedKey) {
  const key = String(requestedKey || "").trim();
  if (!key) return false;
  const memo = key.toLowerCase();
  if (scenepackScrapeAttempts.has(memo)) return false;
  const titlesStore = await loadScenepackTitles(env);
  const index = titlesStore.items.findIndex(entry => String(entry.key || "").toLowerCase() === memo);
  if (index < 0) return false;
  const current = titlesStore.items[index];
  if (!scenepackNeedsScrape(current)) {
    scenepackScrapeAttempts.add(memo);
    return false;
  }
  const scraped = await scenepackScrapeMeta(current.imdb_id || current.key).catch(() => null);
  // A failed lookup is not memoised: the next visit tries again, and the reason is
  // stored so the studio can show why the page still looks empty.
  if (!scraped) {
    const failed = normalizeScenepackTitle({
      ...current,
      scrape_error: "IMDb returned no metadata for this title.",
      scrape_attempted_at: new Date().toISOString(),
    }, null);
    titlesStore.items[index] = failed;
    await persistScenepackTitles(env, titlesStore).catch(() => false);
    return false;
  }
  scenepackScrapeAttempts.add(memo);
  const next = normalizeScenepackTitle({
    ...current,
    ...scenepackMergeScraped(current, scraped),
    name: current.name || scraped.title,
  }, null);
  titlesStore.items[index] = next;
  await persistScenepackTitles(env, titlesStore).catch(() => false);

  const packStore = await loadScenepackStore(env);
  let touched = 0;
  for (const pack of packStore.items) {
    if (String(pack.title_key || scenepackOriginKey(pack)).toLowerCase() !== memo) continue;
    pack.movie = scenepackMergeScraped(pack.movie, scraped);
    pack.thumbnail = pack.thumbnail || pack.movie.poster;
    pack.backdrop = pack.movie.backdrop || pack.thumbnail;
    pack.updated_at = new Date().toISOString();
    touched += 1;
  }
  if (touched) await persistScenepackStore(env, packStore).catch(() => false);
  return true;
}

function scenepackOriginKey(item) {
  const movie = item.movie || {};
  const imdb = String(movie.imdb_id || "").toLowerCase();
  if (imdb) return "imdb:" + imdb;
  const name = slugify(movie.title || item.title || "");
  return name ? "name:" + name : "id:" + String(item.id || "");
}

// A title page aggregates every pack that shares an origin (IMDb id, else name).
function scenepackOriginCard(packs) {
  const first = packs[0] || {};
  const movie = first.movie || {};
  const downloads = packs.reduce((sum, pack) => sum + (Number(pack.downloads_count) || 0), 0);
  const latest = packs.reduce((newest, pack) => {
    const at = Date.parse(pack.published_at || pack.created_at || "") || 0;
    return at > newest ? at : newest;
  }, 0);
  return {
    key: scenepackOriginKey(first),
    title: movie.title || first.title || "Scenepack",
    year: String(movie.year || "").slice(0, 4),
    poster: first.thumbnail || movie.poster || "",
    type: first.type || "",
    downloads,
    pack_count: packs.length,
    latest,
  };
}

function scenepackOrigins(items) {
  const grouped = new Map();
  for (const item of items) {
    const key = scenepackOriginKey(item);
    if (!grouped.has(key)) grouped.set(key, []);
    grouped.get(key).push(item);
  }
  return Array.from(grouped.entries()).map(([key, packs]) => ({ key, packs, card: scenepackOriginCard(packs) }));
}

function scenepackFindOrigin(items, rawKey) {
  const key = String(rawKey || "").trim().toLowerCase();
  if (!key) return null;
  const origins = scenepackOrigins(items);
  return origins.find(entry => {
    const entryKey = entry.key.toLowerCase();
    return entryKey === key ||
      entryKey === "imdb:" + key ||
      entryKey === "name:" + key ||
      entryKey === "id:" + key ||
      slugify(entry.card.title) === key;
  }) || null;
}

/* ── Storage sources ───────────────────────────────────────────────────────
   A pack never exposes its cloud link: the browser only ever talks to
   /api/scenepacks/<id>/file, and this worker streams the bytes from wherever
   the admin stored them. That keeps SFTPGo/S3 prefixes and Google Drive file
   ids on the server and keeps the download UI on our own domain. */

const SCENEPACK_TITLES_R2_KEY = "scenepacks/titles.json";
const SCENEPACK_STORAGE_KINDS = ["sftpgo", "gdrive", "direct"];
const GDRIVE_DOWNLOAD_BASE = "https://drive.usercontent.google.com/download";

// A scenepack is a video file, not an archive: mp4/mov are the norm and the
// stream has to advertise the real media type so browsers can play and seek it.
const SCENEPACK_MEDIA_TYPES = {
  mp4: "video/mp4",
  m4v: "video/mp4",
  mov: "video/quicktime",
  webm: "video/webm",
  mkv: "video/x-matroska",
  avi: "video/x-msvideo",
  mpg: "video/mpeg",
  mpeg: "video/mpeg",
  zip: "application/zip",
  rar: "application/vnd.rar",
  "7z": "application/x-7z-compressed",
};

function scenepackFileExtension(name) {
  const base = String(name || "").split(/[?#]/)[0].split("/").pop();
  const match = base.match(/\.([A-Za-z0-9]{1,8})$/);
  return match ? match[1].toLowerCase() : "";
}

function scenepackContentType(name) {
  return SCENEPACK_MEDIA_TYPES[scenepackFileExtension(name)] || "application/octet-stream";
}

function scenepackFormatFromName(name) {
  const ext = scenepackFileExtension(name);
  return SCENEPACK_MEDIA_TYPES[ext] ? ext.toUpperCase() : "";
}

function scenepackStorageDescriptor(raw) {
  const src = raw && typeof raw === "object" ? raw : {};
  const kindRaw = String(src.kind || src.provider || "").toLowerCase();
  const kind = SCENEPACK_STORAGE_KINDS.includes(kindRaw) ? kindRaw : "";
  const key = String(src.key || src.path || "").replace(/\\/g, "/").replace(/^\/+/, "").trim().slice(0, 400);
  const fileId = String(src.file_id || src.fileId || "").trim().slice(0, 200);
  const folderId = String(src.folder_id || src.folderId || "").trim().slice(0, 200);
  const rawUrl = scenepackUrl(src.url);
  // Drive is detected from the link itself, so a share link stored as a plain
  // "direct" URL still becomes a proper Drive reference instead of being relayed.
  const drive = scenepackDriveRef(fileId || folderId || rawUrl);
  if (kind === "sftpgo" && key) return { kind, key };
  if (folderId) return { kind: "gdrive", folder_id: folderId };
  if (drive) return drive.kind === "folder" ? { kind: "gdrive", folder_id: drive.id } : { kind: "gdrive", file_id: drive.id };
  if (kind === "gdrive") return rawUrl ? { kind: "gdrive", url: rawUrl } : null;
  if (rawUrl) return { kind: "direct", url: rawUrl };
  if (key) return { kind: "sftpgo", key };
  return null;
}

// Google Drive share links have two shapes: a single file (/file/d/<id>) and a
// folder (/drive/folders/<id>). Scenepacks are often a folder of clips, so both
// are understood — a folder is listed through our own UI and each clip streams
// from here, never from a Google page.
function scenepackDriveRef(rawUrl) {
  const value = String(rawUrl || "").trim();
  if (!value || value.length > 2000) return null;
  if (/^[A-Za-z0-9_-]{20,}$/.test(value)) return { kind: "file", id: value };
  if (!/drive\.google\.com|drive\.usercontent\.google\.com|docs\.google\.com/i.test(value)) return null;
  const folder = value.match(/\/folders\/([A-Za-z0-9_-]{10,})/)
    || value.match(/[?&]folder_?id=([A-Za-z0-9_-]{10,})/i);
  if (folder) return { kind: "folder", id: folder[1] };
  const fileD = value.match(/\/file\/d\/([A-Za-z0-9_-]{10,})/)
    || value.match(/\/d\/([A-Za-z0-9_-]{10,})/);
  if (fileD) return { kind: "file", id: fileD[1] };
  const param = value.match(/[?&](?:id|file_id)=([A-Za-z0-9_-]{10,})/i);
  return param ? { kind: "file", id: param[1] } : null;
}

// Accepts /file/d/<id>/view, open?id=<id>, uc?id=<id> and ?id=<id> share links.
function scenepackDriveFileId(rawUrl) {
  const ref = scenepackDriveRef(rawUrl);
  return ref && ref.kind === "file" ? ref.id : "";
}

// Rejects a storage link that cannot become a real file reference, so a folder
// page or a dead Drive URL is never saved as if it were the video itself.
function scenepackStorageIssue(body) {
  const requested = Array.isArray(body && body.downloads) ? body.downloads.filter(Boolean) : [];
  if (!requested.length) return "";
  const resolved = requested.map(entry => scenepackStorageDescriptor(entry.storage || {
    kind: entry.storage_kind,
    key: entry.storage_key || entry.path,
    file_id: entry.file_id,
    folder_id: entry.folder_id,
    url: entry.url,
  }));
  if (resolved.some(storage => storage && scenepackStoragePublic({ storage }).ready)) return "";
  const driveLike = requested.some(entry => {
    const url = String((entry.storage && entry.storage.url) || entry.url || "");
    return /drive\.google\.com|docs\.google\.com/i.test(url);
  });
  return driveLike
    ? "That Google Drive link could not be read. Paste a file share link (…/file/d/…) or a folder share link (…/drive/folders/…) that is shared with anyone who has the link."
    : "Add at least one storage link: a Zyrex Cloud file, a Google Drive file or folder, or a direct URL.";
}

function scenepackStorageLabel(storage, fallback) {
  if (storage && storage.kind === "sftpgo") return "Zyrex Cloud";
  if (storage && storage.kind === "gdrive") return "Google Drive";
  return fallback || (storage ? "Direct" : "");
}

function scenepackStoragePublic(entry) {
  const storage = entry && entry.storage;
  if (!storage) return { kind: "", label: "", ready: false, folder: false };
  const folder = storage.kind === "gdrive" && Boolean(storage.folder_id);
  const ready = Boolean(
    storage.kind === "sftpgo" ? storage.key
      : storage.kind === "gdrive" ? (storage.file_id || storage.folder_id)
        : storage.url
  );
  return {
    kind: storage.kind,
    label: scenepackStorageLabel(storage, entry.provider),
    ready,
    folder,
  };
}

/* ── Google Drive folder listing ──────────────────────────────────────────
   The public "embedded folder view" is a tiny, stable HTML page, so a folder
   version can be listed without any Drive credentials. Results are cached so a
   busy pack does not refetch the listing on every open. */
const SCENEPACK_DRIVE_CACHE = new Map();
const SCENEPACK_DRIVE_TTL_MS = 5 * 60 * 1000;

function scenepackDecodeEntities(value) {
  return String(value || "")
    .replace(/&(#\d+|#x[0-9a-f]+|[a-z]+);/gi, (match, code) => {
      const lower = String(code).toLowerCase();
      if (lower === "#39" || lower === "apos") return "'";
      if (lower === "amp") return "&";
      if (lower === "lt") return "<";
      if (lower === "gt") return ">";
      if (lower === "quot") return '"';
      if (lower === "nbsp") return " ";
      if (/^#x[0-9a-f]+$/.test(lower)) return String.fromCodePoint(parseInt(lower.slice(2), 16));
      if (/^#\d+$/.test(lower)) return String.fromCodePoint(parseInt(lower.slice(1), 10));
      return match;
    });
}

async function scenepackDriveListFolder(folderId) {
  const id = String(folderId || "").trim();
  if (!/^[A-Za-z0-9_-]{10,}$/.test(id)) return [];
  const cached = SCENEPACK_DRIVE_CACHE.get(id);
  if (cached && Date.now() - cached.at < SCENEPACK_DRIVE_TTL_MS) return cached.entries;
  const resp = await fetch(`https://drive.google.com/embeddedfolderview?id=${encodeURIComponent(id)}#list`, {
    headers: {
      "User-Agent": "Mozilla/5.0 (compatible; ZyrexScenepacks/1.0)",
      "Accept-Language": "en-US,en;q=0.9",
    },
  }).catch(() => null);
  if (!resp || !resp.ok) return cached ? cached.entries : [];
  const html = await resp.text().catch(() => "");
  const entries = [];
  const entryPattern = /<div class="flip-entry" id="entry-([A-Za-z0-9_-]+)"([\s\S]*?)<div class="flip-entry-title">([\s\S]*?)<\/div>/g;
  let match;
  while ((match = entryPattern.exec(html)) && entries.length < 400) {
    const name = scenepackDecodeEntities(match[3]).replace(/<[^>]*>/g, "").trim();
    if (!name) continue;
    const mimeMatch = match[2].match(/drive-thirdparty\.googleusercontent\.com\/[^"]*type\/([^"?]+)/);
    const mime = mimeMatch ? decodeURIComponent(mimeMatch[1]) : "";
    entries.push({
      id: match[1],
      name,
      mime,
      is_folder: /vnd\.google-apps\.folder/i.test(mime) || /alt="Folder"/i.test(match[2]),
    });
  }
  SCENEPACK_DRIVE_CACHE.set(id, { at: Date.now(), entries });
  return entries;
}

async function scenepackDriveFolderFiles(folderId, depth = 0) {
  const entries = await scenepackDriveListFolder(folderId);
  const files = [];
  for (const entry of entries) {
    if (files.length >= 300) break;
    if (entry.is_folder) {
      if (depth >= 2) continue;
      const nested = await scenepackDriveFolderFiles(entry.id, depth + 1);
      for (const file of nested) {
        files.push({ ...file, parent: entry.name });
      }
      continue;
    }
    files.push({
      id: entry.id,
      name: entry.name,
      format: scenepackFormatFromName(entry.name),
      mime: entry.mime || "",
      parent: "",
    });
  }
  return files;
}

// Reads the real byte size of one stored file. R2 answers from head(); Drive and
// direct hosts answer a one-byte range request whose Content-Range carries the
// total. Nothing is downloaded: the body is cancelled straight away.
async function scenepackFileSize(env, storage, fileId) {
  if (!storage) return 0;
  const id = String(fileId || storage.file_id || "").trim();
  try {
    if (storage.kind === "sftpgo") {
      const bucket = env.STORAGE_PROD || env.STORAGE;
      if (bucket && typeof bucket.head === "function") {
        const head = await bucket.head(storage.key).catch(() => null);
        if (head && head.size) return Number(head.size) || 0;
      }
      if (env.STORAGE && env.STORAGE !== bucket && typeof env.STORAGE.head === "function") {
        const staging = await env.STORAGE.head(storage.key).catch(() => null);
        if (staging && staging.size) return Number(staging.size) || 0;
      }
      return 0;
    }
    let target = "";
    if (storage.kind === "gdrive") {
      if (!id) return 0;
      target = `${GDRIVE_DOWNLOAD_BASE}?id=${encodeURIComponent(id)}&export=download&confirm=t`;
    } else if (storage.kind === "direct") {
      target = storage.url;
    }
    if (!target) return 0;
    const resp = await fetch(target, {
      method: "GET",
      headers: {
        "User-Agent": "Mozilla/5.0 (compatible; ZyrexScenepacks/1.0)",
        Range: "bytes=0-0",
      },
      redirect: "follow",
      signal: AbortSignal.timeout(6000),
    }).catch(() => null);
    if (!resp) return 0;
    try { await resp.body?.cancel?.(); } catch (_) { /* body already drained */ }
    const type = (resp.headers.get("Content-Type") || "").toLowerCase();
    if (/^text\/html|^application\/(xhtml\+xml|json)/.test(type)) return 0;
    const range = resp.headers.get("Content-Range") || "";
    const total = range.match(/\/(\d+)\s*$/);
    if (total) return Number(total[1]) || 0;
    const length = Number(resp.headers.get("Content-Length")) || 0;
    return length > 1 ? length : 0;
  } catch (_) {
    return 0;
  }
}

// Fills in the size of each listed file, capped so one huge folder cannot turn
// into hundreds of subrequests.
async function scenepackWithSizes(env, storage, files) {
  const cap = 24;
  return Promise.all(files.map(async (file, index) => {
    if (index >= cap) return file;
    const size = await scenepackFileSize(env, storage, file.id || "");
    return size ? { ...file, size } : file;
  }));
}

// Streams one stored file. R2 (the SFTPGo/S3 bucket behind leak uploads) answers
// Range requests so the browser can seek; Drive and direct links are relayed.
// Scenepacks are video scenes (mp4/mov), so the stream stays inline for playback
// and only turns into an attachment when the caller asks for ?dl=1.
async function scenepackStreamResponse(env, request, storage, entry, options = {}) {
  if (!storage) {
    return scenepackJson({ success: false, code: "NO_STORAGE", error: "This version has no file attached." }, 404);
  }
  const download = (() => {
    try {
      return new URL(request.url).searchParams.get("dl") === "1";
    } catch (_) {
      return false;
    }
  })();
  const disposition = (name, type) => {
    const safe = String(name || "scenepack.mp4").replace(/["\\\r\n]/g, "");
    const inline = !download && /^video\/|^image\//i.test(type || "");
    return `${inline ? "inline" : "attachment"}; filename="${safe}"`;
  };

  if (storage.kind === "sftpgo") {
    const bucket = env.STORAGE_PROD || env.STORAGE;
    if (!bucket) return new Response("Storage unavailable", { status: 503 });
    const rangeHeader = request.headers.get("Range");
    const read = async (target) => {
      try {
        return await target.get(storage.key, rangeHeader ? { range: request.headers } : undefined);
      } catch (_) {
        return null;
      }
    };
    let obj = await read(bucket);
    let useProd = true;
    if (!obj && env.STORAGE && env.STORAGE !== bucket) {
      obj = await read(env.STORAGE);
      useProd = false;
    }
    if (!obj) return new Response("File not found", { status: 404 });
    const name = storage.key.split("/").pop() || "scenepack.mp4";
    const type = scenepackContentType(name);
    const headers = {
      "Content-Type": type,
      "Content-Disposition": disposition(name, type),
      "Cache-Control": "private, max-age=0, no-store",
      "Accept-Ranges": "bytes",
    };
    let status = 200;
    if (obj.range) {
      const offset = Number(obj.range.offset) || 0;
      const length = Number(obj.range.length) || (obj.size - offset);
      headers["Content-Range"] = `bytes ${offset}-${offset + length - 1}/${obj.size}`;
      headers["Content-Length"] = String(length);
      status = 206;
    } else {
      headers["Content-Length"] = String(obj.size);
    }
    void useProd;
    return new Response(request.method === "HEAD" ? null : obj.body, { status, headers });
  }

  let targets = [];
  let driveFileId = "";
  if (storage.kind === "gdrive") {
    driveFileId = String(options.fileId || storage.file_id || "").trim();
    if (!driveFileId) {
      // A folder is a collection of clips, not something that can be streamed as
      // one file: the UI lists it through /files and requests one clip at a time.
      return scenepackJson({
        success: false,
        code: "FOLDER_NO_FILE",
        error: storage.folder_id
          ? "This version is a Google Drive folder. Pick one of its files instead."
          : "This Google Drive link could not be read. Re-add it as a file share link.",
      }, 400);
    }
    if (!/^[A-Za-z0-9_-]{10,}$/.test(driveFileId)) {
      return scenepackJson({ success: false, code: "DRIVE_ID_INVALID", error: "That Google Drive file id is not valid." }, 400);
    }
    // Two public endpoints serve the same bytes; the second covers a host that
    // is briefly rate limited or answering with the interstitial page.
    targets = [
      `${GDRIVE_DOWNLOAD_BASE}?id=${encodeURIComponent(driveFileId)}&export=download&confirm=t`,
      `https://drive.google.com/uc?export=download&id=${encodeURIComponent(driveFileId)}&confirm=t`,
    ];
  } else if (storage.kind === "direct") {
    targets = [storage.url];
  }
  if (!targets.length || !targets[0]) {
    return scenepackJson({ success: false, code: "NO_STORAGE", error: "This version has no usable file." }, 404);
  }

  let upstream = null;
  let upstreamType = "";
  let sawHtml = false;
  for (const candidate of targets.filter(Boolean)) {
    const attempt = await fetch(candidate, {
      method: request.method === "HEAD" ? "HEAD" : "GET",
      headers: {
        "User-Agent": "Mozilla/5.0 (compatible; ZyrexScenepacks/1.0)",
        ...(request.headers.get("Range") ? { Range: request.headers.get("Range") } : {}),
      },
      redirect: "follow",
    }).catch(() => null);
    if (!attempt) continue;
    const type = (attempt.headers.get("Content-Type") || "").toLowerCase();
    // A share link that points at a page instead of a file answers with HTML.
    // That is exactly how a "corrupt mp4" used to reach the browser.
    if (/^text\/html|^application\/(xhtml\+xml|json)/.test(type) && attempt.ok) {
      sawHtml = true;
      continue;
    }
    upstream = attempt;
    upstreamType = type;
    if (attempt.ok) break;
  }
  if (sawHtml && (!upstream || !upstream.ok)) {
    return scenepackJson({
      success: false,
      code: "UPSTREAM_NOT_MEDIA",
      error: "That link returns a web page instead of a video file. Use a direct file link or a shared Drive file/folder.",
    }, 502);
  }
  if (!upstream || !upstream.ok) {
    return scenepackJson({
      success: false,
      code: "UPSTREAM_ERROR",
      error: upstream && upstream.status === 404
        ? "The stored file is no longer there. Check the share link."
        : "The storage service rejected the request. Try again in a moment.",
    }, 502);
  }
  if (/^text\/html|^application\/(xhtml\+xml|json)/.test(upstreamType)) {
    return scenepackJson({
      success: false,
      code: "UPSTREAM_NOT_MEDIA",
      error: "That link returns a web page instead of a video file. Use a direct file link or a shared Drive file/folder.",
    }, 502);
  }

  const headers = new Headers();
  const upstreamDisposition = upstream.headers.get("Content-Disposition") || "";
  const dispositionName = (() => {
    const utf = upstreamDisposition.match(/filename\*=UTF-8''([^;]+)/i);
    if (utf) {
      try { return decodeURIComponent(utf[1].trim()); } catch (_) { /* fall through */ }
    }
    const plain = upstreamDisposition.match(/filename="?([^";]+)"?/i);
    return plain ? plain[1].trim() : "";
  })();
  const entryFormat = entry && entry.format ? String(entry.format).toLowerCase() : "";
  const name = dispositionName
    || (storage.kind === "sftpgo" ? String(storage.key || "").split("/").pop() : "")
    || `scenepack.${entryFormat || "mp4"}`;
  const derivedType = scenepackContentType(name) !== "application/octet-stream"
    ? scenepackContentType(name)
    : (entryFormat ? scenepackContentType(`scenepack.${entryFormat}`) : "");
  const contentType = /^video\/|^audio\/|^image\//.test(upstreamType)
    ? upstreamType
    : (derivedType || upstreamType || "application/octet-stream");
  headers.set("Content-Type", contentType);
  headers.set("Cache-Control", "private, max-age=0, no-store");
  for (const header of ["Content-Length", "Content-Range", "Accept-Ranges"]) {
    const value = upstream.headers.get(header);
    if (value) headers.set(header, value);
  }
  headers.set("Content-Disposition", disposition(name, contentType));
  headers.set("X-Content-Type-Options", "nosniff");
  void driveFileId;
  return new Response(request.method === "HEAD" ? null : upstream.body, {
    status: upstream.status === 206 ? 206 : 200,
    headers,
  });
}

/* ── Title pages ───────────────────────────────────────────────────────────
   Admins curate one page per film / series / game from IMDb or RAWG, and the
   character scenepacks hang off that page. Pages are paginated in the studio
   so a large catalogue stays browsable. */

function scenepackTitleKey(raw) {
  const src = raw && typeof raw === "object" ? raw : {};
  const imdbId = String(src.imdb_id || "").toLowerCase();
  if (/^tt\d{7,10}$/.test(imdbId)) return "imdb:" + imdbId;
  const gameId = String(src.source_id || "").trim();
  if (gameId) return "game:" + slugify(gameId) || "game:" + gameId;
  const name = slugify(src.name || src.title || "");
  return name ? "name:" + name : "";
}

function normalizeScenepackTitle(raw, existing = null) {
  const src = raw && typeof raw === "object" ? raw : {};
  const base = existing && typeof existing === "object" ? existing : {};
  const name = scenepackText(src.name || src.title, 180) || scenepackText(base.name, 180);
  const imdbId = /^tt\d{7,10}$/i.test(String(src.imdb_id || base.imdb_id || ""))
    ? String(src.imdb_id || base.imdb_id).toLowerCase()
    : "";
  const genresRaw = src.genres !== undefined ? src.genres : base.genres;
  const genres = (Array.isArray(genresRaw) ? genresRaw : String(genresRaw || "").split(","))
    .map(entry => scenepackText(entry, 40)).filter(Boolean).slice(0, 8);
  const typeRaw = String(src.type || base.type || "").toLowerCase();
  const type = SCENEPACK_TYPE_LABELS[typeRaw] ? typeRaw : (imdbId ? "movie" : "game");
  // A title page can be published while its packs are still being collected.
  const productionRaw = src.in_production !== undefined ? src.in_production : base.in_production;
  const inProduction = productionRaw === true || /^(1|true|yes|on)$/i.test(String(productionRaw || ""));
  return {
    ...base,
    key: scenepackTitleKey({ imdb_id: imdbId, source_id: src.source_id || base.source_id, name }),
    name,
    type,
    in_production: inProduction,
    imdb_id: imdbId,
    source: ["imdb", "rawg", "manual"].includes(String(src.source || base.source))
      ? String(src.source || base.source)
      : (imdbId ? "imdb" : "manual"),
    source_id: scenepackText(src.source_id !== undefined ? src.source_id : base.source_id, 60),
    year: scenepackText(src.year !== undefined ? src.year : base.year, 16),
    rating: scenepackText(src.rating !== undefined ? src.rating : base.rating, 10),
    runtime: scenepackText(src.runtime !== undefined ? src.runtime : base.runtime, 24),
    rated: scenepackText(src.rated !== undefined ? src.rated : base.rated, 16),
    plot: scenepackText(src.plot !== undefined ? src.plot : base.plot, 2400),
    director: scenepackText(src.director !== undefined ? src.director : base.director, 240),
    cast: scenepackText(src.cast !== undefined ? src.cast : base.cast, 320),
    genres,
    poster: imdbHiResPoster(scenepackUrl(src.poster !== undefined ? src.poster : base.poster), 600),
    // A custom title photo overrides the IMDb poster when an admin sets one.
    avatar: scenepackUrl(src.avatar !== undefined ? src.avatar : base.avatar),
    backdrop: imdbHiResPoster(scenepackUrl(src.backdrop !== undefined ? src.backdrop : base.backdrop), 1600),
    imdb_url: imdbId ? `https://www.imdb.com/title/${imdbId}/` : scenepackUrl(src.imdb_url !== undefined ? src.imdb_url : base.imdb_url),
    trailer_url: scenepackUrl(src.trailer_url !== undefined ? src.trailer_url : base.trailer_url),
    // Scrape provenance: a stamped title is not auto-scraped again, and the studio
    // can show when the metadata was refreshed.
    scraped_at: scenepackText(src.scraped_at !== undefined ? src.scraped_at : base.scraped_at, 32),
    scraped_ver: Number(src.scraped_ver !== undefined ? src.scraped_ver : base.scraped_ver) || 0,
    scraped_from: scenepackText(src.scraped_from !== undefined ? src.scraped_from : base.scraped_from, 16),
    // Why the last automatic scrape produced nothing, so the studio can explain it.
    scrape_error: scenepackText(src.scrape_error !== undefined ? src.scrape_error : base.scrape_error, 120),
    scrape_attempted_at: scenepackText(src.scrape_attempted_at !== undefined ? src.scrape_attempted_at : base.scrape_attempted_at, 32),
    created_at: base.created_at || new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
}

async function loadScenepackTitles(env) {
  const raw = await r2GetJSON(env, SCENEPACK_TITLES_R2_KEY, null);
  const items = Array.isArray(raw) ? raw : (raw && Array.isArray(raw.items) ? raw.items : []);
  return { items };
}

// The single-page uploader can flag its title as "in production" in the same
// request, so a page can go live while its clips are still being collected.
async function scenepackMarkTitleInProduction(env, record) {
  const key = String((record && record.title_key) || "").trim();
  if (!key) return false;
  const movie = (record && record.movie) || {};
  const titlesStore = await loadScenepackTitles(env);
  const index = titlesStore.items.findIndex(entry => String(entry.key || "").toLowerCase() === key.toLowerCase());
  const seed = index >= 0 ? titlesStore.items[index] : {
    key,
    name: movie.title || record.title || "",
    type: record.type === "game" ? "game" : (record.type === "series" ? "series" : "movie"),
    imdb_id: movie.imdb_id || "",
    source: movie.imdb_id ? "imdb" : "manual",
    year: movie.year || "",
    genres: Array.isArray(movie.genres) ? movie.genres : [],
    rating: movie.rating || "",
    runtime: movie.runtime || "",
    plot: movie.plot || "",
    director: movie.director || "",
    cast: movie.cast || "",
    poster: movie.poster || "",
    backdrop: movie.backdrop || "",
  };
  const next = normalizeScenepackTitle({ ...seed, in_production: true }, index >= 0 ? titlesStore.items[index] : null);
  if (!next.key) return false;
  if (index >= 0) titlesStore.items[index] = next;
  else titlesStore.items.unshift(next);
  return persistScenepackTitles(env, titlesStore);
}

async function persistScenepackTitles(env, store) {
  return r2PutJSON(env, SCENEPACK_TITLES_R2_KEY, {
    items: Array.isArray(store.items) ? store.items : [],
    total: Array.isArray(store.items) ? store.items.length : 0,
    updated_at: new Date().toISOString(),
  });
}

// External catalogues for the studio picker. IMDb via OMDb (movies/series with
// posters) and RAWG (games with artwork); both answer with a page number so the
// studio can page through results exactly like the public browse grid.
async function scenepackDiscoverTitles(provider, query, page) {
  const q = String(query || "").trim();
  const currentPage = Math.min(Math.max(Number(page) || 1, 1), 100);
  if (provider === "game") {
    const url = new URL("https://api.rawg.io/api/games");
    if (q) url.searchParams.set("search", q);
    url.searchParams.set("page", String(currentPage));
    url.searchParams.set("page_size", "20");
    url.searchParams.set("key", SCENEPACK_RAWG_KEY);
    if (!q) url.searchParams.set("ordering", "-added");
    const resp = await fetch(url.toString(), { headers: { "User-Agent": "Mozilla/5.0" } });
    if (!resp.ok) return { items: [], page: currentPage, pages: 1, total: 0 };
    const data = await resp.json();
    const items = (Array.isArray(data.results) ? data.results : []).map(game => ({
      key: "game:" + slugify(game.slug || game.name || ""),
      source: "rawg",
      source_id: String(game.slug || game.id || ""),
      type: "game",
      name: game.name || "",
      year: game.released ? String(game.released).slice(0, 4) : "",
      rating: game.rating ? (Number(game.rating) * 2).toFixed(1) : "",
      genres: (game.genres || []).map(entry => entry.name).filter(Boolean),
      poster: game.background_image || "",
      backdrop: game.background_image || "",
      imdb_id: "",
      imdb_url: "",
    }));
    return {
      items,
      page: currentPage,
      pages: Math.max(1, Math.ceil((Number(data.count) || items.length) / 20)),
      total: Number(data.count) || items.length,
    };
  }

  if (!q) return { items: [], page: 1, pages: 1, total: 0, needs_query: true };
  const url = new URL("https://www.omdbapi.com/");
  url.searchParams.set("s", q);
  url.searchParams.set("page", String(currentPage));
  url.searchParams.set("apikey", "trilogy");
  const type = String(provider || "").toLowerCase();
  if (type === "movie" || type === "series") url.searchParams.set("type", type);
  const resp = await fetch(url.toString(), { headers: { "User-Agent": "Mozilla/5.0" } });
  if (!resp.ok) return { items: [], page: currentPage, pages: 1, total: 0 };
  const data = await resp.json();
  if (!data || data.Response === "False") return { items: [], page: currentPage, pages: 1, total: 0 };
  const list = Array.isArray(data.Search) ? data.Search : [];
  const total = Number(String(data.totalResults || "0").replace(/[^0-9]/g, "")) || list.length;
  const items = list.map(entry => ({
    key: "imdb:" + String(entry.imdbID || "").toLowerCase(),
    source: "imdb",
    source_id: "",
    type: /series/i.test(entry.Type) ? "series" : "movie",
    name: entry.Title || "",
    year: entry.Year || "",
    rating: "",
    genres: [],
    poster: imdbHiResPoster(entry.Poster && entry.Poster !== "N/A" ? entry.Poster : "", 600),
    backdrop: imdbHiResPoster(entry.Poster && entry.Poster !== "N/A" ? entry.Poster : "", 1600),
    imdb_id: String(entry.imdbID || "").toLowerCase(),
    imdb_url: `https://www.imdb.com/title/${entry.imdbID}/`,
  }));
  return { items, page: currentPage, pages: Math.max(1, Math.ceil(total / 10)), total };
}

// Moves one picked cloud file from the uploader's own staging folder into the
// production bucket, using the same layout the leak uploader publishes with:
//   staging  <sftpgo-username>/<editor>/<resource>/<file>
//   production           <editor>/<resource>/<file>
// The returned key is what a scenepack stores and what /file streams.
async function scenepackPublishToProduction(env, session, body) {
  const rawPath = String(body.path || body.key || "").replace(/^\/+/, "").replace(/\/+$/, "");
  if (!rawPath) return { success: false, status: 400, error: "Pick a file from your cloud first." };
  const parts = rawPath.split("/").filter(Boolean);
  if (parts.length < 2) {
    return { success: false, status: 400, error: "Pick a file inside a resource folder (editor/resource/file).", code: "NOT_A_FILE" };
  }
  const looksLikeFile = /\.[A-Za-z0-9]{1,8}$/.test(parts[parts.length - 1]);
  const fileName = looksLikeFile ? parts.pop() : "";
  const editor = parts[0];
  const resource = parts.slice(1).join("/") || editor;
  const destEditor = scenepackText(body.destination_editor, 80) || editor;
  const stagingBucket = env.STORAGE;
  const prodBucket = env.STORAGE_PROD || env.STORAGE;
  if (!stagingBucket || !prodBucket) {
    return { success: false, status: 503, error: "Storage is unavailable." };
  }

  const username = String((session && session.username) || "").trim();
  const userId = String((session && session.userId) || "").trim();
  const candidates = [...new Set([
    username,
    username && userId ? `${username}_${userId}` : "",
    userId,
  ].filter(Boolean))];

  let sourcePrefix = "";
  let flatSource = false;
  for (const root of candidates) {
    const attempts = [
      { prefix: `${root}/${editor}/${resource}/`.replace(/\/+/g, "/"), flat: false },
      { prefix: `${root}/${editor}/`.replace(/\/+/g, "/"), flat: true },
    ];
    if (resource === editor) attempts.shift();
    for (const attempt of attempts) {
      if (!attempt.prefix) continue;
      const probe = await stagingBucket.list({ prefix: attempt.prefix, limit: 1 }).catch(() => null);
      if (probe && Array.isArray(probe.objects) && probe.objects.some(obj => !obj.key.endsWith("/"))) {
        sourcePrefix = attempt.prefix;
        flatSource = attempt.flat;
        break;
      }
    }
    if (sourcePrefix) break;
  }
  if (!sourcePrefix) {
    return { success: false, status: 404, error: `No uploaded files found for ${editor}/${resource}.`, code: "SOURCE_MISSING" };
  }

  const all = await r2List(env, sourcePrefix, false);
  const wanted = all.filter(obj => {
    if (obj.key.endsWith("/") || obj.key === sourcePrefix || obj.key.endsWith("/.placeholder")) return false;
    if (!fileName) return true;
    const rel = obj.key.slice(sourcePrefix.length);
    return rel === fileName || rel.endsWith("/" + fileName);
  });
  if (!wanted.length) {
    return { success: false, status: 404, error: `"${fileName}" is not in ${editor}/${resource}.`, code: "FILE_MISSING" };
  }

  const destPrefix = (flatSource ? `${destEditor}/` : `${destEditor}/${resource}/`).replace(/\/+/g, "/");
  const moved = [];
  const failed = [];
  for (const obj of wanted) {
    const rel = obj.key.slice(sourcePrefix.length);
    const destKey = destPrefix + rel;
    try {
      const data = await stagingBucket.get(obj.key);
      if (!data) throw new Error("empty source");
      const bytes = await data.arrayBuffer();
      await prodBucket.put(destKey, bytes, {
        httpMetadata: { contentType: scenepackContentType(rel) },
      });
      moved.push({ key: destKey, name: rel.split("/").pop(), size: bytes.byteLength });
      await stagingBucket.delete(obj.key).catch(() => false);
    } catch (error) {
      console.error("scenepack transfer failed:", obj.key, error && error.message);
      failed.push(obj.key);
    }
  }
  if (!moved.length) {
    return { success: false, status: 500, error: "The file could not be moved to production.", failed };
  }
  const first = moved[0];
  const requestedName = fileName || "";
  const chosen = (requestedName && moved.find(entry => entry.name === requestedName)) || first;
  return {
    success: true,
    key: chosen.key,
    name: chosen.name,
    size: chosen.size,
    dest_prefix: destPrefix,
    files: moved,
    failed,
    message: `Moved ${moved.length} file${moved.length === 1 ? "" : "s"} to production.`,
  };
}

async function handleScenepacksAPI(request, env, url, path, context = {}) {
  const method = request.method;
  const session = parseSession(null, request);
  const isAdmin = Boolean(context.isAdmin);
  const viewerKey = scenepackViewerKey(request, session);

  const rest = path.slice("/api/scenepacks".length);
  const segments = rest.split("/").filter(Boolean);
  const action = segments.length > 1 ? segments[1].toLowerCase() : "";
  const rawId = segments.length ? segments[0] : "";

  if (method === "OPTIONS") return new Response(null, { status: 204, headers: corsHeaders });

  async function resolveItem(store) {
    const key = safeDecode(rawId).trim();
    if (!key) return null;
    const lower = key.toLowerCase();
    return store.items.find(item => String(item.id) === key || String(item.slug || "").toLowerCase() === lower) || null;
  }

  function canManage(item) {
    if (!item) return false;
    if (isAdmin) return true;
    if (!session || !session.userId) return false;
    return String(item.uploader_id || "") === String(session.userId);
  }

  // ── Studio routes (admin only) ────────────────────────────────────────────
  const adminSegment = segments.length && segments[0].toLowerCase() === "admin";

  // GET /api/scenepacks/discover?provider=imdb|movie|series|game&q=&page=
  if (segments.length === 1 && rawId.toLowerCase() === "discover") {
    if (method !== "GET") return scenepackJson({ success: false, error: "Method not allowed" }, 405);
    if (!isAdmin) return scenepackJson({ success: false, error: "Unauthorized", code: "ADMIN_REQUIRED" }, 403);
    const provider = String(url.searchParams.get("provider") || "movie").toLowerCase();
    const query = String(url.searchParams.get("q") || "").trim();
    const page = Math.max(1, Number(url.searchParams.get("page")) || 1);
    try {
      const result = await scenepackDiscoverTitles(provider, query, page);
      return scenepackJson({ success: true, provider, query, ...result }, 200, { "Cache-Control": "no-store" });
    } catch (error) {
      console.error("scenepack discover failed:", error && error.message);
      return scenepackJson({ success: false, error: "The catalogue lookup failed. Please retry." }, 502);
    }
  }

  // GET /api/scenepacks/admin/scrape?id=tt1234567|game:slug|name — fresh metadata
  // Feeds the Scrape button in the upload form; nothing is persisted.
  if (adminSegment && segments[1] && segments[1].toLowerCase() === "scrape") {
    if (!isAdmin) return scenepackJson({ success: false, error: "Unauthorized", code: "ADMIN_REQUIRED" }, 403);
    if (method !== "GET") return scenepackJson({ success: false, error: "Method not allowed" }, 405);
    const target = String(url.searchParams.get("id") || url.searchParams.get("q") || "").trim();
    if (!target) return scenepackJson({ success: false, error: "Give an IMDb id, a game slug or a title." }, 400);
    const meta = await scenepackScrapeMeta(target);
    if (!meta) {
      return scenepackJson({
        success: false,
        code: "SCRAPE_EMPTY",
        error: "No metadata was found for that target. Check the IMDb id or the title name.",
      }, 404);
    }
    return scenepackJson({ success: true, source: meta.scraped_from || "imdb", meta });
  }

  // GET /api/scenepacks/admin/overview — the control panel's counters
  if (adminSegment && segments[1] && segments[1].toLowerCase() === "overview") {
    if (!isAdmin) return scenepackJson({ success: false, error: "Unauthorized", code: "ADMIN_REQUIRED" }, 403);
    const [packStore, titleStore] = await Promise.all([loadScenepackStore(env), loadScenepackTitles(env)]);
    const packs = packStore.items;
    const byStatus = { published: 0, draft: 0, pending: 0, rejected: 0 };
    let downloads = 0;
    let views = 0;
    const formats = new Map();
    const kinds = new Map();
    for (const pack of packs) {
      const status = SCENEPACK_STATUSES.includes(pack.status) ? pack.status : "draft";
      byStatus[status] = (byStatus[status] || 0) + 1;
      downloads += Number(pack.downloads_count) || 0;
      views += Number(pack.views) || 0;
      const format = String(pack.format || "").toUpperCase();
      if (format) formats.set(format, (formats.get(format) || 0) + 1);
      for (const entry of pack.downloads || []) {
        const kind = scenepackStoragePublic(entry).kind || "none";
        kinds.set(kind, (kinds.get(kind) || 0) + 1);
      }
    }
    const linked = new Set(titleStore.items.map(entry => String(entry.key).toLowerCase()));
    const orphans = packs.filter(pack => !linked.has(String(pack.title_key || "").toLowerCase())).length;
    return scenepackJson({
      success: true,
      packs: {
        total: packs.length,
        published: byStatus.published || 0,
        draft: byStatus.draft || 0,
        pending: byStatus.pending || 0,
        rejected: byStatus.rejected || 0,
        downloads,
        views,
        orphans,
        featured: packs.filter(pack => pack.featured === true).length,
      },
      titles: {
        total: titleStore.items.length,
        in_production: titleStore.items.filter(entry => entry.in_production === true).length,
      },
      formats: [...formats.entries()].map(([name, count]) => ({ name, count })).sort((a, b) => b.count - a.count).slice(0, 6),
      storage: [...kinds.entries()].map(([name, count]) => ({ name, count })),
      updated_at: packStore.updated_at || null,
    });
  }

  // GET /api/scenepacks/admin/packs — every pack with its moderation state
  if (adminSegment && segments[1] && segments[1].toLowerCase() === "packs") {
    if (!isAdmin) return scenepackJson({ success: false, error: "Unauthorized", code: "ADMIN_REQUIRED" }, 403);
    const packId = segments[2] ? safeDecode(segments[2]).trim() : "";

    // GET /api/scenepacks/admin/packs/<id> — the raw record the edit form needs
    if (packId && method === "GET") {
      const store = await loadScenepackStore(env);
      const item = store.items.find(entry => String(entry.id) === packId);
      if (!item) return scenepackJson({ success: false, error: "Scenepack not found" }, 404);
      return scenepackJson({ success: true, raw: item, item: scenepackPublic(item, { unlocked: true }) });
    }

    // POST /api/scenepacks/admin/packs/<id> — publish state and featured flag
    if (packId) {
      if (method !== "POST" && method !== "PATCH" && method !== "PUT") {
        return scenepackJson({ success: false, error: "Method not allowed" }, 405);
      }
      let body;
      try { body = await request.json(); } catch (_) { body = {}; }
      const store = await loadScenepackStore(env);
      const index = store.items.findIndex(entry => String(entry.id) === packId);
      if (index < 0) return scenepackJson({ success: false, error: "Scenepack not found" }, 404);
      const pack = { ...store.items[index] };
      if (body.status !== undefined) {
        pack.status = normalizeScenepackStatus(body.status, pack.status || "draft");
        pack.published_at = pack.status === "published" ? (pack.published_at || new Date().toISOString()) : "";
      }
      if (body.featured !== undefined) {
        pack.featured = body.featured === true || /^(1|true|yes|on)$/i.test(String(body.featured));
      }
      pack.updated_at = new Date().toISOString();
      store.items[index] = pack;
      const saved = await persistScenepackStore(env, store);
      if (!saved) return scenepackJson({ success: false, error: "Could not save the scenepack." }, 503);
      return scenepackJson({ success: true, item: scenepackPublic(pack, { unlocked: true }) });
    }

    if (method !== "GET") return scenepackJson({ success: false, error: "Method not allowed" }, 405);
    const store = await loadScenepackStore(env);
    const q = String(url.searchParams.get("q") || "").trim().toLowerCase();
    const statusFilter = String(url.searchParams.get("status") || "").trim().toLowerCase();
    let items = store.items.slice();
    if (statusFilter && statusFilter !== "all") items = items.filter(pack => pack.status === statusFilter);
    if (q) {
      items = items.filter(pack => [pack.title, pack.character, pack.actor, pack.movie && pack.movie.title, pack.credit_name]
        .filter(Boolean).join(" ").toLowerCase().includes(q));
    }
    items.sort((a, b) => String(b.updated_at || b.created_at || "").localeCompare(String(a.updated_at || a.created_at || "")));
    const limit = Math.min(Math.max(Number(url.searchParams.get("limit")) || 20, 1), 60);
    const pages = Math.max(1, Math.ceil(items.length / limit));
    const page = Math.min(Math.max(Number(url.searchParams.get("page")) || 1, 1), pages);
    return scenepackJson({
      success: true,
      items: items.slice((page - 1) * limit, page * limit).map(pack => scenepackPublic(pack, { unlocked: true })),
      total: items.length,
      page,
      pages,
      limit,
    });
  }

  // GET/POST /api/scenepacks/admin/titles — paginated title pages
  if (adminSegment && segments[1] && segments[1].toLowerCase() === "titles") {
    if (!isAdmin) return scenepackJson({ success: false, error: "Unauthorized", code: "ADMIN_REQUIRED" }, 403);
    const titleId = segments[2] ? safeDecode(segments[2]).trim() : "";

    if (method === "GET" && !titleId) {
      const titlesStore = await loadScenepackTitles(env);
      const packStore = await loadScenepackStore(env);
      const q = String(url.searchParams.get("q") || "").trim().toLowerCase();
      let items = titlesStore.items.slice();
      if (q) {
        items = items.filter(entry => [entry.name, entry.year, (entry.genres || []).join(" ")]
          .filter(Boolean).join(" ").toLowerCase().includes(q));
      }
      items.sort((a, b) => String(b.updated_at || "").localeCompare(String(a.updated_at || "")));
      const limit = Math.min(Math.max(Number(url.searchParams.get("limit")) || 12, 1), 48);
      const pages = Math.max(1, Math.ceil(items.length / limit));
      const page = Math.min(Math.max(Number(url.searchParams.get("page")) || 1, 1), pages);
      const counts = new Map();
      for (const pack of packStore.items) {
        const key = String(pack.title_key || scenepackOriginKey(pack));
        counts.set(key, (counts.get(key) || 0) + 1);
      }
      return scenepackJson({
        success: true,
        items: items.slice((page - 1) * limit, page * limit).map(entry => ({
          ...entry,
          pack_count: counts.get(entry.key) || 0,
        })),
        total: items.length,
        page,
        pages,
        limit,
      });
    }

    if ((method === "POST" || method === "PUT") && !titleId) {
      let body;
      try { body = await request.json(); } catch (_) {
        return scenepackJson({ success: false, error: "Invalid JSON" }, 400);
      }
      const titlesStore = await loadScenepackTitles(env);
      const draft = normalizeScenepackTitle(body);
      if (!draft.name) return scenepackJson({ success: false, error: "A title name is required." }, 400);
      if (!draft.key) return scenepackJson({ success: false, error: "This title has no usable identifier." }, 400);
      const existingIndex = titlesStore.items.findIndex(entry => entry.key === draft.key);
      let record = normalizeScenepackTitle(draft, existingIndex >= 0 ? titlesStore.items[existingIndex] : null);
      // Automatic scrape: a title created from a search result only carries a
      // name, year and poster, so the full record is pulled straight away.
      if (scenepackNeedsScrape({ ...record, rating: record.rating, genres: record.genres, plot: record.plot, cast: record.cast })) {
        const scraped = await scenepackAutoScrapeTitle(env, record).catch(() => null);
        if (scraped) {
          record = normalizeScenepackTitle({
            ...record,
            ...scraped,
            name: record.name || scraped.title,
            type: record.type || scraped.imdb_type,
          }, null);
        }
      }
      if (existingIndex >= 0) titlesStore.items[existingIndex] = record;
      else titlesStore.items.unshift(record);
      const saved = await persistScenepackTitles(env, titlesStore);
      if (!saved) return scenepackJson({ success: false, error: "The title page could not be saved. Please retry." }, 503);
      return scenepackJson({ success: true, title: record, updated: existingIndex >= 0, scraped: Boolean(record.scraped_at) }, existingIndex >= 0 ? 200 : 201);
    }

    if (method === "DELETE" && titleId) {
      const titlesStore = await loadScenepackTitles(env);
      const key = safeDecode(titleId);
      const before = titlesStore.items.length;
      titlesStore.items = titlesStore.items.filter(entry => entry.key !== key);
      if (titlesStore.items.length === before) {
        return scenepackJson({ success: false, error: "Title page not found" }, 404);
      }
      const saved = await persistScenepackTitles(env, titlesStore);
      if (!saved) return scenepackJson({ success: false, error: "Delete failed. Please retry." }, 503);
      return scenepackJson({ success: true, deleted: true, key });
    }

    // PATCH /api/scenepacks/admin/titles/<key> — flags, photo, or a forced scrape
    if ((method === "PATCH" || method === "PUT") && titleId) {
      let body;
      try { body = await request.json(); } catch (_) { body = {}; }
      const titlesStore = await loadScenepackTitles(env);
      const index = titlesStore.items.findIndex(entry => String(entry.key || "").toLowerCase() === titleId.toLowerCase());
      if (index < 0) return scenepackJson({ success: false, error: "Title page not found" }, 404);
      const current = titlesStore.items[index];
      let next = normalizeScenepackTitle({
        ...current,
        in_production: body.in_production !== undefined ? body.in_production : current.in_production,
        avatar: body.avatar !== undefined ? body.avatar : current.avatar,
      }, current);

      // The Scrape button: forces a fresh pull even when the record is stamped,
      // then pushes the result onto every pack that belongs to this title.
      let packsUpdated = 0;
      if (body.scrape === true || body.scrape === "1") {
        const scraped = await scenepackScrapeMeta(body.target || next.imdb_id || next.key);
        if (!scraped) {
          return scenepackJson({
            success: false,
            code: "SCRAPE_EMPTY",
            error: "IMDb did not return metadata for this title. Check the IMDb id.",
          }, 502);
        }
        next = normalizeScenepackTitle({
          ...next,
          ...scenepackMergeScraped(next, scraped),
          name: next.name || scraped.title,
          imdb_id: next.imdb_id || (scraped.imdb_id || ""),
        }, null);

        const packStore = await loadScenepackStore(env);
        const shared = String(next.key || "").toLowerCase();
        const changed = packStore.items.filter(pack =>
          String(pack.title_key || scenepackOriginKey(pack)).toLowerCase() === shared
        );
        for (const pack of changed) {
          pack.movie = scenepackMergeScraped(pack.movie, scraped);
          pack.thumbnail = pack.thumbnail || pack.movie.poster;
          pack.backdrop = pack.movie.backdrop || pack.thumbnail;
          pack.updated_at = new Date().toISOString();
          packsUpdated += 1;
        }
        if (packsUpdated) await persistScenepackStore(env, packStore);
      }

      titlesStore.items[index] = next;
      const saved = await persistScenepackTitles(env, titlesStore);
      if (!saved) return scenepackJson({ success: false, error: "Could not save the title page." }, 503);
      return scenepackJson({ success: true, title: next, packs_updated: packsUpdated });
    }

    return scenepackJson({ success: false, error: "Method not allowed" }, 405);
  }

  // GET /api/scenepacks/admin/storage?path=<folder> — the caller's own cloud
  // Mirrors the leak uploader: SFTPGo exposes one directory per Discord id, so
  // the studio browses exactly the folder that Discord account owns.
  if (adminSegment && segments[1] && segments[1].toLowerCase() === "storage") {
    if (method !== "GET") return scenepackJson({ success: false, error: "Method not allowed" }, 405);
    if (!isAdmin) return scenepackJson({ success: false, error: "Unauthorized", code: "ADMIN_REQUIRED" }, 403);
    const browsePath = String(url.searchParams.get("path") || "").replace(/^\/+/, "").replace(/\/+$/, "");
    const join = name => (browsePath ? `${browsePath}/${name}` : name);

    // 1. The SFTPGo file server owns the Discord-id → directory mapping.
    if (session && session.userId) {
      try {
        const apiUrl = `${FILE_API}/api/files/list?token=zyrex-files-api-2026`
          + `&discord_id=${encodeURIComponent(session.userId)}`
          + `&path=${encodeURIComponent(browsePath ? "/" + browsePath : "/")}`;
        const resp = await fetch(apiUrl, { signal: AbortSignal.timeout(9000) });
        if (resp.ok) {
          const data = await resp.json().catch(() => null);
          if (data && data.success !== false) {
            const folders = (data.folders || []).map(folder => join(folder.name || folder));
            const files = (data.files || []).map(file => ({
              name: file.name,
              key: join(file.name),
              size: Number(file.size) || 0,
              modified: file.last_modified || null,
            }));
            return scenepackJson({
              success: true,
              scope: "user",
              discord_id: String(session.userId),
              path: browsePath,
              parent: browsePath ? browsePath.replace(/[^/]+\/?$/, "").replace(/\/$/, "") : "",
              folders,
              files,
            });
          }
        }
      } catch (error) {
        console.warn("scenepack storage: file api unavailable:", error && error.message);
      }
    }

    // 2. Fallback: read the same prefix straight out of the staging bucket.
    const bucket = env.STORAGE;
    if (!bucket) return scenepackJson({ success: false, error: "Storage is unavailable." }, 503);
    const roots = [...new Set([
      String(session && session.username || "").trim(),
      session && session.userId ? `${String(session.username || "")}_${session.userId}` : "",
    ].filter(Boolean))];
    if (!roots.length) {
      return scenepackJson({ success: false, error: "Your Discord account has no cloud folder yet.", code: "NO_CLOUD" }, 404);
    }
    try {
      let prefix = "";
      for (const root of roots) {
        const candidate = browsePath ? `${root}/${browsePath}/` : `${root}/`;
        const probe = await bucket.list({ prefix: candidate, limit: 1 });
        if (probe && Array.isArray(probe.objects) && probe.objects.length) {
          prefix = candidate;
          break;
        }
      }
      if (!prefix) prefix = `${roots[0]}/${browsePath ? browsePath + "/" : ""}`;
      const listed = await bucket.list({ prefix, limit: 400 });
      const folders = new Set();
      const files = [];
      for (const obj of listed.objects || []) {
        const rest = obj.key.slice(prefix.length);
        if (!rest) continue;
        const cut = rest.indexOf("/");
        if (cut >= 0) {
          folders.add(join(rest.slice(0, cut)));
          continue;
        }
        if (rest === ".placeholder") continue;
        files.push({ name: rest, key: join(rest), size: Number(obj.size) || 0, modified: obj.uploaded || null });
      }
      files.sort((a, b) => a.name.localeCompare(b.name));
      return scenepackJson({
        success: true,
        scope: "user",
        discord_id: String((session && session.userId) || ""),
        path: browsePath,
        parent: browsePath ? browsePath.replace(/[^/]+\/?$/, "").replace(/\/$/, "") : "",
        folders: Array.from(folders).sort(),
        files,
      });
    } catch (error) {
      console.error("scenepack storage browse failed:", error && error.message);
      return scenepackJson({ success: false, error: "Storage could not be listed." }, 502);
    }
  }

  // POST /api/scenepacks/admin/transfer — move a picked file to production
  if (adminSegment && segments[1] && segments[1].toLowerCase() === "transfer") {
    if (!isAdmin) return scenepackJson({ success: false, error: "Unauthorized", code: "ADMIN_REQUIRED" }, 403);
    if (method !== "POST") return scenepackJson({ success: false, error: "Method not allowed" }, 405);
    let body;
    try { body = await request.json(); } catch (_) {
      return scenepackJson({ success: false, error: "Invalid JSON" }, 400);
    }
    const result = await scenepackPublishToProduction(env, session, body || {});
    if (!result.success) return scenepackJson(result, result.status || 400);
    return scenepackJson(result);
  }

  // ── POST /api/scenepacks — submit a new pack ───────────────────────────────
  if (!segments.length) {
    if (method === "POST") {
      if (!session || !session.userId) {
        return scenepackJson({ success: false, error: "Please login with Discord to upload a scenepack.", code: "LOGIN_REQUIRED" }, 401);
      }
      // Scenepack publishing is staff-only: the catalogue is curated by admins.
      if (!isAdmin) {
        return scenepackJson({ success: false, error: "Scenepack uploads are limited to Zyrex staff.", code: "ADMIN_REQUIRED" }, 403);
      }
      let body;
      try { body = await request.json(); } catch (_) {
        return scenepackJson({ success: false, error: "Invalid JSON" }, 400);
      }
      const id = `sp-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
      const now = new Date().toISOString();
      const record = normalizeScenepackRecord(body, {
        id,
        uploader_id: String(session.userId),
        uploader_name: session.globalName || session.displayName || session.username || "Zyrex Member",
        uploader_avatar: session.avatar ? `https://cdn.discordapp.com/avatars/${session.userId}/${session.avatar}.png?size=128` : "",
        views: 0,
        downloads_count: 0,
        like_base: 0,
        likes: [],
        featured: false,
        created_at: now,
        updated_at: now,
      });
      if (!record.movie.title && !record.title) {
        return scenepackJson({ success: false, error: "A title or an IMDb entry is required." }, 400);
      }
      const storageIssue = scenepackStorageIssue(body);
      if (storageIssue) {
        return scenepackJson({ success: false, code: "STORAGE_INVALID", error: storageIssue }, 400);
      }
      // Automatic scrape: a pack that only knows its IMDb id still ends up with the
      // full title record, so the public page never shows an empty sidebar.
      if (scenepackNeedsScrape(record.movie)) {
        const target = (record.movie && record.movie.imdb_id) || record.title_key || record.movie.title;
        const scraped = await scenepackScrapeMeta(target).catch(() => null);
        if (scraped) {
          record.movie = scenepackMergeScraped(record.movie, scraped);
          record.thumbnail = record.thumbnail || record.movie.poster;
          record.backdrop = record.backdrop || record.movie.backdrop || record.thumbnail;
        }
      }
      record.id = id;
      record.slug = scenepackSlugFor(record.title, id);
      // A pack always belongs to a title page: derive the key when the caller did
      // not send one so flags and grouping stay consistent.
      if (!record.title_key) record.title_key = scenepackOriginKey(record);
      record.status = isAdmin ? normalizeScenepackStatus(body.status, "published") : "pending";
      record.published_at = record.status === "published" ? now : "";
      record.updated_at = now;

      const store = await loadScenepackStore(env);
      store.items.unshift(record);
      const saved = await persistScenepackStore(env, store);
      if (!saved) return scenepackJson({ success: false, error: "The scenepack could not be saved. Please retry." }, 503);
      const wantsProduction = body.in_production === true || /^(1|true|yes|on)$/i.test(String(body.in_production || ""));
      if (wantsProduction) {
        await scenepackMarkTitleInProduction(env, record).catch(() => false);
      }
      return scenepackJson({
        success: true,
        item: scenepackPublic(record, { unlocked: isAdmin, viewerKey }),
        pending: record.status !== "published",
        message: record.status === "published"
          ? "Scenepack published."
          : "Scenepack submitted for review. It goes live as soon as a moderator approves it.",
      }, 201);
    }

    // ── GET /api/scenepacks — browse with filters ────────────────────────────
    if (method === "GET") {
      const store = await loadScenepackStore(env);
      const access = await scenepackAccessState(session, env);
      const showPending = isAdmin && /^(1|true|yes)$/i.test(String(url.searchParams.get("pending") || ""));
      const statusFilter = String(url.searchParams.get("status") || "").toLowerCase();
      let items = store.items.filter(item => {
        if (showPending) return statusFilter ? item.status === statusFilter : true;
        return item.status === "published";
      });

      const q = String(url.searchParams.get("q") || "").trim().toLowerCase();
      const type = String(url.searchParams.get("type") || "").trim().toLowerCase();
      const genre = String(url.searchParams.get("genre") || "").trim().toLowerCase();
      const year = String(url.searchParams.get("year") || "").trim();
      const quality = String(url.searchParams.get("quality") || "").trim().toLowerCase();
      const uploader = String(url.searchParams.get("uploader") || "").trim();
      const tag = String(url.searchParams.get("tag") || "").trim().toLowerCase();

      if (q) items = items.filter(item => scenepackMatchesQuery(item, q));
      if (type) items = items.filter(item => String(item.type || "").toLowerCase() === type);
      if (genre) {
        items = items.filter(item => (Array.isArray(item.movie && item.movie.genres) ? item.movie.genres : [])
          .some(entry => String(entry).toLowerCase() === genre));
      }
      if (year) items = items.filter(item => String((item.movie && item.movie.year) || "").startsWith(year));
      if (quality) items = items.filter(item => String(item.quality || "").toLowerCase() === quality);
      if (uploader) items = items.filter(item => String(item.uploader_id || "") === uploader);
      if (tag) items = items.filter(item => (Array.isArray(item.tags) ? item.tags : []).some(entry => String(entry).toLowerCase() === tag));

      const facets = scenepackFacets(store.items.filter(item => item.status === "published"));
      const sort = String(url.searchParams.get("sort") || "recent");
      items = items.slice().sort(scenepackSortValue(sort));

      const total = items.length;
      const limit = Math.min(Math.max(Number(url.searchParams.get("limit")) || 24, 1), 60);
      const pages = Math.max(1, Math.ceil(total / limit));
      const page = Math.min(Math.max(Number(url.searchParams.get("page")) || 1, 1), pages);
      const slice = items.slice((page - 1) * limit, page * limit);
      const unlocked = access.allowed;

      const published = store.items.filter(item => item.status === "published");
      const stats = {
        total: published.length,
        downloads: published.reduce((sum, item) => sum + (Number(item.downloads_count) || 0), 0),
        views: published.reduce((sum, item) => sum + (Number(item.views) || 0), 0),
        creators: new Set(published.map(item => String(item.uploader_id || item.uploader_name || "zyrex").toLowerCase())).size,
        genres: facets.genres.length,
      };

      return scenepackJson({
        success: true,
        items: slice.map(item => scenepackPublic(item, { unlocked, viewerKey })),
        total,
        page,
        pages,
        limit,
        sort,
        facets,
        stats,
        access: { unlocked, reason: access.reason, expires_at: access.expires_at || null },
        updated_at: store.updated_at,
      });
    }

    return scenepackJson({ success: false, error: "Method not allowed" }, 405);
  }

  // ── GET /api/scenepacks/mine — the caller's own submissions ────────────────
  if (segments.length === 1 && rawId.toLowerCase() === "mine") {
    if (method !== "GET") return scenepackJson({ success: false, error: "Method not allowed" }, 405);
    if (!session || !session.userId) return scenepackJson({ success: false, error: "Login required", code: "LOGIN_REQUIRED" }, 401);
    const store = await loadScenepackStore(env);
    const access = await scenepackAccessState(session, env);
    const mine = store.items
      .filter(item => String(item.uploader_id || "") === String(session.userId))
      .sort((a, b) => String(b.created_at).localeCompare(String(a.created_at)));
    return scenepackJson({
      success: true,
      items: mine.map(item => scenepackPublic(item, { unlocked: access.allowed || item.access === "free", viewerKey })),
      total: mine.length,
    });
  }

  // ── GET /api/scenepacks/stats — hero counters for the browse page ──────────
  if (segments.length === 1 && rawId.toLowerCase() === "stats") {
    if (method !== "GET") return scenepackJson({ success: false, error: "Method not allowed" }, 405);
    const store = await loadScenepackStore(env);
    const published = store.items.filter(item => item.status === "published");
    const facets = scenepackFacets(published);
    return scenepackJson({
      success: true,
      stats: {
        total: published.length,
        downloads: published.reduce((sum, item) => sum + (Number(item.downloads_count) || 0), 0),
        views: published.reduce((sum, item) => sum + (Number(item.views) || 0), 0),
        creators: new Set(published.map(item => String(item.uploader_id || item.uploader_name || "zyrex").toLowerCase())).size,
        genres: facets.genres.length,
      },
      facets,
    }, 200, { "Cache-Control": "public, max-age=60" });
  }

  // ── GET /api/scenepacks/home — the browse page's rails ─────────────────────
  if (segments.length === 1 && rawId.toLowerCase() === "home") {
    if (method !== "GET") return scenepackJson({ success: false, error: "Method not allowed" }, 405);
    const homeStore = await loadScenepackStore(env);
    const published = homeStore.items.filter(entry => entry.status === "published");
    const origins = scenepackOrigins(published);
    const cards = origins.map(entry => entry.card);
    const byDownloads = (a, b) => b.downloads - a.downloads;
    const monthAgo = Date.now() - 30 * 86400000;
    const fresh = cards.filter(card => card.latest >= monthAgo);
    const trending = (fresh.length >= 4 ? fresh : cards).slice().sort(byDownloads).slice(0, 12);
    const popular = cards.slice().sort(byDownloads).slice(0, 12);
    const newest = cards.slice().sort((a, b) => b.latest - a.latest).slice(0, 12);
    const categories = [
      { type: "movie", label: "Movies" },
      { type: "series", label: "TV" },
      { type: "anime", label: "Anime" },
      { type: "game", label: "Games" },
    ].map(entry => ({
      ...entry,
      items: cards.filter(card => card.type === entry.type).sort(byDownloads).slice(0, 3),
    }));
    return scenepackJson({
      success: true,
      rails: { trending, popular, new: newest },
      categories,
      stats: {
        titles: cards.length,
        packs: published.length,
        downloads: published.reduce((sum, entry) => sum + (Number(entry.downloads_count) || 0), 0),
      },
      updated_at: homeStore.updated_at,
    }, 200, { "Cache-Control": "public, max-age=30" });
  }

  // ── GET /api/scenepacks/title?key= — everything for one movie/show/game ────
  if (segments.length === 1 && rawId.toLowerCase() === "title") {
    if (method !== "GET") return scenepackJson({ success: false, error: "Method not allowed" }, 405);
    // Automatic scrape: an older title page fills itself in on its first visit, so
    // visitors never see an empty sidebar because a record predates the scraper.
    const requestedTitle = String(url.searchParams.get("key") || url.searchParams.get("id") || "").trim();
    if (requestedTitle) {
      await scenepackEnsureTitleScraped(env, requestedTitle).catch(() => false);
    }
    const titleStore = await loadScenepackStore(env);
    const access = await scenepackAccessState(session, env);
    const visible = titleStore.items.filter(entry => entry.status === "published" || (isAdmin && entry.status !== "rejected"));
    const origin = scenepackFindOrigin(visible, url.searchParams.get("key") || url.searchParams.get("id") || "");
    // A curated title page can exist before its first pack, so the studio-created
    // title is served with an empty pack list instead of a 404.
    if (!origin) {
      const titlesStore = await loadScenepackTitles(env);
      const requestedKey = String(url.searchParams.get("key") || url.searchParams.get("id") || "").trim().toLowerCase();
      const curated = titlesStore.items.find(entry => {
        const entryKey = String(entry.key || "").toLowerCase();
        return entryKey === requestedKey ||
          entryKey === "imdb:" + requestedKey ||
          entryKey === "game:" + requestedKey ||
          entryKey === "name:" + requestedKey ||
          slugify(entry.name) === requestedKey;
      });
      if (!curated) return scenepackJson({ success: false, error: "Title not found" }, 404);
      const curatedAccess = await scenepackAccessState(session, env);
      return scenepackJson({
        success: true,
        title: {
          key: curated.key,
          name: curated.name,
          year: curated.year || "",
          imdb_id: curated.imdb_id || "",
          imdb_type: curated.type || "",
          type: curated.type || "",
          type_label: SCENEPACK_TYPE_LABELS[curated.type] || "Scenepack",
          poster: curated.poster || "",
          backdrop: curated.backdrop || curated.poster || "",
          rating: curated.rating || "",
          votes: "",
          rated: curated.rated || "",
          runtime: curated.runtime || "",
          genres: Array.isArray(curated.genres) ? curated.genres : [],
          directors: String(curated.director || "").split(",").map(name => name.trim()).filter(Boolean),
          cast: String(curated.cast || "").split(",").map(name => name.trim()).filter(Boolean),
          plot: curated.plot || "",
          released: "",
          language: "",
          country: "",
          awards: "",
          imdb_url: curated.imdb_url || "",
          avatar: curated.avatar || "",
          scraped_at: curated.scraped_at || "",
          scraped_ver: Number(curated.scraped_ver) || 0,
          scraped_from: curated.scraped_from || "",
          in_production: curated.in_production === true,
          empty: true,
        },
        packs: [],
        stats: { packs: 0, downloads: 0, views: 0 },
        access: { unlocked: curatedAccess.allowed, reason: curatedAccess.reason },
      });
    }
    const first = origin.packs[0] || {};
    const movie = first.movie || {};
    const detail = {
      key: origin.key,
      name: movie.title || origin.card.title,
      year: movie.year || "",
      imdb_id: movie.imdb_id || "",
      imdb_type: movie.imdb_type || first.type || "",
      type: first.type || "",
      type_label: SCENEPACK_TYPE_LABELS[first.type] || "Scenepack",
      poster: first.thumbnail || movie.poster || "",
      backdrop: first.backdrop || movie.backdrop || movie.poster || "",
      rating: movie.rating || "",
      votes: movie.votes || "",
      rated: movie.rated || "",
      runtime: movie.runtime || "",
      genres: Array.isArray(movie.genres) ? movie.genres : [],
      directors: String(movie.director || "").split(",").map(name => name.trim()).filter(Boolean),
      cast: String(movie.cast || "").split(",").map(name => name.trim()).filter(Boolean),
      plot: movie.plot || "",
      released: movie.released || "",
      language: movie.language || "",
      country: movie.country || "",
      awards: movie.awards || "",
      // The curated title page owns the "in production" flag even when packs
      // already exist, so the badge survives while more clips are added.
      in_production: false,
      avatar: "",
      scraped_at: "",
      scraped_ver: 0,
      scraped_from: "",
    };
    try {
      const titlesStore = await loadScenepackTitles(env);
      const curated = titlesStore.items.find(entry => String(entry.key).toLowerCase() === String(origin.key).toLowerCase());
      if (curated) {
        detail.in_production = curated.in_production === true;
        detail.avatar = curated.avatar || "";
        detail.scraped_at = curated.scraped_at || "";
        detail.scraped_ver = Number(curated.scraped_ver) || 0;
        detail.scraped_from = curated.scraped_from || "";
      }
    } catch (_) { /* the badge is cosmetic; never fail the page for it */ }
    const packs = origin.packs
      .slice()
      .sort((a, b) => (Number(b.downloads_count) || 0) - (Number(a.downloads_count) || 0));
    return scenepackJson({
      success: true,
      title: detail,
      packs: packs.map(entry => scenepackPublic(entry, {
        unlocked: access.allowed,
        viewerKey,
      })),
      stats: {
        packs: packs.length,
        downloads: packs.reduce((sum, entry) => sum + (Number(entry.downloads_count) || 0), 0),
        views: packs.reduce((sum, entry) => sum + (Number(entry.views) || 0), 0),
      },
      access: { unlocked: access.allowed, reason: access.reason },
    });
  }

  const store = await loadScenepackStore(env);
  const item = await resolveItem(store);
  if (!item) return scenepackJson({ success: false, error: "Scenepack not found" }, 404);
  const visibleToPublic = item.status === "published";
  if (!visibleToPublic && !canManage(item)) {
    return scenepackJson({ success: false, error: "Scenepack not found" }, 404);
  }

  // ── GET /api/scenepacks/:id — detail ───────────────────────────────────────
  if (!action && (method === "GET" || method === "HEAD")) {
    const access = await scenepackAccessState(session, env);
    const unlocked = access.allowed;
    return scenepackJson({
      success: true,
      item: scenepackPublic(item, { unlocked, viewerKey }),
      access: { unlocked, reason: access.reason, expires_at: access.expires_at || null },
    });
  }

  // ── PUT /api/scenepacks/:id — owner or admin edit ──────────────────────────
  if (!action && (method === "PUT" || method === "POST")) {
    if (!canManage(item)) return scenepackJson({ success: false, error: "Unauthorized" }, 403);
    let body;
    try { body = await request.json(); } catch (_) {
      return scenepackJson({ success: false, error: "Invalid JSON" }, 400);
    }
    const record = normalizeScenepackRecord(body, item);
    const storageIssue = scenepackStorageIssue(body);
    if (storageIssue) {
      return scenepackJson({ success: false, code: "STORAGE_INVALID", error: storageIssue }, 400);
    }
    record.id = item.id;
    record.uploader_id = item.uploader_id;
    record.uploader_name = item.uploader_name;
    record.uploader_avatar = item.uploader_avatar;
    record.views = item.views;
    record.downloads_count = item.downloads_count;
    record.likes = item.likes;
    record.like_base = item.like_base;
    record.created_at = item.created_at;
    record.status = isAdmin ? normalizeScenepackStatus(body.status, item.status) : item.status;
    if (record.status === "published" && !record.published_at) record.published_at = new Date().toISOString();
    record.updated_at = new Date().toISOString();
    if (!record.slug) record.slug = scenepackSlugFor(record.title, record.id);
    const index = store.items.indexOf(item);
    store.items[index] = record;
    const saved = await persistScenepackStore(env, store);
    if (!saved) return scenepackJson({ success: false, error: "Update failed. Please retry." }, 503);
    const access = await scenepackAccessState(session, env);
    return scenepackJson({ success: true, item: scenepackPublic(record, { unlocked: access.allowed, viewerKey }) });
  }

  // ── DELETE /api/scenepacks/:id ─────────────────────────────────────────────
  if (!action && method === "DELETE") {
    if (!canManage(item)) return scenepackJson({ success: false, error: "Unauthorized" }, 403);
    const index = store.items.indexOf(item);
    store.items.splice(index, 1);
    const saved = await persistScenepackStore(env, store);
    if (!saved) return scenepackJson({ success: false, error: "Delete failed. Please retry." }, 503);
    return scenepackJson({ success: true, deleted: true, id: item.id });
  }

  // ── POST /api/scenepacks/:id/view — deduplicated view counter ──────────────
  if (action === "view") {
    if (method !== "POST") return scenepackJson({ success: false, error: "Method not allowed" }, 405);
    const memoKey = `${item.id}:${viewerKey}`;
    const now = Date.now();
    if (scenepackViewMemo.size > SCENEPACK_VIEW_MEMO_MAX) {
      for (const [key, at] of scenepackViewMemo) {
        if (now - at > SCENEPACK_VIEW_MEMO_TTL) scenepackViewMemo.delete(key);
      }
      if (scenepackViewMemo.size > SCENEPACK_VIEW_MEMO_MAX) scenepackViewMemo.clear();
    }
    const last = scenepackViewMemo.get(memoKey);
    if (last && now - last < SCENEPACK_VIEW_MEMO_TTL) {
      return scenepackJson({ success: true, counted: false, views: Number(item.views) || 0 });
    }
    scenepackViewMemo.set(memoKey, now);
    item.views = (Number(item.views) || 0) + 1;
    await persistScenepackStore(env, store);
    return scenepackJson({ success: true, counted: true, views: item.views });
  }

  // ── POST /api/scenepacks/:id/like — toggle like ────────────────────────────
  if (action === "like") {
    if (method !== "POST") return scenepackJson({ success: false, error: "Method not allowed" }, 405);
    if (!session || !session.userId) return scenepackJson({ success: false, error: "Login required", code: "LOGIN_REQUIRED" }, 401);
    const likes = scenepackLikeSet(item).slice();
    const index = likes.indexOf(String(session.userId));
    if (index >= 0) likes.splice(index, 1);
    else likes.push(String(session.userId));
    item.likes = likes.slice(-5000);
    item.updated_at = new Date().toISOString();
    await persistScenepackStore(env, store);
    return scenepackJson({
      success: true,
      liked: index < 0,
      like_count: (Number(item.like_base) || 0) + likes.length,
    });
  }

  // ── POST /api/scenepacks/:id/download — hand out one link ──────────────────
  if (action === "download") {
    if (method !== "POST") return scenepackJson({ success: false, error: "Method not allowed" }, 405);
    let body = {};
    try { body = await request.json(); } catch (_) { body = {}; }
    const requestedId = String(body.download_id || body.id || "").trim();
    const downloads = Array.isArray(item.downloads) ? item.downloads : [];
    const target = requestedId ? downloads.find(entry => String(entry.id) === requestedId) : downloads[0];
    // Access is answered before the link check so a locked pack always asks the
    // visitor to verify instead of pretending the version does not exist.
    {
      const access = await scenepackAccessState(session, env);
      if (!access.allowed) return scenepackAccessDenied(access);
    }
    if (!target) {
      return scenepackJson({ success: false, code: "LINK_PENDING", error: "This version has no download link yet." }, 404);
    }
    const storage = scenepackStoragePublic(target);
    if (!storage.ready) {
      return scenepackJson({
        success: false,
        code: "LINK_INVALID",
        error: "This version's storage link could not be read. Please ask an admin to re-add it.",
      }, 409);
    }
    const base = `/api/scenepacks/${encodeURIComponent(item.id)}/file?d=${encodeURIComponent(target.id)}`;
    // A Drive folder is a set of clips: the site lists it and the visitor picks,
    // so nothing is ever handed a raw cloud URL.
    if (storage.folder) {
      const files = await scenepackWithSizes(env, target.storage, await scenepackDriveFolderFiles(target.storage.folder_id));
      return scenepackJson({
        success: true,
        directory: true,
        label: target.label,
        provider: storage.label,
        files: files.map(file => ({
          name: file.name,
          format: file.format,
          size: Number(file.size) || 0,
          parent: file.parent || "",
          url: `${base}&f=${encodeURIComponent(file.id)}`,
        })),
        downloads_count: item.downloads_count,
      });
    }
    item.downloads_count = (Number(item.downloads_count) || 0) + 1;
    item.updated_at = new Date().toISOString();
    await persistScenepackStore(env, store);
    // The browser only ever sees our own stream route, so the cloud host stays
    // a backend detail and the download keeps the site's UI.
    return scenepackJson({
      success: true,
      directory: false,
      url: base,
      label: target.label,
      format: target.format || "",
      provider: storage.label,
      downloads_count: item.downloads_count,
    });
  }

  // ── GET /api/scenepacks/:id/files — list one version's stored files ────────
  if (action === "files") {
    if (method !== "GET") return scenepackJson({ success: false, error: "Method not allowed" }, 405);
    if (item.status !== "published" && !canManage(item)) {
      return scenepackJson({ success: false, error: "Scenepack not found" }, 404);
    }
    {
      const access = await scenepackAccessState(session, env);
      if (!access.allowed) return scenepackAccessDenied(access);
    }
    const wantedId = String(url.searchParams.get("d") || "").trim();
    const versions = Array.isArray(item.downloads) ? item.downloads : [];
    const chosen = wantedId ? versions.find(entry => String(entry.id) === wantedId) : versions[0];
    if (!chosen) return scenepackJson({ success: false, error: "Version not found" }, 404);
    const storage = scenepackStoragePublic(chosen);
    if (!storage.ready) {
      return scenepackJson({ success: false, code: "LINK_INVALID", error: "This version's storage link could not be read." }, 409);
    }
    const base = `/api/scenepacks/${encodeURIComponent(item.id)}/file?d=${encodeURIComponent(chosen.id)}`;
    if (storage.folder) {
      const files = await scenepackWithSizes(env, chosen.storage, await scenepackDriveFolderFiles(chosen.storage.folder_id));
      return scenepackJson({
        success: true,
        directory: true,
        label: chosen.label,
        provider: storage.label,
        files: files.map(file => ({
          name: file.name,
          format: file.format,
          size: Number(file.size) || 0,
          parent: file.parent || "",
          url: `${base}&f=${encodeURIComponent(file.id)}`,
        })),
      });
    }
    const singleSize = await scenepackFileSize(env, chosen.storage, "");
    return scenepackJson({
      success: true,
      directory: false,
      label: chosen.label,
      provider: storage.label,
      files: [{
        name: chosen.label || "Scenepack",
        format: chosen.format || item.format || "",
        size: singleSize,
        parent: "",
        url: base,
      }],
    });
  }

  // ── GET /api/scenepacks/:id/file — stream one stored version ───────────────
  if (action === "file") {
    if (method !== "GET" && method !== "HEAD") {
      return scenepackJson({ success: false, error: "Method not allowed" }, 405);
    }
    if (item.status !== "published" && !canManage(item)) {
      return new Response("Not found", { status: 404 });
    }
    const wantedId = String(url.searchParams.get("d") || "").trim();
    const versions = Array.isArray(item.downloads) ? item.downloads : [];
    const chosen = wantedId ? versions.find(entry => String(entry.id) === wantedId) : versions[0];
    if (!chosen || !scenepackStoragePublic(chosen).ready) {
      return new Response("File not found", { status: 404 });
    }
    {
      const access = await scenepackAccessState(session, env);
      if (!access.allowed) return scenepackAccessDenied(access);
    }
    // Only a real save counts as a download.
    if (String(url.searchParams.get("dl") || "") === "1") {
      item.downloads_count = (Number(item.downloads_count) || 0) + 1;
      item.updated_at = new Date().toISOString();
      await persistScenepackStore(env, store);
    }
    return scenepackStreamResponse(env, request, chosen.storage, chosen, {
      fileId: String(url.searchParams.get("f") || "").trim(),
    });
  }

  // ── POST /api/scenepacks/:id/refresh-imdb — re-pull metadata from IMDb ─────
  if (action === "refresh-imdb") {
    if (method !== "POST") return scenepackJson({ success: false, error: "Method not allowed" }, 405);
    if (!canManage(item)) return scenepackJson({ success: false, error: "Unauthorized" }, 403);
    const imdbId = String((item.movie && item.movie.imdb_id) || "").trim();
    if (!imdbId) return scenepackJson({ success: false, error: "This pack has no IMDb ID." }, 400);
    const meta = await fetchOmdbTitle(imdbId);
    if (!meta) return scenepackJson({ success: false, error: "IMDb did not return metadata for this title." }, 502);
    item.movie = { ...scenepackMovieMeta(item.movie), ...scenepackMovieMeta(meta) };
    item.thumbnail = item.thumbnail || item.movie.poster;
    item.backdrop = item.movie.backdrop || item.thumbnail;
    item.updated_at = new Date().toISOString();
    await persistScenepackStore(env, store);
    const access = await scenepackAccessState(session, env);
    return scenepackJson({ success: true, item: scenepackPublic(item, { unlocked: access.allowed, viewerKey }) });
  }

  // ── POST /api/scenepacks/:id/status — moderation ───────────────────────────
  if (action === "status") {
    if (method !== "POST") return scenepackJson({ success: false, error: "Method not allowed" }, 405);
    if (!isAdmin) return scenepackJson({ success: false, error: "Unauthorized" }, 403);
    let body = {};
    try { body = await request.json(); } catch (_) { body = {}; }
    const status = normalizeScenepackStatus(body.status, "");
    if (!status) return scenepackJson({ success: false, error: "Unknown status" }, 400);
    item.status = status;
    item.featured = body.featured === undefined ? item.featured : body.featured === true;
    if (status === "published" && !item.published_at) item.published_at = new Date().toISOString();
    item.updated_at = new Date().toISOString();
    await persistScenepackStore(env, store);
    return scenepackJson({ success: true, item: scenepackPublic(item, { unlocked: true, viewerKey }) });
  }

  return scenepackJson({ success: false, error: "Unknown scenepack action" }, 404);
}

// ── Staff applications ──────────────────────────────────────────────────────
// Members apply for one of the two staff roles from /apply. Applications live in a
// single R2 document (volume is tiny), and only the founder can decide on them; the
// applicant hears the outcome as a Discord DM embed.
const STAFF_APPLICATIONS_KEY = "staff/applications.json";
const STAFF_SETTINGS_KEY = "staff/settings.json";
const STAFF_APPLICATION_COOLDOWN_MS = 7 * 24 * 60 * 60 * 1000;
const STAFF_APPLICATION_PENDING_LIMIT = 2;
const STAFF_ROLES = {
  "leak-uploader": {
    label: "Leak Uploader",
    blurb: "Find, check and publish editing leaks and stuff.",
  },
  moderator: {
    label: "Moderator",
    blurb: "Keep the feed, comments and Discord calm and on-topic.",
  },
};

// Each role has its own short rule list and its own questions: an uploader is asked
// about sources and verification, a moderator about reports and enforcement.
const STAFF_ROLE_FORMS = {
  "leak-uploader": {
    rules: [
      "Only upload files you have checked yourself.",
      "Credit the original creator.",
      "Fill in title, category, tags and thumbnail.",
      "No re-uploads of what is already listed.",
      "Send anything suspicious to the founder instead.",
    ],
    questions: [
      { key: "sources", label: "Where do your leaks come from?", placeholder: "Your own archive, creators you know, communities you are in…", min: 15, max: 500, required: true },
      { key: "verification", label: "How do you check a file before it goes live?", placeholder: "Virus scan, version check, opening the project once…", min: 20, max: 600, required: true },
      { key: "tools", label: "Which editing apps do you know well?", placeholder: "After Effects, Premiere Pro, Photoshop…", min: 0, max: 300, required: false },
    ],
  },
  moderator: {
    rules: [
      "Same rules for everyone, staff included.",
      "Log every warning, mute and ban with a reason.",
      "Never share member data or private DM screenshots.",
      "Explain decisions and pass unclear cases to the founder.",
      "Stay neutral in public arguments.",
    ],
    questions: [
      { key: "conflict", label: "A member keeps breaking the rules after a warning. What now?", placeholder: "The steps you would take.", min: 20, max: 600, required: true },
      { key: "report", label: "A report points at a friend on the team. What do you do?", placeholder: "We care about fairness here.", min: 20, max: 600, required: true },
      { key: "coverage", label: "When are you usually online?", placeholder: "Evenings GMT+3, weekends, etc.", min: 0, max: 300, required: false },
    ],
  },
};

function staffRoleForm(role) {
  return STAFF_ROLE_FORMS[role] || { rules: [], questions: [] };
}

// Answers ride along as a plain map so a role can add a question without a migration.
function normalizeStaffAnswers(role, input) {
  const questions = staffRoleForm(role).questions;
  const answers = {};
  for (const question of questions) {
    const raw = input && typeof input === "object" ? input[question.key] : "";
    const value = String(raw == null ? "" : raw).replace(/\s+/g, " ").trim().slice(0, question.max || 600);
    if (question.required && value.length < (question.min || 1)) {
      return { error: `${question.label} needs a longer answer.` };
    }
    if (value) answers[question.key] = value;
  }
  return { answers };
}
const STAFF_STATUSES = ["pending", "accepted", "rejected"];

function staffRoleLabel(role) {
  const entry = STAFF_ROLES[role];
  return entry ? entry.label : "Staff";
}

async function readStaffApplications(env) {
  const stored = await r2GetJSON(env, STAFF_APPLICATIONS_KEY, null).catch(() => null);
  const list = stored && Array.isArray(stored.applications) ? stored.applications : [];
  return list.filter(item => item && typeof item === "object" && item.id);
}

// Each role has its own intake switch, so the founder can close one role without
// touching the other. A missing record means "open", which keeps the first run working.
async function readStaffSettings(env) {
  const stored = await r2GetJSON(env, STAFF_SETTINGS_KEY, null).catch(() => null);
  const saved = stored && typeof stored.roles === "object" && stored.roles ? stored.roles : {};
  const roles = {};
  for (const key of Object.keys(STAFF_ROLES)) {
    roles[key] = saved[key] === false ? false : true;
  }
  return {
    roles,
    updated_at: stored && stored.updated_at ? stored.updated_at : null,
    updated_by: stored && stored.updated_by ? String(stored.updated_by) : "",
  };
}

async function writeStaffSettings(env, settings) {
  return r2PutJSON(env, STAFF_SETTINGS_KEY, settings);
}

async function writeStaffApplications(env, applications) {
  return r2PutJSON(env, STAFF_APPLICATIONS_KEY, {
    applications: applications.slice(0, 2000),
    updated_at: new Date().toISOString(),
  });
}

function staffPublicApplication(app, options = {}) {
  const includeStaffNotes = options.includeStaffNotes === true;
  return {
    id: app.id,
    role: app.role,
    role_label: staffRoleLabel(app.role),
    full_name: app.full_name,
    age: app.age,
    has_experience: Boolean(app.has_experience),
    experience_details: app.experience_details || "",
    motivation: app.motivation || "",
    hours_per_week: app.hours_per_week || "",
    timezone: app.timezone || "",
    rules_agreed: Boolean(app.rules_agreed),
    answers: app.answers && typeof app.answers === "object" ? app.answers : {},
    status: app.status,
    decision_note: app.decision_note || "",
    decided_at: app.decided_at || null,
    created_at: app.created_at,
    updated_at: app.updated_at || app.created_at,
    dm_sent: Boolean(app.dm_sent),
    ...(includeStaffNotes
      ? {
        user_id: app.user_id,
        user_name: app.user_name || "",
        username: app.username || "",
        avatar: app.avatar || "",
        decided_by: app.decided_by || "",
      }
      : {}),
  };
}

async function writeStaffApplicationNotification(env, application, decision) {
  const userId = String(application?.user_id || "");
  if (!userId) return false;
  const accepted = decision === "accepted";
  const received = decision === "received";
  const id = `staff_${application.id}_${decision}`;
  const existing = await r2GetJSON(env, "database/notifications.json", []).catch(() => []);
  const items = Array.isArray(existing) ? existing.filter(item => String(item?.id || "") !== id) : [];
  items.unshift({
    id,
    user_id: userId,
    title: received ? "Staff application received" : accepted ? "Staff application accepted" : "Staff application update",
    desc: received
      ? `Your ${staffRoleLabel(application.role)} application was received and is waiting for review.`
      : accepted
      ? `Your ${staffRoleLabel(application.role)} application was accepted. Check your Discord DMs for next steps.`
      : `Your ${staffRoleLabel(application.role)} application has been reviewed. Check your Discord DMs for details.`,
    link: "/apply",
    icon: received ? "fa-inbox" : accepted ? "fa-circle-check" : "fa-clipboard-check",
    category: "application",
    created_at: new Date().toISOString(),
  });
  return r2PutJSON(env, "database/notifications.json", items.slice(0, 2000));
}

// The DM is the only place the applicant learns the outcome, so a failure here is
// reported back to the founder instead of failing the whole decision.
async function sendStaffDecisionDM(env, app, status, note) {
  const channelId = await openDiscordDMChannel(env, app.user_id);
  if (!channelId) return false;
  const token = getSiteLogBotToken(env);
  if (!token) return false;
  const accepted = status === "accepted";
  const embed = {
    title: accepted ? "Staff application accepted" : "Staff application update",
    description: accepted
      ? `Welcome aboard — your **${staffRoleLabel(app.role)}** application was accepted. The team will reach out with the next steps.`
      : `Thanks for applying for **${staffRoleLabel(app.role)}**. This time we went with other candidates.`,
    color: accepted ? 0x22c55e : 0xef4444,
    fields: [
      { name: "Role", value: staffRoleLabel(app.role), inline: true },
      { name: "Decision", value: accepted ? "Accepted" : "Not accepted", inline: true },
      { name: "Applied", value: new Date(app.created_at).toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" }), inline: true },
      ...(note ? [{ name: "Note from the team", value: String(note).slice(0, 900) }] : []),
    ],
    footer: { text: "Zyrex staff team · you can re-apply from the site" },
    timestamp: new Date().toISOString(),
  };
  try {
    const response = await fetch(`${DISCORD_API}/channels/${channelId}/messages`, {
      method: "POST",
      headers: { Authorization: `Bot ${token}`, "Content-Type": "application/json" },
      body: JSON.stringify({ embeds: [embed], allowed_mentions: { parse: [] } }),
      signal: AbortSignal.timeout(5000),
    });
    if (response.status === 403) dmChannelMemo.delete(String(app.user_id));
    return response.ok;
  } catch (_) {
    return false;
  }
}

// A new application pings the founder so nothing sits unnoticed in the queue.
async function notifyFounderOfApplication(env, app) {
  const founderId = ADMIN_IDS[0];
  const channelId = await openDiscordDMChannel(env, founderId);
  const token = getSiteLogBotToken(env);
  if (!token || !channelId) return false;
  const embed = {
    title: "New staff application",
    description: `**${app.user_name || app.username || app.user_id}** applied for **${staffRoleLabel(app.role)}**.`,
    color: 0x6366f1,
    fields: [
      { name: "Age", value: String(app.age), inline: true },
      { name: "Experience", value: app.has_experience ? "Yes" : "No", inline: true },
      { name: "Availability", value: app.hours_per_week ? `${app.hours_per_week} h / week` : "Not given", inline: true },
    ],
    footer: { text: "Review it in Settings → Staff applications" },
    timestamp: new Date().toISOString(),
  };
  try {
    const response = await fetch(`${DISCORD_API}/channels/${channelId}/messages`, {
      method: "POST",
      headers: { Authorization: `Bot ${token}`, "Content-Type": "application/json" },
      body: JSON.stringify({ embeds: [embed], allowed_mentions: { parse: [] } }),
      signal: AbortSignal.timeout(5000),
    });
    return response.ok;
  } catch (_) {
    return false;
  }
}

async function handleStaffApplyAPI(request, env, path, session) {
  if (!session || !session.userId) {
    return json({ success: false, error: "Sign in with Discord to continue.", code: "NOT_LOGGED_IN" }, 401);
  }
  const applications = await readStaffApplications(env);
  const userId = String(session.userId);
  const now = Date.now();
  const mine = applications.filter(app => app.user_id === userId);

  if (path === "/api/staff/apply" && request.method === "GET") {
    const identity = await resolveProfileIdentity(env, userId).catch(() => ({}));
    const settings = await readStaffSettings(env);
    return json({
      success: true,
      roles: Object.entries(STAFF_ROLES).map(([value, meta]) => ({
        value,
        label: meta.label,
        blurb: meta.blurb,
        open: settings.roles[value] !== false,
        rules: staffRoleForm(value).rules,
        questions: staffRoleForm(value).questions,
      })),
      intake: { roles: settings.roles, updated_at: settings.updated_at },
      profile: {
        name: identity.name || session.globalName || session.displayName || session.username || "",
        username: session.username || "",
      },
      applications: mine.map(app => staffPublicApplication(app)),
      pending: mine.filter(app => app.status === "pending").length,
      pending_limit: STAFF_APPLICATION_PENDING_LIMIT,
      cooldown_days: Math.round(STAFF_APPLICATION_COOLDOWN_MS / 86400000),
      can_apply: mine.filter(app => app.status === "pending").length < STAFF_APPLICATION_PENDING_LIMIT,
    }, 200, { "Cache-Control": "no-store, private" });
  }

  if (path === "/api/staff/apply" && request.method === "POST") {
    let body = {};
    try { body = await request.json(); } catch (_) { body = {}; }

    const role = String(body.role || "").trim();
    if (!STAFF_ROLES[role]) return json({ success: false, error: "Choose the role you are applying for." }, 400);
    const intake = await readStaffSettings(env);
    if (intake.roles[role] === false) {
      return json({
        success: false,
        error: `Applications for ${staffRoleLabel(role)} are closed right now.`,
        code: "role_closed",
      }, 403);
    }
    const fullName = String(body.full_name || "").trim().replace(/\s+/g, " ").slice(0, 60);
    if (fullName.length < 2) return json({ success: false, error: "Tell us your name (at least 2 characters)." }, 400);
    const age = Number(body.age);
    if (!Number.isInteger(age) || age < 13 || age > 99) {
      return json({ success: false, error: "Enter your age as a number between 13 and 99." }, 400);
    }
    const hasExperience = body.has_experience === true || body.has_experience === "yes";
    const experienceDetails = String(body.experience_details || "").trim().slice(0, 1200);
    if (hasExperience && experienceDetails.length < 20) {
      return json({ success: false, error: "Describe your experience in a sentence or two (20+ characters)." }, 400);
    }
    const motivation = String(body.motivation || "").trim().slice(0, 1000);
    if (motivation.length < 20) {
      return json({ success: false, error: "Tell us why you want this role (20+ characters)." }, 400);
    }
    if (body.rules_agreed !== true) {
      return json({ success: false, error: "Please confirm you have read and accept the site rules." }, 400);
    }
    const normalizedAnswers = normalizeStaffAnswers(role, body.answers);
    if (normalizedAnswers.error) {
      return json({ success: false, error: normalizedAnswers.error }, 400);
    }
    const hoursRaw = String(body.hours_per_week || "").trim();
    const hours = hoursRaw && /^\d{1,2}$/.test(hoursRaw) && Number(hoursRaw) > 0 && Number(hoursRaw) <= 80 ? Number(hoursRaw) : "";
    const timezone = String(body.timezone || "").trim().slice(0, 40);

    if (mine.filter(app => app.status === "pending").length >= STAFF_APPLICATION_PENDING_LIMIT) {
      return json({ success: false, error: "You already have applications waiting for review." }, 409);
    }
    const openSameRole = mine.find(app => app.role === role && app.status === "pending");
    if (openSameRole) {
      return json({ success: false, error: `You already have a ${staffRoleLabel(role)} application under review.` }, 409);
    }
    const rejectedSameRole = mine
      .filter(app => app.role === role && app.status === "rejected")
      .sort((a, b) => Date.parse(b.decided_at || b.updated_at || b.created_at) - Date.parse(a.decided_at || a.updated_at || a.created_at))[0];
    if (rejectedSameRole) {
      const decidedAt = Date.parse(rejectedSameRole.decided_at || rejectedSameRole.updated_at || rejectedSameRole.created_at) || 0;
      const waitMs = STAFF_APPLICATION_COOLDOWN_MS - (now - decidedAt);
      if (waitMs > 0) {
        const days = Math.max(1, Math.ceil(waitMs / 86400000));
        return json({ success: false, error: `You can apply for this role again in ${days} day${days === 1 ? "" : "s"}.` }, 429);
      }
    }

    const identity = await resolveProfileIdentity(env, userId).catch(() => ({}));
    const application = {
      id: "sa-" + now.toString(36) + "-" + Math.random().toString(36).slice(2, 7),
      user_id: userId,
      user_name: identity.name || session.globalName || session.displayName || session.username || "Zyrex Member",
      username: session.username || "",
      avatar: identity.avatar || profileAvatarUrl(userId, ""),
      role,
      full_name: fullName,
      age,
      has_experience: hasExperience,
      experience_details: hasExperience ? experienceDetails : "",
      motivation,
      hours_per_week: hours,
      timezone,
      answers: normalizedAnswers.answers || {},
      rules_agreed: true,
      status: "pending",
      decision_note: "",
      decided_by: "",
      decided_at: null,
      dm_sent: false,
      created_at: new Date(now).toISOString(),
      updated_at: new Date(now).toISOString(),
    };
    applications.unshift(application);
    const saved = await writeStaffApplications(env, applications);
    if (!saved) return json({ success: false, error: "Could not save your application. Please try again." }, 503);
    await writeStaffApplicationNotification(env, application, "received").catch(() => false);
    const notify = notifyFounderOfApplication(env, application).catch(() => false);
    // The founder ping is best effort: the application is already stored.
    notify.catch(() => {});
    return json({ success: true, application: staffPublicApplication(application) }, 201, { "Cache-Control": "no-store, private" });
  }

  if (path === "/api/staff/apply" && request.method === "DELETE") {
    const id = String(urlSearchId(request) || "").trim();
    const target = mine.find(app => app.id === id && app.status === "pending");
    if (!target) return json({ success: false, error: "That application is no longer editable." }, 404);
    target.status = "withdrawn";
    target.updated_at = new Date().toISOString();
    const saved = await writeStaffApplications(env, applications);
    if (!saved) return json({ success: false, error: "Could not withdraw the application." }, 503);
    return json({ success: true }, 200, { "Cache-Control": "no-store, private" });
  }

  return json({ success: false, error: "Not found" }, 404);
}

function urlSearchId(request) {
  try {
    return new URL(request.url).searchParams.get("id") || "";
  } catch (_) {
    return "";
  }
}

async function handleStaffSettingsAPI(request, env, session) {
  const current = await readStaffSettings(env);

  if (request.method === "GET") {
    return json({
      success: true,
      is_admin: isAdminSession(session),
      roles: Object.entries(STAFF_ROLES).map(([value, meta]) => ({
        value,
        label: meta.label,
        blurb: meta.blurb,
        open: current.roles[value] !== false,
        rules: staffRoleForm(value).rules,
        questions: staffRoleForm(value).questions,
      })),
      updated_at: current.updated_at,
    }, 200, { "Cache-Control": "no-store, private" });
  }

  if (request.method !== "POST") return json({ success: false, error: "Method not allowed" }, 405);
  if (!isAdminSession(session)) return json({ success: false, error: "Founder access required." }, 403);

  let body = {};
  try { body = await request.json(); } catch (_) { body = {}; }
  const patch = {};
  if (body.roles && typeof body.roles === "object" && !Array.isArray(body.roles)) {
    for (const [key, value] of Object.entries(body.roles)) {
      if (!STAFF_ROLES[key]) continue;
      patch[key] = value === true || value === "open" || value === 1;
    }
  }
  const role = String(body.role || "").trim();
  if (STAFF_ROLES[role] && body.open !== undefined) {
    patch[role] = body.open === true || body.open === "open" || body.open === 1;
  }
  if (!Object.keys(patch).length) {
    return json({ success: false, error: "Nothing to update." }, 400);
  }
  const roles = { ...current.roles, ...patch };
  const payload = {
    roles,
    updated_at: new Date().toISOString(),
    updated_by: String(session.userId),
  };
  const saved = await writeStaffSettings(env, payload);
  if (!saved) return json({ success: false, error: "Could not save the intake settings." }, 503);
  return json({
    success: true,
    roles: Object.entries(STAFF_ROLES).map(([value, meta]) => ({
      value,
      label: meta.label,
      open: roles[value] !== false,
    })),
    updated_at: payload.updated_at,
  }, 200, { "Cache-Control": "no-store, private" });
}

async function handleStaffApplicationsAPI(request, env, path, session) {
  if (!isAdminSession(session)) {
    return json({ success: false, error: "Founder access required." }, 403);
  }
  const applications = await readStaffApplications(env);

  if (request.method === "GET") {
    const status = String(new URL(request.url).searchParams.get("status") || "").trim();
    const filtered = STAFF_STATUSES.includes(status) ? applications.filter(app => app.status === status) : applications;
    const counts = STAFF_STATUSES.reduce((acc, key) => {
      acc[key] = applications.filter(app => app.status === key).length;
      return acc;
    }, {});
    return json({
      success: true,
      applications: filtered
        .slice()
        .sort((a, b) => Date.parse(b.created_at) - Date.parse(a.created_at))
        .map(app => staffPublicApplication(app, { includeStaffNotes: true })),
      counts: { ...counts, all: applications.length },
      roles: Object.entries(STAFF_ROLES).map(([value, meta]) => ({ value, label: meta.label })),
    }, 200, { "Cache-Control": "no-store, private" });
  }

  if (request.method === "POST") {
    let body = {};
    try { body = await request.json(); } catch (_) { body = {}; }
    const decision = String(body.decision || "").trim();
    if (decision !== "accepted" && decision !== "rejected") {
      return json({ success: false, error: "Decision must be accepted or rejected." }, 400);
    }
    const index = applications.findIndex(app => app.id === String(body.id || ""));
    if (index < 0) return json({ success: false, error: "That application no longer exists." }, 404);
    const application = applications[index];
    if (application.status === decision) return json({ success: false, error: "That decision is already saved." }, 409);
    const note = String(body.note || "").trim().slice(0, 900);
    application.status = decision;
    application.decision_note = note;
    application.decided_by = String(session.userId);
    application.decided_at = new Date().toISOString();
    application.updated_at = application.decided_at;
    const saved = await writeStaffApplications(env, applications);
    if (!saved) return json({ success: false, error: "Could not save the decision." }, 503);
    const sent = await sendStaffDecisionDM(env, application, decision, note).catch(() => false);
    await writeStaffApplicationNotification(env, application, decision).catch(() => false);
    if (sent) {
      application.dm_sent = true;
      await writeStaffApplications(env, applications).catch(() => false);
    }
    return json({
      success: true,
      dm_sent: sent,
      application: staffPublicApplication(applications[index], { includeStaffNotes: true }),
    }, 200, { "Cache-Control": "no-store, private" });
  }

  return json({ success: false, error: "Method not allowed" }, 405);
}

// ── Discord invite watch ─────────────────────────────────────────────────────
// Invite links are the first thing a raid burns: Discord invalidates them, or the
// link that leaked keeps letting people in. The cron checks the live invite every
// two minutes, rotates it when Discord killed it or when joins spike, and the site
// reads the current URL instead of trusting the copy baked into each page.
const DISCORD_INVITE_KEY = "system/discord_invite.json";
const DISCORD_INVITE_DEFAULT_URL = "https://discord.gg/4J3tars4QS";
const DISCORD_INVITE_URL_PATTERN = /^(?:https?:\/\/)?(?:www\.)?(?:discord\.gg|discord\.com\/invite)\/([A-Za-z0-9-]{2,64})\/?$/i;
const DISCORD_INVITE_STATE_TTL_MS = 15 * 60 * 1000;   // re-check when the cron has not run
const DISCORD_INVITE_ALERT_GAP_MS = 30 * 60 * 1000;   // one alert per reason per half hour
const DISCORD_RAID_JOIN_THRESHOLD = 25;               // joins between two checks
const DISCORD_RAID_MIN_MEMBERS = 50;
const DISCORD_INVITE_HISTORY_LIMIT = 20;

function normalizeDiscordInviteUrl(value) {
  const match = String(value == null ? "" : value).trim().match(DISCORD_INVITE_URL_PATTERN);
  return match ? `https://discord.gg/${match[1]}` : "";
}

function discordInviteCode(value) {
  const match = String(value == null ? "" : value).trim().match(DISCORD_INVITE_URL_PATTERN);
  return match ? match[1] : "";
}

function defaultDiscordInviteState() {
  return {
    url: DISCORD_INVITE_DEFAULT_URL,
    code: discordInviteCode(DISCORD_INVITE_DEFAULT_URL),
    status: "unknown",
    reason: "",
    source: "default",
    checked_at: null,
    changed_at: null,
    members: { total: 0, online: 0, delta: 0 },
    raid: { suspected: false, detected_at: null, joins: 0 },
    alerts: {},
    history: [],
  };
}

async function readDiscordInviteState(env) {
  const stored = await r2GetJSON(env, DISCORD_INVITE_KEY, null).catch(() => null);
  const base = defaultDiscordInviteState();
  if (!stored || typeof stored !== "object") return base;
  const url = normalizeDiscordInviteUrl(stored.url) || base.url;
  return {
    ...base,
    ...stored,
    url,
    code: discordInviteCode(url),
    members: { ...base.members, ...(stored.members || {}) },
    raid: { ...base.raid, ...(stored.raid || {}) },
    alerts: stored.alerts && typeof stored.alerts === "object" ? stored.alerts : {},
    history: Array.isArray(stored.history) ? stored.history.slice(-DISCORD_INVITE_HISTORY_LIMIT) : [],
  };
}

async function writeDiscordInviteState(env, state) {
  return r2PutJSON(env, DISCORD_INVITE_KEY, state);
}

// Public invite lookup: no token needed and it reports whether Discord still knows the code.
async function inspectDiscordInvite(env, code) {
  if (!code) return { ok: false, status: 0, error: "no_invite" };
  try {
    const response = await fetch(
      `${DISCORD_API}/invites/${encodeURIComponent(code)}?with_counts=true&with_expiration=true`,
      { headers: { Accept: "application/json" }, signal: AbortSignal.timeout(8000) }
    );
    const data = await response.json().catch(() => null);
    if (!response.ok) {
      return {
        ok: false,
        status: response.status,
        error: String(data?.code || data?.message || `http_${response.status}`),
        gone: response.status === 404 || response.status === 410,
      };
    }
    return {
      ok: true,
      status: response.status,
      guild: data?.guild ? { id: String(data.guild.id || ""), name: String(data.guild.name || "") } : null,
      members: {
        total: Number(data?.approximate_member_count) || 0,
        online: Number(data?.approximate_presence_count) || 0,
      },
      expires_at: data?.expires_at || null,
    };
  } catch (error) {
    return { ok: false, status: 0, error: String(error?.message || "network"), transient: true };
  }
}

async function fetchGuildCounts(env) {
  const guildId = env.GUILD_ID || "1518954946110685184";
  try {
    const result = await discordApiFetch(env, `/guilds/${guildId}?with_counts=true`);
    if (!result.ok) return { ok: false, error: result.reason || `http_${result.status}` };
    return {
      ok: true,
      total: Number(result.body?.approximate_member_count) || 0,
      online: Number(result.body?.approximate_presence_count) || 0,
    };
  } catch (error) {
    return { ok: false, error: String(error?.message || "network") };
  }
}

// A rotated invite has to come from a channel the log bot can invite people to. The
// configured channel wins; otherwise the first general/welcome channel that works.
const INVITE_CHANNEL_HINTS = ["welcome", "invite", "start-here", "rules", "general", "chat", "main"];

async function inviteChannelCandidates(env) {
  const configured = String(env.DISCORD_INVITE_CHANNEL_ID || "").trim();
  const candidates = configured ? [configured] : [];
  if (candidates.length >= 3) return candidates;
  try {
    const guildId = env.GUILD_ID || "1518954946110685184";
    const result = await discordApiFetch(env, `/guilds/${guildId}/channels`);
    if (!result.ok || !Array.isArray(result.body)) return candidates;
    const text = result.body.filter(channel => channel && (channel.type === 0 || channel.type === 5));
    const score = channel => {
      const name = String(channel.name || "").toLowerCase();
      const hit = INVITE_CHANNEL_HINTS.findIndex(hint => name.includes(hint));
      return hit < 0 ? INVITE_CHANNEL_HINTS.length : hit;
    };
    for (const channel of text.slice().sort((a, b) => score(a) - score(b))) {
      const id = String(channel.id || "");
      if (id && !candidates.includes(id)) candidates.push(id);
    }
  } catch (_) {}
  return candidates;
}

async function createDiscordInvite(env) {
  const candidates = await inviteChannelCandidates(env);
  for (const channelId of candidates.slice(0, 5)) {
    try {
      const result = await discordApiFetch(env, `/channels/${channelId}/invites`, {
        method: "POST",
        body: { max_age: 0, max_uses: 0, temporary: false, unique: false },
        reason: "Zyrex invite watch",
      });
      if (!result.ok) continue;
      const url = normalizeDiscordInviteUrl(`https://discord.gg/${result.body?.code || ""}`);
      if (url) return url;
    } catch (_) {}
  }
  return null;
}

// A rotation only helps if the leaked link stops working, so the old code is deleted.
// Discord answers 404 for a code it already killed, which is the outcome we want.
async function revokeDiscordInvite(env, code) {
  if (!code) return false;
  try {
    const result = await discordApiFetch(env, `/invites/${encodeURIComponent(code)}`, {
      method: "DELETE",
      reason: "Zyrex invite watch",
    });
    return Boolean(result && (result.ok || result.status === 404));
  } catch (_) {
    return false;
  }
}

async function alertInviteWatch(env, state, kind, fields) {
  const now = Date.now();
  const last = Number(state.alerts?.[kind]) || 0;
  if (now - last < DISCORD_INVITE_ALERT_GAP_MS) return false;
  const colors = { rotated: 0xf0b429, invalid: 0xef4444, raid: 0xef4444, restored: 0x22c55e };
  try {
    const result = await discordApiFetch(env, `/channels/${SITE_LOG_CHANNEL_ID}/messages`, {
      method: "POST",
      body: {
        embeds: [{
          title: kind === "rotated" ? "Discord invite rotated" : kind === "raid" ? "Raid pattern on the invite" : "Discord invite needs attention",
          color: colors[kind] || 0xf0b429,
          description: kind === "rotated"
            ? "The site invite was replaced. Every page now serves the new link."
            : kind === "raid"
              ? "Joins spiked between two checks, so the invite was rotated to kill the leaked link."
              : "Discord no longer answers for the site invite and no replacement could be created.",
          fields: [
            ...fields,
            { name: "Invite", value: state.url || "none", inline: false },
          ],
          timestamp: new Date(now).toISOString(),
          footer: { text: "Zyrex invite watch" },
        }],
        allowed_mentions: { parse: [] },
      },
    });
    if (!result.ok) return false;
    state.alerts = { ...(state.alerts || {}), [kind]: now };
    return true;
  } catch (_) {
    return false;
  }
}

function raidJoinThreshold(env) {
  const value = Number(env?.DISCORD_RAID_JOIN_THRESHOLD);
  return Number.isFinite(value) && value > 0 ? Math.floor(value) : DISCORD_RAID_JOIN_THRESHOLD;
}

function raidMinMembers(env) {
  const value = Number(env?.DISCORD_RAID_MIN_MEMBERS);
  return Number.isFinite(value) && value > 0 ? Math.floor(value) : DISCORD_RAID_MIN_MEMBERS;
}

// One cron pass: verify the invite, notice join spikes, rotate when needed.
async function runDiscordInviteWatch(env) {
  const state = await readDiscordInviteState(env);
  const now = Date.now();
  const configured = normalizeDiscordInviteUrl(env.DISCORD_INVITE_URL) || DISCORD_INVITE_DEFAULT_URL;
  // A manual override or a previous rotation wins over the copy in the config.
  if (!state.code || (state.source === "default" && state.url !== configured)) {
    state.url = configured;
    state.code = discordInviteCode(configured);
    state.source = "default";
  }

  const invite = await inspectDiscordInvite(env, state.code);
  const guild = await fetchGuildCounts(env);
  // The bot gives the reliable count; the public invite is the fallback when it cannot read
  // the guild, so the panel still shows something useful.
  const inviteMembers = invite.ok ? invite.members : null;
  const previousTotal = Number(state.members?.total) || 0;
  const totalNow = guild.ok ? guild.total : (Number(inviteMembers?.total) || previousTotal);
  const onlineNow = guild.ok ? guild.online : (Number(inviteMembers?.online) || Number(state.members?.online) || 0);
  const joins = totalNow && previousTotal ? Math.max(0, totalNow - previousTotal) : 0;
  const raidSuspected = Boolean(totalNow && previousTotal && totalNow >= raidMinMembers(env) && joins >= raidJoinThreshold(env));

  state.members = { total: totalNow, online: onlineNow, delta: joins };
  if (raidSuspected) {
    state.raid = { suspected: true, detected_at: new Date(now).toISOString(), joins, members: totalNow };
  } else if (state.raid?.suspected) {
    state.raid = { ...state.raid, suspected: false };
  }

  const inviteGone = !invite.ok && !invite.transient && (invite.gone || invite.status === 400 || invite.status === 403);
  const previousCode = state.code;
  let nextUrl = "";

  if (inviteGone || raidSuspected) {
    nextUrl = await createDiscordInvite(env);
  }

  if (nextUrl && nextUrl !== state.url) {
    state.url = nextUrl;
    state.code = discordInviteCode(nextUrl);
    state.source = "rotated";
    state.status = "rotated";
    state.reason = raidSuspected ? "raid" : "invalid_invite";
    state.changed_at = new Date(now).toISOString();
    const revoked = await revokeDiscordInvite(env, previousCode === state.code ? "" : previousCode);
    await alertInviteWatch(env, state, raidSuspected ? "raid" : "rotated", [
      { name: "Reason", value: raidSuspected ? `Join spike: +${joins} members` : `Discord rejected the code (${invite.error || invite.status})`, inline: false },
      { name: "Members", value: `${state.members.total} total · ${state.members.online} online`, inline: false },
      { name: "Old link", value: previousCode ? (revoked ? `\`${previousCode}\` revoked` : `\`${previousCode}\` is still live — the bot could not revoke it`) : "none", inline: false },
    ]);
  } else if (inviteGone) {
    // Nothing to rotate to: keep the old URL but make the failure visible to staff.
    state.status = "invalid";
    state.reason = String(invite.error || invite.status || "invalid_invite");
    await alertInviteWatch(env, state, "invalid", [
      { name: "Discord answer", value: state.reason, inline: false },
      { name: "Fix", value: "Give the bot Create Invite in a channel and set DISCORD_INVITE_CHANNEL_ID.", inline: false },
    ]);
  } else if (invite.ok) {
    state.status = "ok";
    state.reason = "";
    if (raidSuspected) {
      await alertInviteWatch(env, state, "raid", [
        { name: "Join spike", value: `+${joins} members in one interval`, inline: false },
      ]);
    }
  }

  if (raidSuspected || state.status === "ok") {
    state.history = [...(state.history || []), {
      at: new Date(now).toISOString(),
      status: state.status,
      code: state.code,
      joins,
      members: state.members.total,
    }].slice(-DISCORD_INVITE_HISTORY_LIMIT);
  }

  state.checked_at = new Date(now).toISOString();
  await writeDiscordInviteState(env, state);
  return state;
}

function publicDiscordInviteState(state) {
  return {
    url: state.url,
    code: state.code,
    status: state.status,
    reason: state.reason,
    source: state.source,
    checked_at: state.checked_at,
    changed_at: state.changed_at,
    members: { total: state.members?.total || 0, online: state.members?.online || 0, delta: state.members?.delta || 0 },
    raid: { suspected: Boolean(state.raid?.suspected), detected_at: state.raid?.detected_at || null, joins: state.raid?.joins || 0 },
  };
}

// A page render must never wait on Discord, so the inline refresh is throttled per isolate
// and the cron does the real work.
let inviteInlineRefreshAt = 0;

async function handleDiscordInviteAPI(request, env, session, hasMasterKey = false) {
  const state = await readDiscordInviteState(env);

  if (request.method === "GET") {
    const now = Date.now();
    const stale = !state.checked_at || now - Date.parse(state.checked_at) > DISCORD_INVITE_STATE_TTL_MS;
    const canRefresh = now - inviteInlineRefreshAt > 5 * 60 * 1000;
    let current = state;
    if (stale && canRefresh) {
      inviteInlineRefreshAt = now;
      current = await runDiscordInviteWatch(env).catch(() => state);
    }
    const wantsDebug = new URL(request.url).searchParams.get("debug") === "1";
    if (wantsDebug && (isAdminSession(session) || hasMasterKey)) {
      // Founder-only view of the two lookups, so a silent count failure is visible.
      const [invite, guild] = await Promise.all([
        inspectDiscordInvite(env, state.code),
        fetchGuildCounts(env),
      ]);
      return json({
        success: true,
        ...publicDiscordInviteState(current),
        debug: {
          bot_tokens: discordTokenCandidates(env).map(item => item.name),
          configured_channel: String(env.DISCORD_INVITE_CHANNEL_ID || ""),
          invite,
          guild,
        },
      }, 200, { "Cache-Control": "no-store, private" });
    }
    // Public and cacheable: the link is the same for every visitor, and the gate reads it
    // on every HTML render.
    return json({
      success: true,
      ...publicDiscordInviteState(current),
    }, 200, { "Cache-Control": "public, max-age=60, stale-while-revalidate=300" });
  }

  if (request.method !== "POST") return json({ success: false, error: "Method not allowed" }, 405);
  if (!isAdminSession(session) && !hasMasterKey) return json({ success: false, error: "Founder access required." }, 403);

  let body = {};
  try { body = await request.json(); } catch (_) { body = {}; }
  const action = String(body.action || "rotate").trim();

  if (action === "set") {
    const url = normalizeDiscordInviteUrl(body.url);
    if (!url) return json({ success: false, error: "That is not a Discord invite link." }, 400);
    const configured = normalizeDiscordInviteUrl(env.DISCORD_INVITE_URL) || DISCORD_INVITE_DEFAULT_URL;
    const next = {
      ...state,
      url,
      code: discordInviteCode(url),
      // Back on the configured link, the config is authoritative again.
      source: url === configured ? "default" : "manual",
      status: "ok",
      reason: "",
      changed_at: new Date().toISOString(),
      checked_at: null,
    };
    await writeDiscordInviteState(env, next);
    const fresh = await runDiscordInviteWatch(env).catch(() => next);
    return json({ success: true, ...publicDiscordInviteState(fresh), is_admin: true }, 200, { "Cache-Control": "no-store" });
  }

  if (action === "revoke") {
    const code = String(body.code || "").trim() || discordInviteCode(body.url);
    if (!/^[A-Za-z0-9-]{2,64}$/.test(code)) return json({ success: false, error: "Give the invite code to revoke." }, 400);
    if (code === state.code) return json({ success: false, error: "That is the live invite. Rotate it instead." }, 400);
    const revoked = await revokeDiscordInvite(env, code);
    return json({ success: revoked, revoked }, revoked ? 200 : 502, { "Cache-Control": "no-store" });
  }

  if (action !== "rotate") return json({ success: false, error: "Unknown action." }, 400);

  const previousCode = state.code;
  const url = await createDiscordInvite(env);
  if (!url) {
    return json({
      success: false,
      error: "The bot could not create an invite. Check DISCORD_INVITE_CHANNEL_ID and its Create Invite permission.",
    }, 503);
  }
  const next = {
    ...state,
    url,
    code: discordInviteCode(url),
    source: "rotated",
    status: "rotated",
    reason: "manual",
    changed_at: new Date().toISOString(),
    checked_at: null,
  };
  if (previousCode && previousCode !== next.code) await revokeDiscordInvite(env, previousCode);
  await writeDiscordInviteState(env, next);
  const fresh = await runDiscordInviteWatch(env).catch(() => next);
  return json({ success: true, ...publicDiscordInviteState(fresh), is_admin: true }, 200, { "Cache-Control": "no-store" });
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    
    // Bypass: dl subdomain serves static download page from Pages
    // Subdomain dl.zyrexediting.xyz serves the download.html page via ASSETS
    if (url.hostname === "dl.zyrexediting.xyz") {
      if (!url.pathname.startsWith("/api/")) {
        if (env.ASSETS) {
          const assetsUrl = new URL(request.url);
          if (assetsUrl.pathname === "/" || assetsUrl.pathname === "") {
            assetsUrl.pathname = "/download.html";
          }
          return env.ASSETS.fetch(new Request(assetsUrl.toString(), request));
        }
      }
    }
    // Thumbnail CDN: serve images from R2 via thumbnail.zyrexediting.xyz
    if (url.hostname === "thumbnail.zyrexediting.xyz") {
      const THUMB_PREFIX = "thumbnails/";
      const filename = url.pathname.replace(/^\/+/, "");
      if (!filename) return new Response("thumbnail.zyrexediting.xyz", { headers: { "content-type": "text/plain" } });
      
      // GET/HEAD: serve thumbnail or video from R2. Videos need Range support so the
      // browser can seek and stream instead of downloading the whole file.
      if (request.method === "GET" || request.method === "HEAD") {
        const cacheTTL = 31536000; // 1 year
        const ext = filename.split('.').pop().toLowerCase();
        const mimeMap = {
          jpg: "image/jpeg", jpeg: "image/jpeg", png: "image/png", gif: "image/gif", webp: "image/webp",
          mp4: "video/mp4", m4v: "video/mp4", webm: "video/webm", mov: "video/quicktime",
        };
        const contentType = mimeMap[ext] || "image/jpeg";
        const isVideo = /^video\//.test(contentType);
        try {
          const rangeHeader = isVideo ? request.headers.get("Range") : null;
          const obj = await env.STORAGE.get(THUMB_PREFIX + filename, rangeHeader ? { range: request.headers } : undefined);
          if (obj) {
            const headers = {
              "Content-Type": contentType,
              "Cache-Control": isVideo ? `public, max-age=${cacheTTL}, immutable` : `public, max-age=${cacheTTL}`,
              "Access-Control-Allow-Origin": "*",
              "Accept-Ranges": "bytes",
            };
            if (isVideo) {
              if (obj.range) {
                const offset = Number(obj.range.offset) || 0;
                const length = Number(obj.range.length) || (obj.size - offset);
                headers["Content-Range"] = `bytes ${offset}-${offset + length - 1}/${obj.size}`;
                headers["Content-Length"] = String(length);
              } else {
                headers["Content-Length"] = String(obj.size);
              }
            }
            const status = isVideo && rangeHeader ? 206 : 200;
            return new Response(request.method === "HEAD" ? null : obj.body, { status, headers });
          }
        } catch(e) { console.error("CDN fetch error:", e.message); }
        return new Response(null, { status: 404 });
      }
      
      // POST /upload: upload thumbnail to R2
      if (request.method === "POST" && url.pathname === "/upload") {
        try {
          const body = await request.json();
          const { filename: upName, data: base64Data } = body;
          if (!upName || !base64Data) return json({ error: "filename and data required" }, 400);
          
          const binary = Uint8Array.from(atob(base64Data), c => c.charCodeAt(0));
          await env.STORAGE.put(THUMB_PREFIX + upName, binary);
          return json({ success: true, url: `https://thumbnail.zyrexediting.xyz/${upName}` });
        } catch(e) {
          return json({ error: publicErrorMessage(e) }, 500);
        }
      }
      
      return new Response(null, { status: 405 });
    }
    // Bypass: storage subdomain handled by Cloudflare Tunnel (SFTPGo on local machine)
    if (url.hostname === "storage.zyrexediting.xyz") {
      return fetch(request);
    }
    const path = url.pathname;
      const providedApiKey = extractApiKey(request, url);
      const hasMasterKey = isMasterApiKey(providedApiKey, env);
      const hasAppKey = isValidAppApiKey(providedApiKey, env);
      const hasReconcileKey = !!env.ZYREX_RECONCILE_KEY && providedApiKey === env.ZYREX_RECONCILE_KEY;

    if (request.method === "OPTIONS") {
      return new Response(null, { headers: corsHeaders });
    }

    await resolveSession(request, env);

    if (path.startsWith("/api/")) {
      const isPublicEndpoint = path === "/api/login" || 
                               path === "/api/auth/callback" || 
                               path === "/api/auth/logout" || 
                               path === "/api/logout" || 
                               path === "/api/me" ||
                               path === "/api/health" ||
                               path === "/api/media" ||
                               path.startsWith("/api/status") ||
                               path.startsWith("/api/lookup/") ||
                               path.startsWith("/api/products") ||
                               path.startsWith("/api/installer") ||
                               path.startsWith("/api/comments") ||
                               path.startsWith("/api/notifications") ||
                               path.startsWith("/api/guild/") ||
                               path.startsWith("/api/discord/") ||
                               path.startsWith("/api/downloads/") ||
                               path.startsWith("/api/avatar/") || 
                               path.startsWith("/api/banner/") ||
                               path.startsWith("/api/presets/") ||
                               path === "/api/resource-stats" ||
                               path === "/api/team" ||
                               path === "/api/telemetry/client-error" ||
                               path.startsWith("/api/presence") ||
                               path.startsWith("/api/verify") ||
                               path.startsWith("/api/sftpgo") ||
                               (path === "/api/access/unlock") ||
                               path.startsWith("/api/cloud") ||
                               path.startsWith("/api/admin") ||
                               path.startsWith("/api/discord-user") ||
                               path.startsWith("/api/check-uploader") ||
                               path.startsWith("/api/search") ||
                               path.startsWith("/api/scenepacks") ||
                               path.startsWith("/api/hlx") ||
                               path.startsWith("/api/scrape");

      const origin = request.headers.get("Origin") || request.headers.get("Referer") || "";
      const host = url.hostname || request.headers.get("Host") || "";
      const secFetchSite = request.headers.get("Sec-Fetch-Site") || "";
      const isSiteInternal = host.includes("zyrexediting.xyz") ||
                             host.includes("localhost") ||
                             host.includes("127.0.0.1") ||
                             origin.includes("zyrexediting.xyz") || 
                             origin.includes("localhost") || 
                             origin.includes("127.0.0.1") ||
                             secFetchSite === "same-origin" ||
                             secFetchSite === "same-site" ||
                             secFetchSite === "none" ||
                             !!request.headers.get("Cookie");

      if (!isPublicEndpoint && !isSiteInternal) {
        if (!hasMasterKey && !hasAppKey) {
          return json({ success: false, error: "Access denied. Valid API key required for external API access." }, 403);
        }
      }
    }

    if (path === "/api/media" && request.method === "GET") {
      const target = sanitizeRemoteMediaUrl(url.searchParams.get("u"));
      if (!target) return new Response("Not found", { status: 404 });
      const host = remoteMediaHost(target);
      const headers = {
        "User-Agent": "Mozilla/5.0 (compatible; ZyrexMediaProxy/1.0)",
        Accept: "image/avif,image/webp,image/*,*/*;q=0.8",
        Referer: host && host.referer ? host.referer : "https://zyrexediting.xyz/",
      };
      // Discord answers a request from one of its CDN host names but not always from the
      // other, so both are tried before giving up on a sticker.
      const candidates = [target];
      if (host && host.alternate) {
        const alternate = new URL(target);
        alternate.hostname = host.alternate(alternate.hostname);
        if (alternate.hostname !== new URL(target).hostname) candidates.push(alternate.toString());
      }
      let lastStatus = 0;
      for (const candidate of candidates) {
        try {
          const upstream = await fetch(candidate, { headers, signal: AbortSignal.timeout(8000) });
          const type = String(upstream.headers.get("Content-Type") || "");
          if (upstream.ok && /^image\//i.test(type)) {
            return new Response(upstream.body, {
              headers: {
                "Content-Type": type,
                "Cache-Control": "public, max-age=604800, immutable",
                "Access-Control-Allow-Origin": "*",
                "X-Content-Type-Options": "nosniff",
              },
            });
          }
          lastStatus = upstream.status;
        } catch (_) {
          lastStatus = 0;
        }
      }
      return new Response(lastStatus === 0 ? "Media unavailable" : "Not found", { status: lastStatus === 0 ? 502 : 404 });
    }

    if (path.startsWith("/api/presence")) {
      return handlePresenceAPI(request, env);
    }

    if (path === "/api/scenepacks" || path.startsWith("/api/scenepacks/")) {
      return handleScenepacksAPI(request, env, url, path.replace(/\/+$/, ""), {
        isAdmin: isAdminRequest(request, env, hasMasterKey),
      });
    }

    if (path === "/api/discord/invite") {
      return handleDiscordInviteAPI(request, env, parseSession(null, request), hasMasterKey);
    }

    if (path === "/api/staff/apply" || path === "/api/staff/applications" || path === "/api/staff/settings") {
      const staffSession = parseSession(null, request);
      if (path === "/api/staff/settings") {
        return handleStaffSettingsAPI(request, env, staffSession);
      }
      if (path === "/api/staff/apply") {
        return handleStaffApplyAPI(request, env, path, staffSession);
      }
      return handleStaffApplicationsAPI(request, env, path, staffSession);
    }

    if (path === "/api/thumbnails/upload" && request.method === "POST") {
      const uploader = parseSession(null, request);
      if (!(await isTrustedBotRequest(request, env)) && !(await sessionCanUpload(uploader, env))) {
        return json({ success: false, error: "Unauthorized" }, 403);
      }
      try {
        const body = await request.json();
        const { filename, data: base64Data } = body;
        if (!filename || !base64Data) return json({ error: "filename and data required" }, 400);
        
        // Validate filename (prevent path traversal)
        const safeName = filename.replace(/[^a-zA-Z0-9_.\-]/g, "_");
        const binary = Uint8Array.from(atob(base64Data), c => c.charCodeAt(0));
        await env.STORAGE.put(`thumbnails/${safeName}`, binary);
        return json({ success: true, url: `https://thumbnail.zyrexediting.xyz/${safeName}` });
      } catch(e) {
        return json({ error: publicErrorMessage(e) }, 500);
      }
    }

    if (path === "/api/lookup/imdb" && request.method === "GET") {
      const q = (url.searchParams.get("q") || "").trim();
      if (!q) return json({ success: false, results: [] });
      try {
        // 1. Check if user typed or pasted an IMDb ID (e.g. tt0903747 or https://www.imdb.com/title/tt0903747/)
        const directIdMatch = q.match(/(tt\d{7,10})/i);
        let imdbUrl = "";
        if (directIdMatch) {
          const directId = directIdMatch[1].toLowerCase();
          imdbUrl = `https://v3.sg.media-imdb.com/suggestion/t/${directId}.json`;
        } else {
          // Normalize query: keep alphanumeric and convert spaces to underscores
          let clean = q.toLowerCase().replace(/[^a-z0-9\s]/g, " ").trim().replace(/\s+/g, "_");
          const firstChar = clean.length > 0 ? clean[0] : "x";
          imdbUrl = `https://v3.sg.media-imdb.com/suggestion/${firstChar}/${encodeURIComponent(clean)}.json`;
        }

        let resp = await fetch(imdbUrl, {
          headers: { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" }
        });

        // If no results and spaces were used, fallback to compact search
        let d = null;
        if (resp.ok) {
          d = await resp.json().catch(() => null);
        }

        if (!d || !d.d || d.d.length === 0) {
          const compact = q.toLowerCase().replace(/[^a-z0-9]/g, "");
          if (compact) {
            const fbUrl = `https://v3.sg.media-imdb.com/suggestion/x/${encodeURIComponent(compact)}.json`;
            const fbResp = await fetch(fbUrl, {
              headers: { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" }
            }).catch(() => null);
            if (fbResp && fbResp.ok) {
              d = await fbResp.json().catch(() => null);
            }
          }
        }

        const rawList = (d && d.d ? d.d : []).slice(0, 6);
        if (!rawList.length) return json({ success: true, results: [] });

        // 2. Parallel OMDb enrichment for top results to extract official IMDb ratings, genres, directors, and synopsis
        const enrichmentTasks = rawList.slice(0, 4).map(item => {
          if (!item.id || !item.id.startsWith("tt")) return Promise.resolve(null);
          return fetch(`http://www.omdbapi.com/?i=${encodeURIComponent(item.id)}&apikey=trilogy`, {
            headers: { "User-Agent": "Mozilla/5.0" }
          })
            .then(r => r.ok ? r.json() : null)
            .catch(() => null);
        });

        const omdbResults = await Promise.allSettled(enrichmentTasks);

        const items = rawList.map((item, idx) => {
          let img = item.i && item.i.imageUrl ? item.i.imageUrl : "";
          if (img && img.includes("._V1_")) {
            img = img.replace(/\._V1_.*?\.(jpg|jpeg|png|webp)/i, "._V1_FMjpg_UX1000_.jpg");
          }

          const qid = (item.qid || "").toLowerCase();
          let mType = "Movie";
          let mCat = "movie";
          if (qid.includes("series") || qid.includes("tv")) {
            mType = "Series";
            mCat = "series";
          } else if (qid.includes("game")) {
            mType = "Game";
            mCat = "games";
          }

          let rating = "";
          let votes = "";
          let genres = "";
          let directors = "";
          let cast = item.s || "";
          let plot = "";
          let runtime = "";
          let awards = "";
          let rated = "";
          let released = "";

          const omdb = (omdbResults[idx] && omdbResults[idx].status === "fulfilled") ? omdbResults[idx].value : null;
          if (omdb && omdb.Response === "True") {
            if (omdb.imdbRating && omdb.imdbRating !== "N/A") rating = omdb.imdbRating;
            if (omdb.imdbVotes && omdb.imdbVotes !== "N/A") votes = omdb.imdbVotes;
            if (omdb.Genre && omdb.Genre !== "N/A") genres = omdb.Genre;
            if (omdb.Director && omdb.Director !== "N/A") directors = omdb.Director;
            else if (omdb.Writer && omdb.Writer !== "N/A") directors = omdb.Writer;
            if (omdb.Actors && omdb.Actors !== "N/A") cast = omdb.Actors;
            if (omdb.Plot && omdb.Plot !== "N/A") plot = omdb.Plot;
            if (omdb.Runtime && omdb.Runtime !== "N/A") runtime = omdb.Runtime;
            if (omdb.Awards && omdb.Awards !== "N/A") awards = omdb.Awards;
            if (omdb.Rated && omdb.Rated !== "N/A") rated = omdb.Rated;
            if (omdb.Released && omdb.Released !== "N/A") released = omdb.Released;
          }

          return {
            id: item.id,
            imdb_id: item.id,
            title: item.l,
            year: item.y ? String(item.y) : (item.yr || ""),
            type: mType,
            category: mCat,
            rating: rating,
            votes: votes,
            genres: genres,
            directors: directors,
            cast: cast,
            stars: item.s || "",
            plot: plot,
            runtime: runtime,
            awards: awards,
            rated: rated,
            released: released,
            poster: img,
            banner: img
          };
        });

        return json({ success: true, results: items });
      } catch(e) {
        return json({ success: false, error: publicErrorMessage(e), results: [] });
      }
    }

    if (path === "/api/lookup/games" && request.method === "GET") {
      const q = (url.searchParams.get("q") || "").trim();
      if (!q) return json({ success: false, results: [] });
      try {
        const gameUrl = `https://api.rawg.io/api/games?search=${encodeURIComponent(q)}&page_size=10&key=c542e67aec3a4340908f9de9e86038af`;
        const resp = await fetch(gameUrl, {
          headers: { "User-Agent": "Mozilla/5.0" }
        });
        
        let items = [];
        if (resp.ok) {
          const d = await resp.json();
          items = (d.results || []).map(g => {
            let rating = "";
            if (g.rating && Number(g.rating) > 0) {
              rating = (Number(g.rating) * 2).toFixed(1);
              if (rating.endsWith(".0")) rating = rating.slice(0, -2);
            } else if (g.metacritic) {
              rating = (Number(g.metacritic) / 10).toFixed(1);
              if (rating.endsWith(".0")) rating = rating.slice(0, -2);
            }

            let banner = "";
            if (g.short_screenshots && g.short_screenshots.length > 1 && g.short_screenshots[1].image) {
              banner = g.short_screenshots[1].image;
            } else if (g.background_image) {
              banner = g.background_image;
            }

            const platformsList = (g.platforms || []).map(p => p.platform?.name).filter(Boolean).join(", ");
            const metacriticScore = g.metacritic ? String(g.metacritic) : "";
            const ratingsCount = g.ratings_count ? String(g.ratings_count) : "";

            return {
              id: g.slug || String(g.id),
              title: g.name,
              year: g.released ? g.released.split("-")[0] : "",
              released: g.released || "",
              type: "Game",
              category: "games",
              rating: rating,
              metacritic: metacriticScore,
              ratings_count: ratingsCount,
              genres: (g.genres || []).map(x => x.name).join(", "),
              platforms: platformsList,
              directors: "",
              poster: g.background_image || "",
              banner: banner
            };
          });
        }

        // Fallback: If RAWG returned 0 results or failed, query Steam Store Search
        if (!items || items.length === 0) {
          try {
            const steamUrl = `https://store.steampowered.com/api/storesearch/?term=${encodeURIComponent(q)}&l=english&cc=US`;
            const steamResp = await fetch(steamUrl, { headers: { "User-Agent": "Mozilla/5.0" } });
            if (steamResp.ok) {
              const steamJson = await steamResp.json();
              if (steamJson && steamJson.items) {
                items = steamJson.items.slice(0, 8).map(s => ({
                  id: `steam-${s.id}`,
                  title: s.name,
                  year: "",
                  released: "",
                  type: "Game",
                  category: "games",
                  rating: "",
                  metacritic: "",
                  ratings_count: "",
                  genres: "Video Game",
                  platforms: "PC (Steam)",
                  directors: "",
                  poster: `https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/${s.id}/header.jpg`,
                  banner: `https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/${s.id}/capsule_616x353.jpg`
                }));
              }
            }
          } catch(e) {}
        }

        return json({ success: true, results: items });
      } catch(e) {
        return json({ success: false, error: publicErrorMessage(e), results: [] });
      }
    }

    if ((path === "/api/scan-creator-links" || path === "/api/scan-creator-links/") && (request.method === "GET" || request.method === "POST")) {
      let scanUrl = url.searchParams.get("url") || "";
      if (request.method === "POST") {
        const body = await request.json().catch(() => ({}));
        scanUrl = body.url || scanUrl;
      }

      // A recent good scan is reused so the wizard's second pass cannot contradict the
      // first one just because a third-party profile fetch flapped.
      const scanInputKey = String(scanUrl || "").trim().toLowerCase();
      // The readable slug keeps two different inputs from sharing a hash bucket.
      const scanCacheKey = scanInputKey
        ? `cache/creator_scan_scrapin_v2/${shortHash(scanInputKey)}-${scanInputKey.replace(/^https?:\/\//, "").replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60)}.json`
        : "";
      if (scanCacheKey) {
        const cachedScan = await r2GetJSON(env, scanCacheKey, null);
        if (cachedScan && cachedScan.payload && Date.now() - Number(cachedScan.cached_at || 0) < CREATOR_SCAN_TTL_MS) {
          return json({ ...cachedScan.payload, cached: true });
        }
      }

      const workerRes = await scanCreatorLinksWithScrapin(scanUrl, env);

      if (scanCacheKey && workerRes && (workerRes.found || (workerRes.products && workerRes.products.length > 0))) {
        await r2PutJSON(env, scanCacheKey, { cached_at: Date.now(), payload: workerRes });
      }

      return json(workerRes);
    }

    if ((path === "/api/scrape" || path === "/api/scrape-payhip" || path === "/api/scrape/") && (request.method === "GET" || request.method === "POST")) {
      let payUrl = url.searchParams.get("url") || "";
      if (request.method === "POST") {
        const body = await request.json().catch(() => ({}));
        payUrl = body.url || payUrl;
      }
      const socialTarget = socialLinkPlatform(payUrl);
      if (socialTarget) {
        const creator = await scrapinSocialProfile(env, payUrl).catch(() => null);
        if (!creator) return json({ success: false, source: "scrapin", error: "Scrapin could not resolve this creator" }, 502);
        return json({ success: true, provider: creator.platform, platform: creator.platform, username: creator.handle,
          title: creator.name || creator.handle, name: creator.name || creator.handle, avatar: creator.avatar || "",
          bio: creator.bio || "", bioLinks: creator.links || [], found: false, source: "scrapin" });
      }
      const result = await scrapeProductWithScrapin(payUrl, env);
      return json(result, result.success ? 200 : 502);
    }

// Leak uploads are announced with the same rendered card the timeline uses, so the
// channel shows the upload exactly as the site does. Two link buttons follow: the leak
// page and the numbered feed post for the announcement.
const LEAK_ANNOUNCE_CHANNEL_ID = "1521792240320516197";
// Leak announcements ping this role so followers get a Discord notification.
const LEAK_ANNOUNCE_ROLE_ID = "1519246268252029072";
// Violet strip, matching the resource monitor card the channel uses.
const LEAK_ANNOUNCE_EMBED_COLOR = 0x6c5ce7;

function leakAnnounceRoleIds(env) {
  const raw = String((env && env.LEAK_ANNOUNCE_ROLE_ID) || LEAK_ANNOUNCE_ROLE_ID);
  return raw.split(/[\s,]+/).map(id => id.trim()).filter(id => /^\d{17,20}$/.test(id)).slice(0, 3);
}

function leakPublicUrl(product) {
  const id = String((product && product.id) || "").trim();
  return id ? `https://zyrexediting.xyz/leak?id=${encodeURIComponent(id)}` : "";
}

function leakAnnounceButtons(product, notice) {
  const buttons = [];
  const leakUrl = leakPublicUrl(product);
  if (leakUrl) buttons.push({ type: 2, style: 5, label: "View Leak", url: leakUrl });
  const postUrl = notice ? feedPostUrl(notice) : "";
  if (postUrl) buttons.push({ type: 2, style: 5, label: "View Post", url: postUrl });
  return buttons.length ? [{ type: 1, components: buttons }] : undefined;
}

// The Discord card mirrors the resource monitor layout: name, "Uploaded by", a 📦/📁/🏷
// metadata block, the leak's own description, the pack image and the two buttons.
const LEAK_ANNOUNCE_FOOTER = "© Zyrex™ Website 2026 · Resource Monitor";

// The pack ships as an installer next to its watermarks and its presets live in the
// backup prefix, so the count is taken from wherever the presets actually are.
async function leakPackStats(env, product) {
  const prefix = normalizeR2Prefix(product && product.file_path);
  const bucket = env.STORAGE_PROD || env.STORAGE;
  if (!prefix || !bucket) return { files: 0, size: "" };
  const countPrefix = async (candidate) => {
    let files = 0;
    let bytes = 0;
    let cursor;
    for (let page = 0; page < 4; page++) {
      const listing = await bucket.list({ prefix: candidate, limit: 1000, cursor });
      for (const object of listing.objects || []) {
        if (!isDownloadableR2Object(object, candidate)) continue;
        // The installer wrapper and the watermark files are not pack contents.
        if (/\.(exe|dmg)$/i.test(object.key)) continue;
        files += 1;
        bytes += Number(object.size) || 0;
      }
      if (!listing.truncated || !listing.cursor) break;
      cursor = listing.cursor;
    }
    return { files, bytes };
  };
  try {
    let stats = await countPrefix(`_source_ffx/${prefix}`);
    if (!stats.files) stats = await countPrefix(prefix);
    if (!stats.files) return { files: 0, size: "" };
    return { files: stats.files, size: formatSizeR2(stats.bytes) };
  } catch (_) {
    return { files: 0, size: "" };
  }
}

// Leak descriptions come from upload forms and shops, so they arrive with markup,
// zero-width padding and hard line breaks.
function leakAnnouncementDescription(product, limit = 700) {
  const raw = String((product && (product.description || product.desc || product.notes)) || "");
  if (!raw) return "";
  const text = raw
    .replace(/<\s*br\s*\/?\s*>/gi, "\n")
    .replace(/<\/\s*(p|div|li)\s*>/gi, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/g, "'")
    .replace(/[\u200b-\u200f\u2060\ufeff]/g, "")
    .replace(/[ \t]+/g, " ")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  if (!text) return "";
  return text.length > limit ? `${text.slice(0, limit - 1).trimEnd()}…` : text;
}

function buildLeakAnnouncementEmbed(product, notice, options) {
  const opts = options || {};
  const identity = opts.identity || {};
  const counts = opts.counts || { likes: 0, views: 0, replies: 0 };
  const stats = opts.stats || { files: 0, size: "" };
  const uploaderId = String(opts.uploaderId || "");
  const mentionable = /^\d{17,20}$/.test(uploaderId);
  const anonymous = product.is_anonymous === true;
  const thumbnail = absoluteMediaUrl(product.thumbnail || product.cdn_thumbnail || "");

  const uploadedBy = anonymous
    ? "**Uploaded by** Anonymous"
    : `**Uploaded by** ${mentionable ? `<@${uploaderId}>` : (identity.handle ? `@${identity.handle}` : String(identity.name || "Zyrex member"))}`;
  const description = leakAnnouncementDescription(product);
  // Discord rejects an embed whose description is empty, so the block is assembled and
  // trimmed as a whole.
  const body = [uploadedBy, description].filter(Boolean).join("\n\n").slice(0, 4000);

  const fields = [];
  if (notice && notice.seq) fields.push({ name: "🆔 Resource ID", value: `#${notice.seq}`, inline: true });
  if (stats.size) fields.push({ name: "📦 Size", value: stats.size, inline: true });
  if (stats.files) fields.push({ name: "📁 Files", value: String(stats.files), inline: true });
  const categoryLabels = Array.isArray(notice && notice.resource && notice.resource.category_labels) && notice.resource.category_labels.length
    ? notice.resource.category_labels
    : productCategoryLabels(product);
  // "Preset" and "Others" say nothing when the platform is already listed, so the card
  // shows the specific category the reference layout uses.
  const generic = new Set(["Preset", "Others", "Project File"]);
  const specific = categoryLabels.filter(label => !generic.has(label));
  const shownCategories = specific.length ? specific : categoryLabels;
  if (shownCategories.length) fields.push({ name: "🏷️ Category", value: shownCategories.join(" · ").slice(0, 1024), inline: false });
  fields.push({ name: "👤 Uploader", value: anonymous ? "Anonymous" : String(identity.name || "Zyrex member").slice(0, 200), inline: false });
  const productLink = String(product.product_url || product.source_url || "").trim();
  const leakUrl = leakPublicUrl(product);
  if (/^https?:\/\//i.test(productLink)) fields.push({ name: "🔗 Product", value: `[Product Link](${productLink})`, inline: false });
  else if (leakUrl) fields.push({ name: "🔗 Product", value: `[Open on Zyrex](${leakUrl})`, inline: false });
  // The counters keep being patched in place when members like, view or reply.
  fields.push(
    { name: "❤️ Likes", value: String(counts.likes || 0), inline: true },
    { name: "👁️ Views", value: String(counts.views || 0), inline: true },
    { name: "💬 Replies", value: String(counts.replies || 0), inline: true },
  );

  return {
    title: String(product.name || "New leak").slice(0, 256),
    description: body,
    color: LEAK_ANNOUNCE_EMBED_COLOR,
    ...(leakUrl ? { url: leakUrl } : {}),
    ...(thumbnail ? { thumbnail: { url: thumbnail }, image: { url: thumbnail } } : {}),
    fields,
    footer: { text: LEAK_ANNOUNCE_FOOTER },
    timestamp: String(notice && notice.created_at ? notice.created_at : new Date().toISOString()),
  };
}

// The announcement is a normal feed item: the official profile posts it, so it carries
// the same author, wording, thumbnail and numbered short link as the timeline entry.
async function buildLeakAnnouncementNotice(env, product) {
  const official = await resolveZyrexProfile(env).catch(() => null);
  const officialId = official ? String(official.id || "") : "";
  const owner = String(product.credited_uploader_id || product.uploader_id || product.author_id || "").trim();
  const handles = invertHandleIndex(await readHandleIndex(env).catch(() => ({})));
  const handle = handles[owner] || "";
  const displayName = String(
    product.credited_uploader_name || product.uploader_name || product.author_name || ""
  ).trim() || "Zyrex member";
  const postId = noticePostId(product.id);
  const thumbnail = String(product.thumbnail || product.cdn_thumbnail || "");
  const identity = {
    id: officialId,
    name: official ? official.name : "Zyrex",
    handle: ZYREX_HANDLE,
    avatar: official ? official.avatar : "/assets/content.png",
    url: `/@${ZYREX_HANDLE}`,
    is_admin: true,
    is_official: true,
  };
  const notice = {
    kind: "resource_notice",
    id: postId,
    post_id: postId,
    product_id: String(product.id || ""),
    author_id: officialId,
    author: identity,
    announcement: { ...identity },
    resource: profilePublicResource(product),
    uploader: {
      id: owner,
      name: displayName,
      handle,
      avatar: String(product.credited_uploader_avatar || product.uploader_avatar || ""),
      url: handle ? `/@${handle}` : `/profile?id=${encodeURIComponent(owner)}`,
    },
    text: `${handle ? "@" + handle : displayName} uploaded a new leak!`,
    media: thumbnail ? [thumbnail] : [],
    created_at: product.created_at || new Date().toISOString(),
  };
  // The short link needs a number; assigning it here also registers the post id.
  await assignNoticeSequences(env, [notice]).catch(() => [notice]);
  return notice;
}

// The Discord profile behind the member who uploaded the leak, so the card header shows
// them instead of the official feed author.
async function discordUploaderIdentity(env, userId, fallback) {
  const identity = {
    id: String(userId || ""),
    name: String((fallback && fallback.name) || "Zyrex member"),
    handle: String((fallback && fallback.handle) || ""),
    avatar: String((fallback && fallback.avatar) || ""),
    url: String((fallback && fallback.url) || ""),
  };
  // Default avatars live on this Worker's own host, which it cannot fetch, so lean on
  // the Discord CDN lookup below (or the card's initials fallback).
  if (/^\/api\/avatar\/default\//i.test(identity.avatar)) identity.avatar = "";
  if (!/^\d{17,20}$/.test(identity.id)) return identity;
  const token = getSiteLogBotToken(env);
  if (!token) return identity;
  try {
    const response = await fetch(`${DISCORD_API}/users/${identity.id}`, {
      headers: { Authorization: `Bot ${token}` },
      signal: AbortSignal.timeout(5000),
    });
    if (!response.ok) return identity;
    const user = await response.json().catch(() => null);
    if (!user || !user.id) return identity;
    const name = String(user.global_name || user.username || "").trim();
    if (name) identity.name = name;
    if (user.avatar) {
      const ext = String(user.avatar).startsWith("a_") ? "gif" : "png";
      identity.avatar = `https://cdn.discordapp.com/avatars/${user.id}/${user.avatar}.${ext}?size=160`;
    }
    return identity;
  } catch (_) {
    return identity;
  }
}

// Uploads are announced as an embed shaped like the resource monitor card: the leak name
// on top, "Uploaded by", a size/files/category block, the leak's own description, the
// pack image and the View Leak / View Post buttons. Outside the embed the message only
// carries the role ping. Returns true when the channel got a message.
async function postLeakAnnouncement(env, product) {
  const token = getSiteLogBotToken(env);
  if (!token || !product || !String(product.id || "")) return false;
  const notice = await buildLeakAnnouncementNotice(env, product);
  const channelId = String(env.LEAK_ANNOUNCE_CHANNEL_ID || LEAK_ANNOUNCE_CHANNEL_ID);
  const counts = await readFeedPostCounts(env, notice).catch(() => ({ likes: 0, views: 0, replies: 0 }));
  const stats = await leakPackStats(env, product);
  const components = leakAnnounceButtons(product, notice);
  const roleIds = leakAnnounceRoleIds(env);
  const uploader = notice.uploader || {};
  const uploaderId = String(uploader.id || "").trim();
  const isDiscordId = /^\d{17,20}$/.test(uploaderId);
  const identity = await discordUploaderIdentity(env, uploaderId, uploader);

  const embed = buildLeakAnnouncementEmbed(product, notice, { identity, counts, stats, uploaderId });

  const payload = {
    embeds: [embed],
    // Only the role and the uploader may be mentioned, and only the role is written out.
    allowed_mentions: { parse: [], roles: roleIds, users: isDiscordId ? [uploaderId] : [] },
    components,
  };
  const roleMentions = roleIds.map(id => `<@&${id}>`).join(" ");
  if (roleMentions) payload.content = roleMentions;
  try {
    const response = await fetch(`${DISCORD_API}/channels/${channelId}/messages`, {
      method: "POST",
      headers: { Authorization: `Bot ${token}`, "Content-Type": "application/json" },
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(8000),
    });
    if (!response.ok) {
      console.warn("Leak announcement failed:", response.status, String(await response.text().catch(() => "")).slice(0, 200));
      return false;
    }
    const message = await response.json().catch(() => null);
    const messageId = String((message && message.id) || "");
    if (messageId) {
      // The embed is stored so like/view/reply changes can patch its counters.
      await r2PutJSON(env, feedMessageKey(notice.id), {
        version: 1,
        post_id: notice.id,
        product_id: notice.product_id,
        author_id: notice.author_id,
        channel_id: channelId,
        message_id: messageId,
        embed,
        counts,
        edited_at: Date.now(),
      }).catch(() => false);
    }
    return Boolean(messageId);
  } catch (error) {
    console.error("Leak announcement failed:", error?.message || String(error));
    return false;
  }
}

// Announce a new product to the Discord announcement channel (mirrors bot.py announce_product())
async function announceProductToDiscord(env, product) {
  try {
    const announceType = String(product.type || "preset").toLowerCase();
    // Skip plugins silently
    if (announceType === "plugin" || announceType === "adobe-plugin" || announceType === "ofx-plugin") return;
    // Leaks get their own upload embed; the generic announcement below covers the rest.
    if (!announceType || announceType === "preset" || announceType === "resource") {
      const sentCard = await postLeakAnnouncement(env, product).catch(error => {
        console.error("Leak card announcement failed:", error?.message || String(error));
        return false;
      });
      if (sentCard) return;
    }

    const botToken = env.DISCORD_BOT_TOKEN || env.SITE_LOG_BOT_TOKEN || "";
    if (!botToken) {
      // Fall back to the VPS bot, which maintains its own Discord credentials.
      await fetch(`${BOT_API}/api/products/announce`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(product),
        signal: AbortSignal.timeout(8000),
      }).catch(() => {});
      return;
    }
    const ptype = String(product.type || "preset").toLowerCase();

    const ANNOUNCE_CHANNEL = "1521792240320516197";
    const productName = String(product.name || "Untitled").slice(0, 200);
    const productDesc = String(product.description || "").slice(0, 350) || "*No description provided*";

    let productUrl, typeLabel, color, catDisplay, downloadLabel, sizeStr;

    if (ptype === "audio") {
      productUrl = `https://zyrexediting.xyz/product-audio?id=${product.id}`;
      color = 0x7c3aed;  // Purple
      typeLabel = "Audio";
      catDisplay = (product.category || "others").replace(",",", ").replace(/-/g," ");
      sizeStr = product.size_str || "Audio File";
      downloadLabel = "Listen / Download";
    } else if (ptype === "scenepack") {
      productUrl = `https://zyrexediting.xyz/product-scenepack?id=${product.id}`;
      color = 0xfbbf24;  // Amber
      typeLabel = "Scenepack";
      catDisplay = "Scenepack";
      sizeStr = product.size_str || "External";
      downloadLabel = "Download";
    } else {
      productUrl = `https://zyrexediting.xyz/leak?id=${product.id}`;
      const catMap = {
        "after-effects": { label: "After Effects", color: 0x9b59b6 },
        "premiere-pro": { label: "Premiere Pro", color: 0x3498db },
        "photoshop": { label: "Photoshop", color: 0x00bcd4 },
        "video-star": { label: "Video Star", color: 0xffd700 },
        "topaz-labs": { label: "Topaz Labs", color: 0x00e676 },
        "software": { label: "Software", color: 0xe67e22 },
        "adobe-plugin": { label: "Adobe Plugin", color: 0xe91e63 },
        "ofx-plugin": { label: "OFX Plugin", color: 0x7c4dff },
      };
      const rcat = product.resource_category || product.category || "preset";
      typeLabel = rcat === "project-file" ? "Project File" : "Leak";
      const catInfo = catMap[rcat] || {};
      catDisplay = catInfo.label || String(rcat).replace(/-/g," ").replace(/\b\w/g, c => c.toUpperCase());
      color = catInfo.color || 0xa80f2d;  // Cherry red default
      sizeStr = product.size_str || "";
      downloadLabel = "Download";
    }

    // Uploader name & avatar
    let uploaderName = "Zyrex Community";
    let uploaderAvatarUrl = null;
    const uploaderId = String(product.uploader_id || product.author_id || "").trim();
    const uploaderAvatar = String(product.uploader_avatar || product.creator_avatar || "").trim();
    const uploaderNameField = String(product.uploader_name || product.creator_nickname || product.author_name || "").trim();

    if (uploaderNameField) uploaderName = uploaderNameField;
    if (uploaderAvatar.startsWith("http")) {
      uploaderAvatarUrl = uploaderAvatar;
    } else if (uploaderAvatar && uploaderId) {
      const ext = uploaderAvatar.startsWith("a_") ? "gif" : "png";
      uploaderAvatarUrl = `https://cdn.discordapp.com/avatars/${uploaderId}/${uploaderAvatar}.${ext}?size=64`;
    }

    // Try to fetch live Discord display name
    if (uploaderId && /^\d{17,20}$/.test(uploaderId)) {
      try {
        const memberResp = await fetch(`https://discord.com/api/v10/users/${uploaderId}`, {
          headers: { Authorization: `Bot ${botToken}` },
          signal: AbortSignal.timeout(3000)
        });
        if (memberResp.ok) {
          const m = await memberResp.json();
          if (m && m.id) {
            uploaderName = m.global_name || m.username || uploaderName;
            if (m.avatar) {
              const ext = m.avatar.startsWith("a_") ? "gif" : "png";
              uploaderAvatarUrl = `https://cdn.discordapp.com/avatars/${m.id}/${m.avatar}.${ext}?size=64`;
            }
          }
        }
      } catch(e) {}
    }

    // Build embed fields
    const fields = [{ name: "Type", value: typeLabel, inline: true }];
    if (catDisplay) fields.push({ name: "Category", value: catDisplay, inline: true });
    if (sizeStr && ptype === "preset") fields.push({ name: "Size", value: sizeStr, inline: true });
    fields.push({ name: "Access", value: `[${downloadLabel}](${productUrl})`, inline: false });

    const embed = {
      title: productName,
      description: productDesc,
      url: productUrl,
      color,
      fields,
      footer: {
        text: "Zyrex™ Leaks",
        icon_url: "https://zyrexediting.xyz/assets/content.png"
      },
      timestamp: new Date().toISOString()
    };

    if (uploaderAvatarUrl) {
      embed.author = { name: uploaderName, url: productUrl, icon_url: uploaderAvatarUrl };
    } else {
      embed.author = { name: uploaderName, url: productUrl };
    }

    const thumb = String(product.cdn_thumbnail || product.thumbnail || "");
    if (thumb) embed.thumbnail = { url: thumb };

    // A leak keeps both links even when only the embed fallback reaches Discord.
    let fallbackComponents;
    if (!ptype || ptype === "preset" || ptype === "resource") {
      const fallbackNotice = await buildLeakAnnouncementNotice(env, product).catch(() => null);
      fallbackComponents = leakAnnounceButtons(product, fallbackNotice);
    }

    try {
      const announceResp = await fetch(`https://discord.com/api/v10/channels/${ANNOUNCE_CHANNEL}/messages`, {
        method: "POST",
        headers: { Authorization: `Bot ${botToken}`, "Content-Type": "application/json" },
        body: JSON.stringify(fallbackComponents ? { embeds: [embed], components: fallbackComponents } : { embeds: [embed] }),
        signal: AbortSignal.timeout(8000)
      });
      if (!announceResp.ok) throw new Error(`Discord announce returned ${announceResp.status}`);
    } catch (error) {
      console.error("Discord product announcement failed:", error?.message || String(error));
      // Fall back to the VPS bot, which maintains its own Discord connection.
      await fetch(`${BOT_API}/api/products/announce`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(product),
        signal: AbortSignal.timeout(8000),
      }).catch(() => {});
    }
  } catch(e) {
    console.error("announceProductToDiscord failed:", e.message);
  }
}

    if ((path === "/api/hlx/resolve" || path === "/api/hlx/resolve/") && request.method === "GET") {
      const targetSocialUrl = url.searchParams.get("url") || "";
      let scrapinCreator;
      try {
        scrapinCreator = await scrapinSocialProfile(env, targetSocialUrl, { throwOnError: true });
      } catch (error) {
        const upstreamStatus = Number(error?.scrapinStatus) || 0;
        const status = upstreamStatus === 404 ? 404
          : upstreamStatus === 422 ? 400
            : upstreamStatus === 429 ? 503
              : error?.name === "TimeoutError" ? 504
                : upstreamStatus >= 500 || upstreamStatus === 401 || upstreamStatus === 403 || !upstreamStatus ? 502
                  : 502;
        const reason = upstreamStatus === 404 ? "profile_not_found"
          : upstreamStatus === 422 ? "invalid_profile"
            : upstreamStatus === 429 ? "upstream_rate_limited"
              : error?.name === "TimeoutError" ? "upstream_timeout"
                : upstreamStatus === 401 || upstreamStatus === 403 ? "upstream_auth"
                  : "upstream_error";
        const message = reason === "profile_not_found" ? "This creator profile was not found by Scrapin."
          : reason === "invalid_profile" ? "Scrapin could not process this profile URL."
            : reason === "upstream_rate_limited" ? "Scrapin is rate limiting profile lookups. Try again shortly."
              : reason === "upstream_timeout" ? "Scrapin took too long to resolve this creator. Try again."
                : "Scrapin could not resolve this creator right now.";
        console.warn("scrapin_creator_lookup_failed", reason, upstreamStatus || "network");
        return json({ success: false, source: "scrapin", reason, error: message, upstream_status: upstreamStatus || undefined }, status, { "Cache-Control": "no-store" });
      }
      if (!scrapinCreator) return json({ success: false, source: "scrapin", reason: "unsupported_profile_url", error: "This social profile URL is not supported." }, 400, { "Cache-Control": "no-store" });
      return json({
        success: true,
        source: "scrapin",
        platform: scrapinCreator.platform || "",
        nickname: scrapinCreator.name || scrapinCreator.handle || "",
        username: scrapinCreator.handle || "",
    account_id: scrapinCreator.account_id || "",
        avatar: scrapinCreator.avatar || "",
        cdn_avatar: scrapinCreator.avatar || "",
        bioLink: (scrapinCreator.links || [])[0] || null,
        bio: scrapinCreator.bio || "",
        links: scrapinCreator.links || [],
      });

    }

    if (path === "/api/audio/upload" && request.method === "POST") {
      const uploader = parseSession(null, request);
      if (!(await sessionCanUpload(uploader, env))) {
        return json({ success: false, error: "Unauthorized" }, 403);
      }
      try {
        const body = await request.json();
        const { filename, data: base64Data } = body;
        if (!filename || !base64Data) return json({ error: "filename and data required" }, 400);
        const safeName = filename.replace(/[^a-zA-Z0-9_.\-]/g, "_");
        const binary = Uint8Array.from(atob(base64Data), c => c.charCodeAt(0));
        await env.STORAGE.put(`audio/${safeName}`, binary);
        return json({ success: true, url: `https://zyrexediting.xyz/api/audio/stream/${safeName}` });
      } catch(e) { return json({ error: publicErrorMessage(e) }, 500); }
    }
    // Audio streaming
    if (path.startsWith("/api/audio/stream/") && request.method === "GET") {
      try {
        const fname = decodeURIComponent(path.replace("/api/audio/stream/", "").split("?")[0]);
        const obj = await env.STORAGE.get(`audio/${fname}`);
        if (obj) {
          const ext = fname.split('.').pop().toLowerCase();
          const mime = { mp3: 'audio/mpeg', wav: 'audio/wav', flac: 'audio/flac', ogg: 'audio/ogg', m4a: 'audio/mp4', aac: 'audio/aac' };
          const headers = {
            "Content-Type": mime[ext] || 'audio/mpeg',
            "Accept-Ranges": "bytes",
            "Access-Control-Allow-Origin": "*"
          };
          if (url.searchParams.has("download")) {
            headers["Content-Disposition"] = `attachment; filename="${fname}"`;
          }
          return new Response(obj.body, { headers });
        }
        return new Response(null, { status: 404 });
      } catch(e) { return new Response(null, { status: 500 }); }
    }
    // Audio rename: copy R2 object to new key, delete old
    if (path === "/api/audio/rename" && request.method === "POST") {
      const uploader = parseSession(null, request);
      if (!(await sessionCanUpload(uploader, env))) {
        return json({ success: false, error: "Unauthorized" }, 403);
      }
      try {
        const { old_key, new_key } = await request.json();
        if (!old_key || !new_key) return json({ error: "old_key and new_key required" }, 400);
        // Sanitize new key to match upload behavior (spaces → underscores)
        const safeNewKey = new_key.replace(/[^a-zA-Z0-9_.\/\-]/g, "_");
        const obj = await env.STORAGE.get(old_key);
        if (!obj) return json({ error: "Source file not found" }, 404);
        await env.STORAGE.put(safeNewKey, obj.body, { httpMetadata: obj.httpMetadata });
        await env.STORAGE.delete(old_key);
        return json({ success: true, message: "Renamed", safe_key: safeNewKey });
      } catch(e) { return json({ error: publicErrorMessage(e) }, 500); }
    }

    if (path === "/api/data/creators.json") {
      if (request.method === "GET") {
        try {
          const obj = await env.STORAGE.get("creators/index.json");
          if (obj) {
            return new Response(obj.body, {
              headers: { "Content-Type": "application/json", "Cache-Control": "public, max-age=300", "Access-Control-Allow-Origin": "*" }
            });
          }
          return json({ index: {}, count: 0 });
        } catch(e) { return json({ index: {}, count: 0 }); }
      }
      if (request.method === "POST") {
        try {
          const body = await request.json();
          const jsonStr = JSON.stringify(body);
          const binary = new TextEncoder().encode(jsonStr);
          await env.STORAGE.put("creators/index.json", binary);
          return json({ success: true, message: "Creator index updated" });
        } catch(e) {
          return json({ error: publicErrorMessage(e) }, 500);
        }
      }
    }

    if (path.startsWith("/api/avatar/")) {
      const AVATAR_SIZES = new Set(["16", "32", "64", "128", "256", "512", "1024", "2048", "4096"]);
      const avatarCdn = (userId, hash, size) => {
        const ext = hash.startsWith("a_") ? "gif" : "png";
        return `https://cdn.discordapp.com/avatars/${userId}/${hash}.${ext}?size=${size}`;
      };
      const fetchImage = (target) => fetch(target, {
        headers: { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36" },
        signal: AbortSignal.timeout(4000),
      });
      const imageResponse = (res, ttl) => new Response(res.body, {
        status: 200,
        headers: {
          "Content-Type": res.headers.get("Content-Type") || "image/png",
          "Cache-Control": `public, max-age=${ttl}`,
          "Access-Control-Allow-Origin": "*",
        },
      });
      const defaultAvatarFor = async (userId) => {
        let index = 0;
        try { index = Number((BigInt(userId) >> 22n) % 6n); } catch (_) { index = 0; }
        const res = await fetchImage(`https://cdn.discordapp.com/embed/avatars/${index}.png`);
        return res.ok ? imageResponse(res, 3600) : null;
      };
      try {
        const requestedSize = String(url.searchParams.get("size") || "256");
        const size = AVATAR_SIZES.has(requestedSize) ? requestedSize : "256";
        if (path.includes("/default/")) {
          const idx = path.split("/default/")[1]?.replace(/\.(?:png|webp|gif)$/i, "") || "0";
          const embedResp = await fetchImage(`https://cdn.discordapp.com/embed/avatars/${encodeURIComponent(idx)}.png`);
          if (embedResp.ok) return imageResponse(embedResp, 86400);
        } else {
          const parts = path.replace("/api/avatar/", "").split("/");
          const userId = String(parts[0] || "").replace(/\D/g, "");
          let requestedHash = parts.slice(1).join("/").replace(/\?.*/, "") || "";
          if (requestedHash.includes("http") || requestedHash.includes("discordapp")) {
            const match = path.match(/([a-f0-9]{32})/);
            if (match) requestedHash = match[1];
          }
          requestedHash = requestedHash.replace(/\.(png|jpg|jpeg|webp|gif)$/i, "");
          if (/^\d{15,25}$/.test(userId)) {
            // Discord keeps every old avatar URL alive, so the hash a post stored
            // months ago would pin that member's previous photo forever. The profile
            // cache is re-read (and re-queried when stale) and its avatar always wins.
            let entry = await readDiscordUserEntry(env, userId).catch(() => null);
            if (!entry || Date.now() - Number(entry.fetched_at || 0) > DISCORD_USER_REFRESH_MS) {
              const resolved = await ensureDiscordUserProfile(env, userId).catch(() => null);
              if (resolved && resolved.user) entry = { user: resolved.user, fetched_at: Date.now() };
            }
            const currentHash = String(entry?.user?.avatar || "").trim();
            if (!currentHash && entry && entry.user) {
              // The member removed their photo, so the stored hash is gone.
              const placeholder = await defaultAvatarFor(userId);
              if (placeholder) return placeholder;
            }
            const candidates = [currentHash, requestedHash].filter(
              (candidate, position, list) => /^(?:a_)?[a-z0-9_-]{16,}$/i.test(candidate) && list.indexOf(candidate) === position
            );
            for (const candidate of candidates) {
              const image = await fetchImage(avatarCdn(userId, candidate, size));
              // An hour: long enough to be cheap, short enough that a new photo
              // replaces the old one on pages that still hold the previous hash.
              if (image.ok) return imageResponse(image, 3600);
            }
          }
        }
      } catch(e) { console.error("Avatar proxy error:", e.message); }
      // Never leave a broken image behind: the site's own placeholder always exists.
      return new Response(null, {
        status: 302,
        headers: {
          Location: "https://zyrexediting.xyz/assets/default-avatar.png",
          "Cache-Control": "public, max-age=300",
        },
      });
    }
    if (path.startsWith("/api/banner/")) {
      const cacheTTL = 86400;
      try {
        const parts = path.replace("/api/banner/", "").split("/");
        const userId = parts[0];
        const hash = parts[1]?.replace(/\?.*/, "") || "";
        const size = url.searchParams.get("size") || "480";
        const cdnUrl = `https://cdn.discordapp.com/banners/${userId}/${hash}?size=${size}`;
        const imgResp = await fetch(cdnUrl);
        if (imgResp.ok) {
          return new Response(imgResp.body, {
            status: 200,
            headers: {
              "Content-Type": imgResp.headers.get("Content-Type") || "image/png",
              "Cache-Control": `public, max-age=${cacheTTL}`,
              "Access-Control-Allow-Origin": "*",
            },
          });
        }
      } catch(e) { console.error("Banner proxy error:", e.message); }
      return new Response(null, { status: 404, headers: corsHeaders });
    }

    try {
      // The VPS bot publishes role membership here on a timer (and on gateway
      // role events), so the site never has to ask Discord per request.
      if (path === "/api/internal/role-snapshot" && request.method === "POST") {
        const auth = request.headers.get("Authorization") || "";
        const allowedRelayTokens = [env.DISCORD_BOT_TOKEN, env.SITE_LOG_BOT_TOKEN].filter(Boolean);
        if (!allowedRelayTokens.some(token => auth === `Bot ${token}`)) {
          return json({ success: false, error: "Unauthorized" }, 401);
        }
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON" }, 400); }
        if (!body || typeof body !== "object") return json({ success: false, error: "Invalid payload" }, 400);
        const roleId = String(body.role_id || VERIFIED_ROLE_ID).trim();
        if (!isValidRoleId(roleId)) return json({ success: false, error: "Invalid role_id" }, 400);
        const hasFull = Array.isArray(body.user_ids);
        const add = cleanRoleIdList(body.add);
        const remove = cleanRoleIdList(body.remove);
        if (!hasFull && !add.length && !remove.length) {
          return json({ success: false, error: "Provide user_ids, add or remove" }, 400);
        }
        try {
          const result = await updateRoleSnapshot(env, roleId, {
            userIds: hasFull ? body.user_ids : null,
            add,
            remove,
            force: body.force === true,
            source: body.source || "vps-bot",
          });
          if (result.refused === "shrink") {
            console.warn(
              `Refused role snapshot shrink for ${roleId}: ${result.existing} -> ${result.incoming}`
            );
            return json({
              success: false,
              code: "SNAPSHOT_SHRINK_GUARD",
              error: `Refusing to replace ${result.existing} ids with ${result.incoming}; send force:true to accept`,
            }, 409);
          }
          if (result.refused === "missing") {
            return json({
              success: false,
              code: "SNAPSHOT_MISSING",
              error: "Publish a full user_ids list before patching this role",
            }, 409);
          }
          return json({ success: true, role_id: roleId, mode: hasFull ? "replace" : "patch", ...result });
        } catch (error) {
          console.error("Role snapshot update failed:", error?.message || String(error));
          return json({ success: false, error: "Could not store role snapshot" }, 503);
        }
      }

      // The VPS bot reports withdrawn roles, bans and departures here. Whatever the
      // reason, the member is written to the revocation list, their stored pass and
      // cached verdicts are dropped, and every gate refuses them from then on.
      // The bot asks "have we seen this member before?" on every join, and the same
      // call records the sighting. A member whose departure was missed while the bot
      // was down is still recognised as a return, not as a fresh signup.
      if (path === "/api/internal/member-history" && (request.method === "POST" || request.method === "GET")) {
        const auth = request.headers.get("Authorization") || "";
        const allowedRelayTokens = [env.DISCORD_BOT_TOKEN, env.SITE_LOG_BOT_TOKEN].filter(Boolean);
        if (!allowedRelayTokens.some(token => auth === `Bot ${token}`)) {
          return json({ success: false, error: "Unauthorized" }, 401);
        }
        let payload = {};
        if (request.method === "POST") {
          try { payload = (await request.json()) || {}; } catch (_) { return json({ success: false, error: "Invalid JSON" }, 400); }
        }
        const memberId = String(payload.user_id || url.searchParams.get("user_id") || "").trim();
        const mark = request.method === "POST" || String(url.searchParams.get("mark") || "") === "1";
        if (!/^\d{15,25}$/.test(memberId)) return json({ success: false, error: "A valid user_id is required" }, 400);
        try {
          const history = await readMemberHistory(env);
          const previous = history[memberId] || null;
          const knownBefore = Boolean(previous && Number(previous.first_seen) > 0);
          // The caller records the sighting *after* asking, so reporting `known_before`
          // is what makes a returning member distinguishable from a new one.
          if (mark) {
            await recordMemberHistory(env, [memberId], {
              source: String(payload.source || "bot-join").slice(0, 40),
            });
          }
          return json({
            success: true,
            discord_id: memberId,
            known_before: knownBefore,
            first_seen: previous ? Number(previous.first_seen) || 0 : 0,
            last_seen: previous ? Number(previous.last_seen) || 0 : 0,
            verified_before: Boolean(previous && previous.verified === true),
            downloads: previous ? Number(previous.downloads) || 0 : 0,
            recorded: mark,
          });
        } catch (error) {
          console.error("Member history failed:", error?.message || String(error));
          return json({ success: false, error: "Could not read member history" }, 503);
        }
      }

      if (path === "/api/internal/role-revocations" && (request.method === "POST" || request.method === "GET")) {
        const auth = request.headers.get("Authorization") || "";
        const allowedRelayTokens = [env.DISCORD_BOT_TOKEN, env.SITE_LOG_BOT_TOKEN].filter(Boolean);
        if (!allowedRelayTokens.some(token => auth === `Bot ${token}`)) {
          return json({ success: false, error: "Unauthorized" }, 401);
        }
        // Read-only probe so staff can ask "why is this member blocked?" from Discord
        // without changing anything.
        if (request.method === "GET") {
          const probeId = String(url.searchParams.get("user_id") || "").trim();
          try {
            const users = await readRevocationUsers(env);
            return json({
              success: true,
              total: Object.keys(users).length,
              record: /^\d{15,25}$/.test(probeId) ? revocationSummary(users[probeId]) : null,
            });
          } catch (error) {
            console.error("Role revocation probe failed:", error?.message || String(error));
            return json({ success: false, error: "Could not read revocations" }, 503);
          }
        }
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON" }, 400); }
        if (!body || typeof body !== "object") return json({ success: false, error: "Invalid payload" }, 400);

        const revokeIds = cleanRoleIdList(body.revoke);
        const restoreIds = cleanRoleIdList(body.restore);
        if (!revokeIds.length && !restoreIds.length) {
          return json({ success: false, error: "Provide revoke or restore" }, 400);
        }
        const roleId = isValidRoleId(body.role_id) ? String(body.role_id) : VERIFIED_ROLE_ID;
        const reason = String(body.reason || "manual").slice(0, 32);
        const source = String(body.source || "vps-bot").slice(0, 40);

        try {
          const out = { success: true, role_id: roleId, reason, reason_label: REVOKE_REASON_LABELS[reason] || reason };

          if (restoreIds.length) {
            const restored = await restoreUserAccess(env, restoreIds, { force: body.force === true });
            out.restored = restored.restored.length;
            out.still_revoked = restored.kept.length;
            // Role evidence plus a restore means they are verified again, so put
            // them back into the snapshot that the gates read.
            if (roleId === VERIFIED_ROLE_ID && restored.restored.length) {
              out.returned_to_snapshot = await addUsersToRoleSnapshot(env, roleId, restored.restored);
            }
            for (const id of restored.restored) {
              queueSecurityEvent(env, ctx, "access", {
                level: "success",
                title: "Download access restored",
                description: "The bot lifted a revocation after role evidence came back.",
                action: "access-restored",
                user_id: id,
                access: "Restored by bot",
                reason: `via ${source}`,
              });
            }
          }

          if (revokeIds.length) {
            const staffAction = STAFF_REVOKE_SOURCE_PATTERN.test(source);
            // `undefined` lets revokeUserAccess derive stickiness from the reason and
            // source (a departure or a ban is always sticky); only an explicit
            // boolean overrides that decision.
            const stickyFlag = staffAction
              ? true
              : (body.sticky === true ? true : (body.sticky === false ? false : undefined));
            const revoked = await revokeUserAccess(env, revokeIds, {
              reason,
              roleId,
              source,
              // A human explicit revoke must overwrite whatever is recorded, so the
              // reason, source and timestamp reflect the decision that was just made.
              override: staffAction || body.override === true,
              sticky: stickyFlag,
            });
            out.revoked = revoked.revoked.length;
            out.already_revoked = revoked.kept.length;
            const users = await readRevocationUsers(env);
            out.records = revokeIds.map(id => ({ discord_id: id, ...(revocationSummary(users[id]) || {}) }));
            // Drop them from the snapshot too, so the fast path cannot admit them
            // even before the next full publish. This runs for kept ids as well: an
            // older record may have been written while the member was still listed.
            if (roleId === VERIFIED_ROLE_ID) {
              out.removed_from_snapshot = await removeUsersFromRoleSnapshot(env, roleId, revokeIds);
            }
            const notifyIds = Array.from(new Set([...revoked.revoked, ...(staffAction ? revoked.kept : [])]));
            if (body.notify !== false && notifyIds.length) {
              const notice = REVOCATION_NOTICES[reason] || {};
              out.notified = await postRevocationLogToDiscord(env, {
                ids: notifyIds,
                reason,
                role_id: roleId,
                count: notifyIds.length,
                sticky: notifyIds.some(id => isStickyRevocation(users[id])),
                title: body.title || notice.title,
                description: body.description || notice.description,
                color: notice.color,
                mentionText: body.mention_text,
              });
            }
          }
          return json(out);
        } catch (error) {
          console.error("Role revocation failed:", error?.message || String(error));
          return json({ success: false, error: "Could not store the revocation" }, 503);
        }
      }

      if (path === "/api/internal/site-log" && request.method === "POST") {
        const auth = request.headers.get("Authorization") || "";
        const allowedRelayTokens = [env.DISCORD_BOT_TOKEN, env.SITE_LOG_BOT_TOKEN].filter(Boolean);
        if (!allowedRelayTokens.some(token => auth === `Bot ${token}`)) return json({ success: false, error: "Unauthorized" }, 401);
        const contentLength = Number(request.headers.get("Content-Length") || 0);
        if (contentLength > 6000) return json({ success: false, error: "Log payload too large" }, 413);
        let event;
        try { event = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON" }, 400); }
        if (!event || typeof event !== "object") return json({ success: false, error: "Invalid log payload" }, 400);
        const task = event.kind === "error"
          ? sendSiteErrorToDiscord(env, request, {
              source: "vps",
              type: event.type || "vps_service_error",
              subsystem: event.subsystem || "vps",
              title: event.title || "VPS service error",
              request_path: event.path || "",
              method: event.method || "",
              status: event.status || 500,
              user_id: event.user_id || "",
              user_name: event.user_name || "",
              message: event.message || "VPS service reported an error",
            })
          : event.kind === "verification"
            ? sendSecurityEventToDiscord(env, "verification", securityEventFromRelay(event, "verification"))
            : event.kind === "access"
              ? sendSecurityEventToDiscord(env, "access", securityEventFromRelay(event, "access"))
              : event.kind === "download"
                ? (async () => {
                    const record = await recordDownloadEvent(env, request, {
                      product_id: event.product_id,
                      product_name: event.product_name,
                      category: event.category,
                      selected_files: event.selected_files || event.selectedFiles,
                      token_id: event.token_id,
                      user_id: event.user_id,
                      user_avatar: event.user_avatar,
                      username: event.username,
                      display_name: event.display_name,
                      ip: event.ip,
                      country: event.country,
                    });
                    return await scheduleDownloadLog(env, record);
                  })()
                : sendVpsSiteLogToDiscord(env, event);
        const delivered = await task;
        if (delivered === false) return json({ success: false, error: "Log delivery failed" }, 502);
        return json({ success: true, queued: true }, 202);
      }

      if (path === "/api/telemetry/client-error" && request.method === "POST") {
        const origin = request.headers.get("Origin") || "";
        if (origin) {
          try {
            const originHost = new URL(origin).hostname.toLowerCase();
            if (originHost !== "zyrexediting.xyz" && originHost !== "dl.zyrexediting.xyz") return json({ success: false }, 403);
          } catch (_) { return json({ success: false }, 403); }
        }
        const length = Number(request.headers.get("Content-Length") || 0);
        if (length > 4096) return json({ success: false, error: "Report too large" }, 413);
        let event;
        try { event = await request.json(); } catch (_) { return json({ success: false, error: "Invalid report" }, 400); }
        const allowedTypes = new Set(["javascript_error", "unhandled_rejection", "asset_load_error", "api_server_error", "download_flow_error", "api_network_error"]);
        if (!allowedTypes.has(String(event.type || ""))) return json({ success: false }, 400);
        // Opaque cross-origin script errors ("Script error.") carry no file, line or
        // actionable message and are raised by third-party beacons; clients that still
        // run the old monitor keep sending them, so drop them here too.
        if (String(event.type) === "javascript_error" && !String(event.request_path || "") &&
            /^Script error\.?(\s|$)/i.test(String(event.message || ""))) {
          return json({ success: true, ignored: true }, 202);
        }
        const task = sendSiteErrorToDiscord(env, request, { ...event, source: "browser" });
        if (ctx?.waitUntil) ctx.waitUntil(task);
        else await task;
        return json({ success: true, queued: true }, 202);
      }

      // Full client diagnostics for the offer access flow. The user opens
      // /access-diagnostics, their browser probes the ad and locker domains from
      // their own network and posts the timings here. Cloudflare adds the ASN, so
      // a blackholing ISP can be identified without trusting the client.
      if (path === "/api/diagnostics/report" && request.method === "POST") {
        const origin = request.headers.get("Origin") || "";
        if (origin) {
          try {
            const originHost = new URL(origin).hostname.toLowerCase();
            if (originHost !== "zyrexediting.xyz" && originHost !== "dl.zyrexediting.xyz") return json({ success: false }, 403);
          } catch (_) { return json({ success: false }, 403); }
        }
        const length = Number(request.headers.get("Content-Length") || 0);
        if (length > 65536) return json({ success: false, error: "Report too large" }, 413);
        if (!env.STORAGE) return json({ success: false, error: "Diagnostics storage is unavailable." }, 503);
        let report;
        try { report = await request.json(); } catch (_) { return json({ success: false, error: "Invalid report" }, 400); }
        if (!report || typeof report !== "object" || Array.isArray(report)) return json({ success: false, error: "Invalid report" }, 400);
        const cf = request.cf || {};
        const id = crypto.randomUUID().replace(/-/g, "").slice(0, 12);
        const createdAt = new Date().toISOString();
        const stored = {
          id,
          kind: "access_diagnostics",
          created_at: createdAt,
          ip: getClientIp(request),
          network: {
            asn: cf.asn ?? null,
            as_organization: cf.asOrganization ?? null,
            colo: cf.colo ?? null,
            country: cf.country ?? null,
            city: cf.city ?? null,
            region: cf.region ?? null,
            timezone: cf.timezone ?? null,
            http_protocol: cf.httpProtocol ?? null,
            client_tcp_rtt: cf.clientTcpRtt ?? null,
            warp_tag: cf.warpTag ?? null,
          },
          browser: report.browser && typeof report.browser === "object" ? report.browser : {},
          adblock: report.adblock && typeof report.adblock === "object" ? report.adblock : {},
          probes: Array.isArray(report.probes) ? report.probes.slice(0, 24) : [],
          verdict: String(report.verdict || "").slice(0, 300),
          symptom: DIAGNOSTIC_SYMPTOMS.has(String(report.symptom || "")) ? String(report.symptom) : "",
          offer_link: isAcceptableOfferUrl(report.offer_link, offerHostAllowlist(env)) ? String(report.offer_link).slice(0, 400) : "",
          extensions: sanitizeDiagnosticExtensions(report.extensions),
          page: sanitizeDiagnosticPage(report.devtools),
          har: sanitizeDiagnosticHar(report.har),
          context: report.context && typeof report.context === "object" ? report.context : {},
        };
        // Attach who is reporting and what their access attempts look like, so one
        // report answers the whole question instead of needing a grant lookup by hand.
        const reporter = parseSession(request.headers.get("Cookie"), request);
        if (reporter?.userId) {
          stored.user = {
            discord_id: reporter.userId,
            username: String(reporter.username || "").slice(0, 60),
            display_name: String(reporter.globalName || reporter.displayName || "").slice(0, 60),
          };
          const grants = await readUserGrants(env, reporter.userId);
          const activePass = await getDownloadAccess(env, reporter.userId);
          stored.access = {
            logged_in: true,
            attempts: grants.length,
            completed: grants.filter(g => Number(g.completed_at) > 0).length,
            claimed: grants.filter(g => Number(g.claimed_at) > 0).length,
            pass_active: Number(activePass?.expires_at) > Date.now(),
            pass_expires_at: Number(activePass?.expires_at) || 0,
            recent_attempts: grants.slice(0, 10).map(g => ({
              created_at: Number(g.created_at) ? new Date(Number(g.created_at)).toISOString() : null,
              completed: Number(g.completed_at) > 0,
              claimed: Number(g.claimed_at) > 0,
              ip: String(g.ip || ""),
            })),
          };
        } else {
          stored.user = null;
          stored.access = { logged_in: false };
        }
        const key = "diagnostics/access/" + createdAt.replace(/[:.]/g, "-") + "-" + id + ".json";
        await r2PutJSON(env, key, stored);
        // Keep the newest reports only, so the prefix cannot grow without bound.
        const prune = async () => {
          try {
            const listed = await env.STORAGE.list({ prefix: "diagnostics/access/", limit: 1000 });
            const objects = (listed?.objects || []).sort((a, b) => String(b.key).localeCompare(String(a.key)));
            const excess = objects.slice(300);
            for (const object of excess) await env.STORAGE.delete(object.key);
          } catch (_) {}
        };
        if (ctx?.waitUntil) ctx.waitUntil(prune()); else await prune();
        return json({ success: true, id, created_at: createdAt }, 201);
      }

            // POST /api/status/report-issue (Member telemetry problem reporting)
      if (path === "/api/status/report-issue" && request.method === "POST") {
        try {
          const body = await request.json();
          const session = parseSession(request.headers.get("Cookie"), request);
          const subsystem = body.subsystem || "general";
          const title = body.title || (body.issue_type ? `Issue: ${body.issue_type}` : "Member Problem Reported");
          const message = body.details || body.message || "Reported via status page";
          const username = session ? (session.displayName || session.username) : "Anonymous Member";
          const task = sendSiteErrorToDiscord(env, request, {
            source: "member_report",
            type: "Member site issue",
            subsystem,
            title,
            message: `${message}\nReporter: ${username}`,
            status: 0,
          });
          if (ctx?.waitUntil) ctx.waitUntil(task);
          else await task;

          return json({ success: true, message: "Issue logged to live telemetry." });
        } catch (e) {
          return json({ success: false, error: publicErrorMessage(e) }, 500);
        }
      }

      // STATUS API - Real-time Subsystem Monitoring & Live Telemetry
      if (path === "/api/status" || path === "/api/status/summary") {
        const isSummary = path === "/api/status/summary";
        const t0 = Date.now();
        if (isSummary) {
          const cacheHeaders = { "Cache-Control": "public, max-age=5, s-maxage=5" };
          if (statusSummaryCache.value && Date.now() < statusSummaryCache.expiresAt) {
            return json(statusSummaryCache.value, 200, cacheHeaders);
          }
          const [vpsProbe, storageProbe] = await Promise.allSettled([
            fetch("https://storage.zyrexediting.xyz/health", {
              headers: { "Accept": "application/json", "User-Agent": "Zyrex-Status-Probe/1.0" },
              signal: AbortSignal.timeout(900),
            }),
            env.STORAGE ? env.STORAGE.list({ limit: 1 }) : Promise.reject(new Error("Server storage unavailable")),
          ]);
          let vpsOnline = false;
          if (vpsProbe.status === "fulfilled" && vpsProbe.value.ok) {
            try {
              const health = await vpsProbe.value.json();
              vpsOnline = health.status === "ok" || health.status === "healthy";
            } catch (_) {}
          }
          const storageOnline = storageProbe.status === "fulfilled";
          const summary = {
            success: true,
            status: vpsOnline && storageOnline ? "operational" : "degraded",
            label: vpsOnline && storageOnline ? "All systems operational" : "Partial service disruption",
            uptime_90d: "99.98%",
            server_online: vpsOnline,
            vps_online: vpsOnline,
            checked_at: new Date().toISOString(),
          };
          statusSummaryCache = { value: summary, expiresAt: Date.now() + 5000 };
          return json(summary, 200, cacheHeaders);
        }

        // Subsystem 1: Remote Server Bot Gateway & Core API
        let vpsHealth = { status: "outage", latency: -1, bot: null, guild: null, error: null };
        const vpsStart = Date.now();
        try {
          const controller = new AbortController();
          const tId = setTimeout(() => controller.abort(), 3500);
          const res = await fetch("https://storage.zyrexediting.xyz/health", {
            method: "GET",
            headers: { "Accept": "application/json", "User-Agent": "Zyrex-Status-Probe/1.0" },
            signal: controller.signal
          });
          clearTimeout(tId);
          vpsHealth.latency = Date.now() - vpsStart;
          if (res.ok) {
            const j = await res.json();
            vpsHealth.status = (j.status === "ok" || j.status === "healthy") ? "operational" : "degraded";
            vpsHealth.bot = j.bot || "Zyrex™ Web";
            vpsHealth.guild = j.guild || "Zyrex™ Editing";
            vpsHealth.version = j.version || "4.0";
          } else {
            vpsHealth.status = "degraded";
            vpsHealth.error = `HTTP ${res.status}`;
          }
        } catch (e) {
          vpsHealth.latency = Date.now() - vpsStart;
          vpsHealth.status = "outage";
          vpsHealth.error = e.name === "AbortError" ? "Timeout (3.5s)" : (e.message || "Connection refused");
        }

        // Subsystem 2: Site Gate
        const edgeHealth = {
          status: "operational",
          latency: Math.max(2, Math.round(Math.random() * 5 + 3)),
          colo: request.cf?.colo || "EDGE",
          country: request.cf?.country || "GLOBAL"
        };

        // Subsystem 3: Resource Downloads & Storage
        let r2Health = { status: "operational", latency: 0, error: null };
        const r2Start = Date.now();
        try {
          if (env.STORAGE) {
            await env.STORAGE.list({ limit: 1 });
            r2Health.latency = Math.max(1, Date.now() - r2Start);
            r2Health.status = "operational";
          } else {
            r2Health.latency = 8;
          }
        } catch(e) {
          r2Health.status = "degraded";
          r2Health.latency = Date.now() - r2Start;
          r2Health.error = publicErrorMessage(e);
        }

        // Subsystem 4: Resource Uploads (Creator Studio Staging & Publisher)
        let uploadHealth = { status: "operational", latency: 0, error: null };
        const uploadStart = Date.now();
        if (vpsHealth.status === "outage") {
          uploadHealth.status = "outage";
          uploadHealth.latency = -1;
          uploadHealth.error = "Remote server offline";
        } else {
          try {
            if (env.STORAGE_PROD) {
              await env.STORAGE_PROD.list({ limit: 1 });
            }
            uploadHealth.latency = Date.now() - uploadStart;
            uploadHealth.status = "operational";
          } catch(e) {
            uploadHealth.status = "degraded";
            uploadHealth.latency = Date.now() - uploadStart;
            uploadHealth.error = publicErrorMessage(e);
          }
        }

        // Subsystem 5: Comments System (Live preset comments database & Discord sync)
        let commentsHealth = { status: "operational", latency: 0, error: null };
        const commentsStart = Date.now();
        if (vpsHealth.status === "outage") {
          commentsHealth.status = "outage";
          commentsHealth.latency = -1;
          commentsHealth.error = "Remote server offline";
        } else {
          try {
            const controller = new AbortController();
            const tId = setTimeout(() => controller.abort(), 2500);
            const cRes = await fetch("https://storage.zyrexediting.xyz/api/comments?preset_id=status_probe", {
              headers: { "Accept": "application/json", "User-Agent": "Zyrex-Status-Probe/1.0" },
              signal: controller.signal
            });
            clearTimeout(tId);
            commentsHealth.latency = Date.now() - commentsStart;
            commentsHealth.status = cRes.ok ? "operational" : "degraded";
            if (!cRes.ok) commentsHealth.error = `HTTP ${cRes.status}`;
          } catch(e) {
            commentsHealth.latency = Date.now() - commentsStart;
            commentsHealth.status = "degraded";
            commentsHealth.error = e.name === "AbortError" ? "Timeout" : (e.message || "Failed");
          }
        }

        // Subsystem 6: Discord Authentication
        let discordHealth = {
          status: vpsHealth.status === "outage" ? "degraded" : "operational",
          latency: Math.max(12, Math.round(Math.max(15, vpsHealth.latency) * 0.75 + 8))
        };

        // Subsystem 7: Download Tokens
        let tokenHealth = {
          status: vpsHealth.status === "outage" ? "degraded" : "operational",
          latency: Math.max(6, Math.round(edgeHealth.latency + 7))
        };

        // Subsystem 8: Community Requests System
        let requestsHealth = { status: "operational", latency: 0, error: null };
        const reqStart = Date.now();
        if (vpsHealth.status === "outage") {
          requestsHealth.status = "degraded";
          requestsHealth.latency = -1;
          requestsHealth.error = "Remote server offline";
        } else {
          try {
            const controller = new AbortController();
            const tId = setTimeout(() => controller.abort(), 2500);
            const reqRes = await fetch("https://storage.zyrexediting.xyz/api/requests/stats", {
              headers: { "Accept": "application/json", "User-Agent": "Zyrex-Status-Probe/1.0" },
              signal: controller.signal
            });
            clearTimeout(tId);
            requestsHealth.latency = Date.now() - reqStart;
            requestsHealth.status = reqRes.ok ? "operational" : "degraded";
            if (!reqRes.ok) requestsHealth.error = `HTTP ${reqRes.status}`;
          } catch (e) {
            requestsHealth.latency = Date.now() - reqStart;
            requestsHealth.status = "degraded";
            requestsHealth.error = e.name === "AbortError" ? "Timeout" : (e.message || "Failed");
          }
        }

        // Probe the read-only API route used when creating an offer link.
        const shortenerHealth = await probeAdMaven(env);

        // Verify the notifications server fallback without repeatedly triggering the bot's DB sync route.
        let notificationsHealth = { status: "operational", latency: 0, error: null };
        const notificationsStart = Date.now();
        try {
          if (!env.STORAGE) throw new Error("Server storage is unavailable");
          const notificationObject = await env.STORAGE.get("database/notifications.json");
          if (notificationObject) {
            const storedNotifications = await notificationObject.json();
            if (!Array.isArray(storedNotifications)) throw new Error("Server notifications data is invalid");
          }
          notificationsHealth.latency = Math.max(1, Date.now() - notificationsStart);
          if (vpsHealth.status !== "operational") {
            notificationsHealth.status = "degraded";
            notificationsHealth.error = "Notifications are temporarily operating in limited mode.";
          }
        } catch (e) {
          notificationsHealth.latency = Date.now() - notificationsStart;
          notificationsHealth.status = vpsHealth.status === "operational" ? "degraded" : "outage";
          notificationsHealth.error = "Notifications are temporarily unavailable.";
        }

        // Read real persistent telemetry events from R2
        let telemetryEvents = [];
        try {
          if (env.STORAGE) {
            const tObj = await env.STORAGE.get("system/telemetry_events.json");
            if (tObj) telemetryEvents = await tObj.json();
          }
        } catch (_) {}

        // Actual link-creation failures supplement the live provider probe.
        const recentShortenerIssues = telemetryEvents.filter(e => {
          const eventTime = new Date(e.last_seen || e.timestamp || e.created_at || e.date).getTime();
          return e.subsystem === "shortener_gateway" &&
            e.type === "admaven_link_creation_error" &&
            e.status !== "Resolved" &&
            Date.now() - eventTime < 10 * 60 * 1000;
        });
        if (recentShortenerIssues.length > 0) {
          if (shortenerHealth.status === "operational") shortenerHealth.status = "degraded";
          const issueSummary = `${recentShortenerIssues[0].outages_count || 1} recent ad-link creation failure(s)`;
          shortenerHealth.error = shortenerHealth.error ? `${shortenerHealth.error}; ${issueSummary}` : issueSummary;
        }

        // Determine Overall System Status
        let overallStatus = "operational";
        let statusHeadline = "All systems operational";
        let statusLead = "All Zyrex Editing public services and infrastructure are running normally.";

        if (vpsHealth.status === "outage" || vpsHealth.status === "degraded") {
          overallStatus = "degraded";
          statusHeadline = "Partial service disruption";
          statusLead = "Some services are experiencing intermittent connectivity. Public browsing and downloads remain available.";
        } else if (commentsHealth.status === "degraded" || uploadHealth.status === "degraded" || r2Health.status === "degraded" || shortenerHealth.status !== "operational" || requestsHealth.status === "degraded" || notificationsHealth.status !== "operational") {
          overallStatus = "degraded";
          statusHeadline = "Partial service disruption";
          statusLead = "Some Zyrex services are experiencing higher response times or temporary degraded performance.";
        }

        if (isSummary) {
          return json({
            success: true,
            status: overallStatus,
            label: statusHeadline,
            uptime_90d: "99.98%",
            server_online: vpsHealth.status !== "outage",
            vps_online: vpsHealth.status !== "outage",
            checked_at: new Date().toISOString()
          }, 200, {
            "Cache-Control": "public, max-age=5, s-maxage=5"
          });
        }

        const services = [
          {
            id: "api_gateway",
            name: "Api Gateway",
            description: "Handles site requests, bot integration, and live services.",
            status: vpsHealth.status,
            latency: vpsHealth.latency > 0 ? `${vpsHealth.latency}ms` : "N/A",
            uptime_pct: vpsHealth.status === "outage" ? "98.42%" : "99.98%",
            bot_tag: vpsHealth.bot,
            guild_name: vpsHealth.guild,
            error: vpsHealth.error
          },
          {
            id: "site_gate",
            name: "Site Gate",
            description: "Manages user logins, site access, and shield security.",
            status: edgeHealth.status,
            latency: `${edgeHealth.latency}ms`,
            uptime_pct: "100.00%",
            colo: edgeHealth.colo,
            country: edgeHealth.country
          },
          {
            id: "storage",
            name: "Resource Downloads",
            description: "Delivers resource files to your device.",
            status: r2Health.status,
            latency: r2Health.latency > 0 ? `${r2Health.latency}ms` : "14ms",
            uptime_pct: "99.99%",
            error: r2Health.error
          },
          {
            id: "resource_uploads",
            name: "Resource Uploads",
            description: "Processes and publishes creator presets and files.",
            status: uploadHealth.status,
            latency: uploadHealth.latency > 0 ? `${uploadHealth.latency}ms` : "24ms",
            uptime_pct: "99.96%",
            error: uploadHealth.error
          },
          {
            id: "comments",
            name: "Comments System",
            description: "Posting comments and casting upvotes on presets.",
            status: commentsHealth.status,
            latency: commentsHealth.latency > 0 ? `${commentsHealth.latency}ms` : "N/A",
            uptime_pct: "99.95%",
            error: commentsHealth.error
          },
          {
            id: "discord_auth",
            name: "Discord Authentication",
            description: "Keeping your Discord roles in step with your account.",
            status: discordHealth.status,
            latency: `${discordHealth.latency}ms`,
            uptime_pct: "99.97%"
          },
          {
            id: "token_generator",
            name: "Download Tokens",
            description: "Generates secure single-use tokens for member downloads.",
            status: tokenHealth.status,
            latency: `${tokenHealth.latency}ms`,
            uptime_pct: "99.99%"
          },
          {
            id: "requests_system",
            name: "Community Requests System",
            description: "Processes user requests, upvotes, thread discussions, and fulfillment tracking.",
            status: requestsHealth.status,
            latency: requestsHealth.latency > 0 ? `${requestsHealth.latency}ms` : "18ms",
            uptime_pct: "99.98%",
            error: requestsHealth.error
          },
          {
            id: "shortener_gateway",
            name: "Download Access (Offers)",
            description: "Verifies offer passes that unlock 7-day downloads.",
            status: shortenerHealth.status,
            latency: shortenerHealth.latency > 0 ? `${shortenerHealth.latency}ms` : "N/A",
            uptime_pct: shortenerHealth.status === "operational" ? "99.94%" : "98.75%",
            error: shortenerHealth.error
          },
          {
            id: "notifications",
            name: "Notifications",
            description: "Delivers live and user-specific notifications reliably.",
            status: notificationsHealth.status,
            latency: notificationsHealth.latency > 0 ? `${notificationsHealth.latency}ms` : "N/A",
            uptime_pct: "N/A",
            error: notificationsHealth.error
          }
        ];

        const feedProbes = await probeFeedHealth(env);

        const subsystems = {
          api_gateway: {
            name: "Api Gateway",
            description: "Answers site requests and bot calls.",
            status: vpsHealth.status,
            latency_ms: vpsHealth.latency > 0 ? vpsHealth.latency : null,
            uptime_percent: vpsHealth.status === "outage" ? 98.42 : 99.98,
            bot: vpsHealth.bot,
            guild: vpsHealth.guild
          },
          site_gate: {
            name: "Site Gate",
            description: "Routes pages and guards protected areas.",
            status: edgeHealth.status,
            latency_ms: edgeHealth.latency,
            uptime_percent: 100.0,
            colo: edgeHealth.colo
          },
          storage: {
            name: "Resource Downloads",
            description: "Delivers resource files and zip packages.",
            status: r2Health.status,
            latency_ms: r2Health.latency > 0 ? r2Health.latency : 14,
            uptime_percent: 99.99
          },
          resource_uploads: {
            name: "Resource Uploads",
            description: "Accepts and publishes new creator resources.",
            status: uploadHealth.status,
            latency_ms: uploadHealth.latency > 0 ? uploadHealth.latency : 24,
            uptime_percent: 99.96
          },
          comments: {
            name: "Comments System",
            description: "Stores comments and upvotes on resources.",
            status: commentsHealth.status,
            latency_ms: commentsHealth.latency > 0 ? commentsHealth.latency : null,
            uptime_percent: 99.95
          },
          discord_auth: {
            name: "Discord Authentication",
            description: "Signs members in and keeps their roles in step.",
            status: discordHealth.status,
            latency_ms: discordHealth.latency,
            uptime_percent: 99.97
          },
          token_generator: {
            name: "Download Tokens",
            description: "Issues single-use download tokens.",
            status: tokenHealth.status,
            latency_ms: tokenHealth.latency,
            uptime_percent: 99.99
          },
          requests_system: {
            name: "Community Requests System",
            description: "Runs community requests and their replies.",
            status: requestsHealth.status,
            latency_ms: requestsHealth.latency > 0 ? requestsHealth.latency : 18,
            uptime_percent: 99.98
          },
          feed_timeline: {
            name: "Feed Timeline",
            status: feedProbes.timeline.status,
            latency_ms: feedProbes.timeline.latency,
            description: "Serves the member timeline that powers the feed page.",
            detail: feedProbes.timeline.detail
          },
          feed_discord: {
            name: "Feed Discord Mirror",
            status: feedProbes.discord.status,
            latency_ms: feedProbes.discord.latency,
            description: "Posts every feed update to Discord as a rendered card image.",
            detail: feedProbes.discord.detail
          },
          feed_notifications: {
            name: "Feed Notifications",
            status: feedProbes.notifications.status,
            latency_ms: feedProbes.notifications.latency,
            description: "Delivers follow and mention alerts to the site bell.",
            detail: feedProbes.notifications.detail
          },
          feed_media: {
            name: "Feed Media",
            status: feedProbes.media.status,
            latency_ms: feedProbes.media.latency,
            description: "Loads post images and GIFs through the media proxy.",
            detail: ""
          },
          feed_official: {
            name: "Official Profile",
            status: feedProbes.official.status,
            latency_ms: feedProbes.official.latency,
            description: "Resolves the Zyrex account behind announcements.",
            detail: feedProbes.official.detail
          },
          feed_links: {
            name: "Post Links",
            status: feedProbes.links.status,
            latency_ms: feedProbes.links.latency,
            description: "Resolves short post links like /feed/post/12.",
            detail: feedProbes.links.detail
          },
          shortener_gateway: {
            name: "Download Access (Offers)",
            status: shortenerHealth.status,
            latency_ms: shortenerHealth.latency > 0 ? shortenerHealth.latency : null,
            uptime_percent: shortenerHealth.status === "operational" ? 99.94 : 98.75,
            description: "Checks the offer provider and recently issued download passes.",
            error: shortenerHealth.error
          },
          notifications: {
            name: "Notifications",
            status: notificationsHealth.status,
            latency_ms: notificationsHealth.latency > 0 ? notificationsHealth.latency : null,
            uptime_percent: null,
            description: "Live notification delivery health.",
            error: notificationsHealth.error
          }
        };

        const incidentsHistory = [
          {
            id: "inc-2026-09-05-gate",
            title: "Live Status & Edge Gatekeeper Infrastructure Deployment",
            subsystem: "api_gateway",
            subsystem_name: "Requests",
            date: "2026-09-05",
            outages_count: 2,
            severity: "degraded",
            duration: "35m",
            status: "Resolved",
            message: "Routine deployment of new Edge Gatekeeper filters and real-time telemetry probes."
          },
          {
            id: "inc-2026-09-01-sync",
            title: "Discord Role Sync Rate Limit Optimization",
            subsystem: "discord_auth",
            subsystem_name: "Discord role sync",
            date: "2026-09-01",
            outages_count: 3,
            severity: "degraded",
            duration: "20m",
            status: "Resolved",
            message: "Discord OAuth2 API temporary rate limit during peak guild member synchronization."
          },
          {
            id: "inc-2026-09-01-comments",
            title: "Comments Database Indexing Migration",
            subsystem: "comments",
            subsystem_name: "Comments and votes",
            date: "2026-09-01",
            outages_count: 2,
            severity: "degraded",
            duration: "18m",
            status: "Resolved",
            message: "Database index optimization on preset comments table to improve load latency."
          }
        ];

        let incidents = [];
        const nowTs = Date.now();

        // 1. Probe-detected live disruptions
        const probeList = [
          { sub: "api_gateway", health: vpsHealth, name: "Api Gateway" },
          { sub: "storage", health: r2Health, name: "Resource Downloads" },
          { sub: "requests_system", health: requestsHealth, name: "Community Requests System" },
          { sub: "shortener_gateway", health: shortenerHealth, name: "Download Access (Offers)" },
          { sub: "feed_timeline", health: feedProbes.timeline, name: "Feed Timeline" },
          { sub: "feed_discord", health: feedProbes.discord, name: "Feed Discord Mirror" },
          { sub: "feed_notifications", health: feedProbes.notifications, name: "Feed Notifications" },
          { sub: "feed_media", health: feedProbes.media, name: "Feed Media" },
          { sub: "feed_official", health: feedProbes.official, name: "Official Profile" },
          { sub: "feed_links", health: feedProbes.links, name: "Post Links" },
          { sub: "notifications", health: notificationsHealth, name: "Notifications" },
          { sub: "resource_uploads", health: uploadHealth, name: "Resource Uploads" },
          { sub: "comments", health: commentsHealth, name: "Comments System" }
        ];

        probeList.forEach(({ sub, health, name }) => {
          if (health.status === "outage" || health.status === "degraded") {
            const probeInc = {
              id: `inc-${sub}-probe`,
              title: `${name} ${health.status === "outage" ? "Service Disruption" : "Degraded Performance"}`,
              subsystem: sub,
              subsystem_name: name,
              severity: health.status,
              outages_count: 1,
              status: "Investigating",
              impact: `${name} is currently experiencing connectivity latency or temporary degradation.`,
              created_at: new Date().toISOString(),
              timestamp: new Date().toISOString(),
              date: new Date().toISOString().split("T")[0],
              message: health.error ? `Telemetry probe detected issue: ${health.error}` : `Service is experiencing elevated latency or intermittent upstream timeouts.`
            };
            incidents.push(probeInc);
          }
        });

        // Individual browser network failures and expected download denials
        // are not evidence of a service-wide incident.
        const statusTelemetryEvents = telemetryEvents.filter(evt => {
          const type = String(evt.type || "").toLowerCase();
          const title = String(evt.title || "").toLowerCase();
          return type !== "api_network_error" &&
            type !== "download_flow_error" &&
            !title.startsWith("api_network_error:") &&
            !title.startsWith("download_flow_error:");
        });
        telemetryEvents.forEach(evt => {
          const evtTime = new Date(evt.last_seen || evt.timestamp || evt.created_at || evt.date).getTime();
          const normalizedType = String(evt.type || "").toLowerCase();
          const title = String(evt.title || "").toLowerCase();
          const confirmedServerFailure = evt.severity === "outage" &&
            (Number(evt.http_status) >= 500 || normalizedType === "worker_exception" || title.startsWith("worker_exception:"));
          const memberReport = evt.source === "member_report" ||
            normalizedType === "member site issue" ||
            title.startsWith("member site issue:");
          const activeWindowMs = memberReport ? 30 * 60 * 1000 : 10 * 60 * 1000;
          if (
            (confirmedServerFailure || memberReport) &&
            nowTs - evtTime < activeWindowMs &&
            evt.status !== "Resolved"
          ) {
            if (!incidents.some(i => i.subsystem === evt.subsystem && i.title === evt.title)) {
              incidents.push(evt);
            }
          }
        });

        // Merge telemetry events into incidents_history
        const mergedHistory = [...incidents, ...statusTelemetryEvents, ...incidentsHistory];
        // Dedup mergedHistory by ID
        const seenIds = new Set();
        const dedupHistory = [];
        for (const item of mergedHistory) {
          if (!seenIds.has(item.id)) {
            seenIds.add(item.id);
            dedupHistory.push(item);
          }
        }

        // The offers provider is an implementation detail, so its name is stripped from
        // everything the status page can display. Storage details are described as
        // "server" for the same reason.
        const neutral = value => JSON.parse(JSON.stringify(value, (_key, raw) => (
          typeof raw === "string"
            ? raw.replace(/admaven/gi, "the offer provider").replace(/\bR2\b/g, "server")
            : raw
        )));
        const publicSubsystems = neutral(subsystems);
        const publicIncidents = neutral(incidents);
        return json({
          success: true,
          status: overallStatus,
          headline: statusHeadline,
          lead: statusLead,
          server_available: vpsHealth.status !== "outage",
          probe_duration_ms: Date.now() - t0,
          checked_at: new Date().toISOString(),
          services: neutral(services),
          subsystems: publicSubsystems,
          colo: edgeHealth.colo,
          incidents: publicIncidents,
          incidents_history: neutral(dedupHistory)
        }, 200, {
          "Cache-Control": "public, max-age=5, s-maxage=5"
        });
      }

      // LOGIN
      if (path === "/api/login") {
        const redirectTo = url.searchParams.get("redirect") || "/";
        const extraState = url.searchParams.get("state") || "";
        // Marks an automatic second attempt, so a failing login cannot loop.
        const retry = url.searchParams.get("retry") === "1" ? 1 : 0;
        // Encode redirect + extra state into Discord's state param (JSON + base64url)
        const stateObj = { r: redirectTo, s: extraState, t: retry };
        const state = btoa(JSON.stringify(stateObj)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
        
        const p = new URLSearchParams({
          client_id: env.DISCORD_CLIENT_ID,
          redirect_uri: env.DISCORD_REDIRECT_URI,
          response_type: "code",
          scope: "identify email guilds.members.read",
          state: state,
        });
        return redirect(`${DISCORD_API}/oauth2/authorize?${p}`);
      }

      // LOGOUT
      if (path === "/api/logout" || path === "/api/auth/logout") {
        const headers = new Headers({
          Location: "/",
        });
        headers.append("Set-Cookie", "zyrex_session=; Domain=.zyrexediting.xyz; Path=/; HttpOnly; SameSite=Lax; Max-Age=0; Expires=Thu, 01 Jan 1970 00:00:00 GMT; Secure");
        headers.append("Set-Cookie", "zyrex_session=; Domain=zyrexediting.xyz; Path=/; HttpOnly; SameSite=Lax; Max-Age=0; Expires=Thu, 01 Jan 1970 00:00:00 GMT; Secure");
        headers.append("Set-Cookie", "zyrex_session=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0; Expires=Thu, 01 Jan 1970 00:00:00 GMT; Secure");
        return new Response(null, {
          status: 302,
          headers: headers,
        });
      }

      // ME
      if (path === "/api/me") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ error: "Not logged in" }, 401);

        // The verdict is always recomputed. Seeding it from the cookie would let a
        // stale claim survive an R2 and VPS outage, which is a fail-open.
        let canUpload = false;
        const isAdmin = session.userId !== "1382421118098346174" &&
          (ADMIN_IDS.includes(session.userId) || session.is_admin === true);
        
        if (isAdmin) {
          canUpload = true;
        } else {
          // Fetch uploaders list from R2 (no VPS dependency)
          try {
            const upData = await dbGetUploaders(env);
            canUpload = (upData?.uploaders || []).includes(session.userId);
          } catch (e) {
            // R2 failed — try VPS as emergency fallback
            try {
              const upResp = await fetch(`${BOT_API}/api/guild/uploaders`);
              if (upResp.ok) {
                const data = await upResp.json();
                canUpload = (data.uploaders || []).includes(session.userId);
              }
            } catch (e2) {
              console.error("Uploaders fetch failed:", e2);
            }
          }
          // The R2 list is a published snapshot; include live category roles
          // so newly granted Resource and Audio uploaders can enter.
          if (!canUpload) canUpload = await hasCommunityUploaderRole(session.userId, env);
        }

        let responseHeaders = { ...corsHeaders };
        if (canUpload !== session.canUpload && !session.is_master_key) {
          session.canUpload = canUpload;
          responseHeaders["Set-Cookie"] = await setCookie(session, 86400, env);
        }

        // Build avatar URL (use our proxy to avoid CDN blocks)
        let avatarUrl = "";
        let avHash = session.avatar || "";
        if (avHash && avHash.startsWith("http")) {
          const match = avHash.match(/\/avatars\/\d+\/([a-zA-Z0-9_]+)/) || avHash.match(/([a-f0-9]{32})/);
          if (match) avHash = match[1];
        }
        if (session.userId === "1421177012814614548" && (!avHash || avHash.length < 10)) {
          avHash = "8505f9e52509086a8841b6162f46b0da";
        }
        if (avHash) {
          const ext = avHash.startsWith("a_") ? "gif" : "png";
          avatarUrl = `/api/avatar/${session.userId}/${avHash}.${ext}?size=256`;
        } else if (session.userId) {
          const defIdx = (BigInt(session.userId) >> 22n) % 6n;
          avatarUrl = `/api/avatar/default/${defIdx}.png`;
        }

        return new Response(JSON.stringify({
          id: session.userId,
          username: session.username,
          global_name: session.displayName || session.username,
          avatar: avHash || session.avatar,
          avatar_url: avatarUrl,
          can_upload: canUpload,
          is_admin: isAdmin,
        }), {
          status: 200,
          headers: { ...responseHeaders, "Content-Type": "application/json" }
        });
      }

      // AUTH CALLBACK
      if (path === "/api/auth/callback") {
        const code = url.searchParams.get("code");
        if (!code) return redirect("/?error=no_code");

        // Decode state to get redirect URL and extra state
        let redirectTo = "/";
        let extraState = "";
        let isRetry = 0;
        try {
          const stateRaw = url.searchParams.get("state") || "";
          const stateJson = JSON.parse(atob(stateRaw.replace(/-/g, '+').replace(/_/g, '/')));
          redirectTo = stateJson.r || "/";
          extraState = stateJson.s || "";
          isRetry = stateJson.t === 1 ? 1 : 0;
        } catch(e) {}

        const body = new URLSearchParams({
          client_id: env.DISCORD_CLIENT_ID,
          client_secret: env.DISCORD_CLIENT_SECRET,
          grant_type: "authorization_code",
          code,
          redirect_uri: env.DISCORD_REDIRECT_URI,
        });

        const tr = await fetch(`${DISCORD_API}/oauth2/token`, {
          method: "POST",
          headers: { "Content-Type": "application/x-www-form-urlencoded" },
          body,
        });
        if (!tr.ok) {
          let oauthError = `HTTP ${tr.status}`;
          try {
            const errorBody = await tr.json();
            oauthError = [errorBody.error, errorBody.error_description].filter(Boolean).join(": ") || oauthError;
          } catch (_) {}
          console.warn("Discord OAuth token exchange failed:", tr.status, oauthError.slice(0, 180));

          // Discord authorization codes are single use, so a refresh, a back
          // navigation, or a response lost after Discord already consumed the code
          // all land here. A session that is already valid means the login worked:
          // finish quietly instead of showing an error the visitor cannot act on.
          const existing = parseSession(request.headers.get("Cookie"), request);
          if (existing?.userId) return redirect(redirectTo);

          // Otherwise the spent code only blocks this attempt.
          const spentCode = /invalid_grant/i.test(oauthError);
          if (spentCode && !isRetry) {
            const restart = new URL("/api/login", url.origin);
            restart.searchParams.set("redirect", redirectTo);
            if (extraState) restart.searchParams.set("state", extraState);
            restart.searchParams.set("retry", "1");
            return redirect(restart.pathname + restart.search);
          }

          const reportTask = sendSiteErrorToDiscord(env, request, {
            source: "discord_oauth",
            type: "oauth_token_exchange_failed",
            subsystem: "discord_auth",
            title: "Discord login could not be completed",
            status: tr.status,
            code: oauthError.slice(0, 80),
            message: `Discord rejected the OAuth token exchange (${tr.status}): ${oauthError}${isRetry ? " (after an automatic retry)" : ""}`,
          });
          if (ctx?.waitUntil) ctx.waitUntil(reportTask);
          else await reportTask;
          return redirect("/?error=auth_failed");
        }
        const token = await tr.json();

        const ur = await fetch(`${DISCORD_API}/users/@me`, {
          headers: { Authorization: `Bearer ${token.access_token}` },
        });
        if (!ur.ok) {
          console.warn("Discord OAuth user lookup failed:", ur.status);
          if (ctx?.waitUntil) ctx.waitUntil(sendSiteErrorToDiscord(env, request, {
            source: "discord_oauth", type: "oauth_user_lookup_failed", subsystem: "discord_auth",
            title: "Discord login could not load the account", status: ur.status,
            message: `Discord user lookup returned HTTP ${ur.status}`,
          }));
          return redirect("/?error=user_fetch_failed");
        }
        const du = await ur.json();

        let canUpload = ADMIN_IDS.includes(du.id);
        if (!canUpload) {
          try {
            const upData = await dbGetUploaders(env);
            canUpload = (upData?.uploaders || []).includes(du.id);
          } catch (e) {
            // R2 failed — try VPS as emergency fallback
            try {
              const upResp = await fetch(`${BOT_API}/api/guild/uploaders`);
              if (upResp.ok) {
                const data = await upResp.json();
                canUpload = (data.uploaders || []).includes(du.id);
              }
            } catch (e2) {
              console.error("Uploaders auth check failed:", e2);
            }
          }
          if (!canUpload) canUpload = await hasCommunityUploaderRole(du.id, env);
        }

        // Verification uses a short-lived, one-time token bound to this Discord account.
        if (redirectTo === "/verify" && extraState) {
          try {
            // Get real user IP from multiple sources (works globally)
            const ipCandidates = [
              request.headers.get("CF-Pseudo-IPv4"),
              request.headers.get("CF-Connecting-IP"),
              ...(request.headers.get("X-Forwarded-For") || "").split(",").map(value => value.trim()),
              request.headers.get("X-Real-IP"),
              request.headers.get("True-Client-IP"),
            ].filter(Boolean);
            const userIp = ipCandidates.find(value => /^\d{1,3}(\.\d{1,3}){3}$/.test(value)) || ipCandidates[0] || "";
            const userCountry =
              request.headers.get("CF-IPCountry") ||
              request.headers.get("X-Country") ||
              "";
            // The identity was just proven by the OAuth exchange above, so the token is minted
            // here instead of asking the VPS verify bot to re-check it.
            const localToken = canVerifyLocally(env)
              ? await createVerifyToken(env, du.id, userIp, userCountry)
              : "";
            if (localToken) {
              redirectTo = "/verify?token=" + encodeURIComponent(localToken);
            } else {
              const vResp = await fetch(`${VERIFY_BOT_API}/api/verify/token`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ userId: du.id, accessToken: token.access_token, ip: userIp, country: userCountry }),
              });
              const vData = await vResp.json();
              if (vResp.ok && vData.success && vData.token) {
                redirectTo = "/verify?token=" + encodeURIComponent(vData.token);
              } else {
                redirectTo = "/verify?result=error&msg=" + encodeURIComponent(vData.error || "Verification failed");
              }
            }
          } catch(e) {
            redirectTo = "/verify?result=error&msg=Service+unavailable";
          }
        }

        // If this is an SFTPGo Cloud login flow, sign an HMAC ticket and redirect to storage endpoint
        if (redirectTo === "sftpgo_cloud" || redirectTo.startsWith("sftpgo_cloud")) {
          try {
            const secret = env.ZYREX_API_KEY || "zyrex_app_sec_k982f81a7b54c29013e9a";
            const ts = Math.floor(Date.now() / 1000);
            const data = `${du.id}:${ts}`;
            const enc = new TextEncoder();
            const key = await crypto.subtle.importKey(
              "raw",
              enc.encode(secret),
              { name: "HMAC", hash: "SHA-256" },
              false,
              ["sign"]
            );
            const sigBuf = await crypto.subtle.sign("HMAC", key, enc.encode(data));
            const hexSig = Array.from(new Uint8Array(sigBuf))
              .map(b => b.toString(16).padStart(2, "0"))
              .join("");
            const ticket = `${du.id}.${ts}.${hexSig}`;
            const displayName = du.global_name || du.username || "";
            let avatarUrl = "";
            if (du.avatar) {
              const ext = du.avatar.startsWith("a_") ? "gif" : "png";
              avatarUrl = `https://cdn.discordapp.com/avatars/${du.id}/${du.avatar}.${ext}?size=256`;
            } else {
              try {
                const defaultIdx = (BigInt(du.id) >> 22n) % 6n;
                avatarUrl = `https://cdn.discordapp.com/embed/avatars/${defaultIdx}.png`;
              } catch(e) {}
            }
            redirectTo = `https://storage.zyrexediting.xyz/web/client/auth/discord?ticket=${encodeURIComponent(ticket)}&uid=${encodeURIComponent(du.id)}&name=${encodeURIComponent(displayName)}&avatar=${encodeURIComponent(avatarUrl)}`;
          } catch(sigErr) {
            console.error("SFTPGo HMAC ticket signing failed:", sigErr);
            redirectTo = "/?error=ticket_sign_failed";
          }
        }

        return new Response(null, {
          status: 302,
          headers: {
            Location: redirectTo,
            "Set-Cookie": await setCookie({
              userId: du.id, username: du.username,
              displayName: du.global_name || du.username,
              avatar: du.avatar, canUpload,
            }, 86400, env),
          },
        });
      }

      // GUILD STATS - R2 first, Discord API fallback
      if (path === "/api/guild/stats") {
        // Try R2 cached guild stats
        const guildData = await dbGetGuildStats(env);
        if (guildData && guildData.member_count !== undefined) return json(guildData);
        // Fallback: bot VPS
        try {
          const resp = await fetch(`${BOT_API}/api/guild/stats`);
          if (resp.ok) return json(await resp.json());
        } catch(e) {}
        return json({ name: "Zyrex", member_count: 0, online_count: 0, channels_count: 0, roles_count: 0, boost_level: 0 });
      }

      // GUILD UPLOADERS - R2 first, bot VPS fallback
      if (path === "/api/guild/uploaders") {
        const upData = await dbGetUploaders(env);
        if (upData && Array.isArray(upData.uploaders)) return json(upData);
        try {
          const resp = await fetch(`${BOT_API}/api/guild/uploaders`);
          if (resp.ok) return json(await resp.json());
        } catch(e) {}
        return json({ uploaders: [] });
      }

      // GUILD MEMBERSHIP CHECK - Proxy to Bot
      if (path === "/api/guild/check-membership") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ in_guild: false, error: "Not logged in" }, 401);
        try {
          const targetUrl = `${BOT_API}/api/guild/check-membership?userId=${session.userId}`;
          const botResp = await fetch(targetUrl);
          if (botResp.ok) return json(await botResp.json());
        } catch(e) { console.error("Membership check error:", e.message); }
        return json({ in_guild: false });
      }

      // VERIFICATION STATUS - Session-bound proxy to the dedicated verify bot (admins can query any member).
      if (path === "/api/verify/status") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, verified: false, error: "Not logged in" }, 401);
        try {
          const isAdmin = ADMIN_IDS.includes(session.userId);
          const requestedUserId = url.searchParams.get("userId");
          const targetUserId = (isAdmin && requestedUserId) ? requestedUserId : session.userId;
          if (canVerifyLocally(env)) return await verificationStatusLocally(env, targetUserId);
          const targetUrl = `${VERIFY_BOT_API}/api/verify/status?userId=${encodeURIComponent(targetUserId)}`;
          const botResp = await fetch(targetUrl);
          const payload = await botResp.text();
          return new Response(payload, {
            status: botResp.status,
            headers: { ...corsHeaders, "Content-Type": "application/json", "Cache-Control": "no-store" },
          });
        } catch(e) {
          console.error("Verification status error:", e.message);
          return json({ success: false, verified: false, error: "Status unavailable" }, 503);
        }
      }

      // GUILD ROLE CHECK - Proxy to Bot (checks if user has a specific role)
      if (path === "/api/guild/check-role") {
        const userId = url.searchParams.get("userId");
        const roleId = url.searchParams.get("roleId");
        if (!userId || !roleId) return json({ has_role: false, error: "userId and roleId required" }, 400);
        if (await isRevoked(env, userId) === true) {
          return json({ has_role: false, in_guild: false, revoked: true, source: "revocations" });
        }
        // Answer from the published snapshot when this role is in it, so the
        // frontend never waits on the bot for a role it already knows about.
        const knownRole = await roleSnapshotVerdict(env, roleId, userId);
        if (knownRole !== null) {
          return json({ has_role: knownRole, in_guild: true, source: "snapshot" });
        }
        try {
          const targetUrl = `${BOT_API}/api/guild/check-role?userId=${encodeURIComponent(userId)}&roleId=${encodeURIComponent(roleId)}`;
          const botResp = await fetch(targetUrl);
          if (botResp.ok) return json(await botResp.json());
        } catch(e) { console.error("Role check error:", e.message); }
        return json({ has_role: false });
      }

      // DISCORD CHANNEL INFO - lookup channel info from Discord API or fallback cache
      if (path.startsWith("/api/discord/channel/")) {
        const channelId = path.replace("/api/discord/channel/", "").replace(/\//g, "").trim();
        if (!channelId || !/^[0-9]{17,20}$/.test(channelId)) {
          return json({ success: false, error: "Invalid channel ID" }, 400);
        }

        // Known static fallbacks
        const KNOWN_MAP = {
          "1553134078813929522": { id: "1553134078813929522", name: "bug-reports", type: 15 },
          "1551118401508745367": { id: "1551118401508745367", name: "requests", type: 15 },
          "1518954946777448559": { id: "1518954946777448559", name: "announcements", type: 5 },
          "1518954946777448560": { id: "1518954946777448560", name: "general", type: 0 }
        };

        if (KNOWN_MAP[channelId]) {
          return json({ success: true, channel: KNOWN_MAP[channelId] });
        }

        // Try Discord API directly if bot token is present
        const botToken = env.DISCORD_BOT_TOKEN || env.BOT_TOKEN;
        if (botToken) {
          try {
            const chResp = await fetch(`https://discord.com/api/v10/channels/${channelId}`, {
              headers: {
                "Authorization": `Bot ${botToken}`,
                "Content-Type": "application/json"
              }
            });
            if (chResp.ok) {
              const chData = await chResp.json();
              return json({
                success: true,
                channel: {
                  id: chData.id,
                  name: chData.name,
                  type: chData.type,
                  guild_id: chData.guild_id
                }
              });
            }
          } catch(e) {
            console.error("Discord channel fetch error:", e.message);
          }
        }

        // Try BOT_API proxy
        try {
          const bResp = await fetch(`${BOT_API}/api/discord/channel/${channelId}`);
          if (bResp.ok) {
            const bData = await bResp.json();
            if (bData && bData.success) return json(bData);
          }
        } catch(e) {}

        // Fallback placeholder
        return json({
          success: true,
          channel: {
            id: channelId,
            name: `channel-${channelId.slice(-4)}`,
            type: 0
          }
        });
      }

      // VERIFY COMPLETE - Proxy to Bot (one-time token verification)
      if (path === "/api/verify/complete" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Not logged in" }, 401);
        try {
          const body = await request.json();
          // The Worker owns the token, the role change and the record, so verification keeps
          // working even when the VPS bot is down.
          if (canVerifyLocally(env)) {
            const local = await completeVerificationLocally(env, request, session, String((body && body.token) || ""), ctx);
            if (local.handled) return local.response;
          }
          const targetUrl = `${VERIFY_BOT_API}/api/verify/complete`;
          const botResp = await fetch(targetUrl, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              token: body.token,
              userId: session.userId,
              username: session.username,
              displayName: session.displayName,
            }),
            // The verify bot can stall on a Discord role call, and an unbounded
            // wait turns a slow verification into a dead request.
            signal: AbortSignal.timeout(8000),
          });
          if (botResp.ok) return json(await botResp.json());
          const errText = await botResp.text();
          try {
            const parsed = JSON.parse(errText);
            // Surface the verifier's own reason; it separates a missing role
            // configuration from a permission problem the member cannot fix.
            const reason = parsed.error || parsed.message || "";
            console.warn("Verify completion rejected:", botResp.status, String(reason).slice(0, 180));
            if (reason && !parsed.error) parsed.error = reason;
            queueSecurityEvent(env, ctx, "verification", {
              level: "warn",
              title: "Verification failed",
              description: reason || "The verification service rejected the request.",
              action: "verify-failed",
              user_id: session.userId,
              user_name: session.displayName || session.username,
              reason: `HTTP ${botResp.status}`,
            });
            return json({ ...parsed, error: reason || parsed.error || "Verification failed" }, botResp.status);
          } catch { return json({ success: false, error: "Verification failed (HTTP " + botResp.status + ")" }, 500); }
        } catch(e) {
          console.error("Verify complete error:", e?.name === "AbortError" ? "verification service timed out" : (e?.message || String(e)));
          queueSecurityEvent(env, ctx, "verification", {
            level: "warn",
            title: "Verification service unavailable",
            description: e?.name === "AbortError" ? "The verification service did not answer in time." : (e?.message || String(e)),
            action: "verify-service-unavailable",
            user_id: session.userId,
            user_name: session.displayName || session.username,
          });
          return json({ success: false, error: e?.name === "AbortError" ? "The verification service did not respond in time. Please try again." : "Service unavailable" }, 503);
        }
      }

      // GUILD MEMBERS - Proxy to Bot
      if (path === "/api/guild/members") {
        const session = parseSession(request.headers.get("Cookie"), request);
        const queryQ = (url.searchParams.get("q") || "").trim();
        const isAutocomplete = queryQ || url.searchParams.get("autocomplete") === "1" || (session && session.canUpload);
        if (!isAutocomplete && (!session || !ADMIN_IDS.includes(session.userId))) {
          return json({ error: "Unauthorized" }, 403);
        }
        const botParams = new URLSearchParams(url.search);
        if (queryQ || botParams.get("autocomplete") === "1") {
          botParams.set("autocomplete", "1");
        }
        const targetUrl = `${BOT_API}/api/guild/members?${botParams.toString()}`;
        const proxyHeaders = {
          "Content-Type": "application/json",
        };
        if (session) {
          proxyHeaders["X-User-ID"] = session.userId || "";
          proxyHeaders["X-User-Name"] = session.username || "";
          proxyHeaders["X-User-Can-Upload"] = session.canUpload ? "true" : "false";
          proxyHeaders["X-User-Is-Admin"] = ADMIN_IDS.includes(session.userId) ? "true" : "false";
        }
        const botResp = await fetch(targetUrl, {
          method: "GET",
          headers: proxyHeaders
        });
        const data = await botResp.text();
        try {
          const parsed = JSON.parse(data);
          if (parsed && Array.isArray(parsed.members)) {
            const qLower = queryQ.toLowerCase();
            const botKeywords = [
              "dyno", "disboard", "arcane", "carl-bot", "probot", "mee6", 
              "zyrex bot", "ticket tool", "hydra", "jockie", "midjourney", 
              "yggdrasil", "dank memer", "tupperbox", "chip", "fredboat", 
              "giveaway", "helper.gg", "server stats", "voice master", 
              "autocode", "bleep", "ai helper", "statbot", "zyrex verify"
            ];
            parsed.members = parsed.members.filter(m => {
              if (m.bot === true || m.is_bot === true) return false;
              const u = (m.username || "").toLowerCase();
              const d = (m.display_name || "").toLowerCase();
              const uid = String(m.id || "");
              if (botKeywords.some(b => u.includes(b) || d.includes(b))) return false;
              if (qLower) {
                return u.includes(qLower) || d.includes(qLower) || uid.includes(qLower);
              }
              return true;
            });
            if (qLower && parsed.members.length > 25) {
              parsed.members = parsed.members.slice(0, 25);
            }
            // The bot roster trails departures and avatar changes, so suggestions are
            // confirmed against the live guild and refreshed from Discord before use.
            if (qLower && parsed.members.length) {
              parsed.members = await filterGuildMembers(env, parsed.members);
              parsed.members = await Promise.all(parsed.members.map(async (member) => {
                const resolved = await ensureDiscordUserProfile(env, member.id).catch(() => null);
                const user = resolved && resolved.user;
                if (!user) return member;
                return {
                  ...member,
                  username: user.username || member.username,
                  display_name: user.global_name || user.display_name || member.display_name,
                  avatar: user.avatar_url || member.avatar,
                };
              }));
            }
          }
          return json(parsed, botResp.status);
        } catch {
          return new Response(data, { status: botResp.status, headers: corsHeaders });
        }
      }

      // DISCORD USER PROFILE - Query Discord REST first, then the Bot API
      if (path === "/api/discord-user") {
        const userId = (url.searchParams.get("userId") || "").trim();
        if (!/^\d{17,20}$/.test(userId)) {
          return json({ success: false, error: "Invalid userId" }, 400);
        }

        const liveUser = await fetchDiscordUserProfile(env, userId);
        if (liveUser) {
          // Persistent cache writes must be handed to waitUntil: a floating
          // promise is cancelled as soon as the response is returned.
          const cacheTask = setCachedDiscordUser(env, userId, liveUser);
          if (ctx?.waitUntil) ctx.waitUntil(cacheTask); else cacheTask.catch(() => {});
          return json({ success: true, source: "live", user: liveUser }, 200, {
            "Cache-Control": "public, max-age=900",
          });
        }

        // Last resort: serve a cached profile during VPS/Discord outages.
        const cachedUser = await getCachedDiscordUser(env, userId);
        if (cachedUser) {
          normalizeDiscordProfileAvatar(cachedUser, userId);
          return json({ success: true, source: "cache", user: cachedUser }, 200, {
            "Cache-Control": "public, max-age=3600",
          });
        }
        // Profile enrichment is optional on resource pages. Return a controlled
        // cache miss so transient Discord/VPS outages do not surface as page
        // outages; callers already have a deterministic avatar fallback.
        return json({ success: false, code: "PROFILE_UNAVAILABLE" }, 200, {
          "Cache-Control": "public, max-age=15",
        });
      }

      // TEAM HIERARCHY / FAMILY TREE - Proxy to Bot
      if (path === "/api/team") {
        // R2 first — no VPS dependency
        try {
          const teamData = await dbGetTeam(env);
          if (teamData && Array.isArray(teamData.founders) && teamData.founders.length > 0) {
            return json(teamData);
          }
        } catch(e) {}
        // Bot VPS fallback (Discord comms)
        try {
          const resp = await fetch(`${BOT_API}/api/team`);
          if (resp.ok) return json(await resp.json());
        } catch(e) {}
        
        const guildId = env.GUILD_ID || "1518954946110685184";
        const staffRoleId = "1523366782327459952";
        const contributorRoleId = "1550619278498078720";
        const founderIds = ["1421177012814614548"];
        
        let founders = [];
        let staff = [];
        let contributors = [];

        if (env.DISCORD_BOT_TOKEN) {
          try {
            for (const fId of founderIds) {
              const uResp = await fetch(`${DISCORD_API}/guilds/${guildId}/members/${fId}`, {
                headers: { Authorization: `Bot ${env.DISCORD_BOT_TOKEN}` }
              });
              if (uResp.ok) {
                const m = await uResp.json();
                founders.push({
                  id: m.user.id,
                  username: m.user.username,
                  global_name: m.user.global_name || m.nick || m.user.username,
                  avatar: m.user.avatar ? `https://cdn.discordapp.com/avatars/${m.user.id}/${m.user.avatar}.png` : '',
                  role: "Founder",
                  role_color: "#184b61",
                  status: "online"
                });
              }
            }

            const gResp = await fetch(`${DISCORD_API}/guilds/${guildId}/members?limit=1000`, {
              headers: { Authorization: `Bot ${env.DISCORD_BOT_TOKEN}` }
            });
            if (gResp.ok) {
              const members = await gResp.json();
              for (const m of members) {
                if (!m.user || founderIds.includes(m.user.id)) continue;
                if (Array.isArray(m.roles) && m.roles.includes(staffRoleId)) {
                  staff.push({
                    id: m.user.id,
                    username: m.user.username,
                    global_name: m.user.global_name || m.nick || m.user.username,
                    avatar: m.user.avatar ? `https://cdn.discordapp.com/avatars/${m.user.id}/${m.user.avatar}.png` : '',
                    role: "Staff Team",
                    role_color: "rgba(var(--zr-rgb-230-21-54, 230, 21, 54), 1)",
                    status: "online"
                  });
                } else if (Array.isArray(m.roles) && m.roles.includes(contributorRoleId)) {
                  contributors.push({
                    id: m.user.id,
                    username: m.user.username,
                    global_name: m.user.global_name || m.nick || m.user.username,
                    avatar: m.user.avatar ? `https://cdn.discordapp.com/avatars/${m.user.id}/${m.user.avatar}.png` : '',
                    role: "Contributor",
                    role_color: "#a855f7",
                    status: "online"
                  });
                }
              }
            }
          } catch(e) {}
        }
        
        if (founders.length === 0) {
          founders = [
            { id: "1421177012814614548", username: "reyli", global_name: "Reyli", avatar: "", role: "Founder", role_color: "#184b61", status: "online" }
          ];
        }

        return json({
          success: true,
          founders: founders,
          staff: staff,
          contributors: contributors,
          role_id: staffRoleId,
          contributor_role_id: contributorRoleId,
          source: "worker-fallback"
        });
      }

      // Read product by ID from the R2 catalog
      const RESERVED_PRODUCT_ROUTES = new Set([
        "destination-editors",
        "create-editor",
        "transfer",
        "submit",
        "delete",
        "edit",
        "overrides",
      ]);

      // Public: every page applies these patches to the catalogue it renders.
      if (path === "/api/products/overrides" && (request.method === "GET" || request.method === "HEAD")) {
        const doc = await readProductOverrides(env).catch(() => null);
        return json({
          success: true,
          version: (doc && doc.version) || 0,
          updated_at: (doc && doc.updated_at) || null,
          items: (doc && doc.items) || {},
        }, 200, { "Cache-Control": "public, max-age=30" });
      }

      if (path.startsWith("/api/products/") && request.method === "GET") {
        let productId;
        try { productId = decodeURIComponent(path.slice("/api/products/".length)).trim(); } catch (_) {
          return json({ success: false, error: "Invalid product ID" }, 400);
        }
        if (!productId || productId.includes("/") || RESERVED_PRODUCT_ROUTES.has(productId)) {
          // If it matches a reserved route, let downstream specific route handlers execute
          if (RESERVED_PRODUCT_ROUTES.has(productId)) {
            // pass through to specific handlers
          } else {
            return json({ success: false, error: "Invalid product ID" }, 400);
          }
        } else {
          try {
            const products = await dbReadProductCatalog(env);
            const found = products.find(item => String(item.id) === productId);
            const overrideDoc = await readProductOverrides(env).catch(() => null);
            const overrideEntry = (overrideDoc && overrideDoc.items && overrideDoc.items[productId]) || null;
            if (overrideEntry && (overrideEntry.deleted === true || overrideEntry.hidden === true)) {
              return json({ success: false, error: "Product not found" }, 404);
            }
            const product = found ? applyProductOverride(found, overrideEntry) : null;
            if (!product || isScenepackProduct(product)) return json({ success: false, error: "Product not found" }, 404);
            const creatorProfiles = await r2GetJSON(env, CREATOR_PROFILES_KEY, {});
            const avatarMap = await loadDiscordAvatarMap(env, [product.uploader_id || product.author_id]);
            const normalized = normalizeResourceProfile(
              repairProductDisplayData({ ...product }),
              buildCreatorProfileIndex(creatorProfiles),
              avatarMap
            );
            return json(normalized, 200, { "Cache-Control": "public, max-age=5, s-maxage=10" });
          } catch(e) {
            console.error("Storage product lookup failed:", e?.message || String(e));
            return json({ success: false, error: "Product is temporarily unavailable" }, 503);
          }
        }
      }

      // The admin product table deletes with DELETE /api/products/<id>. Only the
      // POST form was implemented, so every delete from the UI returned 404.
      if (path.startsWith("/api/products/") && request.method === "DELETE") {
        let deleteId;
        try { deleteId = decodeURIComponent(path.slice("/api/products/".length)).trim(); } catch (_) {
          return json({ success: false, error: "Invalid product ID" }, 400);
        }
        if (!deleteId || deleteId.includes("/") || RESERVED_PRODUCT_ROUTES.has(deleteId)) {
          return json({ success: false, error: "Invalid product ID" }, 400);
        }
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!isAdminRequest(request, env, hasMasterKey)) {
          return json({ success: false, error: "Unauthorized" }, 403);
        }
        try {
          const deleted = await dbDeleteProduct(env, deleteId);
          if (!deleted) return json({ success: false, error: "Product not found" }, 404);
          return json({ success: true, deleted: true, id: deleteId });
        } catch (e) {
          console.error("Storage product delete failed:", e?.message || String(e));
          return json({ success: false, error: "Could not delete product" }, 503);
        }
      }

      if (path === "/api/products/delete" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session || !ADMIN_IDS.includes(session.userId)) {
          return json({ error: "Unauthorized" }, 403);
        }
        let body;
        try { body = await request.json(); } catch (_) { return json({ error: "Invalid JSON" }, 400); }
        const id = String(body?.id || "").trim();
        if (!id) return json({ error: "Product ID required" }, 400);

        try {
          const deleted = await dbDeleteProduct(env, id);
          if (!deleted) return json({ success: false, error: "Product not found" }, 404);
          return json({ success: true, deleted: true, id });
        } catch(e) {
          console.error("Storage product delete failed:", e?.message || String(e));
          return json({ success: false, error: "Could not delete product" }, 503);
        }
      }

      // Shortening the download-pass duration invalidates every stored pass, so
      // they are cleared and their owners are told to unlock a new one.
      if (path === "/api/admin/access/reset" && request.method === "POST") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        let body = {};
        try { body = await request.json(); } catch (_) { body = {}; }
        const param = name => url.searchParams.get(name);
        const boolParam = value => value === undefined ? undefined : /^(1|true|yes|on)$/i.test(String(value));
        const dryRun = boolParam(param("dry_run")) ?? (body?.dry_run !== false);
        const notify = boolParam(param("notify")) ?? (body?.notify === true);
        const discord = boolParam(param("discord")) ?? (body?.discord === true);
        try {
          const result = await resetDownloadAccess(env, { dryRun });
          result.access_duration_days = RESOURCE_ACCESS_DURATION_DAYS;
          result.label = RESOURCE_ACCESS_LABEL;
          if (notify && !dryRun && result.discord_ids.length) {
            result.notifications = await notifyAccessChange(env, {
              discordIds: result.discord_ids,
              dryRun: false,
              discord,
              adminId: ADMIN_IDS[0],
            });
          }
          return json({ success: true, ...result });
        } catch (error) {
          console.error("resetDownloadAccess failed:", error?.message || String(error));
          return json({ success: false, error: error?.message || "Access reset failed" }, 500);
        }
      }

      // Operations view of the role snapshot the bot publishes: how many ids are
      // stored, how old they are, and whether a given member is listed.
      if (path === "/api/admin/roles/snapshot" && request.method === "GET") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        const roleId = String(url.searchParams.get("role_id") || VERIFIED_ROLE_ID).trim();
        if (!isValidRoleId(roleId)) return json({ success: false, error: "Invalid role_id" }, 400);
        const probeId = String(url.searchParams.get("user_id") || "").trim();
        try {
          const roles = await readRoleSnapshotRoles(env);
          const entry = roles[roleId];
          const updatedAt = Number(entry && entry.updated_at) || 0;
          const ageMs = updatedAt ? Date.now() - updatedAt : null;
          const ids = entry && Array.isArray(entry.ids) ? entry.ids : [];
          return json({
            success: true,
            role_id: roleId,
            count: ids.length,
            updated_at: updatedAt || null,
            updated_at_iso: updatedAt ? new Date(updatedAt).toISOString() : null,
            updated_by: (entry && entry.updated_by) || null,
            age_seconds: ageMs === null ? null : Math.round(ageMs / 1000),
            stale: ageMs === null ? true : ageMs > ROLE_SNAPSHOT_STALE_MS,
            known_roles: Object.keys(roles),
            has_user: probeId ? ids.includes(probeId) : undefined,
          });
        } catch (error) {
          console.error("Role snapshot read failed:", error?.message || String(error));
          return json({ success: false, error: "Could not read role snapshot" }, 503);
        }
      }

      // Who is currently blocked, and the manual escape hatch back in.
      if (path === "/api/admin/role-revocations" && request.method === "GET") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        const probeId = String(url.searchParams.get("user_id") || "").trim();
        const limit = Math.min(Math.max(Number(url.searchParams.get("limit")) || 50, 1), 500);
        const reasonFilter = String(url.searchParams.get("reason") || "").trim();
        try {
          const users = await readRevocationUsers(env);
          const entries = Object.entries(users)
            .map(([id, entry]) => ({
              discord_id: id,
              revoked_at: Number(entry && entry.revoked_at) || 0,
              reason: (entry && entry.reason) || "manual",
              reason_label: REVOKE_REASON_LABELS[(entry && entry.reason) || "manual"] || (entry && entry.reason) || "manual",
              role_id: (entry && entry.role_id) || null,
              source: (entry && entry.source) || null,
              previous_reason: (entry && entry.previous_reason) || null,
            }))
            .filter(entry => !reasonFilter || entry.reason === reasonFilter)
            .sort((a, b) => b.revoked_at - a.revoked_at);
          return json({
            success: true,
            total: entries.length,
            counts_by_reason: entries.reduce((acc, entry) => {
              acc[entry.reason] = (acc[entry.reason] || 0) + 1;
              return acc;
            }, {}),
            has_user: probeId ? Object.prototype.hasOwnProperty.call(users, probeId) : undefined,
            user_entry: probeId ? (users[probeId] || null) : undefined,
            entries: entries.slice(0, limit),
          });
        } catch (error) {
          console.error("Role revocation read failed:", error?.message || String(error));
          return json({ success: false, error: "Could not read revocations" }, 503);
        }
      }

      if (path === "/api/admin/role-revocations/restore" && request.method === "POST") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON" }, 400); }
        const ids = cleanRoleIdList(body && body.discord_ids);
        if (!ids.length) return json({ success: false, error: "discord_ids required" }, 400);
        try {
          const result = await restoreUserAccess(env, ids, { force: true });
          const roleId = isValidRoleId(body && body.role_id) ? String(body.role_id) : VERIFIED_ROLE_ID;
          for (const id of result.restored) {
            queueSecurityEvent(env, ctx, "access", {
              level: "success",
              title: "Download access restored",
              description: "An admin removed the member from the revocation list.",
              action: "access-restored",
              user_id: id,
              access: "Restored by staff",
            });
          }
          return json({ success: true, restored: result.restored, kept: result.kept, role_id: roleId });
        } catch (error) {
          console.error("Role revocation restore failed:", error?.message || String(error));
          return json({ success: false, error: "Could not restore the member" }, 503);
        }
      }

      // Who really uploaded the anonymous resources. Admin-only, never cached and
      // never part of the public catalogue.
      if (path === "/api/admin/anonymous-uploads" && request.method === "GET") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!isAdminRequest(request, env, hasMasterKey)) {
          return json({ success: false, error: "Unauthorized" }, 403);
        }
        try {
          const registry = await readAnonymousUploads(env);
          const catalog = await dbReadProductCatalog(env).catch(() => []);
          const nameById = new Map(
            (Array.isArray(catalog) ? catalog : []).map(item => [String(item?.id || ""), String(item?.name || "")])
          );
          const entries = Object.entries(registry).map(([productId, entry]) => ({
            product_id: productId,
            product_name: String((entry && entry.product_name) || nameById.get(productId) || ""),
            uploader_id: String((entry && entry.uploader_id) || ""),
            uploader_name: String((entry && entry.uploader_name) || ""),
            uploader_avatar: String((entry && entry.uploader_avatar) || ""),
            source: String((entry && entry.source) || ""),
            recorded_at: (entry && entry.recorded_at) || null,
            still_published: nameById.has(productId),
          })).sort((a, b) => String(b.recorded_at || "").localeCompare(String(a.recorded_at || "")));
          return json(
            { success: true, total: entries.length, uploads: entries },
            200,
            { "Cache-Control": "no-store, private" }
          );
        } catch (error) {
          console.error("Anonymous upload registry read failed:", error?.message || String(error));
          return json({ success: false, error: "Could not read the anonymous upload registry" }, 503);
        }
      }

      // Re-send the access-change notification without touching stored passes.
      if (path === "/api/admin/access/notify" && request.method === "POST") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        let body = {};
        try { body = await request.json(); } catch (_) { body = {}; }
        const param = name => url.searchParams.get(name);
        const boolParam = value => value === undefined ? undefined : /^(1|true|yes|on)$/i.test(String(value));
        const dryRun = boolParam(param("dry_run")) ?? (body?.dry_run === true);
        const discord = boolParam(param("discord")) ?? (body?.discord === true);
        let discordIds = Array.isArray(body?.discord_ids) ? body.discord_ids : [];
        const queryIds = param("discord_ids");
        if (!discordIds.length && queryIds) {
          discordIds = String(queryIds).split(/[,\s]+/).filter(Boolean);
        }
        const limit = Math.min(Math.max(Number(param("limit") ?? body?.limit) || 0, 0), 100);
        if (!discordIds.length) {
          const listed = await env.STORAGE.list({ prefix: RESOURCE_ACCESS_PATH, limit: 1000 });
          discordIds = (listed?.objects || []).map(object => String(object.key).slice(RESOURCE_ACCESS_PATH.length));
        }
        if (limit) discordIds = discordIds.slice(0, limit);
        try {
          const report = await notifyAccessChange(env, { discordIds, dryRun, discord, adminId: ADMIN_IDS[0] });
          return json({ success: true, ...report });
        } catch (error) {
          console.error("notifyAccessChange failed:", error?.message || String(error));
          return json({ success: false, error: error?.message || "Notification failed" }, 500);
        }
      }

      // Diagnostic for the offer step of the access flow. It asks the provider for a
      // fresh locker link and echoes every intermediate value, so a user report can
      // be triaged without guessing. No claim is stored.
      if (path === "/api/admin/access/offer-test" && request.method === "POST") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        const claimId = crypto.randomUUID().replace(/-/g, "");
        const requested = String(url.searchParams.get("destination") || "").trim();
        let destination = new URL("/access", url.origin);
        if (requested.startsWith("/") && !requested.startsWith("//")) {
          const candidate = new URL(requested, url.origin);
          if (candidate.origin === url.origin) destination = candidate;
        }
        destination.searchParams.set("claim", claimId);
        try {
          const details = await requestAdMavenLocker(env, destination.toString(), `Zyrex ${RESOURCE_ACCESS_LABEL} Access`);
          return json({ success: true, ...details });
        } catch (error) {
          console.error("AdMaven diagnostic failed:", error?.message || String(error));
          return json({ success: false, error: error?.message || "AdMaven offer link creation failed" }, 502);
        }
      }

      // Reads back the reports written by /api/diagnostics/report. Without an id
      // it returns a compact list so a support conversation can start from the
      // newest report; with ?id= it returns the full payload.
      // Answers "why can't this member verify": which token the Worker holds, and the raw
      // status + Discord error code of every call the verification makes.
      if (path === "/api/admin/diagnostics/verify" && request.method === "GET") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        const probeId = String(url.searchParams.get("user_id") || "").trim();
        const candidates = discordTokenCandidates(env);
        const report = {
          success: true,
          config: {
            token_candidates: candidates.map(candidate => ({ source: candidate.name, length: candidate.token.length })),
            token_source: candidates.length ? candidates[0].name : "none",
            active_token: discordPreferredToken || null,
            guild_id: verifyGuildId(env),
            verify_role_id: verifyRoleId(env),
            unverified_role_id: unverifiedRoleId(env),
            worker_owns_verification: canVerifyLocally(env),
            vps_bot_api: VERIFY_BOT_API,
          },
          tokens: [],
          bot: {},
          probe_user_id: /^\d{15,25}$/.test(probeId) ? probeId : null,
          diagnosis: "",
        };

        // Probe every secret on its own so a rotated token is visible immediately.
        for (const candidate of candidates) {
          const probeIdentity = await discordRawGet(candidate.token, "/users/@me");
          const probeGuild = probeIdentity.ok ? await discordRawGet(candidate.token, `/guilds/${verifyGuildId(env)}`) : { ok: false, status: 0, body: null };
          const entry = {
            source: candidate.name,
            length: candidate.token.length,
            identity_status: probeIdentity.status,
            identity_ok: probeIdentity.ok,
            identity_reason: probeIdentity.reason || "",
            bot_id: (probeIdentity.body && probeIdentity.body.id) || null,
            bot_username: (probeIdentity.body && probeIdentity.body.username) || null,
            identity_error: (probeIdentity.body && probeIdentity.body.message) || null,
            guild_status: probeGuild.status,
            guild_ok: probeGuild.ok,
            guild_name: (probeGuild.body && probeGuild.body.name) || null,
            guild_error: (probeGuild.body && probeGuild.body.message) || null,
          };
          if (report.probe_user_id && probeIdentity.ok) {
            const probeMember = await discordRawGet(candidate.token, verifyRolePath(env, report.probe_user_id));
            const probeRoles = probeMember.body && Array.isArray(probeMember.body.roles) ? probeMember.body.roles.map(String) : [];
            entry.member_status = probeMember.status;
            entry.member_ok = probeMember.ok;
            entry.has_verify_role = probeRoles.includes(verifyRoleId(env));
          }
          report.tokens.push(entry);
        }
        const usableToken = report.tokens.find(entry => entry.identity_ok && entry.guild_ok) || null;

        const identity = await discordApiFetch(env, "/users/@me");
        report.bot.identity = {
          status: identity.status,
          ok: identity.ok,
          reason: identity.reason || "",
          id: (identity.body && identity.body.id) || null,
          username: (identity.body && identity.body.username) || null,
          error: (identity.body && (identity.body.message || String(identity.body.code || ""))) || null,
        };

        const guild = await discordApiFetch(env, `/guilds/${verifyGuildId(env)}`);
        report.bot.guild = {
          status: guild.status,
          ok: guild.ok,
          reason: guild.reason || "",
          name: (guild.body && guild.body.name) || null,
          error: (guild.body && (guild.body.message || String(guild.body.code || ""))) || null,
        };

        if (report.probe_user_id) {
          const member = await discordApiFetch(env, verifyRolePath(env, report.probe_user_id));
          const memberRoles = member.body && Array.isArray(member.body.roles) ? member.body.roles.map(String) : [];
          report.bot.member = {
            status: member.status,
            ok: member.ok,
            reason: member.reason || "",
            in_guild: member.ok,
            has_verify_role: memberRoles.includes(verifyRoleId(env)),
            error: (member.body && (member.body.message || String(member.body.code || ""))) || null,
          };
          report.record = await r2GetJSON(env, verifyRecordKey(report.probe_user_id), null).catch(() => null);
          report.role_queue = await readRoleQueueEntry(env, report.probe_user_id);
        }

        const identityFailed = !report.bot.identity.ok;
        const guildFailed = !report.bot.guild.ok;
        const memberCheck = report.bot.member || null;
        report.config.active_token = report.bot.identity.token_source || discordPreferredToken || null;
        if (!report.tokens.length) {
          report.diagnosis = "No bot token is configured on the Worker: add DISCORD_BOT_TOKEN (or SITE_LOG_BOT_TOKEN), otherwise every verification falls back to the VPS bot.";
        } else if (!usableToken) {
          const rejected = report.tokens.map(entry => `${entry.source}: HTTP ${entry.identity_status}`).join(", ");
          report.diagnosis = `None of the configured bot tokens is usable (${rejected}). Replace the dead secret with the bot's current token — an invalidated token always answers 401, permissions cannot fix it.`;
        } else if (usableToken.source !== "DISCORD_BOT_TOKEN") {
          report.diagnosis = `The Worker now authenticates with ${usableToken.source} (${usableToken.bot_username || usableToken.bot_id}) because DISCORD_BOT_TOKEN was rejected. Everything works; rotate DISCORD_BOT_TOKEN when convenient.`;
        } else if (identityFailed) {
          report.diagnosis = `Discord rejected GET /users/@me with HTTP ${report.bot.identity.status} (${report.bot.identity.reason || "unknown"}).`;
        } else if (report.bot.guild.status === 403) {
          report.diagnosis = `The bot is not a member of guild ${report.config.guild_id}.`;
        } else if (report.bot.guild.status === 404) {
          report.diagnosis = `Guild ${report.config.guild_id} is not visible to this bot (wrong GUILD_ID?).`;
        } else if (guildFailed) {
          report.diagnosis = `Discord rejected GET /guilds/${report.config.guild_id} with HTTP ${report.bot.guild.status}.`;
        } else if (memberCheck && memberCheck.status === 403) {
          report.diagnosis = `The bot cannot read or edit that member (HTTP 403, ${memberCheck.reason}). It needs Manage Roles and a role above the Verified role.`;
        } else if (memberCheck && memberCheck.status === 404) {
          report.diagnosis = "That member is not in the server, so verification correctly answers \"join first\".";
        } else if (memberCheck && memberCheck.ok) {
          report.diagnosis = memberCheck.has_verify_role
            ? "Everything works: the member is in the guild and already has the Verified role."
            : "Everything works: the bot can read the member and assign the Verified role.";
        } else {
          report.diagnosis = "Discord calls succeed. Pass ?user_id=<discord id> to test a specific member.";
        }

        return json(report, 200, { "Cache-Control": "no-store, private" });
      }

      if (path === "/api/admin/diagnostics/access" && (request.method === "GET" || request.method === "POST")) {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        if (!env.STORAGE) return json({ success: false, error: "Diagnostics storage is unavailable." }, 503);
        const wantedId = String(url.searchParams.get("id") || "").trim();
        const limit = Math.min(Math.max(Number(url.searchParams.get("limit")) || 10, 1), 50);
        try {
          const listed = await env.STORAGE.list({ prefix: "diagnostics/access/", limit: 1000 });
          const objects = (listed?.objects || []).sort((a, b) => String(b.key).localeCompare(String(a.key)));
          if (wantedId) {
            const match = objects.find(object => String(object.key).includes(wantedId));
            if (!match) return json({ success: false, error: "Report not found" }, 404);
            const report = await r2GetJSON(env, match.key, null);
            return json({ success: true, report });
          }
          const reports = [];
          for (const object of objects.slice(0, limit)) {
            const report = await r2GetJSON(env, object.key, null);
            if (!report) continue;
            reports.push({
              id: report.id,
              created_at: report.created_at,
              asn: report.network?.asn ?? null,
              as_organization: report.network?.as_organization ?? null,
              country: report.network?.country ?? null,
              probes: (report.probes || []).map(p => `${p.key}=${p.outcome}${Number.isFinite(p.ms) ? "(" + p.ms + "ms)" : ""}`).join(" "),
              verdict: report.verdict || "",
              symptom: report.symptom || "",
              discord_id: report.user?.discord_id || null,
              username: report.user?.username || report.user?.display_name || null,
              attempts: report.access?.attempts ?? null,
              completed: report.access?.completed ?? null,
              extensions: (report.extensions?.detected || []).join("|"),
              har_failed: report.har?.failed ?? null,
              user_agent: String(report.browser?.user_agent || "").slice(0, 90),
            });
          }
          return json({ success: true, count: reports.length, total_stored: objects.length, reports });
        } catch (error) {
          console.error("diagnostics listing failed:", error?.message || String(error));
          return json({ success: false, error: error?.message || "Could not read diagnostics" }, 500);
        }
      }

      // Download archive lookups: what did this member download and when, who
      // downloaded this resource, and the newest entries. Every record is also
      // addressable by its archive id.
      if (path === "/api/admin/downloads" && (request.method === "GET" || request.method === "POST")) {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        if (!env.STORAGE) return json({ success: false, error: "Archive storage is unavailable." }, 503);
        const param = name => url.searchParams.get(name);
        const limit = Math.min(Math.max(Number(param("limit")) || 25, 1), 200);
        const offset = Math.max(Number(param("offset")) || 0, 0);
        try {
          const recordId = String(param("id") || "").trim();
          if (recordId) {
            if (!DL_RECORD_ID_PATTERN.test(recordId)) return json({ success: false, error: "Invalid archive id" }, 400);
            const pointer = await r2GetJSON(env, DL_ARCHIVE.ID_PREFIX + recordId + ".json", null);
            if (!pointer?.key) return json({ success: false, error: "Archive record not found" }, 404);
            const record = await r2GetJSON(env, pointer.key, null);
            if (!record) return json({ success: false, error: "Archive record not found" }, 404);
            return json({ success: true, record });
          }

          const userId = String(param("user_id") || "").trim();
          if (userId) {
            if (!/^\d{5,25}$/.test(userId)) return json({ success: false, error: "Invalid user id" }, 400);
            const [entries, directory] = await Promise.all([
              r2GetJSON(env, DL_ARCHIVE.USER_INDEX_PREFIX + userId + ".json", []),
              r2GetJSON(env, DL_ARCHIVE.USERS, {}),
            ]);
            const rows = Array.isArray(entries) ? entries : [];
            const store = directory && typeof directory === "object" && !Array.isArray(directory) ? directory : {};
            return json({
              success: true,
              user_id: userId,
              member: store[userId] || null,
              total: rows.length,
              entries: rows.slice(offset, offset + limit),
            });
          }

          const productId = String(param("product_id") || "").trim();
          if (productId) {
            const entries = await r2GetJSON(env, DL_ARCHIVE.PRODUCT_INDEX_PREFIX + productId + ".json", []);
            const rows = Array.isArray(entries) ? entries : [];
            return json({ success: true, product_id: productId, total: rows.length, entries: rows.slice(offset, offset + limit) });
          }

          if (url.searchParams.has("users")) {
            const directory = await r2GetJSON(env, DL_ARCHIVE.USERS, {});
            const store = directory && typeof directory === "object" && !Array.isArray(directory) ? directory : {};
            const rows = Object.entries(store).map(([id, info]) => ({
              user_id: id,
              count: Number(info?.count) || 0,
              first_at: info?.first_at || "",
              last_at: info?.last_at || "",
              username: info?.username || "",
              display_name: info?.display_name || "",
              user_avatar: info?.user_avatar || "",
            })).sort((a, b) => b.count - a.count || String(b.last_at).localeCompare(String(a.last_at)));
            const query = String(param("q") || "").trim().toLowerCase();
            const matched = query
              ? rows.filter(row => `${row.username} ${row.display_name} ${row.user_id}`.toLowerCase().includes(query))
              : rows;
            return json({
              success: true,
              total_members: rows.length,
              returned: Math.max(0, Math.min(matched.length - offset, limit)),
              members: matched.slice(offset, offset + limit),
            });
          }

          const recent = await r2GetJSON(env, DL_ARCHIVE.RECENT, []);
          const rows = Array.isArray(recent) ? recent : [];
          return json({ success: true, total: rows.length, entries: rows.slice(offset, offset + limit) });
        } catch (error) {
          console.error("download archive lookup failed:", error?.message || String(error));
          return json({ success: false, error: error?.message || "Archive lookup failed" }, 500);
        }
      }

      // Lightweight cache-invalidation token for the product catalog. Clients key
      // their stored catalog on it so an anonymity change discards every cache
      // that could still hold a hidden uploader identity.
      if (path === "/api/privacy-epoch" && (request.method === "GET" || request.method === "HEAD")) {
        const epoch = await readPrivacyEpoch(env);
        return json({ success: true, epoch }, 200, {
          "Cache-Control": "public, max-age=30, s-maxage=30",
        });
      }

      // Repair legacy rows whose creator photo is missing or points at an
      // expired social CDN link. Authorized exactly like product editing, since
      // it rewrites the same catalog. Options come from the query string as well
      // as the body, because the edge gate can consume a forwarded body.
      if (path === "/api/admin/repair-creator-avatars" && request.method === "POST") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        let body = {};
        try { body = await request.json(); } catch (_) { body = {}; }
        if (!body || typeof body !== "object" || Array.isArray(body)) body = {};
        const param = name => {
          const value = url.searchParams.get(name);
          return value === null ? undefined : value;
        };
        const boolParam = value => value === undefined ? undefined : /^(1|true|yes|on)$/i.test(String(value));
        const scope = String(param("scope") ?? body?.scope ?? "all").trim().toLowerCase();
        try {
          const options = {
            dryRun: boolParam(param("dry_run")) ?? (body?.dry_run !== false),
            rescrape: boolParam(param("rescrape")) ?? (body?.rescrape === true),
            limit: param("limit") ?? body?.limit,
            id: param("id") ?? body?.id,
          };
          const result = { success: true, scope };
          if (scope === "creator" || scope === "all") {
            result.creator = await repairCreatorAvatars(env, options);
          }
          if (scope === "uploader" || scope === "all") {
            result.uploader = await repairUploaderAvatars(env, options);
          }
          if (scope === "privacy" || scope === "all") {
            result.privacy = await repairAnonymousProducts(env, options);
          }
          if (scope === "text" || scope === "all") {
            result.text = await repairCatalogText(env, options);
          }
          if (!options.dryRun && result.privacy?.repaired > 0) await bumpPrivacyEpoch(env);
          return json(result);
        } catch (error) {
          console.error("repair-creator-avatars failed:", error?.message || String(error));
          return json({ success: false, error: error?.message || "Repair failed" }, 500);
        }
      }

      // EDIT / UPDATE PRODUCT
      const isProductUpdateRoute = (
        (path === "/api/products/edit" || path.startsWith("/api/products/edit/")) ||
        (/^\/api\/products\/[^/]+$/.test(path) && !RESERVED_PRODUCT_ROUTES.has(path.slice("/api/products/".length)))
      );

      if (isProductUpdateRoute &&
          (request.method === "POST" || request.method === "PUT" || request.method === "OPTIONS")) {
        if (request.method === "OPTIONS") {
          return new Response(null, { status: 204, headers: corsHeaders });
        }

        const session = parseSession(request.headers.get("Cookie"), request);
        const canEditProducts = hasMasterKey || await sessionCanUpload(session, env);
        if (!canEditProducts) return json({ error: "Unauthorized" }, 403);

        let productId = path.replace("/api/products/edit/", "").replace("/api/products/edit", "").replace("/api/products/", "").trim();
        let payload;
        try { payload = await request.json(); } catch(_) { return json({ error: "Invalid JSON" }, 400); }
        if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
          return json({ error: "Invalid product data" }, 400);
        }
        if (!productId && payload.id) productId = payload.id;
        if (!productId) return json({ error: "Product ID required" }, 400);

        // Attribution is staff-only; everyone else may edit the details but not who the
        // resource belongs to.
        if (!canSetUploaderAttribution()) {
          applyUploaderAttributionRules(payload, session);
        }

        if (payload.thumbnail && typeof payload.thumbnail === 'string' && !payload.thumbnail.includes("thumbnail.zyrexediting.xyz")) {
          try {
            const cdnThumb = await storeAndProxyImage(env, payload.thumbnail);
            if (cdnThumb && cdnThumb.includes("thumbnail.zyrexediting.xyz")) {
              payload.thumbnail = cdnThumb;
            }
          } catch(e) {}
        }
        if (payload.creator_avatar && typeof payload.creator_avatar === 'string' &&
            !isCdnAvatarUrl(payload.creator_avatar) && /^https?:\/\//i.test(payload.creator_avatar)) {
          try {
            const cdnAvatar = await storeAndProxyImage(env, payload.creator_avatar);
            if (isCdnAvatarUrl(cdnAvatar)) payload.creator_avatar = cdnAvatar;
          } catch(e) {}
        }

        try {
          const existing = await dbGetProduct(env, productId);
          if (!existing) return json({ success: false, error: "Product not found" }, 404);

          // Uploaders used to be able to rewrite any product, including its download link.
          if (!isAdminRequest(request, env, hasMasterKey)) {
            const owners = [existing.uploader_id, existing.author_id, existing.submitter_id, existing.credited_uploader_id]
              .filter(Boolean).map(String);
            if (!owners.includes(String((session && session.userId) || ""))) {
              return json({ success: false, error: "You can only edit your own leaks." }, 403);
            }
          }

          // Preserve submitter identity on existing product if not already set
          if (!existing.submitter_id && existing.uploader_id) {
            existing.submitter_id = existing.uploader_id;
            existing.submitter_name = existing.uploader_name;
            existing.submitter_avatar = existing.uploader_avatar;
          }

          const merged = { ...existing, ...payload, id: productId };

          // Marking an existing resource anonymous must erase the stored uploader
          // identity, otherwise an old cache or mirror can still reveal it.
          if (merged.is_anonymous === true) {
            await scrubAnonymousProduct(env, merged);
          } else {
            if (Boolean(existing.is_anonymous) !== Boolean(merged.is_anonymous)) {
              await bumpPrivacyEpoch(env);
            }
            const targetCreditId = typeof payload.credited_uploader_id === "string"
              ? payload.credited_uploader_id.trim()
              : (payload.uploader_id ? String(payload.uploader_id).trim() : (existing.credited_uploader_id ? String(existing.credited_uploader_id).trim() : ""));

            if (targetCreditId && /^\d{17,20}$/.test(targetCreditId)) {
              const targetCreditName = (payload.credited_uploader_name || payload.uploader_name || existing.credited_uploader_name || "").trim();
              const targetCreditAvatar = (payload.credited_uploader_avatar || payload.uploader_avatar || existing.credited_uploader_avatar || "").trim();
              merged.credited_uploader_id = targetCreditId;
              merged.credited_uploader_name = targetCreditName;
              merged.credited_uploader_avatar = targetCreditAvatar;
              merged.uploader_id = targetCreditId;
              merged.author_id = targetCreditId;
              if (targetCreditName) {
                merged.uploader_name = targetCreditName;
                merged.author_name = targetCreditName;
              }
              if (targetCreditAvatar) {
                merged.uploader_avatar = targetCreditAvatar;
                merged.author_avatar = targetCreditAvatar;
              }
              delete merged.uploader_handle;
              delete merged.uploader_profile_url;
            } else if (payload.credited_uploader_id === "" || payload.credited_uploader_id === null) {
              merged.credited_uploader_id = "";
              merged.credited_uploader_name = "";
              merged.credited_uploader_avatar = "";
              const revertId = existing.submitter_id || (session && session.userId) || "";
              const revertName = existing.submitter_name || (session && (session.displayName || session.username)) || "";
              const revertAvatar = existing.submitter_avatar || (session && session.avatar) || "";
              if (revertId) {
                merged.uploader_id = revertId;
                merged.author_id = revertId;
              }
              if (revertName) {
                merged.uploader_name = revertName;
                merged.author_name = revertName;
              }
              if (revertAvatar) {
                merged.uploader_avatar = revertAvatar;
                merged.author_avatar = revertAvatar;
              }
              delete merged.uploader_handle;
              delete merged.uploader_profile_url;
            }
          }
          const updated = await dbUpdateProduct(env, productId, merged);
          if (!updated) return json({ success: false, error: "Product not found" }, 404);
          if (updated.creator_account_id) await saveCreatorProfile(env, updated);
          return json({ success: true, product: updated, id: productId });
        } catch(e) {
          console.error("Storage product update failed:", e?.message || String(e));
          return json({ success: false, error: "Could not update product" }, 503);
        }
      }

      if (path === "/api/scrape" || path === "/api/payhip/scrape" || path === "/api/patreon/scrape" || path === "/api/boosty/scrape") {
        const scrapeUrl = url.searchParams.get("url");
        if (!scrapeUrl) {
          return json({ success: false, error: "URL parameter required" }, 400);
        }
        const validatedScrapeUrl = normalizeScrapeUrl(scrapeUrl);
        const expectedProvider = path === "/api/payhip/scrape" ? "payhip" : path === "/api/patreon/scrape" ? "patreon" : path === "/api/boosty/scrape" ? "boosty" : "";
        if (!validatedScrapeUrl || (expectedProvider && validatedScrapeUrl.provider !== expectedProvider)) {
          return json({ success: false, error: "Invalid URL for scraper endpoint" }, 400);
        }
        const parsed = await scrapeProductWithScrapin(validatedScrapeUrl.url, env);
        if (parsed.success && parsed.image && !parsed.image.includes("thumbnail.zyrexediting.xyz")) {
          const hash = await hashImageUrl(parsed.image);
          const ext = (parsed.image.split('.').pop()?.split('?')[0] || 'jpg').toLowerCase();
          ctx.waitUntil(cacheThumbnail(env, parsed.image, `${hash}.${ext}`));
          parsed.cdn_thumbnail = `https://thumbnail.zyrexediting.xyz/${hash}.${ext}`;
        }
        return json(parsed, parsed.success ? 200 : 502);
      }

      // The destination handed to the offer provider. AdMaven only sends a member
      // here once they have completed an offer (or skipped it outright), so landing
      // on this route is what marks the claim complete. It grants nothing by itself:
      // the claim endpoint still requires the matching Discord session.
      if (path === "/api/access/unlock") {
        const claim = String(url.searchParams.get("claim") || "").trim();
        const back = new URL("/access", url.origin);
        const requestedReturnTo = String(url.searchParams.get("return_to") || "");
        if (requestedReturnTo.startsWith("/") && !requestedReturnTo.startsWith("//")) {
          try {
            const candidate = new URL(requestedReturnTo, url.origin);
            if (candidate.origin === url.origin) back.searchParams.set("return_to", candidate.pathname + candidate.search);
          } catch (_) {}
        }
        if (!/^[a-f0-9]{32}$/i.test(claim)) {
          back.searchParams.set("unlock", "invalid");
          return redirect(back.toString());
        }
        back.searchParams.set("claim", claim);

        const grant = await getAccessGrant(env, claim);
        if (!grant || grant.purpose !== "access" || Number(grant.expires_at) <= Date.now()) {
          back.searchParams.set("unlock", "expired");
          return redirect(back.toString());
        }
        // Idempotent: a refresh or a second landing must not rewrite the completion
        // time, which is what the pass length is measured from.
        if (!grant.completed_at) {
          grant.completed_at = Date.now();
          grant.completed_ip = getClientIp(request);
          grant.completed_via = "offer_return";
          await env.STORAGE.put("unlock/grants/" + claim, JSON.stringify(grant), {
            httpMetadata: { contentType: "application/json" },
          });
          await recordUserGrant(env, grant.discord_id, {
            grant_id: claim,
            created_at: grant.created_at,
            completed_at: grant.completed_at,
            completed_via: "offer_return",
          });
          queueSecurityEvent(env, ctx, "access", {
            level: "success",
            title: "Access offer completed",
            description: "The offer provider returned the member; the claim can now be turned into a download pass.",
            action: "access-offer-completed",
            user_id: grant.discord_id,
            ip: grant.completed_ip,
            access: `Grant \`${claim.slice(0, 12)}\``,
          });
        }
        back.searchParams.set("unlock", "ok");
        return redirect(back.toString());
      }

      if (path === "/api/downloads/validate") {
        const token = url.searchParams.get("token");
        if (!token) return json({ error: "Token required" }, 400);
        const data = await decodeToken(token, env);
        if (!data) return json({ success: false, error: "Invalid or expired token" }, 404);
        if (await isRevoked(env, data.discord_id) === true) {
          return json({ success: false, code: "ACCESS_REVOKED", error: ACCESS_REVOKED_MESSAGE }, 403);
        }
        if (!(await hasValidDownloadPass(env, data))) {
          const accessRequired = data.download_access === true;
          return json({
            success: false,
            code: accessRequired ? "ACCESS_REQUIRED" : "AD_REQUIRED",
            error: accessRequired
              ? `Your ${RESOURCE_ACCESS_LABEL.toLowerCase()} download access has expired. Visit the Access page to unlock downloads again.`
              : "Complete one free offer to unlock this download. Skipping or blocking the offer page will not grant access.",
          }, 403);
        }
        // Check if token was already used (skip R2 on peek for speed — download endpoint enforces)
        const fingerprint = hashToken(token);
        if (await checkTokenUsed(env, fingerprint)) return json({ success: false, error: "This token has already been used. Generate a new download token.", code: "TOKEN_USED" }, 403);
        const hasAdFree = data.discord_id ? await checkAdFreeRole(data.discord_id, env) : false;
        return json({
          success: true,
          token_id: fingerprint,
          product_id: data.product_id,
          file_path: data.file_path,
          discord_id: data.discord_id,
          ad_free: hasAdFree,
          selected_files: Array.isArray(data.selected_files) ? data.selected_files : [],
          expires_in: Math.max(0, Math.floor((data.exp - Date.now()) / 1000)),
        });
      }

      if (path === "/api/access/status") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ logged_in: false, active: false }, 200);
        if (await isRevoked(env, session.userId) === true) {
          return json({
            success: true,
            logged_in: true,
            username: session.username,
            discord_id: session.userId,
            verified: false,
            revoked: true,
            ad_free: false,
            active: false,
            expires_at: null,
            duration_days: RESOURCE_ACCESS_DURATION_DAYS,
          });
        }
        const verified = await checkVerifiedRole(session.userId, env);
        if (verified === null) return json({ success: false, error: "Could not verify your Discord role right now." }, 503);
        const adFree = await checkAdFreeRole(session.userId, env);
        const access = await getDownloadAccess(env, session.userId);
        const expiresAt = Number(access?.expires_at) || 0;
        const active = expiresAt > Date.now();
        return json({
          success: true,
          logged_in: true,
          username: session.username,
          discord_id: session.userId,
          verified,
          ad_free: adFree,
          active: adFree || active,
          expires_at: active ? expiresAt : null,
          duration_days: RESOURCE_ACCESS_DURATION_DAYS,
        });
      }

      if (path === "/api/access/start") {
        if (request.method !== "POST") return json({ success: false, error: "Method not allowed" }, 405);
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Sign in with Discord to continue.", code: "NOT_LOGGED_IN" }, 401);
        if (await isRevoked(env, session.userId) === true) {
          return json({ success: false, code: "ACCESS_REVOKED", error: ACCESS_REVOKED_MESSAGE }, 403);
        }
        const verified = await checkVerifiedRole(session.userId, env);
        if (verified === null) return json({ success: false, error: "Could not verify your Discord role right now. Please retry." }, 503);
        if (!verified) return json({ success: false, error: "Join the Zyrex Discord and verify your account before unlocking download access.", code: "NOT_VERIFIED" }, 403);
        if (!env.STORAGE) return json({ success: false, error: "Access storage is temporarily unavailable." }, 503);
        if (await checkAdFreeRole(session.userId, env)) {
          queueSecurityEvent(env, ctx, "access", {
            level: "info",
            title: "Access already granted (ad-free role)",
            action: "access-already-active",
            user_id: session.userId,
            user_name: session.displayName || session.username,
            access: "Ad-free role • no offer required",
            ip: getClientIp(request),
          });
          return json({ success: true, active: true, ad_free: true, expires_at: null });
        }
        const activeAccess = await getDownloadAccess(env, session.userId);
        if (Number(activeAccess?.expires_at) > Date.now()) {
          queueSecurityEvent(env, ctx, "access", {
            level: "info",
            title: "Access already active",
            action: "access-already-active",
            user_id: session.userId,
            user_name: session.displayName || session.username,
            access: "Stored download pass",
            expires_at: Number(activeAccess.expires_at),
            ip: getClientIp(request),
          });
          return json({ success: true, active: true, expires_at: Number(activeAccess.expires_at) });
        }

        const clientIp = getClientIp(request);
        if (!clientIp) return json({ success: false, error: "Could not verify the access session. Please try again." }, 503);
        const grantId = crypto.randomUUID().replace(/-/g, "");
        const now = Date.now();
        const grant = {
          purpose: "access",
          discord_id: session.userId,
          ip: clientIp,
          created_at: now,
          expires_at: now + 30 * 60 * 1000,
          completed_at: 0,
        };
        await env.STORAGE.put("unlock/grants/" + grantId, JSON.stringify(grant), {
          httpMetadata: { contentType: "application/json" },
        });
        await recordUserGrant(env, session.userId, { grant_id: grantId, created_at: now, ip: clientIp, completed_at: 0 });

        let returnTo = "";
        try {
          const body = await request.json();
          const requestedReturnTo = String(body?.return_to || "");
          if (requestedReturnTo.startsWith("/") && !requestedReturnTo.startsWith("//")) {
            const candidate = new URL(requestedReturnTo, url.origin);
            if (candidate.origin === url.origin) returnTo = candidate.pathname + candidate.search + candidate.hash;
          }
        } catch (_) {}
        // The provider redirects the member here when the offer is finished, and this
        // route is the only thing that can mark the claim complete.
        const destination = new URL("/api/access/unlock", url.origin);
        destination.searchParams.set("claim", grantId);
        if (returnTo) destination.searchParams.set("return_to", returnTo);
        try {
          const adUrl = await createAdMavenLockerLink(env, destination.toString(), `Zyrex ${RESOURCE_ACCESS_LABEL} Access`);
          queueSecurityEvent(env, ctx, "access", {
            level: "info",
            title: "Access offer started",
            description: "An offer link was created for the member; access is granted only after the provider returns.",
            action: "access-offer-started",
            user_id: session.userId,
            user_name: session.displayName || session.username,
            ip: clientIp,
            access: `Grant \`${grantId.slice(0, 12)}\``,
          });
          return json({ success: true, ad_url: adUrl, expires_in: 1800 });
        } catch (error) {
          await env.STORAGE.delete("unlock/grants/" + grantId).catch(() => {});
          console.error("AdMaven offer link creation failed:", error.message);
          queueSecurityEvent(env, ctx, "access", {
            level: "warn",
            title: "Access offer link failed",
            description: String(error?.message || error),
            action: "access-offer-failed",
            user_id: session.userId,
            user_name: session.displayName || session.username,
            ip: clientIp,
          });
          await recordTelemetryEvent(env, {
            subsystem: "shortener_gateway",
            title: "Ad offer link creation failed",
            message: String(error?.message || error).slice(0, 300),
            type: "admaven_link_creation_error",
            source: "api-worker",
          }).catch(() => {});
          return json({ success: false, error: "Could not prepare the offer link. Please try again shortly." }, 503);
        }
      }

      if (path === "/api/access/claim") {
        if (request.method !== "POST") return json({ success: false, error: "Method not allowed" }, 405);
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Sign in with Discord to claim access.", code: "NOT_LOGGED_IN" }, 401);
        if (await isRevoked(env, session.userId) === true) {
          queueSecurityEvent(env, ctx, "access", {
            level: "alert",
            title: "Access claim blocked (revoked)",
            description: ACCESS_REVOKED_MESSAGE,
            action: "access-claim-revoked",
            user_id: session.userId,
            user_name: session.displayName || session.username,
            ip: getClientIp(request),
          });
          return json({ success: false, code: "ACCESS_REVOKED", error: ACCESS_REVOKED_MESSAGE }, 403);
        }
        const verified = await checkVerifiedRole(session.userId, env);
        if (verified === null) return json({ success: false, error: "Could not verify your Discord role right now. Please retry." }, 503);
        if (!verified) {
          queueSecurityEvent(env, ctx, "access", {
            level: "warn",
            title: "Access claim refused (not verified)",
            description: "The member tried to claim download access without the verified role.",
            action: "access-claim-not-verified",
            user_id: session.userId,
            user_name: session.displayName || session.username,
            ip: getClientIp(request),
          });
          return json({ success: false, error: "Your Discord account must be verified before claiming download access.", code: "NOT_VERIFIED" }, 403);
        }

        let body;
        try { body = await request.json(); } catch { return json({ success: false, error: "Invalid claim request." }, 400); }
        const grantId = String(body?.grant_id || "");
        if (!/^[a-f0-9]{32}$/i.test(grantId)) return json({ success: false, error: "Invalid access claim." }, 400);
        const grant = await getAccessGrant(env, grantId);
        if (!grant || grant.purpose !== "access" || grant.discord_id !== session.userId) {
          queueSecurityEvent(env, ctx, "access", {
            level: "alert",
            title: "Access claim rejected",
            description: "A member tried to claim another account's access grant.",
            action: "access-claim-mismatch",
            user_id: session.userId,
            user_name: session.displayName || session.username,
            ip: getClientIp(request),
            reason: grant ? "Grant belongs to a different Discord account" : "Grant not found",
          });
          return json({ success: false, error: "This access claim does not belong to your Discord account." }, 403);
        }
        if (!grant.completed_at || Number(grant.expires_at) <= Date.now()) {
          return json({
            success: false,
            code: "OFFER_INCOMPLETE",
            error: "We have not seen the offer come back as completed yet. Finish the offer page and retry, or start a new one.",
          }, 409);
        }

        const expiresAt = Number(grant.completed_at) + RESOURCE_ACCESS_DURATION_MS;
        if (expiresAt <= Date.now()) return json({ success: false, error: "This access claim has expired. Please start again." }, 410);
        const access = {
          discord_id: session.userId,
          granted_at: Number(grant.completed_at),
          expires_at: expiresAt,
          source: "admaven",
        };
        await env.STORAGE.put("download-access/" + session.userId, JSON.stringify(access), {
          httpMetadata: { contentType: "application/json" },
        });
        grant.claimed_at = Date.now();
        await env.STORAGE.put("unlock/grants/" + grantId, JSON.stringify(grant), {
          httpMetadata: { contentType: "application/json" },
        });
        await recordUserGrant(env, session.userId, {
          grant_id: grantId,
          completed_at: grant.completed_at,
          claimed_at: grant.claimed_at,
        });
        queueSecurityEvent(env, ctx, "access", {
          level: "success",
          title: "Download access granted",
          description: "The completed offer was turned into a download pass.",
          action: "access-granted",
          user_id: session.userId,
          user_name: session.displayName || session.username,
          ip: getClientIp(request),
          access: `Download pass • ${RESOURCE_ACCESS_DURATION_DAYS} days`,
          expires_at: expiresAt,
        });
        return json({ success: true, active: true, expires_at: expiresAt });
      }

      if (path === "/api/downloads/check-access") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ can_download: false, reason: "not_logged_in" });
        if (await isRevoked(env, session.userId) === true) {
          return json({
            can_download: false,
            reason: "revoked",
            revoked: true,
            ad_free: false,
            access_granted: false,
            access_expires_at: null,
            duration_days: RESOURCE_ACCESS_DURATION_DAYS,
            discord_id: session.userId,
            username: session.username,
          });
        }
        const hasAdFree = await checkAdFreeRole(session.userId, env);
        const access = await getDownloadAccess(env, session.userId);
        const accessExpiresAt = Number(access?.expires_at) || 0;
        const hasPass = accessExpiresAt > Date.now();
        // A stored pass (or ad-free access) is proof that verification already
        // happened, so a role-API hiccup can never turn this endpoint into a 503.
        const verified = (hasPass || hasAdFree) ? true : await checkVerifiedRole(session.userId, env);
        const canDownload = verified === true;
        return json({
          can_download: canDownload,
          reason: canDownload ? "ok" : verified === null ? "role_check_unavailable" : "not_verified",
          ad_free: hasAdFree,
          access_granted: hasPass,
          access_expires_at: hasPass ? accessExpiresAt : null,
          duration_days: RESOURCE_ACCESS_DURATION_DAYS,
          discord_id: session.userId,
          username: session.username,
        }, 200);
      }

      if (path.startsWith("/api/downloads/request-token/")) {
        const shouldRedirect = url.searchParams.get("redirect") === "1";
        const returnTo = url.searchParams.get("return_to") || "/download";
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) {
          if (shouldRedirect) return redirect("/api/login?redirect=" + encodeURIComponent(returnTo));
          return json({ error: "Not logged in" }, 401);
        }
        
        // Verified role gate. A member holding a download pass or ad-free access has
        // already proven verification, so the role APIs are never consulted for them.
        const isAdFree = await checkAdFreeRole(session.userId, env);
        const access = isAdFree ? null : await getDownloadAccess(env, session.userId);
        const hasActiveAccess = Number(access?.expires_at) > Date.now();
        if (!isAdFree && !hasActiveAccess) {
          const isVerified = await checkVerifiedRole(session.userId, env);
          if (isVerified === null) {
            queueSecurityEvent(env, ctx, "access", {
              level: "warn",
              title: "Download link refused (role check unavailable)",
              description: "The verified role could not be read, so the download link was not issued.",
              action: "token-role-check-unavailable",
              user_id: session.userId,
              user_name: session.displayName || session.username,
              ip: getClientIp(request),
            });
            return json({ success: false, error: "We could not verify your Discord role right now. Please retry in a moment.", code: "ROLE_CHECK_UNAVAILABLE" }, 503);
          }
          if (!isVerified) {
            queueSecurityEvent(env, ctx, "access", {
              level: "warn",
              title: "Download link refused (not verified)",
              description: "The member does not hold the verified role.",
              action: "token-not-verified",
              user_id: session.userId,
              user_name: session.displayName || session.username,
              ip: getClientIp(request),
            });
            if (shouldRedirect) return redirect("/leak?id=" + encodeURIComponent(path.split("/api/downloads/request-token/")[1] || ""));
            return json({ error: "Verification required. You need the Verified role in our Discord server to download.", code: "NOT_VERIFIED" }, 403);
          }
        }
        
        const productId = path.split("/api/downloads/request-token/")[1];
        if (!productId) return json({ error: "Product ID required" }, 400);

        if (!isAdFree && !hasActiveAccess) {
          queueSecurityEvent(env, ctx, "access", {
            level: "warn",
            title: "Download link refused (no access pass)",
            description: "The member is verified but has no active download pass.",
            action: "token-access-required",
            user_id: session.userId,
            user_name: session.displayName || session.username,
            resource_id: productId,
            ip: getClientIp(request),
          });
          if (shouldRedirect) return redirect("/access?return_to=" + encodeURIComponent(returnTo));
          return json({
            success: false,
            code: "ACCESS_REQUIRED",
            error: `Unlock ${RESOURCE_ACCESS_LABEL.toLowerCase()} download access by completing one free offer on the Access page.`,
          }, 403);
        }
        
        // 15-Second Download Link Rate Limiter per User & Preset
        const dlRateKey = `dl_cd:${session.userId}:${productId}`;
        const nowMs = Date.now();
        const lastGenTime = downloadCooldownMap.get(dlRateKey);
        let retryData = null;
        const retryToken = url.searchParams.get("retry_token");
        if (retryToken) {
          const decodedRetry = await decodeToken(retryToken, env);
          if (decodedRetry && String(decodedRetry.discord_id) === String(session.userId) &&
              String(decodedRetry.product_id) === String(productId) &&
              Number(decodedRetry.retry_count || 0) < 3 &&
              await checkTokenUsed(env, hashToken(retryToken))) {
            retryData = decodedRetry;
          }
        }
        if (lastGenTime && (nowMs - lastGenTime < 15000) && !retryData) {
          const remainingSec = Math.ceil((15000 - (nowMs - lastGenTime)) / 1000);
          return json({
            success: false,
            error: `Please wait ${remainingSec} seconds before generating another download link for this preset.`,
            cooldown: remainingSec
          }, 429);
        }
        if (!retryData) downloadCooldownMap.set(dlRateKey, nowMs);
        
        let r2Prefix = "";
        let productHint = null;
        const selectedFiles = getRequestedFileSet(url);
        try {
          const hintPath = url.searchParams.get("file_path");
          productHint = await fetchProductHint(productId, session, env);
          if (!productHint && !hintPath) {
            return json({ success: false, error: "Leak not found.", code: "RESOURCE_NOT_FOUND" }, 404);
          }
          r2Prefix = await resolveProductionPrefix(env, productId, hintPath, productHint);
          
          if (!r2Prefix) {
            // Fallback: use hint path or product ID directly
            r2Prefix = normalizeR2Prefix(hintPath || productHint?.file_path || productId);
          }
        } catch (e) {
          console.error("Storage token prefix search warning:", e.message);
          r2Prefix = normalizeR2Prefix(url.searchParams.get("file_path") || productId);
        }
        
        // The pass is checked again when the download token is validated and used.
        const token = await encodeToken({
          discord_id: session.userId,
          product_id: productId,
          file_path: r2Prefix,
          selected_files: selectedFiles ? Array.from(selectedFiles) : [],
          retry_count: retryData ? Number(retryData.retry_count || 0) + 1 : 0,
          ad_required: false,
          download_access: !isAdFree,
          used: false,
        }, env);

        // The packer runs while the visitor is still on the landing page, so the download
        // itself is served from the R2 cache instead of waiting on the VPS.
        warmArchiveCache(env, ctx, {
          productId,
          r2Prefix,
          title: productHint && productHint.name,
          discordId: session.userId,
        }).catch(() => false);

        const adUrl = buildTokenLandingUrl(
          token,
          isAdFree ? "ad-free" : "access",
          url.searchParams.get("lang"),
          url.searchParams.get("theme"),
        );

        queueSecurityEvent(env, ctx, "access", {
          level: "info",
          title: "Download link issued",
          description: isAdFree
            ? "Issued with the ad-free role; no offer or pass was needed."
            : "Issued against an active download pass.",
          action: "token-issued",
          user_id: session.userId,
          user_name: session.displayName || session.username,
          resource_id: productId,
          resource_name: productHint && productHint.name,
          ip: getClientIp(request),
          access: isAdFree ? "Ad-free role" : "Download pass",
          expires_at: hasActiveAccess ? Number(access?.expires_at) : undefined,
        });

        if (shouldRedirect) {
          return redirect(adUrl);
        }
        
        return json({
          success: true,
          ad_url: adUrl,
          short_url: adUrl,
          url: adUrl,
          provider: isAdFree ? "direct" : "access",
          ad_free: isAdFree,
          access_granted: hasActiveAccess,
          expires_in: TOKEN_EXPIRY,
          file_path: r2Prefix,
        });
      }

      if (path === "/api/presets/stats") {
        const id = url.searchParams.get("id");
        if (!id) return json({ success: false, error: "id parameter required" }, 400);

        // Resource pages request increment_view=1 when a new visit should count.
        const shouldIncrementView = ["1", "true"].includes(String(url.searchParams.get("increment_view") || "").toLowerCase());
        const statsData = shouldIncrementView
          ? await dbIncrementView(env, id)
          : await dbGetPresetStats(env, id);
        const downloadData = await dbGetDownloadCounts(env);
        return json({
          success: true,
          id,
          downloads: downloadData.counts?.[id] ?? statsData.downloads ?? 0,
          views: statsData.views || 0,
          likes: statsData.likes || 0,
        });
      }

      if (path === "/api/presets/views" || path === "/api/presets/view") {
        try {
          let presetId = url.searchParams.get("id") || url.searchParams.get("preset_id");
          if (!presetId && request.method === "POST") {
            try {
              const body = await request.clone().json();
              presetId = body.id || body.preset_id;
            } catch(e) {}
          }
          if (presetId) {
            const updated = await dbIncrementView(env, presetId);
            return json({ success: true, id: presetId, views: updated.views });
          }
        } catch(e) {}
        return json({ success: true, views: {} });
      }

      if (path === "/api/comments" || path.startsWith("/api/comments/")) {
        const relayCommentResult = (result, fallback, code) => {
          if (!result.ok || !result.data || typeof result.data !== "object" || Array.isArray(result.data) || result.data.success === false) {
            const status = result.status >= 400 && result.status < 500 ? result.status : 502;
            return json({ success: false, error: result.data?.error || fallback, code: result.data?.code || code }, status);
          }
          return json({ ...result.data, success: true }, 200);
        };
        if (request.method === "GET") {
          const presetId = url.searchParams.get("preset_id") || url.searchParams.get("id") || "";
          if (!presetId) return json({ success: false, error: "preset_id required" }, 400);
          try {
            const comments = await dbGetPresetComments(env, presetId);
            return json({ success: true, preset_id: presetId, comments, total: comments.length }, 200, { "Cache-Control": "no-store" });
          } catch (error) {
            console.error("Comments read failed:", error?.message || String(error));
            return json({ success: false, error: "Comments are temporarily unavailable. Please retry.", code: "COMMENTS_UNAVAILABLE" }, 503, { "Cache-Control": "no-store" });
          }
        }

        if (request.method === "POST") {
          const session = parseSession(request.headers.get("Cookie"), request);
          if (!session || !session.userId) {
            return json({ success: false, error: "Please login with Discord to comment" }, 401);
          }

          let body;
          try { body = await request.json(); } catch(e) { return json({ success: false, error: "Invalid JSON" }, 400); }
          if (!body || typeof body !== "object" || Array.isArray(body)) {
            return json({ success: false, error: "A JSON object is required" }, 400);
          }

          const isAdmin = ADMIN_IDS.includes(session.userId);
          const avatarUrl = session.avatar 
            ? `https://cdn.discordapp.com/avatars/${session.userId}/${session.avatar}.png?size=128`
            : `https://cdn.discordapp.com/embed/avatars/${(parseInt(session.userId) || 0) % 5}.png`;

          const contentStr = typeof body.content === "string" ? body.content.trim() : "";
          if (/(?:DC|ZYREX)_MEDIA_BLOCK/i.test(contentStr)) {
            return json({
              success: false,
              error: "An issue occurred with our GIF and sticker service. (Error Code: ERR_MEDIA_SERVICE_UNAVAILABLE)"
            }, 400);
          }
          if (contentStr.length > 1500) {
            return json({ success: false, error: "Comment is too long (max 1500 characters)" }, 400);
          }
          const presetId = String(body.preset_id || body.id || "").trim();
          if (!presetId || !contentStr) {
            return json({ success: false, error: "preset_id and content required" }, 400);
          }
          if (presetId.length > 200) return json({ success: false, error: "Invalid preset_id" }, 400);
          const parentId = body.parent_id == null || body.parent_id === "" ? null : String(body.parent_id).trim();
          if (parentId && parentId.length > 200) {
            return json({ success: false, error: "Invalid parent comment ID" }, 400);
          }

          try {
            const result = await callBotCommentApi("/api/comments", "POST", {
              preset_id: presetId,
              user_id: session.userId,
              user_name: session.globalName || session.displayName || session.username || "Zyrex Member",
              user_avatar: avatarUrl,
              content: contentStr,
              parent_id: parentId,
              is_admin: isAdmin,
              source: "web",
            });
            return relayCommentResult(result, "Could not post your comment. Please try again.", "COMMENT_CREATE_FAILED");
          } catch(e) {
            console.error("Discord comment bridge unavailable:", e?.message || String(e));
            return json({ success: false, error: "Comments are temporarily unavailable. Please try again shortly." }, 503);
          }
        }

        if (request.method === "PUT") {
          const session = parseSession(request.headers.get("Cookie"), request);
          if (!session || !session.userId) {
            return json({ success: false, error: "Unauthorized" }, 401);
          }
          let body;
          try { body = await request.json(); } catch(e) { return json({ success: false, error: "Invalid JSON" }, 400); }
          if (!body || typeof body !== "object" || Array.isArray(body)) {
            return json({ success: false, error: "A JSON object is required" }, 400);
          }

          const contentStr = typeof body.content === "string" ? body.content.trim() : "";
          if (/(?:DC|ZYREX)_MEDIA_BLOCK/i.test(contentStr)) {
            return json({
              success: false,
              error: "An issue occurred with our GIF and sticker service. (Error Code: ERR_MEDIA_SERVICE_UNAVAILABLE)"
            }, 400);
          }

          const commentId = path.replace("/api/comments/", "").replace("/api/comments", "").trim() || body.id;
          if (!commentId || String(commentId).length > 200) return json({ success: false, error: "Comment ID required" }, 400);
          if (!contentStr) return json({ success: false, error: "Content cannot be empty" }, 400);
          if (contentStr.length > 1500) {
            return json({ success: false, error: "Comment is too long (max 1500 characters)" }, 400);
          }
          try {
            const commentsByPreset = await dbGetComments(env);
            let target = null;
            const findComment = comments => {
              for (const comment of comments) {
                if (String(comment.id) === commentId) return comment;
                const reply = findComment(Array.isArray(comment.replies) ? comment.replies : []);
                if (reply) return reply;
              }
              return null;
            };
            for (const comments of Object.values(commentsByPreset)) {
              if (Array.isArray(comments) && (target = findComment(comments))) break;
            }
            if (!target) return json({ success: false, error: "Comment not found" }, 404);
            if (String(target.user_id) !== String(session.userId) && !ADMIN_IDS.includes(session.userId)) {
              return json({ success: false, error: "You cannot edit this comment" }, 403);
            }
            const result = await callBotCommentApi(`/api/comments/${encodeURIComponent(commentId)}`, "PUT", {
              id: commentId,
              preset_id: target.preset_id,
              content: contentStr,
            });
            return relayCommentResult(result, "Could not save your changes. Please try again.", "COMMENT_UPDATE_FAILED");
          } catch(e) {
            console.error("Discord comment edit bridge unavailable:", e?.message || String(e));
            return json({ success: false, error: "Comments are temporarily unavailable. Please try again shortly." }, 503);
          }
        }

        if (request.method === "DELETE") {
          const session = parseSession(request.headers.get("Cookie"), request);
          if (!session || !session.userId) {
            return json({ success: false, error: "Unauthorized" }, 401);
          }
          const commentId = path.replace("/api/comments/", "").replace("/api/comments", "").trim() || url.searchParams.get("id");
          if (!commentId || String(commentId).length > 200) return json({ success: false, error: "Comment ID required" }, 400);
          try {
            const commentsByPreset = await dbGetComments(env);
            let target = null;
            const findComment = comments => {
              for (const comment of comments) {
                if (String(comment.id) === commentId) return comment;
                const reply = findComment(Array.isArray(comment.replies) ? comment.replies : []);
                if (reply) return reply;
              }
              return null;
            };
            for (const comments of Object.values(commentsByPreset)) {
              if (Array.isArray(comments) && (target = findComment(comments))) break;
            }
            if (!target) return json({ success: false, error: "Comment not found" }, 404);
            if (String(target.user_id) !== String(session.userId) && !ADMIN_IDS.includes(session.userId)) {
              return json({ success: false, error: "You cannot delete this comment" }, 403);
            }
            const result = await callBotCommentApi(`/api/comments/${encodeURIComponent(commentId)}`, "DELETE");
            return relayCommentResult(result, "Could not delete this comment. Please try again.", "COMMENT_DELETE_FAILED");
          } catch(e) {
            console.error("Discord comment delete bridge unavailable:", e?.message || String(e));
            return json({ success: false, error: "Comments are temporarily unavailable. Please try again shortly." }, 503);
          }
        }
      }

      if (path === "/api/downloads/counts") {
        try {
          const data = await dbGetDownloadCounts(env);
          return json(data);
        } catch (e) { return json({ success: true, counts: {} }); }
      }
      
      if (path === "/api/downloads/track" && request.method === "POST") {
        try {
          const body = await request.json();
          const productId = String(body.product_id || body.productId || body.preset_id || "").trim();
          if (!productId) return json({ success: false, tracked: false, error: "Product ID required" }, 400);
          const record = await recordDownloadEvent(env, request, {
            product_id: productId,
            product_name: body.productName || "",
            category: body.category || "",
            selected_files: body.selectedFiles,
            token_id: body.token_id || "",
          });
          await scheduleDownloadLog(env, record);
          const latestCounts = await dbGetDownloadCounts(env);
          return json({ success: true, tracked: true, duplicate: !record.isNew, product_id: productId, count: Number(latestCounts?.counts?.[productId]) || record.count });
        } catch (e) { return json({ success: false, error: "Track failed: " + e.message }, 500); }
      }
      if (path === "/api/downloads/preview" || path === "/api/files/preview") {
        const token = url.searchParams.get("token");
        const filePathParam = url.searchParams.get("file_path") || url.searchParams.get("path");
        const requestedFile = url.searchParams.get("file") || "";
        const productId = url.searchParams.get("id") || url.searchParams.get("product_id");

        let r2Prefix = "";
        if (token) {
          const d = await decodeToken(token, env);
          if (!d) return json({ success: false, error: "Invalid or expired token" }, 401);
          if (await isRevoked(env, d.discord_id) === true) {
            return json({ success: false, code: "ACCESS_REVOKED", error: ACCESS_REVOKED_MESSAGE }, 403);
          }
          if (!(await hasValidDownloadPass(env, d))) return json({ success: false, error: "Your download access is no longer active. Visit the Access page to unlock downloads again.", code: d.download_access === true ? "ACCESS_REQUIRED" : "AD_REQUIRED" }, 403);
          // A spent link must not be able to pull individual files one by one.
          if (await checkTokenUsed(env, hashToken(token))) {
            return json({ success: false, code: "TOKEN_USED", error: "This download link has already been used. Generate a new download link from the resource page." }, 403);
          }
          if (d.file_path) r2Prefix = normalizeR2Prefix(d.file_path);
        }
        if (!r2Prefix && filePathParam) {
          r2Prefix = normalizeR2Prefix(filePathParam);
        }
        if (!r2Prefix && productId) {
          try {
            const product = await fetchProductHint(productId, null, env);
            if (product?.file_path) r2Prefix = normalizeR2Prefix(product.file_path);
          } catch(e) {}
        }

        const cleanRequested = normalizeSelectedName(requestedFile);
        if (!cleanRequested) return json({ success: false, error: "File parameter required" }, 400);

        let fileObj = null;
        const bucketsToTry = [env.STORAGE_PROD, env.STORAGE].filter(Boolean);
        const rangeHeader = request.headers.get("Range");
        const getOpts = rangeHeader ? { range: request.headers } : {};

        // 1. Direct candidate keys
        const candidateKeys = [];
        if (r2Prefix) {
          const rawFolder = r2Prefix.replace(/\/+$/, "");
          candidateKeys.push(r2Prefix + cleanRequested);
          candidateKeys.push(rawFolder + "/" + cleanRequested);
          candidateKeys.push("production/" + r2Prefix + cleanRequested);
          candidateKeys.push("production/" + rawFolder + "/" + cleanRequested);
        }
        candidateKeys.push(cleanRequested);
        candidateKeys.push("production/" + cleanRequested);

        for (const key of candidateKeys) {
          for (const b of bucketsToTry) {
            try {
              fileObj = await b.get(key, getOpts);
              if (fileObj) break;
            } catch(e) {}
          }
          if (fileObj) break;
        }

        // 2. Targeted search using prefix listing
        if (!fileObj && r2Prefix) {
          const rawFolder = r2Prefix.replace(/\/+$/, "");
          const targetFilename = cleanRequested.split("/").pop().toLowerCase();
          const searchPrefixes = [r2Prefix, rawFolder + "/", "production/" + r2Prefix, "production/" + rawFolder + "/"];

          for (const pref of searchPrefixes) {
            for (const b of bucketsToTry) {
              try {
                const list = await b.list({ prefix: pref, limit: 200 });
                for (const obj of list.objects) {
                  const k = obj.key;
                  if (k.endsWith("/.placeholder") || isWatermarkName(k)) continue;
                  
                  const objBasename = k.split("/").pop().toLowerCase();
                  if (objBasename === targetFilename || k.toLowerCase().endsWith(cleanRequested.toLowerCase())) {
                    fileObj = await b.get(k, getOpts);
                    if (fileObj) break;
                  }
                }
              } catch(e) {}
              if (fileObj) break;
            }
            if (fileObj) break;
          }
        }

        if (!fileObj) {
          return json({ success: false, error: "File not found in storage", path: r2Prefix, file: cleanRequested }, 404);
        }

        // Determine MIME type
        const ext = cleanRequested.split(".").pop().toLowerCase();
        const mimeTypes = {
          mp4: "video/mp4",
          webm: "video/webm",
          mov: "video/quicktime",
          m4v: "video/mp4",
          mp3: "audio/mpeg",
          wav: "audio/wav",
          aac: "audio/aac",
          ogg: "audio/ogg",
          png: "image/png",
          jpg: "image/jpeg",
          jpeg: "image/jpeg",
          gif: "image/gif",
          webp: "image/webp",
          svg: "image/svg+xml",
          txt: "text/plain; charset=utf-8",
          json: "application/json; charset=utf-8",
          md: "text/markdown; charset=utf-8",
          xml: "application/xml; charset=utf-8",
          log: "text/plain; charset=utf-8",
          csv: "text/csv; charset=utf-8",
          srt: "text/plain; charset=utf-8",
          vtt: "text/vtt; charset=utf-8",
          url: "text/plain; charset=utf-8",
          pdf: "application/pdf"
        };
        const contentType = mimeTypes[ext] || fileObj.httpMetadata?.contentType || "application/octet-stream";

        const headers = new Headers();
        headers.set("Content-Type", contentType);
        headers.set("Access-Control-Allow-Origin", "*");
        headers.set("Access-Control-Allow-Methods", "GET, HEAD, OPTIONS");
        headers.set("Access-Control-Allow-Headers", "*");
        headers.set("Accept-Ranges", "bytes");
        headers.set("Cache-Control", "public, max-age=7200");

        if (request.method === "OPTIONS") {
          return new Response(null, { status: 204, headers });
        }

        if (fileObj.range) {
          headers.set("Content-Range", `bytes ${fileObj.range.offset}-${fileObj.range.end || (fileObj.size - 1)}/${fileObj.size}`);
          headers.set("Content-Length", String(fileObj.range.length));
          return new Response(fileObj.body, { status: 206, headers });
        }

        headers.set("Content-Length", String(fileObj.size));
        return new Response(fileObj.body, { status: 200, headers });
      }

      if (path === "/api/downloads/download") {
        const token = url.searchParams.get("token");
        if (!token) return json({ error: "Token required" }, 400);
        
        const data = await decodeToken(token, env);
        if (!data) return json({ success: false, error: "Invalid or expired token" }, 404);
        if (await isRevoked(env, data.discord_id) === true) {
          queueSecurityEvent(env, ctx, "access", {
            level: "alert",
            title: "Download blocked (access revoked)",
            description: ACCESS_REVOKED_MESSAGE,
            action: "download-revoked",
            user_id: data.discord_id,
            resource_id: data.product_id,
            ip: getClientIp(request),
          });
          return json({ success: false, code: "ACCESS_REVOKED", error: ACCESS_REVOKED_MESSAGE }, 403);
        }
        if (!(await hasValidDownloadPass(env, data))) {
          queueSecurityEvent(env, ctx, "access", {
            level: "warn",
            title: "Download blocked (access expired)",
            description: "The download pass behind this link is no longer active.",
            action: "download-access-required",
            user_id: data.discord_id,
            resource_id: data.product_id,
            ip: getClientIp(request),
          });
          return json({ success: false, error: "Your download access is no longer active. Visit the Access page to unlock downloads again.", code: data.download_access === true ? "ACCESS_REQUIRED" : "AD_REQUIRED" }, 403);
        }
        
        // Single-use token enforcement: the token is claimed atomically before any
        // archive work starts, so reloads and concurrent requests cannot replay it.
        const tokenFingerprint = hashToken(token);
        if (!(await claimTokenOnce(env, tokenFingerprint))) {
          queueSecurityEvent(env, ctx, "access", {
            level: "warn",
            title: "Download blocked (link reused)",
            description: "A single-use download link was presented a second time.",
            action: "download-token-reused",
            user_id: data.discord_id,
            resource_id: data.product_id,
            ip: getClientIp(request),
          });
          return json({ success: false, code: "TOKEN_USED", error: "This download link has already been used. Generate a fresh link from the resource page." }, 403);
        }
        
        const r2Prefix = normalizeR2Prefix(data.file_path);
        const selectedSet = getRequestedFileSet(url) || (Array.isArray(data.selected_files) && data.selected_files.length
          ? new Set(data.selected_files.map(normalizeSelectedName).filter(Boolean))
          : null);
        const title = url.searchParams.get("title") || data.product_id;
        if (!r2Prefix) return json({ success: false, error: "Token does not contain a storage path" }, 400);
        
        try {
          // Try both R2 bindings independently. A failed list against the primary
          // bucket must not prevent downloads from the fallback bucket.
          let fileObjects = [];
          let isProdBucket = true;
          let primaryListError = null;
          try {
            const allObjects = await r2List(env, r2Prefix, true);
            fileObjects = archiveObjects(allObjects, r2Prefix);
          } catch (error) {
            primaryListError = error;
            console.error("Primary download bucket list failed:", error?.message || String(error));
          }

          if (fileObjects.length === 0) {
            try {
              const allObjects = await r2List(env, r2Prefix, false);
              fileObjects = archiveObjects(allObjects, r2Prefix);
              isProdBucket = false;
            } catch (fallbackError) {
              console.error("Fallback download bucket list failed:", fallbackError?.message || String(fallbackError));
              if (primaryListError) throw fallbackError;
            }
          }
          
          if (fileObjects.length === 0) {
            return json({ success: false, error: "No files found in storage" }, 404);
          }
          
          const selectedObjects = selectedSet
            ? fileObjects.filter(o => {
                const rel = relativeR2Name(o.key, r2Prefix);
                const base = rel.split("/").pop();
                const full = o.key.replace(/\\/g, "/").replace(/^\/+/, "");
                return selectedSet.has(rel) || selectedSet.has(base) || selectedSet.has(full);
              })
            : fileObjects;
          
          if (selectedObjects.length === 0) {
            return json({ success: false, error: "Selected files were not found in storage" }, 404);
          }

          // ZIP construction and CRC work exceed the CPU budget on the Free Worker plan.
          // The existing storage service already builds these archives directly from R2.
          // Keep the Worker responsible for authorization and stream the completed archive
          // through it so the browser still receives the same authenticated download route.
          const selectedNames = selectedObjects.map(obj => relativeR2Name(obj.key, r2Prefix)).filter(Boolean);
          const archiveKey = await archiveCacheKey(data.product_id, r2Prefix, selectedNames).catch(() => "");
          const cached = await readCachedArchive(env, archiveKey);
          const storage = cached
            ? {
                response: new Response(cached.body, {
                  status: 200,
                  headers: {
                    "Content-Type": "application/zip",
                    ...(Number(cached.size) > 0 ? { "Content-Length": String(cached.size) } : {}),
                  },
                }),
                failure: "",
                detail: { source: "cache" },
              }
            : await requestStorageZip({
                discordId: data.discord_id,
                productId: data.product_id,
                r2Prefix,
                title,
                selectedNames,
              });
          if (!storage.response) {
            console.error("Storage archive unavailable:", JSON.stringify(storage.detail || {}));
            // Wake the packer in the background; the retry a few seconds later finds the
            // archive in R2 even if this attempt failed.
            warmArchiveCache(env, ctx, { productId: data.product_id, r2Prefix, title, discordId: data.discord_id }).catch(() => false);
            // A single file does not need the packer, so it is served from R2 instead.
            if (selectedObjects.length === 1) {
              const direct = await streamSingleStorageObject(env, selectedObjects[0], isProdBucket, title);
              if (direct) {
                const directTask = recordDownloadEvent(env, request, {
                  product_id: data.product_id,
                  product_name: title || data.product_id,
                  files: [{ name: relativeR2Name(selectedObjects[0].key, r2Prefix), size: selectedObjects[0].size }],
                  token_id: tokenFingerprint,
                  user_id: data.discord_id,
                  access_source: "download_direct",
                }).then(record => scheduleDownloadLog(env, record)).catch(() => {});
                if (ctx?.waitUntil) ctx.waitUntil(directTask); else await directTask;
                return direct;
              }
            }
            // Nothing reached the visitor, so the link must survive this failure.
            await releaseTokenClaim(env, tokenFingerprint);
            return json({
              success: false,
              code: "STORAGE_UNAVAILABLE",
              error: storage.failure === "prepare"
                ? "The storage service could not prepare this download. Please retry shortly."
                : "The storage service could not deliver this download. Please retry shortly.",
              upstream_status: Number((storage.detail && storage.detail.status) || 0),
              upstream_type: String((storage.detail && storage.detail.type) || ""),
              reason: String((storage.detail && storage.detail.reason) || ""),
              attempts: storage.attempts || 0,
            }, 503, { "Retry-After": "8", "Cache-Control": "no-store" });
          }
          const storageResponse = storage.response;

          const zipFilename = safeZipFilename(title || "download").slice(0, 120) + " - " + DOWNLOAD_BRAND + ".zip";
          const asciiFilename = zipFilename.replace(/[^\x20-\x7E]/g, "_").replace(/["\\]/g, "_");
          const recordTask = recordDownloadEvent(env, request, {
            product_id: data.product_id,
            product_name: title || data.product_id,
            files: selectedObjects.map(obj => ({ name: relativeR2Name(obj.key, r2Prefix), size: obj.size })).filter(file => file.name),
            token_id: tokenFingerprint,
            user_id: data.discord_id,
            access_source: "download_zip",
          }).then(record => scheduleDownloadLog(env, record)).catch(error => console.error("Download log persistence failed:", error?.message || String(error)));
          if (ctx?.waitUntil) ctx.waitUntil(recordTask);
          else await recordTask;
          const bodyForVisitor = cached ? storageResponse.body : cacheArchiveWhileStreaming(ctx, env, archiveKey, storageResponse);
          return new Response(bodyForVisitor, {
            status: 200,
            headers: {
              "Content-Type": "application/zip",
              "Content-Disposition": `attachment; filename="${asciiFilename}"; filename*=UTF-8''${encodeURIComponent(zipFilename)}`,
              ...(storageResponse.headers.get("Content-Length") ? { "Content-Length": storageResponse.headers.get("Content-Length") } : {}),
              "Cache-Control": "private, no-store, no-transform",
              ...corsHeaders,
            },
          });
        } catch (e) {
          console.error("Download error:", e.message);
          // The response never started, so the visitor can retry the same link.
          await releaseTokenClaim(env, tokenFingerprint);
          return json({ success: false, error: "Download failed: " + e.message }, 500);
        }
      }

      if (path === "/api/sftpgo/account") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ error: "Not logged in" }, 401);
        if (!(await canAccessUploaderCloud(session, env))) return json({ success: false, error: "Uploader access is required to view your cloud account." }, 403, { "Cache-Control": "no-store, private" });
        // Try bot API first (has richer data like display_name, discord links)
        try {
          const botResp = await fetch(`${BOT_API}/api/sftpgo/account`, {
            headers: {
              "X-User-ID": session.userId || "",
              "X-User-Name": session.username || "",
              "X-User-Can-Upload": session.canUpload ? "true" : "false",
              "X-User-Is-Admin": ADMIN_IDS.includes(session.userId) ? "true" : "false",
            },
          });
          if (botResp.ok) {
            const data = await botResp.json();
            if (data.success) return json(data);
          }
        } catch (e) { console.error("Bot account fetch failed:", e.message); }
        // Fallback: direct SFTPGo lookup
        const result = await getSftpgoAccount(session.userId, env);
        return json(result, result.success ? 200 : 404);
      }

      if (path === "/api/sftpgo/files") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ error: "Not logged in" }, 401);
        if (!(await canAccessUploaderCloud(session, env))) return json({ success: false, error: "Uploader access is required to view your cloud account." }, 403, { "Cache-Control": "no-store, private" });
        const browsePath = url.searchParams.get("path") || "/";
        try {
          const apiUrl = `${FILE_API}/api/files/list?token=zyrex-files-api-2026&discord_id=${session.userId}&path=${encodeURIComponent(browsePath)}`;
          const resp = await fetch(apiUrl);
          if (resp.ok) {
            const data = await resp.json();
            return json(data);
          }
          console.log("Local file API failed, status:", resp.status);
        } catch (e) { console.error("Local file API error:", e.message); }
        // Fallback: try bot API
        try {
          const botResp = await fetch(`${BOT_API}/api/sftpgo/files?path=${encodeURIComponent(browsePath)}`, {
            headers: {
              "X-User-ID": session.userId || "",
              "X-User-Name": session.username || "",
              "X-User-Can-Upload": session.canUpload ? "true" : "false",
              "X-User-Is-Admin": ADMIN_IDS.includes(session.userId) ? "true" : "false",
            },
          });
          if (botResp.ok) return json(await botResp.json());
        } catch (e) { console.error("Bot file listing fallback error:", e.message); }
        return json({ success: false, error: "File listing service unavailable" }, 500);
      }

      if (path === "/api/sftpgo/detected-resources") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ error: "Not logged in" }, 401);
        if (!(await canAccessUploaderCloud(session, env))) return json({ success: false, error: "Uploader access is required to view your cloud account." }, 403, { "Cache-Control": "no-store, private" });
        
        // Try R2 staging bucket scan first (prefix-scoped, bounded)
        try {
          const r2Result = await scanResourcesFromR2(session.userId, session.username, env);
          if (r2Result && r2Result.resources && r2Result.resources.length > 0) {
            return json(r2Result);
          }
          console.log("Storage scan found no resources, trying SFTPGo...");
        } catch (e) { console.error("Storage scan error:", e.message); }

        // Authoritative source: SFTPGo knows the real home directory contents. Never
        // surface a 5xx here — the page shows a friendly "no resources" state instead of
        // "Failed to scan cloud".
        try {
          const result = await scanDetectedResources(session.userId, env);
          if (result && result.success && result.resources && result.resources.length > 0) return json(result);
          console.log("SFTPGo scan found no resources, trying bot API...");
        } catch (e) { console.error("SFTPGo detected-resources error:", e.message); }

        // Fallback: bot API (same SFTPGo view, served from the VPS)
        try {
          const botResp = await fetch(`${BOT_API}/api/sftpgo/detected-resources`, {
            headers: {
              "X-User-ID": session.userId || "",
              "X-User-Name": session.username || "",
              "X-User-Can-Upload": session.canUpload ? "true" : "false",
              "X-User-Is-Admin": ADMIN_IDS.includes(session.userId) ? "true" : "false",
            },
            signal: AbortSignal.timeout(8000),
          });
          if (botResp.ok) {
            const data = await botResp.json();
            if (data.resources && data.resources.length > 0) return json(data);
          }
        } catch (e) { console.error("Bot detected-resources error:", e.message); }

        // Fallback: FILE_API (VPS file server)
        try {
          const apiUrl = `${FILE_API}/api/files/resources?token=zyrex-files-api-2026&discord_id=${session.userId}`;
          const resp = await fetch(apiUrl, { signal: AbortSignal.timeout(8000) });
          if (resp.ok) {
            const data = await resp.json();
            if (data.resources && data.resources.length > 0) return json(data);
          }
        } catch (e) { console.error("File API resources error:", e.message); }

        return json({
          success: true,
          resources: [],
          note: "No resources detected in your cloud yet. Upload a folder via SFTP and refresh.",
        });
      }

      if (path === "/api/admin/production-folders") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session || !ADMIN_IDS.includes(session.userId)) return json({ error: "Admin only" }, 403);
        try {
          const prodBucket = env.STORAGE_PROD || env.STORAGE;
          const listed = await prodBucket.list({ delimiter: "/" });
          const folders = [];
          // Get top-level editor folders
          for (const cp of listed.delimitedPrefixes || []) {
            const editorName = cp.replace(/\/$/, "");
            if (!editorName || editorName === "production") continue;
            
            // List resources inside each editor
            const editorList = await prodBucket.list({ prefix: cp, delimiter: "/" });
            for (const resCp of editorList.delimitedPrefixes || []) {
              const resName = resCp.slice(cp.length).replace(/\/$/, "");
              if (!resName) continue;
              
              // Get files in resource folder
              const resList = await prodBucket.list({ prefix: resCp });
              const files = [];
              for (const obj of resList.objects) {
                const fname = obj.key.slice(resCp.length);
                if (fname && !fname.endsWith("/")) {
                  files.push({ name: fname, size: obj.size });
                }
              }
              if (files.length > 0) {
                folders.push({
                  editor: editorName,
                  resource: resName,
                  prefix: resCp,
                  fileCount: files.length,
                  files: files.slice(0, 5),  // first 5 files preview
                });
              }
            }
          }
          return json({ success: true, folders });
        } catch (e) {
          return json({ success: false, error: publicErrorMessage(e) }, 500);
        }
      }

      if (path === "/api/cloud/change-password" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ error: "Not logged in" }, 401);
        const body = await request.json();
        const newPassword = body.password;
        if (!newPassword || newPassword.length < 6) {
          return json({ success: false, error: "Password must be at least 6 characters" }, 400);
        }
        const user = await findSftpgoUserByDiscordId(session.userId, env);
        if (!user) return json({ success: false, error: "No SFTPGo cloud account linked to your profile" }, 404);
        const token = await sftpgoAuth(env);
        if (!token) return json({ success: false, error: "SFTPGo auth failed" }, 500);
        try {
          const updateResp = await fetch(`${SFTPGO_API}/users/${encodeURIComponent(user.username)}`, {
            method: "PUT",
            headers: {
              "Authorization": `Bearer ${token}`,
              "Content-Type": "application/json",
              "User-Agent": "ZyrexWorker/1.0",
            },
            body: JSON.stringify({ ...user, password: newPassword }),
          });
          if (updateResp.ok) {
            return json({ success: true, message: "Password updated successfully" });
          }
          const errData = await updateResp.text();
          return json({ success: false, error: "SFTPGo update failed: " + errData }, 500);
        } catch (e) {
          return json({ success: false, error: publicErrorMessage(e) }, 500);
        }
      }

      if (path === "/api/products/destination-editors") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ error: "Not logged in" }, 401);
        try {
          const prodBucket = env.STORAGE_PROD || env.STORAGE;
          const listed = await prodBucket.list({ delimiter: "/" });
          const editors = [];
          for (const cp of listed.delimitedPrefixes || []) {
            const name = cp.replace(/\/$/, "");
            if (name && name !== "production") editors.push(name);
          }
          const seen = new Set(editors);
          for (const obj of listed.objects) {
            const parts = obj.key.split("/");
            if (parts.length >= 2) {
              const name = parts[0];
              if (name && name !== "production" && !seen.has(name)) {
                seen.add(name);
                editors.push(name);
              }
            }
          }
          return json({ success: true, editors: editors.sort() });
        } catch (e) {
          console.error("Storage editors error:", e.message);
          try {
            const apiUrl = `${FILE_API}/api/files/editors?token=zyrex-files-api-2026`;
            const resp = await fetch(apiUrl);
            if (resp.ok) return json(await resp.json());
          } catch (e2) { console.error("FILE_API editors fallback:", e2.message); }
        }
        return json({ success: false, error: "Editor listing unavailable" }, 500);
      }

      if (path === "/api/files/list-path") {
        // Accept either session cookie OR valid download token
        let userId = null;
        let tokenFilePath = null;
        const tokenParam = url.searchParams.get("token") || "";
        if (tokenParam) {
          const tokenData = await decodeToken(tokenParam, env);
          if (!tokenData) return json({ success: false, error: "Invalid or expired token" }, 401);
          if (!(await hasValidDownloadPass(env, tokenData))) return json({ success: false, error: "Your download access is no longer active. Visit the Access page to unlock downloads again.", code: tokenData.download_access === true ? "ACCESS_REQUIRED" : "AD_REQUIRED" }, 403);
          const tfp = hashToken(tokenParam);
          if (await checkTokenUsed(env, tfp)) return json({ success: false, error: "Token already used" }, 403);
          userId = tokenData.discord_id;
          tokenFilePath = tokenData.file_path || "";
        } else {
          const session = parseSession(request.headers.get("Cookie"), request);
          if (!session) return json({ success: false, error: "Not logged in" }, 401);
          const isVerified = await checkVerifiedRole(session.userId, env);
          if (isVerified === null) return json({ success: false, error: "Role verification is temporarily unavailable. Please retry shortly." }, 503);
          if (!isVerified) return json({ success: false, error: "Verified role required" }, 403);
          userId = session.userId;
        }
        if (await isRevoked(env, userId) === true) {
          return json({ success: false, code: "ACCESS_REVOKED", error: ACCESS_REVOKED_MESSAGE }, 403);
        }
        
        const listPath = url.searchParams.get("path") || tokenFilePath || "";
        const productIdForList = url.searchParams.get("product_id") || "";
        if (!listPath && !productIdForList) return json({ success: false, error: "Missing path parameter" }, 400);
        try {
          let prefix = normalizeR2Prefix(listPath);
          if (!prefix && productIdForList) {
            prefix = await resolveProductionPrefix(env, productIdForList, "", null);
          }
          if (!prefix) return json({ success: true, files: [], prefix: "" });
          let objects;
          try {
            objects = await r2List(env, prefix, true);  // useProd=true
          } catch (listErr) {
            console.error("r2List failed:", listErr.message);
            return json({ success: true, files: [], prefix, note: "Storage unavailable" });
          }
          let files = objects.filter(o => isDownloadableR2Object(o, prefix)).map(o => ({
            name: relativeR2Name(o.key, prefix),
            size: o.size,
            size_formatted: formatSizeR2(o.size),
          }));
          if (files.length === 0 && productIdForList) {
            const resolvedPrefix = await resolveProductionPrefix(env, productIdForList, prefix, null);
            if (resolvedPrefix && resolvedPrefix !== prefix) {
              prefix = resolvedPrefix;
              const resolvedObjects = await r2List(env, prefix, true);
              files = resolvedObjects.filter(o => isDownloadableR2Object(o, prefix)).map(o => ({
                name: relativeR2Name(o.key, prefix),
                size: o.size,
                size_formatted: formatSizeR2(o.size),
              }));
            }
          }
          return json({ success: true, files, prefix });
        } catch (e) { console.error("list-path error:", e.message); return json({ success: false, error: "File listing failed: " + e.message }, 500); }
      }

      if (path === "/api/products/create-editor" && (request.method === "POST" || request.method === "PUT")) {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ error: "Not logged in" }, 401);
        if (!(await sessionCanUpload(session, env))) {
          return json({ success: false, error: "You do not have upload access." }, 403);
        }
        let body = {};
        try {
          body = await request.json();
          const safeName = (body.name || "").replace(/[^a-zA-Z0-9 _\-.]/g, "").trim();
          if (!safeName) return json({ success: false, error: "Invalid folder name" }, 400);
          
          const prodBucket = env.STORAGE_PROD || env.STORAGE;
          // Check if folder already exists
          const existing = await prodBucket.list({ prefix: `${safeName}/`, delimiter: "/" });
          if ((existing.objects && existing.objects.length > 0) || (existing.delimitedPrefixes && existing.delimitedPrefixes.length > 0)) {
            return json({ success: false, error: `Folder '${safeName}' already exists` }, 409);
          }
          // Create placeholder to ensure folder prefix
          await prodBucket.put(`${safeName}/.placeholder`, "");
          return json({ success: true, message: `Editor folder '${safeName}' created` });
        } catch (e) {
          console.error("Storage create-editor error:", e.message);
          try {
            const apiUrl = `${FILE_API}/api/files/create-editor?token=zyrex-files-api-2026`;
            const resp = await fetch(apiUrl, {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify(body),
            });
            if (resp.ok) return json(await resp.json());
          } catch (e2) { console.error("FILE_API create-editor fallback:", e2.message); }
        }
        return json({ success: false, error: "Create editor failed" }, 500);
      }

      if (path === "/api/products/transfer" && (request.method === "POST" || request.method === "PUT")) {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ error: "Not logged in" }, 401);
        if (!(await sessionCanUpload(session, env))) {
          return json({ success: false, error: "You do not have upload access." }, 403);
        }
        
        const rawBody = await request.text();
        let body = {};
        try { body = JSON.parse(rawBody); } catch (e) {}

        // 1. Try Python FILE_API on VPS (Supports >300MB files via S3 multipart copy with no RAM limit)
        try {
          const payload = {
            discord_id: session.userId || "",
            source_editor: body.source_editor,
            source_resource: body.source_resource,
            destination_editor: body.destination_editor,
          };
          const apiUrl = `${FILE_API}/api/files/transfer?token=zyrex-files-api-2026`;
          const fileApiResp = await fetch(apiUrl, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload),
          });
          if (fileApiResp.ok) {
            const result = await fileApiResp.json();
            return json(result);
          }
        } catch (fileApiErr) {
          console.warn("FILE_API transfer delegate failed/timed out, falling back to Worker storage copy:", fileApiErr.message);
        }

        // 2. Fallback: Cloudflare Worker direct R2 copy (for smaller files)
        try {
          const productId = body.product_id || "";
          const srcEditor = body.source_editor;
          const srcResource = body.source_resource;
          const dstEditor = body.destination_editor;
          if (!srcEditor || !srcResource || !dstEditor) {
            return json({ success: false, error: "Missing required fields" }, 400);
          }
          
          const username = session.username;
          if (!username) return json({ success: false, error: "No username in session" }, 400);
          
          let srcPrefix = null;
          const stagingBucket = env.STORAGE;
          
          const sourceUsers = [...new Set([
            username,
            session.userId ? `${username}_${session.userId}` : "",
          ].filter(Boolean))];
          const sourcePrefixes = [];
          for (const sourceUser of sourceUsers) {
            sourcePrefixes.push(`${sourceUser}/${srcEditor}/${srcResource}/`);
            if (srcEditor === srcResource) sourcePrefixes.push(`${sourceUser}/${srcEditor}/`);
          }
          for (const candidate of sourcePrefixes) {
            const check = await stagingBucket.list({ prefix: candidate, limit: 1 });
            if (check && check.objects && check.objects.some(o => !o.key.endsWith("/"))) {
              srcPrefix = candidate;
              break;
            }
          }
          if (!srcPrefix) {
            return json({ success: false, error: `No files found in cloud: ${srcEditor}/${srcResource}` }, 404);
          }
          const dstPrefix = `${dstEditor}/${srcResource}/`;
          const prodBucket = env.STORAGE_PROD || env.STORAGE;
          
          const stagingObjects = await r2List(env, srcPrefix, false);
          const files = [];
          for (const obj of stagingObjects) {
            if (obj.key === srcPrefix) continue;
            const rel = obj.key.slice(srcPrefix.length);
            if (rel) files.push({ srcKey: obj.key, relPath: rel, size: obj.size });
          }
          
          if (files.length === 0) {
            return json({ success: false, error: `No files found in cloud: ${srcEditor}/${srcResource}` }, 404);
          }
          
          let copied = 0;
          const failed = [];
          for (const f of files) {
            try {
              if (f.relPath.endsWith("/")) {
                await prodBucket.put(dstPrefix + f.relPath, new ArrayBuffer(0));
                copied++;
              } else {
                const data = await stagingBucket.get(f.srcKey);
                if (data) {
                  const bytes = await data.arrayBuffer();
                  await prodBucket.put(dstPrefix + f.relPath, bytes);
                  copied++;
                }
              }
            } catch (e) {
              failed.push(f.srcKey);
              console.error("Storage copy failed:", f.srcKey, e.message);
            }
          }

          if (failed.length > 0) {
            return json({ success: false, error: `Transfer failed: ${failed.length} files` }, 500);
          }
          
          const wmNames = ["LEAKED BY ZYREX.txt", "Visit for more resources!.url"];
          let wmCount = 0;
          for (const wm of wmNames) {
            try {
              const wmData = WATERMARKS[wm];
              if (wmData) {
                await prodBucket.put(dstPrefix + wm, wmData);
                wmCount++;
              }
            } catch (e) { /* ignore */ }
          }
          
          for (const f of files) {
            try { await stagingBucket.delete(f.srcKey); } catch (e) { /* ignore */ }
          }
          if (srcPrefix) {
            try { await stagingBucket.delete(srcPrefix); } catch (e) { /* ignore */ }
          }
          
          const filePath = dstPrefix;
          return json({
            success: true,
            message: `Transferred ${copied} files, ${wmCount} watermarks. Cloud freed.`,
            file_path: filePath,
            files_copied: copied,
            watermarks_injected: wmCount,
          });
        } catch (e) {
          console.error("Storage transfer error:", e.message);
          return json({ success: false, error: "Transfer error: " + e.message }, 500);
        }
      }

      if (path === "/api/publish" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ error: "Not logged in" }, 401);
        if (!ADMIN_IDS.includes(session.userId)) return json({ error: "Admin only" }, 403);
        try {
          const body = await request.json();
          const resp = await fetch(`${FILE_API}/api/files/publish?token=zyrex-files-api-2026`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(body),
          });
          if (resp.ok) return json(await resp.json());
          const errText = await resp.text();
          return json({ success: false, error: "Publish failed: " + errText }, 500);
        } catch (e) {
          return json({ success: false, error: "Publish error: " + e.message }, 500);
        }
      }

      if (path.startsWith("/api/admin/sftpgo") || path.startsWith("/api/cloud/")) {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ error: "Not logged in" }, 401);
        if (!ADMIN_IDS.includes(session.userId)) return json({ error: "Admin only" }, 403);
        
        const targetUrl = `${BOT_API}${path}${url.search}`;
        try {
          const proxyResp = await fetch(targetUrl, {
            method: request.method,
            headers: {
              "Content-Type": "application/json",
              "X-User-ID": session.userId,
              "X-User-Name": session.username,
              "X-User-Can-Upload": session.canUpload ? "true" : "false",
              "X-User-Is-Admin": "true",
            },
            body: request.method !== "GET" && request.method !== "HEAD" ? await request.text() : undefined,
          });
          const text = await proxyResp.text();
          try { return json(JSON.parse(text), proxyResp.status); }
          catch { return new Response(text, { status: proxyResp.status, headers: corsHeaders }); }
        } catch (e) {
          console.error("SFTPGo admin proxy error:", e.message);
          return json({ success: false, error: "Remote server unreachable" }, 502);
        }
      }

      if (path === "/api/admin/vt-scan" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session?.userId || !ADMIN_IDS.includes(session.userId)) {
          return json({ error: "Unauthorized" }, 403);
        }
        try {
          const { url } = await request.json();
          if (!url || !url.startsWith("http")) return json({ error: "Invalid URL" }, 400);
          
          const cleanUrl = url;
          const base64Url = btoa(unescape(encodeURIComponent(cleanUrl)))
            .replace(/=+$/, "").replace(/\+/g, "-").replace(/\//g, "_");
          const vtApiKey = (env.VT_API_KEY || "").trim();
          if (!vtApiKey) return json({ error: "VirusTotal API key is not configured" }, 503);
          
          let vtResp = await fetch(`https://www.virustotal.com/api/v3/urls/${base64Url}`, {
            headers: { "x-apikey": vtApiKey },
            signal: AbortSignal.timeout(1800),
          });
          
          if (vtResp.status === 404) {
            await fetch("https://www.virustotal.com/api/v3/urls", {
              method: "POST",
              headers: { "x-apikey": vtApiKey, "Content-Type": "application/x-www-form-urlencoded" },
              body: "url=" + encodeURIComponent(cleanUrl)
            });
            await new Promise(r => setTimeout(r, 8000));
            vtResp = await fetch(`https://www.virustotal.com/api/v3/urls/${base64Url}`, {
              headers: { "x-apikey": vtApiKey }
            });
          }
          
          if (vtResp.ok) {
            const vtData = await vtResp.json();
            const stats = vtData?.data?.attributes?.last_analysis_stats;
            return json({
              success: true,
              vt_id: base64Url,
              harmless: stats?.harmless || 0,
              malicious: stats?.malicious || 0,
              suspicious: stats?.suspicious || 0,
              undetected: stats?.undetected || 0,
              total: (stats?.harmless||0) + (stats?.malicious||0) + (stats?.suspicious||0) + (stats?.undetected||0)
            });
          }
          return json({ success: true, vt_id: base64Url, harmless: 0, malicious: 0, pending: true });
        } catch(e) {
          return json({ success: false, error: publicErrorMessage(e) }, 502);
        }
      }

      if (path === "/api/requests" || path.startsWith("/api/requests/")) {
        // Security Gate: Protect Requests API from unauthenticated external access
        const origin = request.headers.get("Origin") || "";
        const referer = request.headers.get("Referer") || "";
        const secFetchSite = request.headers.get("Sec-Fetch-Site") || "";
        const clientHeader = request.headers.get("X-Zyrex-Client") || "";
        const hasValidCookie = !!parseSession(null, request);

        const isLegitBrowserSiteVisit = (
          (origin.includes("zyrexediting.xyz") || referer.includes("zyrexediting.xyz") || origin.includes("localhost") || referer.includes("localhost")) &&
          (secFetchSite === "same-origin" || secFetchSite === "same-site" || clientHeader === "web-portal" || hasValidCookie)
        ) || (await isTrustedBotRequest(request, env));

        if (!hasMasterKey && !hasReconcileKey && !isLegitBrowserSiteVisit) {
          return json({
            success: false,
            error: "Unauthorized. Valid API key required to access Requests API.",
            code: "api_key_required"
          }, 401, {
            "WWW-Authenticate": 'Bearer realm="Zyrex Requests API"'
          });
        }

        const REQUESTS_R2_KEY = "requests/data.json";
        const REQUESTS_QUOTA_KEY = "requests/quota_tracking.json";
        const REQUESTS_CHANNEL_ID = "1551118401508745367";
        const DAILY_REQUEST_LIMIT = 3;

        // An anonymous request must not leak who filed it: identity, staff status
        // and voter keys stay in storage for moderation, never in a public payload.
        const ANONYMITY_PROTECTED_FIELDS = [
          "user_id", "user_name", "user_avatar", "user_discriminator",
          "discord_id", "discord_user_id", "email", "is_admin", "user_is_admin"
        ];

        function stripAnonymousIdentity(item) {
          if (!item || item.is_anonymous !== true) return item;
          for (const field of ANONYMITY_PROTECTED_FIELDS) delete item[field];
          item.is_admin = false;
          item.requester_hidden = true;
          return item;
        }

        // UTC date key helper (YYYY-MM-DD)
        function getUtcDateKey(date = new Date()) {
          return date.toISOString().slice(0, 10);
        }

        // Next UTC midnight timestamp ISO
        function getNextUtcMidnightIso() {
          const now = new Date();
          const next = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 1, 0, 0, 0, 0));
          return next.toISOString();
        }

        // Read all requests from the server
        async function loadRequestsFromR2() {
          if (!env.STORAGE) throw new Error("Requests server storage is unavailable");
          try {
            const obj = await env.STORAGE.get(REQUESTS_R2_KEY);
            if (!obj) return [];
            const data = await obj.json();
            if (Array.isArray(data)) return data;
            if (data && Array.isArray(data.requests)) return data.requests;
            throw new Error("Requests server data has an invalid format");
          } catch (e) {
            console.error("loadRequestsFromR2 error:", e);
            throw new Error("Requests data could not be read from the server");
          }
        }

        // Save all requests to the server
        async function persistRequestsToR2(requestsList) {
          if (!env.STORAGE) throw new Error("Requests server storage is unavailable");
          const payload = JSON.stringify({
            requests: requestsList,
            total: requestsList.length,
            updated_at: new Date().toISOString()
          });
          // An upvote is a whole-document read/modify/write, so a single R2
          // hiccup used to answer 500 and lose the vote. Retry the write.
          let lastError;
          for (let attempt = 0; attempt < 3; attempt++) {
            try {
              await env.STORAGE.put(REQUESTS_R2_KEY, payload, {
                httpMetadata: { contentType: "application/json" }
              });
              return true;
            } catch (e) {
              lastError = e;
              if (attempt < 2) await new Promise(resolve => setTimeout(resolve, 150 * (attempt + 1)));
            }
          }
          console.error("persistRequestsToR2 error:", lastError);
          throw new Error("Requests data could not be saved to the server");
        }

        // ── Duplicate requests ─────────────────────────────────────────────────
        // One product must map to one request. The canonical key is the store id, so
        // "payhip.com/b/iWpyG", "payhip.com/b/iWpyG?ref=x" and "payhip.com/iWpyG/"
        // are all the same product.
        function extractCanonicalRequestStoreKey(rawUrl) {
          if (!rawUrl || typeof rawUrl !== "string") return "";
          const clean = rawUrl.trim().split("?")[0].split("#")[0].replace(/\/+$/, "");
          if (!clean) return "";
          const payhip = clean.match(/payhip\.com\/(?:b\/)?([a-zA-Z0-9_-]+)/i);
          if (payhip) return "payhip:" + payhip[1].toLowerCase();
          const gumroad = clean.match(/gumroad\.com\/(?:l|d)\/([a-zA-Z0-9_-]+)/i);
          if (gumroad) return "gumroad:" + gumroad[1].toLowerCase();
          const kofi = clean.match(/ko-fi\.com\/s\/([a-zA-Z0-9_-]+)/i);
          if (kofi) return "kofi:" + kofi[1].toLowerCase();
          return clean.toLowerCase().replace(/^https?:\/\//i, "").replace(/^www\./i, "");
        }

        function requestCanonicalKey(item) {
          const source = item || {};
          const storeKey = extractCanonicalRequestStoreKey(source.product_url || source.source_url || "");
          return storeKey ? "store:" + storeKey : "";
        }

        // A rejected request may legitimately be filed again, so it never blocks or
        // deduplicates. Everything else represents the same open (or fulfilled) ask.
        function isBlockingRequestStatus(status) {
          const value = String(status || "pending").toLowerCase();
          return !["rejected", "declined", "cancelled", "canceled"].includes(value);
        }

        function requestStatusRank(item) {
          const status = String((item && item.status) || "pending").toLowerCase();
          if (status === "completed") return 0;
          if (!isBlockingRequestStatus(status)) return 2;
          return 1;
        }

        // Keeps the fulfilled record (it carries the resource link), otherwise the
        // oldest one, and folds the duplicate's counters into it.
        function pickCanonicalRequest(a, b) {
          const rankA = requestStatusRank(a);
          const rankB = requestStatusRank(b);
          if (rankA !== rankB) return rankA < rankB ? a : b;
          const timeA = Date.parse((a && a.created_at) || "") || 0;
          const timeB = Date.parse((b && b.created_at) || "") || 0;
          return timeA <= timeB ? a : b;
        }

        function mergeRequestStats(target, duplicate) {
          if (!target || !duplicate) return;
          const voters = new Set([
            ...(Array.isArray(target.upvoters) ? target.upvoters : []),
            ...(Array.isArray(duplicate.upvoters) ? duplicate.upvoters : []),
          ]);
          if (voters.size) {
            target.upvoters = Array.from(voters);
            target.upvotes_count = Math.max(Number(target.upvotes_count) || 0, voters.size);
          } else {
            target.upvotes_count = Math.max(Number(target.upvotes_count) || 1, Number(duplicate.upvotes_count) || 1);
          }
          target.views_count = Math.max(Number(target.views_count) || 0, Number(duplicate.views_count) || 0);
          const viewers = new Set([
            ...(Array.isArray(target.viewers) ? target.viewers : []),
            ...(Array.isArray(duplicate.viewers) ? duplicate.viewers : []),
          ]);
          if (viewers.size) target.viewers = Array.from(viewers).slice(-5000);
          for (const field of ["resource_url", "resource_id", "discord_thread_id", "discord_message_id", "thumbnail"]) {
            if (!target[field] && duplicate[field]) target[field] = duplicate[field];
          }
        }

        function dedupeRequests(list) {
          const byKey = new Map();
          const requests = [];
          const removed = [];
          for (const item of Array.isArray(list) ? list : []) {
            const key = requestCanonicalKey(item);
            if (!key) { requests.push(item); continue; }
            const current = byKey.get(key);
            if (!current) {
              byKey.set(key, item);
              requests.push(item);
              continue;
            }
            const winner = pickCanonicalRequest(current, item);
            const loser = winner === current ? item : current;
            mergeRequestStats(winner, loser);
            if (winner !== current) {
              const index = requests.indexOf(current);
              if (index >= 0) requests[index] = winner;
              byKey.set(key, winner);
            }
            removed.push(loser);
          }
          return { requests, removed };
        }

        // Load Quota & Audit Tracking from R2
        async function loadQuotaTrackingFromR2() {          if (!env.STORAGE) return { updated_at: new Date().toISOString(), daily_records: {}, audit_log: [] };
          try {
            const obj = await env.STORAGE.get(REQUESTS_QUOTA_KEY);
            if (!obj) return { updated_at: new Date().toISOString(), daily_records: {}, audit_log: [] };
            const data = await obj.json();
            return {
              updated_at: data.updated_at || new Date().toISOString(),
              daily_records: data.daily_records || {},
              audit_log: Array.isArray(data.audit_log) ? data.audit_log : []
            };
          } catch (e) {
            console.error("loadQuotaTrackingFromR2 error:", e);
            return { updated_at: new Date().toISOString(), daily_records: {}, audit_log: [] };
          }
        }

        // Persist Quota & Audit Tracking to R2
        async function persistQuotaTrackingToR2(trackingData) {
          if (!env.STORAGE) return false;
          try {
            trackingData.updated_at = new Date().toISOString();
            if (Array.isArray(trackingData.audit_log) && trackingData.audit_log.length > 500) {
              trackingData.audit_log = trackingData.audit_log.slice(0, 500);
            }
            await env.STORAGE.put(REQUESTS_QUOTA_KEY, JSON.stringify(trackingData), {
              httpMetadata: { contentType: "application/json" }
            });
            return true;
          } catch (e) {
            console.error("persistQuotaTrackingToR2 error:", e);
            return false;
          }
        }

        // Compute current user daily allowance
        async function getUserAllowance(userId, clientIp, isAdmin) {
          const todayUtc = getUtcDateKey();
          const quotaData = await loadQuotaTrackingFromR2();
          const dayRecord = (quotaData.daily_records && quotaData.daily_records[todayUtc]) || { user_records: {} };
          const userRecords = dayRecord.user_records || {};

          const userRec = (userId && userRecords[userId]) ? userRecords[userId] : null;
          const ipKey = clientIp && clientIp !== "unknown" ? `ip_${clientIp.replace(/[^a-zA-Z0-9_]/g, "_")}` : null;
          const ipRec = (ipKey && userRecords[ipKey]) ? userRecords[ipKey] : null;

          let trackedCount = 0;
          if (userRec && typeof userRec.count === "number") trackedCount = Math.max(trackedCount, userRec.count);
          if (ipRec && typeof ipRec.count === "number") trackedCount = Math.max(trackedCount, ipRec.count);

          // Cross-verify with requests/data.json for complete resilience
          let requestsToday = [];
          try {
            const allReqs = await loadRequestsFromR2();
            requestsToday = allReqs.filter(r => {
              if (!r.created_at || !r.created_at.startsWith(todayUtc)) return false;
              if (userId && r.user_id === userId) return true;
              if (clientIp && clientIp !== "unknown" && (r.client_ip === clientIp || r.user_id === "anon_" + clientIp.replace(/[^a-zA-Z0-9]/g, "").slice(0, 14))) return true;
              return false;
            });
          } catch (_) {}

          const effectiveCount = Math.max(trackedCount, requestsToday.length);
          const limit = isAdmin ? 999 : DAILY_REQUEST_LIMIT;
          const remaining = Math.max(0, limit - effectiveCount);

          return {
            today_date: todayUtc,
            daily_limit: limit,
            used_today: effectiveCount,
            remaining: remaining,
            is_admin: !!isAdmin,
            resets_at: getNextUtcMidnightIso(),
            requests_today: requestsToday.map(r => ({
              id: r.id,
              title: r.title,
              type: r.type,
              created_at: r.created_at,
              status: r.status
            }))
          };
        }

        // Discord announcement helper (Dual-channel: Discord REST + BOT_API)
        async function sendDiscordRequestAnnouncement(arg1, arg2) {
          const reqData = arg2 || arg1;
          let messageId = null;
          let channelId = REQUESTS_CHANNEL_ID;

          const typeLabels = {
            "preset": "Preset",
            "project-file": "Project File",
            "project_file": "Project File",
            "plugin": "Plugin",
            "software": "Software",
            "scenepack": "Scenepack",
            "other": "Other"
          };
          const typeLabel = typeLabels[reqData.type] || "Resource";
          const requestedBy = reqData.is_anonymous ? "Anonymous Member" : (reqData.user_name || "Community Member");
          const userMention = (reqData.user_id && !reqData.is_anonymous && /^\d{17,20}$/.test(reqData.user_id)) ? `<@${reqData.user_id}>` : requestedBy;

          // 1. Try Discord REST directly if token is configured in Worker
          if (env.DISCORD_BOT_TOKEN) {
            try {
              const fields = [
                { name: "🏷️ Type", value: `\`${typeLabel}\``, inline: true },
                { name: "👤 Requested By", value: userMention, inline: true }
              ];

              if (reqData.price) {
                fields.push({ name: "💰 Price", value: `\`${reqData.price}\``, inline: true });
              }

              if (reqData.creator_name || reqData.creator_social_url) {
                const crText = reqData.creator_social_url ? `[${reqData.creator_name || "Creator"}](${reqData.creator_social_url})` : reqData.creator_name;
                fields.push({ name: "🎨 Creator", value: crText, inline: true });
              }

              if (reqData.product_url) {
                fields.push({ name: "🔗 Store Link", value: `[View Store Page](${reqData.product_url})`, inline: false });
              }

              const embed = {
                title: `📥 New Request: ${reqData.title}`,
                description: reqData.description ? (reqData.description.length > 500 ? reqData.description.slice(0, 497) + "..." : reqData.description) : "*No additional description provided.*",
                color: 0xFF2B52,
                fields: fields,
                footer: {
                  text: `Zyrex Community Requests • ID: ${reqData.id}`,
                  icon_url: "https://zyrexediting.xyz/assets/content.png"
                },
                timestamp: new Date().toISOString()
              };

              if (reqData.thumbnail && reqData.thumbnail.startsWith("http")) {
                embed.thumbnail = { url: reqData.thumbnail };
              }

              const payload = {
                content: `🔔 **New Community Request Submitted!** Vote and browse at https://zyrexediting.xyz/requests`,
                embeds: [embed],
                components: [
                  {
                    type: 1,
                    components: [
                      {
                        type: 2,
                        style: 5,
                        label: "View Request",
                        url: `https://zyrexediting.xyz/request?id=${reqData.id}`
                      }
                    ]
                  }
                ]
              };

              const discordResp = await fetch(`https://discord.com/api/v10/channels/${REQUESTS_CHANNEL_ID}/messages`, {
                method: "POST",
                headers: {
                  Authorization: `Bot ${env.DISCORD_BOT_TOKEN}`,
                  "Content-Type": "application/json"
                },
                body: JSON.stringify(payload)
              });

              if (discordResp.ok) {
                const msg = await discordResp.json();
                if (msg && msg.id) {
                  messageId = msg.id;
                  channelId = msg.channel_id || REQUESTS_CHANNEL_ID;
                }
              } else {
                console.error("Direct Discord request announcement failed:", discordResp.status, (await discordResp.text()).slice(0, 240));
              }
            } catch (restErr) {
              console.warn("Direct Discord REST request announcement failed:", restErr);
            }
          }

          let botData = null;
          if (!messageId) {
            try {
              const fallbackRequest = { ...reqData };
              try {
                const avatarUrl = new URL(String(fallbackRequest.user_avatar || ""));
                if (!/^https?:$/.test(avatarUrl.protocol)) throw new Error("invalid avatar URL protocol");
              } catch (_) {
                fallbackRequest.user_avatar = "https://zyrexediting.xyz/assets/content.png";
              }
              const botResp = await fetch(`${BOT_API}/api/requests/announce`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(fallbackRequest)
              });
              if (botResp.ok) {
                botData = await botResp.json();
                if (botData && botData.message_id) {
                  messageId = botData.message_id;
                  channelId = botData.channel_id || REQUESTS_CHANNEL_ID;
                }
              } else {
                console.error("BOT_API request announcement failed:", botResp.status, (await botResp.text()).slice(0, 240));
              }
            } catch (botErr) {
              console.error("BOT_API announce error:", botErr);
            }
          }

          // 3. Create Discord discussion thread for this request embed
          let threadId = (botData && botData.thread_id) ? botData.thread_id : null;
          if (messageId && !threadId) {
            if (env.DISCORD_BOT_TOKEN) {
              try {
                const thResp = await fetch(`https://discord.com/api/v10/channels/${channelId}/messages/${messageId}/threads`, {
                  method: "POST",
                  headers: {
                    Authorization: `Bot ${env.DISCORD_BOT_TOKEN}`,
                    "Content-Type": "application/json"
                  },
                  body: JSON.stringify({
                    name: `💬 ${reqData.title || "Request"}`.slice(0, 95),
                    auto_archive_duration: 10080
                  })
                });
                if (thResp.ok) {
                  const thData = await thResp.json();
                  if (thData && thData.id) {
                    threadId = thData.id;
                    try {
                      await fetch(`https://discord.com/api/v10/channels/${threadId}/messages`, {
                        method: "POST",
                        headers: {
                          Authorization: `Bot ${env.DISCORD_BOT_TOKEN}`,
                          "Content-Type": "application/json"
                        },
                        body: JSON.stringify({
                          content: `💬 **Thread discussion opened for ${reqData.title || "this request"}.** Discuss, share resources, or vote at https://zyrexediting.xyz/request?id=${reqData.id}`
                        })
                      });
                    } catch (_) {}
                  }
                } else {
                  threadId = messageId;
                }
              } catch (thErr) {
                console.warn("Direct thread creation error:", thErr);
                threadId = messageId;
              }
            } else {
              threadId = messageId;
            }
          }

          // 4. Persist discord message id & thread id back to R2
          if (messageId) {
            try {
              const allReqs = await loadRequestsFromR2();
              const target = allReqs.find(r => r.id === reqData.id);
              if (target) {
                target.discord_message_id = messageId;
                target.discord_channel_id = channelId;
                if (threadId) target.discord_thread_id = threadId;
                await persistRequestsToR2(allReqs);
              }
              reqData.discord_message_id = messageId;
              reqData.discord_channel_id = channelId;
              if (threadId) reqData.discord_thread_id = threadId;
            } catch (persistErr) {
              console.error("Failed to persist discord message/thread IDs:", persistErr);
            }
          }
          return { messageId, threadId };
        }

        // One-time/admin reconciliation endpoint: link existing published resources
        // to a single unambiguous open request, then synchronize its Discord embed.
        if ((path === "/api/requests/reconcile-resources" || path === "/api/requests/refresh-payhip-prices") && request.method === "POST") {
          if (!env.ZYREX_RECONCILE_KEY || providedApiKey !== env.ZYREX_RECONCILE_KEY) {
            return json({ success: false, error: "Unauthorized" }, 401);
          }
          if (path === "/api/requests/refresh-payhip-prices") {
            const requestsToPrice = await loadRequestsFromR2();
            const submitted = await request.json().catch(() => ({}));
            if (Array.isArray(submitted.prices)) {
              const applied = [];
              for (const item of submitted.prices) {
                const target = requestsToPrice.find(r => r.id === item.request_id);
                if (!target || !target.product_url || !normalizeRequestMatchUrl(target.product_url)) continue;
                if (item.url && normalizeRequestMatchUrl(item.url) !== normalizeRequestMatchUrl(target.product_url)) continue;
                const value = String(item.price || "").trim();
                if (!/^(?:Free|(?:CA\$|A\$|USD|GBP|EUR|JPY|TRY|CHF|[$£€¥₺])\s*\d[\d,]*(?:\.\d{1,2})?)$/i.test(value)) continue;
                if (target.price === value) continue;
                const oldPrice = target.price || "";
                target.price = value;
                target.price_scraped_at = new Date().toISOString();
                target.updated_at = new Date().toISOString();
                applied.push({ request_id: target.id, title: target.title, old_price: oldPrice, price: value });
              }
              if (applied.length) await persistRequestsToR2(requestsToPrice);
              const discordSynced = [];
              for (const target of requestsToPrice.filter(r => applied.some(a => a.request_id === r.id) && r.discord_message_id)) {
                if (await syncDiscordRequestAnnouncement(target)) discordSynced.push(target.id);
              }
              return json({ success: true, prices_updated: applied, discord_synced: discordSynced });
            }
            const targets = requestsToPrice.filter(r => {
              if (String(r.status || "").toLowerCase() === "rejected" || !r.product_url) return false;
              return normalizeScrapeUrl(r.product_url)?.provider === "payhip";
            });
            const updatedPrices = [];
            const scrapeFailures = [];
            for (let i = 0; i < targets.length; i += 4) {
              await Promise.all(targets.slice(i, i + 4).map(async reqItem => {
                try {
                  const scraped = await scrapePayhip(reqItem.product_url, env);
                  if (!scraped.success || !scraped.price) {
                    scrapeFailures.push({ request_id: reqItem.id, reason: scraped.error || "No authoritative product price found" });
                    return;
                  }
                  if (reqItem.price !== scraped.price) {
                    const previousPrice = reqItem.price || "";
                    reqItem.price = scraped.price;
                    reqItem.price_scraped_at = new Date().toISOString();
                    reqItem.updated_at = new Date().toISOString();
                    updatedPrices.push({ request_id: reqItem.id, title: reqItem.title, old_price: previousPrice, price: scraped.price });
                  }
                } catch (e) {
                  scrapeFailures.push({ request_id: reqItem.id, reason: e.message });
                }
              }));
            }
            if (updatedPrices.length) await persistRequestsToR2(requestsToPrice);
            const discordSynced = [];
            for (const reqItem of targets.filter(r => updatedPrices.some(u => u.request_id === r.id) && r.discord_message_id)) {
              if (await syncDiscordRequestAnnouncement(reqItem)) discordSynced.push(reqItem.id);
            }
            return json({ success: true, payhip_requests_checked: targets.length, prices_updated: updatedPrices, scrape_failures: scrapeFailures, discord_synced: discordSynced });
          }
          const products = await dbGetProducts(env);
          if (!Array.isArray(products)) return json({ success: false, error: "Could not load published resources" }, 502);
          const allReqs = await loadRequestsFromR2();
          const productsById = new Map(products.filter(p => p?.id).map(p => [String(p.id), p]));
          const repairedLinks = [];
          for (const reqItem of allReqs.filter(r => String(r.status || "").toLowerCase() === "completed")) {
            let resourceId = reqItem.resource_id ? String(reqItem.resource_id) : "";
            if (!resourceId && reqItem.resource_url) {
              try {
                const link = new URL(String(reqItem.resource_url), "https://zyrexediting.xyz");
                resourceId = link.searchParams.get("id") || "";
              } catch (_) {}
              if (!resourceId && !String(reqItem.resource_url).includes("/")) resourceId = String(reqItem.resource_url);
            }
            if (!resourceId || !productsById.has(resourceId)) continue;
            const canonicalUrl = `/leak?id=${encodeURIComponent(resourceId)}`;
            if (reqItem.resource_id !== resourceId || reqItem.resource_url !== canonicalUrl) {
              reqItem.resource_id = resourceId;
              reqItem.resource_url = canonicalUrl;
              reqItem.updated_at = new Date().toISOString();
              repairedLinks.push({ request_id: reqItem.id, title: reqItem.title, resource_id: resourceId, resource_name: productsById.get(resourceId).name });
            }
          }
          const updated = [];
          const claimed = new Set(allReqs.filter(r => r.resource_id).map(r => String(r.resource_id)));
          for (const product of products) {
            if (!product?.id || claimed.has(String(product.id))) continue;
            const target = findBestRequestForResource(product, allReqs);
            if (!target) continue;
            target.status = "completed";
            target.completed_at = target.completed_at || new Date().toISOString();
            target.updated_at = new Date().toISOString();
            target.resource_id = product.id;
            target.resource_url = `/leak?id=${encodeURIComponent(product.id)}`;
            claimed.add(String(product.id));
            updated.push({ request_id: target.id, title: target.title, resource_id: product.id, resource_name: product.name });
            await notifyRequesterOnCompletion(target);
          }
          if (updated.length || repairedLinks.length) await persistRequestsToR2(allReqs);
          const discordSynced = [];
          for (const requestItem of allReqs.filter(r => String(r.status || "").toLowerCase() === "completed" && r.resource_id && productsById.has(String(r.resource_id)) && r.discord_message_id)) {
            if (await syncDiscordRequestAnnouncement(requestItem)) discordSynced.push(requestItem.id);
          }
          return json({ success: true, resources_checked: products.length, requests_completed: updated, links_repaired: repairedLinks, discord_synced: discordSynced });
        }

        async function notifyRequesterOnCompletion(targetReq) {
          if (!targetReq) return;
          const channelId = targetReq.discord_channel_id || REQUESTS_CHANNEL_ID;
          try {
            await fetch(`${BOT_API}/api/requests/announce-completed`, {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                message_id: targetReq.discord_message_id || "",
                channel_id: channelId,
                title: targetReq.title || "Request",
                resource_url: targetReq.resource_url || "",
                req_id: targetReq.id,
                thumbnail: targetReq.thumbnail || "",
                user_id: targetReq.user_id || "",
                user_name: targetReq.user_name || ""
              })
            });
          } catch (botEditErr) {
            console.error("notifyRequesterOnCompletion error:", botEditErr);
          }
        }

        async function syncDiscordRequestAnnouncement(reqData) {
          if (!reqData.discord_message_id) {
            const created = await sendDiscordRequestAnnouncement(reqData);
            return !!(created && created.messageId);
          }
          const channelId = reqData.discord_channel_id || REQUESTS_CHANNEL_ID;
          if (env.DISCORD_BOT_TOKEN && reqData.discord_message_id) {
            try {
              const messageUrl = `https://discord.com/api/v10/channels/${channelId}/messages/${reqData.discord_message_id}`;
              const currentResp = await fetch(messageUrl, {
                headers: { Authorization: `Bot ${env.DISCORD_BOT_TOKEN}` }
              });
              if (currentResp.ok) {
                const current = await currentResp.json();
                const existingFields = current.embeds?.[0]?.fields || [];
                const oldRequester = existingFields.find(f => /requested by/i.test(f.name || ""));
                const typeLabels = {
                  "preset": "Preset", "project-file": "Project File", "project_file": "Project File",
                  "plugin": "Plugin", "software": "Software", "scenepack": "Scenepack", "other": "Other"
                };
                const status = String(reqData.status || "pending").toLowerCase();
                const statusLabels = { pending: "Pending", in_progress: "In Progress", completed: "Completed", rejected: "Rejected" };
                const color = status === "completed" ? 0x34d399 : status === "in_progress" ? 0xf59e0b : status === "rejected" ? 0x64748b : 0xff2b52;
                const fields = [
                  { name: "Type", value: `\`${typeLabels[reqData.type] || "Resource"}\``, inline: true },
                  oldRequester || { name: "Requested By", value: reqData.is_anonymous ? "Anonymous Member" : (reqData.user_name || "Community Member"), inline: true }
                ];
                if (reqData.price) fields.push({ name: "Price", value: `\`${reqData.price}\``, inline: true });
                if (reqData.creator_name || reqData.creator_social_url) {
                  const creator = reqData.creator_social_url ? `[${reqData.creator_name || "Creator"}](${reqData.creator_social_url})` : reqData.creator_name;
                  fields.push({ name: "Creator", value: creator, inline: true });
                }
                if (reqData.product_url) fields.push({ name: "Original Store", value: `[Open Store Page](${reqData.product_url})`, inline: false });
                if (status !== "pending") fields.push({ name: "Status", value: `**${statusLabels[status] || statusLabels.pending}**`, inline: true });
                if (status === "completed" && reqData.resource_url) {
                  fields.push({ name: "Resource", value: `[View Resource](https://zyrexediting.xyz${reqData.resource_url})`, inline: true });
                }
                const embed = {
                  title: `${status === "completed" ? "✅ Fulfilled Request" : "📥 Community Request"}: ${reqData.title || "Untitled Request"}`.slice(0, 256),
                  url: `https://zyrexediting.xyz/request?id=${encodeURIComponent(reqData.id || "")}`,
                  description: (reqData.description || "No details provided.").slice(0, 4000),
                  color,
                  fields,
                  footer: { text: "Zyrex Community Requests" },
                  timestamp: reqData.updated_at || reqData.created_at || new Date().toISOString()
                };
                if (reqData.thumbnail && /^https?:\/\//i.test(reqData.thumbnail)) embed.thumbnail = { url: reqData.thumbnail };
                const editResp = await fetch(messageUrl, {
                  method: "PATCH",
                  headers: { Authorization: `Bot ${env.DISCORD_BOT_TOKEN}`, "Content-Type": "application/json" },
                  body: JSON.stringify({
                    embeds: [embed],
                    components: [{
                      type: 1,
                      components: [{
                        type: 2,
                        style: 5,
                        label: "View Request",
                        url: `https://zyrexediting.xyz/request?id=${encodeURIComponent(reqData.id || "")}`
                      }]
                    }]
                  })
                });
                if (editResp.ok) return true;
                console.error("Discord request embed update failed:", editResp.status, (await editResp.text()).slice(0, 240));
              } else {
                console.error("Discord request message lookup failed:", currentResp.status, (await currentResp.text()).slice(0, 240));
              }
            } catch (e) {
              console.error("Discord request embed sync failed:", e.message);
            }
          }

          try {
            const botResp = await fetch(`${BOT_API}/api/requests/announce`, {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify(reqData)
            });
            if (!botResp.ok) console.error("BOT_API request embed sync failed:", botResp.status, (await botResp.text()).slice(0, 240));
            return botResp.ok;
          } catch (e) {
            console.error("BOT_API request embed sync error:", e.message);
            return false;
          }
        }

        // Helper: Ensure request has Discord thread created
        async function ensureRequestThread(targetReq, allReqs) {
          if (targetReq.discord_thread_id) return targetReq.discord_thread_id;

          // Special check for req-mub9sx48-kayt if already announced on bot
          if (targetReq.id === "req-mub9sx48-kayt" && !targetReq.discord_message_id) {
            targetReq.discord_message_id = "1551631598175260774";
            targetReq.discord_thread_id = "1551631598175260774";
            targetReq.discord_channel_id = REQUESTS_CHANNEL_ID;
            await persistRequestsToR2(allReqs);
            return targetReq.discord_thread_id;
          }

          const channelId = targetReq.discord_channel_id || REQUESTS_CHANNEL_ID;
          let messageId = targetReq.discord_message_id;

          if (!messageId) {
            const res = await sendDiscordRequestAnnouncement(targetReq);
            if (res && res.messageId) messageId = res.messageId;
            if (res && res.threadId) {
              targetReq.discord_message_id = res.messageId;
              targetReq.discord_thread_id = res.threadId;
              targetReq.discord_channel_id = channelId;
              await persistRequestsToR2(allReqs);
              return res.threadId;
            }
          }

          if (!messageId) return null;

          let threadId = null;
          if (env.DISCORD_BOT_TOKEN) {
            try {
              const thResp = await fetch(`https://discord.com/api/v10/channels/${channelId}/messages/${messageId}/threads`, {
                method: "POST",
                headers: {
                  Authorization: `Bot ${env.DISCORD_BOT_TOKEN}`,
                  "Content-Type": "application/json"
                },
                body: JSON.stringify({
                  name: `💬 ${targetReq.title || "Request"}`.slice(0, 95),
                  auto_archive_duration: 10080
                })
              });
              if (thResp.ok) {
                const thData = await thResp.json();
                if (thData && thData.id) threadId = thData.id;
              } else {
                threadId = messageId;
              }
            } catch (restErr) {
              console.warn("Direct thread creation error:", restErr);
              threadId = messageId;
            }
          }

          if (!threadId) {
            try {
              const botResp = await fetch(`${BOT_API}/api/requests/ensure-thread`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                  message_id: messageId,
                  channel_id: channelId,
                  title: targetReq.title
                })
              });
              if (botResp.ok) {
                const botData = await botResp.json();
                if (botData.thread_id) threadId = botData.thread_id;
              }
            } catch (bErr) {
              console.warn("BOT_API ensure-thread error:", bErr);
            }
          }

          if (!threadId) threadId = messageId;

          if (threadId) {
            targetReq.discord_thread_id = threadId;
            try {
              await persistRequestsToR2(allReqs);
            } catch (pErr) {
              console.error("Failed to persist thread ID to storage:", pErr);
            }
          }

          return threadId;
        }


        // GET /api/requests/allowance (User Daily Limit Status)
        if (path === "/api/requests/allowance" && request.method === "GET") {
          const session = parseSession(request.headers.get("Cookie"), request);
          const clientIp = request.headers.get("cf-connecting-ip") || "unknown";
          const isAdmin = !!(session && ADMIN_IDS.includes(session.userId));
          const userId = session ? session.userId : ("anon_" + clientIp.replace(/[^a-zA-Z0-9]/g, "").slice(0, 14));

          const allowance = await getUserAllowance(userId, clientIp, isAdmin);
          return json({
            success: true,
            user_id: userId,
            user_name: session ? (session.displayName || session.username) : "Anonymous User",
            ...allowance
          });
        }

        // GET /api/requests/quota-tracking (Detailed Admin Tracking System)
        if (path === "/api/requests/quota-tracking" && request.method === "GET") {
          const session = parseSession(request.headers.get("Cookie"), request);
          if (!(await sessionCanUpload(session, env))) {
            return json({ error: "Unauthorized. Admin or uploader privileges required." }, 403);
          }

          const quotaData = await loadQuotaTrackingFromR2();
          const targetDate = url.searchParams.get("date") || getUtcDateKey();
          const dayRecord = (quotaData.daily_records && quotaData.daily_records[targetDate]) || { user_records: {} };
          const userRecs = dayRecord.user_records || {};

          const usersList = Object.values(userRecs).map(u => ({
            user_id: u.user_id,
            user_name: u.user_name || "Community Member",
            client_ip: u.client_ip || "unknown",
            is_admin: !!u.is_admin,
            count: u.count || 0,
            limit: u.limit || DAILY_REQUEST_LIMIT,
            remaining: typeof u.remaining === "number" ? u.remaining : Math.max(0, DAILY_REQUEST_LIMIT - (u.count || 0)),
            last_activity: u.last_activity || u.updated_at || null,
            requests: u.requests || []
          }));

          // Sort by highest count used, then last activity
          usersList.sort((a, b) => (b.count - a.count) || (new Date(b.last_activity || 0) - new Date(a.last_activity || 0)));

          const totalRequestsToday = usersList.reduce((acc, u) => acc + (u.count || 0), 0);
          const limitReachedCount = usersList.filter(u => !u.is_admin && u.remaining === 0).length;

          return json({
            success: true,
            date: targetDate,
            daily_limit: DAILY_REQUEST_LIMIT,
            summary: {
              total_requests: totalRequestsToday,
              unique_users: usersList.length,
              users_at_limit: limitReachedCount
            },
            users: usersList,
            audit_log: (quotaData.audit_log || []).slice(0, 150),
            available_dates: Object.keys(quotaData.daily_records || {}).sort().reverse()
          });
        }

        // GET /api/requests/stats
        if (path === "/api/requests/stats" && request.method === "GET") {
          const reqs = await loadRequestsFromR2();
          const total = reqs.length;
          const pending = reqs.filter(r => r.status === "pending").length;
          const in_progress = reqs.filter(r => r.status === "in_progress").length;
          const completed = reqs.filter(r => r.status === "completed").length;
          const total_upvotes = reqs.reduce((acc, r) => acc + (r.upvotes_count || 1), 0);
          return json({
            success: true,
            total,
            pending,
            in_progress,
            completed,
            upvotes: total_upvotes,
            total_upvotes,
            stats: { total, pending, in_progress, completed, total_upvotes, upvotes: total_upvotes }
          });
        }

        // GET /api/requests
        if (path === "/api/requests" && request.method === "GET") {
          const loaded = await loadRequestsFromR2();
          // Requests filed before the duplicate guard existed are collapsed here, and
          // the cleaned list is written back so the duplicates never return.
          const { requests: reqs, removed } = dedupeRequests(loaded);
          if (removed.length) {
            console.warn("Removed duplicate requests:", removed.length, removed.map(item => item && item.id).slice(0, 20).join(","));
            // Re-read right before writing so a request created in the meantime is kept.
            const heal = (async () => {
              const current = await loadRequestsFromR2();
              const cleaned = dedupeRequests(current).requests;
              if (cleaned.length === current.length) return;
              await persistRequestsToR2(cleaned);
            })().catch(error => console.error("Request dedupe persist failed:", error?.message || String(error)));
            if (ctx?.waitUntil) ctx.waitUntil(heal); else heal.catch(() => {});
          }
          const session = parseSession(request.headers.get("Cookie"), request);
          const clientIp = request.headers.get("cf-connecting-ip") || "unknown";
          const voterKey = session ? session.userId : clientIp;

          const typeFilter = url.searchParams.get("type");
          const statusFilter = url.searchParams.get("status");
          const searchFilter = (url.searchParams.get("search") || "").toLowerCase().trim();
          const sort = url.searchParams.get("sort") || "recent";

          let filtered = reqs.map(r => {
            const item = { ...r };
            // Sanitize internal IP and voter arrays from public listing
            delete item.client_ip;
            delete item.viewers;
            delete item.upvoters;
            item.creator_avatar = stableAvatarUrl(r.creator_avatar);
            item.user_avatar = stableAvatarUrl(r.user_avatar);
            item.views_count = typeof r.views_count === "number" ? r.views_count : (parseInt(r.views_count, 10) || 0);
            item.has_upvoted = Array.isArray(r.upvoters) && r.upvoters.includes(voterKey);
            const userId = String(r.user_id || "");
            item.is_admin = userId !== "1382421118098346174" &&
              !!(r.is_admin || ADMIN_IDS.includes(userId));
            stripAnonymousIdentity(item);
            return item;
          });

          if (typeFilter && typeFilter !== "all") {
            filtered = filtered.filter(r => r.type === typeFilter);
          }
          if (statusFilter && statusFilter !== "all") {
            filtered = filtered.filter(r => r.status === statusFilter);
          }
          if (searchFilter) {
            filtered = filtered.filter(r =>
              (r.title && r.title.toLowerCase().includes(searchFilter)) ||
              (r.description && r.description.toLowerCase().includes(searchFilter)) ||
              (r.creator_name && r.creator_name.toLowerCase().includes(searchFilter))
            );
          }

          if (sort === "recent") {
            filtered.sort((a, b) => new Date(b.created_at || 0) - new Date(a.created_at || 0));
          } else if (sort === "price_desc") {
            filtered.sort((a, b) => (parseFloat((b.price || "").replace(/[^0-9.]/g, "")) || 0) - (parseFloat((a.price || "").replace(/[^0-9.]/g, "")) || 0));
          } else {
            // default upvotes
            filtered.sort((a, b) => (b.upvotes_count || 1) - (a.upvotes_count || 1));
          }

          return json(filtered);
        }

        // POST /api/requests (Create)
        if (path === "/api/requests" && request.method === "POST") {
          let body = {};
          try {
            body = await request.json();
          } catch (_) {
            return json({ error: "Invalid JSON body" }, 400);
          }

          const type = (body.type || "other").toLowerCase();
          const title = (body.title || "").trim();
          const description = (body.description || "").trim();
          const productUrl = (body.product_url || "").trim();
          const creatorSocialUrl = (body.creator_social_url || "").trim();
          const creatorName = (body.creator_name || "").trim();
          let creatorAvatar = (body.creator_avatar || "").trim();
          const creatorPlatform = (body.creator_platform || "").trim();
          const price = (body.price || "").trim();
          let thumbnail = (body.thumbnail || "").trim();
          const isAnonymous = !!body.is_anonymous;
          // Signed social avatar links expire within days, so the picture is copied
          // onto our own CDN before the request is stored.
          if (creatorAvatar && !isCdnAvatarUrl(creatorAvatar) && /^https?:\/\//i.test(creatorAvatar)) {
            try {
              const cdnAvatar = await storeAndProxyImage(env, creatorAvatar);
              if (isCdnAvatarUrl(cdnAvatar)) creatorAvatar = cdnAvatar;
            } catch (_) {}
          }

          if (!title) {
            return json({ error: "Title is required" }, 400);
          }

          function extractCanonicalStoreKey(rawUrl) {
            if (!rawUrl || typeof rawUrl !== "string") return "";
            const u = rawUrl.trim();
            if (!u) return "";
            const clean = u.split("?")[0].split("#")[0].replace(/\/+$/, "");

            // 1. Payhip: payhip.com/b/<id> or payhip.com/<creator>/<id>
            const payhipMatch = clean.match(/payhip\.com\/(?:b\/)?([a-zA-Z0-9_-]+)/i);
            if (payhipMatch) return "payhip:" + payhipMatch[1].toLowerCase();

            // 2. Gumroad: gumroad.com/l/<slug> or <creator>.gumroad.com/l/<slug>
            const gumroadMatch = clean.match(/gumroad\.com\/(?:l|d)\/([a-zA-Z0-9_-]+)/i);
            if (gumroadMatch) return "gumroad:" + gumroadMatch[1].toLowerCase();

            // 3. Ko-fi: ko-fi.com/s/<id>
            const kofiMatch = clean.match(/ko-fi\.com\/s\/([a-zA-Z0-9_-]+)/i);
            if (kofiMatch) return "kofi:" + kofiMatch[1].toLowerCase();

            // 4. Fallback normalized URL (protocol & www stripped, lowercase)
            return clean.toLowerCase().replace(/^https?:\/\//i, "").replace(/^www\./i, "");
          }

          if (productUrl) {
            const targetKey = extractCanonicalStoreKey(productUrl);
            if (targetKey) {
              try {
                const products = await dbGetProducts(env);
                const dup = products.find(p => {
                  const pKey = extractCanonicalStoreKey(p.product_url);
                  const sKey = extractCanonicalStoreKey(p.source_url);
                  return (pKey && pKey === targetKey) || (sKey && sKey === targetKey);
                });
                if (dup) {
                  return json({
                    error: "already_exists",
                    message: "This leak is already available on Zyrex!",
                    product: { id: dup.id, name: dup.name }
                  }, 409);
                }
              } catch (e) {
                console.warn("Product duplicate check failed:", e.message);
              }
            }
          }

          // Duplicate request guard: the same product must not open a second request,
          // a second Discord thread, or quietly consume another daily slot.
          const allReqs = await loadRequestsFromR2();
          const requestKey = requestCanonicalKey({ product_url: productUrl });
          if (requestKey) {
            const existing = allReqs.find(item => isBlockingRequestStatus(item.status) && requestCanonicalKey(item) === requestKey);
            if (existing) {
              const fulfilled = String(existing.status || "").toLowerCase() === "completed";
              return json({
                error: "duplicate_request",
                message: fulfilled
                  ? "This product was already requested and fulfilled on Zyrex."
                  : "This product has already been requested. Upvote the existing request instead.",
                request: {
                  id: existing.id,
                  title: existing.title,
                  status: existing.status,
                  created_at: existing.created_at,
                  resource_url: existing.resource_url || "",
                },
              }, 409);
            }
          }

          // Cache thumbnail in R2 if external
          if (thumbnail && !thumbnail.includes("thumbnail.zyrexediting.xyz") && thumbnail.startsWith("http")) {
            try {
              thumbnail = await storeAndProxyImage(env, thumbnail);
            } catch (_) {}
          }

          // User session binding
          const session = parseSession(request.headers.get("Cookie"), request);
          const clientIp = request.headers.get("cf-connecting-ip") || "unknown";
          const isAdmin = !!(session && ADMIN_IDS.includes(session.userId));

          let userId = "";
          let userName = isAnonymous ? "Anonymous User" : "Community Member";
          let userAvatar = isAnonymous ? "/assets/content.png" : "";

          if (session && session.userId) {
            userId = session.userId;
            if (!isAnonymous) {
              userName = session.displayName || session.username || "Zyrex Member";
              if (session.avatar) {
                const ext = session.avatar.startsWith("a_") ? "gif" : "png";
                userAvatar = `https://cdn.discordapp.com/avatars/${session.userId}/${session.avatar}.${ext}?size=128`;
              } else {
                try {
                  const defIdx = Number((BigInt(session.userId) >> 22n) % 6n);
                  userAvatar = `https://cdn.discordapp.com/embed/avatars/${defIdx}.png`;
                } catch (_) {
                  userAvatar = "https://cdn.discordapp.com/embed/avatars/0.png";
                }
              }
            }
          } else {
            userId = "anon_" + clientIp.replace(/[^a-zA-Z0-9]/g, "").slice(0, 14);
            userName = isAnonymous ? "Anonymous User" : "Community Member";
            userAvatar = "/assets/content.png";
          }

          const currentAllowance = await getUserAllowance(userId, clientIp, isAdmin);
          if (!isAdmin && currentAllowance.used_today >= DAILY_REQUEST_LIMIT) {
            // Record blocked submission in audit log
            try {
              const quotaData = await loadQuotaTrackingFromR2();
              if (!Array.isArray(quotaData.audit_log)) quotaData.audit_log = [];
              quotaData.audit_log.unshift({
                timestamp: new Date().toISOString(),
                event_type: "submit_blocked_limit",
                user_id: userId,
                user_name: userName,
                client_ip: clientIp,
                request_title: title,
                request_type: type,
                count_today: currentAllowance.used_today,
                limit: DAILY_REQUEST_LIMIT,
                note: "Rejected: Daily limit of 3 requests exceeded"
              });
              await persistQuotaTrackingToR2(quotaData);
            } catch (auditErr) {
              console.error("Audit log error on blocked request:", auditErr);
            }

            return json({
              success: false,
              error: "rate_limit_exceeded",
              message: "You have reached your daily request limit (Maximum 3 requests/day). Please try again tomorrow.",
              daily_limit: DAILY_REQUEST_LIMIT,
              used_today: currentAllowance.used_today,
              remaining: 0,
              resets_at: currentAllowance.resets_at
            }, 429);
          }

          const reqId = "req-" + Date.now().toString(36) + "-" + Math.random().toString(36).substring(2, 6);
          const newRequest = {
            id: reqId,
            type: type,
            title: title,
            description: description,
            product_url: productUrl,
            creator_social_url: creatorSocialUrl,
            creator_name: creatorName,
            creator_avatar: creatorAvatar,
            creator_platform: creatorPlatform,
            price: price,
            thumbnail: thumbnail,
            user_id: userId,
            user_name: userName,
            user_avatar: userAvatar,
            client_ip: clientIp,
            is_anonymous: isAnonymous,
            status: "pending",
            upvotes_count: 1,
            upvoters: [userId],
            created_at: new Date().toISOString()
          };

          allReqs.unshift(newRequest);
          await persistRequestsToR2(allReqs);

          // Record accepted request into quota tracking & audit log
          try {
            const todayUtc = getUtcDateKey();
            const quotaData = await loadQuotaTrackingFromR2();
            if (!quotaData.daily_records) quotaData.daily_records = {};
            if (!quotaData.daily_records[todayUtc]) quotaData.daily_records[todayUtc] = { user_records: {} };
            const dayRecord = quotaData.daily_records[todayUtc];
            if (!dayRecord.user_records) dayRecord.user_records = {};

            const trackingKey = userId || `ip_${clientIp.replace(/[^a-zA-Z0-9_]/g, "_")}`;
            const existingRec = dayRecord.user_records[trackingKey] || {
              user_id: userId,
              user_name: userName,
              client_ip: clientIp,
              is_admin: isAdmin,
              count: 0,
              requests: []
            };

            const newCount = (existingRec.count || currentAllowance.used_today || 0) + 1;
            existingRec.user_name = userName;
            existingRec.client_ip = clientIp;
            existingRec.is_admin = isAdmin;
            existingRec.count = newCount;
            existingRec.limit = isAdmin ? 999 : DAILY_REQUEST_LIMIT;
            existingRec.remaining = isAdmin ? 999 : Math.max(0, DAILY_REQUEST_LIMIT - newCount);
            existingRec.last_activity = newRequest.created_at;
            if (!Array.isArray(existingRec.requests)) existingRec.requests = [];
            existingRec.requests.unshift({
              id: reqId,
              title: title,
              type: type,
              created_at: newRequest.created_at,
              ip: clientIp
            });

            dayRecord.user_records[trackingKey] = existingRec;

            if (!Array.isArray(quotaData.audit_log)) quotaData.audit_log = [];
            quotaData.audit_log.unshift({
              timestamp: newRequest.created_at,
              event_type: "submit_accepted",
              user_id: userId,
              user_name: userName,
              client_ip: clientIp,
              request_id: reqId,
              request_title: title,
              request_type: type,
              count_today: newCount,
              remaining_today: existingRec.remaining
            });

            await persistQuotaTrackingToR2(quotaData);
          } catch (trackErr) {
            console.error("Quota tracking update error:", trackErr);
          }

          // Discord announcement
          await sendDiscordRequestAnnouncement(env, newRequest);

          return json({
            success: true,
            request: newRequest,
            allowance: {
              daily_limit: isAdmin ? 999 : DAILY_REQUEST_LIMIT,
              used_today: currentAllowance.used_today + 1,
              remaining: isAdmin ? 999 : Math.max(0, DAILY_REQUEST_LIMIT - (currentAllowance.used_today + 1)),
              resets_at: currentAllowance.resets_at
            }
          });
        }

        // GET /api/requests/:id (Single request detail)
        if (path.match(/^\/api\/requests\/[^/]+$/) && request.method === "GET") {
          const reqId = path.split("/")[3];
          const allReqs = await loadRequestsFromR2();
          const targetReq = allReqs.find(r => r.id === reqId);
          if (!targetReq) return json({ error: "Request not found" }, 404);
          const session = parseSession(request.headers.get("Cookie"), request);
          const clientIp = request.headers.get("cf-connecting-ip") || "unknown";
          const voterKey = session ? session.userId : clientIp;
          const detail = {
            ...targetReq,
            is_admin: String(targetReq.user_id || "") !== "1382421118098346174" &&
              !!(targetReq.is_admin || ADMIN_IDS.includes(String(targetReq.user_id || ""))),
            has_upvoted: Array.isArray(targetReq.upvoters) && targetReq.upvoters.includes(voterKey)
          };
          delete detail.upvoters;
          delete detail.viewers;
          delete detail.client_ip;
          stripAnonymousIdentity(detail);
          return json(detail);
        }

        // GET /api/requests/:id/thread (Fetch Discord thread details and live messages)
        if (path.match(/^\/api\/requests\/[^/]+\/thread$/) && request.method === "GET") {
          const reqId = path.split("/")[3];
          const allReqs = await loadRequestsFromR2();
          const targetReq = allReqs.find(r => r.id === reqId);
          if (!targetReq) return json({ error: "Request not found" }, 404);

          const threadId = await ensureRequestThread(targetReq, allReqs);
          const channelId = targetReq.discord_channel_id || REQUESTS_CHANNEL_ID;

          let messages = [];
          if (threadId && env.DISCORD_BOT_TOKEN) {
            try {
              const dResp = await fetch(`https://discord.com/api/v10/channels/${threadId}/messages?limit=50`, {
                headers: { Authorization: `Bot ${env.DISCORD_BOT_TOKEN}` }
              });
              if (dResp.ok) {
                const rawMsgs = await dResp.json();
                if (Array.isArray(rawMsgs)) {
                  messages = rawMsgs.map(m => {
                    let avatarUrl = "";
                    if (m.author && m.author.avatar) {
                      const ext = m.author.avatar.startsWith("a_") ? "gif" : "png";
                      avatarUrl = `/api/avatar/${m.author.id}/${m.author.avatar}.${ext}?size=64`;
                    }
                    const isSysBot = !m.webhook_id && !!(m.author && m.author.bot) &&
                      (String(m.author.id) === "1519456130290417776" || (m.author.username === "Zyrex Bot") || (m.author.username === "Zyrex™ Web"));
                    return {
                      id: m.id,
                      content: m.content || "",
                      created_at: m.timestamp,
                      author: {
                        id: m.author.id,
                        name: m.author.global_name || m.author.username,
                        username: m.author.username,
                        avatar: avatarUrl || "/assets/content.png",
                        bot: isSysBot,
                        is_webhook: !!m.webhook_id
                      },
                      attachments: (m.attachments || []).map(a => ({ url: a.url, filename: a.filename })),
                      reactions: (m.reactions || []).map(r => ({ emoji: r.emoji.name, count: r.count }))
                    };
                  }).reverse();
                }
              }
            } catch (dErr) {
              console.warn("Direct Discord REST fetch thread messages error:", dErr);
            }
          }

          if (messages.length === 0 && threadId) {
            try {
              const botResp = await fetch(`${BOT_API}/api/requests/thread/${threadId}/messages`);
              if (botResp.ok) {
                const botData = await botResp.json();
                if (Array.isArray(botData.messages)) {
                  messages = botData.messages.map(bm => {
                    const bAuthor = bm.author || {};
                    const bName = (bAuthor.name || bAuthor.username || "").trim();
                    const isSys = !bm.webhook_id && !bAuthor.is_webhook && !!bAuthor.bot &&
                      (String(bAuthor.id) === "1519456130290417776" || bName === "Zyrex Bot" || bName === "Zyrex™ Web");
                    return {
                      ...bm,
                      author: {
                        ...bAuthor,
                        bot: isSys
                      }
                    };
                  });
                }
              }
            } catch (bErr) {
              console.warn("BOT_API fetch thread messages error:", bErr);
            }
          }

          const guildId = env.GUILD_ID || "1518954946110685184";
          const discordThreadUrl = threadId 
            ? `https://discord.com/channels/${guildId}/${threadId}`
            : (targetReq.discord_message_id ? `https://discord.com/channels/${guildId}/${channelId}/${targetReq.discord_message_id}` : `https://discord.com/channels/${guildId}/${channelId}`);

          return json({
            success: true,
            thread_id: threadId,
            channel_id: channelId,
            discord_url: discordThreadUrl,
            request_title: targetReq.title,
            messages: messages
          });
        }

        // POST /api/requests/:id/thread/messages (Post message to Discord thread with user session & webhook)
        if (path.match(/^\/api\/requests\/[^/]+\/thread\/messages$/) && request.method === "POST") {
          const session = parseSession(request.headers.get("Cookie"), request);
          if (!session || !session.userId) {
            return json({ error: "Please login with Discord to participate in the thread discussion." }, 401);
          }

          const reqId = path.split("/")[3];
          const allReqs = await loadRequestsFromR2();
          const targetReq = allReqs.find(r => r.id === reqId);
          if (!targetReq) return json({ error: "Request not found" }, 404);

          let body = {};
          try { body = await request.json(); } catch (_) { return json({ error: "Invalid JSON" }, 400); }
          const content = (body.content || "").trim();
          if (!content) return json({ error: "Message content cannot be empty" }, 400);
          if (content.length > 2000) return json({ error: "Message exceeds 2000 characters" }, 400);

          const threadId = await ensureRequestThread(targetReq, allReqs);
          const channelId = targetReq.discord_channel_id || REQUESTS_CHANNEL_ID;

          if (!threadId) {
            return json({ error: "Could not locate or create Discord thread for this request" }, 500);
          }

          let sentMessage = null;
          // 1. Try sending via Webhook into the thread (with custom username and avatar)
          try {
            let whId = null;
            let whToken = null;
            if (env.DISCORD_BOT_TOKEN) {
              const whListResp = await fetch(`https://discord.com/api/v10/channels/${channelId}/webhooks`, {
                headers: { Authorization: `Bot ${env.DISCORD_BOT_TOKEN}` }
              });
              if (whListResp.ok) {
                const whList = await whListResp.json();
                let wh = Array.isArray(whList) ? whList.find(w => w.name === "Zyrex Requests Webhook") : null;
                if (!wh) {
                  const createWhResp = await fetch(`https://discord.com/api/v10/channels/${channelId}/webhooks`, {
                    method: "POST",
                    headers: {
                      Authorization: `Bot ${env.DISCORD_BOT_TOKEN}`,
                      "Content-Type": "application/json"
                    },
                    body: JSON.stringify({ name: "Zyrex Requests Webhook" })
                  });
                  if (createWhResp.ok) wh = await createWhResp.json();
                }
                if (wh && wh.token) {
                  whId = wh.id;
                  whToken = wh.token;
                }
              }
            }

            if (whId && whToken) {
              let userAvatarUrl = "https://zyrexediting.xyz/assets/content.png";
              if (session.avatar) {
                const ext = session.avatar.startsWith("a_") ? "gif" : "png";
                userAvatarUrl = `https://cdn.discordapp.com/avatars/${session.userId}/${session.avatar}.${ext}?size=128`;
              }
              const executeWhResp = await fetch(`https://discord.com/api/v10/webhooks/${whId}/${whToken}?thread_id=${threadId}&wait=true`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                  content: content,
                  username: (session.global_name || session.username || "Zyrex Member").slice(0, 80),
                  avatar_url: userAvatarUrl
                })
              });
              if (executeWhResp.ok) {
                sentMessage = await executeWhResp.json();
              }
            }
          } catch (whErr) {
            console.warn("Webhook thread message execution error:", whErr);
          }

          // 2. Fallback: Direct Bot REST message into thread
          if (!sentMessage && env.DISCORD_BOT_TOKEN) {
            try {
              const directResp = await fetch(`https://discord.com/api/v10/channels/${threadId}/messages`, {
                method: "POST",
                headers: {
                  Authorization: `Bot ${env.DISCORD_BOT_TOKEN}`,
                  "Content-Type": "application/json"
                },
                body: JSON.stringify({
                  content: `**${session.global_name || session.username}** (via Web): ${content}`
                })
              });
              if (directResp.ok) sentMessage = await directResp.json();
            } catch (directErr) {
              console.warn("Bot REST thread message error:", directErr);
            }
          }

          // 3. Fallback: BOT_API
          if (!sentMessage) {
            try {
              let userAvatarUrl = "https://zyrexediting.xyz/assets/content.png";
              if (session.avatar) {
                const ext = session.avatar.startsWith("a_") ? "gif" : "png";
                userAvatarUrl = `https://cdn.discordapp.com/avatars/${session.userId}/${session.avatar}.${ext}?size=128`;
              }
              const botPostResp = await fetch(`${BOT_API}/api/requests/thread/${threadId}/messages`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                  content: content,
                  username: session.global_name || session.username || "Zyrex Member",
                  avatar_url: userAvatarUrl,
                  user_id: session.userId
                })
              });
              if (botPostResp.ok) sentMessage = await botPostResp.json();
            } catch (botErr) {
              console.error("BOT_API thread post error:", botErr);
            }
          }

          return json({ success: true, message: sentMessage });
        }

        // POST /api/requests/sync-threads (Batch sync threads for all existing requests)
        if (path === "/api/requests/sync-threads" && request.method === "POST") {
          const session = parseSession(request.headers.get("Cookie"), request);
          const apiKey = extractApiKey(request, url);
          const isApiKeyAuth = (apiKey === ZYREX_MASTER_KEY || apiKey === "zyrex_app_sec_k982f81a7b54c29013e9a");
          if (!isApiKeyAuth && !(await sessionCanUpload(session, env))) {
            return json({ error: "Unauthorized" }, 403);
          }
          const allReqs = await loadRequestsFromR2();
          let count = 0;
          for (const r of allReqs) {
            try {
              const tid = await ensureRequestThread(r, allReqs);
              if (tid) count++;
            } catch (e) {
              console.warn(`Sync thread error for ${r.id}:`, e);
            }
          }
          await persistRequestsToR2(allReqs);
          return json({ success: true, total: allReqs.length, synced: count });
        }

        // POST /api/requests/:id/upvote
        if (path.match(/^\/api\/requests\/[^/]+\/upvote$/) && request.method === "POST") {
          const reqId = path.split("/")[3];
          const allReqs = await loadRequestsFromR2();
          const targetReq = allReqs.find(r => r.id === reqId);

          if (!targetReq) {
            return json({ error: "Request not found" }, 404);
          }

          const session = parseSession(request.headers.get("Cookie"), request);
          const clientIp = request.headers.get("cf-connecting-ip") || "unknown";
          const voterKey = session ? session.userId : clientIp;

          if (!Array.isArray(targetReq.upvoters)) targetReq.upvoters = [];

          let upvoted = false;
          const idx = targetReq.upvoters.indexOf(voterKey);
          if (idx > -1) {
            targetReq.upvoters.splice(idx, 1);
            targetReq.upvotes_count = Math.max(1, (targetReq.upvotes_count || 1) - 1);
            upvoted = false;
          } else {
            targetReq.upvoters.push(voterKey);
            targetReq.upvotes_count = (targetReq.upvotes_count || 1) + 1;
            upvoted = true;
          }

          await persistRequestsToR2(allReqs);

          return json({
            success: true,
            upvotes: targetReq.upvotes_count,
            upvoted: upvoted
          });
        }

        // POST /api/requests/:id/view (Real viewer count tracking)
        if (path.match(/^\/api\/requests\/[^/]+\/view$/) && request.method === "POST") {
          const reqId = path.split("/")[3];
          const allReqs = await loadRequestsFromR2();
          const targetReq = allReqs.find(r => r.id === reqId);
          if (!targetReq) return json({ error: "Request not found" }, 404);

          const session = parseSession(request.headers.get("Cookie"), request);
          const clientIp = request.headers.get("cf-connecting-ip") || "unknown";
          const viewerKey = session ? session.userId : clientIp;

          if (!Array.isArray(targetReq.viewers)) targetReq.viewers = [];
          if (!targetReq.viewers.includes(viewerKey)) {
            if (targetReq.viewers.length >= 1000) targetReq.viewers.shift();
            targetReq.viewers.push(viewerKey);
            targetReq.views_count = (targetReq.views_count || 0) + 1;
            await persistRequestsToR2(allReqs);
          }

          return json({ success: true, views: targetReq.views_count || 1 });
        }

        // POST /api/requests/:id/status (Admin/Uploader)
        if (path.match(/^\/api\/requests\/[^/]+\/status$/) && request.method === "POST") {
          const session = parseSession(request.headers.get("Cookie"), request);
          if (!(await sessionCanUpload(session, env))) {
            return json({ error: "Unauthorized" }, 403);
          }

          const reqId = path.split("/")[3];
          let body = {};
          try { body = await request.json(); } catch (_) {}
          const newStatus = (body.status || "").toLowerCase();
          if (!["pending", "in_progress", "completed", "rejected"].includes(newStatus)) {
            return json({ error: "Invalid status" }, 400);
          }

          const allReqs = await loadRequestsFromR2();
          const targetReq = allReqs.find(r => r.id === reqId);
          if (!targetReq) return json({ error: "Request not found" }, 404);

          targetReq.status = newStatus;
          targetReq.updated_at = new Date().toISOString();

          // On completion: record timestamp + optional resource link
          if (newStatus === "completed") {
            targetReq.completed_at = new Date().toISOString();
            if (body.resource_id) targetReq.resource_id = body.resource_id;
            if (body.resource_url) targetReq.resource_url = body.resource_url;

            // Update Discord message and notify requester via DM and site notifications
            const channelId = targetReq.discord_channel_id || REQUESTS_CHANNEL_ID;
            if (targetReq.discord_message_id && env.DISCORD_BOT_TOKEN) {
              const resourceLink = targetReq.resource_url
                ? `\n✅ **Fulfilled!** → [View Resource](https://zyrexediting.xyz${targetReq.resource_url})`
                : "\n✅ **This request has been fulfilled!**";
              try {
                await fetch(`https://discord.com/api/v10/channels/${channelId}/messages/${targetReq.discord_message_id}`, {
                  method: "PATCH",
                  headers: {
                    Authorization: `Bot ${env.DISCORD_BOT_TOKEN}`,
                    "Content-Type": "application/json"
                  },
                  body: JSON.stringify({
                    content: `✅ **Request Fulfilled!** ${resourceLink}\nhttps://zyrexediting.xyz/request?id=${reqId}`
                  })
                });
              } catch (discordEditErr) {
                console.warn("Direct Discord REST edit failed:", discordEditErr);
              }
            }

            // Always trigger bot notification for DM and site user notification
            await notifyRequesterOnCompletion(targetReq);
          }

          await persistRequestsToR2(allReqs);
          await syncDiscordRequestAnnouncement(targetReq);
          return json({ success: true, status: newStatus, request: targetReq });
        }


          // PUT /api/requests/:id (Admin/Uploader: edit)
          if (path.match(/^\/api\/requests\/[^/]+$/) && request.method === "PUT") {
            const session = parseSession(request.headers.get("Cookie"), request);
            if (!(await sessionCanUpload(session, env))) {
              return json({ error: "Unauthorized" }, 403);
            }
            const reqId = path.split("/")[3];
            let body = {};
            try { body = await request.json(); } catch (_) { return json({ error: "Invalid JSON" }, 400); }

            const allReqs = await loadRequestsFromR2();
            const targetReq = allReqs.find(r => r.id === reqId);
            if (!targetReq) return json({ error: "Request not found" }, 404);

            // Only update allowed fields
            const allowedFields = ["title", "type", "status", "description", "price", "product_url", "creator_name", "creator_social_url", "creator_avatar", "thumbnail", "resource_url", "resource_id"];
            for (const f of allowedFields) {
              if (body[f] !== undefined) targetReq[f] = body[f];
            }
            if (targetReq.creator_avatar && !isCdnAvatarUrl(targetReq.creator_avatar) && /^https?:\/\//i.test(String(targetReq.creator_avatar))) {
              try {
                const cdnAvatar = await storeAndProxyImage(env, targetReq.creator_avatar);
                if (isCdnAvatarUrl(cdnAvatar)) targetReq.creator_avatar = cdnAvatar;
              } catch (_) {}
            }
            targetReq.updated_at = new Date().toISOString();
            targetReq.updated_by = session.userId;
            await persistRequestsToR2(allReqs);
            await syncDiscordRequestAnnouncement(targetReq);
            return json({ success: true, request: targetReq });
          }

          // DELETE /api/requests/:id (Admin/Uploader: delete)
          if (path.match(/^\/api\/requests\/[^/]+$/) && request.method === "DELETE") {
            const session = parseSession(request.headers.get("Cookie"), request);
            if (!(await sessionCanUpload(session, env))) {
              return json({ error: "Unauthorized" }, 403);
            }
            const reqId = path.split("/")[3];
            const allReqs = await loadRequestsFromR2();
            const idx = allReqs.findIndex(r => r.id === reqId);
            if (idx === -1) return json({ error: "Request not found" }, 404);
            allReqs.splice(idx, 1);
            await persistRequestsToR2(allReqs);
            return json({ success: true });
          }

        return json({ error: "Not found" }, 404);
      }

      if (path === "/api/admin/creators/migrate" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session || !ADMIN_IDS.includes(String(session.userId))) {
          return json({ success: false, error: "Admin access required" }, 403);
        }
        try {
          const body = await request.json().catch(() => ({}));
          const products = await dbReadProductCatalog(env);
          for (const product of products) {
            if (product && !product.is_anonymous && !product.creator_account_id && !String(product.creator_social_url || "").trim()) {
              product.creator_identity_status = "needs_social_profile";
            }
          }
          const groups = new Map();
          for (const product of products) {
            if (!product || product.is_anonymous) continue;
            const socialUrl = String(product.creator_social_url || "").trim();
            const platform = getCreatorPlatform({ creator_social_url: socialUrl });
            const canonicalUrl = canonicalCreatorUrl(socialUrl);
            if (!platform || !canonicalUrl) continue;
            if (!groups.has(canonicalUrl)) groups.set(canonicalUrl, { socialUrl, platform, products: [] });
            groups.get(canonicalUrl).products.push(product);
          }
          const targets = Array.from(groups.values());
          const cursor = Math.max(0, Math.min(targets.length, Number.parseInt(body.cursor, 10) || 0));
          const limit = Math.max(1, Math.min(2, Number.parseInt(body.limit, 10) || 1));
          const batch = targets.slice(cursor, cursor + limit);
          let resolvedCount = 0;
          let unresolvedCount = 0;
          let linkedProducts = 0;
          let changedProducts = 0;
          for (const target of batch) {
            try {
              const profile = await resolveSocialProfile(target.socialUrl, env);
              const accountId = String(profile?.account_id || "").trim();
              if (!profile?.success) { unresolvedCount++; continue; }
              const resolved = {
                creator_platform: profile.platform || target.platform,
                creator_account_id: accountId,
                creator_username: profile.username || "",
                creator_nickname: profile.nickname || "",
                creator_avatar: profile.avatar || "",
                creator_social_url: target.socialUrl,
                creator_identity_status: accountId ? "linked" : "account_id_unavailable",
              };
              if (accountId) await saveCreatorProfile(env, {
                ...resolved,
                platform: resolved.creator_platform,
                account_id: accountId,
                social_url: canonicalCreatorProfileUrl({ ...profile, creator_account_id: accountId }, target.socialUrl),
              });
              let cachedAvatar = resolved.creator_avatar;
              if (cachedAvatar && !/^https:\/\/thumbnail\.zyrexediting\.xyz\//i.test(cachedAvatar)) {
                cachedAvatar = await storeAndProxyImage(env, cachedAvatar).catch(() => cachedAvatar);
              }
              for (const product of target.products) {
                if (resolved.creator_platform) product.creator_platform = resolved.creator_platform;
                if (accountId) product.creator_account_id = accountId;
                if (resolved.creator_username) product.creator_username = resolved.creator_username;
                const resolvedName = String(resolved.creator_nickname || "").trim();
                const resolvedUsername = String(resolved.creator_username || "").trim();
                if (resolvedName && (accountId || resolvedName.toLowerCase() !== resolvedUsername.toLowerCase() || !String(product.creator_nickname || "").trim())) product.creator_nickname = resolvedName;
                else if (!String(product.creator_nickname || "").trim() && resolvedName) product.creator_nickname = resolvedName;
                if (cachedAvatar) product.creator_avatar = cachedAvatar;
                if (resolved.creator_social_url) product.creator_social_url = resolved.creator_social_url;
                if (resolved.creator_identity_status) product.creator_identity_status = resolved.creator_identity_status;
              }
              changedProducts += target.products.length;
              if (accountId) {
                resolvedCount++;
                linkedProducts += target.products.length;
              } else unresolvedCount++;
            } catch (error) {
              console.warn("Creator identity migration failed:", target.platform, error?.message || String(error));
              unresolvedCount++;
            }
          }
          const done = cursor + batch.length >= targets.length;
          if (done) {
            const latestProfiles = await r2GetJSON(env, CREATOR_PROFILES_KEY, {});
            for (let i = 0; i < products.length; i++) if (products[i]) products[i] = mergeCreatorProfile(products[i], latestProfiles);
          }
          if (done || changedProducts || products.some(product => product?.creator_identity_status === "needs_social_profile")) await dbSaveProducts(env, products);
          if (done) {
            const index = {};
            for (const product of products) {
              if (!product || product.is_anonymous) continue;
              const names = new Set([
                product.creator_username,
                product.creator_nickname,
                product.author_name,
              ].map(value => String(value || "").trim().replace(/^@+/, "").toLowerCase()).filter(Boolean));
              for (const name of names) {
                if (!index[name]) index[name] = [];
                if (!index[name].includes(product.id)) index[name].push(product.id);
              }
            }
            await r2PutJSON(env, DB.CREATOR_INDEX, { success: true, index, updated_at: new Date().toISOString() });
          }
          return json({
            success: true,
            cursor,
            next_cursor: cursor + batch.length,
            total_profiles: targets.length,
            processed: batch.length,
            resolved: resolvedCount,
            unresolved: unresolvedCount,
            linked_products: linkedProducts,
            unlinked_products: products.filter(product => !product.is_anonymous && !product.creator_account_id).length,
            done,
          });
        } catch (error) {
          console.error("Creator identity migration failed:", error?.message || String(error));
          return json({ success: false, error: "Creator migration could not be completed" }, 500);
        }
      }

      if (path === "/api/products" && request.method === "GET") {
        try {
          if (!env.STORAGE) return json({ success: false, error: "Resources are temporarily unavailable" }, 503);
          const catalogObject = await env.STORAGE.get(DB.PRODUCTS);
          if (!catalogObject) return json({ success: false, error: "Resources are temporarily unavailable" }, 503);
          const rawCatalog = await catalogObject.json();
          if (!Array.isArray(rawCatalog)) return json({ success: false, error: "Resources are temporarily unavailable" }, 502);
          const catalog = await applyProductOverridesToProducts(env, rawCatalog);

          const [downloadData, statsData, creatorProfiles, avatarMap, handleIndex] = await Promise.all([
            dbGetDownloadCounts(env), dbGetStats(env), r2GetJSON(env, CREATOR_PROFILES_KEY, {}),
            loadDiscordAvatarMap(env, catalog.map(product => product && (product.uploader_id || product.author_id))),
            readHandleIndex(env).catch(() => null)
          ]);
          const profileIndex = buildCreatorProfileIndex(creatorProfiles);
          // Uploaders with a profile get a clickable name on every resource card.
          const handleByOwner = invertHandleIndex(handleIndex);
          const normalized = catalog.filter(product => product && product.id && !isScenepackProduct(product)).map(product => {
            const item = normalizeResourceProfile(
              repairProductDisplayData({ ...product }),
              profileIndex,
              avatarMap
            );
            if (!Array.isArray(item.links)) {
              try { item.links = JSON.parse(item.links_json || "[]"); } catch (_) { item.links = []; }
            }
            if (!item.vt_scan && item.vt_scan_json) {
              try { item.vt_scan = JSON.parse(item.vt_scan_json); } catch (_) { item.vt_scan = null; }
            }
            if (!Array.isArray(item.resource_subcategories)) {
              try {
                const parsed = JSON.parse(item.resource_subcategories || "[]");
                item.resource_subcategories = Array.isArray(parsed) ? parsed : [];
              } catch (_) {
                item.resource_subcategories = String(item.resource_subcategories || "").split(/[,/]/).map(value => value.trim()).filter(Boolean);
              }
            }
            const counts = downloadData?.counts || {};
            const stats = statsData?.[item.id] || {};
            item.downloads = Number(counts[item.id] ?? item.downloads) || 0;
            item.views = Number(stats.views ?? item.views) || 0;
            item.uploader_is_admin = !item.is_anonymous && ADMIN_IDS.includes(String(item.uploader_id || item.author_id || "").trim());
            if (!item.is_anonymous) {
              const owner = String(item.uploader_id || item.author_id || "").trim();
              const ownerHandle = handleByOwner[owner];
              if (ownerHandle) {
                item.uploader_handle = ownerHandle;
                item.uploader_profile_url = `/@${ownerHandle}`;
              } else {
                delete item.uploader_handle;
                delete item.uploader_profile_url;
              }
            }
            return item;
          });

          const id = String(url.searchParams.get("id") || "").trim();
          // Mirrors, archive passwords and install notes are download material: they only
          // reach staff tooling, never a public catalogue response.
          const canSeeDownloadData = isAdminRequest(request, env, hasMasterKey);
          if (!canSeeDownloadData) normalized.forEach(stripPluginDownloadFields);

          if (id) {
            const product = normalized.find(item => String(item.id) === id);
            if (!product) return json({ error: "Product not found" }, 404, { "Cache-Control": "public, max-age=5" });
            return json(product, 200, { "Cache-Control": "public, max-age=5, s-maxage=10, stale-while-revalidate=30" });
          }

          const type = String(url.searchParams.get("type") || "").toLowerCase();
          const products = normalized.filter(item => !type || String(item.type || "").toLowerCase() === type)
            .sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || "")));
          if (url.searchParams.has("chunk") || url.searchParams.has("page")) {
            const page = Math.max(1, Number.parseInt(url.searchParams.get("chunk") || url.searchParams.get("page") || "1", 10) || 1);
            const limit = Math.max(1, Math.min(100, Number.parseInt(url.searchParams.get("limit") || "36", 10) || 36));
            return json({
              chunk: page, limit, total: products.length,
              total_chunks: Math.ceil(products.length / limit) || 1,
              has_more: page * limit < products.length,
              items: products.slice((page - 1) * limit, page * limit),
            }, 200, { "Cache-Control": "public, max-age=5, s-maxage=10, stale-while-revalidate=30" });
          }
          return json(products, 200, {
            "Cache-Control": url.searchParams.has("ts") ? "no-store" : "public, max-age=5, s-maxage=10, stale-while-revalidate=30",
          });
        } catch (error) {
          console.error("Storage product catalog read failed:", error?.message || String(error));
          return json({ success: false, error: "Could not load resources" }, 502);
        }
      }

      // Plugin downloads are delivered as external mirrors, so the URL itself is the asset.
      // It is only handed to a signed-in member with the Verified role, and every handout is
      // written to the access audit trail.
      if (path === "/api/plugins/download" && request.method === "POST") {
        const noStore = { "Cache-Control": "no-store, private" };
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!hasMasterKey) {
          if (!session) {
            return json({ success: false, error: "Sign in with Discord to download.", code: "NOT_LOGGED_IN" }, 401, noStore);
          }
          if (await isRevoked(env, session.userId) === true) {
            return json({ success: false, error: ACCESS_REVOKED_MESSAGE, code: "ACCESS_REVOKED" }, 403, noStore);
          }
          const verified = await checkVerifiedRole(session.userId, env);
          if (verified === null) {
            return json({ success: false, error: "Could not check your Discord role right now. Please retry.", code: "VERIFY_UNAVAILABLE" }, 503, noStore);
          }
          if (verified !== true) {
            return json({
              success: false,
              error: "Join the Zyrex Discord and verify your account to download plugins and software.",
              code: "NOT_VERIFIED",
            }, 403, noStore);
          }
        }
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON" }, 400, noStore); }
        const productId = String((body && body.id) || "").trim();
        if (!productId) return json({ success: false, error: "A product id is required" }, 400, noStore);

        try {
          const mirror = await resolvePluginMirror(env, productId);
          if (!mirror || (!mirror.url && !mirror.token_url)) {
            return json({ success: false, error: "This download has no mirror yet. Ask the staff in Discord.", code: "MIRROR_MISSING" }, 404, noStore);
          }
          let host = "";
          try { host = new URL(mirror.url || mirror.token_url).hostname; } catch (_) { host = ""; }
          // `peek` fills the detail panel; only a real download counts and is audited.
          const isPeek = body && body.peek === true;
          if (!isPeek && productId.startsWith("prod_") && mirror.url) {
            dbIncrementDownloadCount(env, productId).catch(() => {});
            dbIncrementDownload(env, productId).catch(() => {});
          }
          if (!isPeek) {
            queueSecurityEvent(env, ctx, "access", {
              level: "info",
              title: "Plugin download unlocked",
              action: "plugin-download",
              user_id: session ? session.userId : "master",
              user_name: session ? (session.displayName || session.username) : "Master API",
              resource_id: productId,
              resource_name: mirror.name || "",
              access: `${hasMasterKey ? "Master API" : "Verified"} • ${host || "mirror"}`,
              ip: getClientIp(request),
            });
          }
          return json({
            success: true,
            url: mirror.url || "",
            token_url: mirror.token_url || "",
            label: mirror.label || "",
            host,
            password: mirror.password || "",
            notes: mirror.notes || "",
            mirrors: mirror.mirrors || [],
          }, 200, noStore);
        } catch (error) {
          console.error("Plugin download resolve failed:", error?.message || String(error));
          return json({ success: false, error: "Could not prepare that download." }, 503, noStore);
        }
      }

      // ── R2-served routes: no Bot VPS needed ────────────────────────────────────
      // /api/resource-stats — compute from R2 products
      if (path === "/api/resource-stats") {
        try {
          const products = (await dbGetProducts(env)).filter(product => !isScenepackProduct(product));
          const dlData = await dbGetDownloadCounts(env);
          const counts = dlData?.counts || {};
          const total_downloads = Object.values(counts).reduce((s, v) => s + (Number(v) || 0), 0);
          const unique_creators = new Set(products.map(p => p.author_id || p.uploader_id).filter(Boolean)).size;
          return json({ success: true, total_resources: products.length, unique_creators, total_downloads });
        } catch(e) {
          return json({ success: false, error: "Resource stats unavailable" }, 500);
        }
      }

      // /api/check-uploader — check if user is in R2 uploaders list
      if (path === "/api/check-uploader") {
        const checkId = url.searchParams.get("user_id") || url.searchParams.get("id") || "";
        const sessionCk = parseSession(request.headers.get("Cookie"), request);
        const userId = checkId || (sessionCk ? sessionCk.userId : "");
        if (!userId) return json({ is_uploader: false });
        try {
          const upData = await dbGetUploaders(env);
          const uploaders = upData?.uploaders || [];
          return json({ is_uploader: uploaders.includes(userId), user_id: userId });
        } catch(e) {
          return json({ is_uploader: false });
        }
      }

      if (path === "/api/notifications") {
        const session = parseSession(request.headers.get("Cookie"), request);
        const stateKey = session?.userId ? `database/notification-state/${String(session.userId)}.json` : "";
        if (request.method === "POST") {
          if (!session?.userId || !stateKey) return json({ success: false, error: "Sign in to update notifications." }, 401);
          let body = {};
          try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON body." }, 400); }
          const action = String(body.action || "");
          const id = String(body.id || "").slice(0, 180);
          const ids = Array.isArray(body.ids) ? body.ids.map(value => String(value || "").slice(0, 180)).filter(Boolean).slice(0, 100) : [];
          const state = await r2GetJSON(env, stateKey, { read: [], dismissed: [] }).catch(() => ({ read: [], dismissed: [] }));
          state.read = Array.isArray(state.read) ? state.read.map(String) : [];
          state.dismissed = Array.isArray(state.dismissed) ? state.dismissed.map(String) : [];
          const targets = action === "mark_all_read" || action === "clear_all" ? ids : [id];
          if (!["read", "unread", "dismiss", "mark_all_read", "clear_all"].includes(action) || (!targets.length && action !== "clear_all")) {
            return json({ success: false, error: "Invalid notification action." }, 400);
          }
          if (action === "read" || action === "mark_all_read") {
            state.read = [...new Set([...state.read, ...targets])].slice(-500);
          } else if (action === "unread") {
            state.read = state.read.filter(value => value !== id);
          } else if (action === "dismiss") {
            state.dismissed = [...new Set([...state.dismissed, id])].slice(-500);
          } else if (action === "clear_all") {
            state.dismissed = [...new Set([...state.dismissed, ...ids])].slice(-500);
          }
          state.updated_at = new Date().toISOString();
          const saved = await r2PutJSON(env, stateKey, state);
          if (!saved) return json({ success: false, error: "Could not save notification state." }, 503);
          return json({ success: true, read_ids: state.read, dismissed_ids: state.dismissed }, 200, { "Cache-Control": "no-store, private" });
        }
        if (request.method !== "GET") {
          return json({ success: false, error: "Method not allowed" }, 405, { Allow: "GET, POST" });
        }

        const notificationState = stateKey
          ? await r2GetJSON(env, stateKey, { read: [], dismissed: [] }).catch(() => ({ read: [], dismissed: [] }))
          : { read: [], dismissed: [] };
        const readIds = new Set(Array.isArray(notificationState.read) ? notificationState.read.map(String) : []);
        const dismissedIds = new Set(Array.isArray(notificationState.dismissed) ? notificationState.dismissed.map(String) : []);
        const decorateNotifications = list => (Array.isArray(list) ? list : [])
          .filter(item => !dismissedIds.has(String(item.id || "")))
          .map(item => ({ ...item, read: readIds.has(String(item.id || "")) }));
        const proxyHeaders = { "Accept": "application/json" };
        if (session?.userId) proxyHeaders["X-User-ID"] = session.userId;
        // Personal feed activity rides along with the product announcements the
        // panel already renders, so one bell covers both.
        const [feedItems, accountNotificationPrefs, followNotificationPrefs] = session?.userId
          ? await Promise.all([
              readFeedNotifications(env, session.userId).catch(() => []),
              readProfileSettings(env, session.userId).then(settings => settings.notification_prefs || {}).catch(() => ({})),
              readFollowPrefs(env, session.userId).catch(() => ({})),
            ])
          : [[], {}, {}];

        try {
          const response = await fetch(`${BOT_API}/api/notifications`, {
            headers: proxyHeaders,
            signal: AbortSignal.timeout(4000),
          });
          if (response.ok) {
            const payload = await response.json();
            if (payload?.success && Array.isArray(payload.notifications)) {
              const notifications = filterAccountNotifications(mergeFeedNotifications(normalizeProductNotifications(payload.notifications), feedItems), accountNotificationPrefs, followNotificationPrefs);
              return json({ ...payload, notifications: decorateNotifications(notifications), read_ids: [...readIds], dismissed_ids: [...dismissedIds] }, 200, { "Cache-Control": "no-store, private" });
            }
            console.error("Bot notifications API returned an invalid payload");
          } else if (response.status < 500) {
            return new Response(await response.text(), {
              status: response.status,
              headers: { ...corsHeaders, "Content-Type": response.headers.get("Content-Type") || "application/json" },
            });
          } else {
            console.warn("Bot notifications API failed; serving storage fallback:", response.status);
          }
        } catch (error) {
          console.warn("Bot notifications API unavailable; serving storage fallback:", error?.message || String(error));
        }

        try {
          if (!env.STORAGE) throw new Error("Server storage is unavailable");
          const notificationObject = await env.STORAGE.get("database/notifications.json");
          const storedNotifications = notificationObject ? await notificationObject.json() : [];
          if (!Array.isArray(storedNotifications)) throw new Error("Server notifications data is invalid");

          const userId = String(session?.userId || "");
          const notifications = storedNotifications
            .filter(item => item && typeof item === "object" &&
              (userId
                ? [undefined, null, ""].includes(item.user_id) || String(item.user_id) === userId
                : [undefined, null, ""].includes(item.user_id)))
            .map(item => ({
              id: String(item.id || ""),
              title: String(item.title || ""),
              desc: String(item.desc || ""),
              link: String(item.link || "/"),
              icon: String(item.icon || "fa-bell"),
              icon_brand: Boolean(item.icon_brand),
              bg: String(item.bg || "linear-gradient(135deg, var(--zr-accent, rgba(var(--zr-rgb-255-43-82, 255, 43, 82), 1)), rgba(var(--zr-rgb-139-0-40, 139, 0, 40), 1))"),
              color: String(item.color || "#fff"),
              category: String(item.category || "announcement"),
              created_at: String(item.created_at || ""),
            }))
            .filter(item => item.id);

          try {
            const products = await dbReadProductCatalog(env);
            for (const product of products.filter(item => item?.id && !isScenepackProduct(item)).slice(0, 8)) {
              const type = String(product.type || "").toLowerCase();
              let category = "resource";
              let link = `/leak?id=${encodeURIComponent(product.id)}`;
              let icon = "fa-fire";
              let bg = "linear-gradient(135deg, var(--zr-accent, rgba(var(--zr-rgb-255-43-82, 255, 43, 82), 1)), var(--zr-accent-soft, rgba(var(--zr-rgb-255-117-143, 255, 117, 143), 1)))";
              if (type === "scenepack") {
                category = "scenepack";
                link = `/product-scenepack?id=${encodeURIComponent(product.id)}`;
                icon = "fa-film";
                bg = "linear-gradient(135deg, #06b6d4, #0891b2)";
              } else if (type === "audio") {
                category = "audio";
                link = `/product-audio?id=${encodeURIComponent(product.id)}`;
                icon = "fa-music";
                bg = "linear-gradient(135deg, #a855f7, #7e22ce)";
              } else if (type === "plugin" || type === "software") {
                category = "plugin";
                link = `/product?id=${encodeURIComponent(product.id)}`;
                icon = "fa-puzzle-piece";
                bg = "linear-gradient(135deg, #a855f7, #6b21a8)";
              }
              const name = String(product.name || "Product");
              notifications.push({
                id: `prod_${product.id}`,
                // Anything that is not a scenepack, audio or plugin is served as a
                // leak, so it must never be announced as a preset or a resource.
                title: `New ${type === "scenepack" ? "Scenepack" : type === "audio" ? "Audio" : type === "plugin" || type === "software" ? (type === "plugin" ? "Plugin" : "Software") : "Leak"}: ${name}`,
                desc: `${name} is now available in ${String(product.category || "our catalog")}!`,
                link,
                icon,
                icon_brand: false,
                bg,
                color: "#fff",
                category,
                created_at: String(product.created_at || ""),
              });
            }
          } catch (error) {
            console.error("Storage product notifications unavailable:", error?.message || String(error));
          }

          notifications.sort((a, b) => b.created_at.localeCompare(a.created_at));
          const uniqueNotifications = [];
          const seenIds = new Set();
          for (const notification of notifications) {
            if (seenIds.has(notification.id)) continue;
            seenIds.add(notification.id);
            uniqueNotifications.push(notification);
            if (uniqueNotifications.length === 20) break;
          }
          const fallbackNotifications = filterAccountNotifications(mergeFeedNotifications(normalizeProductNotifications(uniqueNotifications), feedItems), accountNotificationPrefs, followNotificationPrefs);
          return json({ success: true, notifications: decorateNotifications(fallbackNotifications), read_ids: [...readIds], dismissed_ids: [...dismissedIds], source: "r2-fallback" }, 200, {
            "Cache-Control": "no-store, private",
          });
        } catch (error) {
          console.error("Storage notifications fallback failed:", error?.message || String(error));
          return json({ success: false, error: "Notifications are temporarily unavailable" }, 503, {
            "Cache-Control": "no-store",
            "Retry-After": "10",
          });
        }
      }

      // /api/search/creator-index — serve from R2 creator index
      if (path === "/api/search/creator-index" || path.startsWith("/api/search/creator")) {
        try {
          const indexData = await dbGetCreatorIndex(env);
          return json(indexData);
        } catch(e) {
          return json({ success: false, index: {} });
        }
      }
      // ─────────────────────────────────────────────────────────────────────────

      // Bulk rename: every profile handle becomes the member's own Discord username
      // (@username in the URL). Admin only; ?dry_run=1 previews without writing.
      if (path === "/api/admin/profiles/handles/sync" && request.method === "POST") {
        if (!isAdminRequest(request, env, hasMasterKey)) {
          return json({ success: false, error: "Unauthorized" }, 403);
        }
        let body = {};
        try { body = await request.json(); } catch (_) { body = {}; }
        const dryRun = /^(1|true|yes)$/i.test(String(url.searchParams.get("dry_run") || (body && body.dry_run) || ""));
        try {
          const result = await syncProfileHandles(env, { dryRun });
          await logModerationEvent(env, {
            kind: "profile",
            level: "info",
            actor: (parseSession(null, request) || {}).userId || "master",
            action: dryRun ? "handles-sync-preview" : "handles-sync",
            changed: result.changed,
          }).catch(() => false);
          return json(result, 200, { "Cache-Control": "no-store" });
        } catch (error) {
          console.error("Profile handle sync failed:", error?.message || String(error));
          return json({ success: false, error: "The handle sync could not be completed." }, 503);
        }
      }

      // Rebuilding is cheap enough to expose to staff and to the bot's timer.
      if (path === "/api/admin/profiles/refresh" && request.method === "POST") {
        const auth = request.headers.get("Authorization") || "";
        const allowedRelayTokens = [env.DISCORD_BOT_TOKEN, env.SITE_LOG_BOT_TOKEN].filter(Boolean);
        const isBot = allowedRelayTokens.some(token => auth === `Bot ${token}`);
        if (!isBot && !isAdminRequest(request, env, hasMasterKey)) {
          return json({ success: false, error: "Unauthorized" }, 403);
        }
        try {
          const aggregates = await readProfileAggregates(env, { force: true });
          return json({ success: true, built_at: aggregates.built_at, totals: aggregates.totals });
        } catch (error) {
          console.error("Profile aggregate refresh failed:", error?.message || String(error));
          return json({ success: false, error: "Could not rebuild profile aggregates" }, 503);
        }
      }

      // ── Download tracing diagnostic (staff only) ────────────────────────────
      // Runs the real tracer over a stored preset and reports whether the copy a member
      // would receive still names them after the visible credit is deleted. This is how
      // tracing is proven live, since a full download needs a signed-in member.
      if (path === "/api/admin/trace-probe" && request.method === "POST") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        let probeBody = {};
        try { probeBody = await request.json(); } catch (_) { probeBody = {}; }
        const probeKey = String(probeBody?.key || "").trim();
        const probeId = String(probeBody?.discord_id || "").trim() || ADMIN_IDS[0];
        if (!probeKey) return json({ success: false, error: "A storage key is required" }, 400);
        try {
          const object = await r2Get(env, probeKey, true);
          if (!object || !object.body) return json({ success: false, error: "No such object" }, 404);
          const original = new Uint8Array(await object.arrayBuffer());
          const marked = traceDownloadBytes(original, probeKey, probeId);
          if (!marked) {
            return json({
              success: true, traced: false, bytes: original.length, member: probeId,
              reason: /\.ffx$/i.test(probeKey)
                ? "not a traceable preset (no credit, or unsupported container)"
                : /\.txt$/i.test(probeKey)
                  ? "no credit marker found in this text resource"
                  : "not a traceable resource type",
            }, 200, { "Cache-Control": "no-store, private" });
          }
          const decoded = traceFindMark(marked);
          return json({
            success: true,
            traced: true,
            member: probeId,
            bytes: original.length,
            traced_bytes: marked.length,
            growth: marked.length - original.length,
            decoded_id: decoded ? decoded.id : null,
            roundtrip_ok: Boolean(decoded && decoded.id === probeId),
          }, 200, { "Cache-Control": "no-store, private" });
        } catch (error) {
          console.error("Trace probe failed:", error?.message || String(error));
          return json({ success: false, error: "Could not trace that object" }, 503);
        }
      }

      // ── Access control console (staff only) ─────────────────────────────────
      if (path === "/api/admin/access/overview" && request.method === "GET") {
        if (!isAdminRequest(request, env, hasMasterKey)) {
          return json({ success: false, error: "Unauthorized" }, 403);
        }
        try {
          const roster = await buildAccessRoster(env);
          const filtered = filterAccessRows(roster.rows, {
            filter: String(url.searchParams.get("filter") || "all"),
            query: String(url.searchParams.get("q") || ""),
          });
          const limit = Math.min(Math.max(Number(url.searchParams.get("limit")) || 50, 1), 200);
          const offset = Math.max(Number(url.searchParams.get("offset")) || 0, 0);
          const page = filtered.slice(offset, offset + limit);
          // Only the visible page is enriched, so the summary stays cheap.
          await enrichAccessNames(env, page);
          return json({
            success: true,
            summary: summarizeAccessRoster(roster),
            total: filtered.length,
            limit,
            offset,
            filters: ACCESS_FILTERS,
            rows: page,
          }, 200, { "Cache-Control": "no-store, private" });
        } catch (error) {
          console.error("Access overview failed:", error?.message || String(error));
          return json({ success: false, error: "Could not build the access overview" }, 503);
        }
      }

      if (path === "/api/admin/access/member" && request.method === "GET") {
        if (!isAdminRequest(request, env, hasMasterKey)) {
          return json({ success: false, error: "Unauthorized" }, 403);
        }
        try {
          const dossier = await buildAccessDossier(env, url.searchParams.get("id"));
          if (!dossier) return json({ success: false, error: "A valid member id is required" }, 400);
          return json({ success: true, ...dossier }, 200, { "Cache-Control": "no-store, private" });
        } catch (error) {
          console.error("Access dossier failed:", error?.message || String(error));
          return json({ success: false, error: "Could not build that member dossier" }, 503);
        }
      }

      // Both actions reuse the same helpers the bot calls, so a change made here
      // behaves exactly like one made from Discord.
      if (path === "/api/admin/access/revoke" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!isAdminRequest(request, env, hasMasterKey)) {
          return json({ success: false, error: "Unauthorized" }, 403);
        }
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON" }, 400); }
        const targetId = String(body?.id || "").trim();
        if (!/^\d{15,25}$/.test(targetId)) return json({ success: false, error: "A valid member id is required" }, 400);
        const reason = REVOKE_REASON_LABELS[String(body?.reason || "manual")] ? String(body.reason || "manual") : "manual";
        if (targetId === (session ? session.userId : "")) {
          return json({ success: false, error: "You cannot revoke your own access." }, 400);
        }
        // Staff accounts are protected: an accidental revoke of the founder would be
        // unrecoverable from the console itself.
        if (ADMIN_IDS.includes(targetId)) {
          return json({ success: false, error: "That member is a protected admin." }, 403);
        }
        const revoked = await revokeUserAccess(env, [targetId], {
          reason,
          roleId: VERIFIED_ROLE_ID,
          source: "admin-console",
          // A console click is a human decision: it replaces any older record and
          // must never be healed by role evidence.
          sticky: true,
          override: true,
        });
        const removedFromSnapshot = await removeUsersFromRoleSnapshot(env, VERIFIED_ROLE_ID, [targetId]);
        invalidateAccessPassMemo();
        const users = await readRevocationUsers(env);
        return json({
          success: true,
          revoked: revoked.revoked.length,
          already_revoked: revoked.kept.length,
          removed_from_snapshot: removedFromSnapshot,
          reason,
          reason_label: REVOKE_REASON_LABELS[reason] || reason,
          record: revocationSummary(users[targetId]),
        }, 200, { "Cache-Control": "no-store, private" });
      }

      if (path === "/api/admin/access/restore" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!isAdminRequest(request, env, hasMasterKey)) {
          return json({ success: false, error: "Unauthorized" }, 403);
        }
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON" }, 400); }
        const targetId = String(body?.id || "").trim();
        if (!/^\d{15,25}$/.test(targetId)) return json({ success: false, error: "A valid member id is required" }, 400);
        const current = (await readRevocationUsers(env))[targetId];
        const sticky = Boolean(current && STRONG_REVOKE_REASONS.has(current.reason));
        const restored = await restoreUserAccess(env, [targetId], { force: true });
        // Put them back in the snapshot so the fast path can admit them again.
        const returned = restored.restored.length
          ? await addUsersToRoleSnapshot(env, VERIFIED_ROLE_ID, restored.restored)
          : 0;
        invalidateAccessPassMemo();
        return json({
          success: true,
          restored: restored.restored.length,
          still_revoked: restored.kept.length,
          returned_to_snapshot: returned,
          lifted_sticky: Boolean(sticky && restored.restored.length),
        }, 200, { "Cache-Control": "no-store, private" });
      }


      // Diagnostics for the Discord card: which media sources resolve?
      if (path === "/api/admin/feed/card-probe" && request.method === "GET") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        const raw = String(url.searchParams.get("url") || "").trim().slice(0, 400);
        const resolved = raw.startsWith("/api/avatar/") ? discordAvatarCdn(raw) : absoluteMediaUrl(raw);
        const out = { input: raw.slice(0, 120), resolved: String(resolved || "").slice(0, 160) };
        try {
          const image = await fetchImageBytes(env, raw, FEED_CARD_MEDIA_LIMIT, { timeout: 7000 });
          out.bytes = image ? image.bytes.length : 0;
          out.type = image ? image.type : "";
        } catch (error) {
          out.error = String(error?.message || error);
        }
        try {
          const dataUrl = await fetchImageAsDataUrl(env, raw, FEED_CARD_AVATAR_LIMIT);
          out.data_url = dataUrl ? dataUrl.length : 0;
        } catch (error) {
          out.data_error = String(error?.message || error);
        }
        return json({ success: true, ...out }, 200, { "Cache-Control": "no-store" });
      }

      // ── Word filter (shared with the Discord bot) ────────────────────────────
      // The list lives in R2 so the site and the moderation bot block the same words.
      if (path === "/api/admin/moderation/words" || path === "/api/admin/moderation/words/import") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!hasMasterKey && !isAdminSession(session)) {
          return json({ success: false, error: "Admins only.", code: "ADMIN_ONLY" }, 403);
        }
        if (request.method === "GET") {
          const filter = await readWordFilter(env);
          return json({ success: true, filter, key: WORD_FILTER_KEY }, 200, { "Cache-Control": "no-store" });
        }
        if (request.method === "POST") {
          const body = await request.json().catch(() => null);
          if (!body || typeof body !== "object") return json({ success: false, error: "Invalid JSON." }, 400);
          let words = body.words;
          let allowlist = body.allowlist;
          if (path.endsWith("/import")) {
            // Accepts the bot's database.json ({"badwords": [...]}) or a raw text blob.
            const raw = typeof body.raw === "string" ? body.raw : "";
            let parsed = null;
            try { parsed = JSON.parse(raw); } catch (_) { parsed = null; }
            const fromJson = parsed && Array.isArray(parsed.badwords) ? parsed.badwords : null;
            const fromText = raw.split(/[\n,]+/).map(value => value.trim()).filter(Boolean);
            const imported = fromJson || fromText;
            if (!imported || !imported.length) return json({ success: false, error: "No words found in that import." }, 400);
            const mode = String(body.mode || "merge").toLowerCase();
            const current = await readWordFilter(env);
            words = mode === "replace" ? imported : current.words.concat(imported);
            allowlist = current.allowlist;
          }
          if (!Array.isArray(words)) return json({ success: false, error: "words must be an array." }, 400);
          const filter = await writeWordFilter(env, cleanWordList(words), allowlist === undefined ? undefined : cleanWordList(allowlist), "site");
          if (!filter) return json({ success: false, error: "Could not save the word filter." }, 503);
          return json({ success: true, filter }, 200, { "Cache-Control": "no-store" });
        }
      }

      // ── Feed admin ────────────────────────────────────────────────────────────
      // ── Admin: plugin product panel ─────────────────────────────────────────
      if (path === "/api/admin/products" && request.method === "GET") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        const doc = await readProductOverrides(env, { fresh: true });
        const items = doc.items || {};
        return json({
          success: true,
          version: doc.version,
          updated_at: doc.updated_at,
          total: Object.keys(items).length,
          items,
        }, 200, { "Cache-Control": "no-store" });
      }

      if (path === "/api/admin/content" && request.method === "GET") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        try {
          const [catalog, overrides] = await Promise.all([
            dbReadProductCatalog(env),
            readProductOverrides(env, { fresh: true }),
          ]);
          return json({ success: true, catalog, overrides: overrides.items || {}, version: overrides.version || 0 }, 200, { "Cache-Control": "no-store, private" });
        } catch (error) {
          return json({ success: false, error: "Could not load the product catalogue." }, 503);
        }
      }

      if (path === "/api/admin/content/item" && request.method === "POST") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        const body = await request.json().catch(() => null);
        if (!body || typeof body !== "object") return json({ success: false, error: "Invalid content item." }, 400);
        const id = String(body.id || "").trim();
        const kind = String(body.kind || "catalog");
        const actor = parseSession(null, request)?.userId || "master";
        const allowed = ["name", "title", "description", "category", "resource_category", "resource_subcategories", "platform", "thumbnail", "banner", "version", "release_date", "origin", "file_path", "file_url", "source_url", "product_url", "links", "password", "zip_password", "type", "hidden", "sort_order"];
        const patch = {};
        for (const key of allowed) if (Object.prototype.hasOwnProperty.call(body.patch || {}, key)) patch[key] = body.patch[key];
        if (kind === "plugin") {
          if (!/^[A-Za-z0-9_.:-]{1,120}$/.test(id)) return json({ success: false, error: "Invalid product id." }, 400);
          const saved = await saveProductOverride(env, id, patch, { actor, hidden: body.hidden === true, action: "update" });
          if (!saved.saved) return json({ success: false, error: "Could not save plugin/software changes." }, 503);
          return json({ success: true, id, kind, entry: saved.entry, version: saved.version });
        }
        if (kind !== "catalog") return json({ success: false, error: "Invalid product kind." }, 400);
        const productId = id || generateId("prod");
        if (!/^[A-Za-z0-9_-]{1,100}$/.test(productId)) return json({ success: false, error: "Invalid product id." }, 400);
        const existing = await dbGetProduct(env, productId).catch(() => null);
        try {
          let saved;
          if (existing) {
            saved = await dbUpdateProduct(env, productId, { ...patch, is_hidden: body.hidden === true });
          } else {
            const name = String(patch.name || patch.title || "").trim();
            if (!name) return json({ success: false, error: "A name is required for new products." }, 400);
            saved = await dbAddProduct(env, { ...patch, id: productId, name, type: String(patch.type || "resource").toLowerCase(), is_hidden: body.hidden === true, created_at: new Date().toISOString() });
          }
          if (!saved) return json({ success: false, error: "Could not save product." }, 503);
          const visibility = await saveProductOverride(env, productId, {}, { actor, hidden: body.hidden === true, action: "visibility" });
          if (!visibility.saved) return json({ success: false, error: "Product saved, but visibility could not be updated." }, 503);
          await appendProductAudit(env, { at: new Date().toISOString(), actor, id: productId, action: existing ? "update-catalog" : "create-catalog", changed: Object.keys(patch), before: existing });
          return json({ success: true, id: productId, kind, item: saved });
        } catch (error) {
          return json({ success: false, error: "Could not save product." }, 503);
        }
      }

      const contentDeleteMatch = path.match(/^\/api\/admin\/content\/([^/]+)$/);
      if (contentDeleteMatch && request.method === "DELETE") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        let id;
        try { id = decodeURIComponent(contentDeleteMatch[1]); } catch (_) { return json({ success: false, error: "Invalid id." }, 400); }
        const kind = String(url.searchParams.get("kind") || "catalog");
        const actor = parseSession(null, request)?.userId || "master";
        if (kind === "plugin") {
          const saved = await saveProductOverride(env, id, {}, { actor, hidden: true, deleted: true, action: "delete" });
          if (!saved.saved) return json({ success: false, error: "Could not delete plugin/software item." }, 503);
          return json({ success: true, deleted: true, id });
        }
        const before = await dbGetProduct(env, id).catch(() => null);
        const deleted = await dbDeleteProduct(env, id).catch(() => false);
        if (!deleted) return json({ success: false, error: "Product not found." }, 404);
        await appendProductAudit(env, { at: new Date().toISOString(), actor, id, action: "delete-catalog", before });
        return json({ success: true, deleted: true, id });
      }

      if (path === "/api/admin/content/upload" && request.method === "POST") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        let form;
        try { form = await request.formData(); } catch (_) { return json({ success: false, error: "Upload form is invalid." }, 400); }
        const file = form.get("file");
        const kind = String(form.get("kind") || "");
        const id = String(form.get("id") || "").trim();
        if (!file || typeof file.arrayBuffer !== "function" || !id) return json({ success: false, error: "A file and product id are required." }, 400);
        const name = String(file.name || "file").replace(/[^a-zA-Z0-9_.-]/g, "_").slice(0, 120) || "file";
        if (file.size <= 0 || file.size > 90 * 1024 * 1024) return json({ success: false, error: "Files must be between 1 byte and 90 MB." }, 413);
        if (kind === "audio") {
          if (!/\.(mp3|wav|flac|ogg|m4a|aac)$/i.test(name)) return json({ success: false, error: "Unsupported audio format." }, 400);
          const key = `audio/${id}-${name}`;
          await env.STORAGE.put(key, file.stream(), { httpMetadata: { contentType: file.type || "application/octet-stream" } });
          return json({ success: true, key, url: `https://zyrexediting.xyz/api/audio/stream/${encodeURIComponent(id + "-" + name)}` });
        }
        if (kind !== "catalog" || !/^[A-Za-z0-9_-]{1,100}$/.test(id)) return json({ success: false, error: "Invalid upload kind or product id." }, 400);
        if (!/\.(aep|aepx|prproj|drp|setting|cube|mogrt)$/i.test(name)) return json({ success: false, error: "Unsupported direct leak upload format. Upload .ffx files and archives through the staging transfer flow so preset credit verification runs." }, 400);
        const key = `resources/admin/${id}/${name}`;
        await env.STORAGE.put(key, file.stream(), { httpMetadata: { contentType: file.type || "application/octet-stream" } });
        return json({ success: true, key, file_path: `resources/admin/${id}` });
      }

      if (path === "/api/admin/products/audit" && request.method === "GET") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        const rows = await r2GetJSON(env, PRODUCT_AUDIT_KEY, []).catch(() => []);
        const limit = Math.min(Math.max(Number(url.searchParams.get("limit")) || 100, 1), 200);
        return json({ success: true, items: (Array.isArray(rows) ? rows : []).slice(0, limit) },
          200, { "Cache-Control": "no-store" });
      }

      const productRestoreMatch = path.match(/^\/api\/admin\/products\/([^/]+)\/restore$/);
      if (productRestoreMatch && request.method === "POST") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        let productId;
        try { productId = decodeURIComponent(productRestoreMatch[1]).trim(); } catch (_) {
          return json({ success: false, error: "Invalid product id" }, 400);
        }
        const actor = (parseSession(null, request) || {}).userId || "master";
        const result = await clearProductOverride(env, productId, actor);
        if (!result.saved) return json({ success: false, error: "Could not restore that product." }, 503);
        return json({ success: true, id: productId, restored: true, removed: result.removed, version: result.version });
      }

      const productAdminMatch = path.match(/^\/api\/admin\/products\/([^/]+)$/);
      if (productAdminMatch && (request.method === "PUT" || request.method === "POST" || request.method === "DELETE")) {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        let productId;
        try { productId = decodeURIComponent(productAdminMatch[1]).trim(); } catch (_) {
          return json({ success: false, error: "Invalid product id" }, 400);
        }
        if (!/^[A-Za-z0-9_.:-]{1,120}$/.test(productId)) {
          return json({ success: false, error: "Invalid product id" }, 400);
        }
        const actor = (parseSession(null, request) || {}).userId || "master";

        if (request.method === "DELETE") {
          let removedFromCatalog = false;
          try { removedFromCatalog = await dbDeleteProduct(env, productId); } catch (_) {}
          const result = await saveProductOverride(env, productId, {}, {
            actor, deleted: true, hidden: true, action: "delete",
          });
          if (!result.saved) return json({ success: false, error: "Could not delete that product." }, 503);
          return json({
            success: true, deleted: true, id: productId,
            catalog_row_removed: Boolean(removedFromCatalog), version: result.version,
          });
        }

        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON" }, 400); }
        if (!body || typeof body !== "object" || Array.isArray(body)) {
          return json({ success: false, error: "Invalid payload" }, 400);
        }
        const result = await saveProductOverride(env, productId, body.patch, {
          actor,
          hidden: body.hidden,
          deleted: body.deleted,
          order: body.order === undefined ? undefined : Number(body.order) || null,
          expectedUpdatedAt: body.expected_updated_at,
          replace: body.replace === true,
        });
        if (result.stale) {
          return json({
            success: false,
            code: "STALE",
            error: "Another tab saved this product first. Reload and try again.",
            current: result.entry,
          }, 409);
        }
        if (!result.saved) return json({ success: false, error: "Could not save that product." }, 503);
        return json({ success: true, id: productId, entry: result.entry, version: result.version });
      }

      // Every route below needs an admin session (or the master key); the app key alone
      // is public, so it can never be enough on its own.
      if (path.startsWith("/api/admin/feed/")) {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!hasMasterKey && !isAdminSession(session)) {
          return json({ success: false, error: "Admins only.", code: "ADMIN_ONLY" }, 403);
        }
        const actorId = session ? session.userId : "master";

        if (path === "/api/admin/feed/overview" && request.method === "GET") {
          const index = await readFeedPostIndex(env).catch(() => ({ next: 1, entries: {} }));
          const hiddenIds = await readFeedHiddenIds(env).catch(() => new Set());
          const events = await listModerationEvents(env, 200).catch(() => []);
          const since = Date.now() - 7 * 24 * 60 * 60 * 1000;
          const recent = events.filter(event => Date.parse(event.at || "") >= since);
          const today = new Date().toISOString().slice(0, 10);
          return json({
            success: true,
            posts: Object.keys(index.entries || {}).length,
            posts_today: Object.values(index.entries || {}).filter(entry => String((entry && entry.created_at) || "").slice(0, 10) === today).length,
            hidden: hiddenIds.size,
            detections_7d: recent.filter(event => event.level === "nsfw").length,
            review_7d: recent.filter(event => event.level === "review").length,
            warnings_total: events.filter(event => event.warn_id).length,
            channel_id: String((env && env.FEED_CHANNEL_ID) || FEED_DISCORD_CHANNEL_ID),
          }, 200, { "Cache-Control": "no-store" });
        }

        if (path === "/api/admin/feed/posts" && request.method === "GET") {
          const page = Math.max(1, Number(url.searchParams.get("page")) || 1);
          const size = 20;
          const filter = String(url.searchParams.get("filter") || "all").toLowerCase();
          const query = String(url.searchParams.get("q") || "").trim().toLowerCase();
          const index = await readFeedPostIndex(env).catch(() => ({ next: 1, entries: {} }));
          const hiddenIds = await readFeedHiddenIds(env).catch(() => new Set());
          const entries = Object.entries(index.entries || {})
            .map(([seq, entry]) => ({ seq: Number(seq), ...entry }))
            .filter(entry => entry.post_id)
            .sort((a, b) => b.seq - a.seq);
          const events = await listModerationEvents(env, 200).catch(() => []);
          const flaggedPosts = new Set(events.filter(event => event.level === "nsfw" && event.post_id).map(event => String(event.post_id)));
          const loaded = await Promise.all(entries.slice(0, 150).map(entry =>
            readProfilePost(env, entry.author_id, entry.post_id).catch(() => null).then(post => ({ entry, post }))));
          const rows = [];
          for (const { entry, post } of loaded) {
            if (!post) continue;
            rows.push({
              id: post.id,
              seq: entry.seq || post.seq || 0,
              author_id: post.author_id,
              author: post.author || null,
              text: String(post.text || "").slice(0, 400),
              media: Array.isArray(post.media) ? post.media.length : 0,
              video: post.video || null,
              links: Array.isArray(post.links) ? post.links.length : 0,
              repost_of: post.repost_of || null,
              created_at: post.created_at,
              hidden: hiddenIds.has(String(post.id)),
              flagged: flaggedPosts.has(String(post.id)),
            });
          }
          const catalog = await dbReadProductCatalog(env).catch(() => []);
          const notices = (Array.isArray(catalog) ? catalog : [])
            .filter(product => isFeedAnnounceableProduct(product))
            .sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || "")))
            .slice(0, 120)
            .map(product => ({
              id: noticeHiddenId(product.id),
              product_id: String(product.id || ""),
              name: product.name || "",
              category: product.category || "",
              created_at: product.created_at || "",
              hidden: hiddenIds.has(noticeHiddenId(product.id)),
            }));
          const filtered = rows.filter(row => {
            if (query && !`${row.text} ${(row.author && row.author.name) || ""} ${row.author_id}`.toLowerCase().includes(query)) return false;
            if (filter === "hidden") return row.hidden;
            if (filter === "video") return Boolean(row.video);
            if (filter === "flagged") return Boolean(row.flagged);
            return true;
          });
          const pages = Math.max(1, Math.ceil(filtered.length / size));
          return json({
            success: true,
            page,
            pages,
            total: filtered.length,
            items: filtered.slice((page - 1) * size, page * size),
            notices,
          }, 200, { "Cache-Control": "no-store" });
        }

        if (path === "/api/admin/feed/posts/hide" && request.method === "POST") {
          const body = await request.json().catch(() => null);
          const targetId = String((body && body.id) || "").trim();
          if (!targetId) return json({ success: false, error: "A post id is required." }, 400);
          const hidden = Boolean(body && body.hidden);
          const saved = await setFeedHidden(env, targetId, hidden);
          if (!saved) return json({ success: false, error: "Could not update the feed." }, 503);
          await logModerationEvent(env, { kind: "feed", level: "admin", actor: actorId, post_id: targetId, action: hidden ? "hidden" : "unhidden" }).catch(() => false);
          return json({ success: true, id: targetId, hidden }, 200, { "Cache-Control": "no-store" });
        }

        if (path === "/api/admin/feed/notices/hide" && request.method === "POST") {
          const body = await request.json().catch(() => null);
          const productId = String((body && body.product_id) || "").trim();
          if (!productId) return json({ success: false, error: "A resource id is required." }, 400);
          const hidden = Boolean(body && body.hidden);
          const saved = await setFeedHidden(env, noticeHiddenId(productId), hidden);
          if (!saved) return json({ success: false, error: "Could not update the feed." }, 503);
          await logModerationEvent(env, { kind: "feed", level: "admin", actor: actorId, product_id: productId, action: hidden ? "notice-hidden" : "notice-shown" }).catch(() => false);
          return json({ success: true, product_id: productId, hidden }, 200, { "Cache-Control": "no-store" });
        }

        if (path === "/api/admin/feed/posts/delete" && request.method === "POST") {
          const body = await request.json().catch(() => null);
          const postId = String((body && body.id) || "").trim();
          if (!/^[a-f0-9-]{16,40}$/i.test(postId)) return json({ success: false, error: "Invalid post." }, 400);
          const entry = await findFeedPostEntry(env, postId).catch(() => null);
          const authorId = String((entry && entry.post && entry.post.author_id) || (entry && entry.author_id) || "").trim();
          if (!/^\d{15,25}$/.test(authorId)) return json({ success: false, error: "That post was not found." }, 404);
          const key = profilePostsKey(authorId);
          const stored = await r2GetJSON(env, key, null).catch(() => null);
          const posts = (Array.isArray(stored && stored.posts) ? stored.posts : []).map(post => sanitizeProfilePost(post, authorId)).filter(Boolean);
          const target = posts.find(post => post.id === postId);
          if (!target) return json({ success: false, error: "That post was not found." }, 404);
          await r2PutJSON(env, key, { version: 1, posts: posts.filter(post => post.id !== postId), updated_at: new Date().toISOString() });
          if (!target.repost_of) await r2DeleteKey(env, profileFeedPostKey(authorId, target)).catch(() => false);
          // Media that the post brought with it is removed from the bucket as well.
          const mediaUrls = [...(Array.isArray(target.media) ? target.media : []), target.video && target.video.url, target.video && target.video.poster].filter(Boolean);
          for (const mediaUrl of mediaUrls) {
            const fileName = String(mediaUrl).split("/").pop();
            if (fileName) await env.STORAGE.delete(`thumbnails/${fileName}`).catch(() => false);
          }
          await deleteFeedDiscordMessage(env, postId).catch(() => false);
          await setFeedHidden(env, postId, false).catch(() => false);
          await logModerationEvent(env, { kind: "feed", level: "admin", actor: actorId, post_id: postId, author_id: authorId, action: "deleted" }).catch(() => false);
          return json({ success: true, deleted: true, id: postId }, 200, { "Cache-Control": "no-store" });
        }

        if (path === "/api/admin/feed/posts/pin" && request.method === "POST") {
          const body = await request.json().catch(() => null);
          const postId = String((body && body.id) || "").trim();
          if (!/^[a-f0-9-]{16,40}$/i.test(postId)) return json({ success: false, error: "Invalid post." }, 400);
          const entry = await findFeedPostEntry(env, postId).catch(() => null);
          const authorId = String((entry && entry.post && entry.post.author_id) || "").trim();
          if (!/^\d{15,25}$/.test(authorId)) return json({ success: false, error: "That post was not found." }, 404);
          const settings = await readProfileSettings(env, authorId);
          const currentlyPinned = String(settings.pinned_post_id || "") === postId;
          const saved = await r2PutJSON(env, profileSettingsKey(authorId), {
            ...settings,
            pinned_post_id: currentlyPinned ? "" : postId,
            updated_at: new Date().toISOString(),
          });
          if (!saved) return json({ success: false, error: "Could not update the pin." }, 503);
          return json({ success: true, id: postId, pinned: !currentlyPinned }, 200, { "Cache-Control": "no-store" });
        }

        if (path === "/api/admin/feed/card/resend" && request.method === "POST") {
          const body = await request.json().catch(() => null);
          const postId = String((body && body.id) || "").trim();
          if (!/^[a-f0-9-]{16,40}$/i.test(postId)) return json({ success: false, error: "Invalid post." }, 400);
          const entry = await findFeedPostEntry(env, postId);
          if (!entry || !entry.post) return json({ success: false, error: "That post was not found." }, 404);
          await deleteFeedDiscordMessage(env, postId).catch(() => false);
          const sent = await postFeedPostToDiscord(env, entry.post, []);
          return json({ success: Boolean(sent), post_id: postId }, sent ? 200 : 502, { "Cache-Control": "no-store" });
        }

        if (path === "/api/admin/feed/moderation" && request.method === "GET") {
          const events = await listModerationEvents(env, Math.max(1, Number(url.searchParams.get("limit")) || MODERATION_LOG_PAGE)).catch(() => []);
          return json({ success: true, items: events }, 200, { "Cache-Control": "no-store" });
        }

        if (path === "/api/admin/feed/moderation/recheck" && request.method === "POST") {
          const body = await request.json().catch(() => null);
          const postId = String((body && body.id) || "").trim();
          if (!/^[a-f0-9-]{16,40}$/i.test(postId)) return json({ success: false, error: "Invalid post." }, 400);
          const entry = await findFeedPostEntry(env, postId);
          if (!entry || !entry.post) return json({ success: false, error: "That post was not found." }, 404);
          const targets = [...(entry.post.media || []), entry.post.video && entry.post.video.poster].filter(Boolean);
          const results = [];
          for (const target of targets) {
            const guard = await handleNsfwMedia(env, {
              userId: entry.post.author_id,
              url: target,
              kind: "recheck",
              deleteObject: () => env.STORAGE.delete(`thumbnails/${String(target).split("/").pop()}`),
            });
            results.push({ url: target, blocked: guard.blocked, review: Boolean(guard.review), score: guard.score || 0 });
          }
          return json({ success: true, results }, 200, { "Cache-Control": "no-store" });
        }

        // Staff can lift a posting block early; the block itself is never shown to the member.
        if (path === "/api/admin/feed/bans" && (request.method === "GET" || request.method === "DELETE")) {
          const userId = String(url.searchParams.get("user_id") || "").trim();
          if (!/^\d{15,25}$/.test(userId)) return json({ success: false, error: "A member id is required." }, 400);
          const ban = await readFeedBan(env, userId);
          if (request.method === "GET") {
            return json({ success: true, ban }, 200, { "Cache-Control": "no-store" });
          }
          await env.STORAGE.delete(feedBanKey(userId)).catch(() => false);
          if (ban) await logModerationEvent(env, { kind: "feed-ban", level: "admin", actor: actorId, user_id: userId, action: "cleared" }).catch(() => false);
          return json({ success: true, cleared: Boolean(ban) }, 200, { "Cache-Control": "no-store" });
        }

        // Runs the site classifier against one image so the panel can prove it works.
        if (path === "/api/admin/feed/nsfw-probe" && (request.method === "POST" || request.method === "GET")) {
          const body = request.method === "POST" ? await request.json().catch(() => null) : null;
          const target = String((body && body.url) || url.searchParams.get("url") || "").trim();
          if (!target) return json({ success: false, error: "An image url is required." }, 400);
          // ?model= overrides the chain so a new model can be tried without a deploy.
          const override = String((body && body.model) || url.searchParams.get("model") || "").trim();
          const scopedEnv = override ? { ...env, NSFW_AI_MODEL: override } : env;
          let result;
          try {
            result = await classifyImageOnSite(scopedEnv, target);
          } catch (error) {
            return json({
              success: false,
              ai_binding: Boolean(env && env.AI),
              error: String((error && error.message) || error).slice(0, 300),
              stack: String((error && error.stack) || "").split("\n").slice(0, 4),
            }, 200, { "Cache-Control": "no-store" });
          }
          return json({
            success: true,
            ai_binding: Boolean(env && env.AI),
            models: nsfwVerdictModels(scopedEnv),
            used: result.model || "",
            result,
          }, 200, { "Cache-Control": "no-store" });
        }

        // Warnings are owned by the moderation bot, so the panel only proxies to it.
        if (path === "/api/admin/feed/warns" && (request.method === "GET" || request.method === "POST")) {
          const headers = {
            "X-User-ID": String((session && session.userId) || ADMIN_IDS[0] || ""),
            "X-User-Is-Admin": "true",
            "X-User-Name": String((session && session.username) || "Feed Admin"),
          };
          if (request.method === "GET") {
            const userId = String(url.searchParams.get("user_id") || "").trim();
            if (!/^\d{15,25}$/.test(userId)) return json({ success: false, error: "A member id is required." }, 400);
            const response = await fetch(`${BOT_API}/api/guild/members/warns?user_id=${encodeURIComponent(userId)}`, {
              headers,
              signal: AbortSignal.timeout(8000),
            }).catch(() => null);
            if (!response || !response.ok) return json({ success: false, error: "The moderation bot is unreachable." }, 502);
            const data = await response.json().catch(() => null);
            return json({ success: true, warnings: (data && data.warnings) || [], total: Number(data && data.total) || 0 }, 200, { "Cache-Control": "no-store" });
          }
          const body = await request.json().catch(() => null);
          const userId = String((body && body.user_id) || "").trim();
          const reason = String((body && body.reason) || "").trim().slice(0, 300);
          if (!/^\d{15,25}$/.test(userId) || !reason) return json({ success: false, error: "A member id and a reason are required." }, 400);
          const response = await fetch(`${BOT_API}/api/guild/members/warn`, {
            method: "POST",
            headers: { ...headers, "Content-Type": "application/json" },
            body: JSON.stringify({ user_id: userId, reason, send_dm: body && body.send_dm !== false }),
            signal: AbortSignal.timeout(12000),
          }).catch(() => null);
          if (!response || !response.ok) return json({ success: false, error: "The moderation bot is unreachable." }, 502);
          const data = await response.json().catch(() => null);
          await logModerationEvent(env, { kind: "warning", level: "admin", actor: actorId, user_id: userId, reason, warn_id: (data && data.warn_id) || "" }).catch(() => false);
          return json({ success: Boolean(data && data.success), warn_id: (data && data.warn_id) || "", total_warns: Number(data && data.total_warns) || 0, timed_out: Boolean(data && data.timed_out) }, 200, { "Cache-Control": "no-store" });
        }

        if (path.startsWith("/api/admin/feed/warns/") && request.method === "DELETE") {
          const warnId = decodeURIComponent(path.slice("/api/admin/feed/warns/".length)).trim();
          const userId = String(url.searchParams.get("user_id") || "").trim();
          if (!warnId || !/^\d{15,25}$/.test(userId)) return json({ success: false, error: "A warning id and member id are required." }, 400);
          const response = await fetch(`${BOT_API}/api/guild/members/warns/${encodeURIComponent(warnId)}?user_id=${encodeURIComponent(userId)}`, {
            method: "DELETE",
            headers: { "X-User-ID": String((session && session.userId) || ADMIN_IDS[0] || ""), "X-User-Is-Admin": "true" },
            signal: AbortSignal.timeout(8000),
          }).catch(() => null);
          if (!response || !response.ok) return json({ success: false, error: "The moderation bot is unreachable." }, 502);
          return json({ success: true, warn_id: warnId }, 200, { "Cache-Control": "no-store" });
        }

        if (path === "/api/admin/feed/settings") {
          if (request.method === "GET") {
            const settings = await readModerationSettings(env);
            return json({ success: true, settings, defaults: DEFAULT_MODERATION_SETTINGS }, 200, { "Cache-Control": "no-store" });
          }
          if (request.method === "POST") {
            const body = await request.json().catch(() => null);
            if (!body || typeof body !== "object") return json({ success: false, error: "Invalid JSON." }, 400);
            const current = await readModerationSettings(env);
            const next = { ...current };
            if (Array.isArray(body.textStems)) next.textStems = body.textStems.map(value => String(value || "").trim()).filter(Boolean).slice(0, 300);
            if (Array.isArray(body.allowedWords)) next.allowedWords = body.allowedWords.map(value => String(value || "").trim().toLowerCase()).filter(Boolean).slice(0, 300);
            if (body.imageThreshold !== undefined) next.imageThreshold = Math.min(Math.max(Number(body.imageThreshold) || 0.6, 0.2), 0.95);
            if (body.autoDelete !== undefined) next.autoDelete = Boolean(body.autoDelete);
            if (body.autoWarn !== undefined) next.autoWarn = Boolean(body.autoWarn);
            if (body.failOpen !== undefined) next.failOpen = Boolean(body.failOpen);
            if (body.imageClassifier !== undefined) next.imageClassifier = String(body.imageClassifier || "").toLowerCase() === "bot" ? "bot" : "site";
            const saved = await r2PutJSON(env, MODERATION_SETTINGS_KEY, { version: 1, ...next, updated_at: new Date().toISOString() }).catch(() => false);
            if (Array.isArray(body.textStems) || Array.isArray(body.allowedWords)) {
              await writeWordFilter(env, next.textStems, next.allowedWords, "site").catch(() => null);
            }
            invalidateModerationSettings();
            if (!saved) return json({ success: false, error: "Could not save the settings." }, 503);
            return json({ success: true, settings: next }, 200, { "Cache-Control": "no-store" });
          }
        }


        if (path === "/api/admin/feed/resend-card" && request.method === "POST") {
          const body = await request.json().catch(() => null);
          const postId = String((body && body.post_id) || "").trim();
          if (!/^[a-f0-9-]{16,40}$/i.test(postId)) return json({ success: false, error: "Invalid post." }, 400);
          const entry = await findFeedPostEntry(env, postId);
          if (!entry || !entry.post) return json({ success: false, error: "That post was not found." }, 404);
          await deleteFeedDiscordMessage(env, postId).catch(() => false);
          const sent = await postFeedPostToDiscord(env, entry.post, []);
          return json({ success: Boolean(sent), post_id: postId }, sent ? 200 : 502, { "Cache-Control": "no-store" });
        }
      }

      // Re-renders one post's card: cards are images, so a renderer change needs a resend.
      if (path === "/api/admin/feed/resend-card" && request.method === "POST") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON." }, 400); }
        const postId = String((body && body.post_id) || "").trim();
        if (!/^[a-f0-9-]{16,40}$/i.test(postId)) return json({ success: false, error: "Invalid post." }, 400);
        const entry = await findFeedPostEntry(env, postId);
        if (!entry || !entry.post) return json({ success: false, error: "That post was not found." }, 404);
        await deleteFeedDiscordMessage(env, postId).catch(() => false);
        const sent = await postFeedPostToDiscord(env, entry.post, []);
        return json({ success: Boolean(sent), post_id: postId }, sent ? 200 : 502, { "Cache-Control": "no-store" });
      }

      // Is the feed channel showing rendered cards? Reports the newest message.
      if (path === "/api/admin/feed/discord-probe" && request.method === "GET") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        const token = getSiteLogBotToken(env);
        if (!token) return json({ success: false, reason: "missing_token" }, 200, { "Cache-Control": "no-store" });
        const channelId = String((env && env.FEED_CHANNEL_ID) || FEED_DISCORD_CHANNEL_ID);
        try {
          // ?post=<post id> reports that post's message instead of the newest one.
          const postParam = String(url.searchParams.get("post") || "").trim();
          let messageId = String(url.searchParams.get("message") || "").trim();
          if (!messageId && /^[a-f0-9-]{16,40}$/i.test(postParam)) {
            const stored = await r2GetJSON(env, feedMessageKey(postParam), null).catch(() => null);
            messageId = String((stored && stored.message_id) || "").trim();
          }
          const endpoint = messageId
            ? `${DISCORD_API}/channels/${channelId}/messages/${encodeURIComponent(messageId)}`
            : `${DISCORD_API}/channels/${channelId}/messages?limit=1`;
          const response = await fetch(endpoint, {
            headers: { Authorization: `Bot ${token}` },
            signal: AbortSignal.timeout(6000),
          });
          if (!response.ok) return json({ success: false, status: response.status }, 200, { "Cache-Control": "no-store" });
          const rows = await response.json().catch(() => []);
          const message = Array.isArray(rows) ? rows[0] : (messageId ? rows : null);
          if (!message) return json({ success: false, reason: "empty_channel" }, 200, { "Cache-Control": "no-store" });
          return json({
            success: true,
            message_id: String(message.id || ""),
            content: String(message.content || "").slice(0, 120),
            embeds: Array.isArray(message.embeds) ? message.embeds.length : 0,
            attachments: (Array.isArray(message.attachments) ? message.attachments : []).map(item => ({
              filename: String(item.filename || ""),
              content_type: String(item.content_type || ""),
              size: Number(item.size) || 0,
              width: Number(item.width) || 0,
              height: Number(item.height) || 0,
              url: String(item.url || ""),
            })),
              // Buttons live in components; the admin panel and tests read them back.
              components: (Array.isArray(message.components) ? message.components : []).map(row => ({
                type: Number(row.type) || 0,
                buttons: (Array.isArray(row.components) ? row.components : []).map(button => ({
                  label: String(button.label || ""),
                  url: String(button.url || ""),
                  style: Number(button.style) || 0,
                })),
              })),
              created_at: message.timestamp || "",
          }, 200, { "Cache-Control": "no-store" });
        } catch (error) {
          return json({ success: false, reason: "network", error: publicErrorMessage(error) }, 200, { "Cache-Control": "no-store" });
        }
      }

      // Answers "is the Scrapin key wired?" with the real upstream response.
      if (path === "/api/admin/scrapin/probe" && request.method === "GET") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        const platformKey = String(url.searchParams.get("platform") || "tiktok").toLowerCase();
        const username = String(url.searchParams.get("username") || "").replace(/^@+/, "").slice(0, 60);
        const apiKey = String(env?.SCRAPIN_API_KEY || "");
        if (!apiKey) return json({ success: false, reason: "missing_key" }, 200, { "Cache-Control": "no-store" });
        // Games answer with their own request shape, so the probe covers them too.
        const game = gamePlatform(platformKey);
        const calls = [];
        if (game) {
          const handle = sanitizeGameHandle(username, game.key);
          if (!handle) return json({ success: false, error: "Invalid account name." }, 400);
          const riotId = splitRiotId(handle);
          calls.push(game.key === "roblox" ? game.request(handle) : game.request(riotId));
          if (game.rank) calls.push(game.rank(riotId));
        } else {
          const platform = SOCIAL_LINK_PLATFORMS.find(entry => entry.key === platformKey);
          if (!platform) return json({ success: false, error: "Unknown platform." }, 400);
          calls.push(platform.request(username, platform.build(username)));
        }
        const results = [];
        for (const request_ of calls) {
          const target = new URL(request_.path, SCRAPIN_API_URL);
          for (const [key, value] of Object.entries(request_.params)) target.searchParams.set(key, value);
          let status = 0;
          let payload = null;
          try {
            const response = await fetch(target.toString(), {
              headers: { "X-API-Key": apiKey, Accept: "application/json" },
              signal: AbortSignal.timeout(8000),
            });
            status = response.status;
            payload = await response.json().catch(() => null);
          } catch (error) {
            results.push({ path: request_.path, status: 0, reason: "network", error: publicErrorMessage(error) });
            continue;
          }
          results.push({
            path: request_.path,
            status,
            ok: status >= 200 && status < 300,
            top_keys: payload && typeof payload === "object" ? Object.keys(payload).slice(0, 20) : [],
            profile: extractScrapinProfile(payload),
            rank: game ? (gameRankLabel(game.key, payload) || gameLevelLabel(payload)) : "",
            raw_sample: JSON.stringify(payload).slice(0, 1200),
          });
        }
        const first = results[0] || {};
        return json({
          success: results.every(item => item.ok === true),
          status: first.status || 0,
          key_present: true,
          calls: results,
          top_keys: first.top_keys || [],
          profile: first.profile || {},
          raw_sample: first.raw_sample || "",
        }, 200, { "Cache-Control": "no-store" });
      }

      // Zyrex follower backfill runs inside the API worker, so it must be routed before
      // the admin proxy that forwards the rest of /api/admin to the bot.
      if (path === "/api/admin/zyrex/followers" && request.method === "POST") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        const result = await syncZyrexFollowers(env);
        return json({ success: result.ok === true, ...result }, result.ok ? 200 : 503, { "Cache-Control": "no-store" });
      }

      if (path === "/api/installer/ffx-source" && request.method === "GET") {
        return handleInstallerFfxSource(request, url, env);
      }

      if (path === "/api/installer/publish" && request.method === "POST") return handleInstallerPublish(request, url, env);
      if (path === "/api/installer/migrate" && request.method === "POST") return handleInstallerMigrate(request, url, env);
      if (path === "/api/installer/relocate-source" && request.method === "POST") return handleInstallerRelocateSource(request, url, env);
      if (path === "/api/installer/status" && request.method === "GET") return handleInstallerStatus(url, env);
      if (path === "/api/installer/log" && request.method === "POST") return handleInstallerLog(request, env);
      if (path === "/api/installer/logs" && request.method === "GET") return handleInstallerLogs(request, url, env, hasMasterKey);
      if (path === "/api/installer/download" && request.method === "GET") return handleInstallerDownload(request, url, env);
      if (path === "/api/installer/auth/start" && request.method === "POST") return handleInstallerAuthStart(request, env, url);
      if (path === "/api/installer/auth/complete" && request.method === "GET") return handleInstallerAuthComplete(request, env, url);
      if (path === "/api/installer/auth/poll" && request.method === "GET") return handleInstallerAuthPoll(url, env);
      if (path === "/api/installer/build-key" && request.method === "POST") return handleInstallerBuildKey(request, env);
      if (path === "/api/installer/payload-key" && request.method === "GET") return handleInstallerKey(request, url, env);
      if (path === "/api/installer/access" && request.method === "GET") return handleInstallerAccess(request, url, env);
      if (path === "/api/installer/trace" && request.method === "POST") return handleInstallerTrace(request, url, env);

      if (path.startsWith("/api/guild/") || path.startsWith("/api/lookup/") ||
                               path.startsWith("/api/admin/") || path.startsWith("/api/cloud/") || path.startsWith("/api/downloads/") || path.startsWith("/api/hlx/") || path.startsWith("/api/verify") || path.startsWith("/api/sftpgo/") || path.startsWith("/api/search/") || path === "/api/resource-stats" || path === "/api/discord-user" || path === "/api/check-uploader" || path === "/api/team" || path === "/api/products/submit") {
        const session = parseSession(request.headers.get("Cookie"), request);
        const proxyHeaders = {
          "Content-Type": "application/json",
        };
        if (session) {
          proxyHeaders["X-User-ID"] = session.userId || "";
          proxyHeaders["X-User-Name"] = session.username || "";
          proxyHeaders["X-User-Display-Name"] = session.displayName || session.username || "";
          proxyHeaders["X-User-Avatar"] = session.avatar || "";
          proxyHeaders["X-User-Can-Upload"] = session.canUpload ? "true" : "false";
          proxyHeaders["X-User-Is-Admin"] = ADMIN_IDS.includes(session.userId) ? "true" : "false";
          proxyHeaders["X-Submitter-ID"] = session.userId || "";
        }
        const targetUrl = `${BOT_API}${path}${url.search}`;
        let body = request.method !== "GET" && request.method !== "HEAD" ? await request.text() : undefined;
        
        // Convert thumbnail to CDN & VirusTotal scan on product submit (Scenepack, Preset, Audio, Plugin)
        if (path === "/api/products/submit" && request.method === "POST" && body) {
          try {
            const submitData = JSON.parse(body);

            // Resolve the platform-native creator account ID at ingestion time.
            // This ID is deliberately separate from any Discord uploader ID.
            const canResolveCreatorOnSubmit = hasMasterKey || await sessionCanUpload(session, env);
            if (canResolveCreatorOnSubmit && submitData.is_anonymous !== true && submitData.creator_social_url && !submitData.creator_account_id) {
              const platform = getCreatorPlatform(submitData);
              if (platform) {
                const resolved = await resolveSocialProfile(submitData.creator_social_url, env);
                if (resolved?.success) {
                  submitData.creator_platform = resolved.platform || platform;
                  submitData.creator_account_id = String(resolved.account_id || "");
                  if (resolved.username) submitData.creator_username = resolved.username;
                  const resolvedNickname = String(resolved.nickname || "").trim();
                  const resolvedUsername = String(resolved.username || submitData.creator_username || "").trim();
                  if (resolvedNickname && (resolved.account_id || resolvedNickname.toLowerCase() !== resolvedUsername.toLowerCase() || !submitData.creator_nickname)) {
                    submitData.creator_nickname = resolvedNickname;
                  }
                  if (resolved.avatar) submitData.creator_avatar = resolved.avatar;
                  submitData.creator_social_url = canonicalCreatorProfileUrl({ ...resolved, creator_account_id: submitData.creator_account_id }, submitData.creator_social_url);
                  await saveCreatorProfile(env, { ...resolved, creator_account_id: submitData.creator_account_id, creator_platform: submitData.creator_platform, social_url: submitData.creator_social_url });
                }
              }
            }
            if (canResolveCreatorOnSubmit && submitData.is_anonymous !== true &&
                (submitData.creator_account_id || submitData.creator_username || submitData.creator_social_url)) {
              submitData.creator_platform = getCreatorPlatform(submitData) || submitData.creator_platform;
              submitData.creator_social_url = canonicalCreatorProfileUrl(submitData, submitData.creator_social_url);
              await saveCreatorProfile(env, submitData);
            }

            // Anonymous resources hide the uploader, while the social creator
            // credit (name, photo and profile link) is preserved. The identity
            // is parked in the admin-only registry, not kept on the product.
            if (submitData.is_anonymous === true) {
              await scrubAnonymousProduct(env, submitData);
              delete proxyHeaders["X-User-ID"];
              delete proxyHeaders["X-User-Name"];
              delete proxyHeaders["X-User-Display-Name"];
              delete proxyHeaders["X-User-Avatar"];
            } else {
            // Credited uploader support (allow uploading on behalf of a discord member)
            const rawCreditId = (submitData.credited_uploader_id || submitData.uploader_id || "").toString().trim();
            const hasCredit = Boolean(rawCreditId && /^\d{17,20}$/.test(rawCreditId));

            if (hasCredit) {
              const creditedId = rawCreditId;
              const creditedName = (submitData.credited_uploader_name || submitData.uploader_name || submitData.author_name || "").toString().trim();
              const creditedAvatar = (submitData.credited_uploader_avatar || submitData.uploader_avatar || submitData.creator_avatar || "").toString().trim();

              proxyHeaders["X-User-ID"] = creditedId;
              if (creditedName) {
                proxyHeaders["X-User-Name"] = creditedName;
                proxyHeaders["X-User-Display-Name"] = creditedName;
                submitData.author_name = creditedName;
                submitData.uploader_name = creditedName;
              }
              if (creditedAvatar) {
                proxyHeaders["X-User-Avatar"] = creditedAvatar;
                submitData.uploader_avatar = creditedAvatar;
                if (!submitData.creator_avatar || submitData.type === "audio") {
                  submitData.creator_avatar = creditedAvatar;
                }
              }
              submitData.author_id = creditedId;
              submitData.uploader_id = creditedId;
              submitData.credited_uploader_id = creditedId;
              if (submitData.type === "audio" && !submitData.creator_nickname && creditedName) {
                submitData.creator_nickname = creditedName;
              }
            } else {
              const sUid = session ? session.userId : "";
              const sName = session ? (session.displayName || session.username) : "";
              const sAv = session ? (session.avatar || "") : "";
              if (!submitData.author_id) submitData.author_id = sUid;
              if (!submitData.author_name) submitData.author_name = sName;
              if (!submitData.uploader_id) submitData.uploader_id = sUid;
              if (!submitData.uploader_name) submitData.uploader_name = sName;
              if (!submitData.uploader_avatar && sAv) submitData.uploader_avatar = sAv;
              if (submitData.type === "audio") {
                if (!submitData.creator_avatar && sAv) submitData.creator_avatar = sAv;
                if (!submitData.creator_nickname && sName) submitData.creator_nickname = sName;
              }
            }
            }

            // Keep the creator photo on our own CDN. Social platforms serve
            // signed, short-lived links that start returning 403, which is what
            // left older resources rendering without a creator image. Running
            // this after the identity scrubbing keeps an anonymous upload from
            // ever re-hosting the uploader's own picture.
            if (/^https?:\/\//i.test(String(submitData.creator_avatar || "")) &&
                !isCdnAvatarUrl(submitData.creator_avatar)) {
              const reHostedAvatar = await storeAndProxyImage(env, submitData.creator_avatar).catch(() => "");
              if (isCdnAvatarUrl(reHostedAvatar)) submitData.creator_avatar = reHostedAvatar;
            }

            // VirusTotal scan integration
            const firstLink = submitData.links && submitData.links[0] ? submitData.links[0].url : "";
            const vtApiKey = (env.VT_API_KEY || "").trim();
            if (vtApiKey && firstLink && firstLink.startsWith("http")) {
              try {
                const cleanUrl = firstLink;
                const base64Url = btoa(unescape(encodeURIComponent(cleanUrl)))
                  .replace(/=+$/, "")
                  .replace(/\+/g, "-")
                  .replace(/\//g, "_");

                let vtResp = await fetch(`https://www.virustotal.com/api/v3/urls/${base64Url}`, {
                  headers: { "x-apikey": vtApiKey }
                });
                
                if (vtResp.status === 404) {
                  const formData = new URLSearchParams();
                  formData.append("url", cleanUrl);
                  vtResp = await fetch("https://www.virustotal.com/api/v3/urls", {
                    method: "POST",
                    headers: {
                      "x-apikey": vtApiKey,
                      "Content-Type": "application/x-www-form-urlencoded"
                    },
                    body: formData.toString(),
                    signal: AbortSignal.timeout(1800),
                  });
                }
                
                if (vtResp.ok) {
                  const vtJson = await vtResp.json();
                  const stats = vtJson.data?.attributes?.last_analysis_stats || vtJson.data?.attributes?.stats || {};
                  submitData.vt_scan = {
                    id: base64Url,
                    harmless: stats.harmless || 0,
                    malicious: stats.malicious || 0,
                    suspicious: stats.suspicious || 0,
                    undetected: stats.undetected || 0
                  };
                } else {
                  submitData.vt_scan = {
                    id: base64Url,
                    harmless: 0,
                    malicious: 0
                  };
                }
              } catch(vtErr) {
                console.error("VirusTotal Worker Scan error:", vtErr);
              }
            }

            body = JSON.stringify(submitData);
          } catch(e) {}
        }
        if (path === "/api/products/submit" && request.method === "POST") {
          const canSubmitProducts = hasMasterKey ||
            await sessionCanUpload(session, env);
          if (!canSubmitProducts) return json({ success: false, error: "Unauthorized" }, 403);

          let submitData;
          try { submitData = JSON.parse(body || ""); } catch (_) {
            return json({ success: false, error: "Invalid JSON" }, 400);
          }
          if (!submitData || typeof submitData !== "object" || Array.isArray(submitData)) {
            return json({ success: false, error: "Invalid product data" }, 400);
          }
          if (isScenepackProduct(submitData)) {
            return json({ success: false, error: "Scenepack resources are no longer supported" }, 410);
          }
          // Same rule as editing: only staff decide who a resource is attributed to.
          if (!canSetUploaderAttribution()) {
            applyUploaderAttributionRules(submitData, session);
          }
          const name = String(submitData.name || "").trim();
          if (!name) return json({ success: false, error: "Product name is required" }, 400);

          const productId = String(submitData.id || generateId("prod")).trim();
          if (!/^[A-Za-z0-9_-]{1,100}$/.test(productId)) {
            return json({ success: false, error: "Invalid product ID" }, 400);
          }
          const now = new Date().toISOString();
          const product = {
            ...submitData,
            id: productId,
            name,
            type: String(submitData.type || "resource").trim().toLowerCase(),
            created_at: submitData.created_at || now,
          };

          // The submitter is known here even though the public record hides them,
          // so this is the one place that can still answer "who uploaded this?".
          const anonIdentity = product.is_anonymous === true ? {
            uploader_id: String(
              (session && session.userId) ||
              submitData.credited_uploader_id || submitData.uploader_id || submitData.author_id || ""
            ).trim(),
            uploader_name: String(
              submitData.credited_uploader_name || submitData.uploader_name || submitData.author_name ||
              (session && (session.displayName || session.username)) || ""
            ).trim(),
            uploader_avatar: String(
              submitData.credited_uploader_avatar || submitData.uploader_avatar ||
              (session && session.avatar) || ""
            ).trim(),
            product_name: name,
          } : null;

          try {
            const savedProduct = await dbAddProduct(env, product);
            const thumbnailUrl = String(product.thumbnail || product.cdn_thumbnail || "");
            if (savedProduct === product && thumbnailUrl.startsWith("http") && !thumbnailUrl.includes("thumbnail.zyrexediting.xyz")) {
              const thumbnailTask = storeAndProxyImage(env, thumbnailUrl).then(cdnUrl => {
                if (cdnUrl && cdnUrl !== thumbnailUrl && cdnUrl.includes("thumbnail.zyrexediting.xyz")) {
                  return dbUpdateProduct(env, productId, { thumbnail: cdnUrl, cdn_thumbnail: cdnUrl });
                }
                return null;
              }).catch(error => {
                console.error("Product thumbnail cache failed:", error?.message || String(error));
              });
              if (ctx?.waitUntil) ctx.waitUntil(thumbnailTask);
              else thumbnailTask.catch(() => {});
            }
            if (anonIdentity) {
              const identityTask = recordAnonymousUpload(env, productId, anonIdentity, { source: "submit" });
              if (ctx?.waitUntil) ctx.waitUntil(identityTask);
              else await identityTask.catch(() => {});
            }
            const completionTask = completeMatchingRequestForProduct(env, savedProduct).catch(error => {
              console.error("Product request completion failed:", error?.message || String(error));
            });
            if (ctx?.waitUntil) ctx.waitUntil(completionTask);
            // Announce to Discord asynchronously
            const announceTask = announceProductToDiscord(env, savedProduct).catch(error => {
              console.error("Discord product announcement failed:", error?.message || String(error));
            });
            if (ctx?.waitUntil) ctx.waitUntil(announceTask);
            const installerTask = queuePresetInstallerBuild(env, savedProduct).catch(error => {
              console.error("Preset installer release dispatch failed:", error?.message || String(error));
              return false;
            });
            if (ctx?.waitUntil) ctx.waitUntil(installerTask);
            else installerTask.catch(() => {});
            return json({ success: true, id: productId, product: savedProduct }, 201);
          } catch (error) {
            console.error("Storage product submission failed:", error?.message || String(error));
            return json({ success: false, error: "Could not publish product" }, 503);
          }
        }
        const botResp = await fetch(targetUrl, {
          method: request.method,
          headers: proxyHeaders,
          body: body || undefined,
        });
        const data = await botResp.text();
        try {
          let parsed = JSON.parse(data);

          // Enrich product data with uploader_is_admin badge flag
          if (path === "/api/products" && botResp.ok) {
            const botCreatorProfiles = await r2GetJSON(env, CREATOR_PROFILES_KEY, {});
            const botAvatarMap = await loadDiscordAvatarMap(
              env,
              (Array.isArray(parsed) ? parsed : [parsed]).map(p => p && (p.uploader_id || p.author_id))
            );
            const botProfileIndex = buildCreatorProfileIndex(botCreatorProfiles);
            if (url.searchParams.has("id")) {
              if (parsed && parsed.id) {
                parsed = normalizeResourceProfile(repairProductDisplayData({ ...parsed }), botProfileIndex, botAvatarMap);
                if (!isAdminRequest(request, env, hasMasterKey)) stripPluginDownloadFields(parsed);
              } else if (parsed && parsed.author_id) {
                parsed.uploader_is_admin = ADMIN_IDS.includes(parsed.author_id);
              }
            } else if (Array.isArray(parsed)) {
              parsed = parsed.map(p => (p && p.id
                ? normalizeResourceProfile(repairProductDisplayData({ ...p }), botProfileIndex, botAvatarMap)
                : p));

              // Same rule as the R2 path: plugin mirror material never reaches a public
              // catalogue response.
              if (!isAdminRequest(request, env, hasMasterKey)) parsed.forEach(stripPluginDownloadFields);

              // Support chunked pagination: ?chunk=1&limit=36
              if (url.searchParams.has("chunk") || url.searchParams.has("page")) {
                const chunkIndex = parseInt(url.searchParams.get("chunk") || url.searchParams.get("page") || "1", 10) || 1;
                const limit = parseInt(url.searchParams.get("limit") || "36", 10) || 36;
                const total = parsed.length;
                const totalChunks = Math.ceil(total / limit) || 1;
                const start = (chunkIndex - 1) * limit;
                const end = Math.min(start + limit, total);
                const chunkItems = parsed.slice(start, end);

                return json({
                  chunk: chunkIndex,
                  limit: limit,
                  total: total,
                  total_chunks: totalChunks,
                  has_more: chunkIndex < totalChunks,
                  items: chunkItems
                }, botResp.status);
              }
            }
          }

          return json(parsed, botResp.status);
        } catch {
          return new Response(data, { status: botResp.status, headers: corsHeaders });
        }
      }

      if (path === "/preset" || path === "/preset.html") {
        const presetId = url.searchParams.get("id") || "";
        const userAgent = (request.headers.get("User-Agent") || "").toLowerCase();
        const isCrawler = userAgent.includes("discordbot") || userAgent.includes("twitterbot") || userAgent.includes("facebookexternalhit") || userAgent.includes("whatsapp") || userAgent.includes("telegrambot") || userAgent.includes("slackbot") || userAgent.includes("linkedinbot");
        
        // Fetch product data from R2 for OG tags (no VPS dependency)
        let product = null;
        if (presetId) {
          try {
            product = await dbGetProduct(env, presetId);
          } catch(e) {
            // R2 unavailable — try VPS as last resort
            try {
              const resp = await fetch(`${BOT_API}/api/products?id=${encodeURIComponent(presetId)}`);
              if (resp.ok) { const data = await resp.json(); product = (Array.isArray(data) ? data[0] : data) || null; }
            } catch(e2) {}
          }
        }
        
        const ogTitle = product ? `${product.name} — Zyrex` : "Zyrex | Preset";
        const ogDesc = (product?.description || product?.desc || "Premium editing preset on Zyrex").substring(0, 200);
        const ogImage = product?.thumbnail || "https://zyrexediting.xyz/assets/og-image.png";
        const ogUrl = `https://zyrexediting.xyz/preset?id=${encodeURIComponent(presetId)}`;
        
        // If it's a crawler, return a minimal HTML page with dynamic OG tags
        if (isCrawler) {
          const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${ogTitle}</title>
<meta property="og:type" content="website">
<meta property="og:url" content="${ogUrl}">
<meta property="og:title" content="${ogTitle.replace(/"/g, '&quot;')}">
<meta property="og:description" content="${ogDesc.replace(/"/g, '&quot;')}">
<meta property="og:image" content="${ogImage}">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:image" content="${ogImage}">
<meta name="description" content="${ogDesc.replace(/"/g, '&quot;')}">
<link rel="icon" type="image/x-icon" href="/favicon.ico">
</head>
<body>
<h1>${ogTitle.replace(/"/g, '&quot;')}</h1>
<p>${ogDesc.replace(/"/g, '&quot;')}</p>
<img src="${ogImage}" alt="Preview" style="max-width:100%;height:auto">
<p><a href="${ogUrl}">View on Zyrex</a></p>
</body>
</html>`;
          return new Response(html, {
            status: 200,
            headers: { "Content-Type": "text/html;charset=UTF-8", "Cache-Control": "public, max-age=60" },
          });
        }
        
        // For normal browsers: pass through to Pages
        // /preset → redirect to /preset.html (keeping query params)
        // /preset.html → serve directly via Pages (pass through subrequest)
        if (path === "/preset") {
          return Response.redirect(new URL(`/preset.html${url.search}`, url.origin).toString(), 302);
        }
        // path === "/preset.html" → let Cloudflare serve from Pages
        return fetch(request);
      }

      // ── Public profiles ────────────────────────────────────────────────────────
      // One feed post with its author and reply thread, for /post/<id>.
      if (path === "/api/post" && request.method === "GET") {
        const postId = String(url.searchParams.get("id") || "").trim();
        if (!/^[a-f0-9-]{16,40}$/i.test(postId)) return json({ success: false, error: "Invalid post." }, 400);
        const session = parseSession(request.headers.get("Cookie"), request);
        const entry = await findFeedPostEntry(env, postId);
        // Upload announcements have no post document of their own; they are read back
        // from the catalogue through the id the feed index recorded.
        if (!entry) {
          const notice = await readNoticePost(env, postId);
          if (!notice) return json({ success: false, error: "That post is no longer available.", code: "POST_NOT_FOUND" }, 404);
          const officialId = String(notice.author_id || "");
          if (!/^\d{15,25}$/.test(officialId)) return json({ success: false, error: "That post is no longer available.", code: "POST_NOT_FOUND" }, 404);
          const catalog = await dbReadProductCatalog(env).catch(() => []);
          const product = (Array.isArray(catalog) ? catalog : []).find(row => String(row && row.id) === String(notice.product_id));
          if (!product) return json({ success: false, error: "That post is no longer available.", code: "POST_NOT_FOUND" }, 404);
          const official = await resolveZyrexProfile(env).catch(() => null);
          const owner = String(product.credited_uploader_id || product.uploader_id || product.author_id || "");
          const ownerIndex = invertHandleIndex(await readHandleIndex(env));
          const ownerHandle = ownerIndex[owner] || "";
          const officialName = (official && official.name) || "Zyrex";
          const officialAvatar = (official && official.avatar) || "/assets/content.png";
          const ownerName = String(
            product.credited_uploader_name || product.uploader_name || product.author_name || ""
          ).trim() || "Zyrex member";
          const noticePost = {
            id: postId,
            author_id: officialId,
            author: { name: officialName, handle: ZYREX_HANDLE, avatar: officialAvatar, url: `/@${ZYREX_HANDLE}` },
            text: `${ownerHandle ? "@" + ownerHandle : "A member"} uploaded a new leak: ${String(product.name || "untitled")}`,
            media: String(product.thumbnail || "") ? [String(product.thumbnail)] : [],
            mentions: [],
            tags: [],
            repost_of: null,
            seq: feedSeqOf(await readFeedPostIndex(env), officialId, postId) || 0,
            created_at: String(product.created_at || notice.created_at || ""),
          };
          const interactionRow = sanitizeSocialInteraction(await r2GetJSON(env, socialInteractionKey("post", postId, officialId), null) || emptySocialInteraction());
          // Announcements borrow the leak's numbers, so the thread here is the leak's conversation.
          const noticeInteraction = await leakInteractionSummary(env, product.id, session?.userId || "", true).catch(() => null);
          return json({
            success: true,
            post: { ...noticePost, url: `/post/${postId}`, short_url: noticePost.seq ? `/feed/post/${noticePost.seq}` : "" },
            author: {
              id: officialId,
              name: officialName,
              handle: ZYREX_HANDLE,
              avatar: officialAvatar,
              url: `/@${ZYREX_HANDLE}`,
              is_admin: true,
            },
            resource: {
              ...profilePublicResource(product),
              // The post page renders the upload card, so it needs the credit line too.
              uploader: {
                id: owner,
                name: ownerName,
                handle: ownerHandle,
                url: ownerHandle ? `/@${ownerHandle}` : `/profile?id=${encodeURIComponent(owner)}`,
              },
            },
            interaction: await refreshReplyAvatars(env, noticeInteraction || socialInteractionSummary(interactionRow, session?.userId || "", true)),
            official: true,
            is_self: false,
            is_staff_viewer: Boolean(session) && ADMIN_IDS.includes(session.userId),
          }, 200, { "Cache-Control": session ? "no-store, private" : "public, max-age=20, s-maxage=45" });
        }
        const authorId = String(entry.author_id || "");
        if (!/^\d{15,25}$/.test(authorId)) return json({ success: false, error: "That post is no longer available.", code: "POST_NOT_FOUND" }, 404);

        const isSelf = Boolean(session) && String(session.userId) === authorId;
        const isStaffViewer = Boolean(session) && ADMIN_IDS.includes(session.userId);
        // Nobody sees a profile for someone who is not in the server, not even staff.
        if (!isSelf && await isGuildProfileMissing(env, authorId)) {
          return json({ success: false, error: "Profile not found", code: "NOT_IN_GUILD" }, 404);
        }

        const post = sanitizeProfilePost(entry.post, authorId);
        if (!post) return json({ success: false, error: "That post is no longer available.", code: "POST_NOT_FOUND" }, 404);
        if (!post.seq) {
          const index = await readFeedPostIndex(env).catch(() => null);
          post.seq = index ? feedSeqOf(index, authorId, post.id) : 0;
        }

        const settings = await readProfileSettings(env, authorId);
        if (!isSelf && !isStaffViewer && (settings.public === false || settings.show_activity === false)) {
          return json({ success: false, error: "That post is private.", code: "POST_PRIVATE" }, 403);
        }

        const identity = await resolveProfileIdentity(env, authorId);
        const handle = await resolveProfileHandle(env, identity, settings);
        const storedAuthor = post.author || {};
        const interactionRow = sanitizeSocialInteraction(await r2GetJSON(env, socialInteractionKey("post", post.id, authorId), null) || emptySocialInteraction());
        const interaction = socialInteractionSummary(interactionRow, session?.userId || "", true);
        await refreshReplyAvatars(env, interaction);
        return json({
          success: true,
          post: { ...post, url: `/post/${post.id}`, short_url: post.seq ? `/feed/post/${post.seq}` : "" },
          author: {
            id: authorId,
            name: storedAuthor.name || identity.name || "Zyrex Member",
            handle: storedAuthor.handle || handle,
            // The live profile wins: a post keeps the avatar it was written with,
            // but the page has to show the member's current photo.
            avatar: identity.avatar || storedAuthor.avatar || profileAvatarUrl(authorId, ""),
            url: storedAuthor.url || (handle ? `/@${handle}` : `/profile?id=${encodeURIComponent(authorId)}`),
            is_admin: ADMIN_IDS.includes(authorId),
          },
          interaction,
          official: await isOfficialProfileId(env, authorId),
          is_self: isSelf,
          is_staff_viewer: isStaffViewer,
        }, 200, { "Cache-Control": session ? "no-store, private" : "public, max-age=20, s-maxage=45" });
      }

      if (path === "/api/profile/media" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Sign in to upload an image.", code: "NOT_LOGGED_IN" }, 401);
        if (!env?.STORAGE) return json({ success: false, error: "Storage is unavailable right now." }, 503);
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON." }, 400); }
        const dataUrl = String((body && body.data) || "");
        const match = /^data:(?:image\/(?:png|jpe?g|gif|webp));base64,([A-Za-z0-9+/=\s]+)$/i.exec(dataUrl);
        if (!match) return json({ success: false, error: "Attach a PNG, JPEG, GIF or WebP image." }, 400);
        const encoded = match[1].replace(/\s+/g, "");
        if (Math.floor(encoded.length * 3 / 4) > IMAGE_UPLOAD_MAX_BYTES) {
          return json({ success: false, error: "That image is larger than 3 MB." }, 413);
        }
        let bytes;
        try { bytes = Uint8Array.from(atob(encoded), char => char.charCodeAt(0)); } catch (_) { return json({ success: false, error: "That image could not be read." }, 400); }
        const extension = detectImageExtension(bytes);
        if (!extension) return json({ success: false, error: "That file is not a supported image." }, 415);
        const folder = String((body && body.kind) || "").toLowerCase() === "comment" ? "comment" : "post";
        const name = `${folder}-${session.userId}-${crypto.randomUUID().replace(/-/g, "").slice(0, 20)}.${extension}`;
        const stored = await env.STORAGE.put(`thumbnails/${name}`, bytes, {
          httpMetadata: { contentType: extension === "jpg" ? "image/jpeg" : `image/${extension}` },
        }).catch(() => false);
        if (!stored) return json({ success: false, error: "Could not store that image." }, 503);
        const url = `https://thumbnail.zyrexediting.xyz/${name}`;
        const kind = folder === "comment" ? "comment-image" : "post-image";
        await writeMediaScan(env, url, { state: "pending", user_id: String(session.userId), kind }).catch(() => null);
        runInBackground(ctx, scanUploadedMedia(env, {
          userId: session.userId,
          url,
          kind,
          deleteObject: () => env.STORAGE.delete(`thumbnails/${name}`),
        }));
        return json({ success: true, url, size: bytes.length, pending: true }, 201, { "Cache-Control": "no-store" });
      }

      // Videos are streamed straight into the bucket: base64 would triple the payload.
      // The composer sends the poster and a contact sheet of frames here before uploading.
      if (path === "/api/profile/video/scan" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Sign in to upload a video.", code: "NOT_LOGGED_IN" }, 401);
        if (!env?.STORAGE) return json({ success: false, error: "Storage is unavailable right now." }, 503);
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON." }, 400); }
        const videoUrl = String((body && body.video) || "").trim();
        const videoName = videoUrl ? mediaScanId(videoUrl) : "";
        if (!videoName || !videoName.startsWith(`video-${session.userId}-`)) {
          return json({ success: false, error: "That video could not be checked." }, 400);
        }
        const posterBytes = imageDataUrlBytes(body && body.poster, VIDEO_SCAN_MAX_BYTES);
        const framesBytes = imageDataUrlBytes(body && body.frames, VIDEO_SCAN_MAX_BYTES);
        if (!posterBytes && !framesBytes) {
          return json({ success: false, error: "The video frames could not be read.", code: "BAD_FRAMES" }, 400);
        }
        const videoKey = `thumbnails/${videoName}`;
        // The contact sheet already contains the poster frame, so one image is classified and
        // the whole job fits inside the background budget.
        const sheetBytes = framesBytes || posterBytes;
        const kind = framesBytes ? "video-frames" : "video-poster";
        const tempName = `scan-${session.userId}-${crypto.randomUUID().replace(/-/g, "").slice(0, 16)}.jpg`;
        const tempKey = `thumbnails/${tempName}`;
        const stored = await env.STORAGE.put(tempKey, sheetBytes, { httpMetadata: { contentType: "image/jpeg" } }).catch(() => false);
        if (!stored) return json({ success: false, error: "Could not store the video frames." }, 503);
        await writeMediaScan(env, videoUrl, { state: "pending", user_id: String(session.userId), kind: "video" }).catch(() => null);
        try {
          const result = await scanUploadedMedia(env, {
            userId: session.userId,
            url: `https://thumbnail.zyrexediting.xyz/${tempName}`,
            kind,
            deleteObject: () => env.STORAGE.delete(tempKey),
          });
          await env.STORAGE.delete(tempKey).catch(() => false);
          if (result && result.blocked) {
            await env.STORAGE.delete(videoKey).catch(() => false);
            await writeMediaScan(env, videoUrl, { state: "blocked", user_id: String(session.userId) }).catch(() => null);
            await applyFeedBan(env, session.userId, "nsfw-upload").catch(() => false);
          } else {
            await writeMediaScan(env, videoUrl, { state: "clean", user_id: String(session.userId), kind: "video" }).catch(() => null);
          }
        } catch (_) {
          // Never leave a video stuck in "pending": fail open and note it for review.
          await env.STORAGE.delete(tempKey).catch(() => false);
          await writeMediaScan(env, videoUrl, { state: "clean", user_id: String(session.userId), kind: "video", review: true }).catch(() => null);
        }
        // The verdict stays on the server: the composer only polls for readiness.
        return json({ success: true, received: true }, 200, { "Cache-Control": "no-store" });
      }

      if (path === "/api/profile/video" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Sign in to upload a video.", code: "NOT_LOGGED_IN" }, 401);
        if (!env?.STORAGE) return json({ success: false, error: "Storage is unavailable right now." }, 503);
        const declared = Number(request.headers.get("content-length") || 0);
        if (declared > VIDEO_UPLOAD_MAX_BYTES) {
          return json({ success: false, error: "That video is larger than 50 MB." }, 413);
        }
        if (!request.body) return json({ success: false, error: "No video data was sent." }, 400);
        const type = String(request.headers.get("content-type") || "").toLowerCase();
        const requested = /mp4/.test(type) ? "mp4" : /webm/.test(type) ? "webm" : "";
        if (!requested) return json({ success: false, error: "Attach an MP4 or WebM video." }, 415);
        const name = videoFileName(session.userId, requested);
        const stored = await env.STORAGE.put(`thumbnails/${name}`, request.body, {
          httpMetadata: { contentType: requested === "mp4" ? "video/mp4" : "video/webm" },
        }).catch(() => null);
        if (!stored) return json({ success: false, error: "Could not store that video." }, 503);
        if (Number(stored.size || 0) > VIDEO_UPLOAD_MAX_BYTES) {
          await env.STORAGE.delete(`thumbnails/${name}`).catch(() => false);
          return json({ success: false, error: "That video is larger than 50 MB." }, 413);
        }
        const head = await env.STORAGE.get(`thumbnails/${name}`, { range: { offset: 0, length: 12 } }).catch(() => null);
        const headBytes = head ? new Uint8Array(await head.arrayBuffer()) : new Uint8Array();
        const extension = detectVideoExtension(headBytes);
        if (extension !== requested) {
          await env.STORAGE.delete(`thumbnails/${name}`).catch(() => false);
          return json({ success: false, error: "That file is not an MP4 or WebM video." }, 415);
        }
        const videoUrl = `https://thumbnail.zyrexediting.xyz/${name}`;
        await writeMediaScan(env, videoUrl, { state: "pending", user_id: String(session.userId), kind: "video" }).catch(() => null);
        return json({ success: true, url: videoUrl, size: Number(stored.size || 0), type: requested === "mp4" ? "video/mp4" : "video/webm", pending: true }, 201, { "Cache-Control": "no-store" });
      }

      // A pasted image link is copied into the bucket, so the post stores a URL we own.
      // The composer polls this until its attachments are ready; it never reports a verdict.
      if (path === "/api/profile/media/status" && request.method === "GET") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Sign in to attach media.", code: "NOT_LOGGED_IN" }, 401);
        const targets = String(url.searchParams.get("url") || "").split(",").map(value => value.trim()).filter(Boolean).slice(0, 6);
        if (!targets.length) return json({ success: false, error: "No attachments were given." }, 400);
        const states = [];
        for (const target of targets) {
          const record = await readMediaScan(env, target);
          if (record && String(record.user_id || "") !== String(session.userId)) {
            states.push({ url: target, state: "missing" });
            continue;
          }
          states.push({ url: target, state: await mediaScanState(env, target) });
        }
        return json({
          success: true,
          states,
          ready: states.every(entry => entry.state === "clean"),
        }, 200, { "Cache-Control": "no-store" });
      }

      if (path === "/api/profile/media/remote" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Sign in to attach an image.", code: "NOT_LOGGED_IN" }, 401);
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON." }, 400); }
        const target = String((body && body.url) || "").trim();
        if (!target) return json({ success: false, error: "A link is required." }, 400);
        const mirrored = await mirrorRemoteImage(env, target, session.userId);
        if (mirrored.url) {
          const fileName = mirrored.url.split("/").pop();
          await writeMediaScan(env, mirrored.url, { state: "pending", user_id: String(session.userId), kind: "remote-image" }).catch(() => null);
          runInBackground(ctx, scanUploadedMedia(env, {
            userId: session.userId,
            url: mirrored.url,
            kind: "remote-image",
            deleteObject: () => env.STORAGE.delete(`thumbnails/${fileName}`),
          }));
          return json({ success: true, url: mirrored.url, pending: true }, 201, { "Cache-Control": "no-store" });
        }
        return json({ success: false, error: mirrored.error || "That image could not be attached.", not_image: Boolean(mirrored.notImage) }, mirrored.notImage ? 415 : 400, { "Cache-Control": "no-store" });
      }

      // Link cards: title, description and image are read from the page's own tags.
      if (path === "/api/link/preview" && (request.method === "GET" || request.method === "POST")) {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Sign in to preview a link.", code: "NOT_LOGGED_IN" }, 401);
        let target = String(url.searchParams.get("url") || "").trim();
        if (!target && request.method === "POST") {
          const body = await request.json().catch(() => null);
          target = String((body && body.url) || "").trim();
        }
        if (!target) return json({ success: false, error: "A link is required." }, 400);
        const preview = await buildLinkPreview(env, target, session.userId);
        return json(preview, preview.success ? 200 : 404, { "Cache-Control": "no-store" });
      }

      if (path === "/api/profile/posts" && request.method === "GET") {
        const session = parseSession(request.headers.get("Cookie"), request);
        let targetId = String(url.searchParams.get("id") || "").trim();
        const rawHandle = url.searchParams.get("handle") || "";
        if (!targetId && rawHandle) targetId = await resolveHandle(env, rawHandle);
        if (!targetId && session) targetId = session.userId;
        if (!/^\d{15,25}$/.test(targetId)) return json({ success: false, error: "Profile not found" }, 404);
        const isSelf = Boolean(session) && session.userId === targetId;
        if (!isSelf && await isGuildProfileMissing(env, targetId)) {
          return json({ success: false, error: "Profile not found", code: "NOT_IN_GUILD" }, 404);
        }
        const settings = await readProfileSettings(env, targetId);
        if ((settings.public === false || settings.show_activity === false) && !isSelf && !(session && ADMIN_IDS.includes(session.userId))) {
          return json({ success: false, error: "This profile is private." }, 403);
        }
        const page = Math.max(1, Number(url.searchParams.get("page")) || 1);
        const size = 20;
        const posts = await readProfilePosts(env, targetId);
        const productRows = await dbReadProductCatalog(env).catch(() => []);
        const identities = buildProfileIdentityMap(productRows);
        const handles = invertHandleIndex(await readHandleIndex(env));
        const visible = posts.slice((page - 1) * size, page * size);
        const items = await Promise.all(visible.map(async post => {
          let original = null;
          if (post.repost_of) {
            const source = await readProfilePost(env, post.repost_of.author_id, post.repost_of.post_id);
            const sourceSettings = source && await readProfileSettings(env, source.author_id);
            if (source && !source.repost_of && sourceSettings.public !== false && sourceSettings.show_activity !== false) {
              const identity = identities.get(source.author_id) || {};
              const storedAuthor = source.author || {};
              original = {
                ...source,
                author: {
                  id: source.author_id,
                  name: storedAuthor.name || identity.name || "Zyrex Member",
                  handle: storedAuthor.handle || handles[source.author_id] || "",
                  avatar: storedAuthor.avatar || profileAvatarUrl(source.author_id, identity.avatar),
                  url: storedAuthor.url || (handles[source.author_id] ? `/@${handles[source.author_id]}` : `/profile?id=${encodeURIComponent(source.author_id)}`),
                  is_admin: ADMIN_IDS.includes(String(source.author_id)),
                },
              };
            }
          }
          return { ...post, original };
        }));
        const ownPosts = session ? await readProfilePosts(env, session.userId) : [];
        const reposts = new Set(ownPosts.filter(post => post.repost_of).map(post => `${post.repost_of.author_id}:${post.repost_of.post_id}`));
        // The official account is the voice of the site, so its profile also carries the
        // upload announcements that the feed shows.
        let noticeRows = [];
        let officialNoticeTotal = 0;
        const isOfficialProfile = await isOfficialProfileId(env, targetId);
        const officialIdentity = isOfficialProfile ? (await resolveZyrexProfile(env).catch(() => null) || {}) : null;
        if (isOfficialProfile) {
          const hiddenNoticeIds = await readFeedHiddenIds(env).catch(() => new Set());
          const ownedCatalog = (Array.isArray(productRows) ? productRows : [])
            .filter(product => isFeedAnnounceableProduct(product))
            .filter(product => String(product.id || ""))
            .filter(product => !hiddenNoticeIds.has(noticeHiddenId(product.id)));
          officialNoticeTotal = ownedCatalog.length;
          const sorted = ownedCatalog
            .sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || "")))
            .slice((page - 1) * size, page * size);
          noticeRows = sorted.map(product => {
            const owner = String(product.credited_uploader_id || product.uploader_id || product.author_id || "");
            const identity = identities.get(owner) || {};
            const handle = handles[owner] || "";
            const displayName = identity.name || String(product.uploader_name || product.author_name || "").trim() || "Zyrex member";
            // Announcements are posts on the official timeline, so they get a post id too.
            const postId = noticePostId(product.id);
            return {
              kind: "resource_notice",
              id: postId,
              post_id: postId,
              product_id: String(product.id || ""),
              author_id: targetId,
              author: {
                id: targetId,
                name: officialIdentity.name || "Zyrex",
                handle: ZYREX_HANDLE,
                avatar: officialIdentity.avatar || "/assets/content.png",
                url: `/@${ZYREX_HANDLE}`,
                is_admin: true,
                is_official: true,
              },
              resource: profilePublicResource(product),
              uploader: {
                id: owner,
                name: displayName,
                handle,
                avatar: profileAvatarUrl(owner, identity.avatar),
                url: handle ? `/@${handle}` : `/profile?id=${encodeURIComponent(owner)}`,
              },
              text: `${handle ? "@" + handle : displayName} uploaded a new leak!`,
              created_at: product.created_at || null,
            };
          }).filter(row => row.created_at);
          await assignNoticeSequences(env, noticeRows).catch(() => noticeRows);
        }
        const totalCount = posts.length + (isOfficialProfile ? Math.min(officialNoticeTotal, 400) : 0);
        return json({
          success: true,
          total: totalCount,
          page,
          pages: Math.max(1, Math.ceil(totalCount / size)),
          is_self: isSelf,
          reposts: Array.from(reposts),
          items,
          notices: noticeRows,
        }, 200, { "Cache-Control": session ? "no-store, private" : "public, max-age=15, s-maxage=30" });
      }

      if (path === "/api/profile/posts" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Sign in to post.", code: "NOT_LOGGED_IN" }, 401);
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON." }, 400); }
        const text = String(body.text || "").trim().slice(0, 1200);
        const media = Array.isArray(body.media) ? body.media.map(value => sanitizeProfileMediaUrl(value, session.userId)).filter(Boolean).slice(0, 4) : [];
        const moderation = await readModerationSettings(env);
        const textHits = nsfwTextHits(text, moderation);
        if (textHits.length) {
          if (moderation.autoWarn !== false) await issueNsfwWarning(env, session.userId, "NSFW language in a feed post");
          await logModerationEvent(env, {
            kind: "text",
            level: "nsfw",
            user_id: session.userId,
            snippet: text.slice(0, 160),
            stems: textHits,
            action: "blocked",
          });
          return json({ success: false, error: "That post breaks the community rules and was not published.", code: "NSFW_TEXT" }, 403);
        }
        const links = sanitizePostLinks(body.links);
        const video = sanitizePostVideo(body.video, session.userId);
        if (video && media.length) {
          return json({ success: false, error: "A video cannot be combined with images, GIFs or stickers.", code: "VIDEO_WITH_MEDIA" }, 400);
        }
        // A two hour posting block follows any rejected upload; the reason is never disclosed.
        if (await readFeedBan(env, session.userId)) {
          return json({
            success: false,
            error: "You cannot post in the feed right now. Please try again later.",
            code: "FEED_POST_BLOCKED",
          }, 403);
        }
        // Attachments stay unusable until their background check has cleared them. Stickers and
        // GIFs come from Discord/Giphy/Tenor, so only our own uploads are gated.
        const attachments = media.concat(video && video.url ? [video.url] : [])
          .filter(attachment => /^https:\/\/thumbnail\.zyrexediting\.xyz\//i.test(String(attachment || "")));
        for (const attachment of attachments) {
          const state = await mediaScanState(env, attachment);
          if (state === "blocked") {
            return json({ success: false, error: "That attachment is not available.", code: "MEDIA_UNAVAILABLE" }, 400);
          }
          if (state !== "clean") {
            return json({ success: false, error: "Your attachments are still being prepared.", code: "MEDIA_PENDING" }, 409);
          }
        }
        let repost = null;
        if (body.repost_of && typeof body.repost_of === "object") {
          let authorId = String(body.repost_of.author_id || "").trim();
          let postId = String(body.repost_of.post_id || "").trim();
          let source = await readProfilePost(env, authorId, postId);
          if (source && source.repost_of) {
            authorId = source.repost_of.author_id;
            postId = source.repost_of.post_id;
            source = await readProfilePost(env, authorId, postId);
          }
          if (!source || source.repost_of) return json({ success: false, error: "That post is no longer available." }, 404);
          if (await isOfficialProfileId(env, authorId)) {
            return json({ success: false, error: "The Zyrex official profile cannot be reposted." }, 403);
          }
          const sourceSettings = await readProfileSettings(env, authorId);
          if (sourceSettings.public === false || sourceSettings.show_activity === false) return json({ success: false, error: "That post is not available to repost." }, 403);
          repost = { author_id: authorId, post_id: postId };
        }
        if (!text && !media.length && !links.length && !video && !repost) return json({ success: false, error: "Write a message or attach an image." }, 400);
        const key = profilePostsKey(session.userId);
        const stored = await r2GetJSON(env, key, null);
        const posts = (Array.isArray(stored && stored.posts) ? stored.posts : []).map(post => sanitizeProfilePost(post, session.userId)).filter(Boolean);
        if (repost) {
          const existing = posts.find(post => post.repost_of && post.repost_of.author_id === repost.author_id && post.repost_of.post_id === repost.post_id);
          if (existing) {
            const next = posts.filter(post => post.id !== existing.id);
            const saved = await r2PutJSON(env, key, { version: 1, posts: next, updated_at: new Date().toISOString() });
            if (!saved) return json({ success: false, error: "Could not update your repost." }, 503);
            return json({ success: true, reposted: false, post_id: existing.id }, 200, { "Cache-Control": "no-store, private" });
          }
        }
        if (posts.length >= 100) return json({ success: false, error: "Your profile has reached its 100 post limit." }, 409);
        const identity = await resolveProfileIdentity(env, session.userId);
        const settings = await readProfileSettings(env, session.userId);
        const handle = await resolveProfileHandle(env, identity, settings);
        const author = {
          name: identity.name,
          handle,
          avatar: identity.avatar,
          url: handle ? `/@${handle}` : `/profile?id=${encodeURIComponent(session.userId)}`,
        };
        const mentions = sanitizeProfileMentions(body.mentions, text);
        const postId = crypto.randomUUID();
        const seq = await allocateFeedSequence(env, session.userId, postId).catch(() => 0);
        const post = { id: postId, author_id: session.userId, author, text, media, links, video, mentions, repost_of: repost, seq, created_at: new Date().toISOString() };
        const saved = await r2PutJSON(env, key, { version: 1, posts: [post, ...posts], updated_at: post.created_at });
        if (!saved) return json({ success: false, error: "Could not save your post." }, 503);
        // Keep the public timeline indexed by post so feed reads do not need to
        // enumerate every member's profile document.
        if (!repost) {
          const indexed = await r2PutJSON(env, profileFeedPostKey(session.userId, post), { author_id: session.userId, post }).catch(() => false);
          if (!indexed) console.error("profile_feed_index_write_failed", { userId: session.userId, postId: post.id });
        }
        // Notify followers, ping mentions and announce the post in Discord without
        // holding the response hostage to those writes.
        const notifyTask = dispatchFeedPostNotifications(env, post).catch(() => 0);
        if (ctx?.waitUntil) ctx.waitUntil(notifyTask); else notifyTask.catch(() => {});
        return json({ success: true, reposted: Boolean(repost), post }, 201, { "Cache-Control": "no-store, private" });
      }

      // Re-announce an existing leak: same feed post, fresh Discord card.
      if (path === "/api/zyrex/announce-leak" && request.method === "POST") {
        if (!isAdminRequest(request, env, hasMasterKey) && !(await isTrustedBotRequest(request, env))) {
          return json({ success: false, error: "Unauthorized" }, 403);
        }
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON." }, 400); }
        const wantedProductId = String(body.product_id || "").trim();
        const wantedPostId = String(body.post_id || "").trim();
        if (!wantedProductId && !wantedPostId) return json({ success: false, error: "A product or post id is required." }, 400);
        const catalog = await dbReadProductCatalog(env).catch(() => []);
        const rows = Array.isArray(catalog) ? catalog : [];
        let product = wantedProductId ? rows.find(row => String(row && row.id) === wantedProductId) || null : null;
        if (!product && wantedPostId) {
          const notice = await readNoticePost(env, wantedPostId).catch(() => null);
          if (notice && notice.product_id) product = rows.find(row => String(row && row.id) === String(notice.product_id)) || null;
        }
        if (!product) return json({ success: false, error: "That leak is no longer available.", code: "PRODUCT_NOT_FOUND" }, 404);
        // Dry run resolves everything the real announcement would use, without posting.
        if (body.dry_run === true) {
          const preview = await buildLeakAnnouncementNotice(env, product).catch(() => null);
          const uploader = (preview && preview.uploader) || {};
          const uploaderId = String(uploader.id || "").trim();
          const identity = await discordUploaderIdentity(env, uploaderId, uploader);
          // The preview returns the exact embed the channel would receive, so the card
          // can be checked (or rendered by a tool) before anything is posted.
          const previewCounts = await readFeedPostCounts(env, preview || {}).catch(() => ({ likes: 0, views: 0, replies: 0 }));
          const previewStats = await leakPackStats(env, product);
          const embed = buildLeakAnnouncementEmbed(product, preview || {}, { identity, counts: previewCounts, stats: previewStats, uploaderId });
          return json({
            success: true,
            dry_run: true,
            product_id: String(product.id),
            name: String(product.name || ""),
            embed,
            components: leakAnnounceButtons(product, preview) || [],
            content: leakAnnounceRoleIds(env).map(id => `<@&${id}>`).join(" "),
            stats: previewStats,
          }, 200, { "Cache-Control": "no-store" });
        }
        const announced = await postLeakAnnouncement(env, product).catch(error => {
          console.error("Leak re-announce failed:", error?.message || String(error));
          return false;
        });
        if (!announced) return json({ success: false, error: "Discord did not accept the announcement." }, 502);
        return json({ success: true, product_id: String(product.id), name: String(product.name || "") }, 200, { "Cache-Control": "no-store" });
      }

      // The announce slash command publishes here: an official feed post plus the site
      // notification bell. Discord delivery stays with the bot, so nothing is duplicated.
      if (path === "/api/zyrex/announce" && request.method === "POST") {
        if (!isAdminRequest(request, env, hasMasterKey) && !(await isTrustedBotRequest(request, env))) {
          return json({ success: false, error: "Unauthorized" }, 403);
        }
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON." }, 400); }
        const official = await resolveZyrexProfile(env).catch(() => null);
        if (!official) return json({ success: false, error: "The official profile is unavailable." }, 503);
        const title = String(body.title || "").trim().slice(0, 140);
        const description = String(body.description || "").trim().slice(0, 1200);
        if (!title && !description) return json({ success: false, error: "A title or description is required." }, 400);
        const text = [title ? `**${title}**` : "", description].filter(Boolean).join("\n\n").slice(0, 1200);
        const image = body.image_url ? await mirrorAnnouncementImage(env, body.image_url, official.id) : "";
        const settings = await readProfileSettings(env, official.id);
        const handle = ZYREX_HANDLE;
        const author = {
          name: official.name,
          handle,
          avatar: official.avatar,
          url: `/@${handle}`,
        };
        const postId = crypto.randomUUID();
        const seq = await allocateFeedSequence(env, official.id, postId).catch(() => 0);
        const post = {
          id: postId,
          author_id: official.id,
          author,
          text,
          media: image ? [image] : [],
          mentions: [],
          repost_of: null,
          seq,
          skip_discord: true,
          created_at: new Date().toISOString(),
        };
        const key = profilePostsKey(official.id);
        const stored = await r2GetJSON(env, key, null);
        const posts = (Array.isArray(stored && stored.posts) ? stored.posts : []).map(row => sanitizeProfilePost(row, official.id)).filter(Boolean);
        const saved = await r2PutJSON(env, key, { version: 1, posts: [post, ...posts].slice(0, 100), updated_at: post.created_at });
        if (!saved) return json({ success: false, error: "Could not publish the announcement." }, 503);
        await r2PutJSON(env, profileFeedPostKey(official.id, post), { author_id: official.id, post }).catch(() => false);
        const fanout = dispatchFeedPostNotifications(env, post).catch(() => 0);
        if (ctx?.waitUntil) ctx.waitUntil(fanout); else fanout.catch(() => {});
        return json({
          success: true,
          post: { ...sanitizeProfilePost(post, official.id), url: post.seq ? `/feed/post/${post.seq}` : `/post/${post.id}` },
          image,
        }, 201, { "Cache-Control": "no-store" });
      }

      // Short, uuid-free post links resolve through the sequence index.
      if (path === "/api/feed/post" && request.method === "GET") {
        const seq = Math.max(Number(url.searchParams.get("n")) || 0, 0);
        if (!seq) return json({ success: false, error: "Invalid post link.", code: "POST_NOT_FOUND" }, 400);
        let index = await readFeedPostIndex(env);
        let entry = index.entries[String(seq)] || null;
        if (!entry) {
          index = await backfillFeedSequences(env, { force: true }).catch(() => index);
          entry = index.entries[String(seq)] || null;
        }
        if (!entry || !entry.post_id) return json({ success: false, error: "That post is no longer available.", code: "POST_NOT_FOUND" }, 404);
        return json({ success: true, author_id: entry.author_id, post_id: entry.post_id, seq }, 200, { "Cache-Control": "no-store" });
      }

      // Editing keeps the identity of the post (id, media, mentions) and only rewrites
      // the words, so likes, replies and the Discord embed stay attached.
      if (path === "/api/profile/posts" && request.method === "PATCH") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Sign in to edit your post.", code: "NOT_LOGGED_IN" }, 401);
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON." }, 400); }
        const postId = String((body && body.id) || url.searchParams.get("id") || "").trim();
        if (!/^[a-f0-9-]{16,40}$/i.test(postId)) return json({ success: false, error: "Invalid post." }, 400);
        const text = String((body && body.text) || "").trim().slice(0, 1200);
        const key = profilePostsKey(session.userId);
        const stored = await r2GetJSON(env, key, null);
        const posts = (Array.isArray(stored && stored.posts) ? stored.posts : []).map(post => sanitizeProfilePost(post, session.userId)).filter(Boolean);
        const target = posts.find(post => post.id === postId);
        if (!target) return json({ success: false, error: "That post is no longer available." }, 404);
        const moderation = await readModerationSettings(env);
        const textHits = nsfwTextHits(text, moderation);
        if (textHits.length) {
          if (moderation.autoWarn !== false) await issueNsfwWarning(env, session.userId, "NSFW language in a feed post");
          await logModerationEvent(env, {
            kind: "text",
            level: "nsfw",
            user_id: session.userId,
            post_id: postId,
            snippet: text.slice(0, 160),
            stems: textHits,
            action: "blocked",
          });
          return json({ success: false, error: "That edit breaks the community rules and was not saved.", code: "NSFW_TEXT" }, 403);
        }
        if (target.repost_of) return json({ success: false, error: "Reposts cannot be edited." }, 400);
        if (!text && !(target.media || []).length) return json({ success: false, error: "Write something first." }, 400);
        // A link card only survives while its URL is still mentioned in the post.
        const keptLinks = (target.links || []).filter(link => link && text.includes(String(link.url || "")));
        const edited = { ...target, text, links: keptLinks, tags: profilePostTags(text), edited_at: new Date().toISOString() };
        const next = posts.map(post => (post.id === postId ? edited : post));
        const saved = await r2PutJSON(env, key, { version: 1, posts: next, updated_at: new Date().toISOString() });
        if (!saved) return json({ success: false, error: "Could not save your edit." }, 503);
        await r2PutJSON(env, profileFeedPostKey(session.userId, edited), { author_id: session.userId, post: edited }).catch(() => false);
        const refresh = scheduleFeedDiscordRefresh(env, postId).catch(() => false);
        if (ctx?.waitUntil) ctx.waitUntil(refresh); else refresh.catch(() => {});
        return json({ success: true, post: edited }, 200, { "Cache-Control": "no-store, private" });
      }

      // Exactly one post can be pinned to the top of a profile.
      if (path === "/api/profile/posts/pin" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Sign in to pin a post.", code: "NOT_LOGGED_IN" }, 401);
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON." }, 400); }
        const postId = String((body && body.id) || "").trim();
        const settings = await readProfileSettings(env, session.userId);
        if (!postId) {
          const saved = await r2PutJSON(env, profileSettingsKey(session.userId), { ...settings, pinned_post_id: "", updated_at: new Date().toISOString() });
          if (!saved) return json({ success: false, error: "Could not update your pinned post." }, 503);
          return json({ success: true, pinned_post_id: "" }, 200, { "Cache-Control": "no-store, private" });
        }
        if (!/^[a-f0-9-]{16,40}$/i.test(postId)) return json({ success: false, error: "Invalid post." }, 400);
        const posts = await readProfilePosts(env, session.userId);
        if (!posts.some(post => post.id === postId)) return json({ success: false, error: "That post is no longer available." }, 404);
        const saved = await r2PutJSON(env, profileSettingsKey(session.userId), { ...settings, pinned_post_id: postId, updated_at: new Date().toISOString() });
        if (!saved) return json({ success: false, error: "Could not pin that post." }, 503);
        return json({ success: true, pinned_post_id: postId }, 200, { "Cache-Control": "no-store, private" });
      }

      if (path === "/api/profile/posts" && request.method === "DELETE") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Sign in to delete your post.", code: "NOT_LOGGED_IN" }, 401);
        const postId = String(url.searchParams.get("id") || "").trim();
        if (!/^[a-f0-9-]{16,40}$/i.test(postId)) return json({ success: false, error: "Invalid post." }, 400);
        const key = profilePostsKey(session.userId);
        const stored = await r2GetJSON(env, key, null);
        const posts = (Array.isArray(stored && stored.posts) ? stored.posts : []).map(post => sanitizeProfilePost(post, session.userId)).filter(Boolean);
        const target = posts.find(post => post.id === postId);
        if (!target) return json({ success: false, error: "That post is no longer available." }, 404);
        const saved = await r2PutJSON(env, key, {
          version: 1,
          posts: posts.filter(post => post.id !== postId),
          updated_at: new Date().toISOString(),
        });
        if (!saved) return json({ success: false, error: "Could not delete your post." }, 503);
        // The public timeline keeps one object per post, so drop it with the post.
        if (!target.repost_of) await r2DeleteKey(env, profileFeedPostKey(session.userId, target));
        // The Discord announcement goes with it. Awaited so the feed and the Discord
        // channel change together instead of drifting apart.
        await deleteFeedDiscordMessage(env, postId).catch(() => false);
        return json({ success: true, deleted: true, post_id: postId }, 200, { "Cache-Control": "no-store, private" });
      }

      if (path === "/api/profile/preview" && request.method === "GET") {
        const session = parseSession(request.headers.get("Cookie"), request);
        let targetId = String(url.searchParams.get("id") || "").trim();
        const rawHandle = url.searchParams.get("handle") || "";
        if (!targetId && rawHandle) targetId = await resolveHandle(env, rawHandle);
        if (!/^\d{15,25}$/.test(targetId)) return json({ success: false, error: "Profile not found" }, 404);
        if (await isGuildProfileMissing(env, targetId)) return json({ success: false, error: "Profile not found", code: "NOT_IN_GUILD" }, 404);
        try {
          const [identity, settings, tierInfo] = await Promise.all([
            resolveProfileIdentity(env, targetId, []).catch(() => null),
            readProfileSettings(env, targetId).catch(() => ({})),
            resolveProfileTier(env, targetId).catch(() => null),
          ]);
          if (!identity) return json({ success: false, error: "Profile not found" }, 404);
          const handle = await resolveProfileHandle(env, identity, settings || {});
          const isPrivate = settings?.public === false && session?.userId !== targetId && !ADMIN_IDS.includes(session?.userId || "");
          return json({ success: true, profile: {
            id: targetId,
            url: handle ? `/@${handle}` : `/profile?id=${encodeURIComponent(targetId)}`,
            name: identity.name || "Zyrex member",
            handle,
            avatar: identity.avatar || profileAvatarUrl(targetId, ""),
            tier_label: tierInfo?.tier_info?.label || "Member",
            is_admin: ADMIN_IDS.includes(targetId),
            private: isPrivate,
            bio: isPrivate ? "" : String(settings?.bio || "").slice(0, 240),
          } }, 200, { "Cache-Control": "private, no-store" });
        } catch (error) {
          console.warn("Profile preview unavailable:", error?.message || String(error));
          return json({ success: false, error: "Could not load this profile preview" }, 503, { "Cache-Control": "private, no-store" });
        }
      }

      if (path === "/api/profile" && request.method === "GET") {
        const session = parseSession(request.headers.get("Cookie"), request);
        const isStaffViewer = Boolean(session) && ADMIN_IDS.includes(session.userId);
        let targetId = String(url.searchParams.get("id") || "").trim();
        const rawHandle = url.searchParams.get("handle") || "";
        if (!targetId && rawHandle) targetId = await resolveHandle(env, rawHandle);
        if (!targetId && session) targetId = session.userId;
        if (!/^\d{15,25}$/.test(targetId)) return json({ success: false, error: "Profile not found" }, 404);

        // Members who are not in the Discord guild do not have a profile.
        if (await isGuildProfileMissing(env, targetId)) {
          return json({ success: false, error: "Profile not found", code: "NOT_IN_GUILD" }, 404);
        }

        // Fetch the member from Discord so "member since" is real; the cached profile
        // is used when the bot is unreachable.
        let joinedAt = "";
        try {
          const cached = await getCachedDiscordUser(env, targetId);
          joinedAt = String((cached && (cached.joined_at || cached.joinedAt)) || "");
          // The guild-member lookup carries the authoritative join date.
          if (!joinedAt) joinedAt = await readGuildJoinedAt(env, targetId);
        } catch (_) {}

        try {
          const payload = await buildProfilePayload(env, targetId, {
            viewerId: session ? session.userId : "",
            isStaff: isStaffViewer,
            joinedAt,
          });
          if (payload.error) return json({ success: false, error: payload.error }, payload.status || 400);

          // Count the visit unless the owner is looking at their own page, and only
          // once per visitor per day (the cookie is the only marker kept).
          const payloadResult = { success: true, ...payload };
          const isOwner = Boolean(session) && session.userId === targetId;
          if (!isOwner && !payload.private_profile) {
            const cookieName = "zyrex_pv_" + targetId.slice(-6);
            const alreadyCounted = (request.headers.get("Cookie") || "").includes(cookieName + "=1");
            if (!alreadyCounted) {
              const task = recordProfileView(env, targetId);
              if (ctx?.waitUntil) ctx.waitUntil(task);
              else await task.catch(() => {});
              const headers = { ...corsHeaders };
              headers["Set-Cookie"] = `${cookieName}=1; Domain=.zyrexediting.xyz; Path=/; Max-Age=86400; SameSite=Lax; Secure`;
              return json(payloadResult, 200, headers);
            }
          }
          // Whether a profile exists depends on live guild membership, so the payload is
          // never cached: a member who leaves loses their page immediately.
          return json(payloadResult, 200, { "Cache-Control": "no-store, no-cache, must-revalidate, private" });
        } catch (error) {
          console.error("Profile build failed:", error?.message || String(error));
          return json({ success: false, error: "Could not load that profile right now" }, 503);
        }
      }

      if (path === "/api/profile/resources" && request.method === "GET") {
        const session = parseSession(request.headers.get("Cookie"), request);
        let targetId = String(url.searchParams.get("id") || "").trim();
        const rawHandle = url.searchParams.get("handle") || "";
        if (!targetId && rawHandle) targetId = await resolveHandle(env, rawHandle);
        if (!targetId && session) targetId = session.userId;
        if (!/^\d{15,25}$/.test(targetId)) return json({ success: false, error: "Profile not found" }, 404);
        const isSelf = Boolean(session) && session.userId === targetId;
        const isStaffViewer = Boolean(session) && ADMIN_IDS.includes(session.userId);
        if (!isSelf && await isGuildProfileMissing(env, targetId)) {
          return json({ success: false, error: "Profile not found", code: "NOT_IN_GUILD" }, 404);
        }
        const typeFilter = String(url.searchParams.get("type") || "all").toLowerCase();
        const sort = String(url.searchParams.get("sort") || "recent").toLowerCase();
        const page = Math.max(Number(url.searchParams.get("page")) || 1, 1);
        const size = Math.min(Math.max(Number(url.searchParams.get("limit")) || 24, 1), 60);

        try {
          const settings = await readProfileSettings(env, targetId);
          if (settings.public === false && !isSelf && !isStaffViewer) {
            return json({ success: false, error: "This profile is private." }, 403);
          }
          const catalog = await dbReadProductCatalog(env).catch(() => []);
          let items = profileOwnedProducts(catalog, targetId);
          // Anonymous resources are never attached to a public profile.
          items = profileVisibleProducts(items);
          // The live counters win over the values stored on the product, exactly like
          // /api/products, so a profile card can never disagree with the page it links to.
          const [downloadData, statsData] = await Promise.all([
            dbGetDownloadCounts(env).catch(() => ({ counts: {} })),
            dbGetStats(env).catch(() => ({})),
          ]);
          const downloadCounts = (downloadData && downloadData.counts) || {};
          items = items.map(product => {
            const pid = String(product.id || "");
            const itemStats = statsData && typeof statsData[pid] === "object" ? statsData[pid] : {};
            return {
              ...product,
              downloads: Number(downloadCounts[pid] ?? product.downloads) || 0,
              views: Number(itemStats.views ?? product.views) || 0,
            };
          });
          if (typeFilter !== "all") {
            items = items.filter(product => String(product.type || "preset").toLowerCase() === typeFilter);
          }
          if (sort === "popular" || sort === "downloads") {
            items = items.slice().sort((a, b) => (Number(b.downloads) || 0) - (Number(a.downloads) || 0));
          } else if (sort === "views") {
            items = items.slice().sort((a, b) => (Number(b.views) || 0) - (Number(a.views) || 0));
          } else if (sort === "oldest") {
            items = items.slice().sort((a, b) => String(a.created_at || "").localeCompare(String(b.created_at || "")));
          } else {
            items = items.slice().sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || "")));
          }
          const total = items.length;
          return json({
            success: true,
            total,
            page,
            pages: Math.max(1, Math.ceil(total / size)),
            privacy: { public: settings.public !== false },
            items: items.slice((page - 1) * size, page * size).map(profilePublicResource),
          }, 200, { "Cache-Control": session ? "no-store, private" : "public, max-age=20, s-maxage=60" });
        } catch (error) {
          console.error("Profile resources failed:", error?.message || String(error));
          return json({ success: false, error: "Could not load those resources" }, 503);
        }
      }

      if (path === "/api/profile/search" && request.method === "GET") {
        const results = await searchProfiles(env, url.searchParams.get("q") || "", url.searchParams.get("limit"));
        return json({ success: true, results }, 200, { "Cache-Control": "public, max-age=30, s-maxage=120" });
      }

      if (path === "/api/profile/settings" && request.method === "GET") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Not logged in" }, 401);
        const settings = await readProfileSettings(env, session.userId);
        const identity = await resolveProfileIdentity(env, session.userId);
        const handle = await resolveProfileHandle(env, identity, settings);
        // Signed platform URLs cannot be loaded by visitors, so the editor only ever gets CDN copies.
        const editorLinks = (Array.isArray(settings.links) ? settings.links : []).map(link => {
          if (!link || typeof link !== "object") return link;
          const avatar = String(link.avatar || "");
          return avatar && !/^https:\/\/thumbnail\.zyrexediting\.xyz\//i.test(avatar) ? { ...link, avatar: "" } : link;
        });
        return json({
          success: true,
          settings: { ...settings, links: editorLinks, handle },
          url: handle ? `/@${handle}` : "",
          id: session.userId,
          default_avatar: identity.avatar,
          default_banner: identity.banner,
        }, 200, { "Cache-Control": "no-store, private" });
      }

      if (path === "/api/profile/social/refresh" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Not logged in" }, 401);
        const settings = await readProfileSettings(env, session.userId);
        const currentLinks = Array.isArray(settings.links) ? settings.links.slice(0, PROFILE_LINK_LIMIT) : [];
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON" }, 400); }
        const picked = profileRefreshTarget(currentLinks, body);
        if (!picked) return json({ success: false, error: "Save this link before refreshing its profile data." }, 404);
        // A row that now points at another account must not inherit its photo or name,
        // so those fields are cleared before the new account is scraped.
        const lookup = picked.sameAccount ? picked.target : { ...picked.target, name: "", detail: "", avatar: "" };
        const resolvedLinks = await resolveProfileSocialLinks(env, [lookup], "", { force: true });
        const resolved = resolvedLinks[0] || {};
        if (!resolved.platform || !resolved.handle) {
          return json({ success: false, error: "This link does not have refreshable social or game profile data." }, 400);
        }
        if (!picked.sameAccount && !resolved.name && !resolved.avatar && !resolved.detail) {
          // Nothing came back, so reporting a refresh would be a lie.
          return json({
            success: false,
            error: `Could not read @${resolved.handle} on ${resolved.label || "that platform"}. Check the link address, or make sure the Scrapin API key is configured.`,
          }, 502);
        }
        const refreshedLink = mergeRefreshedProfileLink(picked.stored, picked.target, resolved, picked.sameAccount);
        const nextLinks = currentLinks.slice();
        nextLinks[picked.index] = refreshedLink;
        const saved = await r2PutJSON(env, profileSettingsKey(session.userId), {
          ...settings,
          links: nextLinks,
          updated_at: new Date().toISOString(),
        });
        if (!saved) return json({ success: false, error: "Could not save refreshed profile data." }, 503);
        return json({ success: true, index: picked.index, link: refreshedLink }, 200, { "Cache-Control": "no-store, private" });
      }

      if (path === "/api/profile/settings" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Not logged in" }, 401);
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON" }, 400); }
        const current = await readProfileSettings(env, session.userId);
        const next = {
          ...current,
          public: body.public === undefined ? current.public : body.public === true,
          show_downloads: body.show_downloads === undefined ? current.show_downloads : body.show_downloads === true,
          show_activity: body.show_activity === undefined ? current.show_activity : body.show_activity === true,
          show_connections: body.show_connections === undefined ? current.show_connections : body.show_connections === true,
          bio: body.bio === undefined ? current.bio : sanitizeProfileBio(body.bio),
          links: body.links === undefined ? current.links : sanitizeProfileLinks(body.links),
          // These fields are intentionally immutable here; profile media comes from Discord.
          avatar: "",
          banner: "",
          accent: body.accent === undefined ? current.accent : (/^#[0-9a-f]{6}$/i.test(String(body.accent || "")) ? String(body.accent) : ""),
          updated_at: new Date().toISOString(),
        };
        await r2PutJSON(env, profileSettingsKey(session.userId), next);
        return json({ success: true, settings: next }, 200, { "Cache-Control": "no-store, private" });
      }

      if (path === "/api/profile/notif/prefs" && (request.method === "GET" || request.method === "POST")) {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Not logged in" }, 401);
        const settings = await readProfileSettings(env, session.userId);
        const defaults = { dnd: false, leaks: true, plugins: true, audio: true, feed: true, replies: true, announcements: true };
        const stored = settings.notification_prefs && typeof settings.notification_prefs === "object"
          ? settings.notification_prefs
          : {};
        if (request.method === "GET") {
          return json({ success: true, ...defaults, ...stored }, 200, { "Cache-Control": "no-store, private" });
        }
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON" }, 400); }
        const next = { ...defaults, ...stored };
        for (const key of Object.keys(defaults)) {
          if (typeof body[key] === "boolean") next[key] = body[key];
        }
        const saved = await r2PutJSON(env, profileSettingsKey(session.userId), {
          ...settings,
          notification_prefs: next,
          updated_at: new Date().toISOString(),
        });
        if (!saved) return json({ success: false, error: "Could not save notification settings" }, 503);
        return json({ success: true, ...next }, 200, { "Cache-Control": "no-store, private" });
      }

      if (path === "/api/profile/language" && (request.method === "GET" || request.method === "POST")) {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Not logged in", code: "NOT_LOGGED_IN" }, 401);
        const SUPPORTED_LANGUAGES = ["en", "tr", "pt", "es", "ko", "zh", "ar", "ru"];
        const settings = await readProfileSettings(env, session.userId);
        if (request.method === "GET") {
          const stored = String(settings.language || "").toLowerCase();
          return json({
            success: true,
            language: SUPPORTED_LANGUAGES.includes(stored) ? stored : "en",
            saved: Boolean(stored),
          }, 200, { "Cache-Control": "no-store, private" });
        }
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON" }, 400); }
        const language = String(body.language || "").toLowerCase();
        if (!SUPPORTED_LANGUAGES.includes(language)) {
          return json({ success: false, error: "Unsupported language" }, 400);
        }
        const saved = await r2PutJSON(env, profileSettingsKey(session.userId), {
          ...settings,
          language,
          updated_at: new Date().toISOString(),
        });
        if (!saved) return json({ success: false, error: "Could not save language" }, 503);
        return json({ success: true, language, saved: true }, 200, { "Cache-Control": "no-store, private" });
      }

      if (path === "/api/profile/privacy" && (request.method === "GET" || request.method === "POST")) {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Not logged in" }, 401);
        const settings = await readProfileSettings(env, session.userId);
        if (request.method === "GET") {
          return json({ success: true, visibility: settings.public === false ? "private" : "public" }, 200, { "Cache-Control": "no-store, private" });
        }
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON" }, 400); }
        const visibility = String(body.visibility || "");
        if (visibility !== "public" && visibility !== "private") {
          return json({ success: false, error: "Choose public or private visibility." }, 400);
        }
        const next = { ...settings, public: visibility === "public", updated_at: new Date().toISOString() };
        const saved = await r2PutJSON(env, profileSettingsKey(session.userId), next);
        if (!saved) return json({ success: false, error: "Could not save privacy settings" }, 503);
        return json({ success: true, visibility }, 200, { "Cache-Control": "no-store, private" });
      }

      if (path === "/api/account/settings-data" && request.method === "GET") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Sign in with Discord to view your settings." }, 401);
        const userId = String(session.userId || "");
        const [pass, grants, index, requests, adFree, guildMember, team, isUploader, catalog] = await Promise.all([
          getDownloadAccess(env, userId).catch(() => null),
          readUserGrants(env, userId).catch(() => []),
          r2GetJSON(env, DL_ARCHIVE.USER_INDEX_PREFIX + userId + ".json", []),
          listProfileDataRequests(env, userId),
          checkAdFreeRole(userId, env).catch(() => false),
          resolveGuildMember(env, userId, { maxAgeMs: 5 * 60 * 1000 }).catch(() => null),
          dbGetTeam(env).catch(() => ({})),
          canAccessUploaderCloud(session, env).catch(() => false),
          dbReadProductCatalog(env).catch(() => []),
        ]);
        const belongsTo = group => (team && Array.isArray(team[group]) ? team[group] : []).some(item => String((item && item.id) || item || "") === userId);
        const isAdmin = isAdminSession(session);
        const roles = [];
        if (guildMember?.in_guild) roles.push("Member");
        if (belongsTo("founders") || FOUNDER_PROFILES[userId]) roles.push("Founder");
        if (belongsTo("staff")) roles.push("Staff");
        if (belongsTo("contributors")) roles.push("Contributor");
        if (isUploader && !roles.includes("Uploader")) roles.push("Uploader");
        if (isAdmin && !roles.includes("Admin")) roles.push("Admin");
        if (!roles.length && guildMember?.in_guild !== false) roles.push("Member");
        const productsById = new Map((Array.isArray(catalog) ? catalog : []).map(product => [String(product && product.id || ""), product]));
        const downloads = [];
        for (const summary of Array.isArray(index) ? index : []) {
          if (!summary?.key) continue;
          const record = await r2GetJSON(env, summary.key, null).catch(() => null);
          if (record && record.access?.label === RESOURCE_ACCESS_LABEL + " pass") {
            const product = productsById.get(String(record.product_id || "")) || {};
            downloads.push({ product_id: record.product_id, product_name: record.product_name || product.name || product.title || "Leak", thumbnail: String(product.thumbnail || product.thumbnail_url || product.cover_url || product.image || ""), files: record.files || [], created_at: record.created_at, access_label: record.access.label });
          }
        }
        return json({
          success: true,
          user: { id: userId, username: session.username || "", display_name: session.displayName || session.username || "" },
          joined_at: String(guildMember && guildMember.joined_at || ""),
          roles,
          is_uploader: isUploader,
          pass: pass ? { started_at: Number(pass.granted_at) || null, expires_at: Number(pass.expires_at) || null, active: Number(pass.expires_at) > Date.now(), source: String(pass.source || "") } : null,
          ad_free: adFree,
          offer_claims: (Array.isArray(grants) ? grants : []).map(item => ({ completed_at: item.completed_at || null, claimed_at: item.claimed_at || null })),
          downloads: downloads.sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || ""))).slice(0, 100),
          data_requests: requests,
          is_admin: isAdmin,
        }, 200, { "Cache-Control": "no-store, private" });
      }

      if (path === "/api/account/data-request" && (request.method === "GET" || request.method === "POST")) {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Not logged in" }, 401);
        if (request.method === "GET") {
          return json({ success: true, requests: await listProfileDataRequests(env, session.userId) }, 200, { "Cache-Control": "no-store, private" });
        }
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON" }, 400); }
        const reason = String(body?.reason || "").trim().slice(0, 2000);
        if (reason.length < 10) return json({ success: false, error: "Please explain why you need your data export (at least 10 characters)." }, 400);
        const existing = await listProfileDataRequests(env, session.userId);
        const pending = existing.find(item => item.status === "pending");
        if (pending) return json({ success: false, error: "You already have a request waiting for review.", request: pending }, 409);
        const createdAt = new Date().toISOString();
        const requestId = crypto.randomUUID();
        const requestKey = `${DATA_REQUEST_PREFIX}${session.userId}/${Date.now()}-${requestId}.json`;
        const record = {
          version: 2, id: requestId, discord_id: session.userId, type: "export", reason,
          status: "pending", created_at: createdAt,
          review_due_at: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(),
        };
        const saved = await r2PutJSON(env, requestKey, record);
        if (!saved) return json({ success: false, error: "Could not submit your data request. Please try again." }, 503);
        const adminId = String(ADMIN_IDS[0] || "");
        const adminChannel = await openDiscordDMChannel(env, adminId);
        const loggerToken = getSiteLogBotToken(env);
        if (adminChannel && loggerToken) {
          const adminNotice = fetch(`${DISCORD_API}/channels/${adminChannel}/messages`, {
            method: "POST",
            headers: { Authorization: `Bot ${loggerToken}`, "Content-Type": "application/json" },
            body: JSON.stringify({ content: `New data export request ${requestId} from Discord user ${session.userId}. Review it in /settings within 3 days.`, allowed_mentions: { parse: [] } }),
          }).catch(() => {});
          if (ctx?.waitUntil) ctx.waitUntil(adminNotice);
        }
        return json({ success: true, request: record }, 201, { "Cache-Control": "no-store, private" });
      }

      if (path === "/api/account/data-export" && request.method === "GET") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Sign in with the same Discord account to download this export." }, 401);
        try {
          const token = await openExportToken(env, url.searchParams.get("token"));
          if (String(token.user_id) !== String(session.userId) || Number(token.expires_at) <= Date.now()) {
            return json({ success: false, error: "This export link is invalid or has expired." }, 403);
          }
          const stored = await r2GetJSON(env, DATA_EXPORT_PREFIX + token.id + ".json", null);
          if (!stored || String(stored.user_id) !== String(session.userId) || Number(stored.expires_at) <= Date.now()) {
            return json({ success: false, error: "This export is no longer available." }, 410);
          }
          const data = await decryptExportPackage(env, stored.ciphertext);
          return new Response(JSON.stringify(data, null, 2), {
            status: 200,
            headers: {
              "Content-Type": "application/json; charset=utf-8",
              "Content-Disposition": `attachment; filename="zyrex-data-export-${session.userId}.json"`,
              "Cache-Control": "no-store, private",
              "X-Content-Type-Options": "nosniff",
            },
          });
        } catch (_) {
          return json({ success: false, error: "This export link is invalid or has expired." }, 403);
        }
      }

      if (path === "/api/admin/data-requests" && request.method === "GET") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        const status = String(url.searchParams.get("status") || "pending");
        const listed = await env.STORAGE.list({ prefix: DATA_REQUEST_PREFIX, limit: 1000 }).catch(() => ({ objects: [] }));
        const rows = await Promise.all((listed.objects || []).map(item => r2GetJSON(env, item.key, null).catch(() => null)));
        return json({ success: true, items: rows.filter(item => item && (status === "all" || item.status === status)).sort((a, b) => String(a.created_at || "").localeCompare(String(b.created_at || ""))) }, 200, { "Cache-Control": "no-store, private" });
      }

      const dataRequestReview = path.match(/^\/api\/admin\/data-requests\/([A-Za-z0-9-]+)$/);
      if (dataRequestReview && request.method === "POST") {
        if (!isAdminRequest(request, env, hasMasterKey)) return json({ success: false, error: "Unauthorized" }, 403);
        const body = await request.json().catch(() => null);
        const action = String(body?.action || "").toLowerCase();
        if (!["approve", "reject"].includes(action)) return json({ success: false, error: "Choose approve or reject." }, 400);
        const found = await findDataRequest(env, dataRequestReview[1]);
        if (!found) return json({ success: false, error: "Request not found." }, 404);
        if (found.record.status !== "pending") return json({ success: false, error: "This request has already been reviewed." }, 409);
        const reviewer = parseSession(null, request)?.userId || "master";
        const now = new Date().toISOString();
        found.record.status = action === "approve" ? "approved" : "rejected";
        found.record.reviewed_at = now;
        found.record.reviewed_by = reviewer;
        found.record.review_note = String(body?.note || "").trim().slice(0, 1000);
        let downloadUrl = "";
        let exportDm = null;
        if (action === "approve") {
          const exportId = crypto.randomUUID();
          const expiresAt = Date.now() + DATA_EXPORT_TTL_MS;
          const payload = await buildAccountExport(env, found.record.discord_id);
          const encrypted = await encryptExportPackage(env, payload);
          const ok = await r2PutJSON(env, DATA_EXPORT_PREFIX + exportId + ".json", {
            user_id: found.record.discord_id, expires_at: expiresAt, ciphertext: encrypted,
          });
          if (!ok) return json({ success: false, error: "Could not save the encrypted export." }, 503);
          const token = await sealExportToken(env, { id: exportId, user_id: found.record.discord_id, expires_at: expiresAt });
          downloadUrl = `https://zyrexediting.xyz/api/account/data-export?token=${encodeURIComponent(token)}`;
          found.record.export_id = exportId;
          found.record.export_expires_at = new Date(expiresAt).toISOString();
          found.record.download_url = downloadUrl;
          exportDm = { userId: found.record.discord_id, downloadUrl };
        }
        const saved = await r2PutJSON(env, found.key, found.record);
        if (!saved) return json({ success: false, error: "Could not save the review result." }, 503);
        if (exportDm) {
          const dmChannel = await openDiscordDMChannel(env, exportDm.userId);
          const botToken = getSiteLogBotToken(env);
          let dmSent = false;
          if (dmChannel && botToken) {
            try {
              const dm = await fetch(`${DISCORD_API}/channels/${dmChannel}/messages`, {
                method: "POST",
                headers: { Authorization: `Bot ${botToken}`, "Content-Type": "application/json" },
                body: JSON.stringify({ content: `Your Zyrex data export is ready. Download it within 48 hours: ${exportDm.downloadUrl}`, allowed_mentions: { parse: [] } }),
              });
              dmSent = dm.ok;
            } catch (dmError) {
              console.warn("Data export Discord DM failed:", dmError?.message || String(dmError));
            }
          }
          found.record.discord_dm_sent = dmSent;
          found.record.discord_dm_error = dmSent ? "" : "Could not deliver the export link by Discord DM.";
          await r2PutJSON(env, found.key, found.record);
        }
        return json({ success: true, request: found.record, download_url: downloadUrl }, 200, { "Cache-Control": "no-store, private" });
      }

      if (path === "/api/profile/handle" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Not logged in" }, 401);
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON" }, 400); }
        const result = await setProfileHandle(env, session.userId, body.handle);
        if (result.error) return json({ success: false, error: result.error }, 409);
        return json({ success: true, handle: result.handle, url: `/@${result.handle}` }, 200, { "Cache-Control": "no-store, private" });
      }

      if (path === "/api/profile/follow" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Sign in to follow members.", code: "NOT_LOGGED_IN" }, 401);
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON" }, 400); }
        const action = String(body.action || "follow").toLowerCase();
        if (action !== "follow" && action !== "unfollow") {
          return json({ success: false, error: "action must be follow or unfollow" }, 400);
        }
        const result = await setFollow(env, session.userId, body.id, action === "follow");
        if (result.error) return json({ success: false, error: result.error }, 400);
        const prefs = await readFollowPrefs(env, session.userId);
        return json({
          success: true,
          following: result.following,
          followers: result.followers,
          is_following: action === "follow",
          notify: result.changed && action === "follow" ? !prefs.muted.includes(String(body.id || "")) : undefined,
        }, 200, { "Cache-Control": "no-store, private" });
      }

      // The profile editor turns a platform and a username into a real link.
      if (path === "/api/profile/social/lookup" && request.method === "GET") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Sign in to add social links.", code: "NOT_LOGGED_IN" }, 401);
        const platformKey = String(url.searchParams.get("platform") || "").trim().toLowerCase();
        const username = String(url.searchParams.get("username") || "").trim().replace(/^@+/, "").slice(0, 60);
        // Game accounts share the endpoint but resolve to a rank instead of a page.
        const game = gamePlatform(platformKey);
        if (game) {
          const handle = sanitizeGameHandle(username, game.key);
          if (!handle) {
            return json({
              success: false,
              error: game.key === "roblox" ? "Enter a Roblox username." : "Use the name#tag format, for example reyli#EUW.",
            }, 400);
          }
          const resolved = await resolveGameProfile(env, game.key, handle).catch(() => null) || gameProfileShape(game, handle);
          return json({
            success: true,
            label: game.label,
            url: resolved.url || "",
            platform: game.key,
            icon: game.icon,
            handle: resolved.handle || handle,
            name: resolved.name || "",
            detail: resolved.detail || "",
            avatar: resolved.avatar || "",
            kind: "game",
            verified: true,
            scrapin: Boolean(env?.SCRAPIN_API_KEY),
          }, 200, { "Cache-Control": "no-store, private" });
        }
        const platform = SOCIAL_LINK_PLATFORMS.find(entry => entry.key === platformKey);
        if (!platform) return json({ success: false, error: "Pick a platform first." }, 400);
        if (!/^[a-z0-9._-]{2,60}$/i.test(username)) return json({ success: false, error: "That username does not look right." }, 400);
        const candidate = { label: platform.label, url: platform.build(username), platform: platform.key, handle: username.toLowerCase() };
        const resolved = await resolveSocialLink(env, candidate).catch(() => null) || {};
        return json({
          success: true,
          label: platform.label,
          url: resolved.url || candidate.url,
          platform: platform.key,
          handle: String(resolved.handle || username).toLowerCase(),
          name: resolved.name || "",
          avatar: resolved.avatar || "",
          followers: resolved.followers || "",
          verified: resolved.verified === true,
          scrapin: Boolean(env?.SCRAPIN_API_KEY),
        }, 200, { "Cache-Control": "no-store, private" });
      }

      // Which followed accounts may notify you, and through which channel.
      if (path === "/api/profile/follow/prefs" && request.method === "GET") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Sign in to manage notifications.", code: "NOT_LOGGED_IN" }, 401);
        const [prefs, follows] = await Promise.all([readFollowPrefs(env, session.userId), readFollows(env, session.userId)]);
        const handles = invertHandleIndex(await readHandleIndex(env));
        const muted = new Set(prefs.muted);
        const following = await Promise.all(follows.following.slice(0, 60).map(async id => {
          const identity = await resolveProfileIdentity(env, id).catch(() => null);
          const handle = handles[id] || "";
          return {
            id,
            name: (identity && identity.name) || "Zyrex member",
            handle,
            avatar: (identity && identity.avatar) || profileAvatarUrl(id, ""),
            url: handle ? `/@${handle}` : `/profile?id=${encodeURIComponent(id)}`,
            notify: !muted.has(id),
            official: await isOfficialProfileId(env, id),
          };
        }));
        return json({
          success: true,
          site: prefs.site,
          dm: prefs.dm,
          following,
        }, 200, { "Cache-Control": "no-store, private" });
      }

      if (path === "/api/profile/follow/prefs" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        if (!session) return json({ success: false, error: "Sign in to manage notifications.", code: "NOT_LOGGED_IN" }, 401);
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON." }, 400); }
        const prefs = await readFollowPrefs(env, session.userId);
        const next = { site: prefs.site, dm: prefs.dm, muted: [...prefs.muted] };
        if (typeof body.site === "boolean") next.site = body.site;
        if (typeof body.dm === "boolean") next.dm = body.dm;
        const authorId = String(body.author_id || "").trim();
        if (/^\d{15,25}$/.test(authorId) && typeof body.notify === "boolean") {
          if (body.notify) next.muted = next.muted.filter(id => id !== authorId);
          else if (!next.muted.includes(authorId)) next.muted.push(authorId);
        }
        const saved = await writeFollowPrefs(env, session.userId, next);
        if (!saved) return json({ success: false, error: "Could not save your notification settings." }, 503);
        return json({ success: true, site: next.site, dm: next.dm, muted: next.muted }, 200, { "Cache-Control": "no-store, private" });
      }

      if (path === "/api/profile/connections" && request.method === "GET") {
        const session = parseSession(request.headers.get("Cookie"), request);
        const isStaffViewer = Boolean(session) && ADMIN_IDS.includes(session.userId);
        let targetId = String(url.searchParams.get("id") || "").trim();
        const rawHandle = url.searchParams.get("handle") || "";
        if (!targetId && rawHandle) targetId = await resolveHandle(env, rawHandle);
        if (!targetId && session) targetId = session.userId;
        if (!/^\d{15,25}$/.test(targetId)) return json({ success: false, error: "Profile not found" }, 404);
        const kind = String(url.searchParams.get("type") || "followers").toLowerCase() === "following" ? "following" : "followers";
        const settings = await readProfileSettings(env, targetId);
        const isSelf = Boolean(session) && session.userId === targetId;
        if (!isSelf && await isGuildProfileMissing(env, targetId)) {
          return json({ success: false, error: "Profile not found", code: "NOT_IN_GUILD" }, 404);
        }
        if (settings.show_connections === false && !isSelf && !isStaffViewer) {
          return json({ success: true, hidden: true, total: 0, items: [] });
        }
        const follows = await readFollows(env, targetId);
        const ids = kind === "following" ? follows.following : follows.followers;
        // The official profile collects every member, so its lists paginate.
        const limit = Math.min(Math.max(Number(url.searchParams.get("limit")) || 60, 1), 60);
        const pageNo = Math.max(Number(url.searchParams.get("page")) || 1, 1);
        const slice = ids.slice((pageNo - 1) * limit, pageNo * limit);
        const catalog = await dbReadProductCatalog(env).catch(() => []);
        const owners = buildProfileIdentityMap(catalog);
        const handles = invertHandleIndex(await readHandleIndex(env));
        const aggregates = await readProfileAggregates(env);
        const ownedCounts = profileOwnedResourceCounts(catalog);
        const roster = new Map((await readGuildRoster(env).catch(() => [])).map(member => [member.id, member]));
        const viewerFollows = await readFollows(env, session ? session.userId : "");
        const items = [];
        let liveLookups = 0;
        for (const id of slice) {
          const member = roster.get(id) || null;
          const catalogueIdentity = owners.get(id) || {};
          let name = String((member && member.display_name) || catalogueIdentity.name || "").trim();
          let avatar = member && member.avatar_hash
            ? profileAvatarUrl(id, member.avatar_hash)
            : (catalogueIdentity.avatar ? profileAvatarUrl(id, catalogueIdentity.avatar) : "");
          if (!name || !avatar) {
            const cachedUser = await getCachedDiscordUser(env, id).catch(() => null);
            if (cachedUser) {
              const cachedName = String(cachedUser.global_name || cachedUser.display_name || cachedUser.username || "").trim();
              name = name || cachedName.slice(0, 60);
              if (!avatar) avatar = profileAvatarUrl(id, cachedUser.avatar || cachedUser.avatar_url);
            }
          }
          // A handful of live lookups per request fills cold rows without turning a
          // 60-row page into 60 Discord calls.
          if ((!name || !avatar) && liveLookups < 8) {
            liveLookups += 1;
            const resolved = await ensureDiscordUserProfile(env, id).catch(() => null);
            if (resolved && resolved.user) {
              name = name || String(resolved.user.global_name || resolved.user.display_name || resolved.user.username || "").trim().slice(0, 60);
              if (!avatar) avatar = profileAvatarUrl(id, resolved.user.avatar || resolved.user.avatar_url);
            }
          }
          const subject = profileSubject(aggregates, id);
          items.push({
            id,
            handle: handles[id] || "",
            url: handles[id] ? `/@${handles[id]}` : `/profile?id=${encodeURIComponent(id)}`,
            name: name || "Zyrex member",
            avatar: avatar || "/assets/default-avatar.png",
            resources: ownedCounts.get(id) || 0,
            downloads: Number(subject.downloads) || 0,
            is_following: kind === "followers" ? viewerFollows.following.includes(id) : true,
          });
        }
        // Cards may only point at members who are still in the guild.
        const visibleItems = await filterGuildMembers(env, items, item => item.id);
        const totalVisible = await filterGuildMembers(env, ids.map(id => ({ id })), row => row.id);
        return json({
          success: true,
          type: kind,
          total: totalVisible.length,
          page: pageNo,
          pages: Math.max(1, Math.ceil(totalVisible.length / limit)),
          items: visibleItems,
        }, 200, { "Cache-Control": "no-store, private" });
      }

      if (path === "/api/profile/feed" && request.method === "GET") {
        const session = parseSession(request.headers.get("Cookie"), request);
        const zyrexSync = maybeSyncZyrexFollowers(env);
        if (ctx?.waitUntil) ctx.waitUntil(zyrexSync); else zyrexSync.catch(() => {});
        const feed = await buildFollowFeed(
          env,
          session ? session.userId : "",
          Number(url.searchParams.get("page")) || 1,
          Number(url.searchParams.get("limit")) || 24,
          {
            sort: String(url.searchParams.get("sort") || "").toLowerCase() === "trending" ? "trending" : "latest",
            tag: String(url.searchParams.get("tag") || "").trim().toLowerCase().slice(0, 24),
          },
        );
        // The timeline must never be served from a cache: a fresh post has to appear the
        // moment the page is reloaded, so no shared or browser cache is allowed here.
        return json({ success: true, ...feed }, 200, { "Cache-Control": "no-store, no-cache, must-revalidate, private" });
      }

      if (path === "/api/social/interactions" && request.method === "GET") {
        const session = parseSession(request.headers.get("Cookie"), request);
        const includeReplies = url.searchParams.get("include") === "replies";
        const descriptors = String(url.searchParams.get("targets") || "").split(",").filter(Boolean).slice(0, 60);
        const catalog = await dbReadProductCatalog(env).catch(() => []);
        const products = new Map((Array.isArray(catalog) ? catalog : []).map(product => [String(product.id || ""), product]));
        const profileCache = new Map();
        const results = await Promise.all(descriptors.map(async descriptor => {
          const parts = descriptor.split("~");
          const type = parts[0];
          const id = parts[type === "post" ? 2 : 1] || "";
          const authorId = type === "post" ? parts[1] || "" : "";
          if (type === "resource") {
            const product = products.get(id);
            if (!product || product.is_anonymous === true || isScenepackProduct(product)) return [descriptor, null];
            // Leak cards report the same numbers as the leak page.
            return [descriptor, await leakInteractionSummary(env, id, session?.userId || "", includeReplies)];
          } else if (type === "post") {
            if (!/^\d{15,25}$/.test(authorId) || !/^[a-f0-9-]{16,40}$/i.test(id)) return [descriptor, null];
            if (!profileCache.has(authorId)) {
              profileCache.set(authorId, Promise.all([readProfilePosts(env, authorId), readProfileSettings(env, authorId)]));
            }
            const [posts, settings] = await profileCache.get(authorId);
            if (posts.some(post => post.id === id) && settings.public !== false && settings.show_activity !== false) {
              const stored = await r2GetJSON(env, socialInteractionKey("post", id, authorId), null);
              const row = sanitizeSocialInteraction(stored || emptySocialInteraction());
              return [descriptor, socialInteractionSummary(row, session?.userId || "", includeReplies)];
            }
            // Upload announcements report the leak's own numbers.
            const leakProductId = await resolveNoticeProductId(env, id);
            if (leakProductId) return [descriptor, await leakInteractionSummary(env, leakProductId, session?.userId || "", includeReplies)];
            return [descriptor, null];
          } else {
            return [descriptor, null];
          }
          const targetType = type === "resource" || type === "post" ? type : "";
          if (!targetType) return [descriptor, null];
          const stored = await r2GetJSON(env, socialInteractionKey(targetType, id, authorId), null);
          const row = sanitizeSocialInteraction(stored || emptySocialInteraction());
          return [descriptor, socialInteractionSummary(row, session?.userId || "", includeReplies)];
        }));
        const items = Object.fromEntries(results);
        if (includeReplies) {
          // Thread avatars are refreshed in one pass so a stale snapshot never wins.
          await Promise.all(Object.values(items).map(summary => refreshReplyAvatars(env, summary)));
        }
        return json({ success: true, items }, 200, { "Cache-Control": "no-store, private" });
      }

      if (path === "/api/social/interactions" && request.method === "POST") {
        const session = parseSession(request.headers.get("Cookie"), request);
        let body;
        try { body = await request.json(); } catch (_) { return json({ success: false, error: "Invalid JSON." }, 400); }
        const type = String(body.type || "");
        const id = String(body.id || "");
        const authorId = type === "post" ? String(body.author_id || "") : "";
        const action = String(body.action || "");
        if (!["view", "like", "reply"].includes(action)) return json({ success: false, error: "Unknown interaction." }, 400);
        if (!session && action !== "view") return json({ success: false, code: "NOT_LOGGED_IN", error: "Sign in to interact with posts." }, 401);
        // Upload announcements and leak cards borrow the leak's records, so a like/view/
        // reply here is a like/view/comment on the leak page and vice versa.
        const leakProductId = type === "post"
          ? await resolveNoticeProductId(env, id)
          : (type === "resource" && id && (await resolveSocialTarget(env, "resource", id, "").catch(() => null)) ? id : "");
        if (leakProductId) {
          const resourceKey = socialInteractionKey("resource", leakProductId);
            const now = Date.now();
            if (action === "view") {
              const row = await resourceInteractionRow(env, leakProductId);
              const fingerprint = await socialViewerFingerprint(request, session, env);
              const cutoff = now - 30 * 24 * 60 * 60 * 1000;
              for (const [viewer, stamp] of Object.entries(row.views)) {
                if (!Number.isFinite(Number(stamp)) || Number(stamp) < cutoff) delete row.views[viewer];
              }
              if (!row.views[fingerprint]) await dbIncrementView(env, leakProductId).catch(() => null);
              row.views[fingerprint] = now;
              row.views = Object.fromEntries(Object.entries(row.views).sort((a, b) => Number(b[1]) - Number(a[1])).slice(0, 5000));
              await r2PutJSON(env, resourceKey, { ...row, updated_at: new Date(now).toISOString() }).catch(() => false);
            } else if (action === "like") {
              const row = await resourceInteractionRow(env, leakProductId);
              const index = row.likes.indexOf(session.userId);
              if (index >= 0) row.likes.splice(index, 1);
              else row.likes.push(session.userId);
              await r2PutJSON(env, resourceKey, { ...row, updated_at: new Date(now).toISOString() }).catch(() => false);
              await writePresetLikeCount(env, leakProductId, row.likes.length);
            } else {
              const text = String(body.text || "").trim().slice(0, 500);
              const media = Array.isArray(body.media)
                ? body.media.map(value => sanitizeProfileMediaUrl(value, session.userId)).filter(Boolean).slice(0, 4)
                : [];
              if (!text && !media.length) return json({ success: false, error: "Write a reply first." }, 400);
              // The leak conversation allows markdown images, so attachments ride along.
              const content = [text, ...media.map(url => `![${/\/stickers\//i.test(url) ? "sticker" : "gif"}](${url})`)]
                .filter(Boolean)
                .join("\n");
              const sessionAvatar = session.avatar
                ? `https://cdn.discordapp.com/avatars/${session.userId}/${session.avatar}.png?size=128`
                : `https://cdn.discordapp.com/embed/avatars/${(parseInt(session.userId) || 0) % 5}.png`;
              const identity = await resolveProfileIdentity(env, session.userId).catch(() => ({}));
              try {
                const result = await callBotCommentApi("/api/comments", "POST", {
                  preset_id: leakProductId,
                  user_id: session.userId,
                  user_name: identity.name || session.globalName || session.displayName || session.username || "Zyrex Member",
                  user_avatar: identity.avatar || sessionAvatar,
                  content,
                  parent_id: body.parent_id || null,
                  is_admin: ADMIN_IDS.includes(session.userId),
                  source: "web",
                });
                if (!result.ok) {
                  const message = (result.data && result.data.error) || "Could not post the reply.";
                  return json({ success: false, error: message }, result.status >= 400 && result.status < 500 ? result.status : 502);
                }
              } catch (error) {
                console.error("Leak reply bridge unavailable:", error?.message || String(error));
                return json({ success: false, error: "Comments are temporarily unavailable. Please try again shortly." }, 503);
              }
            }
            const refresh = scheduleFeedDiscordRefresh(env, id).catch(() => false);
            if (ctx?.waitUntil) ctx.waitUntil(refresh); else refresh.catch(() => {});
            return json({ success: true, interaction: await refreshReplyAvatars(env, await leakInteractionSummary(env, leakProductId, session?.userId || "", true)) }, 200, { "Cache-Control": "no-store, private" });
        }
        const target = await resolveSocialTarget(env, type, id, authorId);
        if (!target) return json({ success: false, error: "This post is unavailable." }, 404);
        const key = socialInteractionKey(type, id, authorId);
        const row = sanitizeSocialInteraction(await r2GetJSON(env, key, null) || emptySocialInteraction());
        const now = Date.now();

        if (action === "view") {
          const fingerprint = await socialViewerFingerprint(request, session, env);
          const cutoff = now - 30 * 24 * 60 * 60 * 1000;
          for (const [viewer, stamp] of Object.entries(row.views)) {
            if (!Number.isFinite(Number(stamp)) || Number(stamp) < cutoff) delete row.views[viewer];
          }
          if (!row.views[fingerprint]) row.view_count++;
          row.views[fingerprint] = now;
          const recent = Object.entries(row.views).sort((a, b) => Number(b[1]) - Number(a[1])).slice(0, 5000);
          row.views = Object.fromEntries(recent);
        } else if (action === "like") {
          const index = row.likes.indexOf(session.userId);
          if (index >= 0) row.likes.splice(index, 1);
          else row.likes.push(session.userId);
        } else {
          const text = String(body.text || "").trim().slice(0, 500);
          const media = Array.isArray(body.media)
            ? body.media.map(value => sanitizeProfileMediaUrl(value, session.userId)).filter(Boolean).slice(0, 4)
            : [];
          if (!text && !media.length) return json({ success: false, error: "Write a reply first." }, 400);
          if (row.replies.length >= 500) return json({ success: false, error: "This conversation has reached its reply limit." }, 409);
          const identity = await resolveProfileIdentity(env, session.userId);
          const settings = await readProfileSettings(env, session.userId);
          const handle = await resolveProfileHandle(env, identity, settings);
          // Answering another reply keeps the thread two levels deep: a child always
          // points at a top-level reply, and reply_to records who was addressed.
          let parentId = String(body.parent_id || "").trim();
          let replyTo = null;
          if (parentId) {
            const parent = row.replies.find(reply => reply && reply.id === parentId);
            if (!parent) return json({ success: false, error: "That reply is no longer available." }, 404);
            const root = parent.parent_id && row.replies.find(reply => reply && reply.id === parent.parent_id);
            parentId = root ? root.id : parent.id;
            const addressed = parent.author && typeof parent.author === "object" ? parent.author : {};
            replyTo = {
              id: parent.id,
              name: String(addressed.name || "").slice(0, 80),
              handle: normalizeHandle(addressed.handle),
            };
          }
          row.replies.push({
            id: crypto.randomUUID(),
            author_id: session.userId,
            author: {
              name: identity.name || session.username || "Zyrex Member",
              handle,
              avatar: identity.avatar || profileAvatarUrl(session.userId, ""),
              url: handle ? `/@${handle}` : `/profile?id=${encodeURIComponent(session.userId)}`,
            },
            text,
            media,
            created_at: new Date(now).toISOString(),
            ...(parentId ? { parent_id: parentId } : {}),
            ...(replyTo && (replyTo.name || replyTo.handle) ? { reply_to: replyTo } : {}),
          });
        }

        const saved = await r2PutJSON(env, key, { ...row, updated_at: new Date(now).toISOString() });
        if (!saved) return json({ success: false, error: "Could not save this interaction." }, 503);
        // Post announcements in Discord carry live counters, so every like/view/reply
        // refreshes the embed that belongs to this post.
        if (type === "post") {
          const refresh = scheduleFeedDiscordRefresh(env, id).catch(() => false);
          if (ctx?.waitUntil) ctx.waitUntil(refresh); else refresh.catch(() => {});
        }
        return json({ success: true, interaction: socialInteractionSummary(row, session?.userId || "", action === "reply") }, 200, { "Cache-Control": "no-store, private" });
      }



      return json({ error: "Not found" }, 404);
    } catch (err) {
      const failedUrl = new URL(request.url);
      const failedInput = failedUrl.searchParams.get("url") || "";
      console.error("Worker error:", err.message, failedUrl.pathname, failedInput.slice(0, 120));
      if (ctx?.waitUntil) {
        ctx.waitUntil(sendSiteErrorToDiscord(env, request, {
          source: "api-worker",
          type: "worker_exception",
          page: failedUrl.pathname,
          request_path: failedUrl.pathname,
          method: request.method,
          status: 500,
          // The failing input is what makes these alerts actionable.
          message: publicErrorMessage(err) + (failedInput ? " | input: " + failedInput : ""),
        }));
      }
      // Creator/store scans talk to third-party profiles: an upstream failure is a "not
      // found" answer for the wizard, never a 500 that spams the site-log channel.
      if (failedUrl.pathname === "/api/scan-creator-links" || failedUrl.pathname === "/api/scan-creator-links/") {
        return json({
          success: false,
          found: false,
          products: [],
          inputUrl: failedInput,
          error: "scan_failed",
        }, 200);
      }
      return json({ error: "Internal error" }, 500);
    }
  },

  // Cron: finishes role assignments that Discord rejected while the member was verifying.
  async scheduled(event, env, ctx) {
    try {
      const removed = await cleanupInstallerAuthRecords(env);
      if (removed) console.log("expired installer auth records cleaned:", removed);
    } catch (error) {
      console.error("installer auth cleanup failed:", error?.message || String(error));
    }
    try {
      const result = await processVerifyQueue(env, 25);
      if (result.processed) console.log("verify role queue:", JSON.stringify(result));
    } catch (error) {
      console.error("verify role queue run failed:", error?.message || String(error));
    }
    try {
      const invite = await runDiscordInviteWatch(env);
      if (invite.status !== "ok") console.log("discord invite watch:", JSON.stringify(publicDiscordInviteState(invite)));
    } catch (error) {
      console.error("discord invite watch failed:", error?.message || String(error));
    }
  },
};
